/**
 * Webhook Service — WS-8.1
 * Fire-and-forget HMAC-signed webhook delivery with delivery logging.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import crypto from 'crypto';
import { WEBHOOK_EVENTS } from '@/modules/accounting/constants/webhookEvents';
type Row = Record<string, unknown>;

export { WEBHOOK_EVENTS };
export type { WebhookEvent } from '@/modules/accounting/constants/webhookEvents';


export interface Webhook {
  id: string;
  companyId: string;
  name: string;
  url: string;
  secret: string | null;
  events: string[];
  isActive: boolean;
  lastTriggeredAt: string | null;
  failureCount: number;
  createdAt: string;
}

export interface WebhookInput {
  name: string;
  url: string;
  secret?: string | null;
  events: string[];
  isActive?: boolean;
}

export interface Delivery {
  id: string;
  webhookId: string;
  event: string;
  payload: Record<string, unknown>;
  responseStatus: number | null;
  responseBody: string | null;
  deliveredAt: string;
  success: boolean;
}

function mapWebhook(row: Row): Webhook {
  return {
    id: String(row.id),
    companyId: String(row.company_id),
    name: String(row.name),
    url: String(row.url),
    secret: row.secret ? String(row.secret) : null,
    events: Array.isArray(row.events) ? row.events : [],
    isActive: Boolean(row.is_active),
    lastTriggeredAt: row.last_triggered_at ? String(row.last_triggered_at) : null,
    failureCount: Number(row.failure_count),
    createdAt: String(row.created_at),
  };
}

function mapDelivery(row: Row): Delivery {
  return {
    id: String(row.id),
    webhookId: String(row.webhook_id),
    event: String(row.event),
    payload: (row.payload !== null && typeof row.payload === 'object' ? row.payload : JSON.parse(typeof row.payload === 'string' ? row.payload : '{}')) as Record<string, unknown>,
    responseStatus: row.response_status != null ? Number(row.response_status) : null,
    responseBody: row.response_body ? String(row.response_body) : null,
    deliveredAt: String(row.delivered_at),
    success: Boolean(row.success),
  };
}

function signPayload(secret: string, body: string): string {
  return crypto.createHmac('sha256', secret).update(body).digest('hex');
}

/** Fire webhook for an event — non-blocking, never throws to caller. */
export async function fireWebhook(
  companyId: string,
  event: string,
  payload: Record<string, unknown>,
): Promise<void> {
  // Intentionally fire-and-forget — wrap everything in try/catch
  void (async () => {
    try {
      const rows = (await sql`
        SELECT * FROM webhook_endpoints
        WHERE company_id = ${companyId}
          AND is_active = true
          AND ${event} = ANY(events)
      `) as Row[];

      for (const row of rows) {
        const endpoint = mapWebhook(row);
        const body = JSON.stringify(payload);
        const signature = endpoint.secret ? signPayload(endpoint.secret, body) : '';

        let responseStatus: number | null = null;
        let responseBody: string | null = null;
        let success = false;

        try {
          const controller = new AbortController();
          const timeout = setTimeout(() => controller.abort(), 5000);
          const resp = await fetch(endpoint.url, {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
              'X-Webhook-Event': event,
              ...(signature ? { 'X-Webhook-Signature': signature } : {}),
            },
            body,
            signal: controller.signal,
          });
          clearTimeout(timeout);
          responseStatus = resp.status;
          responseBody = await resp.text().catch(() => null);
          success = resp.ok;
        } catch (fetchErr) {
          log.warn('Webhook delivery failed', { endpointId: endpoint.id, error: fetchErr }, 'webhook');
        }

        // Record delivery
        await sql`
          INSERT INTO webhook_deliveries (webhook_id, event, payload, response_status, response_body, success)
          VALUES (${endpoint.id}::UUID, ${event}, ${JSON.stringify(payload)}::JSONB,
                  ${responseStatus}, ${responseBody}, ${success})
        `;

        if (success) {
          await sql`
            UPDATE webhook_endpoints
            SET last_triggered_at = NOW(), failure_count = 0
            WHERE id = ${endpoint.id}::UUID
          `;
        } else {
          await sql`
            UPDATE webhook_endpoints
            SET failure_count = failure_count + 1,
                is_active = CASE WHEN failure_count + 1 >= 10 THEN false ELSE is_active END
            WHERE id = ${endpoint.id}::UUID
          `;
        }
      }
    } catch (err) {
      log.error('fireWebhook error', { companyId, event, error: err }, 'webhook');
    }
  })();
}

export async function getWebhooks(companyId: string): Promise<Webhook[]> {
  const rows = (await sql`
    SELECT * FROM webhook_endpoints WHERE company_id = ${companyId} ORDER BY created_at DESC
  `) as Row[];
  return rows.map(mapWebhook);
}

export async function createWebhook(companyId: string, input: WebhookInput): Promise<Webhook> {
  const rows = (await sql`
    INSERT INTO webhook_endpoints (company_id, name, url, secret, events, is_active)
    VALUES (${companyId}, ${input.name}, ${input.url}, ${input.secret ?? null},
            ${JSON.stringify(input.events)}::TEXT[], ${input.isActive ?? true})
    RETURNING *
  `) as Row[];
  log.info('Webhook created', { id: rows[0]?.id }, 'webhook');
  return mapWebhook(rows[0]!);
}

export async function updateWebhook(
  companyId: string,
  id: string,
  updates: Partial<WebhookInput>,
): Promise<Webhook> {
  // Build individual field updates to avoid array casting complexity
  if (updates.name !== undefined) {
    await sql`UPDATE webhook_endpoints SET name = ${updates.name} WHERE id = ${id}::UUID AND company_id = ${companyId}`;
  }
  if (updates.url !== undefined) {
    await sql`UPDATE webhook_endpoints SET url = ${updates.url} WHERE id = ${id}::UUID AND company_id = ${companyId}`;
  }
  if (updates.secret !== undefined) {
    await sql`UPDATE webhook_endpoints SET secret = ${updates.secret ?? null} WHERE id = ${id}::UUID AND company_id = ${companyId}`;
  }
  if (updates.events !== undefined) {
    await sql`UPDATE webhook_endpoints SET events = ${updates.events}::TEXT[] WHERE id = ${id}::UUID AND company_id = ${companyId}`;
  }
  if (updates.isActive !== undefined) {
    await sql`UPDATE webhook_endpoints SET is_active = ${updates.isActive} WHERE id = ${id}::UUID AND company_id = ${companyId}`;
  }
  const rows = (await sql`
    SELECT * FROM webhook_endpoints WHERE id = ${id}::UUID AND company_id = ${companyId}
  `) as Row[];
  if (!rows[0]) throw new Error('Webhook not found');
  log.info('Webhook updated', { id }, 'webhook');
  return mapWebhook(rows[0]!);
}

export async function deleteWebhook(companyId: string, id: string): Promise<void> {
  await sql`DELETE FROM webhook_endpoints WHERE id = ${id}::UUID AND company_id = ${companyId}`;
  log.info('Webhook deleted', { id }, 'webhook');
}

export async function getDeliveries(
  companyId: string,
  webhookId: string,
  limit = 50,
): Promise<Delivery[]> {
  // Verify ownership
  const rows = (await sql`
    SELECT wd.* FROM webhook_deliveries wd
    JOIN webhook_endpoints we ON we.id = wd.webhook_id
    WHERE wd.webhook_id = ${webhookId}::UUID AND we.company_id = ${companyId}
    ORDER BY wd.delivered_at DESC
    LIMIT ${limit}
  `) as Row[];
  return rows.map(mapDelivery);
}

export async function testWebhook(
  companyId: string,
  id: string,
): Promise<{ success: boolean; status: number; body: string }> {
  const rows = (await sql`
    SELECT * FROM webhook_endpoints WHERE id = ${id}::UUID AND company_id = ${companyId}
  `) as Row[];
  if (!rows[0]) throw new Error('Webhook not found');
  const endpoint = mapWebhook(rows[0]!);

  const payload = { test: true, event: 'webhook.test', timestamp: new Date().toISOString() };
  const body = JSON.stringify(payload);
  const signature = endpoint.secret ? signPayload(endpoint.secret, body) : '';

  try {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 5000);
    const resp = await fetch(endpoint.url, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-Webhook-Event': 'webhook.test',
        ...(signature ? { 'X-Webhook-Signature': signature } : {}),
      },
      body,
      signal: controller.signal,
    });
    clearTimeout(timeout);
    const respBody = await resp.text().catch(() => '');
    log.info('Webhook test sent', { id, status: resp.status }, 'webhook');
    return { success: resp.ok, status: resp.status, body: respBody };
  } catch (err) {
    log.warn('Webhook test failed', { id, error: err }, 'webhook');
    return { success: false, status: 0, body: err instanceof Error ? err.message : 'Request failed' };
  }
}

/**
 * Audit Service
 * Admin action logging for ISAFlow Admin Platform
 * Includes unified audit log across admin, accounting, and auth sources.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { AuditLogEntry, PaginatedResult } from '../types/admin.types';

export interface UnifiedAuditEntry {
  id: string;
  source: 'admin' | 'accounting' | 'auth';
  user_id: string | null;
  user_name: string | null;
  user_email: string | null;
  company_id: string | null;
  company_name: string | null;
  action: string;
  entity_type: string | null;
  entity_id: string | null;
  entity_ref: string | null;
  details: Record<string, unknown> | string | null;
  ip_address: string | null;
  created_at: string;
}

export interface UnifiedAuditFilters {
  source?: 'admin' | 'accounting' | 'auth';
  company_id?: string;
  user_id?: string;
  action?: string;
  entity_type?: string;
  search?: string;
  from_date?: string;
  to_date?: string;
  page?: number;
  limit?: number;
}

export interface AuditLogFilters {
  admin_user_id?: string;
  target_type?: string;
  target_id?: string;
  action?: string;
  from_date?: string;
  to_date?: string;
  page?: number;
  limit?: number;
}

export async function logAdminAction(
  adminUserId: string,
  action: string,
  targetType: string,
  targetId: string | null,
  details: Record<string, unknown> | null,
  ipAddress: string | null
): Promise<void> {
  try {
    await sql`
      INSERT INTO admin_audit_log (
        admin_user_id,
        action,
        target_type,
        target_id,
        details,
        ip_address,
        created_at
      ) VALUES (
        ${adminUserId},
        ${action},
        ${targetType},
        ${targetId},
        ${details ? JSON.stringify(details) : null},
        ${ipAddress},
        NOW()
      )
    `;
  } catch (err) {
    // Audit logging must not break the calling flow — log and swallow
    log.error('logAdminAction failed', { adminUserId, action, error: err }, 'auditService');
  }
}

export async function getAuditLog(
  filters: AuditLogFilters = {}
): Promise<PaginatedResult<AuditLogEntry>> {
  const page = Math.max(1, filters.page ?? 1);
  const limit = Math.min(100, Math.max(1, filters.limit ?? 25));
  const offset = (page - 1) * limit;

  try {
    const rows = await sql`
      SELECT
        al.id,
        al.admin_user_id,
        COALESCE(u.first_name || ' ' || u.last_name, u.email, 'Unknown') AS admin_name,
        al.action,
        al.target_type,
        al.target_id,
        al.details,
        al.ip_address,
        al.created_at
      FROM admin_audit_log al
      LEFT JOIN users u ON u.id = al.admin_user_id::text
      WHERE (
        ${filters.admin_user_id ? sql`al.admin_user_id = ${filters.admin_user_id}` : sql`TRUE`}
      )
      AND (${filters.target_type ? sql`al.target_type = ${filters.target_type}` : sql`TRUE`})
      AND (${filters.target_id ? sql`al.target_id = ${filters.target_id}` : sql`TRUE`})
      AND (${filters.action ? sql`al.action ILIKE ${'%' + filters.action + '%'}` : sql`TRUE`})
      AND (${filters.from_date ? sql`al.created_at >= ${filters.from_date}::timestamptz` : sql`TRUE`})
      AND (${filters.to_date ? sql`al.created_at <= ${filters.to_date}::timestamptz` : sql`TRUE`})
      ORDER BY al.created_at DESC
      LIMIT ${limit} OFFSET ${offset}
    `;

    const [countRow] = await sql`
      SELECT COUNT(*)::int AS total
      FROM admin_audit_log al
      WHERE (
        ${filters.admin_user_id ? sql`al.admin_user_id = ${filters.admin_user_id}` : sql`TRUE`}
      )
      AND (${filters.target_type ? sql`al.target_type = ${filters.target_type}` : sql`TRUE`})
      AND (${filters.target_id ? sql`al.target_id = ${filters.target_id}` : sql`TRUE`})
      AND (${filters.action ? sql`al.action ILIKE ${'%' + filters.action + '%'}` : sql`TRUE`})
      AND (${filters.from_date ? sql`al.created_at >= ${filters.from_date}::timestamptz` : sql`TRUE`})
      AND (${filters.to_date ? sql`al.created_at <= ${filters.to_date}::timestamptz` : sql`TRUE`})
    `;

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const toIso = (v: unknown) =>
      v instanceof Date ? v.toISOString() : (v as string);

    const total = countRow?.total ?? 0;

    return {
      items: rows.map((r) => ({
        id: r.id as string,
        admin_user_id: r.admin_user_id as string,
        admin_name: r.admin_name as string,
        action: r.action as string,
        target_type: r.target_type as string,
        target_id: r.target_id as string | null,
        details: (r.details ?? {}) as Record<string, unknown>,
        ip_address: r.ip_address as string | null,
        created_at: toIso(r.created_at),
      })),
      total,
      page,
      limit,
      total_pages: Math.ceil(total / limit),
    };
  } catch (err) {
    log.error('getAuditLog failed', { error: err }, 'auditService');
    throw err;
  }
}

// ---------------------------------------------------------------------------
// Unified audit log — merges admin_audit_log, audit_log, user_sessions
// ---------------------------------------------------------------------------

// eslint-disable-next-line @typescript-eslint/no-explicit-any
function toIsoDate(v: unknown): string {
  if (v instanceof Date) return v.toISOString();
  return v as string;
}

export async function getUnifiedAuditLog(
  filters: UnifiedAuditFilters = {}
): Promise<PaginatedResult<UnifiedAuditEntry>> {
  const page  = Math.max(1, filters.page  ?? 1);
  const limit = Math.min(100, Math.max(1, filters.limit ?? 50));
  const offset = (page - 1) * limit;

  // Per-source inclusion flags
  const includeAdmin      = !filters.source || filters.source === 'admin';
  const includeAccounting = !filters.source || filters.source === 'accounting';
  const includeAuth       = !filters.source || filters.source === 'auth';

  // Common date / search helpers (applied on the outer WHERE)
  const fromDate    = filters.from_date ?? null;
  const toDate      = filters.to_date   ?? null;
  const searchTerm  = filters.search    ? `%${filters.search}%` : null;
  const filterAction      = filters.action      ?? null;
  const filterEntityType  = filters.entity_type ?? null;
  const filterCompanyId   = filters.company_id  ?? null;
  const filterUserId      = filters.user_id     ?? null;

  try {
    // We build each CTE arm only when the source is requested.
    // Because Neon's sql tag requires a static-ish structure we compose
    // conditional fragments and UNION them.  When a source is excluded we
    // emit a "SELECT ... WHERE FALSE" stub so the UNION still type-checks.

    const rows = await sql`
      WITH admin_rows AS (
        SELECT
          'admin-' || al.id::text                    AS id,
          'admin'::text                              AS source,
          al.admin_user_id::text                     AS user_id,
          COALESCE(u.first_name || ' ' || u.last_name, u.email, 'Admin') AS user_name,
          u.email                                    AS user_email,
          NULL::uuid                                 AS company_id,
          NULL::text                                 AS company_name,
          al.action                                  AS action,
          al.target_type                             AS entity_type,
          al.target_id::text                         AS entity_id,
          NULL::text                                 AS entity_ref,
          al.details::text                           AS details_text,
          al.ip_address                              AS ip_address,
          al.created_at                              AS created_at
        FROM admin_audit_log al
        LEFT JOIN users u ON u.id::text = al.admin_user_id::text
        WHERE ${includeAdmin ? sql`TRUE` : sql`FALSE`}
          AND (${filterCompanyId ? sql`FALSE` : sql`TRUE`})
          AND (${filterUserId    ? sql`al.admin_user_id::text = ${filterUserId}` : sql`TRUE`})
      ),
      accounting_rows AS (
        SELECT
          'acct-' || al.id::text                     AS id,
          'accounting'::text                         AS source,
          al.user_id::text                           AS user_id,
          COALESCE(u.first_name || ' ' || u.last_name, al.user_email, 'User') AS user_name,
          COALESCE(al.user_email, u.email)           AS user_email,
          al.company_id                              AS company_id,
          c.name                                     AS company_name,
          al.action                                  AS action,
          al.entity_type                             AS entity_type,
          al.entity_id::text                         AS entity_id,
          al.entity_ref                              AS entity_ref,
          al.changes::text                           AS details_text,
          al.ip_address                              AS ip_address,
          al.created_at                              AS created_at
        FROM audit_log al
        LEFT JOIN users u ON u.id = al.user_id
        LEFT JOIN companies c ON c.id = al.company_id
        WHERE ${includeAccounting ? sql`TRUE` : sql`FALSE`}
          AND (${filterCompanyId ? sql`al.company_id = ${filterCompanyId}::uuid` : sql`TRUE`})
          AND (${filterUserId    ? sql`al.user_id::text = ${filterUserId}` : sql`TRUE`})
          AND (${filterEntityType ? sql`al.entity_type ILIKE ${filterEntityType}` : sql`TRUE`})
      ),
      auth_rows AS (
        SELECT
          'auth-' || us.id::text                     AS id,
          'auth'::text                               AS source,
          us.user_id::text                           AS user_id,
          COALESCE(u.first_name || ' ' || u.last_name, u.email, 'User') AS user_name,
          u.email                                    AS user_email,
          NULL::uuid                                 AS company_id,
          NULL::text                                 AS company_name,
          'login'::text                              AS action,
          'session'::text                            AS entity_type,
          us.id::text                                AS entity_id,
          NULL::text                                 AS entity_ref,
          NULL::text                                 AS details_text,
          us.ip_address                              AS ip_address,
          us.created_at                              AS created_at
        FROM user_sessions us
        LEFT JOIN users u ON u.id = us.user_id
        WHERE ${includeAuth ? sql`TRUE` : sql`FALSE`}
          AND (${filterCompanyId ? sql`FALSE` : sql`TRUE`})
          AND (${filterUserId    ? sql`us.user_id::text = ${filterUserId}` : sql`TRUE`})
          AND (${filterEntityType ? sql`'session' ILIKE ${filterEntityType}` : sql`TRUE`})
      ),
      combined AS (
        SELECT * FROM admin_rows
        UNION ALL
        SELECT * FROM accounting_rows
        UNION ALL
        SELECT * FROM auth_rows
      )
      SELECT *
      FROM combined
      WHERE (${fromDate   ? sql`created_at >= ${fromDate}::timestamptz`   : sql`TRUE`})
        AND (${toDate     ? sql`created_at <= ${toDate}::timestamptz`     : sql`TRUE`})
        AND (${filterAction ? sql`action ILIKE ${'%' + filterAction + '%'}` : sql`TRUE`})
        AND (${searchTerm
          ? sql`(user_email ILIKE ${searchTerm} OR entity_ref ILIKE ${searchTerm} OR action ILIKE ${searchTerm})`
          : sql`TRUE`})
      ORDER BY created_at DESC
      LIMIT ${limit} OFFSET ${offset}
    `;

    const [countRow] = await sql`
      WITH admin_rows AS (
        SELECT al.admin_user_id::text AS user_id, NULL::uuid AS company_id,
               al.action, NULL::text AS entity_type, NULL::text AS user_email,
               NULL::text AS entity_ref, al.created_at
        FROM admin_audit_log al
        WHERE ${includeAdmin ? sql`TRUE` : sql`FALSE`}
          AND (${filterCompanyId ? sql`FALSE` : sql`TRUE`})
          AND (${filterUserId ? sql`al.admin_user_id::text = ${filterUserId}` : sql`TRUE`})
      ),
      accounting_rows AS (
        SELECT al.user_id::text, al.company_id, al.action, al.entity_type,
               al.user_email, al.entity_ref, al.created_at
        FROM audit_log al
        WHERE ${includeAccounting ? sql`TRUE` : sql`FALSE`}
          AND (${filterCompanyId ? sql`al.company_id = ${filterCompanyId}::uuid` : sql`TRUE`})
          AND (${filterUserId    ? sql`al.user_id::text = ${filterUserId}` : sql`TRUE`})
          AND (${filterEntityType ? sql`al.entity_type ILIKE ${filterEntityType}` : sql`TRUE`})
      ),
      auth_rows AS (
        SELECT us.user_id::text, NULL::uuid AS company_id, 'login'::text AS action,
               'session'::text AS entity_type, u.email AS user_email,
               NULL::text AS entity_ref, us.created_at
        FROM user_sessions us
        LEFT JOIN users u ON u.id = us.user_id
        WHERE ${includeAuth ? sql`TRUE` : sql`FALSE`}
          AND (${filterCompanyId ? sql`FALSE` : sql`TRUE`})
          AND (${filterUserId    ? sql`us.user_id::text = ${filterUserId}` : sql`TRUE`})
          AND (${filterEntityType ? sql`'session' ILIKE ${filterEntityType}` : sql`TRUE`})
      ),
      combined AS (
        SELECT * FROM admin_rows
        UNION ALL
        SELECT * FROM accounting_rows
        UNION ALL
        SELECT * FROM auth_rows
      )
      SELECT COUNT(*)::int AS total
      FROM combined
      WHERE (${fromDate   ? sql`created_at >= ${fromDate}::timestamptz`   : sql`TRUE`})
        AND (${toDate     ? sql`created_at <= ${toDate}::timestamptz`     : sql`TRUE`})
        AND (${filterAction ? sql`action ILIKE ${'%' + filterAction + '%'}` : sql`TRUE`})
        AND (${searchTerm
          ? sql`(user_email ILIKE ${searchTerm} OR entity_ref ILIKE ${searchTerm} OR action ILIKE ${searchTerm})`
          : sql`TRUE`})
    `;

    const total = countRow?.total ?? 0;

    return {
      items: rows.map((r) => {
        let details: Record<string, unknown> | string | null = null;
        if (r.details_text) {
          try {
            details = JSON.parse(r.details_text as string) as Record<string, unknown>;
          } catch {
            details = r.details_text as string;
          }
        }
        return {
          id:           r.id           as string,
          source:       r.source       as 'admin' | 'accounting' | 'auth',
          user_id:      r.user_id      as string | null,
          user_name:    r.user_name    as string | null,
          user_email:   r.user_email   as string | null,
          company_id:   r.company_id   as string | null,
          company_name: r.company_name as string | null,
          action:       r.action       as string,
          entity_type:  r.entity_type  as string | null,
          entity_id:    r.entity_id    as string | null,
          entity_ref:   r.entity_ref   as string | null,
          details,
          ip_address:   r.ip_address   as string | null,
          created_at:   toIsoDate(r.created_at),
        };
      }),
      total,
      page,
      limit,
      total_pages: Math.ceil(total / limit),
    };
  } catch (err) {
    log.error('getUnifiedAuditLog failed', { error: err }, 'auditService');
    throw err;
  }
}

