/**
 * Executive Summary Service
 * Builds a concise executive dashboard summary from financial data.
 * Pure business logic — no database dependencies.
 */

export interface ExecutiveSummaryInput {
  period: string;
  companyName: string;
  revenue: number;
  costOfSales: number;
  operatingExpenses: number;
  netProfit: number;
  totalAssets: number;
  totalLiabilities: number;
  totalEquity: number;
  currentAssets: number;
  currentLiabilities: number;
  cash: number;
  accountsReceivable: number;
  accountsPayable: number;
  inventory: number;
  priorRevenue?: number;
  priorNetProfit?: number;
}

export interface ExecutiveKPIs {
  revenue: number;
  netProfit: number;
  grossProfitMargin: number;
  netProfitMargin: number;
  revenueGrowth: number;
  profitGrowth: number;
  currentRatio: number;
  debtToEquity: number;
  cashBalance: number;
}

export interface CashPositionSummary {
  cashBalance: number;
  accountsReceivable: number;
  accountsPayable: number;
  netWorkingCapital: number;
  currentRatio: number;
}

export interface ExecutiveHighlight {
  type: 'positive' | 'negative' | 'neutral';
  message: string;
}

export interface ExecutiveAlert {
  severity: 'info' | 'warning' | 'danger';
  message: string;
}

export interface ExecutiveSummary {
  period: string;
  companyName: string;
  kpis: ExecutiveKPIs;
  cashPosition: CashPositionSummary;
  highlights: ExecutiveHighlight[];
  alerts: ExecutiveAlert[];
  generatedAt: string;
}

function safeDiv(n: number, d: number): number {
  return d === 0 ? 0 : n / d;
}

function pct(n: number, d: number): number {
  return Math.round(safeDiv(n, d) * 10000) / 100;
}

function growthRate(current: number, prior: number): number {
  if (prior === 0) return 0;
  return Math.round(((current - prior) / prior) * 10000) / 100;
}

export function generateHighlights(input: ExecutiveSummaryInput): ExecutiveHighlight[] {
  const highlights: ExecutiveHighlight[] = [];
  const grossProfit = input.revenue - input.costOfSales;
  const grossMargin = pct(grossProfit, input.revenue);
  const netMargin = pct(input.netProfit, input.revenue);

  if (input.priorRevenue && input.priorRevenue > 0) {
    const revGrowth = growthRate(input.revenue, input.priorRevenue);
    if (revGrowth > 0) {
      highlights.push({ type: 'positive', message: `Revenue grew ${revGrowth.toFixed(1)}% vs prior period` });
    } else if (revGrowth < 0) {
      highlights.push({ type: 'negative', message: `Revenue declined ${Math.abs(revGrowth).toFixed(1)}% vs prior period` });
    }
  }

  if (grossMargin >= 40) {
    highlights.push({ type: 'positive', message: `Strong gross margin of ${grossMargin.toFixed(1)}%` });
  } else if (grossMargin < 20) {
    highlights.push({ type: 'negative', message: `Low gross margin of ${grossMargin.toFixed(1)}% — review cost structure` });
  }

  if (netMargin >= 15) {
    highlights.push({ type: 'positive', message: `Healthy net profit margin of ${netMargin.toFixed(1)}%` });
  } else if (netMargin < 5 && netMargin >= 0) {
    highlights.push({ type: 'neutral', message: `Thin net margin of ${netMargin.toFixed(1)}% — monitor closely` });
  }

  const currentRatio = safeDiv(input.currentAssets, input.currentLiabilities);
  if (currentRatio >= 2.0) {
    highlights.push({ type: 'positive', message: `Strong liquidity with current ratio of ${currentRatio.toFixed(2)}` });
  } else if (currentRatio < 1.0) {
    highlights.push({ type: 'negative', message: `Liquidity risk — current ratio below 1.0 at ${currentRatio.toFixed(2)}` });
  }

  if (highlights.length === 0) {
    highlights.push({ type: 'neutral', message: 'Financial performance in line with expectations' });
  }

  return highlights;
}

export function summarizeCashPosition(input: ExecutiveSummaryInput): CashPositionSummary {
  return {
    cashBalance: input.cash,
    accountsReceivable: input.accountsReceivable,
    accountsPayable: input.accountsPayable,
    netWorkingCapital: input.currentAssets - input.currentLiabilities,
    currentRatio: Math.round(safeDiv(input.currentAssets, input.currentLiabilities) * 100) / 100,
  };
}

export function generateAlerts(input: ExecutiveSummaryInput): ExecutiveAlert[] {
  const alerts: ExecutiveAlert[] = [];

  if (input.netProfit < 0) {
    alerts.push({ severity: 'danger', message: `Net loss of R ${Math.abs(input.netProfit).toLocaleString('en-ZA')} reported this period` });
  }

  const currentRatio = safeDiv(input.currentAssets, input.currentLiabilities);
  if (currentRatio < 1.0) {
    alerts.push({ severity: 'danger', message: `Current ratio ${currentRatio.toFixed(2)} — current liabilities exceed current assets` });
  } else if (currentRatio < 1.2) {
    alerts.push({ severity: 'warning', message: `Current ratio ${currentRatio.toFixed(2)} is below recommended minimum of 1.2` });
  }

  if (input.cash <= 0) {
    alerts.push({ severity: 'danger', message: 'Cash balance is zero or negative — immediate action required' });
  } else if (input.currentLiabilities > 0 && input.cash < input.currentLiabilities * 0.1) {
    alerts.push({ severity: 'warning', message: 'Cash balance is very low relative to current liabilities' });
  }

  const debtToEquity = safeDiv(input.totalLiabilities, input.totalEquity);
  if (debtToEquity > 2.0) {
    alerts.push({ severity: 'warning', message: `High leverage — debt-to-equity ratio at ${debtToEquity.toFixed(2)}` });
  }

  if (input.priorNetProfit && input.priorNetProfit > 0) {
    const profitChange = growthRate(input.netProfit, input.priorNetProfit);
    if (profitChange < -20) {
      alerts.push({ severity: 'warning', message: `Net profit declined ${Math.abs(profitChange).toFixed(1)}% vs prior period` });
    }
  }

  return alerts;
}

export function buildExecutiveSummary(
  input: ExecutiveSummaryInput,
  _from: string,
  _to: string,
): ExecutiveSummary {
  const grossProfit = input.revenue - input.costOfSales;
  const revenueGrowth = input.priorRevenue ? growthRate(input.revenue, input.priorRevenue) : 0;
  const profitGrowth = input.priorNetProfit ? growthRate(input.netProfit, input.priorNetProfit) : 0;

  const kpis: ExecutiveKPIs = {
    revenue: input.revenue,
    netProfit: input.netProfit,
    grossProfitMargin: pct(grossProfit, input.revenue),
    netProfitMargin: pct(input.netProfit, input.revenue),
    revenueGrowth,
    profitGrowth,
    currentRatio: Math.round(safeDiv(input.currentAssets, input.currentLiabilities) * 100) / 100,
    debtToEquity: Math.round(safeDiv(input.totalLiabilities, input.totalEquity) * 100) / 100,
    cashBalance: input.cash,
  };

  return {
    period: input.period,
    companyName: input.companyName,
    kpis,
    cashPosition: summarizeCashPosition(input),
    highlights: generateHighlights(input),
    alerts: generateAlerts(input),
    generatedAt: new Date().toISOString(),
  };
}

/**
 * Report Pack Service
 * Assembles ordered report sections for Board, Management, and Monthly packs.
 * Pure business logic — no database dependencies.
 */

import { calculateExtendedRatios, type FinancialData } from './reportingEngineService';
import { buildKPIScorecard, type KPITargetConfig } from './kpiScorecardService';
import { buildProfitWaterfall } from './waterfallDataService';

export interface ReportPackInput {
  companyName: string;
  period: string;
  revenue: number;
  costOfSales: number;
  operatingExpenses: number;
  netProfit: number;
  totalAssets: number;
  totalLiabilities: number;
  totalEquity: number;
  currentAssets: number;
  currentLiabilities: number;
  cash: number;
  accountsReceivable: number;
  accountsPayable: number;
  inventory: number;
  operatingCashFlow?: number;
  capitalExpenditure?: number;
}

export type PackType = 'board' | 'management' | 'monthly';

export interface PackSectionConfig {
  type: string;
  title: string;
}

export interface PackSection {
  type: string;
  title: string;
  data: Record<string, unknown>;
}

export interface ReportPack {
  type: PackType;
  companyName: string;
  period: string;
  generatedAt: string;
  sections: PackSection[];
}

const BOARD_SECTIONS: PackSectionConfig[] = [
  { type: 'income_statement', title: 'Income Statement' },
  { type: 'balance_sheet', title: 'Balance Sheet' },
  { type: 'ratios', title: 'Financial Ratios' },
  { type: 'kpis', title: 'KPI Scorecard' },
  { type: 'commentary', title: 'Commentary' },
];

const MANAGEMENT_SECTIONS: PackSectionConfig[] = [
  { type: 'income_statement', title: 'Income Statement' },
  { type: 'balance_sheet', title: 'Balance Sheet' },
  { type: 'cash_flow', title: 'Cash Flow' },
  { type: 'ratios', title: 'Financial Ratios' },
  { type: 'kpis', title: 'KPI Scorecard' },
  { type: 'waterfall', title: 'Profit Waterfall' },
  { type: 'trends', title: 'Trend Analysis' },
  { type: 'commentary', title: 'Commentary' },
];

const MONTHLY_SECTIONS: PackSectionConfig[] = [
  { type: 'income_statement', title: 'Income Statement' },
  { type: 'balance_sheet', title: 'Balance Sheet' },
  { type: 'cash_flow', title: 'Cash Flow' },
  { type: 'ratios', title: 'Financial Ratios' },
];

export function getPackTemplate(type: PackType): PackSectionConfig[] {
  switch (type) {
    case 'board': return BOARD_SECTIONS;
    case 'management': return MANAGEMENT_SECTIONS;
    case 'monthly': return MONTHLY_SECTIONS;
  }
}

const DEFAULT_KPI_TARGETS: KPITargetConfig[] = [
  { ratioKey: 'grossProfitMargin', target: 35, warningThreshold: 25, criticalThreshold: 15, lowerIsBetter: false },
  { ratioKey: 'netProfitMargin', target: 15, warningThreshold: 10, criticalThreshold: 5, lowerIsBetter: false },
  { ratioKey: 'currentRatio', target: 1.5, warningThreshold: 1.2, criticalThreshold: 1.0, lowerIsBetter: false },
  { ratioKey: 'debtToEquity', target: 0.5, warningThreshold: 1.0, criticalThreshold: 2.0, lowerIsBetter: true },
  { ratioKey: 'debtorDays', target: 30, warningThreshold: 45, criticalThreshold: 60, lowerIsBetter: true },
];

function buildSectionData(
  type: string,
  input: ReportPackInput,
  financialData: FinancialData,
): Record<string, unknown> {
  const grossProfit = input.revenue - input.costOfSales;

  switch (type) {
    case 'income_statement':
      return {
        revenue: input.revenue,
        costOfSales: input.costOfSales,
        grossProfit,
        operatingExpenses: input.operatingExpenses,
        netProfit: input.netProfit,
        grossMargin: input.revenue > 0 ? Math.round((grossProfit / input.revenue) * 10000) / 100 : 0,
        netMargin: input.revenue > 0 ? Math.round((input.netProfit / input.revenue) * 10000) / 100 : 0,
      };

    case 'balance_sheet':
      return {
        currentAssets: input.currentAssets,
        totalAssets: input.totalAssets,
        currentLiabilities: input.currentLiabilities,
        totalLiabilities: input.totalLiabilities,
        totalEquity: input.totalEquity,
        cash: input.cash,
        accountsReceivable: input.accountsReceivable,
        accountsPayable: input.accountsPayable,
      };

    case 'cash_flow': {
      const opCF = input.operatingCashFlow ?? input.netProfit;
      const capex = input.capitalExpenditure ?? 0;
      return {
        operatingCashFlow: opCF,
        investingCashFlow: -capex,
        financingCashFlow: 0,
        netCashFlow: opCF - capex,
        openingCash: input.cash - (opCF - capex),
        closingCash: input.cash,
      };
    }

    case 'ratios':
      return calculateExtendedRatios(financialData) as unknown as Record<string, unknown>;

    case 'kpis': {
      const ratios = calculateExtendedRatios(financialData);
      const scorecard = buildKPIScorecard(ratios, DEFAULT_KPI_TARGETS);
      return { scorecard };
    }

    case 'waterfall': {
      const steps = buildProfitWaterfall({
        revenue: input.revenue,
        costOfSales: input.costOfSales,
        grossProfit,
        operatingExpenses: input.operatingExpenses,
        otherIncome: 0,
        otherExpenses: 0,
        netProfit: input.netProfit,
      });
      return { steps };
    }

    case 'trends':
      return { note: 'Multi-period trend data requires historical context via API' };

    case 'commentary':
      return {
        period: input.period,
        companyName: input.companyName,
        summary: `${input.companyName} reported revenue of R ${input.revenue.toLocaleString('en-ZA')} with a net profit margin of ${input.revenue > 0 ? Math.round((input.netProfit / input.revenue) * 100) : 0}%.`,
      };

    default:
      return {};
  }
}

export function buildReportPack(
  type: PackType,
  data: ReportPackInput,
  from: string,
  to: string,
): ReportPack {
  const template = getPackTemplate(type);

  const financialData: FinancialData = {
    revenue: data.revenue,
    costOfSales: data.costOfSales,
    operatingExpenses: data.operatingExpenses,
    netProfit: data.netProfit,
    totalAssets: data.totalAssets,
    totalLiabilities: data.totalLiabilities,
    totalEquity: data.totalEquity,
    currentAssets: data.currentAssets,
    currentLiabilities: data.currentLiabilities,
    inventory: data.inventory,
    accountsReceivable: data.accountsReceivable,
    accountsPayable: data.accountsPayable,
    cash: data.cash,
    operatingCashFlow: data.operatingCashFlow,
    capitalExpenditure: data.capitalExpenditure,
  };

  const sections: PackSection[] = template.map(config => ({
    type: config.type,
    title: config.title,
    data: buildSectionData(config.type, data, financialData),
  }));

  return {
    type,
    companyName: data.companyName,
    period: `${from} to ${to}`,
    generatedAt: new Date().toISOString(),
    sections,
  };
}

/**
 * Three-Way Forecast Service
 * Generates linked P&L, Balance Sheet, and Cash Flow projections.
 * Validates: BS balances (A=L+E), CF reconciles to BS cash movement.
 * Pure business logic — no database dependencies.
 */

export interface HistoricalFinancials {
  revenue: number;
  costOfSales: number;
  operatingExpenses: number;
  netProfit: number;
  totalAssets: number;
  totalLiabilities: number;
  totalEquity: number;
  currentAssets: number;
  currentLiabilities: number;
  cash: number;
  accountsReceivable: number;
  accountsPayable: number;
  inventory: number;
}

export interface ForecastParams {
  revenueGrowthRate: number;     // %
  costOfSalesGrowthRate: number; // %
  opexGrowthRate: number;        // %
  capitalExpenditure: number;    // absolute amount per month
  taxRate?: number;              // %, default 27
  dividendPayout?: number;       // absolute amount per month, default 0
}

export interface ForecastPnL {
  revenue: number;
  costOfSales: number;
  grossProfit: number;
  operatingExpenses: number;
  ebit: number;
  taxExpense: number;
  netProfit: number;
}

export interface ForecastBalanceSheet {
  cash: number;
  accountsReceivable: number;
  otherCurrentAssets: number;
  currentAssets: number;
  fixedAssets: number;
  totalAssets: number;
  accountsPayable: number;
  otherCurrentLiabilities: number;
  currentLiabilities: number;
  longTermLiabilities: number;
  totalLiabilities: number;
  retainedEarnings: number;
  totalEquity: number;
}

export interface ForecastCashFlow {
  operatingCashFlow: number;
  investingCashFlow: number;
  financingCashFlow: number;
  netCashFlow: number;
  openingCash: number;
  closingCash: number;
}

export interface ForecastMonth {
  month: number;
  label: string;
  pnl: ForecastPnL;
  balanceSheet: ForecastBalanceSheet;
  cashFlow: ForecastCashFlow;
}

export interface ForecastValidation {
  balanceSheetBalances: boolean;
  cashFlowReconciles: boolean;
  bsDiff: number;
  cfDiff: number;
}

export interface ThreeWayForecastResult {
  months: ForecastMonth[];
  params: ForecastParams;
  generatedAt: string;
}

const TOLERANCE = 1; // R1 rounding tolerance

function applyGrowth(base: number, ratePct: number, monthIndex: number): number {
  // Compound monthly growth
  const monthlyRate = ratePct / 100 / 12;
  return Math.round(base * Math.pow(1 + monthlyRate, monthIndex) * 100) / 100;
}

export function projectPnL(
  historical: HistoricalFinancials,
  params: ForecastParams,
  monthIndex: number,
): ForecastPnL {
  const revenue = applyGrowth(historical.revenue, params.revenueGrowthRate, monthIndex);
  const costOfSales = applyGrowth(historical.costOfSales, params.costOfSalesGrowthRate, monthIndex);
  const grossProfit = revenue - costOfSales;
  const operatingExpenses = applyGrowth(historical.operatingExpenses, params.opexGrowthRate, monthIndex);
  const ebit = grossProfit - operatingExpenses;
  const taxRate = params.taxRate ?? 27;
  const taxExpense = ebit > 0 ? Math.round(ebit * (taxRate / 100) * 100) / 100 : 0;
  const netProfit = Math.round((ebit - taxExpense) * 100) / 100;

  return { revenue, costOfSales, grossProfit, operatingExpenses, ebit, taxExpense, netProfit };
}

export function projectBalanceSheet(
  historical: HistoricalFinancials,
  params: ForecastParams,
  monthIndex: number,
  netProfit: number,
  closingCash?: number,
): ForecastBalanceSheet {
  // AR grows proportionally with revenue growth
  const monthlyRevRate = params.revenueGrowthRate / 100 / 12;
  const accountsReceivable = Math.round(historical.accountsReceivable * Math.pow(1 + monthlyRevRate, monthIndex) * 100) / 100;

  // AP grows proportionally with COGS growth
  const monthlyCOGSRate = params.costOfSalesGrowthRate / 100 / 12;
  const accountsPayable = Math.round(historical.accountsPayable * Math.pow(1 + monthlyCOGSRate, monthIndex) * 100) / 100;

  // Fixed assets: prior + capex (simple model, no depreciation)
  const capexThisPeriod = params.capitalExpenditure;
  const fixedAssets = Math.max(0, Math.round((historical.totalAssets - historical.currentAssets + capexThisPeriod) * 100) / 100);

  // Other current assets remain stable
  const otherCurrentAssets = Math.max(0, historical.currentAssets - historical.cash - historical.accountsReceivable);

  // Liabilities
  const otherCurrentLiabilities = Math.max(0, historical.currentLiabilities - historical.accountsPayable);
  const currentLiabilities = Math.round((accountsPayable + otherCurrentLiabilities) * 100) / 100;
  const longTermLiabilities = Math.round(Math.max(0, historical.totalLiabilities - historical.currentLiabilities) * 100) / 100;
  const totalLiabilities = Math.round((currentLiabilities + longTermLiabilities) * 100) / 100;

  // Equity: prior equity + this period's net profit
  const totalEquity = Math.round((historical.totalEquity + netProfit) * 100) / 100;
  const retainedEarnings = Math.round((historical.totalEquity - historical.totalLiabilities + netProfit) * 100) / 100;

  // Force balance: totalAssets = totalLiabilities + totalEquity (plug into cash)
  const nonCashCurrentAssets = Math.round((accountsReceivable + otherCurrentAssets) * 100) / 100;
  const impliedTotalAssets = Math.round((totalLiabilities + totalEquity) * 100) / 100;
  const impliedCurrentAssets = Math.round((impliedTotalAssets - fixedAssets) * 100) / 100;

  // Cash = implied current assets - non-cash current assets
  const cash = closingCash !== undefined
    ? closingCash
    : Math.round((impliedCurrentAssets - nonCashCurrentAssets) * 100) / 100;

  // Rebuild current assets and total assets using actual cash
  const currentAssets = Math.round((cash + nonCashCurrentAssets) * 100) / 100;
  const totalAssets = Math.round((currentAssets + fixedAssets) * 100) / 100;

  return {
    cash,
    accountsReceivable,
    otherCurrentAssets: Math.round(otherCurrentAssets * 100) / 100,
    currentAssets,
    fixedAssets,
    totalAssets,
    accountsPayable,
    otherCurrentLiabilities,
    currentLiabilities,
    longTermLiabilities,
    totalLiabilities,
    retainedEarnings,
    totalEquity,
  };
}

export function projectCashFlow(
  historical: HistoricalFinancials,
  pnl: ForecastPnL,
  bs: ForecastBalanceSheet,
  params: ForecastParams,
): ForecastCashFlow {
  // Operating: net profit + working capital movements
  const arChange = -(bs.accountsReceivable - historical.accountsReceivable);
  const apChange = bs.accountsPayable - historical.accountsPayable;
  const operatingCashFlow = Math.round((pnl.netProfit + arChange + apChange) * 100) / 100;

  // Investing: capex
  const investingCashFlow = -params.capitalExpenditure;

  // Financing: dividends
  const dividends = params.dividendPayout ?? 0;
  const financingCashFlow = -dividends;

  const netCashFlow = Math.round((operatingCashFlow + investingCashFlow + financingCashFlow) * 100) / 100;
  const openingCash = historical.cash;
  const closingCash = Math.round((openingCash + netCashFlow) * 100) / 100;

  return { operatingCashFlow, investingCashFlow, financingCashFlow, netCashFlow, openingCash, closingCash };
}

export function validateForecast(month: ForecastMonth): ForecastValidation {
  const bs = month.balanceSheet;
  const cf = month.cashFlow;

  // Check A = L + E
  const bsDiff = Math.abs(bs.totalAssets - (bs.totalLiabilities + bs.totalEquity));
  const balanceSheetBalances = bsDiff < TOLERANCE;

  // Check CF net reconciles to cash movement (closing - opening)
  const cashMovement = cf.closingCash - cf.openingCash;
  const cfNet = cf.operatingCashFlow + cf.investingCashFlow + cf.financingCashFlow;
  const cfDiff = Math.abs(cfNet - cashMovement);
  const cashFlowReconciles = cfDiff < TOLERANCE;

  return { balanceSheetBalances, cashFlowReconciles, bsDiff, cfDiff };
}

function monthLabel(baseDate: Date, offset: number): string {
  const d = new Date(baseDate.getFullYear(), baseDate.getMonth() + offset, 1);
  return d.toLocaleDateString('en-ZA', { month: 'short', year: 'numeric' });
}

export function generateThreeWayForecast(
  historical: HistoricalFinancials,
  params: ForecastParams,
  months: number,
): ThreeWayForecastResult {
  const now = new Date();
  const result: ForecastMonth[] = [];

  let prevHistorical = { ...historical };

  for (let i = 1; i <= months; i++) {
    const pnl = projectPnL(historical, params, i);

    // Pass 1: project BS without final cash to derive AR/AP movements
    const bsPass1 = projectBalanceSheet(prevHistorical, params, 1, pnl.netProfit);

    // Project CF using AR/AP from BS pass 1
    const cf = projectCashFlow(prevHistorical, pnl, bsPass1, params);

    // Pass 2: project BS with actual closing cash from CF
    const finalBS = projectBalanceSheet(prevHistorical, params, 1, pnl.netProfit, cf.closingCash);

    result.push({
      month: i,
      label: monthLabel(now, i),
      pnl,
      balanceSheet: finalBS,
      cashFlow: cf,
    });

    // Roll forward
    prevHistorical = {
      revenue: pnl.revenue,
      costOfSales: pnl.costOfSales,
      operatingExpenses: pnl.operatingExpenses,
      netProfit: pnl.netProfit,
      totalAssets: finalBS.totalAssets,
      totalLiabilities: finalBS.totalLiabilities,
      totalEquity: finalBS.totalEquity,
      currentAssets: finalBS.currentAssets,
      currentLiabilities: finalBS.currentLiabilities,
      cash: cf.closingCash,
      accountsReceivable: finalBS.accountsReceivable,
      accountsPayable: finalBS.accountsPayable,
      inventory: historical.inventory,
    };
  }

  return {
    months: result,
    params,
    generatedAt: new Date().toISOString(),
  };
}

/**
 * Multi-Document Match Service
 * Pure business logic — cross-matches PO, GRN, and Invoice documents.
 * No database dependencies.
 */

import type { ExtractedDocument } from '@/modules/accounting/types/documentCapture.types';
import { fuzzyMatchSupplier } from '@/modules/accounting/utils/fuzzyMatch';

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export type DocumentRole = 'purchase_order' | 'delivery_note' | 'invoice';

export type MatchStatus = 'full_match' | 'partial_match' | 'unmatched';

export interface DocumentClassification {
  role: DocumentRole;
  confidence: number;
}

export interface CrossReference {
  field: string;
  poValue: unknown;
  grnValue: unknown;
  invoiceValue: unknown;
  matched: boolean;
}

export interface MatchDiscrepancy {
  field: string;
  expected: unknown;
  actual: unknown;
  severity: 'error' | 'warning';
  message: string;
}

export interface MultiDocMatchInput {
  documents: ExtractedDocument[];
}

export interface MultiDocMatchResult {
  matchStatus: MatchStatus;
  overallConfidence: number;
  classifiedDocuments: Array<{ document: ExtractedDocument; role: DocumentRole; confidence: number }>;
  missingDocuments: DocumentRole[];
  crossReferences: CrossReference[];
  discrepancies: MatchDiscrepancy[];
}

// ---------------------------------------------------------------------------
// Reference number patterns
// ---------------------------------------------------------------------------

const PO_PATTERNS = [/\bPO[-_]?\d/i, /\bpurchase.?order\b/i, /\bPURCH/i];
const GRN_PATTERNS = [/\bGRN[-_]?\d/i, /\bDN[-_]?\d/i, /\bdelivery.?note\b/i, /\bgoods.?receiv/i];
const INV_PATTERNS = [/\bINV[-_]?\d/i, /\bFAKTUUR\b/i, /\bINVOICE\b/i, /\bTAX.?INVOICE\b/i];

function matchesAny(text: string, patterns: RegExp[]): boolean {
  return patterns.some(p => p.test(text));
}

// ---------------------------------------------------------------------------
// classifyDocumentRole
// ---------------------------------------------------------------------------

export function classifyDocumentRole(doc: ExtractedDocument): DocumentClassification {
  const ref = doc.referenceNumber || '';
  const raw = doc.rawText || '';
  const combined = `${ref} ${raw}`;

  // Pattern-based classification has priority
  if (matchesAny(combined, PO_PATTERNS)) {
    return { role: 'purchase_order', confidence: 0.9 };
  }
  if (matchesAny(combined, GRN_PATTERNS)) {
    return { role: 'delivery_note', confidence: 0.9 };
  }
  if (matchesAny(combined, INV_PATTERNS)) {
    return { role: 'invoice', confidence: 0.85 };
  }

  // Fall back to documentType field
  if (doc.documentType === 'purchase_order') {
    return { role: 'purchase_order', confidence: 0.75 };
  }
  if (doc.documentType === 'delivery_note') {
    return { role: 'delivery_note', confidence: 0.75 };
  }
  if (doc.documentType === 'invoice') {
    return { role: 'invoice', confidence: 0.75 };
  }

  // Default to invoice as most common
  return { role: 'invoice', confidence: 0.4 };
}

// ---------------------------------------------------------------------------
// buildCrossReferenceReport
// ---------------------------------------------------------------------------

export function buildCrossReferenceReport(
  po: ExtractedDocument,
  grn: ExtractedDocument,
  invoice: ExtractedDocument,
): CrossReference[] {
  const refs: CrossReference[] = [];

  // Vendor name cross-check
  refs.push({
    field: 'vendorName',
    poValue: po.vendorName,
    grnValue: grn.vendorName,
    invoiceValue: invoice.vendorName,
    matched: vendorNamesMatch(po.vendorName, grn.vendorName, invoice.vendorName),
  });

  // Total amount
  refs.push({
    field: 'totalAmount',
    poValue: po.totalAmount,
    grnValue: grn.totalAmount,
    invoiceValue: invoice.totalAmount,
    matched: amountsMatch(po.totalAmount, invoice.totalAmount),
  });

  // PO reference cross-check (GRN and Invoice should reference the PO)
  refs.push({
    field: 'purchaseOrderRef',
    poValue: po.referenceNumber,
    grnValue: grn.purchaseOrderRef,
    invoiceValue: invoice.purchaseOrderRef,
    matched:
      (grn.purchaseOrderRef != null && grn.purchaseOrderRef === po.referenceNumber) ||
      (invoice.purchaseOrderRef != null && invoice.purchaseOrderRef === po.referenceNumber),
  });

  // Line item cross-checks
  const poItems = po.lineItems ?? [];
  const grnItems = grn.lineItems ?? [];
  const invItems = invoice.lineItems ?? [];

  if (poItems.length > 0 && invItems.length > 0) {
    const poQty = sumField(poItems, 'quantity');
    const grnQty = sumField(grnItems, 'quantity');
    const invQty = sumField(invItems, 'quantity');

    refs.push({
      field: 'quantity',
      poValue: poQty,
      grnValue: grnQty,
      invoiceValue: invQty,
      matched: poQty === invQty && (grnItems.length === 0 || grnQty === invQty),
    });

    const poUnitPrice = avgField(poItems, 'unitPrice');
    const invUnitPrice = avgField(invItems, 'unitPrice');
    refs.push({
      field: 'unitPrice',
      poValue: poUnitPrice,
      grnValue: null,
      invoiceValue: invUnitPrice,
      matched: unitPricesMatch(poUnitPrice, invUnitPrice),
    });
  }

  return refs;
}

// ---------------------------------------------------------------------------
// findDiscrepancies
// ---------------------------------------------------------------------------

export function findDiscrepancies(
  crossRefs: CrossReference[],
  _docs: ExtractedDocument[],
): MatchDiscrepancy[] {
  const discrepancies: MatchDiscrepancy[] = [];

  for (const ref of crossRefs) {
    if (ref.matched) continue;

    const severity = ref.field === 'vendorName' || ref.field === 'unitPrice' || ref.field === 'totalAmount'
      ? 'error'
      : 'warning';

    discrepancies.push({
      field: ref.field,
      expected: ref.poValue,
      actual: ref.invoiceValue,
      severity,
      message: `${ref.field} mismatch: PO=${JSON.stringify(ref.poValue)}, Invoice=${JSON.stringify(ref.invoiceValue)}`,
    });
  }

  return discrepancies;
}

// ---------------------------------------------------------------------------
// performMultiDocMatch
// ---------------------------------------------------------------------------

export function performMultiDocMatch(input: MultiDocMatchInput): MultiDocMatchResult {
  const { documents } = input;

  // Classify each document
  const classified = documents.map(doc => ({
    document: doc,
    ...classifyDocumentRole(doc),
  }));

  const po = classified.find(c => c.role === 'purchase_order');
  const grn = classified.find(c => c.role === 'delivery_note');
  const invoice = classified.find(c => c.role === 'invoice');

  const missingDocuments: DocumentRole[] = [];
  if (!po) missingDocuments.push('purchase_order');
  if (!grn) missingDocuments.push('delivery_note');
  if (!invoice) missingDocuments.push('invoice');

  // Need at least PO + invoice to run a match
  if (!po || !invoice) {
    return {
      matchStatus: 'unmatched',
      overallConfidence: 0,
      classifiedDocuments: classified,
      missingDocuments,
      crossReferences: [],
      discrepancies: [],
    };
  }

  const grnDoc = grn?.document ?? makeEmptyDoc('delivery_note');
  const crossReferences = buildCrossReferenceReport(po.document, grnDoc, invoice.document);
  const discrepancies = findDiscrepancies(crossReferences, documents);

  const errorCount = discrepancies.filter(d => d.severity === 'error').length;
  const matchedCount = crossReferences.filter(r => r.matched).length;
  const totalChecks = crossReferences.length;

  const hasVendorError = discrepancies.some(d => d.field === 'vendorName' && d.severity === 'error');

  let matchStatus: MatchStatus;
  if (hasVendorError) {
    matchStatus = 'unmatched';
  } else if (errorCount === 0 && missingDocuments.length === 0) {
    matchStatus = 'full_match';
  } else if (errorCount === 0 || matchedCount / totalChecks >= 0.5) {
    matchStatus = 'partial_match';
  } else {
    matchStatus = 'unmatched';
  }

  const classificationConfidence =
    classified.reduce((sum, c) => sum + c.confidence, 0) / classified.length;
  const matchConfidence = totalChecks > 0 ? matchedCount / totalChecks : 0;
  const overallConfidence = Math.round(((classificationConfidence + matchConfidence) / 2) * 100) / 100;

  return {
    matchStatus,
    overallConfidence,
    classifiedDocuments: classified,
    missingDocuments,
    crossReferences,
    discrepancies,
  };
}

// ---------------------------------------------------------------------------
// Private helpers
// ---------------------------------------------------------------------------

function makeEmptyDoc(type: ExtractedDocument['documentType']): ExtractedDocument {
  return {
    documentType: type,
    vendorName: null,
    vendorVatNumber: null,
    vendorAddress: null,
    vendorBankDetails: null,
    customerName: null,
    customerVatNumber: null,
    date: null,
    dueDate: null,
    paymentTerms: null,
    referenceNumber: null,
    purchaseOrderRef: null,
    currency: null,
    subtotal: null,
    vatAmount: null,
    vatRate: null,
    totalAmount: null,
    lineItems: [],
    rawText: '',
    confidence: 0,
    warnings: [],
    extractionMethod: 'vlm',
  };
}

function vendorNamesMatch(a: string | null, b: string | null, c: string | null): boolean {
  const names = [a, b, c].filter((n): n is string => n != null);
  if (names.length < 2) return true; // not enough data to fail

  const candidates = names.map(n => ({ id: n, name: n }));
  // All names should fuzzy-match the first one
  return names.slice(1).every(name => {
    const match = fuzzyMatchSupplier(names[0]!, candidates, 0.55);
    return match !== null && fuzzyMatchSupplier(name, [{ id: names[0]!, name: names[0]! }], 0.55) !== null;
  });
}

function amountsMatch(a: number | null, b: number | null, tolerancePct = 2): boolean {
  if (a == null || b == null) return true;
  if (a === 0 && b === 0) return true;
  const base = Math.max(Math.abs(a), Math.abs(b));
  return (Math.abs(a - b) / base) * 100 <= tolerancePct;
}

function unitPricesMatch(a: number | null, b: number | null, tolerancePct = 2): boolean {
  return amountsMatch(a, b, tolerancePct);
}

type LineItemKey = 'quantity' | 'unitPrice' | 'total';

function sumField(items: ExtractedDocument['lineItems'], field: LineItemKey): number {
  return items.reduce((sum, item) => sum + (item[field] ?? 0), 0);
}

function avgField(items: ExtractedDocument['lineItems'], field: LineItemKey): number | null {
  const vals = items.map(i => i[field]).filter((v): v is number => v != null);
  if (vals.length === 0) return null;
  return vals.reduce((s, v) => s + v, 0) / vals.length;
}

