/**
 * Admin Tools Landing Page
 * Overview of available platform tools with navigation cards.
 */

import Link from 'next/link';
import { AdminLayout } from '@/components/admin/AdminLayout';
import { useAdminHref } from '@/hooks/useAdminPrefix';
import { Megaphone, Download, UserCog, Zap, ExternalLink } from 'lucide-react';

interface ToolCard {
  icon: React.ComponentType<{ className?: string }>;
  title: string;
  description: string;
  /** relative admin path (e.g. '/admin/tools/announcements') or null */
  adminHref: string | null;
  externalHref?: string;
  note?: string;
}

const TOOLS: ToolCard[] = [
  {
    icon: Megaphone,
    title: 'Announcements',
    description:
      'Create and manage platform-wide announcements. Target all users, specific plans, or individual companies. Schedule start/end times and mark messages as dismissible.',
    adminHref: '/admin/tools/announcements',
  },
  {
    icon: Download,
    title: 'Data Export',
    description:
      'Export all accounting data for any company as a structured JSON file. Includes chart of accounts, customers, suppliers, invoices, journal entries, and bank transactions.',
    adminHref: null,
    note: 'Navigate to Company Detail then click "Export Data" button to download.',
  },
  {
    icon: UserCog,
    title: 'Impersonation',
    description:
      'View the application as a specific company for debugging and support. Generates a 30-minute impersonation token that switches company context in the customer app.',
    adminHref: null,
    note: 'Navigate to Company Detail then click "Impersonate" button to generate a session.',
  },
  {
    icon: Zap,
    title: 'Sage Auto-Import',
    description:
      'Trigger a full Sage Accounting data import for any company. Pulls chart of accounts, customers, suppliers, invoices, and journal entries via the internal REST API.',
    adminHref: null,
    externalHref: '/accounting/migration/sage-auto',
    note: 'Opens in the customer app -- you must be logged in to a company.',
  },
];

export default function AdminToolsPage() {
  const adminHref = useAdminHref();

  return (
    <AdminLayout title="Admin Tools">
      <div className="max-w-4xl mx-auto space-y-6">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Admin Tools</h1>
          <p className="mt-1 text-sm text-gray-500 dark:text-gray-400">
            Platform management tools for super_admin use only.
          </p>
        </div>

        <div className="grid gap-4 sm:grid-cols-2">
          {TOOLS.map((tool) => {
            const Icon = tool.icon;
            return (
              <div
                key={tool.title}
                className="bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl p-5 flex flex-col gap-3"
              >
                <div className="flex items-center gap-3">
                  <div className="p-2 bg-teal-500/10 rounded-lg">
                    <Icon className="w-5 h-5 text-teal-600 dark:text-teal-400" />
                  </div>
                  <h2 className="text-base font-semibold text-gray-900 dark:text-white">
                    {tool.title}
                  </h2>
                </div>

                <p className="text-sm text-gray-600 dark:text-gray-400 flex-1">
                  {tool.description}
                </p>

                {tool.note && (
                  <p className="text-xs text-amber-600 dark:text-amber-400 bg-amber-50 dark:bg-amber-900/20 rounded-lg px-3 py-2">
                    {tool.note}
                  </p>
                )}

                {tool.externalHref && (
                  <a
                    href={tool.externalHref}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="inline-flex items-center gap-1.5 text-sm font-medium text-teal-600 dark:text-teal-400 hover:underline"
                  >
                    Open Sage Import
                    <ExternalLink className="w-3.5 h-3.5" />
                  </a>
                )}

                {tool.adminHref && (
                  <Link
                    href={adminHref(tool.adminHref)}
                    className="inline-flex items-center gap-1.5 text-sm font-medium text-teal-600 dark:text-teal-400 hover:underline"
                  >
                    Manage {tool.title}
                  </Link>
                )}
              </div>
            );
          })}
        </div>
      </div>
    </AdminLayout>
  );
}

/**
 * Admin Announcements Manager
 * List, create, edit, and delete system announcements.
 */

import { useState, useEffect, useCallback } from 'react';
import { AdminLayout } from '@/components/admin/AdminLayout';
import { ConfirmModal } from '@/components/admin/ConfirmModal';
import {
  AnnouncementModal,
  EMPTY_FORM,
  type AnnouncementFormState,
} from '@/components/admin/AnnouncementModal';
import { apiFetch } from '@/lib/apiFetch';
import { Plus, Pencil, Trash2, AlertCircle, Loader2 } from 'lucide-react';
import type { Announcement } from '@/modules/admin/types/admin.types';

const TYPE_BADGE: Record<string, string> = {
  info:        'bg-blue-500/10 text-blue-600 dark:text-blue-400',
  warning:     'bg-yellow-500/10 text-yellow-600 dark:text-yellow-400',
  maintenance: 'bg-orange-500/10 text-orange-600 dark:text-orange-400',
  feature:     'bg-teal-500/10 text-teal-600 dark:text-teal-400',
};

function fmtDate(v: string | null) {
  if (!v) return '—';
  return new Date(v).toLocaleString('en-ZA', { dateStyle: 'medium', timeStyle: 'short' });
}

function announcementToForm(item: Announcement): AnnouncementFormState {
  return {
    title:          item.title,
    message:        item.message,
    type:           item.type,
    target:         item.target,
    target_ids:     (item.target_ids ?? []).join(', '),
    starts_at:      item.starts_at ? item.starts_at.slice(0, 16) : '',
    ends_at:        item.ends_at   ? item.ends_at.slice(0, 16)   : '',
    is_dismissible: item.is_dismissible,
  };
}

export default function AdminAnnouncementsPage() {
  const [rows, setRows]         = useState<Announcement[]>([]);
  const [loading, setLoading]   = useState(true);
  const [error, setError]       = useState('');
  const [editItem, setEditItem] = useState<Announcement | null>(null);
  const [showNew, setShowNew]   = useState(false);
  const [saving, setSaving]     = useState(false);
  const [deleteId, setDeleteId] = useState<string | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const res  = await apiFetch('/api/admin/announcements?limit=100');
      const data = await res.json();
      setRows(data.data?.items ?? []);
    } catch {
      setError('Failed to load announcements.');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { load(); }, [load]);

  const handleSave = async (form: AnnouncementFormState) => {
    setSaving(true);
    try {
      const targetIds = form.target_ids
        ? form.target_ids.split(',').map(s => s.trim()).filter(Boolean)
        : [];
      const body = {
        title:          form.title,
        message:        form.message,
        type:           form.type,
        target:         form.target,
        target_ids:     targetIds,
        starts_at:      form.starts_at ? new Date(form.starts_at).toISOString() : undefined,
        ends_at:        form.ends_at   ? new Date(form.ends_at).toISOString()   : undefined,
        is_dismissible: form.is_dismissible,
      };

      if (editItem) {
        await apiFetch(`/api/admin/announcements/${editItem.id}`, {
          method: 'PATCH', body: JSON.stringify(body),
        });
      } else {
        await apiFetch('/api/admin/announcements', {
          method: 'POST', body: JSON.stringify(body),
        });
      }

      setEditItem(null);
      setShowNew(false);
      await load();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to save announcement');
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async () => {
    if (!deleteId) return;
    try {
      await apiFetch(`/api/admin/announcements/${deleteId}`, { method: 'DELETE' });
      setDeleteId(null);
      await load();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to delete announcement');
      setDeleteId(null);
    }
  };

  const isModalOpen = showNew || !!editItem;
  const modalInitial = editItem ? announcementToForm(editItem) : { ...EMPTY_FORM };

  return (
    <AdminLayout title="Announcements">
      {isModalOpen && (
        <AnnouncementModal
          initial={modalInitial}
          onClose={() => { setShowNew(false); setEditItem(null); }}
          onSave={handleSave}
          saving={saving}
        />
      )}

      <ConfirmModal
        open={!!deleteId}
        title="Delete Announcement"
        message="This will permanently remove the announcement. Users will no longer see it."
        confirmLabel="Delete"
        onConfirm={handleDelete}
        onCancel={() => setDeleteId(null)}
      />

      <div className="space-y-4">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Announcements</h1>
            <p className="text-sm text-gray-500 dark:text-gray-400 mt-0.5">
              Platform messages shown to users in the app.
            </p>
          </div>
          <button
            onClick={() => setShowNew(true)}
            className="flex items-center gap-1.5 px-4 py-2 bg-teal-600 hover:bg-teal-700 text-white text-sm font-medium rounded-lg"
          >
            <Plus className="w-4 h-4" />
            New Announcement
          </button>
        </div>

        {error && (
          <div className="flex items-center gap-2 text-sm text-red-600 dark:text-red-400 bg-red-50 dark:bg-red-900/20 rounded-lg p-3">
            <AlertCircle className="w-4 h-4 flex-shrink-0" />
            {error}
          </div>
        )}

        {loading ? (
          <div className="flex justify-center py-12">
            <Loader2 className="w-6 h-6 animate-spin text-teal-500" />
          </div>
        ) : rows.length === 0 ? (
          <div className="text-center py-12 text-sm text-gray-500 dark:text-gray-400">
            No announcements yet. Create one to get started.
          </div>
        ) : (
          <div className="overflow-x-auto rounded-xl border border-gray-200 dark:border-gray-700">
            <table className="w-full text-sm">
              <thead className="bg-gray-50 dark:bg-gray-700/50 text-xs text-gray-500 dark:text-gray-400 uppercase tracking-wider">
                <tr>
                  <th className="px-4 py-3 text-left">Title</th>
                  <th className="px-4 py-3 text-left">Type</th>
                  <th className="px-4 py-3 text-left">Target</th>
                  <th className="px-4 py-3 text-left">Starts</th>
                  <th className="px-4 py-3 text-left">Ends</th>
                  <th className="px-4 py-3 text-left">Dismiss.</th>
                  <th className="px-4 py-3 text-right">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100 dark:divide-gray-700">
                {rows.map((row) => (
                  <tr key={row.id} className="bg-white dark:bg-gray-800 hover:bg-gray-50 dark:hover:bg-gray-700/40">
                    <td className="px-4 py-3 font-medium text-gray-900 dark:text-white max-w-xs truncate">
                      {row.title}
                    </td>
                    <td className="px-4 py-3">
                      <span className={`px-2 py-0.5 rounded-full text-xs font-medium capitalize ${TYPE_BADGE[row.type] ?? 'bg-gray-100 text-gray-600'}`}>
                        {row.type}
                      </span>
                    </td>
                    <td className="px-4 py-3 text-gray-600 dark:text-gray-400 capitalize">
                      {row.target}
                    </td>
                    <td className="px-4 py-3 text-gray-600 dark:text-gray-400">
                      {fmtDate(row.starts_at)}
                    </td>
                    <td className="px-4 py-3 text-gray-600 dark:text-gray-400">
                      {fmtDate(row.ends_at)}
                    </td>
                    <td className="px-4 py-3 text-gray-600 dark:text-gray-400">
                      {row.is_dismissible ? 'Yes' : 'No'}
                    </td>
                    <td className="px-4 py-3">
                      <div className="flex items-center justify-end gap-2">
                        <button onClick={() => setEditItem(row)}
                          className="text-gray-400 hover:text-teal-500" title="Edit">
                          <Pencil className="w-4 h-4" />
                        </button>
                        <button onClick={() => setDeleteId(row.id)}
                          className="text-gray-400 hover:text-red-500" title="Delete">
                          <Trash2 className="w-4 h-4" />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </AdminLayout>
  );
}

/**
 * Sage Auto-Import Page
 *
 * Flow:
 * 1. User logs into Sage in a separate browser tab
 * 2. User opens this page and clicks "Connect to Sage"
 * 3. ISAFlow opens a popup/iframe to accounting.sageone.co.za
 * 4. JavaScript runs inside that context (same-session cookies)
 * 5. Each step pulls data from Sage's internal APIs
 * 6. Data is mapped and previewed before import
 */

import { useState, useCallback, useRef, useEffect } from 'react';
import { useRouter } from 'next/router';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import { useAuth } from '@/contexts/AuthContext';
import {
  ArrowLeft, Download, CheckCircle2, AlertCircle,
  Loader2, Database, Users, Building2, FileText, ShieldCheck,
  ExternalLink, RefreshCw,
} from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';

interface PullStep {
  id: string;
  label: string;
  icon: typeof Database;
  description: string;
  status: 'pending' | 'pulling' | 'done' | 'error';
  count?: number;
  error?: string;
}

const INITIAL_STEPS: PullStep[] = [
  { id: 'company', label: 'Company Info', icon: Building2, description: 'Name, tax number, registration', status: 'pending' },
  { id: 'accounts', label: 'Chart of Accounts', icon: Database, description: 'All GL accounts with categories', status: 'pending' },
  { id: 'customers', label: 'Customers', icon: Users, description: 'Customer contacts and balances', status: 'pending' },
  { id: 'suppliers', label: 'Suppliers', icon: Building2, description: 'Supplier contacts and balances', status: 'pending' },
  { id: 'arInvoices', label: 'Customer Invoices (AR)', icon: FileText, description: 'Outstanding sales invoices', status: 'pending' },
  { id: 'apInvoices', label: 'Supplier Invoices (AP)', icon: FileText, description: 'Outstanding purchase invoices', status: 'pending' },
];

export default function SageAutoImportPage() {
  const { user } = useAuth();
  const router = useRouter();
  const [steps, setSteps] = useState<PullStep[]>(INITIAL_STEPS);
  const [connected, setConnected] = useState(false);
  const [pulling, setPulling] = useState(false);
  const [error, setError] = useState('');
  const [sageWindow, setSageWindow] = useState<Window | null>(null);
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const pulledData = useRef<Record<string, any>>({});

  // Super admin only — redirect others
  useEffect(() => {
    if (user && user.role !== 'super_admin') {
      router.replace('/accounting/migration');
    }
  }, [user, router]);

  const updateStep = useCallback((id: string, update: Partial<PullStep>) => {
    setSteps(prev => prev.map(s => s.id === id ? { ...s, ...update } : s));
  }, []);

  const openSageTab = useCallback(() => {
    const win = window.open('https://accounting.sageone.co.za/Dashboard/Home.aspx', 'sage_session');
    if (win) {
      setSageWindow(win);
      setConnected(true);
      setError('');
    } else {
      setError('Popup blocked — please allow popups for this site');
    }
  }, []);

  const runScriptInSage = useCallback(async (script: string): Promise<unknown> => {
    // We can't inject JS into a cross-origin window directly.
    // Instead, we use the fetch approach: the user's Sage tab has cookies,
    // but we call from ISAFlow's context. Since the Sage APIs accept
    // same-origin requests with cookies, we need to proxy through Sage's domain.
    //
    // Alternative approach: execute the fetch from THIS page using the
    // Sage domain — this won't work due to CORS.
    //
    // The working approach: use a message channel with the Sage popup.
    // But since we can't inject into cross-origin, we use the simplest method:
    // fetch from the SERVER side using the session cookies the user provides.
    //
    // ACTUAL working approach for browser automation:
    // The Chrome extension (Claude-in-Chrome) or DevTools MCP can run JS
    // in the Sage tab. For the production flow, we use an approach where
    // the user copies a bookmarklet or we use a browser extension.
    //
    // For now: direct fetch from this page won't work (CORS).
    // We'll use the postMessage approach with a helper page.

    return new Promise((resolve, reject) => {
      if (!sageWindow || sageWindow.closed) {
        reject(new Error('Sage window is closed. Please reconnect.'));
        return;
      }

      // Cross-origin eval is not possible: accounting.sageone.co.za is a
      // different origin from ISAFlow. Browsers block window.eval() (and any
      // property access) on cross-origin windows with a SecurityError.
      // The eval() call that was here has been removed — it can never succeed.
      //
      // The only viable paths are:
      //   1. Bookmarklet: the user runs a script manually inside the Sage tab
      //      (see the "Bookmarklet Method" section below).
      //   2. Browser extension: an extension with "all_urls" permission can
      //      inject content scripts into the Sage domain.
      //   3. Server-side proxy: the user supplies session cookies and ISAFlow
      //      proxies requests to the Sage API server-side.
      reject(new Error('Cannot access Sage window — cross-origin restriction. Use the bookmarklet method instead.'));
    });
  }, [sageWindow]);

  const pullAllData = useCallback(async () => {
    setPulling(true);
    setError('');

    try {
      // Get the fetch scripts from our API
      const scriptsRes = await apiFetch('/api/accounting/migration/sage-pull');
      const scriptsJson = await scriptsRes.json();
      if (!scriptsRes.ok) throw new Error('Failed to load pull scripts');
      const scripts = scriptsJson.data.scripts as Record<string, string>;

      // Run each step
      for (const step of INITIAL_STEPS) {
        updateStep(step.id, { status: 'pulling' });
        try {
          const rawData = await runScriptInSage(scripts[step.id] || '');

          // Send raw data to our API for mapping
          const mapRes = await apiFetch('/api/accounting/migration/sage-pull', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ step: step.id, rawData }),
          });
          const mapJson = await mapRes.json();
          if (!mapRes.ok) throw new Error(mapJson.message || 'Mapping failed');

          pulledData.current[step.id] = mapJson.data;
          updateStep(step.id, {
            status: 'done',
            count: mapJson.data.total ?? mapJson.data.records?.length ?? 1,
          });
        } catch (err) {
          const msg = err instanceof Error ? err.message : 'Pull failed';
          updateStep(step.id, { status: 'error', error: msg });
        }
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to pull data');
    } finally {
      setPulling(false);
    }
  }, [runScriptInSage, updateStep]);

  const allDone = steps.every(s => s.status === 'done');
  const anyError = steps.some(s => s.status === 'error');

  return (
    <AppLayout>
      <div className="max-w-3xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <Link href="/accounting/migration" className="flex items-center gap-2 text-blue-600 hover:text-blue-800 mb-6 text-sm">
          <ArrowLeft className="h-4 w-4" /> Back to Migration Hub
        </Link>

        <div className="flex items-center gap-3 mb-6">
          <div className="p-2 rounded-lg bg-green-500/10">
            <Download className="h-6 w-6 text-green-500" />
          </div>
          <div>
            <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Auto-Import from Sage</h1>
            <p className="text-sm text-[var(--ff-text-secondary)]">Pull data directly from your Sage Business Cloud account</p>
          </div>
        </div>

        {error && (
          <div className="flex items-center gap-2 p-3 rounded-lg bg-red-500/10 text-red-400 text-sm mb-4">
            <AlertCircle className="h-4 w-4 shrink-0" /> {error}
          </div>
        )}

        {/* Step 1: Connect */}
        <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-6 mb-6">
          <h2 className="font-semibold text-[var(--ff-text-primary)] mb-3">Step 1: Connect to Sage</h2>
          <p className="text-sm text-[var(--ff-text-secondary)] mb-4">
            Open Sage Business Cloud in a new window. Make sure you&apos;re logged in and
            have selected the correct company. ISAFlow will read data from your active session.
          </p>
          <div className="flex items-center gap-3">
            <button
              onClick={openSageTab}
              className="flex items-center gap-2 px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-500 text-sm font-medium"
            >
              <ExternalLink className="h-4 w-4" />
              {connected ? 'Reconnect to Sage' : 'Open Sage'}
            </button>
            {connected && (
              <span className="flex items-center gap-1 text-sm text-green-400">
                <CheckCircle2 className="h-4 w-4" /> Sage window open
              </span>
            )}
          </div>
        </div>

        {/* Step 2: Pull Data */}
        <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-6 mb-6">
          <div className="flex items-center justify-between mb-4">
            <h2 className="font-semibold text-[var(--ff-text-primary)]">Step 2: Pull Data</h2>
            <button
              onClick={pullAllData}
              disabled={!connected || pulling}
              className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50 text-sm font-medium"
            >
              {pulling ? <Loader2 className="h-4 w-4 animate-spin" /> : <RefreshCw className="h-4 w-4" />}
              {pulling ? 'Pulling...' : 'Pull All Data'}
            </button>
          </div>

          <div className="divide-y divide-[var(--ff-border-light)]">
            {steps.map(step => {
              const Icon = step.icon;
              return (
                <div key={step.id} className="flex items-center gap-3 py-3">
                  <div className="p-1.5 rounded bg-[var(--ff-bg-primary)]">
                    <Icon className="h-4 w-4 text-[var(--ff-text-secondary)]" />
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className="text-sm font-medium text-[var(--ff-text-primary)]">{step.label}</p>
                    <p className="text-xs text-[var(--ff-text-secondary)]">
                      {step.status === 'error' ? step.error : step.description}
                    </p>
                  </div>
                  <div className="shrink-0">
                    {step.status === 'pending' && (
                      <span className="text-xs text-[var(--ff-text-secondary)]">Waiting</span>
                    )}
                    {step.status === 'pulling' && (
                      <Loader2 className="h-4 w-4 animate-spin text-blue-400" />
                    )}
                    {step.status === 'done' && (
                      <span className="flex items-center gap-1 text-xs text-green-400">
                        <CheckCircle2 className="h-4 w-4" />
                        {step.count} records
                      </span>
                    )}
                    {step.status === 'error' && (
                      <AlertCircle className="h-4 w-4 text-red-400" />
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        </div>

        {/* Step 3: Import into ISAFlow */}
        {(allDone || anyError) && (
          <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-6">
            <div className="flex items-center gap-3 mb-4">
              <ShieldCheck className="h-5 w-5 text-teal-400" />
              <h2 className="font-semibold text-[var(--ff-text-primary)]">Step 3: Import into ISAFlow</h2>
            </div>
            {allDone ? (
              <>
                <p className="text-sm text-[var(--ff-text-secondary)] mb-4">
                  All data pulled successfully. Continue to the Migration Wizard to review and import.
                </p>
                <Link
                  href="/accounting/migration"
                  className="inline-flex items-center gap-2 px-4 py-2 bg-teal-600 text-white rounded-lg hover:bg-teal-500 text-sm font-medium"
                >
                  Continue to Migration Wizard
                </Link>
              </>
            ) : (
              <p className="text-sm text-amber-400">
                Some steps failed. You can retry the pull or continue with partial data.
              </p>
            )}
          </div>
        )}

        {/* Bookmarklet fallback */}
        <div className="mt-8 p-4 rounded-lg border border-[var(--ff-border-light)] bg-[var(--ff-bg-primary)]">
          <h3 className="text-sm font-medium text-[var(--ff-text-primary)] mb-2">Alternative: Bookmarklet Method</h3>
          <p className="text-xs text-[var(--ff-text-secondary)] mb-3">
            If the auto-pull doesn&apos;t work due to browser restrictions, you can use this bookmarklet.
            Drag it to your bookmarks bar, then click it while on the Sage dashboard.
          </p>
          <p className="text-xs text-[var(--ff-text-secondary)] font-mono bg-gray-900 p-2 rounded break-all">
            javascript:void(fetch(&apos;/services/Account/GetWithFilter&apos;,&#123;method:&apos;POST&apos;,headers:&#123;&apos;Content-Type&apos;:&apos;application/json&apos;&#125;,body:JSON.stringify(&#123;FilterId:2,Search:&apos;&apos;,Skip:0,Take:1000&#125;)&#125;).then(r=&gt;r.json()).then(d=&gt;&#123;const b=new Blob([JSON.stringify(d)],&#123;type:&apos;application/json&apos;&#125;);const a=document.createElement(&apos;a&apos;);a.href=URL.createObjectURL(b);a.download=&apos;sage-accounts.json&apos;;a.click()&#125;))
          </p>
        </div>
      </div>
    </AppLayout>
  );
}

