/**
 * Admin Data Migration Tool
 * Bulk CSV upload for accounts, customers, and suppliers — any company.
 */

import { useState, useEffect, useCallback, useRef } from 'react';
import { AdminLayout } from '@/components/admin/AdminLayout';
import { apiFetch } from '@/lib/apiFetch';
import {
  Upload, CheckCircle2, AlertCircle, Loader2, Database, Play,
} from 'lucide-react';

// --- Types ---

type Source = 'xero' | 'quickbooks' | 'pastel';
type FileType = 'accounts' | 'customers' | 'suppliers';
type ZoneStatus = 'idle' | 'uploading' | 'parsed' | 'error';

interface Company {
  id: string;
  name: string;
  trading_name: string | null;
}

interface ZoneState {
  status: ZoneStatus;
  count: number;
  error: string;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  parsed: any[];
}

interface ExecResult {
  accounts?: { succeeded: number; failed: number };
  customers?: { succeeded: number; failed: number };
  suppliers?: { succeeded: number; failed: number };
}

const DEFAULT_ZONE: ZoneState = { status: 'idle', count: 0, error: '', parsed: [] };

const SOURCE_OPTIONS: { value: Source; label: string }[] = [
  { value: 'xero',        label: 'Xero' },
  { value: 'quickbooks',  label: 'QuickBooks' },
  { value: 'pastel',      label: 'Sage / Pastel' },
];

const FILE_ZONES: { type: FileType; label: string; hint: string }[] = [
  { type: 'accounts',  label: 'Chart of Accounts', hint: 'accounts .csv' },
  { type: 'customers', label: 'Customers',          hint: 'customers .csv' },
  { type: 'suppliers', label: 'Suppliers',          hint: 'suppliers .csv' },
];

// --- Helpers ---

function statusIcon(status: ZoneStatus, size = 'w-5 h-5') {
  if (status === 'uploading') return <Loader2 className={`${size} animate-spin text-teal-500`} />;
  if (status === 'parsed')    return <CheckCircle2 className={`${size} text-teal-500`} />;
  if (status === 'error')     return <AlertCircle className={`${size} text-red-500`} />;
  return <Upload className={`${size} text-gray-400`} />;
}

function zoneBorder(status: ZoneStatus) {
  if (status === 'parsed')  return 'border-teal-500 bg-teal-500/5';
  if (status === 'error')   return 'border-red-500 bg-red-500/5';
  if (status === 'uploading') return 'border-teal-400 bg-teal-400/5';
  return 'border-gray-300 dark:border-gray-600 hover:border-teal-400 dark:hover:border-teal-500';
}

// --- Component ---

export default function AdminMigrationsPage() {
  const [companies, setCompanies]       = useState<Company[]>([]);
  const [companiesLoading, setCompaniesLoading] = useState(true);
  const [selectedCompany, setSelectedCompany]   = useState('');
  const [selectedSource, setSelectedSource]     = useState<Source>('xero');
  const [zones, setZones]               = useState<Record<FileType, ZoneState>>({
    accounts:  { ...DEFAULT_ZONE },
    customers: { ...DEFAULT_ZONE },
    suppliers: { ...DEFAULT_ZONE },
  });
  const [executing, setExecuting]       = useState(false);
  const [execResult, setExecResult]     = useState<ExecResult | null>(null);
  const [execError, setExecError]       = useState('');

  const fileRefs = {
    accounts:  useRef<HTMLInputElement>(null),
    customers: useRef<HTMLInputElement>(null),
    suppliers: useRef<HTMLInputElement>(null),
  };

  // Load companies
  const loadCompanies = useCallback(async () => {
    setCompaniesLoading(true);
    try {
      const res  = await apiFetch('/api/admin/companies?limit=200&sort_by=name&sort_dir=asc');
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Failed to load companies');
      const items: Company[] = (json.data?.items ?? []).map((c: Company) => ({
        id: c.id, name: c.name, trading_name: c.trading_name,
      }));
      setCompanies(items);
      if (items.length > 0) setSelectedCompany(items[0].id);
    } catch {
      // Companies will show empty — handled in UI
    } finally {
      setCompaniesLoading(false);
    }
  }, []);

  useEffect(() => { loadCompanies(); }, [loadCompanies]);

  // Reset parsed state when source changes
  useEffect(() => {
    setZones({ accounts: { ...DEFAULT_ZONE }, customers: { ...DEFAULT_ZONE }, suppliers: { ...DEFAULT_ZONE } });
    setExecResult(null);
    setExecError('');
  }, [selectedSource]);

  const patchZone = (type: FileType, patch: Partial<ZoneState>) =>
    setZones(prev => ({ ...prev, [type]: { ...prev[type], ...patch } }));

  const handleFileSelect = async (file: File, type: FileType) => {
    if (!selectedCompany) return;

    patchZone(type, { status: 'uploading', error: '', count: 0, parsed: [] });

    try {
      const formData = new FormData();
      formData.append('file', file);
      formData.append('source', selectedSource);
      formData.append('fileType', type);

      const res  = await apiFetch(
        `/api/accounting/migration-parse?companyId=${selectedCompany}`,
        { method: 'POST', body: formData },
      );
      const json = await res.json();

      if (!res.ok) throw new Error(json.message || 'Parse failed');

      const count: number  = json.data?.count  ?? 0;
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const parsed: any[]  = json.data?.parsed ?? [];
      patchZone(type, { status: 'parsed', count, parsed });
    } catch (err) {
      patchZone(type, {
        status: 'error',
        error: err instanceof Error ? err.message : 'Upload failed',
      });
    }
  };

  const handleExecute = async () => {
    if (!selectedCompany) return;
    setExecuting(true);
    setExecError('');
    setExecResult(null);

    try {
      const res  = await apiFetch(
        `/api/accounting/migration-execute?companyId=${selectedCompany}`,
        {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            source:    selectedSource,
            accounts:  zones.accounts.parsed,
            customers: zones.customers.parsed,
            suppliers: zones.suppliers.parsed,
          }),
        },
      );
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Migration failed');
      setExecResult(json.data as ExecResult);
    } catch (err) {
      setExecError(err instanceof Error ? err.message : 'Migration failed');
    } finally {
      setExecuting(false);
    }
  };

  const anyParsed = Object.values(zones).some(z => z.status === 'parsed');
  const totalParsed = Object.values(zones).reduce((sum, z) => sum + z.count, 0);

  return (
    <AdminLayout title="Data Migration">
      <div className="max-w-3xl mx-auto space-y-6">

        {/* Header */}
        <div className="flex items-center gap-3">
          <div className="p-2 bg-teal-500/10 rounded-lg">
            <Database className="w-5 h-5 text-teal-600 dark:text-teal-400" />
          </div>
          <div>
            <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Data Migration</h1>
            <p className="text-sm text-gray-500 dark:text-gray-400 mt-0.5">
              Upload CSV files to migrate data into any company account.
            </p>
          </div>
        </div>

        {/* Step 1: Company + Source */}
        <div className="bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl p-5 space-y-4">
          <h2 className="text-sm font-semibold text-gray-900 dark:text-white uppercase tracking-wide">
            1. Select Target &amp; Source
          </h2>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-medium text-gray-600 dark:text-gray-400 mb-1">
                Target Company
              </label>
              {companiesLoading ? (
                <div className="flex items-center gap-2 text-sm text-gray-500">
                  <Loader2 className="w-4 h-4 animate-spin" /> Loading&hellip;
                </div>
              ) : (
                <select
                  value={selectedCompany}
                  onChange={e => setSelectedCompany(e.target.value)}
                  className="w-full text-sm border border-gray-300 dark:border-gray-600 rounded-lg px-3 py-2 bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:ring-2 focus:ring-teal-500 focus:border-transparent"
                >
                  {companies.length === 0 && (
                    <option value="">No companies found</option>
                  )}
                  {companies.map(c => (
                    <option key={c.id} value={c.id}>
                      {c.trading_name ?? c.name}
                    </option>
                  ))}
                </select>
              )}
            </div>

            <div>
              <label className="block text-xs font-medium text-gray-600 dark:text-gray-400 mb-1">
                Source System
              </label>
              <select
                value={selectedSource}
                onChange={e => setSelectedSource(e.target.value as Source)}
                className="w-full text-sm border border-gray-300 dark:border-gray-600 rounded-lg px-3 py-2 bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:ring-2 focus:ring-teal-500 focus:border-transparent"
              >
                {SOURCE_OPTIONS.map(opt => (
                  <option key={opt.value} value={opt.value}>{opt.label}</option>
                ))}
              </select>
            </div>
          </div>
        </div>

        {/* Step 2: File upload zones */}
        <div className="bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl p-5 space-y-4">
          <h2 className="text-sm font-semibold text-gray-900 dark:text-white uppercase tracking-wide">
            2. Upload CSV Files
          </h2>

          <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
            {FILE_ZONES.map(({ type, label, hint }) => {
              const zone = zones[type];
              return (
                <div key={type}>
                  <input
                    ref={fileRefs[type]}
                    type="file"
                    accept=".csv,.xlsx"
                    className="hidden"
                    onChange={e => {
                      const f = e.target.files?.[0];
                      if (f) handleFileSelect(f, type);
                      // Reset input so same file can be re-selected
                      e.target.value = '';
                    }}
                  />
                  <button
                    type="button"
                    disabled={!selectedCompany || zone.status === 'uploading'}
                    onClick={() => fileRefs[type].current?.click()}
                    className={[
                      'w-full flex flex-col items-center gap-2 p-4 border-2 border-dashed rounded-xl transition-colors text-center',
                      'disabled:opacity-50 disabled:cursor-not-allowed',
                      zoneBorder(zone.status),
                    ].join(' ')}
                  >
                    {statusIcon(zone.status)}
                    <span className="text-sm font-medium text-gray-700 dark:text-gray-300">{label}</span>
                    {zone.status === 'idle' && (
                      <span className="text-xs text-gray-400">{hint}</span>
                    )}
                    {zone.status === 'uploading' && (
                      <span className="text-xs text-teal-500">Parsing&hellip;</span>
                    )}
                    {zone.status === 'parsed' && (
                      <span className="text-xs text-teal-600 dark:text-teal-400 font-medium">
                        {zone.count} records
                      </span>
                    )}
                    {zone.status === 'error' && (
                      <span className="text-xs text-red-500 line-clamp-2">{zone.error}</span>
                    )}
                  </button>
                </div>
              );
            })}
          </div>

          <p className="text-xs text-gray-400 dark:text-gray-500">
            Click a zone to choose a file. Files are parsed immediately — no data is saved until you execute.
          </p>
        </div>

        {/* Step 3: Summary + Execute */}
        {anyParsed && (
          <div className="bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl p-5 space-y-4">
            <h2 className="text-sm font-semibold text-gray-900 dark:text-white uppercase tracking-wide">
              3. Review &amp; Execute
            </h2>

            <div className="grid grid-cols-3 gap-3 text-center">
              {FILE_ZONES.map(({ type, label }) => (
                <div key={type} className="bg-gray-50 dark:bg-gray-700/40 rounded-lg py-3 px-2">
                  <p className="text-2xl font-bold text-gray-900 dark:text-white">
                    {zones[type].count}
                  </p>
                  <p className="text-xs text-gray-500 dark:text-gray-400 mt-0.5">{label}</p>
                </div>
              ))}
            </div>

            <p className="text-sm text-gray-600 dark:text-gray-400">
              <span className="font-semibold text-gray-900 dark:text-white">{totalParsed} total records</span>
              {' '}will be imported into{' '}
              <span className="font-semibold text-gray-900 dark:text-white">
                {companies.find(c => c.id === selectedCompany)?.trading_name ??
                 companies.find(c => c.id === selectedCompany)?.name ?? 'selected company'}
              </span>.
            </p>

            {execError && (
              <div className="flex items-center gap-2 text-sm text-red-600 dark:text-red-400 bg-red-50 dark:bg-red-900/20 rounded-lg p-3">
                <AlertCircle className="w-4 h-4 flex-shrink-0" />
                {execError}
              </div>
            )}

            <button
              type="button"
              onClick={handleExecute}
              disabled={executing}
              className="flex items-center gap-2 px-5 py-2.5 bg-teal-600 hover:bg-teal-700 disabled:opacity-50 disabled:cursor-not-allowed text-white text-sm font-medium rounded-lg transition-colors"
            >
              {executing
                ? <Loader2 className="w-4 h-4 animate-spin" />
                : <Play className="w-4 h-4" />}
              {executing ? 'Executing migration\u2026' : 'Execute Migration'}
            </button>
          </div>
        )}

        {/* Results */}
        {execResult && (
          <div className="bg-teal-50 dark:bg-teal-900/20 border border-teal-200 dark:border-teal-800 rounded-xl p-5 space-y-3">
            <div className="flex items-center gap-2">
              <CheckCircle2 className="w-5 h-5 text-teal-600 dark:text-teal-400" />
              <h2 className="text-sm font-semibold text-teal-900 dark:text-teal-200">Migration Complete</h2>
            </div>

            <div className="grid grid-cols-3 gap-3 text-center text-sm">
              {FILE_ZONES.map(({ type, label }) => {
                const r = execResult[type];
                if (!r) return null;
                return (
                  <div key={type} className="bg-white dark:bg-gray-800 rounded-lg py-3 px-2">
                    <p className="font-medium text-gray-900 dark:text-white">{label}</p>
                    <p className="text-teal-600 dark:text-teal-400 mt-1">
                      {r.succeeded} imported
                    </p>
                    {r.failed > 0 && (
                      <p className="text-red-500 text-xs">{r.failed} failed</p>
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        )}

      </div>
    </AdminLayout>
  );
}

