/**
 * Admin Data Migration Tool
 * Bulk CSV upload for accounts, customers, and suppliers — any company.
 */

import { useState, useEffect, useCallback, useRef } from 'react';
import { AdminLayout } from '@/components/admin/AdminLayout';
import { apiFetch } from '@/lib/apiFetch';
import { Upload, CheckCircle2, AlertCircle, Loader2, Database, Play } from 'lucide-react';

type Source   = 'xero' | 'quickbooks' | 'pastel';
type FileType = 'accounts' | 'customers' | 'suppliers';
type ZoneStatus = 'idle' | 'uploading' | 'parsed' | 'error';

interface Company { id: string; name: string; trading_name: string | null }
// eslint-disable-next-line @typescript-eslint/no-explicit-any
interface ZoneState { status: ZoneStatus; count: number; error: string; parsed: any[] }
interface ExecResult {
  accounts?:  { succeeded: number; failed: number };
  customers?: { succeeded: number; failed: number };
  suppliers?: { succeeded: number; failed: number };
}

const BLANK: ZoneState = { status: 'idle', count: 0, error: '', parsed: [] };

const SOURCES: { value: Source; label: string }[] = [
  { value: 'xero',       label: 'Xero' },
  { value: 'quickbooks', label: 'QuickBooks' },
  { value: 'pastel',     label: 'Sage / Pastel' },
];

const ZONES: { type: FileType; label: string }[] = [
  { type: 'accounts',  label: 'Chart of Accounts' },
  { type: 'customers', label: 'Customers' },
  { type: 'suppliers', label: 'Suppliers' },
];

function zoneCls(s: ZoneStatus) {
  if (s === 'parsed')    return 'border-teal-500 bg-teal-500/5';
  if (s === 'error')     return 'border-red-400 bg-red-500/5';
  if (s === 'uploading') return 'border-teal-300 bg-teal-400/5';
  return 'border-gray-300 dark:border-gray-600 hover:border-teal-400';
}

export default function AdminMigrationsPage() {
  const [companies, setCompanies]   = useState<Company[]>([]);
  const [loadingCo, setLoadingCo]   = useState(true);
  const [companyId, setCompanyId]   = useState('');
  const [source, setSource]         = useState<Source>('xero');
  const [zones, setZones]           = useState<Record<FileType, ZoneState>>({
    accounts: { ...BLANK }, customers: { ...BLANK }, suppliers: { ...BLANK },
  });
  const [executing, setExecuting]   = useState(false);
  const [result, setResult]         = useState<ExecResult | null>(null);
  const [execErr, setExecErr]       = useState('');

  const refs = {
    accounts:  useRef<HTMLInputElement>(null),
    customers: useRef<HTMLInputElement>(null),
    suppliers: useRef<HTMLInputElement>(null),
  };

  const patch = (t: FileType, p: Partial<ZoneState>) =>
    setZones(prev => ({ ...prev, [t]: { ...prev[t], ...p } }));

  const loadCompanies = useCallback(async () => {
    setLoadingCo(true);
    try {
      const res  = await apiFetch('/api/admin/companies?limit=200&sort_by=name&sort_dir=asc');
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Failed');
      const items: Company[] = (json.data?.items ?? []).map((c: Company) =>
        ({ id: c.id, name: c.name, trading_name: c.trading_name }));
      setCompanies(items);
      if (items.length > 0 && items[0]) setCompanyId(items[0].id);
    } catch { /* error state handled by empty list */ } finally { setLoadingCo(false); }
  }, []);

  useEffect(() => { loadCompanies(); }, [loadCompanies]);

  // Reset zones when source changes
  useEffect(() => {
    setZones({ accounts: { ...BLANK }, customers: { ...BLANK }, suppliers: { ...BLANK } });
    setResult(null);
    setExecErr('');
  }, [source]);

  const handleFile = async (file: File, type: FileType) => {
    if (!companyId) return;
    patch(type, { status: 'uploading', error: '', count: 0, parsed: [] });
    try {
      const fd = new FormData();
      fd.append('file', file);
      fd.append('source', source);
      fd.append('fileType', type);
      const res  = await apiFetch(`/api/accounting/migration-parse?companyId=${companyId}`, { method: 'POST', body: fd });
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Parse failed');
      patch(type, { status: 'parsed', count: json.data?.count ?? 0, parsed: json.data?.parsed ?? [] });
    } catch (err) {
      patch(type, { status: 'error', error: err instanceof Error ? err.message : 'Upload failed' });
    }
  };

  const handleExecute = async () => {
    if (!companyId) return;
    setExecuting(true); setExecErr(''); setResult(null);
    try {
      const res  = await apiFetch(`/api/accounting/migration-execute?companyId=${companyId}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ source, accounts: zones.accounts.parsed, customers: zones.customers.parsed, suppliers: zones.suppliers.parsed }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Migration failed');
      setResult(json.data as ExecResult);
    } catch (err) {
      setExecErr(err instanceof Error ? err.message : 'Migration failed');
    } finally { setExecuting(false); }
  };

  const anyParsed  = Object.values(zones).some(z => z.status === 'parsed');
  const totalCount = Object.values(zones).reduce((s, z) => s + z.count, 0);
  const companyName = companies.find(c => c.id === companyId);

  const selectCls = 'w-full text-sm border border-gray-300 dark:border-gray-600 rounded-lg px-3 py-2 bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:ring-2 focus:ring-teal-500 focus:border-transparent';

  return (
    <AdminLayout title="Data Migration">
      <div className="max-w-3xl mx-auto space-y-5">

        {/* Header */}
        <div className="flex items-center gap-3">
          <div className="p-2 bg-teal-500/10 rounded-lg">
            <Database className="w-5 h-5 text-teal-600 dark:text-teal-400" />
          </div>
          <div>
            <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Data Migration</h1>
            <p className="text-sm text-gray-500 dark:text-gray-400 mt-0.5">
              Upload CSV files to migrate data into any company account.
            </p>
          </div>
        </div>

        {/* Step 1 — Company + Source */}
        <div className="bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl p-5 space-y-4">
          <p className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wide">1. Target &amp; Source</p>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-medium text-gray-600 dark:text-gray-400 mb-1">Company</label>
              {loadingCo ? (
                <div className="flex items-center gap-2 text-sm text-gray-400"><Loader2 className="w-4 h-4 animate-spin" /> Loading&hellip;</div>
              ) : (
                <select value={companyId} onChange={e => setCompanyId(e.target.value)} className={selectCls}>
                  {!companies.length && <option value="">No companies found</option>}
                  {companies.map(c => <option key={c.id} value={c.id}>{c.trading_name ?? c.name}</option>)}
                </select>
              )}
            </div>
            <div>
              <label className="block text-xs font-medium text-gray-600 dark:text-gray-400 mb-1">Source System</label>
              <select value={source} onChange={e => setSource(e.target.value as Source)} className={selectCls}>
                {SOURCES.map(s => <option key={s.value} value={s.value}>{s.label}</option>)}
              </select>
            </div>
          </div>
        </div>

        {/* Step 2 — Upload zones */}
        <div className="bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl p-5 space-y-3">
          <p className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wide">2. Upload CSV Files</p>
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
            {ZONES.map(({ type, label }) => {
              const z = zones[type];
              return (
                <div key={type}>
                  <input ref={refs[type]} type="file" accept=".csv,.xlsx" className="hidden"
                    onChange={e => { const f = e.target.files?.[0]; if (f) handleFile(f, type); e.target.value = ''; }} />
                  <button type="button" disabled={!companyId || z.status === 'uploading'}
                    onClick={() => refs[type].current?.click()}
                    className={`w-full flex flex-col items-center gap-2 p-4 border-2 border-dashed rounded-xl transition-colors text-center disabled:opacity-50 disabled:cursor-not-allowed ${zoneCls(z.status)}`}>
                    {z.status === 'uploading' ? <Loader2 className="w-5 h-5 animate-spin text-teal-500" />
                      : z.status === 'parsed'  ? <CheckCircle2 className="w-5 h-5 text-teal-500" />
                      : z.status === 'error'   ? <AlertCircle className="w-5 h-5 text-red-500" />
                      : <Upload className="w-5 h-5 text-gray-400" />}
                    <span className="text-sm font-medium text-gray-700 dark:text-gray-300">{label}</span>
                    {z.status === 'idle'      && <span className="text-xs text-gray-400">.csv / .xlsx</span>}
                    {z.status === 'uploading' && <span className="text-xs text-teal-500">Parsing&hellip;</span>}
                    {z.status === 'parsed'    && <span className="text-xs font-semibold text-teal-600 dark:text-teal-400">{z.count} records</span>}
                    {z.status === 'error'     && <span className="text-xs text-red-500 line-clamp-2">{z.error}</span>}
                  </button>
                </div>
              );
            })}
          </div>
          <p className="text-xs text-gray-400">Files are parsed client-side — no data saved until you execute below.</p>
        </div>

        {/* Step 3 — Summary + Execute */}
        {anyParsed && (
          <div className="bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl p-5 space-y-4">
            <p className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wide">3. Review &amp; Execute</p>
            <div className="grid grid-cols-3 gap-3 text-center">
              {ZONES.map(({ type, label }) => (
                <div key={type} className="bg-gray-50 dark:bg-gray-700/40 rounded-lg py-3">
                  <p className="text-2xl font-bold text-gray-900 dark:text-white">{zones[type].count}</p>
                  <p className="text-xs text-gray-500 dark:text-gray-400 mt-0.5">{label}</p>
                </div>
              ))}
            </div>
            <p className="text-sm text-gray-600 dark:text-gray-400">
              <strong className="text-gray-900 dark:text-white">{totalCount} records</strong> will be imported into{' '}
              <strong className="text-gray-900 dark:text-white">{companyName?.trading_name ?? companyName?.name ?? 'selected company'}</strong>.
            </p>
            {execErr && (
              <div className="flex items-center gap-2 text-sm text-red-600 dark:text-red-400 bg-red-50 dark:bg-red-900/20 rounded-lg p-3">
                <AlertCircle className="w-4 h-4 flex-shrink-0" />{execErr}
              </div>
            )}
            <button type="button" onClick={handleExecute} disabled={executing}
              className="flex items-center gap-2 px-5 py-2.5 bg-teal-600 hover:bg-teal-700 disabled:opacity-50 disabled:cursor-not-allowed text-white text-sm font-medium rounded-lg transition-colors">
              {executing ? <Loader2 className="w-4 h-4 animate-spin" /> : <Play className="w-4 h-4" />}
              {executing ? 'Running\u2026' : 'Execute Migration'}
            </button>
          </div>
        )}

        {/* Results */}
        {result && (
          <div className="bg-teal-50 dark:bg-teal-900/20 border border-teal-200 dark:border-teal-800 rounded-xl p-5 space-y-3">
            <div className="flex items-center gap-2">
              <CheckCircle2 className="w-5 h-5 text-teal-600 dark:text-teal-400" />
              <p className="text-sm font-semibold text-teal-900 dark:text-teal-200">Migration complete</p>
            </div>
            <div className="grid grid-cols-3 gap-3 text-center text-sm">
              {ZONES.map(({ type, label }) => {
                const r = result[type];
                if (!r) return <div key={type} className="bg-white dark:bg-gray-800 rounded-lg py-3 px-2 text-gray-400 text-xs">{label}<br />not imported</div>;
                return (
                  <div key={type} className="bg-white dark:bg-gray-800 rounded-lg py-3 px-2">
                    <p className="font-medium text-gray-900 dark:text-white">{label}</p>
                    <p className="text-teal-600 dark:text-teal-400 mt-1">{r.succeeded} imported</p>
                    {r.failed > 0 && <p className="text-red-500 text-xs">{r.failed} failed</p>}
                  </div>
                );
              })}
            </div>
          </div>
        )}

      </div>
    </AdminLayout>
  );
}

/**
 * Admin Sage Auto-Import
 * Wraps the Sage import flow for admins, with a company selector.
 * Admin picks a target company, then proceeds through the same
 * connect → pull → review steps as the customer-facing page.
 */

import { useState, useCallback, useRef, useEffect } from 'react';
import { AdminLayout } from '@/components/admin/AdminLayout';
import { useAdminHref } from '@/hooks/useAdminPrefix';
import Link from 'next/link';
import { apiFetch } from '@/lib/apiFetch';
import {
  ArrowLeft, Download, CheckCircle2, AlertCircle,
  Loader2, Database, Users, Building2, FileText, ShieldCheck,
  ExternalLink, RefreshCw,
} from 'lucide-react';

interface Company {
  id: string;
  name: string;
}

interface PullStep {
  id: string;
  label: string;
  icon: typeof Database;
  description: string;
  status: 'pending' | 'pulling' | 'done' | 'error';
  count?: number;
  error?: string;
}

const INITIAL_STEPS: PullStep[] = [
  { id: 'company',    label: 'Company Info',           icon: Building2, description: 'Name, tax number, registration',   status: 'pending' },
  { id: 'accounts',  label: 'Chart of Accounts',       icon: Database,  description: 'All GL accounts with categories',  status: 'pending' },
  { id: 'customers', label: 'Customers',               icon: Users,     description: 'Customer contacts and balances',   status: 'pending' },
  { id: 'suppliers', label: 'Suppliers',               icon: Building2, description: 'Supplier contacts and balances',   status: 'pending' },
  { id: 'arInvoices',label: 'Customer Invoices (AR)',  icon: FileText,  description: 'Outstanding sales invoices',       status: 'pending' },
  { id: 'apInvoices',label: 'Supplier Invoices (AP)',  icon: FileText,  description: 'Outstanding purchase invoices',    status: 'pending' },
];

export default function AdminSageImportPage() {
  const adminHref = useAdminHref();

  const [companies, setCompanies]               = useState<Company[]>([]);
  const [selectedCompanyId, setSelectedCompanyId] = useState('');
  const [companiesError, setCompaniesError]     = useState('');

  const [steps, setSteps]       = useState<PullStep[]>(INITIAL_STEPS);
  const [connected, setConnected] = useState(false);
  const [pulling, setPulling]   = useState(false);
  const [error, setError]       = useState('');
  const [sageWindow, setSageWindow] = useState<Window | null>(null);
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const pulledData = useRef<Record<string, any>>({});

  // Load companies on mount
  useEffect(() => {
    apiFetch('/api/admin/companies?limit=200')
      .then(r => r.json())
      .then(d => setCompanies(d.data?.items ?? []))
      .catch(() => setCompaniesError('Failed to load companies.'));
  }, []);

  const updateStep = useCallback((id: string, update: Partial<PullStep>) => {
    setSteps(prev => prev.map(s => s.id === id ? { ...s, ...update } : s));
  }, []);

  const openSageTab = useCallback(() => {
    const win = window.open('https://accounting.sageone.co.za/Dashboard/Home.aspx', 'sage_session');
    if (win) {
      setSageWindow(win);
      setConnected(true);
      setError('');
    } else {
      setError('Popup blocked — please allow popups for this site.');
    }
  }, []);

  const runScriptInSage = useCallback(async (_script: string): Promise<unknown> => {
    return new Promise((_resolve, reject) => {
      if (!sageWindow || sageWindow.closed) {
        reject(new Error('Sage window is closed. Please reconnect.'));
        return;
      }
      // Cross-origin restriction: cannot inject JS into accounting.sageone.co.za.
      // Use the bookmarklet method below as an alternative.
      reject(new Error('Cannot access Sage window — cross-origin restriction. Use the bookmarklet method instead.'));
    });
  }, [sageWindow]);

  const pullAllData = useCallback(async () => {
    if (!selectedCompanyId) {
      setError('Please select a target company before pulling data.');
      return;
    }
    setPulling(true);
    setError('');

    try {
      const scriptsRes  = await apiFetch(`/api/accounting/migration/sage-pull?companyId=${selectedCompanyId}`);
      const scriptsJson = await scriptsRes.json();
      if (!scriptsRes.ok) throw new Error('Failed to load pull scripts');
      const scripts = scriptsJson.data.scripts as Record<string, string>;

      for (const step of INITIAL_STEPS) {
        updateStep(step.id, { status: 'pulling' });
        try {
          const rawData = await runScriptInSage(scripts[step.id] || '');

          const mapRes  = await apiFetch(
            `/api/accounting/migration/sage-pull?companyId=${selectedCompanyId}`,
            {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ step: step.id, rawData }),
            },
          );
          const mapJson = await mapRes.json();
          if (!mapRes.ok) throw new Error(mapJson.message || 'Mapping failed');

          pulledData.current[step.id] = mapJson.data;
          updateStep(step.id, {
            status: 'done',
            count: mapJson.data.total ?? mapJson.data.records?.length ?? 1,
          });
        } catch (err) {
          const msg = err instanceof Error ? err.message : 'Pull failed';
          updateStep(step.id, { status: 'error', error: msg });
        }
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to pull data');
    } finally {
      setPulling(false);
    }
  }, [selectedCompanyId, runScriptInSage, updateStep]);

  const allDone  = steps.every(s => s.status === 'done');
  const anyError = steps.some(s => s.status === 'error');

  return (
    <AdminLayout title="Sage Auto-Import">
      <div className="max-w-3xl mx-auto space-y-6">

        {/* Header */}
        <div>
          <Link
            href={adminHref('/admin/tools')}
            className="inline-flex items-center gap-1.5 text-sm text-teal-600 dark:text-teal-400 hover:underline mb-4"
          >
            <ArrowLeft className="w-4 h-4" /> Back to Admin Tools
          </Link>
          <div className="flex items-center gap-3">
            <div className="p-2 rounded-lg bg-teal-500/10">
              <Download className="h-6 w-6 text-teal-600 dark:text-teal-400" />
            </div>
            <div>
              <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Sage Auto-Import</h1>
              <p className="text-sm text-gray-500 dark:text-gray-400">
                Pull data from Sage Business Cloud into an ISAFlow company.
              </p>
            </div>
          </div>
        </div>

        {/* Global error */}
        {error && (
          <div className="flex items-center gap-2 p-3 rounded-lg bg-red-500/10 text-red-600 dark:text-red-400 text-sm">
            <AlertCircle className="h-4 w-4 shrink-0" /> {error}
          </div>
        )}

        {/* Company Selector */}
        <div className="bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl p-6">
          <h2 className="font-semibold text-gray-900 dark:text-white mb-3">Target Company</h2>
          <p className="text-sm text-gray-500 dark:text-gray-400 mb-4">
            Select the ISAFlow company that Sage data will be imported into.
          </p>

          {companiesError ? (
            <div className="flex items-center gap-2 text-sm text-red-600 dark:text-red-400">
              <AlertCircle className="h-4 w-4 shrink-0" /> {companiesError}
            </div>
          ) : (
            <select
              value={selectedCompanyId}
              onChange={e => setSelectedCompanyId(e.target.value)}
              className="w-full rounded-lg border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 text-gray-900 dark:text-white text-sm px-3 py-2 focus:outline-none focus:ring-2 focus:ring-teal-500"
            >
              <option value="">-- Select a company --</option>
              {companies.map(c => (
                <option key={c.id} value={c.id}>{c.name}</option>
              ))}
            </select>
          )}
        </div>

        {/* Step 1: Connect */}
        <div className="bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl p-6">
          <h2 className="font-semibold text-gray-900 dark:text-white mb-3">Step 1: Connect to Sage</h2>
          <p className="text-sm text-gray-500 dark:text-gray-400 mb-4">
            Open Sage Business Cloud in a new window. Log in and select the correct company.
            ISAFlow will read data from the active session.
          </p>
          <div className="flex items-center gap-3">
            <button
              onClick={openSageTab}
              className="flex items-center gap-2 px-4 py-2 bg-teal-600 hover:bg-teal-700 text-white rounded-lg text-sm font-medium"
            >
              <ExternalLink className="h-4 w-4" />
              {connected ? 'Reconnect to Sage' : 'Open Sage'}
            </button>
            {connected && (
              <span className="flex items-center gap-1 text-sm text-teal-500">
                <CheckCircle2 className="h-4 w-4" /> Sage window open
              </span>
            )}
          </div>
        </div>

        {/* Step 2: Pull Data */}
        <div className="bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl p-6">
          <div className="flex items-center justify-between mb-4">
            <h2 className="font-semibold text-gray-900 dark:text-white">Step 2: Pull Data</h2>
            <button
              onClick={pullAllData}
              disabled={!connected || pulling || !selectedCompanyId}
              className="flex items-center gap-2 px-4 py-2 bg-teal-600 hover:bg-teal-700 text-white rounded-lg disabled:opacity-50 text-sm font-medium"
            >
              {pulling
                ? <Loader2 className="h-4 w-4 animate-spin" />
                : <RefreshCw className="h-4 w-4" />}
              {pulling ? 'Pulling...' : 'Pull All Data'}
            </button>
          </div>

          <div className="divide-y divide-gray-100 dark:divide-gray-700">
            {steps.map(step => {
              const Icon = step.icon;
              return (
                <div key={step.id} className="flex items-center gap-3 py-3">
                  <div className="p-1.5 rounded bg-gray-100 dark:bg-gray-700">
                    <Icon className="h-4 w-4 text-gray-500 dark:text-gray-400" />
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className="text-sm font-medium text-gray-900 dark:text-white">{step.label}</p>
                    <p className="text-xs text-gray-500 dark:text-gray-400">
                      {step.status === 'error' ? step.error : step.description}
                    </p>
                  </div>
                  <div className="shrink-0">
                    {step.status === 'pending' && (
                      <span className="text-xs text-gray-400">Waiting</span>
                    )}
                    {step.status === 'pulling' && (
                      <Loader2 className="h-4 w-4 animate-spin text-teal-500" />
                    )}
                    {step.status === 'done' && (
                      <span className="flex items-center gap-1 text-xs text-teal-500">
                        <CheckCircle2 className="h-4 w-4" />
                        {step.count} records
                      </span>
                    )}
                    {step.status === 'error' && (
                      <AlertCircle className="h-4 w-4 text-red-400" />
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        </div>

        {/* Step 3: Confirm */}
        {(allDone || anyError) && (
          <div className="bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl p-6">
            <div className="flex items-center gap-3 mb-4">
              <ShieldCheck className="h-5 w-5 text-teal-500" />
              <h2 className="font-semibold text-gray-900 dark:text-white">Step 3: Review &amp; Import</h2>
            </div>
            {allDone ? (
              <p className="text-sm text-gray-500 dark:text-gray-400">
                All data pulled successfully. Navigate to the target company&apos;s Migration
                Wizard in the customer app to complete the import.
              </p>
            ) : (
              <p className="text-sm text-amber-600 dark:text-amber-400">
                Some steps failed. You can retry the pull or continue with partial data.
              </p>
            )}
          </div>
        )}

        {/* Bookmarklet fallback */}
        <div className="p-4 rounded-xl border border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-800/50">
          <h3 className="text-sm font-medium text-gray-900 dark:text-white mb-2">
            Alternative: Bookmarklet Method
          </h3>
          <p className="text-xs text-gray-500 dark:text-gray-400 mb-3">
            If auto-pull fails due to browser restrictions, drag the snippet below to your
            bookmarks bar and click it while on the Sage dashboard.
          </p>
          <p className="text-xs font-mono bg-gray-900 text-gray-300 p-2 rounded break-all">
            javascript:void(fetch(&apos;/services/Account/GetWithFilter&apos;,&#123;method:&apos;POST&apos;,headers:&#123;&apos;Content-Type&apos;:&apos;application/json&apos;&#125;,body:JSON.stringify(&#123;FilterId:2,Search:&apos;&apos;,Skip:0,Take:1000&#125;)&#125;).then(r=&gt;r.json()).then(d=&gt;&#123;const b=new Blob([JSON.stringify(d)],&#123;type:&apos;application/json&apos;&#125;);const a=document.createElement(&apos;a&apos;);a.href=URL.createObjectURL(b);a.download=&apos;sage-accounts.json&apos;;a.click()&#125;))
          </p>
        </div>

      </div>
    </AdminLayout>
  );
}

/**
 * Admin Data Migration Tool
 * Bulk CSV upload for accounts, customers, and suppliers — any company.
 */

import { useState, useEffect, useCallback, useRef } from 'react';
import { AdminLayout } from '@/components/admin/AdminLayout';
import { apiFetch } from '@/lib/apiFetch';
import { Upload, CheckCircle2, AlertCircle, Loader2, Database, Play } from 'lucide-react';

type Source   = 'xero' | 'quickbooks' | 'pastel';
type FileType = 'accounts' | 'customers' | 'suppliers';
type ZoneStatus = 'idle' | 'uploading' | 'parsed' | 'error';

interface Company { id: string; name: string; trading_name: string | null }
// eslint-disable-next-line @typescript-eslint/no-explicit-any
interface ZoneState { status: ZoneStatus; count: number; error: string; parsed: any[] }
interface ExecResult {
  accounts?:  { succeeded: number; failed: number };
  customers?: { succeeded: number; failed: number };
  suppliers?: { succeeded: number; failed: number };
}

const BLANK: ZoneState = { status: 'idle', count: 0, error: '', parsed: [] };

const SOURCES: { value: Source; label: string }[] = [
  { value: 'xero',       label: 'Xero' },
  { value: 'quickbooks', label: 'QuickBooks' },
  { value: 'pastel',     label: 'Sage / Pastel' },
];

const ZONES: { type: FileType; label: string }[] = [
  { type: 'accounts',  label: 'Chart of Accounts' },
  { type: 'customers', label: 'Customers' },
  { type: 'suppliers', label: 'Suppliers' },
];

function zoneCls(s: ZoneStatus) {
  if (s === 'parsed')    return 'border-teal-500 bg-teal-500/5';
  if (s === 'error')     return 'border-red-400 bg-red-500/5';
  if (s === 'uploading') return 'border-teal-300 bg-teal-400/5';
  return 'border-gray-300 dark:border-gray-600 hover:border-teal-400';
}

export default function AdminMigrationsPage() {
  const [companies, setCompanies]   = useState<Company[]>([]);
  const [loadingCo, setLoadingCo]   = useState(true);
  const [companyId, setCompanyId]   = useState('');
  const [source, setSource]         = useState<Source>('xero');
  const [zones, setZones]           = useState<Record<FileType, ZoneState>>({
    accounts: { ...BLANK }, customers: { ...BLANK }, suppliers: { ...BLANK },
  });
  const [executing, setExecuting]   = useState(false);
  const [result, setResult]         = useState<ExecResult | null>(null);
  const [execErr, setExecErr]       = useState('');

  const refs = {
    accounts:  useRef<HTMLInputElement>(null),
    customers: useRef<HTMLInputElement>(null),
    suppliers: useRef<HTMLInputElement>(null),
  };

  const patch = (t: FileType, p: Partial<ZoneState>) =>
    setZones(prev => ({ ...prev, [t]: { ...prev[t], ...p } }));

  const loadCompanies = useCallback(async () => {
    setLoadingCo(true);
    try {
      const res  = await apiFetch('/api/admin/companies?limit=200&sort_by=name&sort_dir=asc');
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Failed');
      const items: Company[] = (json.data?.items ?? []).map((c: Company) =>
        ({ id: c.id, name: c.name, trading_name: c.trading_name }));
      setCompanies(items);
      if (items.length > 0 && items[0]) setCompanyId(items[0].id);
    } catch { /* error state handled by empty list */ } finally { setLoadingCo(false); }
  }, []);

  useEffect(() => { loadCompanies(); }, [loadCompanies]);

  // Reset zones when source changes
  useEffect(() => {
    setZones({ accounts: { ...BLANK }, customers: { ...BLANK }, suppliers: { ...BLANK } });
    setResult(null);
    setExecErr('');
  }, [source]);

  const handleFile = async (file: File, type: FileType) => {
    if (!companyId) return;
    patch(type, { status: 'uploading', error: '', count: 0, parsed: [] });
    try {
      const fd = new FormData();
      fd.append('file', file);
      fd.append('source', source);
      fd.append('fileType', type);
      const res  = await apiFetch(`/api/accounting/migration-parse?companyId=${companyId}`, { method: 'POST', body: fd });
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Parse failed');
      patch(type, { status: 'parsed', count: json.data?.count ?? 0, parsed: json.data?.parsed ?? [] });
    } catch (err) {
      patch(type, { status: 'error', error: err instanceof Error ? err.message : 'Upload failed' });
    }
  };

  const handleExecute = async () => {
    if (!companyId) return;
    setExecuting(true); setExecErr(''); setResult(null);
    try {
      const res  = await apiFetch(`/api/accounting/migration-execute?companyId=${companyId}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ source, accounts: zones.accounts.parsed, customers: zones.customers.parsed, suppliers: zones.suppliers.parsed }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Migration failed');
      setResult(json.data as ExecResult);
    } catch (err) {
      setExecErr(err instanceof Error ? err.message : 'Migration failed');
    } finally { setExecuting(false); }
  };

  const anyParsed  = Object.values(zones).some(z => z.status === 'parsed');
  const totalCount = Object.values(zones).reduce((s, z) => s + z.count, 0);
  const companyName = companies.find(c => c.id === companyId);

  const selectCls = 'w-full text-sm border border-gray-300 dark:border-gray-600 rounded-lg px-3 py-2 bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:ring-2 focus:ring-teal-500 focus:border-transparent';

  return (
    <AdminLayout title="Data Migration">
      <div className="max-w-3xl mx-auto space-y-5">

        {/* Header */}
        <div className="flex items-center gap-3">
          <div className="p-2 bg-teal-500/10 rounded-lg">
            <Database className="w-5 h-5 text-teal-600 dark:text-teal-400" />
          </div>
          <div>
            <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Data Migration</h1>
            <p className="text-sm text-gray-500 dark:text-gray-400 mt-0.5">
              Upload CSV files to migrate data into any company account.
            </p>
          </div>
        </div>

        {/* Step 1 — Company + Source */}
        <div className="bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl p-5 space-y-4">
          <p className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wide">1. Target &amp; Source</p>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-medium text-gray-600 dark:text-gray-400 mb-1">Company</label>
              {loadingCo ? (
                <div className="flex items-center gap-2 text-sm text-gray-400"><Loader2 className="w-4 h-4 animate-spin" /> Loading&hellip;</div>
              ) : (
                <select value={companyId} onChange={e => setCompanyId(e.target.value)} className={selectCls}>
                  {!companies.length && <option value="">No companies found</option>}
                  {companies.map(c => <option key={c.id} value={c.id}>{c.trading_name ?? c.name}</option>)}
                </select>
              )}
            </div>
            <div>
              <label className="block text-xs font-medium text-gray-600 dark:text-gray-400 mb-1">Source System</label>
              <select value={source} onChange={e => setSource(e.target.value as Source)} className={selectCls}>
                {SOURCES.map(s => <option key={s.value} value={s.value}>{s.label}</option>)}
              </select>
            </div>
          </div>
        </div>

        {/* Step 2 — Upload zones */}
        <div className="bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl p-5 space-y-3">
          <p className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wide">2. Upload CSV Files</p>
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
            {ZONES.map(({ type, label }) => {
              const z = zones[type];
              return (
                <div key={type}>
                  <input ref={refs[type]} type="file" accept=".csv,.xlsx" className="hidden"
                    onChange={e => { const f = e.target.files?.[0]; if (f) handleFile(f, type); e.target.value = ''; }} />
                  <button type="button" disabled={!companyId || z.status === 'uploading'}
                    onClick={() => refs[type].current?.click()}
                    className={`w-full flex flex-col items-center gap-2 p-4 border-2 border-dashed rounded-xl transition-colors text-center disabled:opacity-50 disabled:cursor-not-allowed ${zoneCls(z.status)}`}>
                    {z.status === 'uploading' ? <Loader2 className="w-5 h-5 animate-spin text-teal-500" />
                      : z.status === 'parsed'  ? <CheckCircle2 className="w-5 h-5 text-teal-500" />
                      : z.status === 'error'   ? <AlertCircle className="w-5 h-5 text-red-500" />
                      : <Upload className="w-5 h-5 text-gray-400" />}
                    <span className="text-sm font-medium text-gray-700 dark:text-gray-300">{label}</span>
                    {z.status === 'idle'      && <span className="text-xs text-gray-400">.csv / .xlsx</span>}
                    {z.status === 'uploading' && <span className="text-xs text-teal-500">Parsing&hellip;</span>}
                    {z.status === 'parsed'    && <span className="text-xs font-semibold text-teal-600 dark:text-teal-400">{z.count} records</span>}
                    {z.status === 'error'     && <span className="text-xs text-red-500 line-clamp-2">{z.error}</span>}
                  </button>
                </div>
              );
            })}
          </div>
          <p className="text-xs text-gray-400">Files are parsed client-side — no data saved until you execute below.</p>
        </div>

        {/* Step 3 — Summary + Execute */}
        {anyParsed && (
          <div className="bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl p-5 space-y-4">
            <p className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wide">3. Review &amp; Execute</p>
            <div className="grid grid-cols-3 gap-3 text-center">
              {ZONES.map(({ type, label }) => (
                <div key={type} className="bg-gray-50 dark:bg-gray-700/40 rounded-lg py-3">
                  <p className="text-2xl font-bold text-gray-900 dark:text-white">{zones[type].count}</p>
                  <p className="text-xs text-gray-500 dark:text-gray-400 mt-0.5">{label}</p>
                </div>
              ))}
            </div>
            <p className="text-sm text-gray-600 dark:text-gray-400">
              <strong className="text-gray-900 dark:text-white">{totalCount} records</strong> will be imported into{' '}
              <strong className="text-gray-900 dark:text-white">{companyName?.trading_name ?? companyName?.name ?? 'selected company'}</strong>.
            </p>
            {execErr && (
              <div className="flex items-center gap-2 text-sm text-red-600 dark:text-red-400 bg-red-50 dark:bg-red-900/20 rounded-lg p-3">
                <AlertCircle className="w-4 h-4 flex-shrink-0" />{execErr}
              </div>
            )}
            <button type="button" onClick={handleExecute} disabled={executing}
              className="flex items-center gap-2 px-5 py-2.5 bg-teal-600 hover:bg-teal-700 disabled:opacity-50 disabled:cursor-not-allowed text-white text-sm font-medium rounded-lg transition-colors">
              {executing ? <Loader2 className="w-4 h-4 animate-spin" /> : <Play className="w-4 h-4" />}
              {executing ? 'Running\u2026' : 'Execute Migration'}
            </button>
          </div>
        )}

        {/* Results */}
        {result && (
          <div className="bg-teal-50 dark:bg-teal-900/20 border border-teal-200 dark:border-teal-800 rounded-xl p-5 space-y-3">
            <div className="flex items-center gap-2">
              <CheckCircle2 className="w-5 h-5 text-teal-600 dark:text-teal-400" />
              <p className="text-sm font-semibold text-teal-900 dark:text-teal-200">Migration complete</p>
            </div>
            <div className="grid grid-cols-3 gap-3 text-center text-sm">
              {ZONES.map(({ type, label }) => {
                const r = result[type];
                if (!r) return <div key={type} className="bg-white dark:bg-gray-800 rounded-lg py-3 px-2 text-gray-400 text-xs">{label}<br />not imported</div>;
                return (
                  <div key={type} className="bg-white dark:bg-gray-800 rounded-lg py-3 px-2">
                    <p className="font-medium text-gray-900 dark:text-white">{label}</p>
                    <p className="text-teal-600 dark:text-teal-400 mt-1">{r.succeeded} imported</p>
                    {r.failed > 0 && <p className="text-red-500 text-xs">{r.failed} failed</p>}
                  </div>
                );
              })}
            </div>
          </div>
        )}

      </div>
    </AdminLayout>
  );
}

