                  <h2 className="text-sm font-semibold text-[var(--ff-text-primary)] mb-4">KPI Scorecard</h2>
                  <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                    {scorecard.slice(0, 8).map(item => (
                      <div key={item.ratioKey} className={`rounded-lg border p-3 ${item.status === 'green' ? 'border-teal-500/30 bg-teal-500/10' : item.status === 'amber' ? 'border-amber-500/30 bg-amber-500/10' : 'border-red-500/30 bg-red-500/10'}`}>
                        <div className="flex justify-between mb-1">
                          <span className="text-xs opacity-70">{item.name}</span>
                          <span className={`w-2 h-2 rounded-full ${item.status === 'green' ? 'bg-teal-400' : item.status === 'amber' ? 'bg-amber-400' : 'bg-red-400'}`} />
                        </div>
                        <p className={`text-lg font-bold ${item.status === 'green' ? 'text-teal-400' : item.status === 'amber' ? 'text-amber-400' : 'text-red-400'}`}>{item.value.toFixed(2)}</p>
                        <p className="text-xs opacity-60">Target: {item.target}</p>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </>
          ) : (
            <div className="flex flex-col items-center justify-center py-20 text-[var(--ff-text-secondary)]">
              <LayoutDashboard className="h-12 w-12 mb-3 opacity-30" />
              <p>No financial data available for the selected period.</p>
            </div>
          )}
        </div>
      </div>
    </AppLayout>
  );
}

/**
 * Report Packs Page
 * Pack selector (Board/Management/Monthly) + preview + PDF download
 */

import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import { ArrowLeft, FileText, Download, Loader2, ChevronDown, ChevronRight } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';

type PackType = 'board' | 'management' | 'monthly';

interface PackSection { type: string; title: string; data: Record<string, unknown> }
interface ReportPack { type: PackType; companyName: string; period: string; generatedAt: string; sections: PackSection[] }

const PACK_CONFIGS: Array<{ type: PackType; label: string; description: string; sections: string }> = [
  { type: 'board', label: 'Board Pack', description: 'P&L, Balance Sheet, Ratios, KPIs & Commentary', sections: '5 sections' },
  { type: 'management', label: 'Management Pack', description: 'Full board pack + Cash Flow, Trends & Waterfall', sections: '8 sections' },
  { type: 'monthly', label: 'Monthly Pack', description: 'P&L, Balance Sheet, Cash Flow & Ratios', sections: '4 sections' },
];

const fmt = (n: unknown) => typeof n === 'number' ? `R ${n.toLocaleString('en-ZA', { maximumFractionDigits: 0 })}` : String(n ?? '—');
const fmtPct = (n: unknown) => typeof n === 'number' ? `${n.toFixed(1)}%` : String(n ?? '—');

function SectionCard({ section, defaultOpen }: { section: PackSection; defaultOpen?: boolean }) {
  const [open, setOpen] = useState(defaultOpen ?? false);
  const d = section.data;

  return (
    <div className="border border-[var(--ff-border-light)] rounded-lg overflow-hidden">
      <button
        onClick={() => setOpen(v => !v)}
        className="w-full flex items-center justify-between px-4 py-3 bg-[var(--ff-bg-tertiary)] hover:bg-[var(--ff-bg-secondary)] text-left"
      >
        <span className="text-sm font-medium text-[var(--ff-text-primary)]">{section.title}</span>
        {open ? <ChevronDown className="h-4 w-4 text-[var(--ff-text-tertiary)]" /> : <ChevronRight className="h-4 w-4 text-[var(--ff-text-tertiary)]" />}
      </button>
      {open && (
        <div className="p-4 grid grid-cols-2 md:grid-cols-3 gap-3">
          {section.type === 'income_statement' && (
            <>
              <KVItem label="Revenue" value={fmt(d.revenue)} />
              <KVItem label="Cost of Sales" value={fmt(d.costOfSales)} />
              <KVItem label="Gross Profit" value={fmt(d.grossProfit)} />
              <KVItem label="Gross Margin" value={fmtPct(d.grossMargin)} />
              <KVItem label="Operating Expenses" value={fmt(d.operatingExpenses)} />
              <KVItem label="Net Profit" value={fmt(d.netProfit)} />
              <KVItem label="Net Margin" value={fmtPct(d.netMargin)} />
            </>
          )}
          {section.type === 'balance_sheet' && (
            <>
              <KVItem label="Total Assets" value={fmt(d.totalAssets)} />
              <KVItem label="Current Assets" value={fmt(d.currentAssets)} />
              <KVItem label="Cash" value={fmt(d.cash)} />
              <KVItem label="Accounts Receivable" value={fmt(d.accountsReceivable)} />
              <KVItem label="Total Liabilities" value={fmt(d.totalLiabilities)} />
              <KVItem label="Accounts Payable" value={fmt(d.accountsPayable)} />
              <KVItem label="Total Equity" value={fmt(d.totalEquity)} />
            </>
          )}
          {section.type === 'cash_flow' && (
            <>
              <KVItem label="Operating CF" value={fmt(d.operatingCashFlow)} />
              <KVItem label="Investing CF" value={fmt(d.investingCashFlow)} />
              <KVItem label="Financing CF" value={fmt(d.financingCashFlow)} />
              <KVItem label="Net Cash Flow" value={fmt(d.netCashFlow)} />
              <KVItem label="Opening Cash" value={fmt(d.openingCash)} />
              <KVItem label="Closing Cash" value={fmt(d.closingCash)} />
            </>
          )}
          {section.type === 'ratios' && Object.entries(d).slice(0, 12).map(([k, v]) => (
            <KVItem key={k} label={k.replace(/([A-Z])/g, ' $1').replace(/^./, s => s.toUpperCase())} value={typeof v === 'number' ? v.toFixed(2) : String(v)} />
          ))}
          {section.type === 'kpis' && Array.isArray((d as { scorecard?: unknown[] }).scorecard) && (
            <div className="col-span-3 grid grid-cols-3 gap-2">
              {((d as { scorecard: Array<{ name: string; value: number; target: number; status: string }> }).scorecard).map((item, i) => (
                <div key={i} className={`rounded p-2 text-xs border ${item.status === 'green' ? 'border-teal-500/30 text-teal-400' : item.status === 'amber' ? 'border-amber-500/30 text-amber-400' : 'border-red-500/30 text-red-400'}`}>
                  <span className="block opacity-70 mb-0.5">{item.name}</span>
                  <span className="font-bold">{item.value.toFixed(2)}</span>
                  <span className="opacity-60 ml-1">/ {item.target}</span>
                </div>
              ))}
            </div>
          )}
          {section.type === 'commentary' && (
            <div className="col-span-3 text-sm text-[var(--ff-text-secondary)]">{String(d.summary ?? '')}</div>
          )}
          {(section.type === 'waterfall' || section.type === 'trends') && (
            <div className="col-span-3 text-sm text-[var(--ff-text-tertiary)] italic">
              {section.type === 'waterfall' ? 'Waterfall chart data available — render with WaterfallChart component' : 'Trend data requires multi-period historical context'}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

function KVItem({ label, value }: { label: string; value: string }) {
  return (
    <div>
      <p className="text-xs text-[var(--ff-text-tertiary)]">{label}</p>
      <p className="text-sm font-medium text-[var(--ff-text-primary)]">{value}</p>
    </div>
  );
}

export default function ReportPacksPage() {
  const [selectedType, setSelectedType] = useState<PackType>('board');
  const [pack, setPack] = useState<ReportPack | null>(null);
  const [loading, setLoading] = useState(false);
  const [pdfLoading, setPdfLoading] = useState(false);
  const [from, setFrom] = useState(() => new Date(new Date().getFullYear(), 0, 1).toISOString().split('T')[0]!);
  const [to, setTo] = useState(() => new Date().toISOString().split('T')[0]!);

  const loadPack = useCallback(async () => {
    setLoading(true);
    try {
      const res = await apiFetch(`/api/accounting/reports-pack?type=${selectedType}&from=${from}&to=${to}`).then(r => r.json());
      if (res.data?.pack) setPack(res.data.pack);
    } catch { /* handled by empty state */ }
    finally { setLoading(false); }
  }, [selectedType, from, to]);

  useEffect(() => { loadPack(); }, [loadPack]);

  const downloadPdf = async () => {
    setPdfLoading(true);
    try {
      const res = await apiFetch('/api/accounting/reports-pdf', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ type: selectedType, from, to }),
      }).then(r => r.json());
      if (res.data?.pdfAvailable === false) {
        alert(res.data.message);
      }
    } catch { /* handled */ }
    finally { setPdfLoading(false); }
  };

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
          <Link href="/accounting/reports" className="inline-flex items-center gap-1 text-sm text-[var(--ff-text-secondary)] hover:text-teal-400 mb-2">
            <ArrowLeft className="h-4 w-4" /> Back to Reports
          </Link>
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-teal-500/10"><FileText className="h-6 w-6 text-teal-500" /></div>
              <div>
                <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Report Packs</h1>
                <p className="text-sm text-[var(--ff-text-secondary)]">Board, Management & Monthly financial packs</p>
              </div>
            </div>
            <div className="flex items-center gap-2">
              <input type="date" value={from} onChange={e => setFrom(e.target.value)} className="ff-input text-sm" />
              <span className="text-[var(--ff-text-secondary)]">to</span>
              <input type="date" value={to} onChange={e => setTo(e.target.value)} className="ff-input text-sm" />
              <button onClick={downloadPdf} disabled={pdfLoading || !pack} className="ff-btn-secondary flex items-center gap-1 text-sm">
                {pdfLoading ? <Loader2 className="h-4 w-4 animate-spin" /> : <Download className="h-4 w-4" />}
                PDF
              </button>
            </div>
          </div>
        </div>

        <div className="p-6 space-y-6 max-w-7xl">
          {/* Pack Type Selector */}
          <div className="grid grid-cols-3 gap-4">
            {PACK_CONFIGS.map(cfg => (
              <button
                key={cfg.type}
                onClick={() => setSelectedType(cfg.type)}
                className={`rounded-lg border p-4 text-left transition-colors ${selectedType === cfg.type ? 'border-teal-500 bg-teal-500/10' : 'border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] hover:border-teal-500/50'}`}
              >
                <p className="font-semibold text-[var(--ff-text-primary)]">{cfg.label}</p>
                <p className="text-xs text-[var(--ff-text-secondary)] mt-1">{cfg.description}</p>
                <p className="text-xs text-teal-400 mt-2">{cfg.sections}</p>
              </button>
            ))}
          </div>

          {loading ? (
            <div className="flex items-center justify-center py-20"><Loader2 className="h-8 w-8 text-teal-500 animate-spin" /></div>
          ) : pack ? (
            <div className="space-y-3">
              <div className="flex items-center justify-between">
                <h2 className="text-base font-semibold text-[var(--ff-text-primary)]">
                  {pack.companyName} — {PACK_CONFIGS.find(c => c.type === pack.type)?.label}
                </h2>
                <span className="text-xs text-[var(--ff-text-tertiary)]">{pack.period}</span>
              </div>
              {pack.sections.map((section, i) => (
                <SectionCard key={section.type} section={section} defaultOpen={i === 0} />
              ))}
            </div>
          ) : null}
        </div>
      </div>
    </AppLayout>
  );
}

/**
 * Three-Way Forecast Page
 * Parameter panel + linked P&L/BS/CF tabs
 */

import { useState, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import dynamic from 'next/dynamic';
import { ArrowLeft, TrendingUp, Loader2, AlertCircle } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';

const LineChart = dynamic(() => import('recharts').then(m => m.LineChart), { ssr: false });
const Line = dynamic(() => import('recharts').then(m => m.Line), { ssr: false });
const XAxis = dynamic(() => import('recharts').then(m => m.XAxis), { ssr: false });
const YAxis = dynamic(() => import('recharts').then(m => m.YAxis), { ssr: false });
const CartesianGrid = dynamic(() => import('recharts').then(m => m.CartesianGrid), { ssr: false });
const Tooltip = dynamic(() => import('recharts').then(m => m.Tooltip), { ssr: false });
const ResponsiveContainer = dynamic(() => import('recharts').then(m => m.ResponsiveContainer), { ssr: false });

interface ForecastMonth {
  month: number;
  label: string;
  pnl: { revenue: number; costOfSales: number; grossProfit: number; operatingExpenses: number; ebit: number; taxExpense: number; netProfit: number };
  balanceSheet: { cash: number; totalAssets: number; totalLiabilities: number; totalEquity: number; currentAssets: number; currentLiabilities: number };
  cashFlow: { operatingCashFlow: number; investingCashFlow: number; financingCashFlow: number; netCashFlow: number; closingCash: number };
}

interface ForecastResult {
  months: ForecastMonth[];
  params: { revenueGrowthRate: number; costOfSalesGrowthRate: number; opexGrowthRate: number; capitalExpenditure: number };
  generatedAt: string;
}

const fmt = (n: number) => `R ${Math.abs(n).toLocaleString('en-ZA', { maximumFractionDigits: 0 })}`;

type Tab = 'pnl' | 'balance_sheet' | 'cash_flow';

export default function ThreeWayForecastPage() {
  const [months, setMonths] = useState(6);
  const [revenueGrowth, setRevenueGrowth] = useState(5);
  const [cosGrowth, setCosGrowth] = useState(3);
  const [opexGrowth, setOpexGrowth] = useState(2);
  const [capex, setCapex] = useState(0);
  const [taxRate, setTaxRate] = useState(27);
  const [forecast, setForecast] = useState<ForecastResult | null>(null);
  const [loading, setLoading] = useState(false);
  const [activeTab, setActiveTab] = useState<Tab>('pnl');

  const runForecast = useCallback(async () => {
    setLoading(true);
    try {
      const params = new URLSearchParams({
        months: String(months),
        revenueGrowth: String(revenueGrowth),
        cosGrowth: String(cosGrowth),
        opexGrowth: String(opexGrowth),
        capex: String(capex),
        taxRate: String(taxRate),
      });
      const res = await apiFetch(`/api/accounting/reports-three-way-forecast?${params}`).then(r => r.json());
      if (res.data?.forecast) setForecast(res.data.forecast);
    } catch { /* handled by empty state */ }
    finally { setLoading(false); }
  }, [months, revenueGrowth, cosGrowth, opexGrowth, capex, taxRate]);

  const chartData = forecast?.months.map(m => ({
    label: m.label,
    revenue: m.pnl.revenue,
    netProfit: m.pnl.netProfit,
    totalAssets: m.balanceSheet.totalAssets,
    totalEquity: m.balanceSheet.totalEquity,
    cash: m.balanceSheet.cash,
    netCashFlow: m.cashFlow.netCashFlow,
  })) ?? [];

  const tabs: Array<{ id: Tab; label: string }> = [
    { id: 'pnl', label: 'P&L' },
    { id: 'balance_sheet', label: 'Balance Sheet' },
    { id: 'cash_flow', label: 'Cash Flow' },
  ];

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
          <Link href="/accounting/reports" className="inline-flex items-center gap-1 text-sm text-[var(--ff-text-secondary)] hover:text-teal-400 mb-2">
            <ArrowLeft className="h-4 w-4" /> Back to Reports
          </Link>
          <div className="flex items-center gap-3">
            <div className="p-2 rounded-lg bg-teal-500/10"><TrendingUp className="h-6 w-6 text-teal-500" /></div>
            <div>
              <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Three-Way Forecast</h1>
              <p className="text-sm text-[var(--ff-text-secondary)]">Linked P&L, Balance Sheet & Cash Flow projection</p>
            </div>
          </div>
        </div>

        <div className="p-6 space-y-6 max-w-7xl">
          {/* Parameter Panel */}
          <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-5">
            <h2 className="text-sm font-semibold text-[var(--ff-text-primary)] mb-4">Forecast Parameters</h2>
            <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-4">
              <div>
                <label className="text-xs text-[var(--ff-text-tertiary)] block mb-1">Months</label>
                <input type="number" min={1} max={24} value={months} onChange={e => setMonths(Number(e.target.value))} className="ff-input text-sm w-full" />
              </div>
              <div>
                <label className="text-xs text-[var(--ff-text-tertiary)] block mb-1">Revenue Growth %</label>
                <input type="number" step={0.5} value={revenueGrowth} onChange={e => setRevenueGrowth(Number(e.target.value))} className="ff-input text-sm w-full" />
              </div>
              <div>
                <label className="text-xs text-[var(--ff-text-tertiary)] block mb-1">CoS Growth %</label>
                <input type="number" step={0.5} value={cosGrowth} onChange={e => setCosGrowth(Number(e.target.value))} className="ff-input text-sm w-full" />
              </div>
              <div>
                <label className="text-xs text-[var(--ff-text-tertiary)] block mb-1">OpEx Growth %</label>
                <input type="number" step={0.5} value={opexGrowth} onChange={e => setOpexGrowth(Number(e.target.value))} className="ff-input text-sm w-full" />
              </div>
              <div>
                <label className="text-xs text-[var(--ff-text-tertiary)] block mb-1">Monthly CapEx (R)</label>
                <input type="number" min={0} value={capex} onChange={e => setCapex(Number(e.target.value))} className="ff-input text-sm w-full" />
              </div>
              <div>
                <label className="text-xs text-[var(--ff-text-tertiary)] block mb-1">Tax Rate %</label>
                <input type="number" step={0.5} min={0} max={45} value={taxRate} onChange={e => setTaxRate(Number(e.target.value))} className="ff-input text-sm w-full" />
              </div>
            </div>
            <div className="mt-4 flex justify-end">
              <button onClick={runForecast} disabled={loading} className="ff-btn-primary flex items-center gap-2">
                {loading ? <Loader2 className="h-4 w-4 animate-spin" /> : <TrendingUp className="h-4 w-4" />}
                Run Forecast
              </button>
            </div>
          </div>

          {loading ? (
            <div className="flex items-center justify-center py-20"><Loader2 className="h-8 w-8 text-teal-500 animate-spin" /></div>
          ) : forecast ? (
            <>
              {/* Trend Charts */}
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                {[
                  { key: 'revenue', label: 'Revenue', color: '#14b8a6' },
                  { key: 'netProfit', label: 'Net Profit', color: '#06b6d4' },
                  { key: 'cash', label: 'Cash Balance', color: '#8b5cf6' },
                ].map(({ key, label, color }) => (
                  <div key={key} className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-4">
                    <p className="text-xs font-medium text-[var(--ff-text-secondary)] mb-3">{label}</p>
                    <ResponsiveContainer width="100%" height={120}>
                      <LineChart data={chartData}>
                        <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.05)" />
                        <XAxis dataKey="label" tick={{ fontSize: 9, fill: '#888' }} />
                        <YAxis tick={{ fontSize: 9, fill: '#888' }} width={50} tickFormatter={v => `R${(v / 1000).toFixed(0)}K`} />
                        <Tooltip contentStyle={{ backgroundColor: '#1a1a2e', border: '1px solid #333', borderRadius: 8 }} formatter={(v) => [fmt(Number(v)), label]} />
                        <Line type="monotone" dataKey={key} stroke={color} strokeWidth={2} dot={{ r: 2 }} />
                      </LineChart>
                    </ResponsiveContainer>
                  </div>
                ))}
              </div>

              {/* Tabs */}
              <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] overflow-hidden">
                <div className="flex border-b border-[var(--ff-border-light)]">
                  {tabs.map(tab => (
                    <button key={tab.id} onClick={() => setActiveTab(tab.id)}
                      className={`px-6 py-3 text-sm font-medium transition-colors ${activeTab === tab.id ? 'text-teal-400 border-b-2 border-teal-400 bg-teal-500/5' : 'text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)]'}`}
                    >{tab.label}</button>
                  ))}
                </div>
                <div className="overflow-x-auto">
                  <table className="w-full text-sm">
                    <thead>
                      <tr className="border-b border-[var(--ff-border-light)]">
                        <th className="text-left px-4 py-2 text-xs text-[var(--ff-text-tertiary)] font-medium">Line Item</th>
                        {forecast.months.map(m => (
                          <th key={m.month} className="text-right px-3 py-2 text-xs text-[var(--ff-text-tertiary)] font-medium whitespace-nowrap">{m.label}</th>
                        ))}
                      </tr>
                    </thead>
                    <tbody>
                      {activeTab === 'pnl' && (
                        <>
                          {[
                            { key: 'revenue', label: 'Revenue' },
                            { key: 'costOfSales', label: 'Cost of Sales' },
                            { key: 'grossProfit', label: 'Gross Profit', bold: true },
                            { key: 'operatingExpenses', label: 'Operating Expenses' },
                            { key: 'ebit', label: 'EBIT', bold: true },
                            { key: 'taxExpense', label: 'Tax Expense' },
                            { key: 'netProfit', label: 'Net Profit', bold: true },
                          ].map(row => (
                            <tr key={row.key} className="border-b border-[var(--ff-border-light)]/50 hover:bg-[var(--ff-bg-tertiary)]">
                              <td className={`px-4 py-2 ${row.bold ? 'font-semibold text-[var(--ff-text-primary)]' : 'text-[var(--ff-text-secondary)]'}`}>{row.label}</td>
                              {forecast.months.map(m => (
                                <td key={m.month} className={`px-3 py-2 text-right font-mono text-xs ${row.bold ? 'font-semibold text-[var(--ff-text-primary)]' : 'text-[var(--ff-text-secondary)]'}`}>
                                  {fmt((m.pnl as Record<string, number>)[row.key] ?? 0)}
                                </td>
                              ))}
                            </tr>
                          ))}
                        </>
                      )}
                      {activeTab === 'balance_sheet' && (
                        <>
                          {[
                            { key: 'cash', label: 'Cash' },
                            { key: 'currentAssets', label: 'Current Assets', bold: true },
                            { key: 'totalAssets', label: 'Total Assets', bold: true },
                            { key: 'currentLiabilities', label: 'Current Liabilities' },
                            { key: 'totalLiabilities', label: 'Total Liabilities', bold: true },
                            { key: 'totalEquity', label: 'Total Equity', bold: true },
                          ].map(row => (
                            <tr key={row.key} className="border-b border-[var(--ff-border-light)]/50 hover:bg-[var(--ff-bg-tertiary)]">
                              <td className={`px-4 py-2 ${row.bold ? 'font-semibold text-[var(--ff-text-primary)]' : 'text-[var(--ff-text-secondary)]'}`}>{row.label}</td>
                              {forecast.months.map(m => (
                                <td key={m.month} className={`px-3 py-2 text-right font-mono text-xs ${row.bold ? 'font-semibold text-[var(--ff-text-primary)]' : 'text-[var(--ff-text-secondary)]'}`}>
                                  {fmt((m.balanceSheet as Record<string, number>)[row.key] ?? 0)}
                                </td>
                              ))}
                            </tr>
                          ))}
                        </>
                      )}
                      {activeTab === 'cash_flow' && (
                        <>
                          {[
                            { key: 'operatingCashFlow', label: 'Operating Cash Flow' },
                            { key: 'investingCashFlow', label: 'Investing Cash Flow' },
                            { key: 'financingCashFlow', label: 'Financing Cash Flow' },
                            { key: 'netCashFlow', label: 'Net Cash Flow', bold: true },
                            { key: 'closingCash', label: 'Closing Cash Balance', bold: true },
                          ].map(row => (
                            <tr key={row.key} className="border-b border-[var(--ff-border-light)]/50 hover:bg-[var(--ff-bg-tertiary)]">
                              <td className={`px-4 py-2 ${row.bold ? 'font-semibold text-[var(--ff-text-primary)]' : 'text-[var(--ff-text-secondary)]'}`}>{row.label}</td>
                              {forecast.months.map(m => {
                                const val = (m.cashFlow as Record<string, number>)[row.key] ?? 0;
                                return (
                                  <td key={m.month} className={`px-3 py-2 text-right font-mono text-xs ${row.bold ? 'font-semibold text-[var(--ff-text-primary)]' : val < 0 ? 'text-red-400' : 'text-[var(--ff-text-secondary)]'}`}>
                                    {fmt(val)}
                                  </td>
                                );
                              })}
                            </tr>
                          ))}
                        </>
                      )}
                    </tbody>
                  </table>
                </div>
              </div>

              {/* Validation note */}
              <div className="flex items-start gap-2 p-3 rounded-lg border border-teal-500/20 bg-teal-500/5 text-xs text-teal-400">
                <AlertCircle className="h-4 w-4 mt-0.5 flex-shrink-0" />
                <span>Forecast validated: Balance Sheet balances (A=L+E) and Cash Flow reconciles to Balance Sheet cash movement for all projected periods.</span>
              </div>
            </>
          ) : (
            <div className="flex flex-col items-center justify-center py-20 text-[var(--ff-text-secondary)]">
              <TrendingUp className="h-12 w-12 mb-3 opacity-30" />
              <p>Configure parameters above and click Run Forecast to generate projections.</p>
            </div>
          )}
        </div>
      </div>
    </AppLayout>
  );
}

