export const TEAL = { r: 20, g: 184, b: 166 }; // #14b8a6

// ── Company Details ────────────────────────────────────────────────────────────

export interface CompanyDetails {
  name: string;
  address: string;
  phone: string;
  email: string;
  vatNumber: string;
  bankName: string;
  bankAccountName: string;
  bankAccountNumber: string;
  bankBranchCode: string;
  bankReference: string;
}

const COMPANY_SETTINGS_KEYS = [
  'company_name', 'company_address', 'company_phone', 'company_email',
  'company_vat_number', 'bank_name', 'bank_account_name',
  'bank_account_number', 'bank_branch_code',
] as const;

async function getCompanyDetailsFromSettings(): Promise<CompanyDetails> {
  try {
    const rows = await sql`
      SELECT key, value FROM app_settings
      WHERE key = ANY(${COMPANY_SETTINGS_KEYS as unknown as string[]})
    `;
    const settings: Record<string, string> = {};
    for (const row of rows) {
      settings[row.key as string] = String(row.value ?? '');
    }
    return {
      name: settings.company_name || 'Company Name Not Set',
      address: settings.company_address || '',
      phone: settings.company_phone || '',
      email: settings.company_email || '',
      vatNumber: settings.company_vat_number || '',
      bankName: settings.bank_name || '',
      bankAccountName: settings.bank_account_name || '',
      bankAccountNumber: settings.bank_account_number || '',
      bankBranchCode: settings.bank_branch_code || '',
      bankReference: '',
    };
  } catch {
    log.warn('Failed to load company settings for PDF, using fallbacks', {}, 'pdfShared');
    return {
      name: 'Company Name Not Set',
      address: '', phone: '', email: '', vatNumber: '',
      bankName: '', bankAccountName: '', bankAccountNumber: '',
      bankBranchCode: '', bankReference: '',
    };
  }
}

/**
 * Load company details from the companies table, with fallback to app_settings.
 */
export async function getCompanyDetailsFromCompany(companyId: string): Promise<CompanyDetails> {
  try {
    const rows = await sql`
      SELECT name, address_line1, address_line2, city, province, postal_code,
             phone, email, vat_number,
             bank_name, bank_account_number, bank_branch_code
      FROM companies WHERE id = ${companyId}::UUID
    `;
    if (rows.length > 0) {
      const c = rows[0] as Row;
      const addressParts = [c.address_line1, c.address_line2, c.city, c.province, c.postal_code].filter(Boolean).map(String);
      return {
        name: c.name ? String(c.name) : 'Company Name Not Set',
        address: addressParts.join(', '),
        phone: c.phone ? String(c.phone) : '',
        email: c.email ? String(c.email) : '',
        vatNumber: c.vat_number ? String(c.vat_number) : '',
        bankName: c.bank_name ? String(c.bank_name) : '',
        bankAccountName: c.name ? String(c.name) : '',
        bankAccountNumber: c.bank_account_number ? String(c.bank_account_number) : '',
        bankBranchCode: c.bank_branch_code ? String(c.bank_branch_code) : '',
        bankReference: '',
      };
    }
  } catch {
    log.warn('Failed to load company from companies table, trying app_settings', {}, 'pdfShared');
  }
  return getCompanyDetailsFromSettings();
}

// ── Page footer renderer ──────────────────────────────────────────────────────

/**
 * Render IsaFlow teal footer lines on every page of a jsPDF document.
 */
export function renderPageFooters(
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  doc: any,
  pageW: number,
  pageH: number,
  margin: number,
): void {
  const totalPages = (doc as { internal: { getNumberOfPages: () => number } })
    .internal.getNumberOfPages();

  for (let i = 1; i <= totalPages; i++) {
    doc.setPage(i);
    doc.setFontSize(7);
    doc.setFont('helvetica', 'normal');
    doc.setTextColor(150, 150, 150);

    doc.setDrawColor(TEAL.r, TEAL.g, TEAL.b);
    doc.setLineWidth(0.3);
    doc.line(margin, pageH - 12, pageW - margin, pageH - 12);

    doc.text(`Page ${i} of ${totalPages}`, pageW - margin, pageH - 7, { align: 'right' });
    doc.text('Generated by IsaFlow', margin, pageH - 7);
  }
}

/**
 * Invoice PDF Builder — generates Tax Invoice PDFs using jsPDF + jspdf-autotable.
 * Returns a Node.js Buffer suitable for API responses and email attachments.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { fmtZAR, fmtDate, TEAL, getCompanyDetailsFromCompany, renderPageFooters } from './pdfShared';

type Row = Record<string, unknown>;

interface InvoiceRow {
  invoice_number: string;
  invoice_date: string | Date;
  due_date: string | Date | null;
  billing_period_start: string | Date | null;
  billing_period_end: string | Date | null;
  client_name: string | null;
  client_address: string | null;
  client_contact: string | null;
  client_email: string | null;
  client_phone: string | null;
  client_vat: string | null;
  project_name: string | null;
  subtotal: unknown;
  tax_amount: unknown;
  total_amount: unknown;
  amount_paid: unknown;
  tax_rate: unknown;
  notes: string | null;
}


export async function generateInvoicePdf(companyId: string, invoiceId: string): Promise<Buffer> {
  const COMPANY = await getCompanyDetailsFromCompany(companyId);

  const invoiceRows = (await sql`
    SELECT ci.*,
           c.name AS client_name,
           c.email AS client_email,
           c.phone AS client_phone,
           c.vat_number AS client_vat,
           c.billing_address AS client_address,
           c.contact_person AS client_contact,
           p.name AS project_name
    FROM customer_invoices ci
    LEFT JOIN customers c ON c.id = COALESCE(ci.client_id, ci.customer_id)
    LEFT JOIN projects p ON p.id = ci.project_id
    WHERE ci.id = ${invoiceId}::UUID
  `) as Row[];

  if (invoiceRows.length === 0) throw new Error(`Invoice not found: ${invoiceId}`);
  const invoice = invoiceRows[0]!;

  const items = (await sql`
    SELECT * FROM customer_invoice_items
    WHERE invoice_id = ${invoiceId}::UUID
    ORDER BY created_at
  `) as Row[];

  log.info('Generating invoice PDF', {
    invoiceId,
    invoiceNumber: invoice.invoice_number,
    itemCount: items.length,
  }, 'invoicePdfBuilder');

  const [{ jsPDF }, { default: autoTable }] = await Promise.all([
    import('jspdf'),
    import('jspdf-autotable'),
  ]);

  const doc = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
  const PAGE_W = doc.internal.pageSize.getWidth();
  const PAGE_H = doc.internal.pageSize.getHeight();
  const MARGIN = 14;
  const CONTENT_W = PAGE_W - MARGIN * 2;

  // Header bar
  doc.setFillColor(TEAL.r, TEAL.g, TEAL.b);
  doc.rect(0, 0, PAGE_W, 28, 'F');

/**
 * Report Pack Service
 * Assembles ordered report sections for Board, Management, and Monthly packs.
 * Pure business logic — no database dependencies.
 */

import { calculateExtendedRatios, type FinancialData } from './reportingEngineService';
import { buildKPIScorecard, type KPITargetConfig } from './kpiScorecardService';
import { buildProfitWaterfall } from './waterfallDataService';

export interface ReportPackInput {
  companyName: string;
  period: string;
  revenue: number;
  costOfSales: number;
  operatingExpenses: number;
  netProfit: number;
  totalAssets: number;
  totalLiabilities: number;
  totalEquity: number;
  currentAssets: number;
  currentLiabilities: number;
  cash: number;
  accountsReceivable: number;
  accountsPayable: number;
  inventory: number;
  operatingCashFlow?: number;
  capitalExpenditure?: number;
}

export type PackType = 'board' | 'management' | 'monthly';

export interface PackSectionConfig {
  type: string;
  title: string;
}

export interface PackSection {
  type: string;
  title: string;
  data: Record<string, unknown>;
}

export interface ReportPack {
  type: PackType;
  companyName: string;
  period: string;
  generatedAt: string;
  sections: PackSection[];
}

const BOARD_SECTIONS: PackSectionConfig[] = [
  { type: 'income_statement', title: 'Income Statement' },
  { type: 'balance_sheet', title: 'Balance Sheet' },
  { type: 'ratios', title: 'Financial Ratios' },
  { type: 'kpis', title: 'KPI Scorecard' },
  { type: 'commentary', title: 'Commentary' },
];

const MANAGEMENT_SECTIONS: PackSectionConfig[] = [
  { type: 'income_statement', title: 'Income Statement' },
  { type: 'balance_sheet', title: 'Balance Sheet' },
  { type: 'cash_flow', title: 'Cash Flow' },
  { type: 'ratios', title: 'Financial Ratios' },
  { type: 'kpis', title: 'KPI Scorecard' },
  { type: 'waterfall', title: 'Profit Waterfall' },
  { type: 'trends', title: 'Trend Analysis' },
  { type: 'commentary', title: 'Commentary' },
];

const MONTHLY_SECTIONS: PackSectionConfig[] = [
  { type: 'income_statement', title: 'Income Statement' },
  { type: 'balance_sheet', title: 'Balance Sheet' },
  { type: 'cash_flow', title: 'Cash Flow' },
  { type: 'ratios', title: 'Financial Ratios' },
];

export function getPackTemplate(type: PackType): PackSectionConfig[] {
  switch (type) {
    case 'board': return BOARD_SECTIONS;
    case 'management': return MANAGEMENT_SECTIONS;
    case 'monthly': return MONTHLY_SECTIONS;
  }
}

const DEFAULT_KPI_TARGETS: KPITargetConfig[] = [
  { ratioKey: 'grossProfitMargin', target: 35, warningThreshold: 25, criticalThreshold: 15, lowerIsBetter: false },
  { ratioKey: 'netProfitMargin', target: 15, warningThreshold: 10, criticalThreshold: 5, lowerIsBetter: false },
  { ratioKey: 'currentRatio', target: 1.5, warningThreshold: 1.2, criticalThreshold: 1.0, lowerIsBetter: false },
  { ratioKey: 'debtToEquity', target: 0.5, warningThreshold: 1.0, criticalThreshold: 2.0, lowerIsBetter: true },
  { ratioKey: 'debtorDays', target: 30, warningThreshold: 45, criticalThreshold: 60, lowerIsBetter: true },
];

function buildSectionData(
  type: string,
  input: ReportPackInput,
  financialData: FinancialData,
): Record<string, unknown> {
  const grossProfit = input.revenue - input.costOfSales;

  switch (type) {
    case 'income_statement':
      return {
        revenue: input.revenue,
        costOfSales: input.costOfSales,
        grossProfit,
        operatingExpenses: input.operatingExpenses,
        netProfit: input.netProfit,
        grossMargin: input.revenue > 0 ? Math.round((grossProfit / input.revenue) * 10000) / 100 : 0,
        netMargin: input.revenue > 0 ? Math.round((input.netProfit / input.revenue) * 10000) / 100 : 0,
      };

    case 'balance_sheet':
      return {
        currentAssets: input.currentAssets,
        totalAssets: input.totalAssets,
        currentLiabilities: input.currentLiabilities,
        totalLiabilities: input.totalLiabilities,
        totalEquity: input.totalEquity,
        cash: input.cash,
        accountsReceivable: input.accountsReceivable,
        accountsPayable: input.accountsPayable,
      };

    case 'cash_flow': {
      const opCF = input.operatingCashFlow ?? input.netProfit;
      const capex = input.capitalExpenditure ?? 0;
      return {
        operatingCashFlow: opCF,
        investingCashFlow: -capex,
        financingCashFlow: 0,
        netCashFlow: opCF - capex,
        openingCash: input.cash - (opCF - capex),
        closingCash: input.cash,
      };
    }

    case 'ratios':
      return calculateExtendedRatios(financialData) as unknown as Record<string, unknown>;

    case 'kpis': {
      const ratios = calculateExtendedRatios(financialData);
      const scorecard = buildKPIScorecard(ratios, DEFAULT_KPI_TARGETS);
      return { scorecard };
    }

    case 'waterfall': {
      const steps = buildProfitWaterfall({
        revenue: input.revenue,
        costOfSales: input.costOfSales,
        grossProfit,
        operatingExpenses: input.operatingExpenses,
        otherIncome: 0,
        otherExpenses: 0,
        netProfit: input.netProfit,
      });
      return { steps };
    }

    case 'trends':
      return { note: 'Multi-period trend data requires historical context via API' };

    case 'commentary':
      return {
        period: input.period,
        companyName: input.companyName,
        summary: `${input.companyName} reported revenue of R ${input.revenue.toLocaleString('en-ZA')} with a net profit margin of ${input.revenue > 0 ? Math.round((input.netProfit / input.revenue) * 100) : 0}%.`,
      };

    default:
      return {};
  }
}

export function buildReportPack(
  type: PackType,
  data: ReportPackInput,
  from: string,
  to: string,
): ReportPack {
  const template = getPackTemplate(type);

  const financialData: FinancialData = {
    revenue: data.revenue,
    costOfSales: data.costOfSales,
    operatingExpenses: data.operatingExpenses,
    netProfit: data.netProfit,
    totalAssets: data.totalAssets,
    totalLiabilities: data.totalLiabilities,
    totalEquity: data.totalEquity,
    currentAssets: data.currentAssets,
    currentLiabilities: data.currentLiabilities,
    inventory: data.inventory,
    accountsReceivable: data.accountsReceivable,
    accountsPayable: data.accountsPayable,
    cash: data.cash,
    operatingCashFlow: data.operatingCashFlow,
    capitalExpenditure: data.capitalExpenditure,
  };

  const sections: PackSection[] = template.map(config => ({
    type: config.type,
    title: config.title,
    data: buildSectionData(config.type, data, financialData),
  }));

  return {
    type,
    companyName: data.companyName,
    period: `${from} to ${to}`,
    generatedAt: new Date().toISOString(),
    sections,
  };
}

