async () => {
  // Fetch all Dec 2026 transactions
  const res = await fetch('/api/accounting/bank-transactions?from=2026-12-01&to=2026-12-31&limit=100&page=1', { credentials: 'include' });
  const json = await res.json();
  const txs = json.data?.items || [];
  const total = json.data?.total || txs.length;

  // Summarize
  const suggested = txs.filter(t => t.suggestedGlAccountId || t.suggestedSupplierId || t.suggestedClientId);
  const unallocated = txs.filter(t => !t.suggestedGlAccountId && !t.suggestedSupplierId && !t.suggestedClientId);

  // Group unallocated by description pattern
  const patterns = {};
  for (const t of unallocated) {
    const key = (t.description || '').replace(/\d{4}\/\d{2}|\d+/g, '#').trim();
    if (!patterns[key]) patterns[key] = { count: 0, totalAmount: 0, sample: t.description };
    patterns[key].count++;
    patterns[key].totalAmount += Math.abs(t.amount);
  }

  return {
    totalDec: total,
    pageCount: txs.length,
    suggested: suggested.length,
    unallocated: unallocated.length,
    totalSpent: txs.filter(t => t.amount < 0).reduce((s, t) => s + Math.abs(t.amount), 0),
    totalReceived: txs.filter(t => t.amount > 0).reduce((s, t) => s + t.amount, 0),
    unallocatedPatterns: Object.entries(patterns).sort((a, b) => b[1].count - a[1].count).slice(0, 15)
  };
}

