  const unsuggestedNew = dec.filter(t => t.status === 'imported' && !t.suggestedGlAccountId && !t.suggestedSupplierId && !t.suggestedClientId);

  // Group unallocated by description pattern
  const patterns = {};
  for (const t of unsuggestedNew) {
    const desc = (t.description || '').replace(/\s*\d{4}\/\d{2}.*$/, '').replace(/\s*\/\d{2}$/, '').trim();
    if (!patterns[desc]) patterns[desc] = { count: 0, totalAmount: 0, amounts: [], ids: [] };
    patterns[desc].count++;
    patterns[desc].totalAmount += t.amount;
    patterns[desc].amounts.push(t.amount);
    patterns[desc].ids.push(t.id);
  }

  return {
    totalAll: all.length,
    totalDec: dec.length,
    suggestedCount: suggested.length,
    unsuggestedNewCount: unsuggestedNew.length,
    statusBreakdown: dec.reduce((acc, t) => { acc[t.status] = (acc[t.status] || 0) + 1; return acc; }, {}),
    totalSpent: dec.filter(t => t.amount < 0).reduce((s, t) => s + t.amount, 0),
    totalReceived: dec.filter(t => t.amount > 0).reduce((s, t) => s + t.amount, 0),
    unallocatedPatterns: Object.entries(patterns)
      .sort((a, b) => b[1].count - a[1].count)
      .map(([k, v]) => ({ desc: k, count: v.count, total: Math.round(v.totalAmount * 100) / 100 }))
  };
}

