async () => {
  // Get all Dec 2026 transactions
  const all = [];
  for (let page = 1; page <= 10; page++) {
    const res = await fetch(`/api/accounting/bank-transactions?pageSize=100&page=${page}&tab=new`, { credentials: 'include' });
    const json = await res.json();
    const items = json.data?.transactions || [];
    if (items.length === 0) break;
    all.push(...items);
  }
  const dec = all.filter(t => t.transactionDate?.startsWith('2026-12') && t.status === 'imported');

  let allocated = 0, errors = 0, errMsgs = [];

  for (const tx of dec) {
    const desc = (tx.description || '').toUpperCase();
    let body = { action: 'allocate', bankTransactionId: tx.id };

    // Customer receipts (already suggested)
    if (tx.suggestedClientId) {
      body.allocationType = 'customer';
      body.entityId = tx.suggestedClientId;
      body.vatCode = 'none';
    }
    // Supplier payments (already suggested)  
    else if (tx.suggestedSupplierId) {
      body.allocationType = 'supplier';
      body.entityId = tx.suggestedSupplierId;
      body.vatCode = 'none';
    }
    // GL account allocations (already suggested)
    else if (tx.suggestedGlAccountId) {
      body.allocationType = 'account';
      body.contraAccountId = tx.suggestedGlAccountId;
      body.vatCode = tx.suggestedVatCode || 'none';
    }
    // Manual allocations for unsugested patterns
    else if (desc.includes('BANK CHARGES')) {
      body.allocationType = 'account';
      body.contraAccountId = '3f3a7306-24da-48de-9cbe-babd1c37cba3'; // placeholder - need actual 5700 id
      body.vatCode = 'none';
    }
    else if (desc.includes('SALARY PAYMENT')) {
      body.allocationType = 'account';
      body.contraAccountId = '0619d1e5-adb0-485d-844b-8e09b02ba99b'; // placeholder - need actual 5200 id
      body.vatCode = 'none';
    }
    else {
      // Skip for now - need GL account IDs
      continue;
    }

    try {
      const res = await fetch('/api/accounting/bank-transactions-action', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify(body)
      });
      const json = await res.json();
      if (res.ok) allocated++;
      else { errors++; if (errMsgs.length < 3) errMsgs.push(json.error?.message || json.message); }
    } catch (e) {
      errors++;
    }
  }

  return { totalDec: dec.length, allocated, errors, errMsgs };
}

