    '5600': '436472c9-6c13-4d83-9809-9fc359bcba02',
    '5400': '17c148e7-8591-4559-b4fd-4cc2f4202c8a',
    '4310': '41af28d4-b0ca-44dc-8144-07be12f96fc4'
  };
  const SUP = {
    sage: 'd1000000-0000-0000-0000-000000000008',
    city: 'd1000000-0000-0000-0000-000000000007',
    bidvest: 'd1000000-0000-0000-0000-000000000010',
    builders: 'd1000000-0000-0000-0000-000000000002'
  };

  // Get Dec 2026 transactions
  const all = [];
  for (let p = 1; p <= 10; p++) {
    const r = await fetch(`/api/accounting/bank-transactions?pageSize=100&page=${p}&tab=new`, { credentials: 'include' });
    const j = await r.json();
    const items = j.data?.transactions || [];
    if (!items.length) break;
    all.push(...items);
  }
  const dec = all.filter(t => t.transactionDate?.startsWith('2026-12') && t.status === 'imported');

  // Build allocation requests
  const requests = [];
  for (const tx of dec) {
    const desc = (tx.description || '').toUpperCase();
    let body = { action: 'allocate', bankTransactionId: tx.id };

    if (tx.suggestedClientId) {
      Object.assign(body, { allocationType: 'customer', entityId: tx.suggestedClientId, vatCode: 'none' });
    } else if (tx.suggestedSupplierId) {
      Object.assign(body, { allocationType: 'supplier', entityId: tx.suggestedSupplierId, vatCode: 'none' });
    } else if (tx.suggestedGlAccountId) {
      Object.assign(body, { allocationType: 'account', contraAccountId: tx.suggestedGlAccountId, vatCode: tx.suggestedVatCode || 'none' });
    } else if (desc.includes('BANK CHARGES')) {
      Object.assign(body, { allocationType: 'account', contraAccountId: GL['5700'], vatCode: 'none' });
    } else if (desc.includes('SALARY PAYMENT')) {
      Object.assign(body, { allocationType: 'account', contraAccountId: GL['5200'], vatCode: 'none' });
    } else if (desc.includes('SAGE SA')) {
      Object.assign(body, { allocationType: 'supplier', entityId: SUP.sage, vatCode: 'standard' });
    } else if (desc.includes('CITY OF JHB')) {
      Object.assign(body, { allocationType: 'supplier', entityId: SUP.city, vatCode: 'standard' });
    } else if (desc.includes('BIDVEST')) {
      Object.assign(body, { allocationType: 'supplier', entityId: SUP.bidvest, vatCode: 'standard' });
    } else if (desc.includes('BUILDERS WAREHOUSE')) {
      Object.assign(body, { allocationType: 'supplier', entityId: SUP.builders, vatCode: 'standard' });
    } else {
      continue; // skip unknown
    }
    requests.push(body);
  }

  // Process in batches of 10
  let ok = 0, fail = 0, errs = [];
  for (let i = 0; i < requests.length; i += 10) {
    const batch = requests.slice(i, i + 10);
    const results = await Promise.all(batch.map(b =>
      fetch('/api/accounting/bank-transactions-action', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        credentials: 'include', body: JSON.stringify(b)
      }).then(r => r.json().then(j => ({ ok: r.ok, msg: j.error?.message })))
    ));
    for (const r of results) {
      if (r.ok) ok++; else { fail++; if (errs.length < 5) errs.push(r.msg); }
    }
  }

  return { total: dec.length, requested: requests.length, allocated: ok, failed: fail, errors: errs };
}

