  // Use bulk_accept to mark as reviewed (batch of 50)
  let reviewed = 0, failed = 0;
  for (let i = 0; i < decIds.length; i += 50) {
    const batch = decIds.slice(i, i + 50);
    const res = await fetch('/api/accounting/bank-transactions-action', {
