      credentials: 'include', body: JSON.stringify({ action: 'bulk_accept', bankTransactionIds: batch })
    });
    const json = await res.json();
    if (res.ok) reviewed += json.data?.accepted || batch.length;
    else failed += batch.length;
  }

  return { totalIds: decIds.length, reviewed, failed };
}

