    .filter(t => t.transactionDate?.startsWith('2026-12') && t.status === 'allocated')
    .map(t => t.id);

  // Use bulk_accept to mark as reviewed (batch of 50)
  let reviewed = 0, failed = 0;
  for (let i = 0; i < decIds.length; i += 50) {
    const batch = decIds.slice(i, i + 50);
    const res = await fetch('/api/accounting/bank-transactions-action', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      credentials: 'include', body: JSON.stringify({ action: 'bulk_accept', bankTransactionIds: batch })
    });
    const json = await res.json();
    if (res.ok) reviewed += json.data?.accepted || batch.length;
    else failed += batch.length;
  }

  return { totalIds: decIds.length, reviewed, failed };
}

async () => {
  // Get Trial Balance for Dec 2026
  const res = await fetch('/api/accounting/reports-trial-balance?period=2026-12', { credentials: 'include' });
  const json = await res.json();
  const accounts = json.data?.accounts || json.data || [];
  if (accounts.length === 0) return { error: 'No data', rawKeys: Object.keys(json.data || json) };

  // Summarize
  let totalDebit = 0, totalCredit = 0;
  const summary = accounts.filter(a => (a.debit || 0) !== 0 || (a.credit || 0) !== 0).map(a => {
    totalDebit += a.debit || 0;
    totalCredit += a.credit || 0;
    return { code: a.accountCode, name: a.accountName, debit: a.debit || 0, credit: a.credit || 0 };
  });

  return { 
    accountCount: summary.length,
    totalDebit: Math.round(totalDebit * 100) / 100,
    totalCredit: Math.round(totalCredit * 100) / 100,
    balanced: Math.abs(totalDebit - totalCredit) < 0.01,
    accounts: summary
  };
}

