() => {
  // Set date inputs to Dec 2026 via DOM manipulation
  const inputs = document.querySelectorAll('input[type="date"]');
  if (inputs.length >= 2) {
    const fromInput = inputs[0];
    const toInput = inputs[1];

    // Set values using native setter to trigger React state
    const nativeInputValueSetter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;

    nativeInputValueSetter.call(fromInput, '2026-12-01');
    fromInput.dispatchEvent(new Event('input', { bubbles: true }));
    fromInput.dispatchEvent(new Event('change', { bubbles: true }));

    nativeInputValueSetter.call(toInput, '2026-12-31');
    toInput.dispatchEvent(new Event('input', { bubbles: true }));
    toInput.dispatchEvent(new Event('change', { bubbles: true }));

    return { set: true, from: fromInput.value, to: toInput.value };
  }
  return { error: 'date inputs not found', inputCount: inputs.length };
}

