async () => {
  // Get all Nov 2026 allocated transactions and mark as reviewed
  const all = [];
  for (let p = 1; p <= 15; p++) {
    const r = await fetch(`/api/accounting/bank-transactions?pageSize=100&page=${p}&tab=new`, { credentials: 'include' });
    const j = await r.json();
    const items = j.data?.transactions || [];
    if (!items.length) break;
    all.push(...items);
  }

  const novAllocated = all.filter(t => t.transactionDate?.startsWith('2026-11') && t.status === 'allocated');
  const novIds = novAllocated.map(t => t.id);

  if (novIds.length === 0) return { message: 'No Nov allocated txns to review', novImported: all.filter(t => t.transactionDate?.startsWith('2026-11') && t.status === 'imported').length };

  // Bulk accept
  let reviewed = 0;
  for (let i = 0; i < novIds.length; i += 50) {
    const batch = novIds.slice(i, i + 50);
    const res = await fetch('/api/accounting/bank-transactions-action', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      credentials: 'include', body: JSON.stringify({ action: 'bulk_accept', bankTransactionIds: batch })
    });
    if (res.ok) reviewed += batch.length;
  }

  return { novReviewed: reviewed, novTotal: novAllocated.length };
}

