async () => {
  const GL = {
    '5700': '3f3a7306-24da-48de-9cbe-babd1c37cba3',
    '5200': '0619d1e5-adb0-485d-844b-8e09b02ba99b',
  };
  const SUP = {
    sage: 'd1000000-0000-0000-0000-000000000008',
    city: 'd1000000-0000-0000-0000-000000000007',
    bidvest: 'd1000000-0000-0000-0000-000000000010',
    builders: 'd1000000-0000-0000-0000-000000000002'
  };

  const all = [];
  for (let p = 1; p <= 15; p++) {
    const r = await fetch(`/api/accounting/bank-transactions?pageSize=100&page=${p}&tab=new`, { credentials: 'include' });
    const j = await r.json();
    const items = j.data?.transactions || [];
    if (!items.length) break;
    all.push(...items);
  }

  const jan = all.filter(t => t.transactionDate?.startsWith('2027-01') && t.status === 'imported');

  const requests = [];
  let skipped = [];
  for (const tx of jan) {
    const desc = (tx.description || '').toUpperCase();
    let body = { action: 'allocate', bankTransactionId: tx.id, vatCode: 'none' };

    if (tx.suggestedClientId) {
      Object.assign(body, { allocationType: 'customer', entityId: tx.suggestedClientId });
    } else if (tx.suggestedSupplierId) {
      Object.assign(body, { allocationType: 'supplier', entityId: tx.suggestedSupplierId });
    } else if (tx.suggestedGlAccountId) {
      Object.assign(body, { allocationType: 'account', contraAccountId: tx.suggestedGlAccountId, vatCode: tx.suggestedVatCode === 'exempt' ? 'exempt' : 'none' });
    } else if (desc.includes('BANK CHARGES')) {
      Object.assign(body, { allocationType: 'account', contraAccountId: GL['5700'] });
    } else if (desc.includes('SALARY PAYMENT')) {
      Object.assign(body, { allocationType: 'account', contraAccountId: GL['5200'] });
    } else if (desc.includes('SAGE SA')) {
      Object.assign(body, { allocationType: 'supplier', entityId: SUP.sage });
    } else if (desc.includes('CITY OF JHB')) {
      Object.assign(body, { allocationType: 'supplier', entityId: SUP.city });
    } else if (desc.includes('BIDVEST')) {
      Object.assign(body, { allocationType: 'supplier', entityId: SUP.bidvest });
    } else if (desc.includes('BUILDERS WAREHOUSE')) {
      Object.assign(body, { allocationType: 'supplier', entityId: SUP.builders });
    } else if (desc.includes('TELKOM')) {
      Object.assign(body, { allocationType: 'supplier', entityId: 'd1000000-0000-0000-0000-000000000009' }); // Telkom
    } else {
      skipped.push(desc.substring(0, 30));
      continue;
    }
    requests.push(body);
  }

  // Sequential
  let ok = 0, fail = 0, errs = [];
  for (const b of requests) {
    try {
      const r = await fetch('/api/accounting/bank-transactions-action', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        credentials: 'include', body: JSON.stringify(b)
      });
      if (r.ok) ok++;
      else { const j = await r.json(); fail++; if (errs.length < 3) errs.push(j.error?.message); }
    } catch(e) { fail++; }
  }

  return { month: '2027-01', total: jan.length, requested: requests.length, allocated: ok, failed: fail, skipped: [...new Set(skipped)], errors: errs };
}

