async () => {
  // Get all Jan 2027 allocated and review them
  const all = [];
  for (let p = 1; p <= 15; p++) {
    const r = await fetch(`/api/accounting/bank-transactions?pageSize=100&page=${p}&tab=new`, { credentials: 'include' });
    const j = await r.json();
    const items = j.data?.transactions || [];
    if (!items.length) break;
    all.push(...items);
  }

  const janAllocated = all.filter(t => t.transactionDate?.startsWith('2027-01') && t.status === 'allocated');
  const janIds = janAllocated.map(t => t.id);

  let reviewed = 0;
  for (let i = 0; i < janIds.length; i += 50) {
    const batch = janIds.slice(i, i + 50);
    const res = await fetch('/api/accounting/bank-transactions-action', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      credentials: 'include', body: JSON.stringify({ action: 'bulk_accept', bankTransactionIds: batch })
    });
    if (res.ok) reviewed += batch.length;
  }

  // Check remaining unallocated
  const remaining = all.filter(t => t.status === 'imported');

  return { 
    janReviewed: reviewed, 
    janTotal: janAllocated.length,
    remainingImported: remaining.length,
    remainingMonths: [...new Set(remaining.map(t => (t.transactionDate || '').substring(0, 7)))]
  };
}

