/**
 * Sage-style bank transaction table with inline allocation
 * Type selector: Account / Supplier / Customer — Selection dropdown changes accordingly
 * VAT selector: No VAT / Standard 15% / Zero-Rated / Exempt
 * Notes: inline-editable per row, saved on blur
 */

import { useState, useRef, useEffect } from 'react';
import { Check, X, Undo2, Search, Scissors, SearchCheck, RotateCcw, Paperclip, BookmarkPlus, Plus } from 'lucide-react';

export type AllocType = 'account' | 'supplier' | 'customer';
export type VatCode = 'none' | 'standard' | 'zero_rated' | 'exempt';

export const VAT_OPTIONS: { value: VatCode; label: string; rate: number }[] = [
  { value: 'none', label: 'No VAT', rate: 0 },
  { value: 'standard', label: 'Standard 15%', rate: 15 },
  { value: 'zero_rated', label: 'Zero Rated', rate: 0 },
  { value: 'exempt', label: 'Exempt', rate: 0 },
];

tool_input.function:
async () => {
  // Final status check - any remaining transactions?
  const r1 = await fetch('/api/accounting/bank-transactions?pageSize=1&page=1&tab=new', { credentials: 'include' });
  const j1 = await r1.json();
  const newTotal = j1.data?.total || 0;

  const r2 = await fetch('/api/accounting/bank-transactions?pageSize=1&page=1&tab=reviewed', { credentials: 'include' });
  const j2 = await r2.json();
  const reviewedTotal = j2.data?.total || 0;

  // Check all months that have data
  const all = [];
  for (let p = 1; p <= 20; p++) {
    const r = await fetch(`/api/accounting/bank-transactions?pageSize=100&page=${p}`, { credentials: 'include' });
    const j = await r.json();
    const items = j.data?.transactions || [];
    if (!items.length) break;
    all.push(...items);
  }

  const byStatus = {};
  const byMonth = {};
  for (const t of all) {
    byStatus[t.status] = (byStatus[t.status] || 0) + 1;
    const m = (t.transactionDate || '').substring(0, 7);
    if (!byMonth[m]) byMonth[m] = { total: 0, statuses: {} };
    byMonth[m].total++;
    byMonth[m].statuses[t.status] = (byMonth[m].statuses[t.status] || 0) + 1;
  }

  return { 
    newTab: newTotal,
    reviewedTab: reviewedTotal,
    totalFetched: all.length,
    byStatus,
    months: Object.entries(byMonth).sort((a, b) => a[0].localeCompare(b[0]))
  };
}

