// ── Exchange Rates ──────────────────────────────────────────────────────────

export async function getExchangeRates(companyId: string, filters?: {
  fromCurrency?: string; toCurrency?: string; limit?: number;
}): Promise<ExchangeRate[]> {
  const limit = filters?.limit || 100;

  if (filters?.fromCurrency && filters?.toCurrency) {
    const rows = (await sql`
      SELECT * FROM exchange_rates
      WHERE company_id = ${companyId}
        AND from_currency = ${filters.fromCurrency} AND to_currency = ${filters.toCurrency}
      ORDER BY effective_date DESC LIMIT ${limit}
    `) as Row[];
    return rows.map(mapRate);
  }
  if (filters?.fromCurrency) {
    const rows = (await sql`
      SELECT * FROM exchange_rates
      WHERE company_id = ${companyId} AND from_currency = ${filters.fromCurrency}
      ORDER BY effective_date DESC LIMIT ${limit}
    `) as Row[];
    return rows.map(mapRate);
  }
  const rows = (await sql`
    SELECT * FROM exchange_rates WHERE company_id = ${companyId} ORDER BY effective_date DESC LIMIT ${limit}
  `) as Row[];
  return rows.map(mapRate);
}

export async function getLatestRate(companyId: string, 
  fromCurrency: string, toCurrency: string, asOfDate?: string
): Promise<number | null> {
  const date = asOfDate || new Date().toISOString().split('T')[0]!;
  const rows = (await sql`
    SELECT rate FROM exchange_rates
    WHERE company_id = ${companyId}
      AND from_currency = ${fromCurrency} AND to_currency = ${toCurrency}
      AND effective_date <= ${date}::DATE
    ORDER BY effective_date DESC LIMIT 1
  `) as Row[];
  return rows[0] ? Number(rows[0].rate) : null;
}

export async function setExchangeRate(companyId: string, input: {
  fromCurrency: string; toCurrency: string; rate: number;
  effectiveDate: string; source?: string;
}, userId: string): Promise<ExchangeRate> {
  const rows = (await sql`
    INSERT INTO exchange_rates (company_id, from_currency, to_currency, rate, effective_date, source, created_by)
    VALUES (${companyId}, ${input.fromCurrency}, ${input.toCurrency}, ${input.rate},
            ${input.effectiveDate}::DATE, ${input.source || 'manual'}, ${userId}::UUID)
    ON CONFLICT (company_id, from_currency, to_currency, effective_date)
    DO UPDATE SET rate = EXCLUDED.rate, source = EXCLUDED.source, created_by = EXCLUDED.created_by
    RETURNING *
  `) as Row[];
  log.info('Set exchange rate', {
    pair: `${input.fromCurrency}/${input.toCurrency}`,
    rate: input.rate, date: input.effectiveDate,
  }, 'accounting');
  return mapRate(rows[0]!);
}

export async function convertAmount(companyId: string, 
  amount: number, fromCurrency: string, toCurrency: string, asOfDate?: string
): Promise<{ converted: number; rate: number } | null> {
  if (fromCurrency === toCurrency) return { converted: amount, rate: 1 };
  const rate = await getLatestRate(companyId, fromCurrency, toCurrency, asOfDate);
  if (rate === null) return null;
  return { converted: Math.round(amount * rate * 100) / 100, rate };
}

// ── Settings ────────────────────────────────────────────────────────────────

export async function getSetting(key: string): Promise<string | null> {
  const rows = (await sql`
    SELECT setting_value FROM accounting_settings WHERE setting_key = ${key}
  `) as Row[];
  return rows[0] ? String(rows[0].setting_value) : null;
}

export async function setSetting(key: string, value: string, userId: string): Promise<void> {
  await sql`
    INSERT INTO accounting_settings (setting_key, setting_value, updated_by)
    VALUES (${key}, ${value}, ${userId}::UUID)
    ON CONFLICT (setting_key) DO UPDATE SET setting_value = EXCLUDED.setting_value,
      updated_by = EXCLUDED.updated_by, updated_at = NOW()
  `;
}

// ── Helpers ─────────────────────────────────────────────────────────────────

function mapCurrency(row: Row): Currency {
  return {
    code: String(row.code),
    name: String(row.name),
    symbol: String(row.symbol),
    decimalPlaces: Number(row.decimal_places),
    isActive: Boolean(row.is_active),
  };
}

function mapRate(row: Row): ExchangeRate {
  return {
    id: String(row.id),
    fromCurrency: String(row.from_currency),
    toCurrency: String(row.to_currency),
    rate: Number(row.rate),
    effectiveDate: row.effective_date instanceof Date
      ? row.effective_date.toISOString().split('T')[0]!
      : String(row.effective_date).split('T')[0]!,
    source: String(row.source || 'manual'),
  };
}

/**
 * Debtors Manager Service
 * Sage-parity collections/aging dashboard for AR
 *
 * Queries customer_invoices and customer_payments (existing tables).
 * No new migration required.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

type Row = Record<string, unknown>;

// ── Types ─────────────────────────────────────────────────────────────────────

export interface DebtorSummary {
  clientId: string;
  clientName: string;
  current: number;
  days30: number;
  days60: number;
  days90: number;
  days90Plus: number;
  totalOutstanding: number;
  invoiceCount: number;
}

export interface DebtorInvoice {
  id: string;
  invoiceNumber: string;
  invoiceDate: string;
  dueDate: string | null;
  totalAmount: number;
  amountPaid: number;
  outstanding: number;
  daysOverdue: number;
  status: string;
  agingBucket: 'current' | 'days30' | 'days60' | 'days90' | 'days90Plus';
}

export interface OverdueInvoice {
  id: string;
  invoiceNumber: string;
  clientId: string;
  clientName: string;
  invoiceDate: string;
  dueDate: string;
  totalAmount: number;
  amountPaid: number;
  outstanding: number;
  daysOverdue: number;
  status: string;
}

export interface CollectionStats {
  totalOutstanding: number;
  totalOverdue: number;
  avgDaysOutstanding: number;
  collectionRate: number;
  clientCount: number;
  overdueCount: number;
}

// ── Helpers ───────────────────────────────────────────────────────────────────

function classifyBucket(daysOverdue: number): DebtorInvoice['agingBucket'] {
  if (daysOverdue <= 0) return 'current';
  if (daysOverdue <= 30) return 'days30';
  if (daysOverdue <= 60) return 'days60';
  if (daysOverdue <= 90) return 'days90';
  return 'days90Plus';
}

// ── Debtors Summary ───────────────────────────────────────────────────────────

/**
 * Aggregate outstanding invoices by customer with aging buckets.
 * Buckets: current (not yet due), 1-30, 31-60, 61-90, 90+ days overdue.
 */
export async function getDebtorsSummary(companyId: string): Promise<DebtorSummary[]> {
  try {
    const rows = (await sql`
      SELECT
        ci.client_id,
        c.name AS client_name,
        COUNT(ci.id)::int AS invoice_count,
        SUM(
          CASE WHEN ci.due_date IS NULL OR ci.due_date >= CURRENT_DATE
               THEN (ci.total_amount - ci.amount_paid) ELSE 0 END
        ) AS current,
        SUM(
          CASE WHEN ci.due_date IS NOT NULL
                AND ci.due_date < CURRENT_DATE
                AND (CURRENT_DATE - ci.due_date) <= 30
               THEN (ci.total_amount - ci.amount_paid) ELSE 0 END
        ) AS days30,
        SUM(
          CASE WHEN ci.due_date IS NOT NULL
                AND (CURRENT_DATE - ci.due_date) BETWEEN 31 AND 60
               THEN (ci.total_amount - ci.amount_paid) ELSE 0 END
        ) AS days60,
        SUM(
          CASE WHEN ci.due_date IS NOT NULL
                AND (CURRENT_DATE - ci.due_date) BETWEEN 61 AND 90
               THEN (ci.total_amount - ci.amount_paid) ELSE 0 END
        ) AS days90,
        SUM(
          CASE WHEN ci.due_date IS NOT NULL
                AND (CURRENT_DATE - ci.due_date) > 90
               THEN (ci.total_amount - ci.amount_paid) ELSE 0 END
        ) AS days90_plus,
        SUM(ci.total_amount - ci.amount_paid) AS total_outstanding
      FROM customer_invoices ci
      JOIN customers c ON c.id = ci.client_id
      WHERE ci.company_id = ${companyId}
        AND ci.status IN ('approved', 'sent', 'partially_paid', 'overdue')
        AND (ci.total_amount - ci.amount_paid) > 0
      GROUP BY ci.client_id, c.name
      ORDER BY total_outstanding DESC
    `) as Row[];

    return rows.map((r: Row) => ({
      clientId: String(r.client_id),
      clientName: String(r.client_name),
      current: Number(r.current),
      days30: Number(r.days30),
      days60: Number(r.days60),
      days90: Number(r.days90),
      days90Plus: Number(r.days90_plus),
      totalOutstanding: Number(r.total_outstanding),
      invoiceCount: Number(r.invoice_count),
    }));
  } catch (err) {
    log.error('getDebtorsSummary failed', { error: err }, 'accounting');
    throw err;
  }
}

// ── Debtor Detail ─────────────────────────────────────────────────────────────

/**
 * List outstanding invoices for a specific customer with age and amounts.
 */
export async function getDebtorDetail(companyId: string, clientId: string): Promise<DebtorInvoice[]> {
  try {
    const rows = (await sql`
      SELECT
        ci.id,
        ci.invoice_number,
        ci.invoice_date,
        ci.due_date,
        ci.total_amount,
        ci.amount_paid,
        (ci.total_amount - ci.amount_paid) AS outstanding,
        ci.status,
        CASE
          WHEN ci.due_date IS NULL THEN 0
          ELSE GREATEST(0, (CURRENT_DATE - ci.due_date)::int)
        END AS days_overdue
      FROM customer_invoices ci
      WHERE ci.company_id = ${companyId}
        AND ci.client_id = ${clientId}::UUID
        AND ci.status IN ('approved', 'sent', 'partially_paid', 'overdue')
        AND (ci.total_amount - ci.amount_paid) > 0
      ORDER BY ci.due_date ASC NULLS LAST, ci.invoice_date ASC
    `) as Row[];

    return rows.map((r: Row) => {
      const daysOverdue = Number(r.days_overdue);
      return {
        id: String(r.id),
        invoiceNumber: String(r.invoice_number),
        invoiceDate: String(r.invoice_date),
        dueDate: r.due_date ? String(r.due_date) : null,
        totalAmount: Number(r.total_amount),
        amountPaid: Number(r.amount_paid),
        outstanding: Number(r.outstanding),
        daysOverdue,
        status: String(r.status),
        agingBucket: classifyBucket(daysOverdue),
      };
    });
  } catch (err) {
    log.error('getDebtorDetail failed', { clientId, error: err }, 'accounting');
    throw err;
  }
}

// ── Overdue Invoices ──────────────────────────────────────────────────────────

/**
 * List all overdue invoices sorted by age descending.
 * Optionally filter to invoices overdue by at least daysOverdue days.
 */
export async function getOverdueInvoices(companyId: string, daysOverdue?: number): Promise<OverdueInvoice[]> {
  const minDays = daysOverdue ?? 1;

  try {
    const rows = (await sql`
      SELECT
        ci.id,
        ci.invoice_number,
        ci.client_id,
        c.name AS client_name,
        ci.invoice_date,
        ci.due_date,
        ci.total_amount,
        ci.amount_paid,
        (ci.total_amount - ci.amount_paid) AS outstanding,
        (CURRENT_DATE - ci.due_date)::int AS days_overdue,
        ci.status
      FROM customer_invoices ci
      JOIN customers c ON c.id = ci.client_id
      WHERE ci.company_id = ${companyId}
        AND ci.due_date IS NOT NULL
        AND ci.due_date < CURRENT_DATE
        AND (CURRENT_DATE - ci.due_date) >= ${minDays}
        AND ci.status IN ('approved', 'sent', 'partially_paid', 'overdue')
        AND (ci.total_amount - ci.amount_paid) > 0
      ORDER BY days_overdue DESC, ci.total_amount DESC
    `) as Row[];

    return rows.map((r: Row) => ({
      id: String(r.id),
      invoiceNumber: String(r.invoice_number),
      clientId: String(r.client_id),
      clientName: String(r.client_name),
      invoiceDate: String(r.invoice_date),
      dueDate: String(r.due_date),
      totalAmount: Number(r.total_amount),
      amountPaid: Number(r.amount_paid),
      outstanding: Number(r.outstanding),
      daysOverdue: Number(r.days_overdue),
      status: String(r.status),
    }));
  } catch (err) {
    log.error('getOverdueInvoices failed', { daysOverdue, error: err }, 'accounting');
    throw err;
  }
}

// ── Collection Stats ──────────────────────────────────────────────────────────

/**
 * Aggregate collection metrics: total outstanding, total overdue,
 * average days outstanding, and collection rate.
 */
export async function getCollectionStats(companyId: string): Promise<CollectionStats> {
  try {
    const rows = (await sql`
      SELECT
        SUM(ci.total_amount - ci.amount_paid)                            AS total_outstanding,
        SUM(CASE WHEN ci.due_date < CURRENT_DATE
                 THEN (ci.total_amount - ci.amount_paid) ELSE 0 END)     AS total_overdue,
        COALESCE(AVG(
          CASE WHEN ci.due_date IS NOT NULL AND ci.due_date < CURRENT_DATE
               THEN (CURRENT_DATE - ci.due_date)::numeric END
        ), 0)                                                             AS avg_days_outstanding,
        COUNT(DISTINCT ci.client_id)::int                                AS client_count,
        COUNT(CASE WHEN ci.due_date < CURRENT_DATE THEN 1 END)::int      AS overdue_count
      FROM customer_invoices ci
      WHERE ci.company_id = ${companyId}
        AND ci.status IN ('approved', 'sent', 'partially_paid', 'overdue')
        AND (ci.total_amount - ci.amount_paid) > 0
    `) as Row[];

    const rateRows = (await sql`
      SELECT
        SUM(ci.total_amount)  AS invoiced,
        SUM(ci.amount_paid)   AS collected
      FROM customer_invoices ci
      WHERE ci.company_id = ${companyId}
        AND ci.status NOT IN ('draft', 'cancelled')
    `) as Row[];

    const r = rows[0] ?? {};
    const rate = rateRows[0] ?? {};
    const invoiced = Number(rate.invoiced ?? 0);
    const collected = Number(rate.collected ?? 0);

    return {
      totalOutstanding: Number(r.total_outstanding ?? 0),
      totalOverdue: Number(r.total_overdue ?? 0),
      avgDaysOutstanding: Math.round(Number(r.avg_days_outstanding ?? 0)),
      collectionRate: invoiced > 0 ? Math.round((collected / invoiced) * 100 * 10) / 10 : 0,
      clientCount: Number(r.client_count ?? 0),
      overdueCount: Number(r.overdue_count ?? 0),
    };
  } catch (err) {
    log.error('getCollectionStats failed', { error: err }, 'accounting');
    throw err;
  }
}

/**
 * Customer Quote Service — Sage-parity quotes with convert-to-invoice
 */

import { sql, withTransaction } from '@/lib/neon';
import { log } from '@/lib/logger';

type Row = Record<string, unknown>;

export interface QuoteLine {
  id: string;
  quoteId: string;
  lineNumber: number;
  description: string;
  quantity: number;
  unitPrice: number;
  taxRate: number;
  lineTotal: number;
  accountId: string | null;
}

export interface Quote {
  id: string;
  quoteNumber: string;
  clientId: string | null;
  customerName: string;
  quoteDate: string;
  expiryDate: string | null;
  status: string;
  subtotal: number;
  taxAmount: number;
  total: number;
  notes: string | null;
  terms: string | null;
  convertedInvoiceId: string | null;
  createdAt: string;
  updatedAt: string;
  lines?: QuoteLine[];
}

interface QuoteFilters {
  status?: string;
  search?: string;
  limit?: number;
  offset?: number;
}

interface QuoteInput {
  customerName: string;
  clientId?: string;
  quoteDate?: string;
  expiryDate?: string;
  notes?: string;
  terms?: string;
  lines: { description: string; quantity: number; unitPrice: number; taxRate?: number; accountId?: string }[];
}

function mapQuote(r: Row): Quote {
  return {
    id: String(r.id), quoteNumber: String(r.quote_number), clientId: r.client_id != null ? String(r.client_id) : null,
    customerName: String(r.customer_name), quoteDate: String(r.quote_date),
    expiryDate: r.expiry_date != null ? String(r.expiry_date) : null, status: String(r.status),
    subtotal: Number(r.subtotal), taxAmount: Number(r.tax_amount),
    total: Number(r.total), notes: r.notes != null ? String(r.notes) : null, terms: r.terms != null ? String(r.terms) : null,
    convertedInvoiceId: r.converted_invoice_id != null ? String(r.converted_invoice_id) : null,
    createdAt: String(r.created_at), updatedAt: String(r.updated_at),
  };
}

function mapLine(r: Row): QuoteLine {
  return {
    id: String(r.id), quoteId: String(r.quote_id), lineNumber: Number(r.line_number),
    description: String(r.description), quantity: Number(r.quantity),
    unitPrice: Number(r.unit_price), taxRate: Number(r.tax_rate),
    lineTotal: Number(r.line_total), accountId: r.account_id != null ? String(r.account_id) : null,
  };
}

async function nextQuoteNumber(): Promise<string> {
  const rows = (await sql`
    SELECT quote_number FROM customer_quotes ORDER BY created_at DESC LIMIT 1
  `) as Row[];
  if (rows.length === 0) return 'QUO-00001';
  const last = String(rows[0]!.quote_number);
  const num = parseInt(last.replace('QUO-', ''), 10) || 0;
  return `QUO-${String(num + 1).padStart(5, '0')}`;
}

function calcTotals(lines: QuoteInput['lines']) {
  let subtotal = 0;
  let taxAmount = 0;
  for (const l of lines) {
    const lt = Math.round(l.quantity * l.unitPrice * 100) / 100;
    const lineTax = Math.round(lt * ((l.taxRate ?? 15) / 100) * 100) / 100;
    subtotal += lt;
    taxAmount += lineTax;
  }
  return { subtotal: Math.round(subtotal * 100) / 100, taxAmount: Math.round(taxAmount * 100) / 100, total: Math.round((subtotal + taxAmount) * 100) / 100 };
}

export async function getQuotes(companyId: string, filters?: QuoteFilters): Promise<{ quotes: Quote[]; total: number }> {
  const limit = filters?.limit || 50;
  const offset = filters?.offset || 0;
  let rows: Row[];
  let countRows: Row[];

  if (filters?.search) {
    const pattern = `%${filters.search}%`;
    rows = (await sql`
      SELECT * FROM customer_quotes
      WHERE company_id = ${companyId}
        AND (quote_number ILIKE ${pattern} OR customer_name ILIKE ${pattern})
      ORDER BY created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`
      SELECT COUNT(*) AS cnt FROM customer_quotes
      WHERE company_id = ${companyId}
        AND (quote_number ILIKE ${pattern} OR customer_name ILIKE ${pattern})
    `) as Row[];
  } else if (filters?.status) {
    rows = (await sql`
      SELECT * FROM customer_quotes WHERE company_id = ${companyId} AND status = ${filters.status}
      ORDER BY created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`
      SELECT COUNT(*) AS cnt FROM customer_quotes WHERE company_id = ${companyId} AND status = ${filters.status}
    `) as Row[];
  } else {
    rows = (await sql`
      SELECT * FROM customer_quotes WHERE company_id = ${companyId} ORDER BY created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`SELECT COUNT(*) AS cnt FROM customer_quotes WHERE company_id = ${companyId}`) as Row[];
  }
  return { quotes: rows.map(mapQuote), total: Number(countRows[0]?.cnt || 0) };
}

export async function getQuote(companyId: string, id: string): Promise<Quote | null> {
  // companyId may be empty string for internal calls — skip company filter in that case
  const rows = companyId
    ? (await sql`SELECT * FROM customer_quotes WHERE id = ${id}::UUID AND company_id = ${companyId}`) as Row[]
    : (await sql`SELECT * FROM customer_quotes WHERE id = ${id}::UUID`) as Row[];
  if (rows.length === 0) return null;
  const quote = mapQuote(rows[0]!);
  const lineRows = (await sql`
    SELECT * FROM customer_quote_lines WHERE quote_id = ${id}::UUID ORDER BY line_number
  `) as Row[];
  quote.lines = lineRows.map(mapLine);
  return quote;
}

export async function createQuote(companyId: string, input: QuoteInput, userId?: string): Promise<Quote> {
  const quoteNumber = await nextQuoteNumber();
  const { subtotal, taxAmount, total } = calcTotals(input.lines);
  const qd = input.quoteDate || new Date().toISOString().split('T')[0];

  const rows = (await sql`
    INSERT INTO customer_quotes (company_id, quote_number, client_id, customer_name, quote_date, expiry_date,
      subtotal, tax_amount, total, notes, terms, created_by)
    VALUES (${companyId}, ${quoteNumber}, ${input.clientId || null}, ${input.customerName}, ${qd},
      ${input.expiryDate || null}, ${subtotal}, ${taxAmount}, ${total},
      ${input.notes || null}, ${input.terms || null}, ${userId || null})
    RETURNING *
  `) as Row[];

  const quote = mapQuote(rows[0]!);
  for (let i = 0; i < input.lines.length; i++) {
    const l = input.lines[i];
    if (!l) continue;
    const lineTotal = Math.round(l.quantity * l.unitPrice * 100) / 100;
    await sql`
      INSERT INTO customer_quote_lines (quote_id, line_number, description, quantity, unit_price, tax_rate, line_total, account_id)
      VALUES (${quote.id}::UUID, ${i + 1}, ${l.description}, ${l.quantity}, ${l.unitPrice}, ${l.taxRate ?? 15}, ${lineTotal}, ${l.accountId || null})
    `;
  }
  log.info('Quote created', { quoteNumber, total });
  return (await getQuote('', quote.id))!;
}

export async function updateQuote(companyId: string, id: string, input: QuoteInput): Promise<Quote | null> {
  const existing = await getQuote(companyId, id);
  if (!existing || existing.status !== 'draft') return null;
  const { subtotal, taxAmount, total } = calcTotals(input.lines);

  await sql`
    UPDATE customer_quotes SET customer_name = ${input.customerName}, client_id = ${input.clientId || null},
      quote_date = ${input.quoteDate || existing.quoteDate}, expiry_date = ${input.expiryDate || null},
      subtotal = ${subtotal}, tax_amount = ${taxAmount}, total = ${total},
      notes = ${input.notes || null}, terms = ${input.terms || null}, updated_at = NOW()
    WHERE id = ${id}::UUID AND company_id = ${companyId}::UUID AND status = 'draft'
  `;
  await sql`DELETE FROM customer_quote_lines WHERE quote_id = ${id}::UUID`;
  for (let i = 0; i < input.lines.length; i++) {
    const l = input.lines[i];
    if (!l) continue;
    const lineTotal = Math.round(l.quantity * l.unitPrice * 100) / 100;
    await sql`
      INSERT INTO customer_quote_lines (quote_id, line_number, description, quantity, unit_price, tax_rate, line_total, account_id)
      VALUES (${id}::UUID, ${i + 1}, ${l.description}, ${l.quantity}, ${l.unitPrice}, ${l.taxRate ?? 15}, ${lineTotal}, ${l.accountId || null})
    `;
  }
  log.info('Quote updated', { id });
  return getQuote('', id);
}

export async function deleteQuote(companyId: string, id: string): Promise<boolean> {
  const rows = (await sql`DELETE FROM customer_quotes WHERE id = ${id}::UUID AND company_id = ${companyId} AND status = 'draft' RETURNING id`) as Row[];
  return rows.length > 0;
}

export async function updateQuoteStatus(companyId: string, id: string, status: string): Promise<Quote | null> {
  await sql`UPDATE customer_quotes SET status = ${status}, updated_at = NOW() WHERE id = ${id}::UUID AND company_id = ${companyId}`;
  log.info('Quote status changed', { id, status });
  return getQuote('', id);
}

export async function convertToInvoice(companyId: string, id: string, userId?: string): Promise<{ quote: Quote; invoiceId: string } | null> {
  const quote = await getQuote(companyId, id);
  if (!quote || quote.status !== 'accepted') return null;

  const invoiceId = await withTransaction(async (tx) => {
    // Create invoice from quote
    const invRows = (await tx`
      INSERT INTO customer_invoices (company_id, client_id, invoice_date, due_date, subtotal, tax_amount, total, notes, status, created_by)
      VALUES (${companyId}, ${quote.clientId}, ${quote.quoteDate}, ${quote.expiryDate || quote.quoteDate}, ${quote.subtotal},
        ${quote.taxAmount}, ${quote.total}, ${'Converted from ' + quote.quoteNumber}, 'draft', ${userId || null})
      RETURNING id
    `) as Row[];
    const newInvoiceId = String(invRows[0]!.id);

    // Copy lines
    for (const line of quote.lines || []) {
      await tx`
        INSERT INTO customer_invoice_items (invoice_id, description, quantity, unit_price, tax_rate, line_total, account_id)
        VALUES (${newInvoiceId}::UUID, ${line.description}, ${line.quantity}, ${line.unitPrice}, ${line.taxRate}, ${line.lineTotal}, ${line.accountId})
      `;
    }

    await tx`UPDATE customer_quotes SET status = 'converted', converted_invoice_id = ${newInvoiceId}::UUID, updated_at = NOW() WHERE id = ${id}::UUID AND company_id = ${companyId}::UUID`;
    return newInvoiceId;
  });

  log.info('Quote converted to invoice', { quoteId: id, invoiceId });
  return { quote: (await getQuote('', id))!, invoiceId };
}

/**
 * Phase 2: Bank Categorisation Rules Service
 * Quick entry rules + statement mapping for auto-categorisation
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { createJournalEntry, postJournalEntry } from './journalEntryService';
import { getSystemAccountId } from './systemAccountResolver';
import type {
  BankCategorisationRule, RuleCreateInput, RuleApplyResult,
} from '../types/bank.types';
import type { JournalLineInput } from '../types/gl.types';

// ── CRUD ────────────────────────────────────────────────────────────────────

export async function getRules(companyId: string): Promise<BankCategorisationRule[]> {
  const rows = (await sql`
    SELECT r.*, ga.account_code AS gl_account_code, ga.account_name AS gl_account_name,
           s.company_name AS supplier_name, c.name AS client_name
    FROM bank_categorisation_rules r
    LEFT JOIN gl_accounts ga ON ga.id = r.gl_account_id
    LEFT JOIN suppliers s ON s.id = r.supplier_id
    LEFT JOIN customers c ON c.id = r.client_id
    WHERE r.company_id = ${companyId}::UUID
    ORDER BY r.priority ASC, r.rule_name ASC
  `) as Record<string, unknown>[];
