}

export async function createRule(companyId: string, input: RuleCreateInput, userId: string): Promise<BankCategorisationRule> {
  const vatCode = input.vatCode || 'none';
  const rows = (await sql`
    INSERT INTO bank_categorisation_rules (
      company_id, rule_name, match_field, match_type, match_pattern,
      gl_account_id, supplier_id, client_id, description_template,
      priority, auto_create_entry, vat_code, created_by
    ) VALUES (
      ${companyId}::UUID, ${input.ruleName}, ${input.matchField}, ${input.matchType}, ${input.matchPattern},
      ${input.glAccountId || null}::UUID, ${input.supplierId || null}::UUID,
      ${input.clientId || null}::UUID,
      ${input.descriptionTemplate || null},
      ${input.priority || 100}, ${input.autoCreateEntry === true}, ${vatCode}, ${userId}
    ) RETURNING *
  `) as Record<string, unknown>[];
  log.info('Created bank rule', { id: rows[0]!.id, ruleName: input.ruleName }, 'accounting');
  return mapRuleRow(rows[0]!);
}

export async function updateRule(companyId: string, id: string, input: Partial<RuleCreateInput>): Promise<BankCategorisationRule> {
  const rows = (await sql`
    UPDATE bank_categorisation_rules SET
      rule_name = COALESCE(${input.ruleName || null}, rule_name),
      match_field = COALESCE(${input.matchField || null}, match_field),
      match_type = COALESCE(${input.matchType || null}, match_type),
      match_pattern = COALESCE(${input.matchPattern || null}, match_pattern),
      gl_account_id = COALESCE(${input.glAccountId || null}::UUID, gl_account_id),
      supplier_id = COALESCE(${input.supplierId || null}::UUID, supplier_id),
      client_id = COALESCE(${input.clientId || null}::UUID, client_id),
      description_template = COALESCE(${input.descriptionTemplate || null}, description_template),
      priority = COALESCE(${input.priority || null}, priority),
      auto_create_entry = COALESCE(${input.autoCreateEntry ?? null}, auto_create_entry),
      vat_code = COALESCE(${input.vatCode || null}, vat_code)
    WHERE company_id = ${companyId}::UUID AND id = ${id}::UUID RETURNING *
  `) as Record<string, unknown>[];
  if (!rows[0]) throw new Error(`Rule ${id} not found`);
  return mapRuleRow(rows[0]);
}

export async function deleteRule(companyId: string, id: string): Promise<void> {
  await sql`DELETE FROM bank_categorisation_rules WHERE company_id = ${companyId}::UUID AND id = ${id}::UUID`;
}

export async function deleteRules(companyId: string, ids: string[]): Promise<number> {
  if (ids.length === 0) return 0;
  const rows = await sql`
    DELETE FROM bank_categorisation_rules
    WHERE company_id = ${companyId}::UUID AND id = ANY(${ids}::UUID[])
    RETURNING id
  ` as { id: string }[];
  return rows.length;
}

export async function toggleRule(companyId: string, id: string, isActive: boolean): Promise<void> {
  await sql`UPDATE bank_categorisation_rules SET is_active = ${isActive} WHERE company_id = ${companyId}::UUID AND id = ${id}::UUID`;
}

// ── Apply Rules ─────────────────────────────────────────────────────────────

/** Lookup a GL account UUID by account code */
async function glAccountByCode(code: string): Promise<string> {
  const rows = (await sql`
    SELECT id FROM gl_accounts WHERE account_code = ${code} AND is_active = TRUE LIMIT 1
  `) as Record<string, unknown>[];
  if (rows.length === 0) throw new Error(`GL account ${code} not found`);
  return String(rows[0]!.id);
}

/** Convert rule match type to SQL ILIKE pattern */
function toSqlPattern(matchType: string, matchPattern: string): string {
  switch (matchType) {
    case 'contains': return `%${matchPattern}%`;
    case 'starts_with': return `${matchPattern}%`;
    case 'ends_with': return `%${matchPattern}`;
    case 'exact': return matchPattern;
    default: return `%${matchPattern}%`;
  }
}

export async function applyRules(companyId: string, 
  bankAccountId: string,
  userId: string
): Promise<RuleApplyResult> {
  try {
    // Get active rules ordered by priority (scoped to company)
    const rules = (await sql`
      SELECT * FROM bank_categorisation_rules
      WHERE company_id = ${companyId}::UUID AND is_active = true
      ORDER BY priority ASC
    `) as Record<string, unknown>[];

    if (rules.length === 0) return { applied: 0, skipped: 0, entries: [] };

    let totalApplied = 0;
    const entries: RuleApplyResult['entries'] = [];

    const autoCreateRules = rules.filter((r: Record<string, unknown>) => Boolean(r.auto_create_entry));
    const hasSuggestionRules = rules.some((r: Record<string, unknown>) => !r.auto_create_entry);

    if (hasSuggestionRules) {
      // Single-query approach: JOIN all suggestion-mode rules against all unmatched
      // transactions in one CTE, assign the highest-priority matching rule per tx.
      // ILIKE patterns are generated inline using CASE on match_type column —
      // one network round-trip to Neon regardless of rule count.
      const updated = (await sql`
        WITH matched AS (
          SELECT
            bt.id                                              AS tx_id,
            r.gl_account_id,
            r.supplier_id,
            r.client_id,
            r.rule_name,
            r.vat_code,
            ROW_NUMBER() OVER (PARTITION BY bt.id ORDER BY r.priority ASC) AS rn
          FROM bank_transactions bt
          JOIN bank_categorisation_rules r ON (
            r.company_id = ${companyId}::UUID
            AND r.is_active = true
            AND r.auto_create_entry = false
            AND (
              (r.match_field IN ('description', 'both')
                AND bt.description ILIKE
                  CASE r.match_type
                    WHEN 'contains'    THEN '%' || r.match_pattern || '%'
                    WHEN 'starts_with' THEN        r.match_pattern || '%'
                    WHEN 'ends_with'   THEN '%' || r.match_pattern
                    ELSE                           r.match_pattern
                  END)
              OR
              (r.match_field IN ('reference', 'both')
                AND bt.reference ILIKE
                  CASE r.match_type
                    WHEN 'contains'    THEN '%' || r.match_pattern || '%'
                    WHEN 'starts_with' THEN        r.match_pattern || '%'
                    WHEN 'ends_with'   THEN '%' || r.match_pattern
                    ELSE                           r.match_pattern
                  END)
            )
          )
          WHERE bt.bank_account_id = ${bankAccountId}::UUID
            AND bt.status IN ('imported', 'allocated')
            AND bt.suggested_gl_account_id IS NULL
            AND bt.suggested_supplier_id IS NULL
            AND bt.suggested_client_id IS NULL
            AND bt.suggested_category IS NULL
        ),
        top_match AS (SELECT * FROM matched WHERE rn = 1)
        UPDATE bank_transactions bt
        SET
          suggested_gl_account_id = tm.gl_account_id,
          suggested_supplier_id   = tm.supplier_id,
          suggested_client_id     = tm.client_id,
          suggested_category      = tm.rule_name,
          suggested_vat_code      = COALESCE(tm.vat_code, 'none')
        FROM top_match tm
        WHERE bt.id = tm.tx_id
        RETURNING bt.id, tm.rule_name
      `) as Record<string, unknown>[];

      for (const row of updated) {
        entries.push({ bankTxId: String(row.id), ruleName: String(row.rule_name), suggestion: true });
      }
      totalApplied += updated.length;

      // Backfill vat_code for already-suggested transactions (suggested before the vat_code column existed)
      await sql`
        UPDATE bank_transactions bt
        SET suggested_vat_code = r.vat_code
        FROM (
          SELECT DISTINCT ON (rule_name) rule_name, vat_code
          FROM bank_categorisation_rules
          WHERE company_id = ${companyId}::UUID AND is_active = true AND vat_code != 'none'
          ORDER BY rule_name, priority ASC
        ) r
        WHERE bt.bank_account_id = ${bankAccountId}::UUID
          AND bt.status IN ('imported', 'allocated')
          AND bt.suggested_category = r.rule_name
          AND bt.suggested_vat_code = 'none'
      `;
    }

    // Auto-create JE mode — sequential (each transaction needs its own JE)
    for (const rule of autoCreateRules) {
      const pattern = toSqlPattern(String(rule.match_type), String(rule.match_pattern));
      const field = String(rule.match_field);
      const ruleName = String(rule.rule_name);

      let matchingTxs: Record<string, unknown>[];
      if (field === 'description') {
        matchingTxs = (await sql`
          SELECT id, amount, transaction_date, description
          FROM bank_transactions
          WHERE bank_account_id = ${bankAccountId}::UUID
            AND status IN ('imported', 'allocated')
            AND matched_journal_line_id IS NULL
            AND description ILIKE ${pattern}
          ORDER BY transaction_date
        `) as Record<string, unknown>[];
      } else if (field === 'reference') {
        matchingTxs = (await sql`
          SELECT id, amount, transaction_date, description, reference
          FROM bank_transactions
          WHERE bank_account_id = ${bankAccountId}::UUID
            AND status IN ('imported', 'allocated')
            AND matched_journal_line_id IS NULL
            AND reference ILIKE ${pattern}
          ORDER BY transaction_date
        `) as Record<string, unknown>[];
      } else {
        matchingTxs = (await sql`
          SELECT id, amount, transaction_date, description, reference
          FROM bank_transactions
          WHERE bank_account_id = ${bankAccountId}::UUID
            AND status IN ('imported', 'allocated')
            AND matched_journal_line_id IS NULL
            AND (description ILIKE ${pattern} OR reference ILIKE ${pattern})
          ORDER BY transaction_date
        `) as Record<string, unknown>[];
      }

      for (const tx of matchingTxs) {
        const totalAmount = Math.abs(Number(tx.amount));
        const isDeposit = Number(tx.amount) > 0;
        const entryDesc = rule.description_template
          ? String(rule.description_template).replace('{description}', String(tx.description || '')).replace('{amount}', totalAmount.toFixed(2))
          : `Bank: ${tx.description || 'Categorised by rule'}`;

        // VAT splitting — mirrors allocateTransaction logic
        const vatCode = String(rule.vat_code || 'none');
        const hasVat = vatCode === 'standard';
        const netAmount = hasVat ? Math.round((totalAmount * 100 / 115) * 100) / 100 : totalAmount;
        const vatAmount = hasVat ? Math.round((totalAmount - netAmount) * 100) / 100 : 0;
        const vatAccountKey = isDeposit ? 'vat_output' as const : 'vat_input' as const;
        const mapVatType = vatCode === 'standard' ? 'standard' as const
          : vatCode === 'zero_rated' ? 'zero_rated' as const
          : vatCode === 'exempt' ? 'exempt' as const
          : undefined;

        let lines: JournalLineInput[];
        if (isDeposit) {
          lines = [
            { glAccountId: bankAccountId, debit: totalAmount, credit: 0, description: entryDesc },
            { glAccountId: String(rule.gl_account_id), debit: 0, credit: netAmount, description: entryDesc, vatType: mapVatType },
          ];
          if (hasVat) {
            const vatAcctId = await getSystemAccountId(vatAccountKey);
            lines.splice(1, 0, { glAccountId: vatAcctId, debit: 0, credit: vatAmount, description: `VAT @ 15%`, vatType: 'standard' });
          }
        } else {
          lines = [
            { glAccountId: String(rule.gl_account_id), debit: netAmount, credit: 0, description: entryDesc, vatType: mapVatType },
            { glAccountId: bankAccountId, debit: 0, credit: totalAmount, description: entryDesc },
          ];
          if (hasVat) {
            const vatAcctId = await getSystemAccountId(vatAccountKey);
            lines.splice(1, 0, { glAccountId: vatAcctId, debit: vatAmount, credit: 0, description: `VAT @ 15%`, vatType: 'standard' });
          }
        }

        const je = await createJournalEntry(companyId, {
          entryDate: tx.transaction_date instanceof Date
            ? tx.transaction_date.toISOString().split('T')[0]!
            : String(tx.transaction_date).split('T')[0]!,
          description: entryDesc,
          source: 'auto_bank_recon',
          lines,
        }, userId);
        await postJournalEntry(companyId, je.id, userId);

        const bankLineRows = (await sql`
          SELECT id FROM gl_journal_lines
          WHERE journal_entry_id = ${je.id}::UUID AND gl_account_id = ${bankAccountId}::UUID
          LIMIT 1
        `) as Record<string, unknown>[];

        if (bankLineRows[0]) {
          await sql`
            UPDATE bank_transactions
            SET status = 'allocated', matched_journal_line_id = ${bankLineRows[0].id}::UUID,
                allocation_type = 'account',
                allocated_entity_name = ${ruleName},
                updated_at = NOW()
            WHERE id = ${tx.id}::UUID
          `;
        }

        entries.push({ bankTxId: String(tx.id), ruleName, journalEntryId: je.id });
        totalApplied++;
      }
    }

    // Count remaining unmatched for the skipped total
    const remaining = (await sql`
      SELECT COUNT(*) AS cnt FROM bank_transactions
      WHERE bank_account_id = ${bankAccountId}::UUID
        AND status IN ('imported', 'allocated')
        AND suggested_gl_account_id IS NULL
        AND matched_journal_line_id IS NULL
    `) as Record<string, unknown>[];
    const skipped = Number(remaining[0]?.cnt ?? 0);

    log.info('Applied bank rules', { bankAccountId, applied: totalApplied, skipped }, 'accounting');
    return { applied: totalApplied, skipped, entries };
  } catch (err) {
    log.error('Failed to apply bank rules', { error: err }, 'accounting');
    throw err;
  }
}

// ── Helpers ─────────────────────────────────────────────────────────────────

function mapRuleRow(row: Record<string, unknown>): BankCategorisationRule {
  return {
    id: String(row.id),
    ruleName: String(row.rule_name),
    matchField: String(row.match_field) as BankCategorisationRule['matchField'],
    matchType: String(row.match_type) as BankCategorisationRule['matchType'],
    matchPattern: String(row.match_pattern ?? row.match_value ?? ''),
    glAccountId: row.gl_account_id ? String(row.gl_account_id) : undefined,
    supplierId: row.supplier_id ? String(row.supplier_id) : undefined,
    clientId: row.client_id ? String(row.client_id) : undefined,
    descriptionTemplate: row.description_template ? String(row.description_template) : undefined,
    priority: Number(row.priority),
    isActive: Boolean(row.is_active),
    autoCreateEntry: Boolean(row.auto_create_entry),
    vatCode: (row.vat_code || 'none') as BankCategorisationRule['vatCode'],
    createdBy: row.created_by ? String(row.created_by) : undefined,
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
    glAccountCode: row.gl_account_code ? String(row.gl_account_code) : undefined,
    glAccountName: row.gl_account_name ? String(row.gl_account_name) : undefined,
    supplierName: row.supplier_name ? String(row.supplier_name) : undefined,
    clientName: row.client_name ? String(row.client_name) : undefined,
  };
}

/**
 * PRD-060: FibreFlow Accounting Module — Phase 4
 * Bank Allocation Service — Sage Process Bank equivalent (allocate, split, reverse)
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { createJournalEntry, postJournalEntry } from './journalEntryService';
import { getSystemAccountId } from './systemAccountResolver';
import { mapTxRow } from './bankTransactionQueryService';
import type { BankTransaction } from '../types/bank.types';
import type { JournalLineInput } from '../types/gl.types';

type Row = Record<string, unknown>;

export type AllocationType = 'account' | 'supplier' | 'customer';

export interface SplitLine {
  contraAccountId: string;
  amount: number;
  description?: string;
  vatCode?: string;
}

// ── Allocate ──────────────────────────────────────────────────────────────────

/**
 * Allocate a bank transaction — Sage Process Bank equivalent.
 * Supports: account (GL), supplier (AP payment), customer (AR receipt).
 */
export async function allocateTransaction(
  companyId: string, bankTxId: string, contraAccountId: string | null, userId: string,
  description?: string, allocType: AllocationType = 'account', entityId?: string,
  vatCode?: string, cc1Id?: string, cc2Id?: string, buId?: string,
): Promise<{ journalEntryId: string; bankTransaction: BankTransaction }> {
  const txRows = (await sql`SELECT * FROM bank_transactions WHERE id = ${bankTxId}::UUID`) as Row[];
  if (txRows.length === 0) throw new Error(`Bank transaction ${bankTxId} not found`);
  const tx = txRows[0]!;
  if (tx.status !== 'imported') throw new Error(`Transaction already ${tx.status} — cannot allocate`);

  const totalAmount = Math.abs(Number(tx.amount));
  const bankAccountId = String(tx.bank_account_id);
  const txDate = tx.transaction_date instanceof Date
    ? (tx.transaction_date.toISOString().split('T')[0] ?? '')
    : (String(tx.transaction_date).split('T')[0] ?? '');
  const isSpent = Number(tx.amount) < 0;

  const hasVat = vatCode === 'standard';
  const vatRate = hasVat ? 15 : 0;
  const netAmount = hasVat ? Math.round((totalAmount * 100 / 115) * 100) / 100 : totalAmount;
  const vatAmount = hasVat ? Math.round((totalAmount - netAmount) * 100) / 100 : 0;
  const vatAccountKey = isSpent ? 'vat_input' as const : 'vat_output' as const;
  const mapVatType = vatCode === 'standard' ? 'standard' as const
    : vatCode === 'zero_rated' ? 'zero_rated' as const
    : vatCode === 'exempt' ? 'exempt' as const : undefined;

  let lines: JournalLineInput[];
  let source: import('../types/gl.types').GLEntrySource;
  let entryDesc = '';
  let allocEntityName: string | null = null;

  if (allocType === 'supplier' && entityId) {
    const apAccountId = await getSystemAccountId('payable');
    const supRows = (await sql`SELECT name FROM suppliers WHERE id = ${entityId}::UUID`) as Row[];
    const supName = supRows.length > 0 ? String(supRows[0]!.name) : `Supplier #${entityId}`;
    allocEntityName = supName;
    entryDesc = description || `Payment to ${supName}`;
    source = 'auto_supplier_payment';
    lines = [
      { glAccountId: apAccountId, debit: netAmount, credit: 0, description: entryDesc, vatType: mapVatType },
      { glAccountId: bankAccountId, debit: 0, credit: totalAmount, description: entryDesc },
    ];
    if (hasVat) {
      const vatAcctId = await getSystemAccountId(vatAccountKey);
      lines.splice(1, 0, { glAccountId: vatAcctId, debit: vatAmount, credit: 0, description: `VAT @ ${vatRate}%`, vatType: 'standard' });
    }
  } else if (allocType === 'customer' && entityId) {
    const arAccountId = await getSystemAccountId('receivable');
    const custRows = (await sql`SELECT name FROM customers WHERE id = ${entityId}::UUID`) as Row[];
    const custName = custRows.length > 0 ? String(custRows[0]!.name) : `Customer #${entityId}`;
    allocEntityName = custName;
    entryDesc = description || `Receipt from ${custName}`;
    source = 'auto_payment';
    lines = [
      { glAccountId: bankAccountId, debit: totalAmount, credit: 0, description: entryDesc },
      { glAccountId: arAccountId, debit: 0, credit: netAmount, description: entryDesc, vatType: mapVatType },
    ];
    if (hasVat) {
      const vatAcctId = await getSystemAccountId(vatAccountKey);
      lines.push({ glAccountId: vatAcctId, debit: 0, credit: vatAmount, description: `VAT @ ${vatRate}%`, vatType: 'standard' });
    }
  } else {
    if (!contraAccountId) throw new Error('contraAccountId is required for account allocation');
    const acctRows = (await sql`SELECT account_code, account_name FROM gl_accounts WHERE id = ${contraAccountId}::UUID`) as Row[];
    allocEntityName = acctRows.length > 0 ? `${String(acctRows[0]!.account_code)} ${String(acctRows[0]!.account_name)}` : null;
    entryDesc = description || String(tx.description || 'Bank allocation');
    source = 'auto_bank_recon';
    if (!isSpent) {
      lines = [
        { glAccountId: bankAccountId, debit: totalAmount, credit: 0, description: entryDesc },
        { glAccountId: contraAccountId, debit: 0, credit: netAmount, description: entryDesc, vatType: mapVatType },
      ];
      if (hasVat) {
        const vatAcctId = await getSystemAccountId(vatAccountKey);
        lines.push({ glAccountId: vatAcctId, debit: 0, credit: vatAmount, description: `VAT @ ${vatRate}%`, vatType: 'standard' });
      }
    } else {
      lines = [{ glAccountId: contraAccountId, debit: netAmount, credit: 0, description: entryDesc, vatType: mapVatType }];
      if (hasVat) {
        const vatAcctId = await getSystemAccountId(vatAccountKey);
        lines.push({ glAccountId: vatAcctId, debit: vatAmount, credit: 0, description: `VAT @ ${vatRate}%`, vatType: 'standard' });
      }
      lines.push({ glAccountId: bankAccountId, debit: 0, credit: totalAmount, description: entryDesc });
    }
  }

  const linesWithDims = lines.map(l =>
    l.glAccountId === bankAccountId ? l : { ...l, costCenterId: cc1Id || l.costCenterId, buId: buId || l.buId }
  );

  const je = await createJournalEntry(companyId, {
    entryDate: txDate, description: entryDesc, source, sourceDocumentId: bankTxId, lines: linesWithDims,
  }, userId);
  await postJournalEntry(companyId, je.id, userId);

  const jeLines = (await sql`
    SELECT id FROM gl_journal_lines
    WHERE journal_entry_id = ${je.id}::UUID AND gl_account_id = ${bankAccountId}::UUID LIMIT 1`) as Row[];
  const journalLineId = jeLines.length > 0 ? String(jeLines[0]!.id) : null;

  if (journalLineId) {
    await sql`
      UPDATE bank_transactions
      SET status = 'allocated', matched_journal_line_id = ${journalLineId}::UUID,
          allocation_type = ${allocType}, allocated_entity_name = ${allocEntityName},
          cc1_id = ${cc1Id || null}::UUID, cc2_id = ${cc2Id || null}::UUID,
          bu_id = ${buId || null}::UUID, updated_at = NOW()
      WHERE id = ${bankTxId}::UUID`;
  }

  if (allocType === 'customer' && entityId) {
    const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
    let paymentUserId: string | null = userId;
    if (!uuidPattern.test(userId)) {
      const fallback = (await sql`SELECT id FROM users WHERE id::TEXT ~ '^[0-9a-f]{8}-' LIMIT 1`) as Row[];
      paymentUserId = fallback.length > 0 ? String(fallback[0]!.id) : null;
    }
    if (paymentUserId) {
      await sql`
        INSERT INTO customer_payments (
          company_id, client_id, payment_date, total_amount, payment_method,
          bank_reference, bank_account_id, description, status,
          gl_journal_entry_id, created_by, confirmed_by, confirmed_at
        ) VALUES (
          ${companyId}::UUID, ${entityId}::UUID, ${txDate}, ${totalAmount}, 'eft',
          ${tx.reference || tx.bank_reference || tx.description || null},
          ${bankAccountId}::UUID, ${entryDesc}, 'confirmed',
          ${je.id}::UUID, ${paymentUserId}::UUID, ${paymentUserId}::UUID, NOW()
        )`;
    }
  }

  log.info('Allocated bank transaction', { bankTxId, journalEntryId: je.id, allocType, entityId, contraAccountId }, 'accounting');
  const updated = (await sql`SELECT * FROM bank_transactions WHERE id = ${bankTxId}::UUID`) as Row[];
  return { journalEntryId: je.id, bankTransaction: mapTxRow(updated[0]!) };
}

// ── Split Allocate ────────────────────────────────────────────────────────────

export async function splitAllocateTransaction(
  companyId: string, bankTxId: string, lines: SplitLine[], userId: string,
): Promise<{ journalEntryId: string; bankTransaction: BankTransaction }> {
  const txRows = (await sql`SELECT * FROM bank_transactions WHERE id = ${bankTxId}::UUID`) as Row[];
  if (txRows.length === 0) throw new Error(`Bank transaction ${bankTxId} not found`);
  const tx = txRows[0]!;
  if (tx.status !== 'imported') throw new Error(`Transaction already ${tx.status} — cannot split allocate`);
  if (!lines || lines.length === 0) throw new Error('At least one split line is required');

  const totalAmount = Math.abs(Number(tx.amount));
  const linesTotal = lines.reduce((sum, l) => sum + Number(l.amount), 0);
  if (Math.abs(linesTotal - totalAmount) > 0.01) {
    throw new Error(`Split lines total R${linesTotal.toFixed(2)} does not equal transaction amount R${totalAmount.toFixed(2)}`);
  }

  const bankAccountId = String(tx.bank_account_id);
  const txDate = tx.transaction_date instanceof Date
    ? (tx.transaction_date.toISOString().split('T')[0] ?? '')
    : (String(tx.transaction_date).split('T')[0] ?? '');
  const isSpent = Number(tx.amount) < 0;
  const entryDesc = String(tx.description || 'Split bank allocation');
  const journalLines: JournalLineInput[] = [];

  for (const line of lines) {
    const lineAmount = Number(line.amount);
    const hasVat = line.vatCode === 'standard';
    const netAmount = hasVat ? Math.round((lineAmount * 100 / 115) * 100) / 100 : lineAmount;
    const vatAmount = hasVat ? Math.round((lineAmount - netAmount) * 100) / 100 : 0;
    const vatAccountKey = isSpent ? 'vat_input' as const : 'vat_output' as const;
    const lineDesc = line.description || entryDesc;
    const mapVatType = line.vatCode === 'standard' ? 'standard' as const
      : line.vatCode === 'zero_rated' ? 'zero_rated' as const
      : line.vatCode === 'exempt' ? 'exempt' as const : undefined;
    if (isSpent) {
      journalLines.push({ glAccountId: line.contraAccountId, debit: netAmount, credit: 0, description: lineDesc, vatType: mapVatType });
      if (hasVat) {
        const vatAcctId = await getSystemAccountId(vatAccountKey);
        journalLines.push({ glAccountId: vatAcctId, debit: vatAmount, credit: 0, description: 'VAT @ 15%', vatType: 'standard' });
      }
    } else {
      journalLines.push({ glAccountId: line.contraAccountId, debit: 0, credit: netAmount, description: lineDesc, vatType: mapVatType });
      if (hasVat) {
        const vatAcctId = await getSystemAccountId(vatAccountKey);
        journalLines.push({ glAccountId: vatAcctId, debit: 0, credit: vatAmount, description: 'VAT @ 15%', vatType: 'standard' });
      }
    }
  }

  if (isSpent) {
    journalLines.push({ glAccountId: bankAccountId, debit: 0, credit: totalAmount, description: entryDesc });
  } else {
    journalLines.unshift({ glAccountId: bankAccountId, debit: totalAmount, credit: 0, description: entryDesc });
  }

  const je = await createJournalEntry(companyId, {
    entryDate: txDate, description: entryDesc, source: 'auto_bank_recon', sourceDocumentId: bankTxId, lines: journalLines,
  }, userId);
  await postJournalEntry(companyId, je.id, userId);

  const jeLines = (await sql`
    SELECT id FROM gl_journal_lines
    WHERE journal_entry_id = ${je.id}::UUID AND gl_account_id = ${bankAccountId}::UUID LIMIT 1`) as Row[];
  const journalLineId = jeLines.length > 0 ? String(jeLines[0]!.id) : null;

  if (journalLineId) {
    await sql`
      UPDATE bank_transactions
      SET status = 'allocated', matched_journal_line_id = ${journalLineId}::UUID,
          allocation_type = 'account', allocated_entity_name = 'Split allocation', updated_at = NOW()
      WHERE id = ${bankTxId}::UUID`;
  }

  log.info('Split-allocated bank transaction', { bankTxId, journalEntryId: je.id, lineCount: lines.length }, 'accounting');
  const updated = (await sql`SELECT * FROM bank_transactions WHERE id = ${bankTxId}::UUID`) as Row[];
  return { journalEntryId: je.id, bankTransaction: mapTxRow(updated[0]!) };
}

// ── Reverse Reconciled ────────────────────────────────────────────────────────

export async function reverseReconciledTransaction(
  companyId: string, bankTxId: string, userId: string
): Promise<void> {
  const txRows = (await sql`SELECT * FROM bank_transactions WHERE id = ${bankTxId}::UUID`) as Row[];
  const tx = txRows[0];
  if (!tx) throw new Error('Transaction not found');
  if (tx.status !== 'allocated' && tx.status !== 'matched' && tx.status !== 'reconciled') {
    throw new Error('Can only reverse allocated, matched, or reconciled transactions');
  }
  if (tx.matched_journal_line_id) {
    const jlRows = (await sql`
      SELECT journal_entry_id FROM gl_journal_lines WHERE id = ${tx.matched_journal_line_id}::UUID`) as Row[];
    if (jlRows.length > 0 && jlRows[0]!.journal_entry_id) {
      const { reverseJournalEntry } = await import('./journalEntryService');
      try {
        await reverseJournalEntry('', String(jlRows[0]!.journal_entry_id), userId);
      } catch (e) {
        throw new Error(`Cannot reverse: ${e instanceof Error ? e.message : 'Journal reversal failed'}`);
      }
    }
  }
  await sql`
    UPDATE bank_transactions
    SET status = 'imported', matched_journal_line_id = NULL, reconciliation_id = NULL,
        linked_po_id = NULL, linked_asset_id = NULL, linked_fleet_fuel_id = NULL,
        linked_fleet_service_id = NULL, allocation_type = NULL, allocated_entity_name = NULL,
        updated_at = NOW()
    WHERE id = ${bankTxId}::UUID`;
  log.info('Reversed reconciled bank transaction', { bankTxId, userId }, 'accounting');
}

/**
 * PRD-060: FibreFlow Accounting Module
 * Double-Entry Validation Utilities
 *
 * Core validation logic for journal entries ensuring
 * fundamental accounting equation integrity.
 */

import type { JournalLineInput, JournalValidationResult, LineValidationResult } from '../types/gl.types';

/**
 * Validate a single journal line.
 * Rules:
 * - Must have a valid glAccountId
 * - Debit and credit must be >= 0
 * - Exactly one of debit/credit must be > 0 (not both, not neither)
 */
export function validateJournalLine(line: JournalLineInput): LineValidationResult {
  if (!line.glAccountId || line.glAccountId.trim() === '') {
    return { valid: false, error: 'GL account ID is required' };
  }

  if (line.debit < 0 || line.credit < 0) {
    return { valid: false, error: 'Debit and credit amounts cannot be negative' };
  }

  if (line.debit > 0 && line.credit > 0) {
    return { valid: false, error: 'A line must have either debit or credit, not both. One must be zero.' };
  }

  if (line.debit === 0 && line.credit === 0) {
    return { valid: false, error: 'A line must have a non-zero debit or credit amount' };
  }

  return { valid: true };
}

/**
 * Validate an entire journal entry (set of lines).
 * Rules:
 * - Must have at least 2 lines
 * - Each line must pass individual validation
 * - Total debits must equal total credits (exact match, no tolerance)
 */
export function validateJournalEntry(lines: JournalLineInput[]): JournalValidationResult {
  const errors: string[] = [];

  if (!lines || lines.length === 0) {
    return {
      valid: false,
      totalDebit: 0,
      totalCredit: 0,
      difference: 0,
      errors: ['Journal entry must have at least one line'],
    };
  }

  if (lines.length < 2) {
    errors.push('Journal entry must have at least 2 lines for double-entry');
  }

  // Validate individual lines
  for (let i = 0; i < lines.length; i++) {
    const lineResult = validateJournalLine(lines[i]!);
    if (!lineResult.valid) {
      errors.push(`Line ${i + 1}: ${lineResult.error}`);
    }
  }

  // Calculate totals using fixed-point arithmetic to avoid floating-point issues
  const totalDebit = roundToCents(
    lines.reduce((sum, line) => sum + (line.debit || 0), 0)
  );
  const totalCredit = roundToCents(
    lines.reduce((sum, line) => sum + (line.credit || 0), 0)
  );
  const difference = roundToCents(Math.abs(totalDebit - totalCredit));

  if (difference > 0) {
    errors.push(
      `Entry is not balanced: total debit R${totalDebit.toFixed(2)} != total credit R${totalCredit.toFixed(2)} (difference: R${difference.toFixed(2)})`
    );
  }

  return {
    valid: errors.length === 0,
    totalDebit,
    totalCredit,
    difference,
    errors,
  };
}

/**
 * Generate a journal entry number in format JE-YYYY-NNNNN
 */
export function formatJournalEntryNumber(year: number, sequence: number): string {
  return `JE-${year}-${String(sequence).padStart(5, '0')}`;
}

/**
 * Generate a supplier payment number in format PAY-YYYY-NNNNN
 */
export function formatPaymentNumber(prefix: string, year: number, sequence: number): string {
  return `${prefix}-${year}-${String(sequence).padStart(5, '0')}`;
}

/**
 * Round to 2 decimal places (cents) to avoid floating-point arithmetic issues
 */
export function roundToCents(value: number): number {
  return Math.round(value * 100) / 100;
}

/**
 * Customer Sales Order Service — CRUD with items
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

type Row = Record<string, unknown>;

export interface SalesOrderItem {
  id: string;
  salesOrderId: string;
  lineNumber: number;
  description: string;
  quantity: number;
  unitPrice: number;
  taxRate: number;
  lineTotal: number;
}

export interface SalesOrder {
  id: string;
  orderNumber: string;
  customerId: string | null;
  customerName: string;
  orderDate: string;
  deliveryDate: string | null;
  reference: string | null;
  status: string;
  subtotal: number;
  taxAmount: number;
  totalAmount: number;
  notes: string | null;
  internalNotes: string | null;
  createdAt: string;
  updatedAt: string;
  items?: SalesOrderItem[];
}

interface SalesOrderFilters {
  status?: string;
  search?: string;
  limit?: number;
  offset?: number;
}

interface SalesOrderInput {
  customer_id?: string;
  order_date?: string;
  delivery_date?: string;
  reference?: string;
  notes?: string;
  internal_notes?: string;
  items: { description: string; quantity: number; unit_price: number; tax_rate?: number }[];
}

function mapOrder(r: Row): SalesOrder {
  return {
    id: String(r.id),
    orderNumber: String(r.order_number),
    customerId: r.customer_id != null ? String(r.customer_id) : null,
    customerName: r.customer_name ? String(r.customer_name) : '',
    orderDate: String(r.order_date),
    deliveryDate: r.delivery_date != null ? String(r.delivery_date) : null,
    reference: r.reference != null ? String(r.reference) : null,
    status: String(r.status),
    subtotal: Number(r.subtotal),
    taxAmount: Number(r.tax_amount),
    totalAmount: Number(r.total_amount),
    notes: r.notes != null ? String(r.notes) : null,
    internalNotes: r.internal_notes != null ? String(r.internal_notes) : null,
    createdAt: String(r.created_at),
    updatedAt: String(r.updated_at),
  };
}

function mapItem(r: Row): SalesOrderItem {
  return {
    id: String(r.id),
    salesOrderId: String(r.sales_order_id),
    lineNumber: Number(r.line_number),
    description: String(r.description),
    quantity: Number(r.quantity),
    unitPrice: Number(r.unit_price),
    taxRate: Number(r.tax_rate),
    lineTotal: Number(r.line_total),
  };
}

async function nextOrderNumber(companyId: string): Promise<string> {
  // Use company_document_numbers for sequential numbering
  const rows = (await sql`
    INSERT INTO company_document_numbers (company_id, document_type, prefix, next_number)
    VALUES (${companyId}::UUID, 'sales_order', 'SO-', 1)
    ON CONFLICT (company_id, document_type)
    DO UPDATE SET next_number = company_document_numbers.next_number + 1
    RETURNING next_number - 1 AS current_number, prefix
  `) as Row[];

  if (rows.length === 0) return 'SO-00001';
  const num = Number(rows[0]!.current_number);
  const prefix = String(rows[0]!.prefix || 'SO-');
  return `${prefix}${String(num).padStart(5, '0')}`;
}

function calcTotals(items: SalesOrderInput['items']) {
  let subtotal = 0;
  let taxAmount = 0;
  for (const item of items) {
    const lt = Math.round(item.quantity * item.unit_price * 100) / 100;
    const lineTax = Math.round(lt * ((item.tax_rate ?? 15) / 100) * 100) / 100;
    subtotal += lt;
    taxAmount += lineTax;
  }
  return {
    subtotal: Math.round(subtotal * 100) / 100,
    taxAmount: Math.round(taxAmount * 100) / 100,
    totalAmount: Math.round((subtotal + taxAmount) * 100) / 100,
  };
}

export async function getSalesOrders(companyId: string, filters?: SalesOrderFilters): Promise<{ orders: SalesOrder[]; total: number }> {
  const limit = filters?.limit || 100;
  const offset = filters?.offset || 0;
  let rows: Row[];
  let countRows: Row[];

  if (filters?.search && filters?.status) {
    const pattern = `%${filters.search}%`;
    rows = (await sql`
      SELECT so.*, c.name AS customer_name
      FROM customer_sales_orders so
      LEFT JOIN customers c ON c.id = so.customer_id
      WHERE so.company_id = ${companyId}::UUID
        AND so.status = ${filters.status}
        AND (so.order_number ILIKE ${pattern} OR c.name ILIKE ${pattern} OR so.reference ILIKE ${pattern})
      ORDER BY so.created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`
      SELECT COUNT(*) AS cnt
      FROM customer_sales_orders so
      LEFT JOIN customers c ON c.id = so.customer_id
      WHERE so.company_id = ${companyId}::UUID
        AND so.status = ${filters.status}
        AND (so.order_number ILIKE ${pattern} OR c.name ILIKE ${pattern} OR so.reference ILIKE ${pattern})
    `) as Row[];
  } else if (filters?.search) {
    const pattern = `%${filters.search}%`;
    rows = (await sql`
      SELECT so.*, c.name AS customer_name
      FROM customer_sales_orders so
      LEFT JOIN customers c ON c.id = so.customer_id
      WHERE so.company_id = ${companyId}::UUID
        AND (so.order_number ILIKE ${pattern} OR c.name ILIKE ${pattern} OR so.reference ILIKE ${pattern})
      ORDER BY so.created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`
      SELECT COUNT(*) AS cnt
      FROM customer_sales_orders so
      LEFT JOIN customers c ON c.id = so.customer_id
      WHERE so.company_id = ${companyId}::UUID
        AND (so.order_number ILIKE ${pattern} OR c.name ILIKE ${pattern} OR so.reference ILIKE ${pattern})
    `) as Row[];
  } else if (filters?.status) {
    rows = (await sql`
      SELECT so.*, c.name AS customer_name
      FROM customer_sales_orders so
      LEFT JOIN customers c ON c.id = so.customer_id
      WHERE so.company_id = ${companyId}::UUID AND so.status = ${filters.status}
      ORDER BY so.created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`
      SELECT COUNT(*) AS cnt FROM customer_sales_orders so
      WHERE so.company_id = ${companyId}::UUID AND so.status = ${filters.status}
    `) as Row[];
  } else {
    rows = (await sql`
      SELECT so.*, c.name AS customer_name
      FROM customer_sales_orders so
      LEFT JOIN customers c ON c.id = so.customer_id
      WHERE so.company_id = ${companyId}::UUID
      ORDER BY so.created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`
      SELECT COUNT(*) AS cnt FROM customer_sales_orders so
      WHERE so.company_id = ${companyId}::UUID
    `) as Row[];
  }

  return { orders: rows.map(mapOrder), total: Number(countRows[0]?.cnt || 0) };
}

export async function getSalesOrder(companyId: string, id: string): Promise<SalesOrder | null> {
  const rows = (await sql`
    SELECT so.*, c.name AS customer_name
    FROM customer_sales_orders so
    LEFT JOIN customers c ON c.id = so.customer_id
    WHERE so.id = ${id}::UUID AND so.company_id = ${companyId}::UUID
  `) as Row[];
  if (rows.length === 0) return null;
  const order = mapOrder(rows[0]!);
  const itemRows = (await sql`
    SELECT * FROM customer_sales_order_items
    WHERE sales_order_id = ${id}::UUID ORDER BY line_number
  `) as Row[];
  order.items = itemRows.map(mapItem);
  return order;
}

export async function createSalesOrder(companyId: string, input: SalesOrderInput, userId?: string): Promise<SalesOrder> {
  const orderNumber = await nextOrderNumber(companyId);
  const { subtotal, taxAmount, totalAmount } = calcTotals(input.items);
  const orderDate = input.order_date || new Date().toISOString().split('T')[0];

  const rows = (await sql`
    INSERT INTO customer_sales_orders (
      company_id, order_number, customer_id, order_date, delivery_date,
      reference, subtotal, tax_amount, total_amount, notes, internal_notes, created_by
    ) VALUES (
      ${companyId}::UUID, ${orderNumber}, ${input.customer_id || null},
      ${orderDate}, ${input.delivery_date || null}, ${input.reference || null},
      ${subtotal}, ${taxAmount}, ${totalAmount},
      ${input.notes || null}, ${input.internal_notes || null}, ${userId || null}
    ) RETURNING *
  `) as Row[];

  const order = mapOrder(rows[0]!);
  for (let i = 0; i < input.items.length; i++) {
    const item = input.items[i];
    if (!item) continue;
    const lineTotal = Math.round(item.quantity * item.unit_price * 100) / 100;
    await sql`
      INSERT INTO customer_sales_order_items (
        sales_order_id, line_number, description, quantity, unit_price, tax_rate, line_total
      ) VALUES (
        ${order.id}::UUID, ${i + 1}, ${item.description}, ${item.quantity},
        ${item.unit_price}, ${item.tax_rate ?? 15}, ${lineTotal}
      )
    `;
  }
  log.info('Sales order created', { orderNumber, totalAmount });
  return (await getSalesOrder(companyId, order.id))!;
}

export async function updateSalesOrder(companyId: string, id: string, input: SalesOrderInput): Promise<SalesOrder | null> {
  const existing = await getSalesOrder(companyId, id);
  if (!existing || existing.status !== 'draft') return null;
  const { subtotal, taxAmount, totalAmount } = calcTotals(input.items);

  await sql`
    UPDATE customer_sales_orders SET
      customer_id = ${input.customer_id || existing.customerId},
      order_date = ${input.order_date || existing.orderDate},
      delivery_date = ${input.delivery_date || null},
      reference = ${input.reference || null},
      subtotal = ${subtotal}, tax_amount = ${taxAmount}, total_amount = ${totalAmount},
      notes = ${input.notes || null}, internal_notes = ${input.internal_notes || null},
      updated_at = NOW()
    WHERE id = ${id}::UUID AND company_id = ${companyId}::UUID AND status = 'draft'
  `;

  await sql`DELETE FROM customer_sales_order_items WHERE sales_order_id = ${id}::UUID`;
  for (let i = 0; i < input.items.length; i++) {
    const item = input.items[i];
    if (!item) continue;
    const lineTotal = Math.round(item.quantity * item.unit_price * 100) / 100;
    await sql`
      INSERT INTO customer_sales_order_items (
        sales_order_id, line_number, description, quantity, unit_price, tax_rate, line_total
      ) VALUES (
        ${id}::UUID, ${i + 1}, ${item.description}, ${item.quantity},
        ${item.unit_price}, ${item.tax_rate ?? 15}, ${lineTotal}
      )
    `;
  }
  log.info('Sales order updated', { id });
  return getSalesOrder(companyId, id);
}

export async function deleteSalesOrder(companyId: string, id: string): Promise<boolean> {
  const rows = (await sql`
    DELETE FROM customer_sales_orders
    WHERE id = ${id}::UUID AND company_id = ${companyId}::UUID AND status = 'draft'
    RETURNING id
  `) as Row[];
  return rows.length > 0;
}

/**
 * PRD-060: FibreFlow Accounting Module — Phase 2
 * Supplier Payment Service
 */

import { sql, withTransaction } from '@/lib/neon';
import { log } from '@/lib/logger';
import { createJournalEntry, postJournalEntry } from './journalEntryService';
import { getSystemAccount, getSystemAccountId } from './systemAccountResolver';
import { validatePaymentAllocations } from '../utils/paymentAllocation';
import type {
  SupplierPayment,
  PaymentAllocation,
  PaymentAllocationInput,
  PaymentMethod,
  PaymentStatus,
  InvoiceForAllocation,
} from '../types/ap.types';
import type { JournalLineInput } from '../types/gl.types';
type Row = Record<string, unknown>;


interface PaymentFilters {
  status?: PaymentStatus;
  supplierId?: number;
  limit?: number;
  offset?: number;
}

export interface CreatePaymentInput {
  supplierId: number;
  paymentDate: string;
  totalAmount: number;
  paymentMethod?: PaymentMethod;
  bankAccountId?: string;
  reference?: string;
  description?: string;
  allocations: PaymentAllocationInput[];
}

export async function getSupplierPayments(companyId: string, filters?: PaymentFilters): Promise<{
  payments: SupplierPayment[];
  total: number;
}> {
  try {
    // TODO: Apply pagination cap to all list endpoints (M16)
    const limit = Math.min(filters?.limit || 50, 200);
    const offset = filters?.offset || 0;
    let rows: Row[];
    let countRows: Row[];

    if (filters?.status && filters?.supplierId) {
      rows = (await sql`
        SELECT sp.*, s.name AS supplier_name
        FROM supplier_payments sp LEFT JOIN suppliers s ON s.id = sp.supplier_id
        WHERE sp.company_id = ${companyId}::UUID
          AND sp.status = ${filters.status} AND sp.supplier_id = ${filters.supplierId}
        ORDER BY sp.payment_date DESC LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`
        SELECT COUNT(*) AS cnt FROM supplier_payments
        WHERE company_id = ${companyId}::UUID
          AND status = ${filters.status} AND supplier_id = ${filters.supplierId}
      `) as Row[];
    } else if (filters?.status) {
      rows = (await sql`
        SELECT sp.*, s.name AS supplier_name
        FROM supplier_payments sp LEFT JOIN suppliers s ON s.id = sp.supplier_id
        WHERE sp.company_id = ${companyId}::UUID AND sp.status = ${filters.status}
        ORDER BY sp.payment_date DESC LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`
        SELECT COUNT(*) AS cnt FROM supplier_payments
        WHERE company_id = ${companyId}::UUID AND status = ${filters.status}
      `) as Row[];
    } else if (filters?.supplierId) {
      rows = (await sql`
        SELECT sp.*, s.name AS supplier_name
        FROM supplier_payments sp LEFT JOIN suppliers s ON s.id = sp.supplier_id
        WHERE sp.company_id = ${companyId}::UUID AND sp.supplier_id = ${filters.supplierId}
        ORDER BY sp.payment_date DESC LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`
        SELECT COUNT(*) AS cnt FROM supplier_payments
        WHERE company_id = ${companyId}::UUID AND supplier_id = ${filters.supplierId}
      `) as Row[];
    } else {
      rows = (await sql`
        SELECT sp.*, s.name AS supplier_name
        FROM supplier_payments sp LEFT JOIN suppliers s ON s.id = sp.supplier_id
        WHERE sp.company_id = ${companyId}::UUID
        ORDER BY sp.payment_date DESC LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`
        SELECT COUNT(*) AS cnt FROM supplier_payments WHERE company_id = ${companyId}::UUID
      `) as Row[];
    }

    return { payments: rows.map(mapPaymentRow), total: Number(countRows[0]!.cnt) };
  } catch (err) {
    log.error('Failed to get supplier payments', { error: err }, 'accounting');
    throw err;
  }
}

export async function getSupplierPaymentById(companyId: string, 
  id: string
): Promise<(SupplierPayment & { allocations: PaymentAllocation[] }) | null> {
  try {
    const rows = (await sql`
      SELECT sp.*, s.name AS supplier_name
      FROM supplier_payments sp LEFT JOIN suppliers s ON s.id = sp.supplier_id
      WHERE sp.id = ${id} AND sp.company_id = ${companyId}::UUID
    `) as Row[];
    if (rows.length === 0) return null;

    const allocRows = (await sql`
      SELECT pa.*, si.invoice_number
      FROM payment_allocations pa
      LEFT JOIN supplier_invoices si ON si.id = pa.invoice_id
      WHERE pa.payment_id = ${id}
    `) as Row[];

    return { ...mapPaymentRow(rows[0]!), allocations: allocRows.map(mapAllocationRow) };
  } catch (err) {
    log.error('Failed to get supplier payment', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function createSupplierPayment(companyId: string, 
  input: CreatePaymentInput,
  userId: string
): Promise<SupplierPayment> {
  try {
    // Load invoices for allocation validation
    const invoiceIds = input.allocations.map(a => a.invoiceId);
    const invoiceRows = (await sql`
      SELECT id, invoice_number, total_amount, amount_paid, balance
      FROM supplier_invoices
      WHERE id = ANY(${invoiceIds}::UUID[])
    `) as Row[];

    const invoices: InvoiceForAllocation[] = invoiceRows.map((r: Row) => ({
      id: String(r.id),
      invoiceNumber: String(r.invoice_number),
      totalAmount: Number(r.total_amount),
      amountPaid: Number(r.amount_paid),
      balance: Number(r.balance),
    }));

    const validation = validatePaymentAllocations(input.totalAmount, input.allocations, invoices);
    if (!validation.valid) {
      throw new Error(`Invalid allocations: ${validation.errors.join('; ')}`);
    }

    const paymentRow = await withTransaction(async (tx) => {
      const rows = (await tx`
        INSERT INTO supplier_payments (
          company_id, supplier_id, payment_date, total_amount, payment_method,
          bank_account_id, reference, description, created_by
        ) VALUES (
          ${companyId}::UUID, ${input.supplierId}, ${input.paymentDate}, ${input.totalAmount},
          ${input.paymentMethod || 'eft'}, ${input.bankAccountId || null},
          ${input.reference || null}, ${input.description || null}, ${userId}::UUID
        ) RETURNING *
      `) as Row[];

      const paymentId = String(rows[0]!.id);

      for (const alloc of input.allocations) {
        await tx`
          INSERT INTO payment_allocations (payment_id, invoice_id, amount_allocated)
          VALUES (${paymentId}::UUID, ${alloc.invoiceId}::UUID, ${alloc.amount})
        `;
      }

      return rows[0] as Row;
    });

    log.info('Created supplier payment', {
      paymentId: String(paymentRow.id),
      paymentNumber: String(paymentRow.payment_number),
      totalAmount: input.totalAmount,
    }, 'accounting');

    return mapPaymentRow(paymentRow);
  } catch (err) {
    log.error('Failed to create supplier payment', { error: err }, 'accounting');
    throw err;
  }
}

export async function processSupplierPayment(companyId: string, 
  id: string,
  userId: string
): Promise<SupplierPayment> {
  try {
    const payment = await getSupplierPaymentById(companyId, id);
    if (!payment) throw new Error(`Payment ${id} not found`);
    if (payment.status !== 'approved') throw new Error(`Payment must be approved before processing`);

    // Auto-post GL entry: DR Accounts Payable, CR Bank
    const apAccount = await getSystemAccount('payable');
    const bankAccount = payment.bankAccountId
      ? ((await sql`SELECT * FROM gl_accounts WHERE id = ${payment.bankAccountId}`) as Row[])[0]
      : await getSystemAccount('bank');

    if (!bankAccount) throw new Error('Bank account not found');

    const lines: JournalLineInput[] = [
      {
        glAccountId: apAccount.id,
        debit: payment.totalAmount,
        credit: 0,
        description: `Payment ${payment.paymentNumber} to supplier`,
      },
      {
        glAccountId: String(bankAccount.id),
        debit: 0,
        credit: payment.totalAmount,
        description: `Payment ${payment.paymentNumber} to supplier`,
      },
    ];

    const journalEntry = await createJournalEntry(companyId, {
      entryDate: payment.paymentDate,
      description: `Supplier payment ${payment.paymentNumber}`,
      source: 'auto_supplier_payment',
      sourceDocumentId: id,
      lines,
    }, userId);

    await postJournalEntry(companyId, journalEntry.id, userId);

    // Update invoice balances and mark payment processed atomically
    const updated = await withTransaction(async (tx) => {
      for (const alloc of payment.allocations) {
        await tx`
          UPDATE supplier_invoices
          SET amount_paid = amount_paid + ${alloc.amountAllocated}
          WHERE id = ${alloc.invoiceId}
        `;
        await tx`
          UPDATE supplier_invoices SET status = CASE
            WHEN (total_amount - amount_paid) <= 0.01 THEN 'paid'
            WHEN amount_paid > 0 THEN 'partially_paid'
            ELSE status
          END
          WHERE id = ${alloc.invoiceId}
        `;
      }

      const rows = (await tx`
        UPDATE supplier_payments
        SET status = 'processed', processed_at = NOW(),
            gl_journal_entry_id = ${journalEntry.id}::UUID
        WHERE id = ${id} AND company_id = ${companyId}::UUID
        RETURNING *
      `) as Row[];

      return rows[0] as Row;
    });

    log.info('Processed supplier payment', { id, journalEntryId: journalEntry.id }, 'accounting');
    return mapPaymentRow(updated);
  } catch (err) {
    log.error('Failed to process supplier payment', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function approveSupplierPayment(companyId: string, 
  id: string,
  userId: string
): Promise<SupplierPayment> {
  try {
    const payment = await getSupplierPaymentById(companyId, id);
    if (!payment) throw new Error(`Payment ${id} not found`);
    if (payment.status !== 'draft') throw new Error(`Cannot approve payment with status: ${payment.status}`);

    const rows = (await sql`
      UPDATE supplier_payments
      SET status = 'approved', approved_by = ${userId}::UUID, approved_at = NOW()
      WHERE id = ${id} AND company_id = ${companyId}::UUID
      RETURNING *
    `) as Row[];

    return mapPaymentRow(rows[0]!);
  } catch (err) {
    log.error('Failed to approve supplier payment', { id, error: err }, 'accounting');
    throw err;
  }
}

function mapPaymentRow(row: Row): SupplierPayment {
  return {
    id: String(row.id),
    paymentNumber: row.payment_number ? String(row.payment_number) : '',
    supplierId: String(row.supplier_id),
    paymentDate: String(row.payment_date),
    totalAmount: Number(row.total_amount),
    paymentMethod: String(row.payment_method) as SupplierPayment['paymentMethod'],
    bankAccountId: row.bank_account_id ? String(row.bank_account_id) : undefined,
    reference: row.reference ? String(row.reference) : undefined,
    description: row.description ? String(row.description) : undefined,
    status: String(row.status) as SupplierPayment['status'],
    glJournalEntryId: row.gl_journal_entry_id ? String(row.gl_journal_entry_id) : undefined,
    batchId: row.batch_id ? String(row.batch_id) : undefined,
    createdBy: String(row.created_by),
    approvedBy: row.approved_by ? String(row.approved_by) : undefined,
    approvedAt: row.approved_at ? String(row.approved_at) : undefined,
    processedAt: row.processed_at ? String(row.processed_at) : undefined,
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
    supplierName: row.supplier_name ? String(row.supplier_name) : undefined,
  };
}

function mapAllocationRow(row: Row): PaymentAllocation {
  return {
    id: String(row.id),
