type Row = Record<string, unknown>;

export async function getBatches(companyId: string, filters?: {
  status?: string;
  limit?: number;
  offset?: number;
}): Promise<{ items: SupplierPaymentBatch[]; total: number }> {
  const limit = filters?.limit || 50;
  const offset = filters?.offset || 0;
  let rows: Row[];
  let countRows: Row[];

  if (filters?.status) {
    rows = (await sql`
      SELECT * FROM supplier_payment_batches
      WHERE company_id = ${companyId} AND status = ${filters.status}
      ORDER BY created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Record<string, unknown>[];
    countRows = (await sql`
      SELECT COUNT(*) AS cnt FROM supplier_payment_batches
      WHERE company_id = ${companyId} AND status = ${filters.status}
    `) as Record<string, unknown>[];
  } else {
    rows = (await sql`
      SELECT * FROM supplier_payment_batches WHERE company_id = ${companyId}
      ORDER BY created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Record<string, unknown>[];
    countRows = (await sql`SELECT COUNT(*) AS cnt FROM supplier_payment_batches WHERE company_id = ${companyId}`) as Record<string, unknown>[];
  }

  return { items: rows.map(mapRow), total: Number(countRows[0]?.cnt || 0) };
}

export async function getBatchById(companyId: string, id: string): Promise<SupplierPaymentBatch | null> {
  // companyId may be empty string when called internally after creating a batch — skip filter in that case
  const rows = companyId
    ? (await sql`SELECT * FROM supplier_payment_batches WHERE id = ${id} AND company_id = ${companyId}`) as Row[]
    : (await sql`SELECT * FROM supplier_payment_batches WHERE id = ${id}`) as Record<string, unknown>[];
  if (!rows[0]) return null;
  return mapRow(rows[0]);
}

export async function createBatch(companyId: string, 
  input: BatchPaymentCreateInput,
  userId: string
): Promise<SupplierPaymentBatch> {
  const paymentMethod = input.paymentMethod || 'eft';
  const batchDate = input.batchDate || new Date().toISOString().split('T')[0]!;

  const batchId = await withTransaction(async (tx) => {
    const batchRows = (await tx`
      INSERT INTO supplier_payment_batches (
        batch_date, payment_method, bank_account_id, notes,
        payment_count, total_amount, created_by
      ) VALUES (
        ${batchDate}, ${paymentMethod}, ${input.bankAccountId || null},
        ${input.notes || null}, ${input.payments.length}, 0, ${userId}::UUID
      ) RETURNING id
    `) as Record<string, unknown>[];

    const id = String(batchRows[0]!.id);
    let totalAmount = 0;

    for (const p of input.payments) {
      const payTotal = p.invoiceAllocations.reduce((s: number, a: { amount: number }) => s + a.amount, 0);
      totalAmount += payTotal;

      const payRows = (await tx`
        INSERT INTO supplier_payments (
          supplier_id, payment_date, total_amount, payment_method,
          status, batch_id, created_by
        ) VALUES (
          ${p.supplierId}::UUID, ${batchDate},
          ${payTotal}, ${paymentMethod}, 'draft', ${id}::UUID, ${userId}::UUID
        ) RETURNING id
      `) as Record<string, unknown>[];

      const paymentId = String(payRows[0]!.id);
      for (const alloc of p.invoiceAllocations) {
        await tx`
          INSERT INTO payment_allocations (payment_id, invoice_id, amount_allocated)
          VALUES (${paymentId}::UUID, ${alloc.invoiceId}::UUID, ${alloc.amount})
        `;
      }
    }

    await tx`
      UPDATE supplier_payment_batches SET total_amount = ${totalAmount} WHERE id = ${id}
    `;

    return id;
  });

  log.info('Created batch payment', { batchId, paymentCount: input.payments.length }, 'accounting');
  const result = await getBatchById('', batchId);
  return result!;
}

export async function approveBatch(companyId: string, id: string, _userId: string): Promise<void> {
  await sql`UPDATE supplier_payment_batches SET status = 'approved' WHERE id = ${id} AND company_id = ${companyId} AND status = 'draft'`;
  await sql`UPDATE supplier_payments SET status = 'approved' WHERE batch_id = ${id}::UUID AND status = 'draft'`;
  log.info('Approved batch', { id }, 'accounting');
}

export async function processBatch(companyId: string, id: string, userId: string): Promise<void> {
  const batch = await getBatchById('', id);
  if (!batch) throw new Error('Batch not found');
  if (batch.status !== 'approved') throw new Error('Batch must be approved first');

  const totalAmount = batch.totalAmount;

  // GL: DR AP, CR Bank
  const apAccount = await getSystemAccount('payable');
  const bankAccount = batch.bankAccountId
    ? { id: batch.bankAccountId }
    : await getSystemAccount('bank');

  const lines: JournalLineInput[] = [
    { glAccountId: apAccount.id, debit: totalAmount, credit: 0,
      description: `Batch payment ${batch.batchNumber}` },
    { glAccountId: bankAccount.id, debit: 0, credit: totalAmount,
      description: `Batch payment ${batch.batchNumber}` },
  ];

  const je = await createJournalEntry('', {
    entryDate: batch.batchDate,
    description: `Supplier batch payment ${batch.batchNumber}`,
    source: 'auto_batch_payment',
    sourceDocumentId: id,
    lines,
  }, userId);
  await postJournalEntry(companyId, je.id, userId);

  // Update all linked payments and their invoices atomically
  await withTransaction(async (tx) => {
    const payments = (await tx`
      SELECT sp.id, pa.invoice_id, pa.amount_allocated
      FROM supplier_payments sp
      JOIN payment_allocations pa ON pa.payment_id = sp.id
      WHERE sp.batch_id = ${id}::UUID
    `) as Record<string, unknown>[];

    for (const p of payments) {
      await tx`
        UPDATE supplier_invoices
        SET amount_paid = amount_paid + ${Number(p.amount_allocated)},
            status = CASE
              WHEN (total_amount - amount_paid - ${Number(p.amount_allocated)}) <= 0.01 THEN 'paid'
              WHEN amount_paid + ${Number(p.amount_allocated)} > 0 THEN 'partially_paid'
              ELSE status END
        WHERE id = ${p.invoice_id}::UUID
      `;
    }

    await tx`UPDATE supplier_payments SET status = 'processed' WHERE batch_id = ${id}::UUID`;
    await tx`
      UPDATE supplier_payment_batches
      SET status = 'processed', processed_by = ${userId}::UUID, processed_at = NOW(),
          gl_journal_entry_id = ${je.id}::UUID
      WHERE id = ${id}
    `;
  });

  log.info('Processed batch', { id, journalEntryId: je.id }, 'accounting');
}

export async function cancelBatch(companyId: string, id: string): Promise<void> {
  await sql`UPDATE supplier_payment_batches SET status = 'cancelled' WHERE id = ${id} AND company_id = ${companyId} AND status = 'draft'`;
  await sql`UPDATE supplier_payments SET status = 'cancelled' WHERE batch_id = ${id}::UUID AND status = 'draft'`;
}

function mapRow(row: Record<string, unknown>): SupplierPaymentBatch {
  return {
    id: String(row.id),
    batchNumber: row.batch_number ? String(row.batch_number) : '',
    batchDate: String(row.batch_date),
    totalAmount: Number(row.total_amount),
    paymentCount: Number(row.payment_count),
    paymentMethod: String(row.payment_method) as SupplierPaymentBatch['paymentMethod'],
    bankAccountId: row.bank_account_id ? String(row.bank_account_id) : undefined,
    status: String(row.status) as SupplierPaymentBatch['status'],
    glJournalEntryId: row.gl_journal_entry_id ? String(row.gl_journal_entry_id) : undefined,
    notes: row.notes ? String(row.notes) : undefined,
    processedBy: row.processed_by ? String(row.processed_by) : undefined,
    processedAt: row.processed_at ? String(row.processed_at) : undefined,
    createdBy: String(row.created_by),
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
  };
}

/**
 * Disclosure Note Service — WS-7.2
 * Orchestrates auto-generated + manual IFRS disclosure notes.
 * Auto-generation helpers live in disclosureNoteGenerators.ts.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import {
  noteAccountingPolicies,
  notePPE,
  noteReceivables,
  notePayables,
  noteRevenue,
  noteCash,
  noteTaxation,
} from './disclosureNoteGenerators';

export interface NoteTable {
  headers: string[];
  rows: string[][];
}

export interface DisclosureNote {
  noteNumber: number;
  title: string;
  content: string;
  tables?: NoteTable[];
  source: 'auto' | 'manual';
  id?: string;
}

type Row = Record<string, unknown>;

// ── Main: Generate All Auto Notes ────────────────────────────────────────────

export async function generateDisclosureNotes(
  companyId: string,
  fiscalYear: number,
): Promise<DisclosureNote[]> {
  log.info('Generating disclosure notes', { companyId, fiscalYear }, 'disclosureNoteService');

  const [n1, n2, n3, n4, n5, n6, n7] = await Promise.all([
    noteAccountingPolicies(companyId, fiscalYear),
    notePPE(companyId, fiscalYear),
    noteReceivables(companyId, fiscalYear),
    notePayables(companyId, fiscalYear),
    noteRevenue(companyId, fiscalYear),
    noteCash(companyId, fiscalYear),
    noteTaxation(companyId, fiscalYear),
  ]);

  return [n1, n2, n3, n4, n5, n6, n7];
}

// ── Manual Notes CRUD ─────────────────────────────────────────────────────────

export async function saveManualNote(
  companyId: string,
  fiscalYear: number,
  note: { title: string; content: string; noteNumber: number },
  createdBy: string,
): Promise<void> {
  log.info('Saving manual disclosure note', { companyId, fiscalYear, noteNumber: note.noteNumber }, 'disclosureNoteService');

  await sql`
    INSERT INTO disclosure_notes_manual (company_id, fiscal_year, note_number, title, content, created_by)
    VALUES (${companyId}, ${fiscalYear}, ${note.noteNumber}, ${note.title}, ${note.content}, ${createdBy})
    ON CONFLICT (company_id, fiscal_year, note_number)
    DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, updated_at = NOW()
  `;
}

export async function getManualNotes(
  companyId: string,
  fiscalYear: number,
): Promise<DisclosureNote[]> {
  const rows = await sql`
    SELECT id, note_number, title, content
    FROM disclosure_notes_manual
    WHERE company_id = ${companyId} AND fiscal_year = ${fiscalYear}
    ORDER BY note_number ASC
  ` as Row[];

  return rows.map((r: Row) => ({
    noteNumber: r.note_number as number,
    title: r.title as string,
    content: r.content as string,
    source: 'manual' as const,
    id: r.id as string,
  }));
}

export async function deleteManualNote(companyId: string, noteId: string): Promise<void> {
  log.info('Deleting manual disclosure note', { companyId, noteId }, 'disclosureNoteService');

  await sql`
    DELETE FROM disclosure_notes_manual
    WHERE id = ${noteId} AND company_id = ${companyId}
  `;
}

/**
 * PRD-060: FibreFlow Accounting Module — Phase 2
 * AP Aging Report Service
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { calculateAgingBuckets } from '../utils/aging';
import type { AgingBucket, AgingInvoice } from '../types/ap.types';
type Row = Record<string, unknown>;


export async function getAPAging(companyId: string, asAtDate?: string): Promise<AgingBucket[]> {
  try {
    const asAt = asAtDate ? new Date(asAtDate) : new Date();

    const rows = (await sql`
      SELECT si.id, si.supplier_id AS entity_id, s.name AS entity_name,
        si.due_date, si.total_amount, si.amount_paid, si.balance
      FROM supplier_invoices si
      JOIN suppliers s ON s.id = si.supplier_id
      WHERE si.company_id = ${companyId}::UUID
        AND si.status IN ('approved', 'partially_paid')
        AND si.balance > 0
        AND si.due_date IS NOT NULL
      ORDER BY si.due_date
    `) as Row[];

    const invoices: AgingInvoice[] = rows.map((r: Row) => ({
      id: String(r.id),
      entityId: String(r.entity_id),
      entityName: String(r.entity_name),
      dueDate: String(r.due_date),
      totalAmount: Number(r.total_amount),
      amountPaid: Number(r.amount_paid),
      balance: Number(r.balance),
    }));

    return calculateAgingBuckets(invoices, asAt);
  } catch (err) {
    log.error('Failed to get AP aging', { error: err }, 'accounting');
    throw err;
  }
}

export async function getAPAgingDetail(companyId: string, 
  supplierId: string,
  asAtDate?: string
): Promise<{ supplier: { id: string; name: string }; invoices: AgingInvoice[]; buckets: AgingBucket | null }> {
  try {
    const asAt = asAtDate ? new Date(asAtDate) : new Date();

    const supplierRows = (await sql`SELECT id, name FROM suppliers WHERE id = ${Number(supplierId)} AND company_id = ${companyId}::UUID`) as Row[];
    if (supplierRows.length === 0) throw new Error(`Supplier ${supplierId} not found`);

    const rows = (await sql`
      SELECT si.id, si.supplier_id AS entity_id, s.name AS entity_name,
        si.due_date, si.invoice_number, si.total_amount, si.amount_paid, si.balance
      FROM supplier_invoices si
      JOIN suppliers s ON s.id = si.supplier_id
      WHERE si.company_id = ${companyId}::UUID
        AND si.supplier_id = ${Number(supplierId)}
        AND si.status IN ('approved', 'partially_paid')
        AND si.balance > 0
        AND si.due_date IS NOT NULL
      ORDER BY si.due_date
    `) as Row[];

    const invoices: AgingInvoice[] = rows.map((r: Row) => ({
      id: String(r.id),
      entityId: String(r.entity_id),
      entityName: String(r.entity_name),
      dueDate: String(r.due_date),
      totalAmount: Number(r.total_amount),
      amountPaid: Number(r.amount_paid),
      balance: Number(r.balance),
    }));

    const buckets = calculateAgingBuckets(invoices, asAt);

    return {
      supplier: { id: String(supplierRows[0]!.id), name: String(supplierRows[0]!.name) },
      invoices,
      buckets: buckets.length > 0 ? buckets[0]! : null,
    };
  } catch (err) {
    log.error('Failed to get AP aging detail', { supplierId, error: err }, 'accounting');
    throw err;
  }
}

/**
 * PRD-060: FibreFlow Accounting Module — Phase 4
 * Bank Import Service — statement import and persistence
 */

import { transaction } from '@/lib/neon';
import { log } from '@/lib/logger';
import {
  detectBankFormat,
  parseFNBStatement,
  parseStandardBankStatement,
  parseNedbankStatement,
  parseABSAStatement,
  parseCapitecStatement,
} from '../utils/bankCsvParsers';
import { parseOfxStatement } from '../utils/bankOfxParser';
import { parseQifStatement } from '../utils/bankQifParser';
import type { BankFormat, BankCsvParseResult } from '../types/bank.types';

export async function importBankStatement(
  companyId: string,
  csvContent: string,
  bankAccountId: string,
  statementDate: string,
  bankFormat?: BankFormat
): Promise<{ batchId: string; transactionCount: number; errors: Array<{ row: number; error: string }> }> {
  try {
    const format = bankFormat && bankFormat !== 'unknown' ? bankFormat : detectBankFormat(csvContent);
    let parseResult;

    switch (format) {
      case 'fnb':
        parseResult = parseFNBStatement(csvContent);
        break;
      case 'standard_bank':
        parseResult = parseStandardBankStatement(csvContent);
        break;
      case 'nedbank':
        parseResult = parseNedbankStatement(csvContent);
        break;
      case 'absa':
        parseResult = parseABSAStatement(csvContent);
        break;
      case 'capitec':
        parseResult = parseCapitecStatement(csvContent);
        break;
      case 'ofx':
        parseResult = parseOfxStatement(csvContent);
        break;
      case 'qif':
        parseResult = parseQifStatement(csvContent);
        break;
      default:
        throw new Error('Unable to detect bank format. Please specify the bank.');
    }

    if (parseResult.transactions.length === 0) {
      return { batchId: '', transactionCount: 0, errors: parseResult.errors };
    }

    const batchId = crypto.randomUUID();

    await transaction((txSql) =>
      parseResult.transactions.map(tx => txSql`
        INSERT INTO bank_transactions (
          company_id, bank_account_id, transaction_date, value_date, amount,
          description, reference, import_batch_id
        ) VALUES (
          ${companyId}::UUID, ${bankAccountId}::UUID, ${tx.transactionDate}, ${tx.valueDate || null},
          ${tx.amount}, ${tx.description}, ${tx.reference || null}, ${batchId}::UUID
        )
      `)
    );

    log.info('Imported bank statement', {
      batchId, format, count: parseResult.transactions.length,
    }, 'accounting');

    return {
      batchId,
      transactionCount: parseResult.transactions.length,
      errors: parseResult.errors,
    };
  } catch (err) {
    log.error('Failed to import bank statement', { error: err }, 'accounting');
    throw err;
  }
}

/**
 * Persist an already-parsed set of transactions (e.g. from a PDF import).
 * Reuses the same INSERT logic as importBankStatement so behaviour is identical.
 */
export async function importParsedTransactions(
  companyId: string,
  parseResult: BankCsvParseResult,
  bankAccountId: string,
  statementDate: string,
): Promise<{ batchId: string; transactionCount: number; errors: Array<{ row: number; error: string }> }> {
  try {
    if (parseResult.transactions.length === 0) {
      return { batchId: '', transactionCount: 0, errors: parseResult.errors };
    }

    const batchId = crypto.randomUUID();

    await transaction((txSql) =>
      parseResult.transactions.map(tx => txSql`
        INSERT INTO bank_transactions (
          company_id, bank_account_id, transaction_date, value_date, amount,
          description, reference, import_batch_id
        ) VALUES (
          ${companyId}::UUID, ${bankAccountId}::UUID, ${tx.transactionDate}, ${tx.valueDate || null},
          ${tx.amount}, ${tx.description}, ${tx.reference || null}, ${batchId}::UUID
        )
      `)
    );

    log.info('Imported parsed bank statement', {
      batchId,
      format: parseResult.bankFormat,
      count: parseResult.transactions.length,
      statementDate,
    }, 'accounting');

    return {
      batchId,
      transactionCount: parseResult.transactions.length,
      errors: parseResult.errors,
    };
  } catch (err) {
    log.error('Failed to import parsed bank transactions', { error: err }, 'accounting');
    throw err;
  }
}

/**
 * IFRS Disclosure Note Generators — WS-7.2
 * Each function queries live financial data and returns a formatted DisclosureNote.
 */

import { sql } from '@/lib/neon';
import type { DisclosureNote } from './disclosureNoteService';

type Row = Record<string, unknown>;

function fmt(n: number | null | undefined): string {
  if (n == null) return '—';
  return new Intl.NumberFormat('en-ZA', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(n);
}

function fiscalRange(year: number): { start: string; end: string } {
  return { start: `${year}-01-01`, end: `${year}-12-31` };
}

// ── Note 1: Accounting Policies ───────────────────────────────────────────────

export async function noteAccountingPolicies(companyId: string, _fiscalYear: number): Promise<DisclosureNote> {
  const rows = await sql`
    SELECT depreciation_method, inventory_valuation_method, default_currency, vat_system_type
    FROM companies WHERE id = ${companyId}
  ` as Row[];

  const c = rows[0] ?? {};
  const depMethod = c.depreciation_method ?? 'straight-line';
  const invMethod = c.inventory_valuation_method ?? 'weighted average cost';
  const currency = c.default_currency ?? 'ZAR';
  const vatType = c.vat_system_type ?? 'invoice';

  const content = [
    `Basis of preparation: The annual financial statements have been prepared on the historical cost basis and in accordance with International Financial Reporting Standards (IFRS) and the requirements of the Companies Act of South Africa. The functional and presentation currency is ${currency}.`,
    ``,
    `Property, Plant and Equipment: Stated at cost less accumulated depreciation and impairment losses. Depreciation is calculated on the ${depMethod} method over the estimated useful lives of assets.`,
    ``,
    `Inventories: Valued at the lower of cost and net realisable value. Cost is determined using the ${invMethod} method.`,
    ``,
    `Revenue Recognition: Revenue from the sale of goods is recognised when the significant risks and rewards of ownership have passed to the buyer. Revenue from services is recognised in the period in which the services are rendered.`,
    ``,
    `Taxation: Value Added Tax (VAT) is accounted for on the ${vatType} basis as registered with the South African Revenue Service (SARS).`,
  ].join('\n');

  return { noteNumber: 1, title: 'Accounting Policies', content, source: 'auto' };
}

// ── Note 2: Property, Plant & Equipment ───────────────────────────────────────

export async function notePPE(companyId: string, fiscalYear: number): Promise<DisclosureNote> {
  const { start, end } = fiscalRange(fiscalYear);

  const rows = await sql`
    SELECT
      fa.category,
      SUM(fa.cost) AS total_cost,
      SUM(fa.accumulated_depreciation) AS total_accum_dep,
      SUM(CASE WHEN fa.acquisition_date BETWEEN ${start} AND ${end} THEN fa.cost ELSE 0 END) AS additions,
      SUM(CASE WHEN fa.disposal_date BETWEEN ${start} AND ${end} THEN fa.cost ELSE 0 END) AS disposals,
      SUM(fa.depreciation_charge) AS dep_charge
    FROM fixed_assets fa
    WHERE fa.company_id = ${companyId}
      AND (fa.disposal_date IS NULL OR fa.disposal_date >= ${start})
    GROUP BY fa.category
    ORDER BY fa.category
  ` as Row[];

  const headers = ['Category', 'Cost', 'Accum Depr', 'Carrying Value', 'Additions', 'Disposals', 'Depr Charge'];
  const tableRows: string[][] = rows.map((r: Row) => {
    const cv = (Number(r.total_cost) || 0) - (Number(r.total_accum_dep) || 0);
    return [String(r.category ?? 'Uncategorised'), fmt(r.total_cost as number | null), fmt(r.total_accum_dep as number | null), fmt(cv), fmt(r.additions as number | null), fmt(r.disposals as number | null), fmt(r.dep_charge as number | null)];
  });

  const totalCost = rows.reduce((s: number, r: Row) => s + (Number(r.total_cost) || 0), 0);
  const totalAccum = rows.reduce((s: number, r: Row) => s + (Number(r.total_accum_dep) || 0), 0);
  tableRows.push(['Total', fmt(totalCost), fmt(totalAccum), fmt(totalCost - totalAccum), '', '', '']);

  const content = `The table below summarises the movement in property, plant and equipment for the year ended 31 December ${fiscalYear}. Depreciation is charged to profit or loss on a systematic basis over the estimated useful lives of the assets.`;

  return {
    noteNumber: 2,
    title: 'Property, Plant and Equipment',
    content,
    tables: rows.length > 0 ? [{ headers, rows: tableRows }] : undefined,
    source: 'auto',
  };
}

// ── Note 3: Trade & Other Receivables ─────────────────────────────────────────

export async function noteReceivables(companyId: string, fiscalYear: number): Promise<DisclosureNote> {
  const { end } = fiscalRange(fiscalYear);

  const rows = await sql`
    SELECT
      SUM(ci.total_amount) FILTER (WHERE ci.status NOT IN ('paid','cancelled','void')) AS gross_receivables,
      SUM(ci.total_amount) FILTER (
        WHERE ci.status NOT IN ('paid','cancelled','void')
          AND ci.due_date <= ${end}::date AND ci.due_date > ${end}::date - INTERVAL '30 days'
      ) AS current_amount,
      SUM(ci.total_amount) FILTER (
        WHERE ci.status NOT IN ('paid','cancelled','void')
          AND ci.due_date <= ${end}::date - INTERVAL '30 days'
          AND ci.due_date > ${end}::date - INTERVAL '60 days'
      ) AS days_30,
      SUM(ci.total_amount) FILTER (
        WHERE ci.status NOT IN ('paid','cancelled','void')
          AND ci.due_date <= ${end}::date - INTERVAL '60 days'
          AND ci.due_date > ${end}::date - INTERVAL '90 days'
      ) AS days_60,
      SUM(ci.total_amount) FILTER (
        WHERE ci.status NOT IN ('paid','cancelled','void')
          AND ci.due_date <= ${end}::date - INTERVAL '90 days'
      ) AS days_90_plus
    FROM customer_invoices ci
    WHERE ci.company_id = ${companyId} AND ci.invoice_date <= ${end}
  ` as Row[];

  const r = rows[0] ?? {};
  const gross = Number(r.gross_receivables) || 0;

  return {
    noteNumber: 3,
    title: 'Trade and Other Receivables',
    content: `Trade receivables are carried at original invoice amount less any provision for doubtful debts assessed at the reporting date based on objective evidence of impairment.`,
    tables: [
      { headers: ['', 'Amount (R)'], rows: [['Gross trade receivables', fmt(gross)], ['Less: Provision for doubtful debts', fmt(0)], ['Net trade receivables', fmt(gross)]] },
      { headers: ['Current', '30 days', '60 days', '90+ days', 'Total'], rows: [[fmt(r.current_amount as number | null), fmt(r.days_30 as number | null), fmt(r.days_60 as number | null), fmt(r.days_90_plus as number | null), fmt(gross)]] },
    ],
    source: 'auto',
  };
}

// ── Note 4: Trade & Other Payables ────────────────────────────────────────────

export async function notePayables(companyId: string, fiscalYear: number): Promise<DisclosureNote> {
  const { end } = fiscalRange(fiscalYear);

  const rows = await sql`
    SELECT
      SUM(si.total_amount) FILTER (WHERE si.status NOT IN ('paid','cancelled','void')) AS gross_payables,
      SUM(si.total_amount) FILTER (
        WHERE si.status NOT IN ('paid','cancelled','void')
          AND si.due_date <= ${end}::date AND si.due_date > ${end}::date - INTERVAL '30 days'
      ) AS current_amount,
      SUM(si.total_amount) FILTER (
        WHERE si.status NOT IN ('paid','cancelled','void')
          AND si.due_date <= ${end}::date - INTERVAL '30 days'
          AND si.due_date > ${end}::date - INTERVAL '60 days'
      ) AS days_30,
      SUM(si.total_amount) FILTER (
        WHERE si.status NOT IN ('paid','cancelled','void')
          AND si.due_date <= ${end}::date - INTERVAL '60 days'
      ) AS days_60_plus
    FROM supplier_invoices si
    WHERE si.company_id = ${companyId} AND si.invoice_date <= ${end}
  ` as Row[];

  const r = rows[0] ?? {};
  const gross = Number(r.gross_payables) || 0;

  return {
    noteNumber: 4,
    title: 'Trade and Other Payables',
    content: `Trade and other payables are carried at cost which is the fair value of the consideration to be paid in the future for goods and services received, whether or not billed to the entity.`,
    tables: [
      { headers: ['', 'Amount (R)'], rows: [['Trade payables', fmt(gross)], ['Accrued liabilities', fmt(0)], ['Total trade and other payables', fmt(gross)]] },
      { headers: ['Current', '30 days', '60+ days', 'Total'], rows: [[fmt(r.current_amount as number | null), fmt(r.days_30 as number | null), fmt(r.days_60_plus as number | null), fmt(gross)]] },
    ],
    source: 'auto',
  };
}

// ── Note 5: Revenue ───────────────────────────────────────────────────────────

export async function noteRevenue(companyId: string, fiscalYear: number): Promise<DisclosureNote> {
  const { start, end } = fiscalRange(fiscalYear);

  const rows = await sql`
    SELECT ga.account_name, ga.account_code,
      SUM(ABS(gjl.credit_amount - gjl.debit_amount)) AS net_amount
    FROM gl_journal_lines gjl
    JOIN gl_accounts ga ON ga.id = gjl.account_id
    JOIN gl_journal_entries gje ON gje.id = gjl.journal_entry_id
    WHERE gjl.company_id = ${companyId}
      AND ga.account_type = 'revenue'
      AND gje.entry_date BETWEEN ${start} AND ${end}
      AND gje.status = 'posted'
    GROUP BY ga.account_name, ga.account_code
    ORDER BY net_amount DESC
  ` as Row[];

  const total = rows.reduce((s: number, r: Row) => s + (Number(r.net_amount) || 0), 0);
  const tableRows: string[][] = rows.map((r: Row) => [String(r.account_name), String(r.account_code), fmt(r.net_amount as number | null)]);
  tableRows.push(['Total Revenue', '', fmt(total)]);

  return {
    noteNumber: 5,
    title: 'Revenue',
    content: `Revenue is measured at the fair value of the consideration received or receivable and represents amounts receivable for goods and services provided in the normal course of business, net of discounts and VAT.`,
    tables: tableRows.length > 1 ? [{ headers: ['Account', 'Code', 'Amount (R)'], rows: tableRows }] : undefined,
    source: 'auto',
  };
}

// ── Note 6: Cash and Cash Equivalents ─────────────────────────────────────────

export async function noteCash(companyId: string, fiscalYear: number): Promise<DisclosureNote> {
  const { end } = fiscalRange(fiscalYear);

  const rows = await sql`
    SELECT ga.account_name, ga.account_code,
      COALESCE(SUM(gjl.debit_amount - gjl.credit_amount), 0) AS balance
    FROM gl_accounts ga
    LEFT JOIN gl_journal_lines gjl ON gjl.account_id = ga.id AND gjl.company_id = ${companyId}
    LEFT JOIN gl_journal_entries gje ON gje.id = gjl.journal_entry_id
      AND gje.entry_date <= ${end} AND gje.status = 'posted'
    WHERE ga.company_id = ${companyId}
      AND ga.account_subtype IN ('bank', 'cash', 'petty_cash')
    GROUP BY ga.account_name, ga.account_code
    ORDER BY ga.account_code
  ` as Row[];

  const total = rows.reduce((s: number, r: Row) => s + (Number(r.balance) || 0), 0);
  const tableRows: string[][] = rows.map((r: Row) => [String(r.account_name), String(r.account_code), fmt(r.balance as number | null)]);
  tableRows.push(['Total', '', fmt(total)]);

  return {
    noteNumber: 6,
    title: 'Cash and Cash Equivalents',
    content: `Cash and cash equivalents include cash on hand and deposits held at call with banks. Bank overdrafts are shown within borrowings in current liabilities on the balance sheet.`,
    tables: tableRows.length > 1 ? [{ headers: ['Bank Account', 'Code', 'Balance (R)'], rows: tableRows }] : undefined,
    source: 'auto',
  };
}

// ── Note 7: Taxation (VAT) ────────────────────────────────────────────────────

export async function noteTaxation(companyId: string, fiscalYear: number): Promise<DisclosureNote> {
  const { start, end } = fiscalRange(fiscalYear);

  const rows = await sql`
    SELECT
      SUM(gjl.debit_amount) FILTER (WHERE ga.account_subtype = 'vat_input') AS vat_input,
      SUM(gjl.credit_amount) FILTER (WHERE ga.account_subtype = 'vat_output') AS vat_output
    FROM gl_journal_lines gjl
    JOIN gl_accounts ga ON ga.id = gjl.account_id
    JOIN gl_journal_entries gje ON gje.id = gjl.journal_entry_id
    WHERE gjl.company_id = ${companyId}
      AND ga.account_subtype IN ('vat_input', 'vat_output')
      AND gje.entry_date BETWEEN ${start} AND ${end}
      AND gje.status = 'posted'
  ` as Row[];

  const r = rows[0] ?? {};
  const input = Number(r.vat_input) || 0;
  const output = Number(r.vat_output) || 0;

  return {
    noteNumber: 7,
    title: 'Taxation',
    content: `The company is registered for Value Added Tax (VAT) with SARS. VAT is levied at the standard rate of 15% on all taxable supplies. The reconciliation below reflects the net VAT position for the year ended 31 December ${fiscalYear}.`,
    tables: [{
      headers: ['', 'Amount (R)'],
      rows: [
        ['Output VAT (collected from customers)', fmt(output)],
        ['Input VAT (paid to suppliers)', fmt(input)],
        ['Net VAT payable / (receivable)', fmt(output - input)],
      ],
    }],
    source: 'auto',
  };
}

/**
 * PRD-060: FibreFlow Accounting Module — Phase 4
 * Bank Transaction Query Service — queries, status mutations, and row mappers
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { BankTransaction } from '../types/bank.types';

type Row = Record<string, unknown>;

// ── Row Mappers ───────────────────────────────────────────────────────────────

export function fmtDate(val: unknown): string {
  if (val instanceof Date) return val.toISOString().split('T')[0] ?? '';
  return val ? String(val).split('T')[0] ?? '' : '';
}

export function mapTxRow(row: Row): BankTransaction {
  return {
    id: String(row.id),
    bankAccountId: String(row.bank_account_id),
    transactionDate: fmtDate(row.transaction_date),
    valueDate: row.value_date ? fmtDate(row.value_date) : undefined,
    amount: Number(row.amount),
    description: row.description ? String(row.description) : undefined,
    reference: row.reference ? String(row.reference) : undefined,
    bankReference: row.bank_reference ? String(row.bank_reference) : undefined,
    status: String(row.status) as BankTransaction['status'],
    matchedJournalLineId: row.matched_journal_line_id ? String(row.matched_journal_line_id) : undefined,
    reconciliationId: row.reconciliation_id ? String(row.reconciliation_id) : undefined,
    importBatchId: row.import_batch_id ? String(row.import_batch_id) : undefined,
    excludeReason: row.exclude_reason ? String(row.exclude_reason) : undefined,
    notes: row.notes ? String(row.notes) : undefined,
    suggestedGlAccountId: row.suggested_gl_account_id ? String(row.suggested_gl_account_id) : undefined,
    suggestedCategory: row.suggested_category ? String(row.suggested_category) : undefined,
    suggestedCostCentre: row.suggested_cost_centre ? String(row.suggested_cost_centre) : undefined,
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
    bankAccountName: row.bank_account_name ? String(row.bank_account_name) : undefined,
    matchedEntryNumber: row.matched_entry_number ? String(row.matched_entry_number) : undefined,
    suggestedGlAccountName: row.suggested_gl_account_name ? String(row.suggested_gl_account_name) : undefined,
    suggestedGlAccountCode: row.suggested_gl_account_code ? String(row.suggested_gl_account_code) : undefined,
    suggestedSupplierId: row.suggested_supplier_id ? String(row.suggested_supplier_id) : undefined,
    suggestedSupplierName: row.suggested_supplier_name ? String(row.suggested_supplier_name) : undefined,
    suggestedClientId: row.suggested_client_id ? String(row.suggested_client_id) : undefined,
    suggestedClientName: row.suggested_client_name ? String(row.suggested_client_name) : undefined,
    suggestedVatCode: row.suggested_vat_code && row.suggested_vat_code !== 'none'
      ? String(row.suggested_vat_code) : undefined,
    suggestedConfidence: row.suggested_confidence != null ? Number(row.suggested_confidence) : undefined,
    cc1Id: row.cc1_id ? String(row.cc1_id) : undefined,
    cc2Id: row.cc2_id ? String(row.cc2_id) : undefined,
    buId: row.bu_id ? String(row.bu_id) : undefined,
    cc1Name: row.cc1_name ? String(row.cc1_name) : undefined,
    cc2Name: row.cc2_name ? String(row.cc2_name) : undefined,
    buName: row.bu_name ? String(row.bu_name) : undefined,
    allocationType: row.allocation_type
      ? String(row.allocation_type) as BankTransaction['allocationType'] : undefined,
    allocatedEntityName: row.allocated_entity_name ? String(row.allocated_entity_name) : undefined,
  };
}

// ── Filters Interface ─────────────────────────────────────────────────────────

export interface BankTxFilters {
  bankAccountId?: string;
  reconciliationId?: string;
  status?: string;
  fromDate?: string;
  toDate?: string;
  fromAmount?: string;
  toAmount?: string;
  search?: string;
  sortOrder?: 'asc' | 'desc';
  allocationFilter?: 'all' | 'unallocated' | 'allocated';
  txType?: 'all' | 'spent' | 'received';
  allocType?: 'all' | 'account' | 'supplier' | 'customer';
  hasSuggestion?: 'all' | 'yes' | 'no';
  limit?: number;
  offset?: number;
}

// ── Shared SELECT fragment ────────────────────────────────────────────────────

const TX_SELECT = sql`
  SELECT bt.*, ga.account_name AS bank_account_name,
         sga.account_name AS suggested_gl_account_name, sga.account_code AS suggested_gl_account_code,
         COALESCE(ss.company_name, ss.name) AS suggested_supplier_name,
         sc.name AS suggested_client_name
  FROM bank_transactions bt
  LEFT JOIN gl_accounts ga ON ga.id = bt.bank_account_id
  LEFT JOIN gl_accounts sga ON sga.id = bt.suggested_gl_account_id
  LEFT JOIN suppliers ss ON ss.id = bt.suggested_supplier_id
  LEFT JOIN customers sc ON sc.id = bt.suggested_client_id
`;

// ── Query ─────────────────────────────────────────────────────────────────────

export async function getBankTransactions(
  companyId: string,
  filters?: BankTxFilters
): Promise<{ transactions: BankTransaction[]; total: number }> {
  try {
    const limit = Math.min(filters?.limit || 100, 200);
    const offset = filters?.offset || 0;
    let rows: Row[];
    let countRows: Row[];

    if (filters?.reconciliationId) {
      rows = (await sql`${TX_SELECT}
        WHERE bt.reconciliation_id = ${filters.reconciliationId}::UUID
        ORDER BY bt.transaction_date DESC, bt.amount DESC
        LIMIT ${limit} OFFSET ${offset}`) as Row[];
      countRows = (await sql`SELECT COUNT(*) AS cnt FROM bank_transactions
        WHERE reconciliation_id = ${filters.reconciliationId}::UUID`) as Row[];
    } else if (filters?.bankAccountId && filters?.status) {
      const searchPattern = filters.search ? `%${filters.search}%` : '%';
      const fromDate = filters.fromDate || '1900-01-01';
      const toDate = filters.toDate || '2099-12-31';
      const fromAmt = filters.fromAmount || '-999999999';
      const toAmt = filters.toAmount || '999999999';
      let statusArr: string[];
      if (filters.status === 'imported') {
        if (filters.allocationFilter === 'unallocated') statusArr = ['imported'];
        else if (filters.allocationFilter === 'allocated') statusArr = ['allocated'];
        else statusArr = ['imported', 'allocated'];
      } else {
        statusArr = [filters.status];
      }
      // SAFETY INVARIANT: txTypeCond, allocTypeCond, hasSuggCond are built from
      // fixed string literals keyed on validated enum values — no user input is
      // interpolated directly. The final `extra` fragment is therefore safe.
      const txTypeCond = filters.txType === 'spent' ? 'AND bt.amount < 0'
        : filters.txType === 'received' ? 'AND bt.amount > 0' : '';
      const validAllocTypes = ['account', 'supplier', 'customer'] as const;
      // Validate allocType against strict allowlist before building SQL fragment
      const safeAllocType = filters.allocType && validAllocTypes.includes(filters.allocType as typeof validAllocTypes[number])
        ? filters.allocType : null;
      const allocTypeCond = safeAllocType ? `AND bt.allocation_type = '${safeAllocType}'` : '';
      const hasSuggCond = filters.hasSuggestion === 'yes'
        ? 'AND (bt.suggested_gl_account_id IS NOT NULL OR bt.suggested_supplier_id IS NOT NULL OR bt.suggested_client_id IS NOT NULL)'
        : filters.hasSuggestion === 'no'
          ? 'AND bt.suggested_gl_account_id IS NULL AND bt.suggested_supplier_id IS NULL AND bt.suggested_client_id IS NULL'
          : '';
      // sortDir is strictly validated — only 'ASC' or 'DESC' are possible
      const sortDir = filters.sortOrder === 'asc' ? 'ASC' : 'DESC';
      if (sortDir !== 'ASC' && sortDir !== 'DESC') throw new Error('Invalid sort direction');
      const extra = [txTypeCond, allocTypeCond, hasSuggCond].filter(Boolean).join(' ');
      rows = (await sql`${TX_SELECT}
        WHERE bt.bank_account_id = ${filters.bankAccountId}::UUID
          AND bt.status = ANY(${statusArr}::TEXT[])
          AND bt.transaction_date >= ${fromDate} AND bt.transaction_date <= ${toDate}
          AND bt.amount >= ${fromAmt}::NUMERIC AND bt.amount <= ${toAmt}::NUMERIC
          AND (bt.description ILIKE ${searchPattern} OR bt.reference ILIKE ${searchPattern})
          ${sql.unsafe(extra)}
        ORDER BY bt.transaction_date ${sql.unsafe(sortDir)}, bt.amount DESC
        LIMIT ${limit} OFFSET ${offset}`) as Row[];
      countRows = (await sql`SELECT COUNT(*) AS cnt FROM bank_transactions bt
        WHERE bt.bank_account_id = ${filters.bankAccountId}::UUID
          AND bt.status = ANY(${statusArr}::TEXT[])
          AND bt.transaction_date >= ${fromDate} AND bt.transaction_date <= ${toDate}
          AND bt.amount >= ${fromAmt}::NUMERIC AND bt.amount <= ${toAmt}::NUMERIC
          AND (bt.description ILIKE ${searchPattern} OR bt.reference ILIKE ${searchPattern})
          ${sql.unsafe(extra)}`) as Row[];
    } else if (filters?.bankAccountId) {
      rows = (await sql`${TX_SELECT}
        WHERE bt.bank_account_id = ${filters.bankAccountId}::UUID
        ORDER BY bt.transaction_date DESC, bt.amount DESC
        LIMIT ${limit} OFFSET ${offset}`) as Row[];
      countRows = (await sql`SELECT COUNT(*) AS cnt FROM bank_transactions
        WHERE bank_account_id = ${filters.bankAccountId}::UUID`) as Row[];
    } else {
      rows = (await sql`${TX_SELECT}
        WHERE bt.company_id = ${companyId}
        ORDER BY bt.transaction_date DESC, bt.amount DESC
        LIMIT ${limit} OFFSET ${offset}`) as Row[];
      countRows = (await sql`SELECT COUNT(*) AS cnt FROM bank_transactions
        WHERE company_id = ${companyId}`) as Row[];
    }

    return { transactions: rows.map(mapTxRow), total: Number(countRows[0]!.cnt) };
  } catch (err) {
    log.error('Failed to get bank transactions', { error: err }, 'accounting');
    throw err;
  }
}

// ── Status Mutations ──────────────────────────────────────────────────────────

export async function matchTransaction(
  companyId: string, bankTxId: string, journalLineId: string, reconciliationId?: string
): Promise<BankTransaction> {
  try {
    let rows: Row[];
    if (reconciliationId) {
      rows = (await sql`
        UPDATE bank_transactions
        SET status = 'matched', matched_journal_line_id = ${journalLineId}::UUID,
            reconciliation_id = ${reconciliationId}::UUID
        WHERE id = ${bankTxId}::UUID AND company_id = ${companyId}::UUID RETURNING *`) as Row[];
    } else {
      rows = (await sql`
        UPDATE bank_transactions
        SET status = 'matched', matched_journal_line_id = ${journalLineId}::UUID
        WHERE id = ${bankTxId}::UUID AND company_id = ${companyId}::UUID RETURNING *`) as Row[];
    }
    if (rows.length === 0) throw new Error(`Bank transaction ${bankTxId} not found`);
    log.info('Matched bank transaction', { bankTxId, journalLineId }, 'accounting');
    return mapTxRow(rows[0]!);
  } catch (err) {
    log.error('Failed to match bank transaction', { bankTxId, error: err }, 'accounting');
    throw err;
  }
}

export async function unmatchTransaction(companyId: string, bankTxId: string): Promise<BankTransaction> {
  try {
    const rows = (await sql`
      UPDATE bank_transactions
      SET status = 'imported', matched_journal_line_id = NULL,
          allocation_type = NULL, allocated_entity_name = NULL
      WHERE id = ${bankTxId}::UUID AND company_id = ${companyId}::UUID RETURNING *`) as Row[];
    if (rows.length === 0) throw new Error(`Bank transaction ${bankTxId} not found`);
    log.info('Unmatched bank transaction', { bankTxId }, 'accounting');
    return mapTxRow(rows[0]!);
  } catch (err) {
    log.error('Failed to unmatch bank transaction', { bankTxId, error: err }, 'accounting');
    throw err;
  }
}

export async function excludeTransaction(
  companyId: string, bankTxId: string, reason?: string
): Promise<BankTransaction> {
  try {
    const rows = (await sql`
      UPDATE bank_transactions SET status = 'excluded', exclude_reason = ${reason || null}
      WHERE id = ${bankTxId}::UUID AND company_id = ${companyId}::UUID RETURNING *`) as Row[];
    if (rows.length === 0) throw new Error(`Bank transaction ${bankTxId} not found`);
    log.info('Excluded bank transaction', { bankTxId, reason }, 'accounting');
    return mapTxRow(rows[0]!);
  } catch (err) {
    log.error('Failed to exclude bank transaction', { bankTxId, error: err }, 'accounting');
    throw err;
  }
}

/** Delete bank transactions — only imported (unallocated) transactions can be deleted. */
export async function deleteTransactions(companyId: string, bankTxIds: string[]): Promise<number> {
  if (bankTxIds.length === 0) return 0;
  try {
    const result = (await sql`
      DELETE FROM bank_transactions
      WHERE id = ANY(${bankTxIds}::UUID[]) AND status = 'imported'
        AND company_id = ${companyId}::UUID`) as Row[];
    const deleted = result.length ?? bankTxIds.length;
    log.info('Deleted bank transactions', { count: deleted, ids: bankTxIds }, 'accounting');
    return deleted;
  } catch (err) {
    log.error('Failed to delete bank transactions', { bankTxIds, error: err }, 'accounting');
    throw err;
  }
}

/** Mark a batch of imported/allocated transactions as matched without creating journal entries. */
export async function bulkAcceptTransactions(companyId: string, ids: string[]): Promise<number> {
  if (ids.length === 0) return 0;
  try {
    const result = (await sql`
      UPDATE bank_transactions SET status = 'matched', updated_at = NOW()
      WHERE id = ANY(${ids}::UUID[]) AND status IN ('imported', 'allocated')
        AND company_id = ${companyId}::UUID`) as Row[];
    const count = (result as unknown as { count?: number }).count ?? ids.length;
    log.info('Bulk accepted bank transactions', { count, ids }, 'accounting');
    return count;
  } catch (err) {
    log.error('Failed to bulk accept bank transactions', { ids, error: err }, 'accounting');
    throw err;
  }
}

/**
 * PRD-060: FibreFlow Accounting Module
 * Payment Allocation Validation
 *
 * Validates that payment allocations across invoices are correct:
 * - No overpayment per invoice
 * - Total allocations don't exceed payment amount
 * - No duplicate invoice allocations
 * - All referenced invoices exist
 */

import type {
  PaymentAllocationInput,
  PaymentAllocationResult,
  InvoiceForAllocation,
} from '../types/ap.types';

/**
 * Validate payment allocations against invoices.
 */
export function validatePaymentAllocations(
  paymentAmount: number,
  allocations: PaymentAllocationInput[],
  invoices: InvoiceForAllocation[]
): PaymentAllocationResult {
  const errors: string[] = [];
  const invoiceMap = new Map(invoices.map(inv => [inv.id, inv]));
  const resultAllocations: PaymentAllocationResult['allocations'] = [];

  // Check for duplicate invoice IDs
  const invoiceIds = allocations.map(a => a.invoiceId);
  const duplicates = invoiceIds.filter((id, i) => invoiceIds.indexOf(id) !== i);
  if (duplicates.length > 0) {
    errors.push(`Duplicate invoice allocations: ${duplicates.join(', ')}`);
    return {
      valid: false,
      allocations: [],
      totalAllocated: 0,
      unallocated: paymentAmount,
      errors,
    };
  }

  let totalAllocated = 0;

  for (const alloc of allocations) {
    // Validate amount is positive
    if (alloc.amount <= 0) {
      errors.push(`Allocation amount must be positive (invoice: ${alloc.invoiceId}, amount: ${alloc.amount})`);
      continue;
    }

    // Validate invoice exists
    const invoice = invoiceMap.get(alloc.invoiceId);
    if (!invoice) {
      errors.push(`Invoice not found: ${alloc.invoiceId}`);
      continue;
    }

    // Validate doesn't exceed invoice balance
    if (alloc.amount > invoice.balance) {
      errors.push(
        `Allocation R${alloc.amount.toFixed(2)} exceeds invoice ${invoice.invoiceNumber} balance of R${invoice.balance.toFixed(2)}`
      );
      continue;
    }

    const newBalance = Math.round((invoice.balance - alloc.amount) * 100) / 100;

    resultAllocations.push({
      invoiceId: alloc.invoiceId,
      amount: alloc.amount,
      newBalance,
      fullyPaid: newBalance === 0,
    });

    totalAllocated += alloc.amount;
  }

  // Check total allocations don't exceed payment amount
  totalAllocated = Math.round(totalAllocated * 100) / 100;
  if (totalAllocated > paymentAmount) {
    errors.push(
      `Total allocations R${totalAllocated.toFixed(2)} exceed payment amount R${paymentAmount.toFixed(2)}`
    );
  }

  const unallocated = Math.round((paymentAmount - totalAllocated) * 100) / 100;

  return {
    valid: errors.length === 0,
    allocations: resultAllocations,
    totalAllocated,
    unallocated: Math.max(0, unallocated),
    errors,
  };
}

/**
 * PRD-060: FibreFlow Accounting Module
 * Bank Transaction Auto-Match Algorithm
 *
 * Four-tier matching strategy:
 *   Tier 0: Rule-based match via bank_categorisation_rules (confidence 1.0)
 *   Tier 1: Exact reference match (confidence 1.0)
 *   Tier 2: Amount + date within 3 days (confidence 0.9)
 *   Tier 3: Amount only match (confidence 0.7)
 */

import type { AutoMatchCandidate } from '../types/bank.types';

interface BankTxForMatch {
  id: string;
  amount: number;
  transactionDate: string;
  reference?: string;
  description?: string;
}

interface JournalLineForMatch {
  id: string;
  debit: number;
  credit: number;
  description?: string;
  entryDate: string;
  entryNumber?: string;
  sourceDocumentId?: string;
}

/**
 * Find match candidates for a single bank transaction against unmatched GL journal lines.
 * Returns candidates sorted by confidence DESC.
 */
export function findMatchCandidates(
  bankTx: BankTxForMatch,
  glLines: JournalLineForMatch[],
  threshold: number = 0.7
): AutoMatchCandidate[] {
  const candidates: AutoMatchCandidate[] = [];
  const txAmount = Math.abs(bankTx.amount);
  const isDeposit = bankTx.amount > 0;

  for (const line of glLines) {
    // For deposits, match against credit lines; for withdrawals, match against debit lines
    const lineAmount = isDeposit ? line.credit : line.debit;
    if (lineAmount <= 0) continue;

    const amountMatch = Math.abs(txAmount - lineAmount) < 0.02;
    if (!amountMatch) continue;

    // Tier 1: Exact reference match
    if (bankTx.reference && bankTx.reference.trim().length > 2) {
      const ref = bankTx.reference.toLowerCase().trim();
      const lineDesc = (line.description || '').toLowerCase();
      const entryNum = (line.entryNumber || '').toLowerCase();
      const sourceDoc = (line.sourceDocumentId || '').toLowerCase();

      if (lineDesc.includes(ref) || entryNum.includes(ref) || ref.includes(entryNum) || sourceDoc.includes(ref)) {
        candidates.push({
          bankTransactionId: bankTx.id,
          journalLineId: line.id,
          confidence: 1.0,
          matchReason: 'exact_reference',
        });
        continue;
      }
    }

    // Check description-based reference match
    if (bankTx.description && bankTx.description.trim().length > 3) {
      const desc = bankTx.description.toLowerCase().trim();
      const lineDesc = (line.description || '').toLowerCase();
      if (lineDesc.length > 3 && (desc.includes(lineDesc) || lineDesc.includes(desc))) {
        candidates.push({
          bankTransactionId: bankTx.id,
          journalLineId: line.id,
          confidence: 0.95,
          matchReason: 'exact_reference',
        });
        continue;
      }
    }

    // Tier 2: Amount + date within 3 days
    const daysDiff = Math.abs(dateDiffDays(bankTx.transactionDate, line.entryDate));
    if (daysDiff <= 3) {
      candidates.push({
        bankTransactionId: bankTx.id,
        journalLineId: line.id,
        confidence: 0.9,
        matchReason: 'amount_date',
      });
      continue;
    }

    // Tier 3: Amount only
    candidates.push({
      bankTransactionId: bankTx.id,
      journalLineId: line.id,
      confidence: 0.7,
      matchReason: 'amount_only',
    });
  }

  return candidates
    .filter(c => c.confidence >= threshold)
    .sort((a, b) => b.confidence - a.confidence);
}

/**
 * Run auto-match across multiple bank transactions.
 * Returns best single match per bank transaction (highest confidence).
 * Prevents duplicate GL line matches.
 */
export function runAutoMatch(
  bankTxs: BankTxForMatch[],
  glLines: JournalLineForMatch[],
  threshold: number = 0.7
): { matches: AutoMatchCandidate[]; unmatched: string[] } {
  const matches: AutoMatchCandidate[] = [];
  const usedGlLines = new Set<string>();
  const unmatched: string[] = [];

  // Sort bank transactions by amount DESC for better matching priority
  const sorted = [...bankTxs].sort((a, b) => Math.abs(b.amount) - Math.abs(a.amount));

  for (const tx of sorted) {
    const availableLines = glLines.filter(l => !usedGlLines.has(l.id));
    const candidates = findMatchCandidates(tx, availableLines, threshold);

    if (candidates.length > 0) {
      const best = candidates[0]!;
      matches.push(best);
      usedGlLines.add(best.journalLineId);
    } else {
      unmatched.push(tx.id);
    }
  }

  return { matches, unmatched };
}

function dateDiffDays(dateA: string, dateB: string): number {
  const a = new Date(dateA);
  const b = new Date(dateB);
  return Math.round((a.getTime() - b.getTime()) / (1000 * 60 * 60 * 24));
}

/**
 * PRD-060: FibreFlow Accounting Module — Phase 3
 * AR Aging Report Service
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { calculateAgingBuckets } from '../utils/aging';
import type { AgingBucket, AgingInvoice } from '../types/ap.types';
type Row = Record<string, unknown>;


export async function getARAging(companyId: string, asAtDate?: string): Promise<AgingBucket[]> {
  try {
    const asAt = asAtDate ? new Date(asAtDate) : new Date();

    const rows = (await sql`
      SELECT ci.id, COALESCE(ci.client_id, ci.customer_id) AS entity_id, c.name AS entity_name,
        ci.due_date, ci.total_amount, ci.amount_paid,
        (ci.total_amount - ci.amount_paid) AS balance
      FROM customer_invoices ci
      JOIN customers c ON c.id = COALESCE(ci.client_id, ci.customer_id)
      WHERE ci.company_id = ${companyId}
        AND ci.status IN ('approved', 'sent', 'partially_paid', 'overdue')
        AND (ci.total_amount - ci.amount_paid) > 0
        AND ci.due_date IS NOT NULL
      ORDER BY ci.due_date
    `) as Row[];

    const invoices: AgingInvoice[] = rows.map((r: Row) => ({
      id: String(r.id),
      entityId: String(r.entity_id),
      entityName: String(r.entity_name),
      dueDate: String(r.due_date),
      totalAmount: Number(r.total_amount),
      amountPaid: Number(r.amount_paid),
      balance: Number(r.balance),
    }));

    // Include unallocated credit notes as negative balances
    const cnRows = (await sql`
      SELECT cn.id, cn.client_id AS entity_id, c.name AS entity_name,
        cn.credit_date AS due_date, cn.total_amount, 0 AS amount_paid,
        -cn.total_amount AS balance
      FROM credit_notes cn
      JOIN customers c ON c.id = cn.client_id
      WHERE cn.company_id = ${companyId}
        AND cn.type = 'customer' AND cn.status = 'approved'
        AND cn.customer_invoice_id IS NULL
    `) as Row[];

    for (const r of cnRows) {
      invoices.push({
        id: String(r.id),
        entityId: String(r.entity_id),
        entityName: String(r.entity_name),
        dueDate: String(r.due_date),
        totalAmount: Number(r.total_amount),
        amountPaid: Number(r.amount_paid),
        balance: Number(r.balance),
      });
    }

    return calculateAgingBuckets(invoices, asAt);
  } catch (err) {
    log.error('Failed to get AR aging', { error: err }, 'accounting');
    throw err;
  }
}

export async function getARAgingDetail(companyId: string, 
  clientId: string,
  asAtDate?: string
): Promise<{ client: { id: string; name: string }; invoices: AgingInvoice[]; buckets: AgingBucket | null }> {
  try {
    const asAt = asAtDate ? new Date(asAtDate) : new Date();

    const clientRows = (await sql`SELECT id, name AS name FROM customers WHERE id = ${clientId}::UUID AND company_id = ${companyId}`) as Row[];
    if (clientRows.length === 0) throw new Error(`Client ${clientId} not found`);

    const rows = (await sql`
      SELECT ci.id, COALESCE(ci.client_id, ci.customer_id) AS entity_id, c.name AS entity_name,
        ci.due_date, ci.invoice_number, ci.total_amount, ci.amount_paid,
        (ci.total_amount - ci.amount_paid) AS balance
      FROM customer_invoices ci
      JOIN customers c ON c.id = COALESCE(ci.client_id, ci.customer_id)
      WHERE ci.company_id = ${companyId}
        AND COALESCE(ci.client_id, ci.customer_id) = ${clientId}::UUID
        AND ci.status IN ('approved', 'sent', 'partially_paid', 'overdue')
        AND (ci.total_amount - ci.amount_paid) > 0
        AND ci.due_date IS NOT NULL
      ORDER BY ci.due_date
    `) as Row[];

    const invoices: AgingInvoice[] = rows.map((r: Row) => ({
      id: String(r.id),
      entityId: String(r.entity_id),
      entityName: String(r.entity_name),
      dueDate: String(r.due_date),
      totalAmount: Number(r.total_amount),
      amountPaid: Number(r.amount_paid),
      balance: Number(r.balance),
    }));

    const buckets = calculateAgingBuckets(invoices, asAt);
    return {
      client: { id: String(clientRows[0]!.id), name: String(clientRows[0]!.name) },
      invoices,
      buckets: buckets.length > 0 ? buckets[0]! : null,
    };
  } catch (err) {
    log.error('Failed to get AR aging detail', { clientId, error: err }, 'accounting');
    throw err;
  }
}

/**
 * CaseWare Export Service — WS-7.3
 * Exports trial balance in CaseWare CSV format with configurable account mappings.
 */

