}

export interface TemplateInput {
  id?: string;
  name: string;
  description?: string;
  dataSource: string;
  columns: ReportColumn[];
  filters?: ReportFilter[];
  sortBy?: ReportSort[];
  groupBy?: string[];
  totals?: Record<string, boolean>;
  layoutOptions?: Record<string, unknown>;
  isShared?: boolean;
  schedule?: unknown;
}

// Re-exports
export { getAvailableFields };
export { runReport } from './customReportRunner';

// ─── CRUD ────────────────────────────────────────────────────────────────────

export async function getTemplates(companyId: string, userId: string): Promise<ReportTemplate[]> {
  const rows = await sql`
    SELECT id, company_id, created_by, name, description, data_source,
      columns, filters, sort_by, group_by, totals, layout_options,
      is_shared, schedule, created_at, updated_at
    FROM custom_report_templates
    WHERE company_id = ${companyId}
      AND (created_by = ${userId} OR is_shared = true)
    ORDER BY updated_at DESC
  `;
  return rows.map(r => mapTemplate(r as Row));
}

export async function getTemplateById(companyId: string, id: string): Promise<ReportTemplate | null> {
  const rows = await sql`
    SELECT id, company_id, created_by, name, description, data_source,
      columns, filters, sort_by, group_by, totals, layout_options,
      is_shared, schedule, created_at, updated_at
    FROM custom_report_templates
    WHERE company_id = ${companyId} AND id = ${id}
  `;
  if (!rows[0]) return null;
  return mapTemplate(rows[0] as Row);
}

export async function saveTemplate(
  companyId: string,
  userId: string,
  input: TemplateInput,
): Promise<ReportTemplate> {
  const cols    = JSON.stringify(input.columns ?? []);
  const filters = JSON.stringify(input.filters ?? []);
  const sortBy  = JSON.stringify(input.sortBy ?? []);
  const groupBy = JSON.stringify(input.groupBy ?? []);
  const totals  = JSON.stringify(input.totals ?? {});
  const layout  = JSON.stringify(input.layoutOptions ?? {});
  const sched   = input.schedule ? JSON.stringify(input.schedule) : null;
  const shared  = input.isShared ?? false;

  if (input.id) {
    const existing = await getTemplateById(companyId, input.id);
    if (!existing) throw new Error('Template not found');
    if (existing.createdBy !== userId) throw new Error('You do not own this template');

    const rows = await sql`
      UPDATE custom_report_templates SET
        name = ${input.name}, description = ${input.description ?? null},
        data_source = ${input.dataSource},
        columns = ${cols}::jsonb, filters = ${filters}::jsonb,
        sort_by = ${sortBy}::jsonb, group_by = ${groupBy}::jsonb,
        totals = ${totals}::jsonb, layout_options = ${layout}::jsonb,
        is_shared = ${shared}, schedule = ${sched}::jsonb,
        updated_at = NOW()
      WHERE company_id = ${companyId} AND id = ${input.id}
      RETURNING *
    `;
    if (!rows[0]) throw new Error('Update returned no row');
    log.info('Template updated', { id: input.id, companyId }, 'CustomReportService');
    return mapTemplate(rows[0] as Row);
  }

  const rows = await sql`
    INSERT INTO custom_report_templates
      (company_id, created_by, name, description, data_source, columns, filters,
       sort_by, group_by, totals, layout_options, is_shared, schedule)
    VALUES (
      ${companyId}, ${userId}, ${input.name}, ${input.description ?? null},
      ${input.dataSource}, ${cols}::jsonb, ${filters}::jsonb,
      ${sortBy}::jsonb, ${groupBy}::jsonb, ${totals}::jsonb, ${layout}::jsonb,
      ${shared}, ${sched}::jsonb
    )
    RETURNING *
  `;
  if (!rows[0]) throw new Error('Insert returned no row');
  log.info('Template created', { id: (rows[0] as Row).id, companyId }, 'CustomReportService');
  return mapTemplate(rows[0] as Row);
}

export async function deleteTemplate(companyId: string, userId: string, id: string): Promise<void> {
  const existing = await getTemplateById(companyId, id);
  if (!existing) throw new Error('Template not found');
  if (existing.createdBy !== userId) throw new Error('You do not own this template');
  await sql`DELETE FROM custom_report_templates WHERE company_id = ${companyId} AND id = ${id}`;
  log.info('Template deleted', { id, companyId }, 'CustomReportService');
}

// ─── Mapper ──────────────────────────────────────────────────────────────────

function mapTemplate(r: Row): ReportTemplate {
  return {
    id: String(r.id),
    companyId: String(r.company_id),
    createdBy: String(r.created_by),
    name: String(r.name),
    description: r.description ? String(r.description) : null,
    dataSource: String(r.data_source),
    columns: (r.columns ?? []) as ReportColumn[],
    filters: (r.filters ?? []) as ReportFilter[],
    sortBy: (r.sort_by ?? []) as ReportSort[],
    groupBy: (r.group_by ?? []) as string[],
    totals: (r.totals ?? {}) as Record<string, boolean>,
    layoutOptions: (r.layout_options ?? {}) as Record<string, unknown>,
    isShared: Boolean(r.is_shared),
    schedule: r.schedule ?? null,
    createdAt: r.created_at,
    updatedAt: r.updated_at,
  };
}

/**
 * Duplicate Detection Service — Detection
 * PRD: WS-6.6 — Duplicate Detection and Merge Wizard
 *
 * Detects potential duplicate customers, suppliers, and items using
 * fuzzy name matching, exact email matching, and VAT number matching.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { fuzzyMatch } from '@/modules/accounting/utils/fuzzyMatcher';
import { mergeEntities } from './duplicateMergeService';

type Row = Record<string, unknown>;

// ── Types ─────────────────────────────────────────────────────────────────────

export interface DuplicateEntity {
  id: string;
  name: string;
  email?: string;
  vatNumber?: string;
  phone?: string;
  [key: string]: unknown;
}

export interface DuplicatePair {
  entityType: 'customer' | 'supplier' | 'item';
  primary: DuplicateEntity;
  duplicate: DuplicateEntity;
  confidence: number;   // 0–100
  matchReasons: string[];
}

// Re-export merge so consumers only need one import
export { mergeEntities };
export type { MergeResult } from './duplicateMergeService';

// ── Public API ────────────────────────────────────────────────────────────────

export async function detectDuplicates(
  companyId: string,
  entityType: 'customer' | 'supplier' | 'item',
): Promise<DuplicatePair[]> {
  log.info('Detecting duplicates', { companyId, entityType }, 'duplicate-detection');

  if (entityType === 'customer') return detectCustomerDuplicates(companyId);
  if (entityType === 'supplier') return detectSupplierDuplicates(companyId);
  return detectItemDuplicates(companyId);
}

// ── Customer detection ────────────────────────────────────────────────────────

async function detectCustomerDuplicates(companyId: string): Promise<DuplicatePair[]> {
  const rows = (await sql`
    SELECT id, name, email, vat_number, phone, registration_number, contact_person, billing_address
    FROM customers
    WHERE company_id = ${companyId}::UUID
      AND deleted_at IS NULL
      AND is_active = true
    ORDER BY name
  `) as Row[];

  const entities: DuplicateEntity[] = rows.map((r: Row) => ({
    id: r.id as string,
    name: r.name as string,
    email: r.email != null ? String(r.email) : undefined,
    vatNumber: r.vat_number != null ? String(r.vat_number) : undefined,
    phone: r.phone != null ? String(r.phone) : undefined,
    registrationNumber: r.registration_number != null ? String(r.registration_number) : undefined,
    contactPerson: r.contact_person != null ? String(r.contact_person) : undefined,
    billingAddress: r.billing_address != null ? String(r.billing_address) : undefined,
  }));

  const pairs = findDuplicatePairs(entities, 'customer', 0.85);
  log.info('Customer duplicate scan complete', { count: pairs.length, companyId }, 'duplicate-detection');
  return pairs;
}

// ── Supplier detection ────────────────────────────────────────────────────────

async function detectSupplierDuplicates(companyId: string): Promise<DuplicatePair[]> {
  const rows = (await sql`
    SELECT id, name, email, vat_number, phone, registration_number, contact_person, address
    FROM suppliers
    WHERE company_id = ${companyId}::UUID
      AND deleted_at IS NULL
      AND is_active = true
    ORDER BY name
  `) as Row[];

  const entities: DuplicateEntity[] = rows.map((r: Row) => ({
    id: r.id as string,
    name: r.name as string,
    email: r.email != null ? String(r.email) : undefined,
    vatNumber: r.vat_number != null ? String(r.vat_number) : undefined,
    phone: r.phone != null ? String(r.phone) : undefined,
    registrationNumber: r.registration_number != null ? String(r.registration_number) : undefined,
    contactPerson: r.contact_person != null ? String(r.contact_person) : undefined,
    address: r.address != null ? String(r.address) : undefined,
  }));

  const pairs = findDuplicatePairs(entities, 'supplier', 0.85);
  log.info('Supplier duplicate scan complete', { count: pairs.length, companyId }, 'duplicate-detection');
  return pairs;
}

// ── Item detection ────────────────────────────────────────────────────────────

async function detectItemDuplicates(companyId: string): Promise<DuplicatePair[]> {
  const rows = (await sql`
    SELECT id, code, description, item_type, unit, cost_price, selling_price_excl
    FROM items
    WHERE company_id = ${companyId}::UUID
      AND deleted_at IS NULL
      AND is_active = true
    ORDER BY code
  `) as Row[];

  const pairs: DuplicatePair[] = [];
  const seen = new Set<string>();

  for (let i = 0; i < rows.length; i++) {
    for (let j = i + 1; j < rows.length; j++) {
      const a = rows[i] as Row;
      const b = rows[j] as Row;
      const pairKey = [a.id as string, b.id as string].sort().join(':');
      if (seen.has(pairKey)) continue;

      const reasons: string[] = [];
      let confidence = 0;

      if (a.code && b.code && (a.code as string).toLowerCase() === (b.code as string).toLowerCase()) {
        reasons.push(`Same item code: ${a.code as string}`);
        confidence = 100;
      } else {
        const nameResult = fuzzyMatch(a.description as string, [b.description as string], 0.90);
        if (nameResult) {
          const pct = Math.round(nameResult.score * 100);
          reasons.push(`Name ${pct}% match`);
          confidence = Math.max(confidence, pct);
        }
      }

      if (reasons.length > 0) {
        seen.add(pairKey);
        pairs.push({
          entityType: 'item',
          primary: { id: a.id as string, name: a.description as string, itemCode: a.code, itemType: a.item_type, unit: a.unit, costPrice: a.cost_price },
          duplicate: { id: b.id as string, name: b.description as string, itemCode: b.code, itemType: b.item_type, unit: b.unit, costPrice: b.cost_price },
          confidence,
          matchReasons: reasons,
        });
      }
    }
  }

  log.info('Item duplicate scan complete', { count: pairs.length, companyId }, 'duplicate-detection');
  return pairs;
}

// ── Generic pair-finding ──────────────────────────────────────────────────────

function findDuplicatePairs(
  entities: DuplicateEntity[],
  entityType: 'customer' | 'supplier',
  nameThreshold: number,
): DuplicatePair[] {
  const pairs: DuplicatePair[] = [];
  const seen = new Set<string>();

  // For >500 entities, bucket by first 3 chars to reduce O(n²) comparisons
  const useBucketing = entities.length > 500;
  const compareGroups: DuplicateEntity[][] = useBucketing
    ? buildBuckets(entities)
    : [entities];

  for (const group of compareGroups) {
    for (let i = 0; i < group.length; i++) {
      for (let j = i + 1; j < group.length; j++) {
        const a = group[i]!;
        const b = group[j]!;
        const pairKey = [a.id, b.id].sort().join(':');
        if (seen.has(pairKey)) continue;

        const { reasons, confidence } = scorePair(a, b, nameThreshold);
        if (reasons.length > 0) {
          seen.add(pairKey);
          pairs.push({ entityType, primary: a, duplicate: b, confidence: Math.min(confidence, 100), matchReasons: reasons });
        }
      }
    }
  }

  pairs.sort((a, b) => b.confidence - a.confidence);
  return pairs;
}

function buildBuckets(entities: DuplicateEntity[]): DuplicateEntity[][] {
  const map = new Map<string, DuplicateEntity[]>();
  for (const e of entities) {
    const key = e.name.toLowerCase().slice(0, 3);
    if (!map.has(key)) map.set(key, []);
    map.get(key)!.push(e);
  }
  return Array.from(map.values());
}

function scorePair(a: DuplicateEntity, b: DuplicateEntity, nameThreshold: number): { reasons: string[]; confidence: number } {
  const reasons: string[] = [];
  let confidence = 0;

  if (a.vatNumber && b.vatNumber && a.vatNumber === b.vatNumber) {
    reasons.push(`Same VAT number: ${a.vatNumber}`);
    confidence = Math.max(confidence, 95);
  }

  if (a.email && b.email && a.email.toLowerCase() === b.email.toLowerCase()) {
    reasons.push(`Same email: ${a.email}`);
    confidence = Math.max(confidence, 90);
  }

  const nameResult = fuzzyMatch(a.name, [b.name], nameThreshold);
  if (nameResult) {
    const pct = Math.round(nameResult.score * 100);
    reasons.push(`Name ${pct}% match`);
    confidence = Math.max(confidence, pct);
  }

  return { reasons, confidence };
}

/**
 * Cash Flow Forecasting Service
 * Projects future cash position based on historical patterns,
 * recurring invoices, known payables, and seasonal trends.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// ── Types ────────────────────────────────────────────────────────────────────

export interface CashFlowForecastPoint {
  date: string;          // YYYY-MM-DD
  label: string;         // "Apr 2026", "Week 14", etc.
  projectedInflow: number;
  projectedOutflow: number;
  projectedNet: number;
  projectedBalance: number;
  confidence: number;    // 0-1
}

export interface CashFlowAlert {
  type: 'warning' | 'danger';
  message: string;
  date: string;
  projectedBalance: number;
}

export interface CashFlowForecastResult {
  currentBalance: number;
  forecastPoints: CashFlowForecastPoint[];
  alerts: CashFlowAlert[];
  assumptions: string[];
  generatedAt: string;
}

export interface HistoricalCashFlow {
  month: string;
  inflow: number;
  outflow: number;
  net: number;
}

// ── Historical Analysis ──────────────────────────────────────────────────────

/** Get current total cash balance across all bank accounts */
async function getCurrentCashBalance(companyId: string): Promise<number> {
  const rows = (await sql`
    SELECT COALESCE(SUM(
      CASE WHEN ga.account_subtype IN ('bank', 'cash')
        THEN COALESCE(
          (SELECT SUM(jl.debit) - SUM(jl.credit)
           FROM gl_journal_lines jl
           JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
           WHERE jl.gl_account_id = ga.id
             AND je.status = 'posted'
             AND je.company_id = ${companyId}),
          0)
        ELSE 0
      END
    ), 0) AS total_cash
    FROM gl_accounts ga
    WHERE ga.company_id = ${companyId}
      AND ga.account_type = 'asset'
      AND ga.account_subtype IN ('bank', 'cash')
      AND ga.is_active = true
  `) as Record<string, unknown>[];
  return Number(rows[0]?.total_cash ?? 0);
}

/** Get monthly cash inflows and outflows for the last N months */
async function getHistoricalCashFlows(companyId: string, months: number): Promise<HistoricalCashFlow[]> {
  // Compute the start date in JS to avoid interval arithmetic in tagged templates
  const startDate = new Date();
  startDate.setMonth(startDate.getMonth() - months);
  const startStr = startDate.toISOString().split('T')[0]!;

  const rows = (await sql`
    WITH monthly AS (
      SELECT
        date_trunc('month', je.entry_date) AS month,
        COALESCE(SUM(CASE WHEN jl.debit > 0 AND ga.account_subtype IN ('bank', 'cash') THEN jl.debit ELSE 0 END), 0) AS inflow,
        COALESCE(SUM(CASE WHEN jl.credit > 0 AND ga.account_subtype IN ('bank', 'cash') THEN jl.credit ELSE 0 END), 0) AS outflow
      FROM gl_journal_lines jl
      JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
      JOIN gl_accounts ga ON ga.id = jl.gl_account_id
      WHERE je.company_id = ${companyId}
        AND je.status = 'posted'
        AND ga.account_type = 'asset'
        AND ga.account_subtype IN ('bank', 'cash')
        AND je.entry_date >= ${startStr}::DATE
      GROUP BY date_trunc('month', je.entry_date)
    )
    SELECT
      to_char(month, 'YYYY-MM') AS month,
      inflow,
      outflow,
      (inflow - outflow) AS net
    FROM monthly
    ORDER BY month ASC
  `) as Record<string, unknown>[];

  return rows.map((r: Record<string, unknown>) => ({
    month: String(r.month),
    inflow: Number(r.inflow),
    outflow: Number(r.outflow),
    net: Number(r.net),
  }));
}

/** Get known future receivables (unpaid customer invoices) */
async function getExpectedReceivables(companyId: string): Promise<Array<{ dueDate: string; amount: number }>> {
  const rows = (await sql`
    SELECT due_date, SUM(total_amount - COALESCE(amount_paid, 0)) AS amount_due
    FROM customer_invoices
    WHERE company_id = ${companyId}
      AND status IN ('sent', 'overdue', 'approved')
      AND due_date >= CURRENT_DATE
      AND (total_amount - COALESCE(amount_paid, 0)) > 0
    GROUP BY due_date
    ORDER BY due_date ASC
  `) as Record<string, unknown>[];

  return rows.map((r: Record<string, unknown>) => ({
    dueDate: String(r.due_date),
    amount: Number(r.amount_due),
  }));
}

/** Get known future payables (unpaid supplier invoices) */
async function getExpectedPayables(companyId: string): Promise<Array<{ dueDate: string; amount: number }>> {
  const rows = (await sql`
    SELECT due_date, SUM(total_amount - COALESCE(amount_paid, 0)) AS amount_due
    FROM supplier_invoices
    WHERE company_id = ${companyId}
      AND status IN ('approved', 'received', 'overdue')
      AND due_date >= CURRENT_DATE
      AND (total_amount - COALESCE(amount_paid, 0)) > 0
    GROUP BY due_date
    ORDER BY due_date ASC
  `) as Record<string, unknown>[];

  return rows.map((r: Record<string, unknown>) => ({
    dueDate: String(r.due_date),
    amount: Number(r.amount_due),
  }));
}

/** Get recurring invoice amounts for projection */
async function getRecurringRevenue(companyId: string): Promise<number> {
  const rows = (await sql`
    SELECT COALESCE(SUM(total_amount), 0) AS monthly_recurring
    FROM recurring_invoices
    WHERE company_id = ${companyId}
      AND status = 'active'
      AND frequency = 'monthly'
  `) as Record<string, unknown>[];
  return Number(rows[0]?.monthly_recurring ?? 0);
}

// ── Forecasting Engine ───────────────────────────────────────────────────────

/**
 * Generate a cash flow forecast for the next N months.
 * Uses a blend of:
 * 1. Known receivables and payables (high confidence)
 * 2. Recurring invoices (medium-high confidence)
 * 3. Historical average patterns (medium confidence)
 * 4. Seasonal adjustment from same month prior year (lower confidence)
 */
export async function generateForecast(companyId: string, 
  forecastMonths = 6,
  alertThreshold = 0
): Promise<CashFlowForecastResult> {
  const [currentBalance, historical, receivables, payables, recurringRevenue] = await Promise.all([
    getCurrentCashBalance(companyId),
    getHistoricalCashFlows(companyId, 12),
    getExpectedReceivables(companyId),
    getExpectedPayables(companyId),
    getRecurringRevenue(companyId),
  ]);

  // Calculate historical averages
  const avgInflow = historical.length > 0
    ? historical.reduce((sum, h) => sum + h.inflow, 0) / historical.length
    : 0;
  const avgOutflow = historical.length > 0
    ? historical.reduce((sum, h) => sum + h.outflow, 0) / historical.length
    : 0;

  // Build month-by-month forecast
  const forecastPoints: CashFlowForecastPoint[] = [];
  const alerts: CashFlowAlert[] = [];
  let runningBalance = currentBalance;
  const now = new Date();

  for (let i = 1; i <= forecastMonths; i++) {
    const forecastDate = new Date(now.getFullYear(), now.getMonth() + i, 1);
    const monthStr = forecastDate.toISOString().slice(0, 7); // YYYY-MM
    const monthLabel = forecastDate.toLocaleDateString('en-ZA', { month: 'short', year: 'numeric' });

    // Known receivables due this month
    const knownInflows = receivables
      .filter(r => String(r.dueDate).startsWith(monthStr))
      .reduce((sum, r) => sum + r.amount, 0);

    // Known payables due this month
    const knownOutflows = payables
      .filter(p => String(p.dueDate).startsWith(monthStr))
      .reduce((sum, p) => sum + p.amount, 0);

    // Projected inflow: known receivables + recurring revenue + historical average for unknowns
    const knownInflowWeight = knownInflows > 0 ? 0.7 : 0;
    const historicalInflowWeight = 1 - knownInflowWeight;
    const projectedInflow = knownInflows + recurringRevenue + (avgInflow * historicalInflowWeight * 0.5);

    // Projected outflow: known payables + historical average for unknowns
    const knownOutflowWeight = knownOutflows > 0 ? 0.7 : 0;
    const historicalOutflowWeight = 1 - knownOutflowWeight;
    const projectedOutflow = knownOutflows + (avgOutflow * historicalOutflowWeight * 0.5);

    const projectedNet = projectedInflow - projectedOutflow;
    runningBalance += projectedNet;

    // Confidence decreases as we project further out
    const baseConfidence = 0.9;
    const decayFactor = 0.1;
    const knownDataBoost = (knownInflows + knownOutflows > 0) ? 0.1 : 0;
    const confidence = Math.max(0.3, baseConfidence - (i * decayFactor) + knownDataBoost);

    forecastPoints.push({
      date: forecastDate.toISOString().slice(0, 10),
      label: monthLabel,
      projectedInflow: Math.round(projectedInflow * 100) / 100,
      projectedOutflow: Math.round(projectedOutflow * 100) / 100,
      projectedNet: Math.round(projectedNet * 100) / 100,
      projectedBalance: Math.round(runningBalance * 100) / 100,
      confidence: Math.round(confidence * 100) / 100,
    });

    // Generate alerts
    if (runningBalance < alertThreshold) {
      alerts.push({
        type: runningBalance < 0 ? 'danger' : 'warning',
        message: runningBalance < 0
          ? `Projected negative cash balance of R ${Math.abs(runningBalance).toLocaleString('en-ZA', { minimumFractionDigits: 2 })} in ${monthLabel}`
          : `Cash balance projected to drop below threshold in ${monthLabel}`,
        date: forecastDate.toISOString().slice(0, 10),
        projectedBalance: Math.round(runningBalance * 100) / 100,
      });
    }
  }

  // Build assumptions list
  const assumptions: string[] = [];
  if (historical.length > 0) {
    assumptions.push(`Based on ${historical.length} months of historical data`);
  } else {
    assumptions.push('Limited historical data — forecast accuracy may be low');
  }
  if (recurringRevenue > 0) {
    assumptions.push(`Includes R ${recurringRevenue.toLocaleString('en-ZA', { minimumFractionDigits: 2 })} monthly recurring revenue`);
  }
  if (receivables.length > 0) {
    const totalAR = receivables.reduce((s, r) => s + r.amount, 0);
    assumptions.push(`${receivables.length} outstanding invoices totalling R ${totalAR.toLocaleString('en-ZA', { minimumFractionDigits: 2 })}`);
  }
  if (payables.length > 0) {
    const totalAP = payables.reduce((s, p) => s + p.amount, 0);
    assumptions.push(`${payables.length} outstanding payables totalling R ${totalAP.toLocaleString('en-ZA', { minimumFractionDigits: 2 })}`);
  }
  assumptions.push('Confidence decreases for months further in the future');

  log.info('Cash flow forecast generated', {
    months: forecastMonths,
    currentBalance,
    pointCount: forecastPoints.length,
    alertCount: alerts.length,
  }, 'accounting');

  return {
    currentBalance: Math.round(currentBalance * 100) / 100,
    forecastPoints,
    alerts,
    assumptions,
    generatedAt: new Date().toISOString(),
  };
}

/** Get historical cash flow data for chart display */
export async function getHistoricalForChart(companyId: string, months = 6): Promise<HistoricalCashFlow[]> {
  return getHistoricalCashFlows(companyId, months);
}

/**
 * Recurring Invoice Service
 * Phase 1 Sage Alignment: Auto-generate customer invoices on schedule
 */

import { sql, withTransaction } from '@/lib/neon';
import { log } from '@/lib/logger';
import type {
  RecurringInvoice,
  RecurringInvoiceCreateInput,
} from '../types/ar.types';

type Row = Record<string, unknown>;

export async function getRecurringInvoices(companyId: string, filters?: {
  status?: string;
  clientId?: string;
  limit?: number;
  offset?: number;
}): Promise<{ items: RecurringInvoice[]; total: number }> {
  const limit = filters?.limit || 50;
  const offset = filters?.offset || 0;
  let rows: Row[];
  let countRows: Row[];

  if (filters?.clientId) {
    rows = (await sql`
      SELECT ri.*, c.name AS client_name
      FROM recurring_invoices ri LEFT JOIN customers c ON c.id = ri.client_id
      WHERE ri.company_id = ${companyId} AND ri.client_id = ${filters.clientId}::UUID
      ORDER BY ri.created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`
      SELECT COUNT(*) AS cnt FROM recurring_invoices
      WHERE company_id = ${companyId} AND client_id = ${filters.clientId}::UUID
    `) as Row[];
  } else if (filters?.status) {
    rows = (await sql`
      SELECT ri.*, c.name AS client_name
      FROM recurring_invoices ri LEFT JOIN customers c ON c.id = ri.client_id
      WHERE ri.company_id = ${companyId} AND ri.status = ${filters.status}
      ORDER BY ri.created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`
      SELECT COUNT(*) AS cnt FROM recurring_invoices WHERE company_id = ${companyId} AND status = ${filters.status}
    `) as Row[];
  } else {
    rows = (await sql`
      SELECT ri.*, c.name AS client_name
      FROM recurring_invoices ri LEFT JOIN customers c ON c.id = ri.client_id
      WHERE ri.company_id = ${companyId}
      ORDER BY ri.created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`SELECT COUNT(*) AS cnt FROM recurring_invoices WHERE company_id = ${companyId}`) as Row[];
  }

  return { items: rows.map(mapRow), total: Number(countRows[0]?.cnt || 0) };
}

export async function createRecurringInvoice(companyId: string, 
  input: RecurringInvoiceCreateInput,
  userId: string
): Promise<RecurringInvoice> {
  const taxRate = input.taxRate ?? 15;
  const subtotal = input.lineItems.reduce(
    (s, li) => s + li.quantity * li.unitPrice, 0
  );
  const taxAmount = Math.round(subtotal * (taxRate / 100) * 100) / 100;
  const totalAmount = subtotal + taxAmount;

  const rows = (await sql`
    INSERT INTO recurring_invoices (
      company_id, template_name, client_id, project_id, frequency, next_run_date,
      end_date, description, line_items, subtotal, tax_rate, tax_amount,
      total_amount, payment_terms, created_by
    ) VALUES (
      ${companyId}, ${input.templateName}, ${input.clientId}::UUID,
      ${input.projectId || null}, ${input.frequency}, ${input.nextRunDate},
      ${input.endDate || null}, ${input.description || null},
      ${JSON.stringify(input.lineItems)}::JSONB, ${subtotal}, ${taxRate},
      ${taxAmount}, ${totalAmount}, ${input.paymentTerms || '30 days'}, ${userId}::UUID
    ) RETURNING *
  `) as Row[];

  log.info('Created recurring invoice', { id: rows[0]?.id }, 'accounting');
  return mapRow(rows[0]!);
}

export async function updateRecurringStatus(companyId: string, 
  id: string,
  status: 'paused' | 'active' | 'cancelled'
): Promise<void> {
  await sql`UPDATE recurring_invoices SET status = ${status} WHERE id = ${id} AND company_id = ${companyId}`;
  log.info('Updated recurring invoice status', { id, status }, 'accounting');
}

export async function generateInvoiceFromRecurring(companyId: string, 
  id: string,
  userId: string
): Promise<string> {
  const rows = (await sql`SELECT * FROM recurring_invoices WHERE id = ${id} AND company_id = ${companyId}`) as Row[];
  if (!rows[0]) throw new Error('Recurring invoice not found');
  const ri = rows[0];
  if (ri.status !== 'active') throw new Error('Recurring invoice is not active');

  const nextDate = advanceDate(String(ri.next_run_date), String(ri.frequency));
  const endDate = ri.end_date ? String(ri.end_date) : null;
  const newStatus = endDate && nextDate > endDate ? 'completed' : 'active';

  const invoiceId = await withTransaction(async (tx) => {
    const inv = (await tx`
      INSERT INTO customer_invoices (
        client_id, project_id, invoice_date, due_date, subtotal,
        tax_amount, total_amount, status, description, created_by
      ) VALUES (
        ${ri.client_id}::UUID, ${ri.project_id || null},
        CURRENT_DATE, CURRENT_DATE + INTERVAL '30 days',
        ${Number(ri.subtotal)}, ${Number(ri.tax_amount)}, ${Number(ri.total_amount)},
        'approved', ${ri.description || ri.template_name}, ${userId}::UUID
      ) RETURNING id
    `) as Row[];

    await tx`
      UPDATE recurring_invoices
      SET last_run_date = CURRENT_DATE, next_run_date = ${nextDate}::DATE,
          run_count = run_count + 1, status = ${newStatus}
      WHERE id = ${id}
    `;

    return String(inv[0]!.id);
  });

  log.info('Generated invoice from recurring', { recurringId: id, invoiceId }, 'accounting');
  return invoiceId;
}

function advanceDate(dateStr: string, frequency: string): string {
  const d = new Date(dateStr);
  switch (frequency) {
    case 'weekly': d.setDate(d.getDate() + 7); break;
    case 'monthly': d.setMonth(d.getMonth() + 1); break;
    case 'quarterly': d.setMonth(d.getMonth() + 3); break;
    case 'annually': d.setFullYear(d.getFullYear() + 1); break;
  }
  return d.toISOString().split('T')[0]!;
}

function mapRow(row: Row): RecurringInvoice {
  return {
    id: String(row.id),
    templateName: String(row.template_name),
    clientId: String(row.client_id),
    projectId: row.project_id ? String(row.project_id) : undefined,
    frequency: String(row.frequency) as RecurringInvoice['frequency'],
    nextRunDate: String(row.next_run_date),
    endDate: row.end_date ? String(row.end_date) : undefined,
    lastRunDate: row.last_run_date ? String(row.last_run_date) : undefined,
    runCount: Number(row.run_count),
    status: String(row.status) as RecurringInvoice['status'],
    description: row.description ? String(row.description) : undefined,
    lineItems: Array.isArray(row.line_items) ? row.line_items as RecurringInvoice['lineItems'] : JSON.parse(typeof row.line_items === 'string' ? row.line_items : '[]'),
    subtotal: Number(row.subtotal),
    taxRate: Number(row.tax_rate),
    taxAmount: Number(row.tax_amount),
    totalAmount: Number(row.total_amount),
    paymentTerms: row.payment_terms ? String(row.payment_terms) : undefined,
    createdBy: String(row.created_by),
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
    clientName: row.client_name ? String(row.client_name) : undefined,
  };
}

/**
 * Fuzzy Match Utility
 * Matches extracted vendor/customer names against existing database records
 * using Dice coefficient on bigrams for SA business name matching.
 */

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

interface MatchCandidate {
  id: string | number;
  name: string;
}

interface MatchResult {
  id: string | number;
  name: string;
  score: number;
}

const DEFAULT_THRESHOLD = 0.6;

/**
 * Find the best matching supplier from a list.
 */
export function fuzzyMatchSupplier(
  extractedName: string,
  suppliers: Array<{ id: string | number; name: string }>,
  threshold = DEFAULT_THRESHOLD,
): MatchResult | null {
  return findBestMatch(extractedName, suppliers, threshold);
}

/**
 * Find the best matching client from a list.
 * Handles `companyName` field mapping.
 */
export function fuzzyMatchClient(
  extractedName: string,
  clients: Array<{ id: string | number; companyName?: string; name?: string; company_name?: string }>,
  threshold = DEFAULT_THRESHOLD,
): MatchResult | null {
  const candidates: MatchCandidate[] = clients.map(c => ({
    id: c.id,
    name: c.companyName || c.company_name || c.name || '',
  }));
  return findBestMatch(extractedName, candidates, threshold);
}

// ---------------------------------------------------------------------------
// Core matching
// ---------------------------------------------------------------------------

function findBestMatch(
  query: string,
  candidates: MatchCandidate[],
  threshold: number,
): MatchResult | null {
  if (!query || candidates.length === 0) return null;

  const normalizedQuery = normalize(query);
  if (!normalizedQuery) return null;

  let best: MatchResult | null = null;

  for (const candidate of candidates) {
    const normalizedCandidate = normalize(candidate.name);
    if (!normalizedCandidate) continue;

    // Exact match after normalization
    if (normalizedQuery === normalizedCandidate) {
      return { id: candidate.id, name: candidate.name, score: 1.0 };
    }

    // Containment check (one contains the other)
    if (normalizedQuery.includes(normalizedCandidate) || normalizedCandidate.includes(normalizedQuery)) {
      const score = Math.min(normalizedQuery.length, normalizedCandidate.length) /
        Math.max(normalizedQuery.length, normalizedCandidate.length);
      const adjustedScore = 0.7 + score * 0.3; // Range: 0.7 - 1.0
      if (adjustedScore >= threshold && (!best || adjustedScore > best.score)) {
        best = { id: candidate.id, name: candidate.name, score: Math.round(adjustedScore * 100) / 100 };
      }
      continue;
    }

    // Dice coefficient on bigrams
    const score = diceCoefficient(normalizedQuery, normalizedCandidate);
    if (score >= threshold && (!best || score > best.score)) {
      best = { id: candidate.id, name: candidate.name, score: Math.round(score * 100) / 100 };
    }
  }

  return best;
}

// ---------------------------------------------------------------------------
// Normalization — strips SA business suffixes and noise
// ---------------------------------------------------------------------------

const STRIP_PATTERNS = [
  /\b\(pty\)\b/gi,
  /\bpty\b/gi,
  /\bltd\b/gi,
  /\blimited\b/gi,
  /\binc\b/gi,
  /\bincorporated\b/gi,
  /\bcc\b/gi,
  /\bnpc\b/gi,
  /\bsoc\b/gi,
  /\bt\/a\b/gi,
  /\btrading\s+as\b/gi,
];

function normalize(name: string): string {
  let s = name.toLowerCase().trim();
  for (const pattern of STRIP_PATTERNS) {
    s = s.replace(pattern, '');
  }
  // Remove punctuation and collapse whitespace
  s = s.replace(/[^a-z0-9\s]/g, '').replace(/\s+/g, ' ').trim();
  return s;
}

// ---------------------------------------------------------------------------
// Dice coefficient on bigrams
// ---------------------------------------------------------------------------

function bigrams(str: string): Set<string> {
  const result = new Set<string>();
  for (let i = 0; i < str.length - 1; i++) {
    result.add(str.substring(i, i + 2));
  }
  return result;
}

function diceCoefficient(a: string, b: string): number {
  if (a === b) return 1;
  if (a.length < 2 || b.length < 2) return 0;

  const bigramsA = bigrams(a);
  const bigramsB = bigrams(b);

  let intersectionSize = 0;
  for (const bg of bigramsA) {
    if (bigramsB.has(bg)) intersectionSize++;
  }

  return (2 * intersectionSize) / (bigramsA.size + bigramsB.size);
}

