import { sql, withTransaction } from '@/lib/neon';
import { log } from '@/lib/logger';
import { createJournalEntry, postJournalEntry } from './journalEntryService';
import type { RecurringJournal, RecurringJournalCreateInput, JournalLineInput } from '../types/gl.types';
type Row = Record<string, unknown>;


export async function getRecurringJournals(companyId: string, filters?: {
  status?: string;
  limit?: number;
  offset?: number;
}): Promise<{ items: RecurringJournal[]; total: number }> {
  const limit = filters?.limit || 50;
  const offset = filters?.offset || 0;
  let rows: Row[];
  let countRows: Row[];

  if (filters?.status) {
    rows = (await sql`
      SELECT * FROM recurring_journals WHERE company_id = ${companyId} AND status = ${filters.status}
      ORDER BY created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`
      SELECT COUNT(*) AS cnt FROM recurring_journals WHERE company_id = ${companyId} AND status = ${filters.status}
    `) as Row[];
  } else {
    rows = (await sql`
      SELECT * FROM recurring_journals WHERE company_id = ${companyId}
      ORDER BY created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`SELECT COUNT(*) AS cnt FROM recurring_journals WHERE company_id = ${companyId}`) as Row[];
  }

  return { items: rows.map(mapRow), total: Number(countRows[0]?.cnt || 0) };
}

export async function createRecurringJournal(companyId: string, 
  input: RecurringJournalCreateInput,
  userId: string
): Promise<RecurringJournal> {
  // Validate lines balance
  const totalDebit = input.lines.reduce((s, l) => s + l.debit, 0);
  const totalCredit = input.lines.reduce((s, l) => s + l.credit, 0);
  if (Math.abs(totalDebit - totalCredit) > 0.01) {
    throw new Error(`Journal lines do not balance: DR ${totalDebit.toFixed(2)} vs CR ${totalCredit.toFixed(2)}`);
  }

  const rows = (await sql`
    INSERT INTO recurring_journals (
      company_id, template_name, description, frequency, next_run_date,
      end_date, lines, total_amount, created_by
    ) VALUES (
      ${companyId}, ${input.templateName}, ${input.description || null}, ${input.frequency},
      ${input.nextRunDate}, ${input.endDate || null},
      ${JSON.stringify(input.lines)}::JSONB, ${totalDebit}, ${userId}::UUID
    ) RETURNING *
  `) as Row[];

  log.info('Created recurring journal', { id: rows[0]?.id }, 'accounting');
  return mapRow(rows[0]!);
}

export async function updateRecurringJournalStatus(companyId: string, 
  id: string,
  status: 'paused' | 'active' | 'cancelled'
): Promise<void> {
  await sql`UPDATE recurring_journals SET status = ${status} WHERE id = ${id} AND company_id = ${companyId}`;
  log.info('Updated recurring journal status', { id, status }, 'accounting');
}

export async function generateJournalFromRecurring(companyId: string, 
  id: string,
  userId: string
): Promise<string> {
  const rows = (await sql`SELECT * FROM recurring_journals WHERE id = ${id} AND company_id = ${companyId}`) as Row[];
  if (!rows[0]) throw new Error('Recurring journal not found');
  const rj = rows[0];
  if (rj.status !== 'active') throw new Error('Recurring journal is not active');

  const lines: JournalLineInput[] = Array.isArray(rj.lines) ? rj.lines as JournalLineInput[] : JSON.parse(typeof rj.lines === 'string' ? rj.lines : '[]');

  const je = await createJournalEntry('', {
    entryDate: new Date().toISOString().split('T')[0]!,
    description: rj.description ? String(rj.description) : String(rj.template_name),
    source: 'auto_recurring',
    lines,
  }, userId);
  await postJournalEntry(companyId, je.id, userId);

  // Advance next run date and mark last run atomically so a failure here
  // doesn't leave an orphaned GL entry with the recurring template unadvanced.
  const nextDate = advanceDate(String(rj.next_run_date), String(rj.frequency));
  const endDate = rj.end_date ? String(rj.end_date) : null;
  const newStatus = endDate && nextDate > endDate ? 'completed' : 'active';

  await withTransaction(async (tx) => {
    await tx`
      UPDATE recurring_journals
      SET last_run_date = CURRENT_DATE, next_run_date = ${nextDate}::DATE,
          run_count = run_count + 1, status = ${newStatus}
      WHERE id = ${id}
    `;
  });

  log.info('Generated journal from recurring', { recurringId: id, journalId: je.id }, 'accounting');
  return je.id;
}

function advanceDate(dateStr: string, frequency: string): string {
  const d = new Date(dateStr);
  switch (frequency) {
    case 'weekly': d.setDate(d.getDate() + 7); break;
    case 'monthly': d.setMonth(d.getMonth() + 1); break;
    case 'quarterly': d.setMonth(d.getMonth() + 3); break;
    case 'annually': d.setFullYear(d.getFullYear() + 1); break;
  }
  return d.toISOString().split('T')[0]!;
}

function mapRow(row: Row): RecurringJournal {
  return {
    id: String(row.id),
    templateName: String(row.template_name),
    description: row.description ? String(row.description) : undefined,
    frequency: String(row.frequency) as RecurringJournal['frequency'],
    nextRunDate: String(row.next_run_date),
    endDate: row.end_date ? String(row.end_date) : undefined,
    lastRunDate: row.last_run_date ? String(row.last_run_date) : undefined,
    runCount: Number(row.run_count),
    status: String(row.status) as RecurringJournal['status'],
    lines: Array.isArray(row.lines) ? row.lines as JournalLineInput[] : JSON.parse(typeof row.lines === 'string' ? row.lines : '[]'),
    totalAmount: Number(row.total_amount),
    createdBy: String(row.created_by),
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
  };
}

/**
 * PRD-060: FibreFlow Accounting Module
 * Payment Allocation Validation
 *
 * Validates that payment allocations across invoices are correct:
 * - No overpayment per invoice
 * - Total allocations don't exceed payment amount
 * - No duplicate invoice allocations
 * - All referenced invoices exist
 */

import type {
  PaymentAllocationInput,
  PaymentAllocationResult,
  InvoiceForAllocation,
} from '../types/ap.types';

/**
 * Validate payment allocations against invoices.
 */
export function validatePaymentAllocations(
  paymentAmount: number,
  allocations: PaymentAllocationInput[],
  invoices: InvoiceForAllocation[]
): PaymentAllocationResult {
  const errors: string[] = [];
  const invoiceMap = new Map(invoices.map(inv => [inv.id, inv]));
  const resultAllocations: PaymentAllocationResult['allocations'] = [];

  // Check for duplicate invoice IDs
  const invoiceIds = allocations.map(a => a.invoiceId);
  const duplicates = invoiceIds.filter((id, i) => invoiceIds.indexOf(id) !== i);
  if (duplicates.length > 0) {
    errors.push(`Duplicate invoice allocations: ${duplicates.join(', ')}`);
    return {
      valid: false,
      allocations: [],
      totalAllocated: 0,
      unallocated: paymentAmount,
      errors,
    };
  }

  let totalAllocated = 0;

  for (const alloc of allocations) {
    // Validate amount is positive
    if (alloc.amount <= 0) {
      errors.push(`Allocation amount must be positive (invoice: ${alloc.invoiceId}, amount: ${alloc.amount})`);
      continue;
    }

    // Validate invoice exists
    const invoice = invoiceMap.get(alloc.invoiceId);
    if (!invoice) {
      errors.push(`Invoice not found: ${alloc.invoiceId}`);
      continue;
    }

    // Validate doesn't exceed invoice balance
    if (alloc.amount > invoice.balance) {
      errors.push(
        `Allocation R${alloc.amount.toFixed(2)} exceeds invoice ${invoice.invoiceNumber} balance of R${invoice.balance.toFixed(2)}`
      );
      continue;
    }

    const newBalance = Math.round((invoice.balance - alloc.amount) * 100) / 100;

    resultAllocations.push({
      invoiceId: alloc.invoiceId,
      amount: alloc.amount,
      newBalance,
      fullyPaid: newBalance === 0,
    });

    totalAllocated += alloc.amount;
  }

  // Check total allocations don't exceed payment amount
  totalAllocated = Math.round(totalAllocated * 100) / 100;
  if (totalAllocated > paymentAmount) {
    errors.push(
      `Total allocations R${totalAllocated.toFixed(2)} exceed payment amount R${paymentAmount.toFixed(2)}`
    );
  }

  const unallocated = Math.round((paymentAmount - totalAllocated) * 100) / 100;

  return {
    valid: errors.length === 0,
    allocations: resultAllocations,
    totalAllocated,
    unallocated: Math.max(0, unallocated),
    errors,
  };
}

/**
 * Fuzzy Matcher Utility
 * PRD: Customer Migration Wizard — Phase 1
 *
 * Generic fuzzy matching for migration contact name resolution.
 * Complements fuzzyMatch.ts (which is supplier/client specific) with a
 * simpler needle-in-haystack API used by migration services.
 *
 * Uses Levenshtein edit distance normalized to [0, 1] similarity score,
 * with a Dice bigram coefficient fallback for longer strings (>6 chars).
 */

export interface FuzzyMatchResult {
  match: string;
  score: number;  // 0.0 – 1.0, higher is better
}

const DEFAULT_THRESHOLD = 0.7;

/**
 * Find the best fuzzy match for needle in a haystack of strings.
 *
 * @param needle    String to search for
 * @param haystack  Candidate strings
 * @param threshold Minimum score to accept (default 0.7)
 * @returns Best match with score, or null if nothing meets the threshold
 */
export function fuzzyMatch(
  needle: string,
  haystack: string[],
  threshold = DEFAULT_THRESHOLD,
): FuzzyMatchResult | null {
  if (!needle || haystack.length === 0) return null;

  const normalizedNeedle = normalize(needle);
  if (!normalizedNeedle) return null;

  let best: FuzzyMatchResult | null = null;

  for (const candidate of haystack) {
    const normalizedCandidate = normalize(candidate);
    if (!normalizedCandidate) continue;

    // Exact match shortcut
    if (normalizedNeedle === normalizedCandidate) {
      return { match: candidate, score: 1.0 };
    }

    const score = scoreStrings(normalizedNeedle, normalizedCandidate);
    if (score >= threshold && (!best || score > best.score)) {
      best = { match: candidate, score: Math.round(score * 1000) / 1000 };
    }
  }

  return best;
}

/**
 * Score all haystack items against needle, returning sorted results.
 * Useful for showing ranked match suggestions in the UI.
 */
export function fuzzyRank(
  needle: string,
  haystack: string[],
  threshold = 0.5,
): FuzzyMatchResult[] {
  if (!needle || haystack.length === 0) return [];

  const normalizedNeedle = normalize(needle);
  if (!normalizedNeedle) return [];

  const results: FuzzyMatchResult[] = [];

  for (const candidate of haystack) {
    const normalizedCandidate = normalize(candidate);
    if (!normalizedCandidate) continue;
    const score = normalizedNeedle === normalizedCandidate ? 1.0 : scoreStrings(normalizedNeedle, normalizedCandidate);
    if (score >= threshold) {
      results.push({ match: candidate, score: Math.round(score * 1000) / 1000 });
    }
  }

  return results.sort((a, b) => b.score - a.score);
}

// ── Scoring ──────────────────────────────────────────────────────────────────

function scoreStrings(a: string, b: string): number {
  // For short strings (<= 6 chars), Levenshtein is more accurate
  if (a.length <= 6 || b.length <= 6) {
    return levenshteinSimilarity(a, b);
  }
  // For longer strings, average Dice + Levenshtein
  const dice = diceCoefficient(a, b);
  const lev  = levenshteinSimilarity(a, b);
  return (dice + lev) / 2;
}

function levenshteinSimilarity(a: string, b: string): number {
  const dist = levenshtein(a, b);
  const maxLen = Math.max(a.length, b.length);
  if (maxLen === 0) return 1.0;
  return 1 - dist / maxLen;
}

function levenshtein(a: string, b: string): number {
  const m = a.length;
  const n = b.length;
  const dp: number[][] = Array.from({ length: m + 1 }, (_, i) =>
    Array.from({ length: n + 1 }, (__, j) => (i === 0 ? j : j === 0 ? i : 0))
  );
  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      if (a[i - 1] === b[j - 1]) {
        dp[i]![j] = dp[i - 1]![j - 1]!;
      } else {
        dp[i]![j] = 1 + Math.min(dp[i - 1]![j]!, dp[i]![j - 1]!, dp[i - 1]![j - 1]!);
      }
    }
  }
  return dp[m]![n]!;
}

function diceCoefficient(a: string, b: string): number {
  if (a === b) return 1;
  if (a.length < 2 || b.length < 2) return 0;
  const bigramsA = new Set<string>();
  const bigramsB = new Set<string>();
  for (let i = 0; i < a.length - 1; i++) bigramsA.add(a.substring(i, i + 2));
  for (let i = 0; i < b.length - 1; i++) bigramsB.add(b.substring(i, i + 2));
  let intersection = 0;
  for (const bg of bigramsA) { if (bigramsB.has(bg)) intersection++; }
  return (2 * intersection) / (bigramsA.size + bigramsB.size);
}

// ── Normalization ─────────────────────────────────────────────────────────────

const STRIP_PATTERNS = [
  /\b\(pty\)\b/gi,
  /\bpty\b/gi,
  /\bltd\b/gi,
  /\blimited\b/gi,
  /\binc\b/gi,
  /\bcc\b/gi,
  /\bnpc\b/gi,
  /\bt\/a\b/gi,
];

function normalize(name: string): string {
  let s = name.toLowerCase().trim();
  for (const pattern of STRIP_PATTERNS) {
    s = s.replace(pattern, '');
  }
  return s.replace(/[^a-z0-9\s]/g, '').replace(/\s+/g, ' ').trim();
}

/**
 * PRD-060: FibreFlow Accounting Module
 * Bank CSV Statement Parsers
 *
 * Parsers for South African bank statement CSV formats:
 * - FNB (First National Bank)
 * - Standard Bank
 * - Nedbank
 * - ABSA
 * - Capitec
 */

import type { ParsedBankTransaction, BankCsvParseResult, BankFormat } from '../types/bank.types';

/**
 * Parse a CSV string into lines, handling quoted fields.
 */
function parseCsvLines(csv: string): string[][] {
  if (!csv || csv.trim() === '') return [];

  const lines = csv.trim().split('\n');
  return lines.map(line => {
    const fields: string[] = [];
    let current = '';
    let inQuotes = false;

    for (let i = 0; i < line.length; i++) {
      const char = line[i];
      if (char === '"') {
        inQuotes = !inQuotes;
      } else if (char === ',' && !inQuotes) {
        fields.push(current.trim());
        current = '';
      } else {
        current += char;
      }
    }
    fields.push(current.trim());
    return fields;
  });
}

/**
 * Parse amount string, handling thousand separators and negative values.
 */
function parseAmount(value: string): number | null {
  if (!value || value.trim() === '') return null;
  const cleaned = value.replace(/[,\s]/g, '').replace(/^["']|["']$/g, '');
  const num = parseFloat(cleaned);
  return isNaN(num) ? null : num;
}

/**
 * Convert date string to YYYY-MM-DD format.
 */
function normalizeDate(dateStr: string, format: 'yyyy/mm/dd' | 'dd/mm/yyyy' | 'yyyy-mm-dd'): string | null {
  const cleaned = dateStr.trim().replace(/^["']|["']$/g, '').trim();
  if (!cleaned) return null;

  let year: string, month: string, day: string;

  if (format === 'yyyy/mm/dd') {
    const parts = cleaned.split('/');
    if (parts.length !== 3) return null;
    year = parts[0]!; month = parts[1]!; day = parts[2]!;
  } else if (format === 'dd/mm/yyyy') {
    const parts = cleaned.split('/');
    if (parts.length !== 3) return null;
    day = parts[0]!; month = parts[1]!; year = parts[2]!;
  } else if (format === 'yyyy-mm-dd') {
    const parts = cleaned.split('-');
    if (parts.length !== 3) return null;
    year = parts[0]!; month = parts[1]!; day = parts[2]!;
  } else {
    return null;
  }

  // Validate
  const y = parseInt(year, 10);
  const m = parseInt(month, 10);
  const d = parseInt(day, 10);
  if (isNaN(y) || isNaN(m) || isNaN(d)) return null;
  if (m < 1 || m > 12 || d < 1 || d > 31) return null;

  return `${year.padStart(4, '0')}-${month.padStart(2, '0')}-${day.padStart(2, '0')}`;
}

// ── FNB Parser ───────────────────────────────────────────────────────────────

/**
 * Parse FNB bank statement CSV.
 * Expected columns: Date, Description, Amount, Balance, Reference
 * Date format: YYYY/MM/DD
 * Amount: single column (positive = credit, negative = debit)
 */
export function parseFNBStatement(csv: string): BankCsvParseResult {
  const result: BankCsvParseResult = {
    transactions: [],
    errors: [],
    bankFormat: 'fnb',
  };

  const lines = parseCsvLines(csv);
  if (lines.length <= 1) return result; // Empty or header only

  // Skip header (row 0)
  for (let i = 1; i < lines.length; i++) {
    const fields = lines[i]!;
    if (fields.length < 3) {
      result.errors.push({ row: i + 1, error: 'Insufficient columns' });
      continue;
    }

    const date = normalizeDate(fields[0]!, 'yyyy/mm/dd');
    if (!date) {
      result.errors.push({ row: i + 1, error: `Invalid date: ${fields[0]}` });
      continue;
    }

    const amount = parseAmount(fields[2]!);
    if (amount === null) {
      result.errors.push({ row: i + 1, error: `Invalid amount: ${fields[2]}` });
      continue;
    }

    const tx: ParsedBankTransaction = {
      transactionDate: date,
      amount,
      description: fields[1]!.trim(),
      reference: fields.length > 4 ? fields[4]!.trim() || undefined : undefined,
      balance: fields.length > 3 ? parseAmount(fields[3]!) ?? undefined : undefined,
    };

    result.transactions.push(tx);
  }

  return result;
}

// ── Standard Bank Parser ─────────────────────────────────────────────────────

/**
 * Parse Standard Bank statement CSV.
 * Expected columns: Date, Description, Debit, Credit, Balance
 * Date format: DD/MM/YYYY
 * Separate debit/credit columns
 */
export function parseStandardBankStatement(csv: string): BankCsvParseResult {
  const result: BankCsvParseResult = {
    transactions: [],
    errors: [],
    bankFormat: 'standard_bank',
  };

  const lines = parseCsvLines(csv);
  if (lines.length <= 1) return result;

  for (let i = 1; i < lines.length; i++) {
    const fields = lines[i]!;
    if (fields.length < 4) {
      result.errors.push({ row: i + 1, error: 'Insufficient columns' });
      continue;
    }

    const date = normalizeDate(fields[0]!, 'dd/mm/yyyy');
    if (!date) {
      result.errors.push({ row: i + 1, error: `Invalid date: ${fields[0]}` });
      continue;
    }

    const debit = parseAmount(fields[2]!);
    const credit = parseAmount(fields[3]!);

    let amount: number;
    if (credit !== null && credit > 0) {
      amount = credit;
    } else if (debit !== null && debit > 0) {
      amount = -debit;
    } else if (credit === null && debit === null) {
      result.errors.push({ row: i + 1, error: 'No debit or credit amount' });
      continue;
    } else {
      amount = 0;
    }

    const tx: ParsedBankTransaction = {
      transactionDate: date,
      amount,
      description: fields[1]!.trim(),
      balance: fields.length > 4 ? parseAmount(fields[4]!) ?? undefined : undefined,
    };

    result.transactions.push(tx);
  }

  return result;
}

// ── Nedbank Parser ───────────────────────────────────────────────────────────

/**
 * Parse Nedbank statement CSV.
 * Expected columns: Transaction Date, Value Date, Transaction Description, Debit Amount, Credit Amount, Balance
 * Date format: YYYY-MM-DD
 */
export function parseNedbankStatement(csv: string): BankCsvParseResult {
  const result: BankCsvParseResult = {
    transactions: [],
    errors: [],
    bankFormat: 'nedbank',
  };

  const lines = parseCsvLines(csv);
  if (lines.length <= 1) return result;

  for (let i = 1; i < lines.length; i++) {
    const fields = lines[i]!;
    if (fields.length < 5) {
      result.errors.push({ row: i + 1, error: 'Insufficient columns' });
      continue;
    }

    const date = normalizeDate(fields[0]!, 'yyyy-mm-dd');
    if (!date) {
      result.errors.push({ row: i + 1, error: `Invalid date: ${fields[0]}` });
      continue;
    }

    const valueDate = normalizeDate(fields[1]!, 'yyyy-mm-dd');
    const debit = parseAmount(fields[3]!);
    const credit = parseAmount(fields[4]!);

    let amount: number;
    if (credit !== null && credit > 0) {
      amount = credit;
    } else if (debit !== null && debit > 0) {
      amount = -debit;
    } else {
      amount = 0;
    }

    const tx: ParsedBankTransaction = {
      transactionDate: date,
      valueDate: valueDate || undefined,
      amount,
      description: fields[2]!.trim(),
      balance: fields.length > 5 ? parseAmount(fields[5]!) ?? undefined : undefined,
    };

    result.transactions.push(tx);
  }

  return result;
}

// ── ABSA Parser ──────────────────────────────────────────────────────────────

/**
 * Parse ABSA bank statement CSV.
 * Expected columns: Account Number,Date,Description1,Description2,Amount,Balance
 * Date format: YYYY/MM/DD
 * Amount: single column with quoted strings, negative values in parentheses or with minus sign
 *
 * Example row:
 *   4087xxxxxx,2026/01/15,"POS Purchase","Woolworths Food","-1234.56","45678.90"
 */
export function parseABSAStatement(csv: string): BankCsvParseResult {
  const result: BankCsvParseResult = {
    transactions: [],
    errors: [],
    bankFormat: 'absa',
  };

  const lines = parseCsvLines(csv);
  if (lines.length <= 1) return result;

  // Skip header (row 0)
  for (let i = 1; i < lines.length; i++) {
    const fields = lines[i]!;
    // Minimum: AccountNumber, Date, Description1, Description2, Amount
    if (fields.length < 5) {
      if (fields.every(f => f === '')) continue; // skip blank lines
      result.errors.push({ row: i + 1, error: 'Insufficient columns' });
      continue;
    }

    // Column 1 = Date (YYYY/MM/DD)
    const date = normalizeDate(fields[1]!, 'yyyy/mm/dd');
    if (!date) {
      result.errors.push({ row: i + 1, error: `Invalid date: ${fields[1]}` });
      continue;
    }

    // Column 4 = Amount (column index 4)
    const amount = parseAmount(fields[4]!);
    if (amount === null) {
      result.errors.push({ row: i + 1, error: `Invalid amount: ${fields[4]}` });
      continue;
    }

    // Combine Description1 + Description2 for a richer description
    const desc1 = fields[2]!.trim();
    const desc2 = fields[3]!.trim();
    const description = desc2 ? `${desc1} ${desc2}`.trim() : desc1;

    const tx: ParsedBankTransaction = {
      transactionDate: date,
      amount,
      description,
      balance: fields.length > 5 ? parseAmount(fields[5]!) ?? undefined : undefined,
    };

    result.transactions.push(tx);
  }

  return result;
}

// ── Capitec Parser ────────────────────────────────────────────────────────────

/**
 * Parse Capitec bank statement CSV.
 * Expected columns: Date,Description,Debit,Credit,Balance
 * Date format: DD/MM/YYYY
 * Separate debit/credit columns (similar to Standard Bank but different header casing)
 */
export function parseCapitecStatement(csv: string): BankCsvParseResult {
  const result: BankCsvParseResult = {
    transactions: [],
    errors: [],
    bankFormat: 'capitec',
  };

  const lines = parseCsvLines(csv);
  if (lines.length <= 1) return result;

  for (let i = 1; i < lines.length; i++) {
    const fields = lines[i]!;
    // Skip blank lines
    if (fields.every(f => f === '')) continue;
    if (fields.length < 4) {
      result.errors.push({ row: i + 1, error: 'Insufficient columns' });
      continue;
    }

    const date = normalizeDate(fields[0]!, 'dd/mm/yyyy');
    if (!date) {
      result.errors.push({ row: i + 1, error: `Invalid date: ${fields[0]}` });
      continue;
    }

    const debit = parseAmount(fields[2]!);
    const credit = parseAmount(fields[3]!);

    let amount: number;
    if (credit !== null && credit > 0) {
      amount = credit;
    } else if (debit !== null && debit > 0) {
      amount = -debit;
    } else if (credit === null && debit === null) {
      result.errors.push({ row: i + 1, error: 'No debit or credit amount' });
      continue;
    } else {
      amount = 0;
    }

    const tx: ParsedBankTransaction = {
      transactionDate: date,
      amount,
      description: fields[1]!.trim(),
      balance: fields.length > 4 ? parseAmount(fields[4]!) ?? undefined : undefined,
    };

    result.transactions.push(tx);
  }

  return result;
}

// ── Format Detection ─────────────────────────────────────────────────────────

/**
 * Detect bank format from CSV header line.
 * Returns 'ofx' or 'qif' when the content matches those non-CSV formats.
 */
export function detectBankFormat(csv: string): BankFormat {
  if (!csv || csv.trim() === '') return 'unknown';

  const trimmed = csv.trim();

  // OFX: starts with OFXHEADER: or <OFX>
  if (trimmed.startsWith('OFXHEADER:') || trimmed.startsWith('<OFX>') || trimmed.startsWith('<ofx>')) {
    return 'ofx';
  }

  // QIF: first non-blank line starts with !Type: or !Account
  const firstNonBlank = trimmed.split('\n').find(l => l.trim().length > 0) ?? '';
  if (firstNonBlank.startsWith('!Type:') || firstNonBlank.startsWith('!Account') || firstNonBlank.startsWith('!type:')) {
    return 'qif';
  }

  const firstLine = trimmed.split('\n')[0]!.toLowerCase();

  // ABSA: "Account Number,Date,Description1,Description2,Amount,Balance"
  if (firstLine.includes('account number') && firstLine.includes('description1')) {
    return 'absa';
  }

  // FNB: "Date","Description","Amount","Balance","Reference"
  if (firstLine.includes('"date"') && firstLine.includes('"amount"') && firstLine.includes('"reference"')) {
    return 'fnb';
  }

  // Nedbank: Transaction Date,Value Date,Transaction Description,...
  if (firstLine.includes('transaction date') && firstLine.includes('value date')) {
    return 'nedbank';
  }

  // Capitec: Date,Description,Debit,Credit,Balance (no extra qualifier columns)
  // Must be checked before Standard Bank since header is similar but Capitec has no extra columns.
  if (
    firstLine.includes('date') &&
    firstLine.includes('description') &&
    firstLine.includes('debit') &&
    firstLine.includes('credit') &&
    firstLine.includes('balance') &&
    !firstLine.includes('transaction date') &&
    !firstLine.includes('value date')
  ) {
    // Disambiguate: Standard Bank may include "Batch No" or similar extra fields.
    // Capitec typically has exactly 5 columns; Standard Bank also 5 — default to capitec
    // when header exactly matches Date,Description,Debit,Credit,Balance.
    const cols = firstLine.split(',').map(s => s.trim().replace(/"/g, ''));
    if (cols.length === 5 && cols[0] === 'date' && cols[1] === 'description') {
      return 'capitec';
    }
    return 'standard_bank';
  }

  // Standard Bank: Date,Description,Debit,Credit,Balance (fallback for variations)
  if (firstLine.includes('date') && firstLine.includes('debit') && firstLine.includes('credit')) {
    return 'standard_bank';
  }

  return 'unknown';
}

/**
 * VAT Return Report Service
 * Generates GL-based VAT201 return with box breakdown and drill-down from journal lines.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { VATReturnReport } from '../types/gl.types';

type Row = Record<string, unknown>;

interface VAT201BoxDef {
  box: string;
  label: string;
  accountType: 'liability' | 'asset';
  vatTypes: string[];
}

const OUTPUT_BOXES: VAT201BoxDef[] = [
  { box: '1',   label: 'Standard rated supplies',           accountType: 'liability', vatTypes: ['standard'] },
  { box: '1A',  label: 'Capital goods/services supplied',   accountType: 'liability', vatTypes: ['capital_goods'] },
  { box: '2',   label: 'Zero-rated supplies (domestic)',    accountType: 'liability', vatTypes: ['zero_rated'] },
  { box: '2A',  label: 'Zero-rated exports',                accountType: 'liability', vatTypes: ['export'] },
  { box: '3',   label: 'Exempt supplies',                   accountType: 'liability', vatTypes: ['exempt'] },
  { box: '12',  label: 'Imported services / other output',  accountType: 'liability', vatTypes: ['reverse_charge', 'imported'] },
];

const INPUT_BOXES: VAT201BoxDef[] = [
  { box: '14',      label: 'Capital goods/services purchased', accountType: 'asset', vatTypes: ['capital_goods'] },
  { box: '15',      label: 'Other goods/services purchased',   accountType: 'asset', vatTypes: ['standard'] },
  { box: '14A/15A', label: 'Goods imported',                   accountType: 'asset', vatTypes: ['imported'] },
  { box: '16',      label: 'Change in use',                    accountType: 'asset', vatTypes: ['reverse_charge'] },
  { box: '17',      label: 'Bad debts',                        accountType: 'asset', vatTypes: ['bad_debt'] },
  { box: '18',      label: 'Other adjustments',                accountType: 'asset', vatTypes: ['exempt', 'no_vat'] },
];

interface VATDrillDown {
  journalEntryId: string;
  entryNumber: string;
  entryDate: string;
  description: string;
  sourceDocument?: string;
  amount: number;
}

interface PopulatedBox {
  box: string;
  label: string;
  amount: number;
  transactions: VATDrillDown[];
}

export async function getVATReturn(companyId: string,
  periodStart: string,
  periodEnd: string
): Promise<VATReturnReport> {
  try {
    const vatLines = (await sql`
      SELECT
        jl.id              AS line_id,
        jl.gl_account_id,
        jl.debit,
        jl.credit,
        jl.vat_type,
        jl.description     AS line_description,
        je.id              AS journal_entry_id,
        je.entry_number,
        je.entry_date,
        je.description     AS entry_description,
        je.source_document_id,
        ga.account_code,
        ga.account_name,
        ga.account_type,
        ga.account_subtype
      FROM gl_journal_lines jl
      JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
      JOIN gl_accounts ga        ON ga.id  = jl.gl_account_id
      WHERE je.status = 'posted'
        AND je.company_id = ${companyId}::UUID
        AND je.entry_date >= ${periodStart}
        AND je.entry_date <= ${periodEnd}
        AND (
          ga.account_subtype IN ('vat_input', 'vat_output', 'tax')
        )
      ORDER BY je.entry_date, je.entry_number
    `) as Row[];

    const toDrillDown = (l: Row, signFn: (debit: number, credit: number) => number): VATDrillDown => ({
      journalEntryId: String(l.journal_entry_id),
      entryNumber:    String(l.entry_number),
      entryDate:      String(l.entry_date),
      description:    l.entry_description
        ? String(l.entry_description)
        : l.line_description ? String(l.line_description) : '',
      sourceDocument: l.source_document_id ? String(l.source_document_id) : undefined,
      amount: signFn(Number(l.debit), Number(l.credit)),
    });

    const outputBoxes: PopulatedBox[] = OUTPUT_BOXES.map((boxDef) => {
      const matching = vatLines.filter((l: Row) => {
        const isOutput = String(l.account_type) === 'liability' || String(l.account_subtype) === 'vat_output';
        const matchesType = l.vat_type != null && boxDef.vatTypes.includes(String(l.vat_type));
        return isOutput && matchesType;
      });
      const transactions = matching.map((l: Row) => toDrillDown(l, (d, c) => c - d));
      const amount = transactions.reduce((s, t) => s + t.amount, 0);
      return { box: boxDef.box, label: boxDef.label, amount, transactions };
    });

    const unclassifiedOutput = vatLines.filter((l: Row) => {
      const isOutput = String(l.account_type) === 'liability' || String(l.account_subtype) === 'vat_output';
      return isOutput && l.vat_type == null;
    });
    if (unclassifiedOutput.length > 0) {
      const box1 = outputBoxes.find((b) => b.box === '1');
      if (box1) {
        const extra = unclassifiedOutput.map((l: Row) => toDrillDown(l, (d, c) => c - d));
        box1.amount += extra.reduce((s, t) => s + t.amount, 0);
        box1.transactions.push(...extra);
      }
    }

    const inputBoxes: PopulatedBox[] = INPUT_BOXES.map((boxDef) => {
      const matching = vatLines.filter((l: Row) => {
        const isInput = String(l.account_type) === 'asset' || String(l.account_subtype) === 'vat_input';
        const matchesType = l.vat_type != null && boxDef.vatTypes.includes(String(l.vat_type));
        return isInput && matchesType;
      });
      const transactions = matching.map((l: Row) => toDrillDown(l, (d, c) => d - c));
      const amount = transactions.reduce((s, t) => s + t.amount, 0);
      return { box: boxDef.box, label: boxDef.label, amount, transactions };
    });

    const unclassifiedInput = vatLines.filter((l: Row) => {
      const isInput = String(l.account_type) === 'asset' || String(l.account_subtype) === 'vat_input';
      return isInput && l.vat_type == null;
    });
    if (unclassifiedInput.length > 0) {
      const box15 = inputBoxes.find((b) => b.box === '15');
      if (box15) {
        const extra = unclassifiedInput.map((l: Row) => toDrillDown(l, (d, c) => d - c));
        box15.amount += extra.reduce((s, t) => s + t.amount, 0);
        box15.transactions.push(...extra);
      }
    }

    const totalOutputTax = outputBoxes.reduce((s, b) => s + b.amount, 0);
    const totalInputTax  = inputBoxes.reduce((s, b) => s + b.amount, 0);
    const netVAT         = totalOutputTax - totalInputTax;

    const outputDetails = outputBoxes
      .filter((b) => Math.abs(b.amount) > 0.001)
      .map((b) => ({ accountCode: b.box, accountName: b.label, amount: b.amount }));
    const inputDetails = inputBoxes
      .filter((b) => Math.abs(b.amount) > 0.001)
      .map((b) => ({ accountCode: b.box, accountName: b.label, amount: b.amount }));

    return {
      periodStart, periodEnd,
      outputBoxes, totalOutputTax,
      inputBoxes, totalInputTax, netVAT,
      outputVAT: totalOutputTax,
      inputVAT:  totalInputTax,
      outputDetails, inputDetails,
    };
  } catch (err) {
    log.error('Failed to generate VAT return', { error: err }, 'accounting');
    throw err;
  }
}

