/**
 * Archive Execution Service
 * Executes the archive run — moves old records to archive tables and deletes originals.
 * SA Companies Act minimum retention: 5 years.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { logAudit } from './auditTrailService';

type Row = Record<string, unknown>;

const COMPONENT = 'data-archiving';

export interface ArchiveResult {
  runId: string;
  entriesArchived: number;
  linesArchived: number;
  transactionsArchived: number;
  invoicesArchived: number;
  supplierInvoicesArchived: number;
}

export async function executeArchive(
  companyId: string,
  cutoffDate: string,
  userId: string
): Promise<ArchiveResult> {
  const runRows = (await sql`
    INSERT INTO archive_runs (company_id, run_by, cutoff_date, status, started_at)
    VALUES (${companyId}, ${userId}, ${cutoffDate}::date, 'running', NOW())
    RETURNING id
  `) as Row[];
  const runId: string = runRows[0]!.id as string;

  log.info('Archive run started', { companyId, runId, cutoffDate, userId }, COMPONENT);

  try {
    // Step 1: Archive GL journal entries
    const jeRows = (await sql`
      INSERT INTO archive_gl_journal_entries
        (id, entry_number, entry_date, fiscal_period_id, description, source,
         source_document_id, status, posted_by, posted_at, reversed_by, reversed_at,
         reversal_of_id, created_by, created_at, updated_at, reference,
         project_id, cost_center_id, company_id)
      SELECT id, entry_number, entry_date, fiscal_period_id, description, source,
             source_document_id, status, posted_by, posted_at, reversed_by, reversed_at,
             reversal_of_id, created_by, created_at, updated_at, reference,
             project_id, cost_center_id, company_id
      FROM gl_journal_entries
      WHERE company_id = ${companyId}
        AND entry_date < ${cutoffDate}::date
        AND status = 'posted'
      ON CONFLICT (id) DO NOTHING
      RETURNING id
    `) as Row[];
    const entriesArchived = jeRows.length;

    // Step 2: Archive GL journal lines
    const jlRows = (await sql`
      INSERT INTO archive_gl_journal_lines
        (id, journal_entry_id, gl_account_id, debit, credit, description,
         project_id, cost_center_id, created_at)
      SELECT jl.id, jl.journal_entry_id, jl.gl_account_id, jl.debit, jl.credit,
             jl.description, jl.project_id, jl.cost_center_id, jl.created_at
      FROM gl_journal_lines jl
      JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
      WHERE je.company_id = ${companyId}
        AND je.entry_date < ${cutoffDate}::date
        AND je.status = 'posted'
      ON CONFLICT (id) DO NOTHING
      RETURNING id
    `) as Row[];
    const linesArchived = jlRows.length;

    // Step 3: Archive reconciled bank transactions
    const btRows = (await sql`
      INSERT INTO archive_bank_transactions
        (id, bank_account_id, transaction_date, value_date, amount, description,
         reference, bank_reference, status, matched_journal_line_id, reconciliation_id,
         import_batch_id, excluded_reason, notes, created_at, updated_at, company_id)
      SELECT id, bank_account_id, transaction_date, value_date, amount, description,
             reference, bank_reference, status, matched_journal_line_id, reconciliation_id,
             import_batch_id, excluded_reason, notes, created_at, updated_at, company_id
      FROM bank_transactions
      WHERE company_id = ${companyId}
        AND transaction_date < ${cutoffDate}::date
        AND status = 'reconciled'
      ON CONFLICT (id) DO NOTHING
      RETURNING id
    `) as Row[];
    const transactionsArchived = btRows.length;

    // Step 4: Archive paid/cancelled customer invoices
    const ciRows = (await sql`
      INSERT INTO archive_customer_invoices
        (id, invoice_number, customer_id, client_id, billing_period_start, billing_period_end,
         subtotal, tax_rate, tax_amount, total_amount, amount_paid, status,
         invoice_date, due_date, sent_at, paid_at, notes, internal_notes,
         project_id, gl_journal_entry_id, created_by, approved_by, approved_at,
         currency, created_at, updated_at, company_id)
      SELECT id, invoice_number, customer_id, client_id, billing_period_start, billing_period_end,
             subtotal, tax_rate, tax_amount, total_amount, amount_paid, status,
             invoice_date, due_date, sent_at, paid_at, notes, internal_notes,
             project_id, gl_journal_entry_id, created_by, approved_by, approved_at,
             currency, created_at, updated_at, company_id
      FROM customer_invoices
      WHERE company_id = ${companyId}
        AND invoice_date < ${cutoffDate}::date
        AND status IN ('paid', 'cancelled')
      ON CONFLICT (id) DO NOTHING
      RETURNING id
    `) as Row[];
    const invoicesArchived = ciRows.length;

    // Step 5: Archive paid/cancelled supplier invoices
    const siRows = (await sql`
      INSERT INTO archive_supplier_invoices
        (id, invoice_number, supplier_id, purchase_order_id, grn_id,
         invoice_date, due_date, received_date, subtotal, tax_rate, tax_amount,
         total_amount, amount_paid, payment_terms, currency, reference,
         status, match_status, project_id, cost_center_id, gl_journal_entry_id,
         sage_invoice_id, notes, created_by, approved_by, approved_at,
         created_at, updated_at, company_id)
      SELECT id, invoice_number, supplier_id, purchase_order_id, grn_id,
             invoice_date, due_date, received_date, subtotal, tax_rate, tax_amount,
             total_amount, amount_paid, payment_terms, currency, reference,
             status, match_status, project_id, cost_center_id, gl_journal_entry_id,
             sage_invoice_id, notes, created_by, approved_by, approved_at,
             created_at, updated_at, company_id
      FROM supplier_invoices
      WHERE company_id = ${companyId}
        AND invoice_date < ${cutoffDate}::date
        AND status IN ('paid', 'cancelled')
      ON CONFLICT (id) DO NOTHING
      RETURNING id
    `) as Row[];
    const supplierInvoicesArchived = siRows.length;

    // Step 6: Delete from active tables (reverse dependency order)
    await sql`
      DELETE FROM gl_journal_lines
      WHERE journal_entry_id IN (
        SELECT id FROM gl_journal_entries
        WHERE company_id = ${companyId}
          AND entry_date < ${cutoffDate}::date
          AND status = 'posted'
      )
    `;

    await sql`
      DELETE FROM gl_journal_entries
      WHERE company_id = ${companyId}
        AND entry_date < ${cutoffDate}::date
        AND status = 'posted'
    `;

    await sql`
      DELETE FROM bank_transactions
      WHERE company_id = ${companyId}
        AND transaction_date < ${cutoffDate}::date
        AND status = 'reconciled'
    `;

    await sql`
      DELETE FROM customer_invoices
      WHERE company_id = ${companyId}
        AND invoice_date < ${cutoffDate}::date
        AND status IN ('paid', 'cancelled')
    `;

    await sql`
      DELETE FROM supplier_invoices
      WHERE company_id = ${companyId}
        AND invoice_date < ${cutoffDate}::date
        AND status IN ('paid', 'cancelled')
    `;

    // Step 7: Update run record to completed
    await sql`
      UPDATE archive_runs
      SET status = 'completed',
          completed_at = NOW(),
          entries_archived = ${entriesArchived},
          lines_archived = ${linesArchived},
          transactions_archived = ${transactionsArchived},
          invoices_archived = ${invoicesArchived},
          supplier_invoices_archived = ${supplierInvoicesArchived}
      WHERE id = ${runId}
    `;

    logAudit({
      companyId,
      userId,
      action: 'export',
      entityType: 'archive_run',
      entityId: runId,
      entityRef: `Archive before ${cutoffDate}`,
      changes: {
        fields: [],
        metadata: {
          cutoffDate,
          entriesArchived: String(entriesArchived),
          linesArchived: String(linesArchived),
          transactionsArchived: String(transactionsArchived),
          invoicesArchived: String(invoicesArchived),
          supplierInvoicesArchived: String(supplierInvoicesArchived),
        },
      },
    }).catch(() => undefined);

    log.info('Archive run completed', {
      companyId, runId, entriesArchived, linesArchived,
      transactionsArchived, invoicesArchived, supplierInvoicesArchived,
    }, COMPONENT);

    return { runId, entriesArchived, linesArchived, transactionsArchived, invoicesArchived, supplierInvoicesArchived };
  } catch (err) {
    await sql`
      UPDATE archive_runs
      SET status = 'failed',
          completed_at = NOW(),
          error_message = ${String(err)}
      WHERE id = ${runId}
    `;
    log.error('Archive run failed', { companyId, runId, error: err }, COMPONENT);
    throw err;
  }
}

/**
 * Document Validation Service
 * Compares VLM-extracted data against entity records to detect discrepancies.
 */

import type {
  ExtractedDocument,
  ExtractedStatutoryDoc,
  ValidationDiscrepancy,
  DocumentValidationResult,
} from '@/modules/accounting/types/documentCapture.types';

// ---------------------------------------------------------------------------
// Invoice Validation
// ---------------------------------------------------------------------------

interface InvoiceRecord {
  invoiceNumber?: string;
  totalAmount?: number;
  vatAmount?: number;
  taxRate?: number;
  vendorName?: string;
  supplierName?: string;
  customerName?: string;
  clientName?: string;
  invoiceDate?: string;
}

export function validateInvoiceDocument(
  extracted: ExtractedDocument,
  invoice: InvoiceRecord,
): DocumentValidationResult {
  const discrepancies: ValidationDiscrepancy[] = [];

  // Total amount
  if (extracted.totalAmount !== null && invoice.totalAmount !== undefined) {
    const diff = Math.abs(extracted.totalAmount - invoice.totalAmount);
    if (diff > 0.02) {
      discrepancies.push({
        field: 'totalAmount',
        expected: invoice.totalAmount,
        actual: extracted.totalAmount,
        severity: diff > invoice.totalAmount * 0.05 ? 'error' : 'warning',
        message: `Total mismatch: document shows ${extracted.totalAmount}, record has ${invoice.totalAmount}`,
      });
    }
  }

  // VAT amount
  if (extracted.vatAmount !== null && invoice.vatAmount !== undefined) {
    const diff = Math.abs(extracted.vatAmount - invoice.vatAmount);
    if (diff > 1) {
      discrepancies.push({
        field: 'vatAmount',
        expected: invoice.vatAmount,
        actual: extracted.vatAmount,
        severity: 'warning',
        message: `VAT mismatch: document shows ${extracted.vatAmount}, record has ${invoice.vatAmount}`,
      });
    }
  }

  // VAT arithmetic check
  if (extracted.subtotal !== null && extracted.vatAmount !== null && extracted.totalAmount !== null) {
    const expected = Math.round((extracted.subtotal + extracted.vatAmount) * 100) / 100;
    if (Math.abs(expected - extracted.totalAmount) > 0.02) {
      discrepancies.push({
        field: 'vatArithmetic',
        expected: expected,
        actual: extracted.totalAmount,
        severity: 'error',
        message: `VAT arithmetic error on document: subtotal (${extracted.subtotal}) + VAT (${extracted.vatAmount}) = ${expected}, but total shows ${extracted.totalAmount}`,
      });
    }
  }

  // Reference number
  if (extracted.referenceNumber && invoice.invoiceNumber) {
    const normExtracted = extracted.referenceNumber.replace(/[-\s/]/g, '').toLowerCase();
    const normInvoice = invoice.invoiceNumber.replace(/[-\s/]/g, '').toLowerCase();
    if (normExtracted !== normInvoice) {
      discrepancies.push({
        field: 'referenceNumber',
        expected: invoice.invoiceNumber,
        actual: extracted.referenceNumber,
        severity: 'warning',
        message: `Reference mismatch: document shows "${extracted.referenceNumber}", record has "${invoice.invoiceNumber}"`,
      });
    }
  }

  // Vendor/customer name (fuzzy check)
  const entityName = invoice.vendorName || invoice.supplierName || invoice.customerName || invoice.clientName;
  const extractedName = extracted.vendorName || extracted.customerName;
  if (entityName && extractedName) {
    const normEntity = entityName.toLowerCase().replace(/\b(pty|ltd|cc|inc)\b/gi, '').trim();
    const normExtracted = extractedName.toLowerCase().replace(/\b(pty|ltd|cc|inc)\b/gi, '').trim();
    if (!normExtracted.includes(normEntity) && !normEntity.includes(normExtracted)) {
      discrepancies.push({
        field: 'entityName',
        expected: entityName,
        actual: extractedName,
        severity: 'warning',
        message: `Name mismatch: document shows "${extractedName}", record has "${entityName}"`,
      });
    }
  }

  // Date check
  if (extracted.date && invoice.invoiceDate) {
    if (extracted.date !== invoice.invoiceDate) {
      discrepancies.push({
        field: 'date',
        expected: invoice.invoiceDate,
        actual: extracted.date,
        severity: 'info',
        message: `Date differs: document shows ${extracted.date}, record has ${invoice.invoiceDate}`,
      });
    }
  }

  const errorCount = discrepancies.filter(d => d.severity === 'error').length;
  const warningCount = discrepancies.filter(d => d.severity === 'warning').length;
  const score = Math.max(0, 1 - (errorCount * 0.3 + warningCount * 0.1));

  return {
    valid: errorCount === 0,
    score: Math.round(score * 100) / 100,
    discrepancies,
    validatedAt: new Date().toISOString(),
  };
}

// ---------------------------------------------------------------------------
// Payment Receipt Validation
// ---------------------------------------------------------------------------

interface PaymentRecord {
  totalAmount?: number;
  paymentDate?: string;
  reference?: string;
  bankReference?: string;
}

export function validatePaymentReceipt(
  extracted: ExtractedDocument,
  payment: PaymentRecord,
): DocumentValidationResult {
  const discrepancies: ValidationDiscrepancy[] = [];

  if (extracted.totalAmount !== null && payment.totalAmount !== undefined) {
    const diff = Math.abs(extracted.totalAmount - payment.totalAmount);
    if (diff > 0.02) {
      discrepancies.push({
        field: 'totalAmount',
        expected: payment.totalAmount,
        actual: extracted.totalAmount,
        severity: diff > payment.totalAmount * 0.01 ? 'error' : 'warning',
        message: `Amount mismatch: receipt shows ${extracted.totalAmount}, payment record has ${payment.totalAmount}`,
      });
    }
  }

  if (extracted.date && payment.paymentDate) {
    const docDate = new Date(extracted.date);
    const payDate = new Date(payment.paymentDate);
    const daysDiff = Math.abs((docDate.getTime() - payDate.getTime()) / (1000 * 60 * 60 * 24));
    if (daysDiff > 7) {
      discrepancies.push({
        field: 'date',
        expected: payment.paymentDate,
        actual: extracted.date,
        severity: 'warning',
        message: `Date differs by ${Math.round(daysDiff)} days: receipt ${extracted.date}, payment ${payment.paymentDate}`,
      });
    }
  }

  const errorCount = discrepancies.filter(d => d.severity === 'error').length;
  const score = Math.max(0, 1 - (errorCount * 0.3 + (discrepancies.length - errorCount) * 0.1));

  return {
    valid: errorCount === 0,
    score: Math.round(score * 100) / 100,
    discrepancies,
    validatedAt: new Date().toISOString(),
  };
}

// ---------------------------------------------------------------------------
// Statutory Compliance Validation
// ---------------------------------------------------------------------------

interface CompanyRecord {
  companyName?: string;
  registrationNumber?: string;
  vatNumber?: string;
}

export function validateStatutoryCompliance(
  extracted: ExtractedStatutoryDoc,
  company: CompanyRecord,
): DocumentValidationResult {
  const discrepancies: ValidationDiscrepancy[] = [];

  if (extracted.entityName && company.companyName) {
    const normExtracted = extracted.entityName.toLowerCase().replace(/\b(pty|ltd|cc|inc)\b/gi, '').trim();
    const normCompany = company.companyName.toLowerCase().replace(/\b(pty|ltd|cc|inc)\b/gi, '').trim();
    if (!normExtracted.includes(normCompany) && !normCompany.includes(normExtracted)) {
      discrepancies.push({
        field: 'entityName',
        expected: company.companyName,
        actual: extracted.entityName,
        severity: 'error',
        message: `Entity name mismatch: certificate shows "${extracted.entityName}", company is "${company.companyName}"`,
      });
    }
  }

  if (extracted.expiryDate) {
    const expiry = new Date(extracted.expiryDate);
    const now = new Date();
    if (expiry < now) {
      discrepancies.push({
        field: 'expiryDate',
        expected: 'valid (not expired)',
        actual: extracted.expiryDate,
        severity: 'error',
        message: `Certificate expired on ${extracted.expiryDate}`,
      });
    } else {
      const daysUntil = Math.ceil((expiry.getTime() - now.getTime()) / (1000 * 60 * 60 * 24));
      if (daysUntil < 30) {
        discrepancies.push({
          field: 'expiryDate',
          expected: 'valid for >30 days',
          actual: `${daysUntil} days remaining`,
          severity: 'warning',
          message: `Certificate expires in ${daysUntil} days (${extracted.expiryDate})`,
        });
      }
    }
  }

  if (extracted.vatNumber && company.vatNumber && extracted.vatNumber !== company.vatNumber) {
    discrepancies.push({
      field: 'vatNumber',
      expected: company.vatNumber,
      actual: extracted.vatNumber,
      severity: 'error',
      message: `VAT number mismatch: certificate shows ${extracted.vatNumber}, company has ${company.vatNumber}`,
    });
  }

  const errorCount = discrepancies.filter(d => d.severity === 'error').length;
  const score = Math.max(0, 1 - (errorCount * 0.3 + (discrepancies.length - errorCount) * 0.1));

  return {
    valid: errorCount === 0,
    score: Math.round(score * 100) / 100,
    discrepancies,
    validatedAt: new Date().toISOString(),
  };
}

/**
 * Fuzzy Match Utility
 * Matches extracted vendor/customer names against existing database records
 * using Dice coefficient on bigrams for SA business name matching.
 */

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

interface MatchCandidate {
  id: string | number;
  name: string;
}

interface MatchResult {
  id: string | number;
  name: string;
  score: number;
}

const DEFAULT_THRESHOLD = 0.6;

/**
 * Find the best matching supplier from a list.
 */
export function fuzzyMatchSupplier(
  extractedName: string,
  suppliers: Array<{ id: string | number; name: string }>,
  threshold = DEFAULT_THRESHOLD,
): MatchResult | null {
  return findBestMatch(extractedName, suppliers, threshold);
}

/**
 * Find the best matching client from a list.
 * Handles `companyName` field mapping.
 */
export function fuzzyMatchClient(
  extractedName: string,
  clients: Array<{ id: string | number; companyName?: string; name?: string; company_name?: string }>,
  threshold = DEFAULT_THRESHOLD,
): MatchResult | null {
  const candidates: MatchCandidate[] = clients.map(c => ({
    id: c.id,
    name: c.companyName || c.company_name || c.name || '',
  }));
  return findBestMatch(extractedName, candidates, threshold);
}

// ---------------------------------------------------------------------------
// Core matching
// ---------------------------------------------------------------------------

function findBestMatch(
  query: string,
  candidates: MatchCandidate[],
  threshold: number,
): MatchResult | null {
  if (!query || candidates.length === 0) return null;

  const normalizedQuery = normalize(query);
  if (!normalizedQuery) return null;

  let best: MatchResult | null = null;

  for (const candidate of candidates) {
    const normalizedCandidate = normalize(candidate.name);
    if (!normalizedCandidate) continue;

    // Exact match after normalization
    if (normalizedQuery === normalizedCandidate) {
      return { id: candidate.id, name: candidate.name, score: 1.0 };
    }

    // Containment check (one contains the other)
    if (normalizedQuery.includes(normalizedCandidate) || normalizedCandidate.includes(normalizedQuery)) {
      const score = Math.min(normalizedQuery.length, normalizedCandidate.length) /
        Math.max(normalizedQuery.length, normalizedCandidate.length);
      const adjustedScore = 0.7 + score * 0.3; // Range: 0.7 - 1.0
      if (adjustedScore >= threshold && (!best || adjustedScore > best.score)) {
        best = { id: candidate.id, name: candidate.name, score: Math.round(adjustedScore * 100) / 100 };
      }
      continue;
    }

    // Dice coefficient on bigrams
    const score = diceCoefficient(normalizedQuery, normalizedCandidate);
    if (score >= threshold && (!best || score > best.score)) {
      best = { id: candidate.id, name: candidate.name, score: Math.round(score * 100) / 100 };
    }
  }

  return best;
}

// ---------------------------------------------------------------------------
// Normalization — strips SA business suffixes and noise
// ---------------------------------------------------------------------------

const STRIP_PATTERNS = [
  /\b\(pty\)\b/gi,
  /\bpty\b/gi,
  /\bltd\b/gi,
  /\blimited\b/gi,
  /\binc\b/gi,
  /\bincorporated\b/gi,
  /\bcc\b/gi,
  /\bnpc\b/gi,
  /\bsoc\b/gi,
  /\bt\/a\b/gi,
  /\btrading\s+as\b/gi,
];

function normalize(name: string): string {
  let s = name.toLowerCase().trim();
  for (const pattern of STRIP_PATTERNS) {
    s = s.replace(pattern, '');
  }
  // Remove punctuation and collapse whitespace
  s = s.replace(/[^a-z0-9\s]/g, '').replace(/\s+/g, ' ').trim();
  return s;
}

// ---------------------------------------------------------------------------
// Dice coefficient on bigrams
// ---------------------------------------------------------------------------

function bigrams(str: string): Set<string> {
  const result = new Set<string>();
  for (let i = 0; i < str.length - 1; i++) {
    result.add(str.substring(i, i + 2));
  }
  return result;
}

function diceCoefficient(a: string, b: string): number {
  if (a === b) return 1;
  if (a.length < 2 || b.length < 2) return 0;

  const bigramsA = bigrams(a);
  const bigramsB = bigrams(b);

  let intersectionSize = 0;
  for (const bg of bigramsA) {
    if (bigramsB.has(bg)) intersectionSize++;
  }

  return (2 * intersectionSize) / (bigramsA.size + bigramsB.size);
}

/**
 * Archive Query Service
 * Read-only queries: storage stats, preview, validation, run history, archived entries.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

type Row = Record<string, unknown>;

const COMPONENT = 'data-archiving';
const MIN_RETENTION_YEARS = 5;

export interface StorageStats {
  tableName: string;
  rowCount: number;
  oldestDate: string | null;
  newestDate: string | null;
}

export interface ArchivePreview {
  journalEntries: number;
  journalLines: number;
  bankTransactions: number;
  customerInvoices: number;
  supplierInvoices: number;
  totalRecords: number;
}

export interface ArchiveValidation {
  valid: boolean;
  errors: string[];
}

export interface ArchiveRun {
  id: string;
  cutoffDate: string;
  status: string;
  entriesArchived: number;
  linesArchived: number;
  transactionsArchived: number;
  invoicesArchived: number;
  supplierInvoicesArchived: number;
  startedAt: string | null;
  completedAt: string | null;
  errorMessage: string | null;
  createdAt: string;
}

export function toISODate(val: Date | string | null): string | null {
  if (!val) return null;
  if (val instanceof Date) return val.toISOString().split('T')[0] ?? null;
  return String(val).split('T')[0] ?? null;
}

export function toStr(val: Date | string | null | undefined): string {
  if (!val) return '';
  if (val instanceof Date) return val.toISOString();
  return String(val);
}

export async function getStorageStats(companyId: string): Promise<StorageStats[]> {
  try {
    const [jeRows, btRows, ciRows, siRows] = await Promise.all([
      sql`
        SELECT COUNT(*) AS row_count,
               MIN(entry_date) AS oldest_date,
               MAX(entry_date) AS newest_date
        FROM gl_journal_entries
        WHERE company_id = ${companyId}
      ` as Promise<Row[]>,
      sql`
        SELECT COUNT(*) AS row_count,
               MIN(transaction_date) AS oldest_date,
               MAX(transaction_date) AS newest_date
        FROM bank_transactions
        WHERE company_id = ${companyId}
      ` as Promise<Row[]>,
      sql`
        SELECT COUNT(*) AS row_count,
               MIN(invoice_date) AS oldest_date,
               MAX(invoice_date) AS newest_date
        FROM customer_invoices
        WHERE company_id = ${companyId}
      ` as Promise<Row[]>,
      sql`
        SELECT COUNT(*) AS row_count,
               MIN(invoice_date) AS oldest_date,
               MAX(invoice_date) AS newest_date
        FROM supplier_invoices
        WHERE company_id = ${companyId}
      ` as Promise<Row[]>,
    ]);

    const jlRows = (await sql`
      SELECT COUNT(*) AS row_count
      FROM gl_journal_lines jl
      JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
      WHERE je.company_id = ${companyId}
    `) as Row[];

    const stats: StorageStats[] = [
      {
        tableName: 'gl_journal_entries',
        rowCount: Number(jeRows[0]?.row_count ?? 0),
        oldestDate: toISODate((jeRows[0]?.oldest_date ?? null) as string | Date | null),
        newestDate: toISODate((jeRows[0]?.newest_date ?? null) as string | Date | null),
      },
      {
        tableName: 'gl_journal_lines',
        rowCount: Number(jlRows[0]?.row_count ?? 0),
        oldestDate: null,
        newestDate: null,
      },
      {
        tableName: 'bank_transactions',
        rowCount: Number(btRows[0]?.row_count ?? 0),
        oldestDate: toISODate((btRows[0]?.oldest_date ?? null) as string | Date | null),
        newestDate: toISODate((btRows[0]?.newest_date ?? null) as string | Date | null),
      },
      {
        tableName: 'customer_invoices',
        rowCount: Number(ciRows[0]?.row_count ?? 0),
        oldestDate: toISODate((ciRows[0]?.oldest_date ?? null) as string | Date | null),
        newestDate: toISODate((ciRows[0]?.newest_date ?? null) as string | Date | null),
      },
      {
        tableName: 'supplier_invoices',
        rowCount: Number(siRows[0]?.row_count ?? 0),
        oldestDate: toISODate((siRows[0]?.oldest_date ?? null) as string | Date | null),
        newestDate: toISODate((siRows[0]?.newest_date ?? null) as string | Date | null),
      },
    ];

    log.info('Storage stats retrieved', { companyId }, COMPONENT);
    return stats;
  } catch (err) {
    log.error('Failed to get storage stats', { companyId, error: err }, COMPONENT);
    throw err;
  }
}

export async function previewArchive(companyId: string, cutoffDate: string): Promise<ArchivePreview> {
  try {
    const [jeRows, btRows, ciRows, siRows] = await Promise.all([
      sql`
        SELECT COUNT(*) AS cnt
        FROM gl_journal_entries
        WHERE company_id = ${companyId}
          AND entry_date < ${cutoffDate}::date
          AND status = 'posted'
      ` as Promise<Row[]>,
      sql`
        SELECT COUNT(*) AS cnt
        FROM bank_transactions
        WHERE company_id = ${companyId}
          AND transaction_date < ${cutoffDate}::date
          AND status = 'reconciled'
      ` as Promise<Row[]>,
      sql`
        SELECT COUNT(*) AS cnt
        FROM customer_invoices
        WHERE company_id = ${companyId}
          AND invoice_date < ${cutoffDate}::date
          AND status IN ('paid', 'cancelled')
      ` as Promise<Row[]>,
      sql`
        SELECT COUNT(*) AS cnt
        FROM supplier_invoices
        WHERE company_id = ${companyId}
          AND invoice_date < ${cutoffDate}::date
          AND status IN ('paid', 'cancelled')
      ` as Promise<Row[]>,
    ]);

    const journalEntries = Number(jeRows[0]?.cnt ?? 0);
    const jlRows = (await sql`
      SELECT COUNT(*) AS cnt
      FROM gl_journal_lines jl
      JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
      WHERE je.company_id = ${companyId}
        AND je.entry_date < ${cutoffDate}::date
        AND je.status = 'posted'
    `) as Row[];

    const journalLines = Number(jlRows[0]?.cnt ?? 0);
    const bankTransactions = Number(btRows[0]?.cnt ?? 0);
    const customerInvoices = Number(ciRows[0]?.cnt ?? 0);
    const supplierInvoices = Number(siRows[0]?.cnt ?? 0);

    return {
      journalEntries,
      journalLines,
      bankTransactions,
      customerInvoices,
      supplierInvoices,
      totalRecords: journalEntries + journalLines + bankTransactions + customerInvoices + supplierInvoices,
    };
  } catch (err) {
    log.error('Failed to preview archive', { companyId, cutoffDate, error: err }, COMPONENT);
    throw err;
  }
}

export async function validateArchive(companyId: string, cutoffDate: string): Promise<ArchiveValidation> {
  const errors: string[] = [];

  try {
    const minCutoff = new Date();
    minCutoff.setFullYear(minCutoff.getFullYear() - MIN_RETENTION_YEARS);
    const cutoff = new Date(cutoffDate);
    if (cutoff >= minCutoff) {
      errors.push(
        `Cutoff date must be at least ${MIN_RETENTION_YEARS} years ago (before ${minCutoff.toISOString().split('T')[0]}). ` +
        `This is required by the SA Companies Act minimum retention period.`
      );
    }

    const unlockedRows = (await sql`
      SELECT COUNT(*) AS cnt
      FROM fiscal_periods
      WHERE company_id = ${companyId}
        AND end_date < ${cutoffDate}::date
        AND status != 'locked'
    `) as Row[];

    const unlockedCount = Number(unlockedRows[0]?.cnt ?? 0);
    if (unlockedCount > 0) {
      errors.push(
        `${unlockedCount} fiscal period(s) before the cutoff date are not locked. ` +
        `All periods must be locked before archiving.`
      );
    }

    const draftRows = (await sql`
      SELECT COUNT(*) AS cnt
      FROM gl_journal_entries
      WHERE company_id = ${companyId}
        AND entry_date < ${cutoffDate}::date
        AND status IN ('draft')
    `) as Row[];

    const draftCount = Number(draftRows[0]?.cnt ?? 0);
    if (draftCount > 0) {
      errors.push(
        `${draftCount} journal entry/entries before the cutoff are still in draft status. ` +
        `Post or delete these before archiving.`
      );
    }

    const preview = await previewArchive(companyId, cutoffDate);
    if (preview.totalRecords === 0) {
      errors.push('No records found before the cutoff date that are eligible for archiving.');
    }

    return { valid: errors.length === 0, errors };
  } catch (err) {
    log.error('Archive validation failed', { companyId, cutoffDate, error: err }, COMPONENT);
    throw err;
  }
}

export async function getArchiveRuns(companyId: string): Promise<ArchiveRun[]> {
  try {
    const rows = (await sql`
      SELECT id, cutoff_date, status, entries_archived, lines_archived,
             transactions_archived, invoices_archived, supplier_invoices_archived,
             started_at, completed_at, error_message, created_at
      FROM archive_runs
      WHERE company_id = ${companyId}
      ORDER BY created_at DESC
      LIMIT 50
    `) as Row[];

    return rows.map((r: Row): ArchiveRun => ({
      id: r.id as string,
      cutoffDate: toISODate(r.cutoff_date as string | Date | null) ?? '',
      status: r.status as string,
      entriesArchived: Number(r.entries_archived ?? 0),
      linesArchived: Number(r.lines_archived ?? 0),
      transactionsArchived: Number(r.transactions_archived ?? 0),
      invoicesArchived: Number(r.invoices_archived ?? 0),
      supplierInvoicesArchived: Number(r.supplier_invoices_archived ?? 0),
      startedAt: r.started_at ? toStr(r.started_at as Date | string) : null,
      completedAt: r.completed_at ? toStr(r.completed_at as Date | string) : null,
      errorMessage: r.error_message as string | null,
      createdAt: toStr(r.created_at as Date | string),
    }));
  } catch (err) {
    log.error('Failed to get archive runs', { companyId, error: err }, COMPONENT);
    throw err;
  }
}

/**
 * CSV utility helpers — shared across all export endpoints.
 *
 * All functions sanitize formula-injection prefixes (OWASP CWE-1236) by
 * prepending a single-quote when the value starts with =, +, -, @, TAB, or CR.
 * The prefix is applied BEFORE quote-wrapping so it lands inside the cell value.
 */

/** Prevent Excel/Sheets formula execution by prefixing dangerous leading chars. */
function sanitizeFormulaInjection(str: string): string {
  if (/^[=+\-@\t\r]/.test(str)) {
    return `'${str}`;
  }
  return str;
}

/**
 * Escape a string value for safe embedding in a CSV cell.
 * Always wraps in double-quotes and escapes internal double-quotes.
 * Accepts string | number | null | undefined — nullish values become empty string.
 */
export function csvCell(value: string | number | null | undefined): string {
  const str = sanitizeFormulaInjection(String(value ?? ''));
  return `"${str.replace(/"/g, '""')}"`;
}

/**
 * Alias for csvCell — used in report export files that call csvVal().
 * Identical behaviour; provided so existing callers don't need renaming.
 */
export function csvVal(value: string | number | null | undefined): string {
  return csvCell(value);
}

/**
 * Conditional quoting variant used in audit-log and custom-report exports.
 * Only wraps in double-quotes when the value contains commas, quotes, or newlines;
 * otherwise returns the plain sanitized string.
 * Nullish values become empty string.
 */
export function escapeCsv(value: string | number | null | undefined): string {
  if (value == null) return '';
  const raw = sanitizeFormulaInjection(String(value));
  if (raw.includes(',') || raw.includes('"') || raw.includes('\n')) {
    return `"${raw.replace(/"/g, '""')}"`;
  }
  return raw;
}

