/**
 * Extract bank statement transactions using VLM.
 */
export async function extractBankStatementWithVlm(
  base64: string,
  mimeType: string,
  rawText?: string,
): Promise<ExtractedBankStatement | null> {
  const config = getVlmConfig();
  if (!config) return null;

  let textPrompt = 'Extract all transactions from this bank statement.';
  if (rawText && rawText.trim().length > 0) {
    textPrompt += `\n\nPDF text layer:\n\n${rawText.substring(0, 6000)}`;
  }

  log.info('Calling vLLM for bank statement extraction', { model: config.model }, 'vlm-bank');

  const userContent = buildImageContent(base64, mimeType, textPrompt);
  const content = await callVlmChat(config, BANK_STATEMENT_PROMPT, userContent, 8192);
  if (!content) return null;

  return parseBankStatementResponse(content);
}

// ---------------------------------------------------------------------------
// Response parsing
// ---------------------------------------------------------------------------

function parseBankStatementResponse(content: string): ExtractedBankStatement | null {
  const jsonStr = cleanVlmJson(content);

  try {
    const parsed = JSON.parse(jsonStr) as Record<string, unknown>;

    const transactions: ExtractedBankTransaction[] = [];
    if (Array.isArray(parsed.transactions)) {
      for (const t of parsed.transactions) {
        if (!t || typeof t !== 'object') continue;
        const tx = t as Record<string, unknown>;
        transactions.push({
          date: asDateString(tx.date),
          description: asString(tx.description) || 'Unknown',
          amount: asNumber(tx.amount) ?? 0,
          balance: asNumber(tx.balance),
          reference: asString(tx.reference),
          transactionType: asString(tx.transactionType) ?? asString(tx.transaction_type),
        });
      }
    }

    const period = parsed.statementPeriod as Record<string, unknown> | null;

    const result: ExtractedBankStatement = {
      bankName: asString(parsed.bankName) ?? asString(parsed.bank_name),
      accountNumber: asString(parsed.accountNumber) ?? asString(parsed.account_number),
      statementPeriod: period
        ? { from: asDateString(period.from), to: asDateString(period.to) }
        : null,
      openingBalance: asNumber(parsed.openingBalance) ?? asNumber(parsed.opening_balance),
      closingBalance: asNumber(parsed.closingBalance) ?? asNumber(parsed.closing_balance),
      transactions,
      confidence: transactions.length > 0 ? 0.85 : 0.1,
      warnings: [],
    };

    if (transactions.length === 0) {
      result.warnings.push('No transactions extracted from bank statement');
    }

    log.info('Bank statement extraction successful', {
      bankName: result.bankName,
      transactionCount: transactions.length,
    }, 'vlm-bank');

    return result;
  } catch (err) {
    log.error('Failed to parse bank statement VLM response', {
      error: err instanceof Error ? err.message : String(err),
    }, 'vlm-bank');
    return null;
  }
}

/**
 * Archive Read Service
 * Query archived entries (read-only view into archive tables).
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { toISODate, toStr } from './archiveQueryService';

type Row = Record<string, unknown>;

const COMPONENT = 'data-archiving';

export interface ArchivedEntry {
  id: string;
  entryNumber: string | null;
  entryDate: string;
  description: string | null;
  status: string | null;
  source: string | null;
  createdAt: string;
}

export async function getArchivedEntries(
  companyId: string,
  filters: { dateFrom?: string; dateTo?: string; limit?: number; offset?: number }
): Promise<{ items: ArchivedEntry[]; total: number }> {
  try {
    const limit = Math.min(filters.limit ?? 50, 200);
    const offset = filters.offset ?? 0;
    const dateFrom = filters.dateFrom ?? null;
    const dateTo = filters.dateTo ?? null;

    const rows = (await sql`
      SELECT id, entry_number, entry_date, description, status, source, created_at
      FROM archive_gl_journal_entries
      WHERE company_id = ${companyId}
        AND (${dateFrom}::date IS NULL OR entry_date >= ${dateFrom}::date)
        AND (${dateTo}::date IS NULL OR entry_date <= ${dateTo}::date)
      ORDER BY entry_date DESC
      LIMIT ${limit} OFFSET ${offset}
    `) as Row[];

    const countRows = (await sql`
      SELECT COUNT(*) AS cnt
      FROM archive_gl_journal_entries
      WHERE company_id = ${companyId}
        AND (${dateFrom}::date IS NULL OR entry_date >= ${dateFrom}::date)
        AND (${dateTo}::date IS NULL OR entry_date <= ${dateTo}::date)
    `) as Row[];

    const items: ArchivedEntry[] = rows.map((r: Row): ArchivedEntry => ({
      id: r.id as string,
      entryNumber: r.entry_number as string | null,
      entryDate: toISODate(r.entry_date as string | Date | null) ?? '',
      description: r.description as string | null,
      status: r.status as string | null,
      source: r.source as string | null,
      createdAt: toStr(r.created_at as Date | string),
    }));

    return { items, total: Number(countRows[0]?.cnt ?? 0) };
  } catch (err) {
    log.error('Failed to get archived entries', { companyId, filters, error: err }, COMPONENT);
    throw err;
  }
}

/**
 * Document Validation Service
 * Compares VLM-extracted data against entity records to detect discrepancies.
 */

import type {
  ExtractedDocument,
  ExtractedStatutoryDoc,
  ValidationDiscrepancy,
  DocumentValidationResult,
} from '@/modules/accounting/types/documentCapture.types';

// ---------------------------------------------------------------------------
// Invoice Validation
// ---------------------------------------------------------------------------

interface InvoiceRecord {
  invoiceNumber?: string;
  totalAmount?: number;
  vatAmount?: number;
  taxRate?: number;
  vendorName?: string;
  supplierName?: string;
  customerName?: string;
  clientName?: string;
  invoiceDate?: string;
}

export function validateInvoiceDocument(
  extracted: ExtractedDocument,
  invoice: InvoiceRecord,
): DocumentValidationResult {
  const discrepancies: ValidationDiscrepancy[] = [];

  // Total amount
  if (extracted.totalAmount !== null && invoice.totalAmount !== undefined) {
    const diff = Math.abs(extracted.totalAmount - invoice.totalAmount);
    if (diff > 0.02) {
      discrepancies.push({
        field: 'totalAmount',
        expected: invoice.totalAmount,
        actual: extracted.totalAmount,
        severity: diff > invoice.totalAmount * 0.05 ? 'error' : 'warning',
        message: `Total mismatch: document shows ${extracted.totalAmount}, record has ${invoice.totalAmount}`,
      });
    }
  }

  // VAT amount
  if (extracted.vatAmount !== null && invoice.vatAmount !== undefined) {
    const diff = Math.abs(extracted.vatAmount - invoice.vatAmount);
    if (diff > 1) {
      discrepancies.push({
        field: 'vatAmount',
        expected: invoice.vatAmount,
        actual: extracted.vatAmount,
        severity: 'warning',
        message: `VAT mismatch: document shows ${extracted.vatAmount}, record has ${invoice.vatAmount}`,
      });
    }
  }

  // VAT arithmetic check
  if (extracted.subtotal !== null && extracted.vatAmount !== null && extracted.totalAmount !== null) {
    const expected = Math.round((extracted.subtotal + extracted.vatAmount) * 100) / 100;
    if (Math.abs(expected - extracted.totalAmount) > 0.02) {
      discrepancies.push({
        field: 'vatArithmetic',
        expected: expected,
        actual: extracted.totalAmount,
        severity: 'error',
        message: `VAT arithmetic error on document: subtotal (${extracted.subtotal}) + VAT (${extracted.vatAmount}) = ${expected}, but total shows ${extracted.totalAmount}`,
      });
    }
  }

  // Reference number
  if (extracted.referenceNumber && invoice.invoiceNumber) {
    const normExtracted = extracted.referenceNumber.replace(/[-\s/]/g, '').toLowerCase();
    const normInvoice = invoice.invoiceNumber.replace(/[-\s/]/g, '').toLowerCase();
    if (normExtracted !== normInvoice) {
      discrepancies.push({
        field: 'referenceNumber',
        expected: invoice.invoiceNumber,
        actual: extracted.referenceNumber,
        severity: 'warning',
        message: `Reference mismatch: document shows "${extracted.referenceNumber}", record has "${invoice.invoiceNumber}"`,
      });
    }
  }

  // Vendor/customer name (fuzzy check)
  const entityName = invoice.vendorName || invoice.supplierName || invoice.customerName || invoice.clientName;
  const extractedName = extracted.vendorName || extracted.customerName;
  if (entityName && extractedName) {
    const normEntity = entityName.toLowerCase().replace(/\b(pty|ltd|cc|inc)\b/gi, '').trim();
    const normExtracted = extractedName.toLowerCase().replace(/\b(pty|ltd|cc|inc)\b/gi, '').trim();
    if (!normExtracted.includes(normEntity) && !normEntity.includes(normExtracted)) {
      discrepancies.push({
        field: 'entityName',
        expected: entityName,
        actual: extractedName,
        severity: 'warning',
        message: `Name mismatch: document shows "${extractedName}", record has "${entityName}"`,
      });
    }
  }

  // Date check
  if (extracted.date && invoice.invoiceDate) {
    if (extracted.date !== invoice.invoiceDate) {
      discrepancies.push({
        field: 'date',
        expected: invoice.invoiceDate,
        actual: extracted.date,
        severity: 'info',
        message: `Date differs: document shows ${extracted.date}, record has ${invoice.invoiceDate}`,
      });
    }
  }

  const errorCount = discrepancies.filter(d => d.severity === 'error').length;
  const warningCount = discrepancies.filter(d => d.severity === 'warning').length;
  const score = Math.max(0, 1 - (errorCount * 0.3 + warningCount * 0.1));

  return {
    valid: errorCount === 0,
    score: Math.round(score * 100) / 100,
    discrepancies,
    validatedAt: new Date().toISOString(),
  };
}

// ---------------------------------------------------------------------------
// Payment Receipt Validation
// ---------------------------------------------------------------------------

interface PaymentRecord {
  totalAmount?: number;
  paymentDate?: string;
  reference?: string;
  bankReference?: string;
}

export function validatePaymentReceipt(
  extracted: ExtractedDocument,
  payment: PaymentRecord,
): DocumentValidationResult {
  const discrepancies: ValidationDiscrepancy[] = [];

  if (extracted.totalAmount !== null && payment.totalAmount !== undefined) {
    const diff = Math.abs(extracted.totalAmount - payment.totalAmount);
    if (diff > 0.02) {
      discrepancies.push({
        field: 'totalAmount',
        expected: payment.totalAmount,
        actual: extracted.totalAmount,
        severity: diff > payment.totalAmount * 0.01 ? 'error' : 'warning',
        message: `Amount mismatch: receipt shows ${extracted.totalAmount}, payment record has ${payment.totalAmount}`,
      });
    }
  }

  if (extracted.date && payment.paymentDate) {
    const docDate = new Date(extracted.date);
    const payDate = new Date(payment.paymentDate);
    const daysDiff = Math.abs((docDate.getTime() - payDate.getTime()) / (1000 * 60 * 60 * 24));
    if (daysDiff > 7) {
      discrepancies.push({
        field: 'date',
        expected: payment.paymentDate,
        actual: extracted.date,
        severity: 'warning',
        message: `Date differs by ${Math.round(daysDiff)} days: receipt ${extracted.date}, payment ${payment.paymentDate}`,
      });
    }
  }

  const errorCount = discrepancies.filter(d => d.severity === 'error').length;
  const score = Math.max(0, 1 - (errorCount * 0.3 + (discrepancies.length - errorCount) * 0.1));

  return {
    valid: errorCount === 0,
    score: Math.round(score * 100) / 100,
    discrepancies,
    validatedAt: new Date().toISOString(),
  };
}

// ---------------------------------------------------------------------------
// Statutory Compliance Validation
// ---------------------------------------------------------------------------

interface CompanyRecord {
  companyName?: string;
  registrationNumber?: string;
  vatNumber?: string;
}

export function validateStatutoryCompliance(
  extracted: ExtractedStatutoryDoc,
  company: CompanyRecord,
): DocumentValidationResult {
  const discrepancies: ValidationDiscrepancy[] = [];

  if (extracted.entityName && company.companyName) {
    const normExtracted = extracted.entityName.toLowerCase().replace(/\b(pty|ltd|cc|inc)\b/gi, '').trim();
    const normCompany = company.companyName.toLowerCase().replace(/\b(pty|ltd|cc|inc)\b/gi, '').trim();
    if (!normExtracted.includes(normCompany) && !normCompany.includes(normExtracted)) {
      discrepancies.push({
        field: 'entityName',
        expected: company.companyName,
        actual: extracted.entityName,
        severity: 'error',
        message: `Entity name mismatch: certificate shows "${extracted.entityName}", company is "${company.companyName}"`,
      });
    }
  }

  if (extracted.expiryDate) {
    const expiry = new Date(extracted.expiryDate);
    const now = new Date();
    if (expiry < now) {
      discrepancies.push({
        field: 'expiryDate',
        expected: 'valid (not expired)',
        actual: extracted.expiryDate,
        severity: 'error',
        message: `Certificate expired on ${extracted.expiryDate}`,
      });
    } else {
      const daysUntil = Math.ceil((expiry.getTime() - now.getTime()) / (1000 * 60 * 60 * 24));
      if (daysUntil < 30) {
        discrepancies.push({
          field: 'expiryDate',
          expected: 'valid for >30 days',
          actual: `${daysUntil} days remaining`,
          severity: 'warning',
          message: `Certificate expires in ${daysUntil} days (${extracted.expiryDate})`,
        });
      }
    }
  }

  if (extracted.vatNumber && company.vatNumber && extracted.vatNumber !== company.vatNumber) {
    discrepancies.push({
      field: 'vatNumber',
      expected: company.vatNumber,
      actual: extracted.vatNumber,
      severity: 'error',
      message: `VAT number mismatch: certificate shows ${extracted.vatNumber}, company has ${company.vatNumber}`,
    });
  }

  const errorCount = discrepancies.filter(d => d.severity === 'error').length;
  const score = Math.max(0, 1 - (errorCount * 0.3 + (discrepancies.length - errorCount) * 0.1));

  return {
    valid: errorCount === 0,
    score: Math.round(score * 100) / 100,
    discrepancies,
    validatedAt: new Date().toISOString(),
  };
}

/**
 * VLM Invoice Service — invoice/document extraction via vLLM (Qwen3-VL)
 *
 * Handles: invoice, credit_note, receipt, purchase_order, delivery_note
 * extraction from images and PDFs.
 */

import { log } from '@/lib/logger';
import type { ExtractedDocument } from '@/modules/accounting/types/documentCapture.types';
import {
  getVlmConfig,
  isVlmAvailable,
  callVlmChat,
  cleanVlmJson,
  buildImageContent,
  asString,
  asNumber,
  asDateString,
  parseLineItems,
  parseBankDetails,
} from './vlmCore';

// ---------------------------------------------------------------------------
// Extraction prompt
// ---------------------------------------------------------------------------

const EXTRACTION_PROMPT = `You are an expert accounting document reader specialised in South African business documents.
Analyse this document image and extract ALL available information into the JSON structure below.
Be precise with numbers — do not guess amounts. If a field is not visible, use null.

For South African documents:
- VAT registration numbers are 10 digits
- Standard VAT rate is 15%
- Currency is typically ZAR (South African Rand) shown as "R"
- Common banks: ABSA, FNB, Standard Bank, Nedbank, Capitec

Return ONLY valid JSON (no markdown, no explanation) matching this schema:

{
  "documentType": "invoice" | "credit_note" | "receipt" | "statement" | "purchase_order" | "delivery_note" | "unknown",
  "vendorName": string | null,
  "vendorVatNumber": string | null,
  "vendorAddress": string | null,
  "vendorBankDetails": { "bankName": string | null, "accountNumber": string | null, "branchCode": string | null, "accountType": string | null } | null,
  "customerName": string | null,
  "customerVatNumber": string | null,
  "date": "YYYY-MM-DD" | null,
  "dueDate": "YYYY-MM-DD" | null,
  "paymentTerms": string | null,
  "referenceNumber": string | null,
  "purchaseOrderRef": string | null,
  "currency": "ZAR" | string | null,
  "subtotal": number | null,
  "vatAmount": number | null,
  "vatRate": number | null,
  "totalAmount": number | null,
  "lineItems": [{ "description": string, "quantity": number | null, "unitPrice": number | null, "total": number | null, "vatAmount": number | null, "vatClassification": "standard" | "zero_rated" | "exempt" | "capital" | null, "glAccountSuggestion": string | null }]
}`;

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * Extract document data from an image buffer using Qwen3 VLM.
 * @param imageBase64 — base64-encoded image (JPEG/PNG) or PDF page render
 * @param mimeType — e.g. "image/jpeg", "image/png"
 * @param rawText — optional PDF text layer for cross-check context
 */
export async function extractWithVlm(
  imageBase64: string,
  mimeType: string,
  rawText?: string,
): Promise<ExtractedDocument | null> {
  const config = getVlmConfig();
  if (!config) {
    log.warn('VLM not configured — VLLM_BASE_URL not set', undefined, 'vlm-invoice');
    return null;
  }

  let textPrompt = 'Extract all accounting data from this document image.';
  if (rawText && rawText.trim().length > 0) {
    textPrompt += `\n\nThe PDF text layer also contains the following text (use it to cross-check your extraction):\n\n${rawText.substring(0, 4000)}`;
  }

  log.info('Calling vLLM for document extraction', {
    model: config.model,
    baseUrl: config.baseUrl,
    mimeType,
    hasRawText: !!rawText,
  }, 'vlm-invoice');

  const userContent = buildImageContent(imageBase64, mimeType, textPrompt);
  const content = await callVlmChat(config, EXTRACTION_PROMPT, userContent, 4096);
  if (!content) return null;

  return parseVlmResponse(content, rawText || '');
}

/**
 * Extract from PDF buffer using VLM.
 * Tries sending the PDF directly, then falls back to rendering the first page.
 */
export async function extractPdfWithVlm(
  pdfBuffer: Buffer,
  rawText?: string,
): Promise<ExtractedDocument | null> {
  if (!isVlmAvailable()) return null;

  const base64 = pdfBuffer.toString('base64');

  let result = await extractWithVlm(base64, 'application/pdf', rawText);
  if (result) return result;

  try {
    const pngBase64 = await renderPdfFirstPage(pdfBuffer);
    if (pngBase64) {
      result = await extractWithVlm(pngBase64, 'image/png', rawText);
      if (result) return result;
    }
  } catch (err) {
    log.warn('PDF-to-image conversion not available', {
      error: err instanceof Error ? err.message : String(err),
    }, 'vlm-invoice');
  }

  return null;
}

// ---------------------------------------------------------------------------
// PDF to image rendering (optional dependency — pdf2pic)
// ---------------------------------------------------------------------------

async function renderPdfFirstPage(pdfBuffer: Buffer): Promise<string | null> {
  try {
    // eslint-disable-next-line @typescript-eslint/no-var-requires
    const pdf2pic = require('pdf2pic') as {
      fromBuffer: (buf: Buffer, opts: Record<string, unknown>) => (
        pageNumber: number,
        options?: Record<string, unknown>
      ) => Promise<{ base64?: string }>;
    };
    const converter = pdf2pic.fromBuffer(pdfBuffer, {
      density: 200, format: 'png', width: 1600, height: 2200,
      saveFilename: 'page', savePath: '/tmp',
    });
    const result = await converter(1, { saveFilename: 'vlm_page', savePath: '/tmp' });
    if (result.base64) return result.base64;
  } catch {
    // pdf2pic not installed — skip image conversion
  }
  return null;
}

// ---------------------------------------------------------------------------
// Response parsing
// ---------------------------------------------------------------------------

function parseVlmResponse(content: string, rawText: string): ExtractedDocument | null {
  const jsonStr = cleanVlmJson(content);

  try {
    const parsed = JSON.parse(jsonStr) as Record<string, unknown>;

    const doc: ExtractedDocument = {
      documentType: validateDocumentType(parsed.documentType as string),
      vendorName: asString(parsed.vendorName),
      vendorVatNumber: asString(parsed.vendorVatNumber),
      vendorAddress: asString(parsed.vendorAddress),
      vendorBankDetails: parseBankDetails(parsed.vendorBankDetails),
      customerName: asString(parsed.customerName),
      customerVatNumber: asString(parsed.customerVatNumber),
      date: asDateString(parsed.date),
      dueDate: asDateString(parsed.dueDate),
      paymentTerms: asString(parsed.paymentTerms),
      referenceNumber: asString(parsed.referenceNumber),
      purchaseOrderRef: asString(parsed.purchaseOrderRef),
      currency: asString(parsed.currency) || 'ZAR',
      subtotal: asNumber(parsed.subtotal),
      vatAmount: asNumber(parsed.vatAmount),
      vatRate: asNumber(parsed.vatRate),
      totalAmount: asNumber(parsed.totalAmount),
      lineItems: parseLineItems(parsed.lineItems),
      rawText,
      confidence: computeConfidence(parsed),
      warnings: [],
      extractionMethod: 'vlm',
    };

    doc.warnings.push(...validateAmounts(doc));

    log.info('VLM extraction successful', {
      documentType: doc.documentType,
      confidence: doc.confidence,
      lineItemCount: doc.lineItems.length,
      warningCount: doc.warnings.length,
    }, 'vlm-invoice');

    return doc;
  } catch (err) {
    log.error('Failed to parse VLM JSON response', {
      error: err instanceof Error ? err.message : String(err),
      responsePreview: content.substring(0, 300),
    }, 'vlm-invoice');
    return null;
  }
}

function validateDocumentType(val: string | undefined): ExtractedDocument['documentType'] {
  const valid: ExtractedDocument['documentType'][] = [
    'invoice', 'credit_note', 'receipt', 'statement',
    'purchase_order', 'delivery_note', 'unknown',
  ];
  if (val && valid.includes(val as ExtractedDocument['documentType'])) {
    return val as ExtractedDocument['documentType'];
  }
  return 'unknown';
}

function computeConfidence(parsed: Record<string, unknown>): number {
  const weights = {
    vendorName: 0.15, date: 0.15, referenceNumber: 0.10, totalAmount: 0.20,
    vatAmount: 0.10, lineItems: 0.10, documentType: 0.05, dueDate: 0.05,
    vendorVatNumber: 0.05, customerName: 0.05,
  };
  let score = 0;
  if (parsed.vendorName) score += weights.vendorName;
  if (parsed.date) score += weights.date;
  if (parsed.referenceNumber) score += weights.referenceNumber;
  if (asNumber(parsed.totalAmount) !== null && asNumber(parsed.totalAmount)! > 0) score += weights.totalAmount;
  if (asNumber(parsed.vatAmount) !== null) score += weights.vatAmount;
  if (Array.isArray(parsed.lineItems) && parsed.lineItems.length > 0) score += weights.lineItems;
  if (parsed.documentType && parsed.documentType !== 'unknown') score += weights.documentType;
  if (parsed.dueDate) score += weights.dueDate;
  if (parsed.vendorVatNumber) score += weights.vendorVatNumber;
  if (parsed.customerName) score += weights.customerName;
  return Math.round(score * 100) / 100;
}

function validateAmounts(doc: ExtractedDocument): string[] {
  const warnings: string[] = [];
  if (doc.subtotal !== null && doc.vatAmount !== null && doc.totalAmount !== null) {
    const expected = Math.round((doc.subtotal + doc.vatAmount) * 100) / 100;
    if (Math.abs(expected - doc.totalAmount) > 0.02) {
      warnings.push(`Amount mismatch: subtotal (${doc.subtotal}) + VAT (${doc.vatAmount}) = ${expected}, but total is ${doc.totalAmount}`);
    }
  }
  if (doc.subtotal !== null && doc.vatRate !== null && doc.vatAmount !== null) {
    const expectedVat = Math.round(doc.subtotal * (doc.vatRate / 100) * 100) / 100;
    if (Math.abs(expectedVat - doc.vatAmount) > 1) {
      warnings.push(`VAT calculation may be incorrect: ${doc.vatRate}% of ${doc.subtotal} = ${expectedVat}, but extracted VAT is ${doc.vatAmount}`);
    }
  }
  if (doc.lineItems.length > 0 && doc.subtotal !== null) {
    const lineSum = Math.round(doc.lineItems.reduce((sum, li) => sum + (li.total ?? 0), 0) * 100) / 100;
    if (lineSum > 0 && Math.abs(lineSum - doc.subtotal) > 1) {
      warnings.push(`Line items sum (${lineSum}) differs from subtotal (${doc.subtotal})`);
    }
  }
  return warnings;
}

/**
