/**
 * VLM Statutory Service — statutory/compliance document extraction via vLLM (Qwen3-VL)
 *
 * Handles: CIPC certificates, SARS tax clearance, B-BBEE certificates, VAT registrations.
 */

import { log } from '@/lib/logger';
import type {
  ExtractedStatutoryDoc,
  StatutoryDocType,
} from '@/modules/accounting/types/documentCapture.types';
import {
  getVlmConfig,
  callVlmChat,
  cleanVlmJson,
  buildImageContent,
  asString,
  asNumber,
  asDateString,
} from './vlmCore';

// ---------------------------------------------------------------------------
// Extraction prompt
// ---------------------------------------------------------------------------

const STATUTORY_DOC_PROMPT = `You are an expert at reading South African statutory and compliance documents.
Extract key information from this document image.

Document types you may encounter:
- CIPC Registration Certificate (Companies and Intellectual Property Commission)
- SARS Tax Clearance Certificate / Tax Compliance Status
- B-BBEE Certificate (Broad-Based Black Economic Empowerment)
- VAT Registration Certificate

Return ONLY valid JSON (no markdown, no explanation) matching this schema:

{
  "documentType": "cipc" | "tax_clearance" | "bbee" | "vat_registration" | "unknown",
  "entityName": string | null,
  "registrationNumber": string | null,
  "vatNumber": string | null,
  "taxNumber": string | null,
  "issueDate": "YYYY-MM-DD" | null,
  "expiryDate": "YYYY-MM-DD" | null,
  "bbeeLevel": number | null,
  "bbeeScore": number | null,
  "verificationAgency": string | null
}

Notes:
- CIPC registration numbers look like: K2024/123456 or 2024/123456/07
- SA VAT numbers are 10 digits
- Tax reference numbers are typically 10 digits
- B-BBEE levels range from 1 (best) to 8 (non-compliant)
- Tax clearance certificates have a PIN and expiry date`;

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * Extract statutory document data using VLM.
 */
export async function extractStatutoryDocWithVlm(
  base64: string,
  mimeType: string,
  docTypeHint?: string,
): Promise<ExtractedStatutoryDoc | null> {
  const config = getVlmConfig();
  if (!config) return null;

  let textPrompt = 'Extract all information from this statutory document.';
  if (docTypeHint) {
    textPrompt += ` This is expected to be a ${docTypeHint} document.`;
  }

  log.info('Calling vLLM for statutory doc extraction', {
    model: config.model,
    docTypeHint,
  }, 'vlm-statutory');

  const userContent = buildImageContent(base64, mimeType, textPrompt);
  const content = await callVlmChat(config, STATUTORY_DOC_PROMPT, userContent, 2048);
  if (!content) return null;

  return parseStatutoryDocResponse(content);
}

// ---------------------------------------------------------------------------
// Response parsing
// ---------------------------------------------------------------------------

function parseStatutoryDocResponse(content: string): ExtractedStatutoryDoc | null {
  const jsonStr = cleanVlmJson(content);

  try {
    const parsed = JSON.parse(jsonStr) as Record<string, unknown>;

    const validTypes: StatutoryDocType[] = ['cipc', 'tax_clearance', 'bbee', 'vat_registration', 'unknown'];
    const docType = validTypes.includes(parsed.documentType as StatutoryDocType)
      ? parsed.documentType as StatutoryDocType
      : 'unknown';

    const result: ExtractedStatutoryDoc = {
      documentType: docType,
      entityName: asString(parsed.entityName) ?? asString(parsed.entity_name),
      registrationNumber: asString(parsed.registrationNumber) ?? asString(parsed.registration_number),
      vatNumber: asString(parsed.vatNumber) ?? asString(parsed.vat_number),
      taxNumber: asString(parsed.taxNumber) ?? asString(parsed.tax_number),
      issueDate: asDateString(parsed.issueDate) ?? asDateString(parsed.issue_date),
      expiryDate: asDateString(parsed.expiryDate) ?? asDateString(parsed.expiry_date),
      bbeeLevel: asNumber(parsed.bbeeLevel) ?? asNumber(parsed.bbee_level),
      bbeeScore: asNumber(parsed.bbeeScore) ?? asNumber(parsed.bbee_score),
      verificationAgency: asString(parsed.verificationAgency) ?? asString(parsed.verification_agency),
      confidence: docType !== 'unknown' ? 0.85 : 0.3,
      warnings: [],
    };

    log.info('Statutory doc extraction successful', {
      documentType: result.documentType,
      entityName: result.entityName,
    }, 'vlm-statutory');

    return result;
  } catch (err) {
    log.error('Failed to parse statutory doc VLM response', {
      error: err instanceof Error ? err.message : String(err),
    }, 'vlm-statutory');
    return null;
  }
}

/**
 * Customer Statement PDF Generator
 * Produces a portrait A4 PDF statement for a single customer
 * using jsPDF + jspdf-autotable (same pattern as reconReportPdf.ts)
 *
 * jsPDF and jspdf-autotable are loaded dynamically to keep them out of the
 * initial page bundle — they are only needed when the user clicks "Download PDF".
 */

// ─── Types ────────────────────────────────────────────────────────────────────

export interface StatementTransaction {
  date: string;
  type: 'invoice' | 'payment' | 'credit_note';
  reference: string;
  description: string;
  debit: number;
  credit: number;
  balance: number;
}

export interface StatementData {
  clientName: string;
  clientEmail?: string;
  clientPhone?: string;
  asAtDate: string;
  totalInvoiced: number;
  totalPaid: number;
  totalCredits: number;
  balanceOutstanding: number;
  transactions: StatementTransaction[];
  companyName?: string;
  companyVatNumber?: string;
}

// ─── Private helpers (no jsPDF type reference — avoids static import) ─────────

const fmtZAR = (amount: number): string =>
  new Intl.NumberFormat('en-ZA', {
    style: 'currency',
    currency: 'ZAR',
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  }).format(amount);

const fmtDate = (d: string): string => {
  if (!d) return '—';
  const parts = d.split('T')[0]?.split('-') ?? [];
  if (parts.length === 3) return `${parts[2]}/${parts[1]}/${parts[0]}`;
  return d;
};

// ─── Main Export Function ─────────────────────────────────────────────────────

/**
 * Generate a portrait A4 PDF customer statement and return it as a Blob.
 * Call `URL.createObjectURL(blob)` to download in the browser.
 *
 * This function is async because it dynamically imports jsPDF and
 * jspdf-autotable to avoid including them in the initial page bundle.
 */
// 🟢 WORKING: generateStatementPdf
export async function generateStatementPdf(data: StatementData): Promise<Blob> {
  const [{ jsPDF }, { default: autoTable }] = await Promise.all([
    import('jspdf'),
    import('jspdf-autotable'),
  ]);

  const doc = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
  const PAGE_W = doc.internal.pageSize.getWidth();

  // ── Header ──────────────────────────────────────────────────────────────────
  doc.setFontSize(18);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(30, 30, 30);
  doc.text('STATEMENT', 14, 18);

  doc.setFontSize(9);
  doc.setFont('helvetica', 'normal');
  doc.setTextColor(80, 80, 80);
  doc.text(data.companyName || 'Company Name Not Set', 14, 26);
  doc.text(data.companyVatNumber ? `VAT No: ${data.companyVatNumber}` : '', 14, 31);

  doc.setFont('helvetica', 'bold');
  doc.setFontSize(11);
  doc.setTextColor(30, 30, 30);
  doc.text(data.clientName, PAGE_W - 14, 18, { align: 'right' });

  doc.setFont('helvetica', 'normal');
  doc.setFontSize(8);
  doc.setTextColor(80, 80, 80);
  if (data.clientEmail) doc.text(data.clientEmail, PAGE_W - 14, 24, { align: 'right' });
  if (data.clientPhone) doc.text(data.clientPhone, PAGE_W - 14, 29, { align: 'right' });

  doc.text(`Statement Date: ${fmtDate(data.asAtDate)}`, PAGE_W - 14, 35, { align: 'right' });
  doc.text(`Generated: ${new Date().toLocaleString('en-ZA')}`, PAGE_W - 14, 40, { align: 'right' });

  doc.setDrawColor(200, 200, 200);
  doc.line(14, 44, PAGE_W - 14, 44);

  // ── Summary box ─────────────────────────────────────────────────────────────
  const BOX_H = 28;
  const COL = (PAGE_W - 28) / 4;
  let cursor = 48;

  doc.setFillColor(245, 247, 250);
  doc.setDrawColor(210, 215, 225);
  doc.roundedRect(14, cursor, PAGE_W - 28, BOX_H, 2, 2, 'FD');

  const labelY = cursor + 9;
  const valueY = cursor + 20;
  const summaryCols = [
    { label: 'Total Invoiced', value: data.totalInvoiced },
    { label: 'Total Paid', value: data.totalPaid },
    { label: 'Credits Applied', value: data.totalCredits },
    { label: 'Balance Due', value: data.balanceOutstanding },
  ];

  summaryCols.forEach((col, i) => {
    const x = 14 + COL * i + COL / 2;
    doc.setFontSize(7.5);
    doc.setFont('helvetica', 'normal');
    doc.setTextColor(100, 100, 100);
    doc.text(col.label, x, labelY, { align: 'center' });

    doc.setFontSize(10);
    doc.setFont('helvetica', 'bold');
    const isBalance = i === 3;
    if (isBalance && col.value > 0) {
      doc.setTextColor(180, 50, 50);
    } else if (isBalance) {
      doc.setTextColor(22, 163, 74);
    } else {
      doc.setTextColor(30, 30, 30);
    }
    doc.text(fmtZAR(col.value), x, valueY, { align: 'center' });
  });

  cursor += BOX_H + 6;

  // ── Transactions table ───────────────────────────────────────────────────────
  const typeLabels: Record<string, string> = {
    invoice: 'Invoice',
    payment: 'Payment',
    credit_note: 'Credit Note',
  };

  const rows = data.transactions.map(t => [
    fmtDate(t.date),
    typeLabels[t.type] || t.type,
    t.reference,
    t.description?.substring(0, 40) || '—',
    t.debit > 0 ? fmtZAR(t.debit) : '',
    t.credit > 0 ? fmtZAR(t.credit) : '',
    fmtZAR(t.balance),
  ]);

  autoTable(doc, {
    startY: cursor,
    head: [['Date', 'Type', 'Reference', 'Description', 'Debit', 'Credit', 'Balance']],
    body: rows,
    styles: { fontSize: 7.5, cellPadding: 2 },
    headStyles: { fillColor: [41, 82, 140], textColor: 255, fontStyle: 'bold', fontSize: 8 },
    alternateRowStyles: { fillColor: [248, 250, 252] },
    columnStyles: {
      4: { halign: 'right', font: 'courier' },
      5: { halign: 'right', font: 'courier' },
      6: { halign: 'right', font: 'courier', fontStyle: 'bold' },
    },
    tableWidth: PAGE_W - 28,
    margin: { left: 14, right: 14 },
  });

  // ── Page footers ─────────────────────────────────────────────────────────────
  const PAGE_H = doc.internal.pageSize.getHeight();
  const totalPages = (doc as typeof doc & { internal: { getNumberOfPages: () => number } })
    .internal.getNumberOfPages();

  for (let i = 1; i <= totalPages; i++) {
    doc.setPage(i);
    doc.setFontSize(7);
    doc.setFont('helvetica', 'normal');
    doc.setTextColor(150, 150, 150);
    doc.line(14, PAGE_H - 10, PAGE_W - 14, PAGE_H - 10);
    doc.text(`Page ${i} of ${totalPages}`, PAGE_W - 14, PAGE_H - 5, { align: 'right' });
    doc.text('FibreFlow Customer Statement — Confidential', 14, PAGE_H - 5);
  }

  return doc.output('blob');
}

/**
 * Description Template Service
 * WS-6.5: Description Templates & Auto-Suggest
 *
 * Provides template management and auto-suggest for description fields
 * using a combination of stored templates and historical GL descriptions.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

type Row = Record<string, unknown>;

export interface DescriptionTemplate {
  id: string;
  companyId: string;
  name: string;
  template: string;
  entityType?: string;
  usageCount: number;
  createdAt: Date | string;
}

export interface DescriptionSuggestion {
  text: string;
  source: 'template' | 'history';
  count?: number;
}

// ── Suggest ──────────────────────────────────────────────────────────────────

export async function suggestDescriptions(
  companyId: string,
  query: string,
  entityType?: string,
  limit = 10,
): Promise<DescriptionSuggestion[]> {
  if (!query.trim()) return [];

  const pattern = `%${query.trim()}%`;

  // 1. Matching templates
  const templateRows = (await sql`
    SELECT name, template, usage_count
    FROM transaction_description_templates
    WHERE company_id = ${companyId}::UUID
      AND (
        template ILIKE ${pattern}
        OR name ILIKE ${pattern}
      )
      ${entityType ? sql`AND (entity_type IS NULL OR entity_type = ${entityType})` : sql``}
    ORDER BY usage_count DESC, name ASC
    LIMIT ${limit}
  `) as Row[];

  const templateSuggestions: DescriptionSuggestion[] = templateRows.map(r => ({
    text: r.template as string,
    source: 'template' as const,
    count: Number(r.usage_count),
  }));

  // 2. Historical descriptions from gl_journal_entries
  const remaining = limit - templateSuggestions.length;
  const historySuggestions: DescriptionSuggestion[] = [];

  if (remaining > 0) {
    const historyRows = (await sql`
      SELECT description, COUNT(*) AS usage_count
      FROM gl_journal_entries
      WHERE company_id = ${companyId}::UUID
        AND description IS NOT NULL
        AND description <> ''
        AND description ILIKE ${pattern}
      GROUP BY description
      ORDER BY COUNT(*) DESC
      LIMIT ${remaining}
    `) as Row[];

    for (const r of historyRows) {
      const text = r.description as string;
      // Only include if not already covered by a template suggestion
      const isDuplicate = templateSuggestions.some(s => s.text === text);
      if (!isDuplicate) {
        historySuggestions.push({
          text,
          source: 'history',
          count: Number(r.usage_count),
        });
      }
    }
  }

  return [...templateSuggestions, ...historySuggestions];
}

// ── CRUD ─────────────────────────────────────────────────────────────────────

export async function getTemplates(
  companyId: string,
  entityType?: string,
): Promise<DescriptionTemplate[]> {
  const rows = (await sql`
    SELECT
      id, company_id, name, template, entity_type, usage_count, created_at
    FROM transaction_description_templates
    WHERE company_id = ${companyId}::UUID
      ${entityType ? sql`AND (entity_type IS NULL OR entity_type = ${entityType})` : sql``}
    ORDER BY usage_count DESC, name ASC
  `) as Row[];

  return rows.map(mapRow);
}

export async function createTemplate(
  companyId: string,
  name: string,
  template: string,
  entityType?: string,
): Promise<DescriptionTemplate> {
  if (!name.trim() || !template.trim()) {
    throw new Error('name and template are required');
  }

  const rows = (await sql`
    INSERT INTO transaction_description_templates (company_id, name, template, entity_type)
    VALUES (${companyId}::UUID, ${name.trim()}, ${template.trim()}, ${entityType ?? null})
    ON CONFLICT (company_id, name)
    DO UPDATE SET template = EXCLUDED.template, entity_type = EXCLUDED.entity_type
    RETURNING id, company_id, name, template, entity_type, usage_count, created_at
  `) as Row[];

  const row = rows[0];
  if (!row) throw new Error('Failed to create template');

  log.info('Description template created', { companyId, name }, 'descriptionTemplateService');
  return mapRow(row);
}

export async function deleteTemplate(
  companyId: string,
  id: string,
): Promise<void> {
  await sql`
    DELETE FROM transaction_description_templates
    WHERE id = ${id}::UUID AND company_id = ${companyId}::UUID
  `;
  log.info('Description template deleted', { companyId, id }, 'descriptionTemplateService');
}

export async function incrementUsageCount(
  companyId: string,
  templateText: string,
): Promise<void> {
  await sql`
    UPDATE transaction_description_templates
    SET usage_count = usage_count + 1
    WHERE company_id = ${companyId}::UUID
      AND template = ${templateText}
  `;
}

// ── Mapper ───────────────────────────────────────────────────────────────────

function mapRow(r: Row): DescriptionTemplate {
  return {
    id: r.id as string,
    companyId: r.company_id as string,
    name: r.name as string,
    template: r.template as string,
    entityType: r.entity_type as string | undefined,
    usageCount: Number(r.usage_count),
    createdAt: r.created_at as Date | string,
  };
}

