vi.mock('@/lib/neon', () => {
  const noopTag = () => Promise.resolve([]);
  (noopTag as unknown as Record<string, unknown>).unsafe = (s: string) => s;
  return { sql: noopTag, transaction: (_cb: unknown) => Promise.resolve() };
});

vi.mock('@/lib/logger', () => ({
  log: { info: vi.fn(), warn: vi.fn(), error: vi.fn(), debug: vi.fn() },
}));

