    expect(input.toISOString()).toBe(original);
  });

  it('handles year boundary for annual frequency', () => {
    const result = calculateNextRunDate(new Date('2025-12-31'), 'annually');
    expect(result.toISOString().split('T')[0]).toBe('2026-12-31');
  });
});

