    const bankTxs = [{ id: 'tx-y', amount: 5000, transactionDate: '2025-04-01' }];
    const { matches, unmatched } = runAutoMatch(bankTxs, []);
    expect(matches).toHaveLength(0);
    expect(unmatched).toContain('tx-y');
  });
});

