      { name: 'Audit trail', isa: Y, sage: Y, qbo: Y },
      { name: 'Approval workflows', isa: Y, sage: N, qbo: N },
      { name: 'Data archiving', isa: Y, sage: N, qbo: N },
      { name: 'POPIA compliance tools', isa: Y, sage: P, qbo: P },
    ],
  },
  {
    title: '16. SA Compliance',
    features: [
      { name: 'BEE scorecard / reporting', isa: Y, sage: N, qbo: N },
      { name: 'SARS compliance calendar', isa: Y, sage: N, qbo: N },
      { name: 'Month-end close checklist', isa: Y, sage: N, qbo: N },
      { name: 'Year-end close', isa: Y, sage: P, qbo: P },
      { name: 'Data subject rights (POPIA)', isa: Y, sage: N, qbo: N },
    ],
  },
  {
    title: '17. Group / Multi-Entity',
    features: [
      { name: 'Multi-company management', isa: Y, sage: N, qbo: N },
      { name: 'Consolidated reporting', isa: Y, sage: N, qbo: N },
      { name: 'Intercompany transactions', isa: Y, sage: N, qbo: N },
      { name: 'Group chart of accounts', isa: Y, sage: N, qbo: N },
      { name: 'Elimination entries', isa: Y, sage: N, qbo: N },
    ],
  },
  {
    title: '18. Integration & Export',
    features: [
      { name: 'SA bank feeds', isa: Y, sage: Y, qbo: Y },
      { name: 'PayFast gateway', isa: Y, sage: P, qbo: N },
      { name: 'CaseWare export', isa: Y, sage: Y, qbo: Y },
      { name: 'REST API', isa: Y, sage: Y, qbo: Y },
      { name: 'Webhooks', isa: Y, sage: P, qbo: P },
      { name: 'Sage data import / migration', isa: Y, sage: 'N/A', qbo: N },
      { name: 'CSV / PDF / Excel export', isa: Y, sage: Y, qbo: P },
      { name: 'Customer portal', isa: Y, sage: Y, qbo: P },
      { name: 'Mobile app', isa: 'PWA', sage: Y, qbo: Y },
    ],
  },
];

function score(v: string): number {
  if (v === Y) return 1;
  if (v === N) return 0;
  if (v === P || v === 'PWA') return 0.5;
  // Tier-locked or add-on or separate = 0.5
  return 0.5;
}

function cellColor(v: string): [number, number, number] {
  if (v === Y) return [GREEN.r, GREEN.g, GREEN.b];
  if (v === N) return [RED.r, RED.g, RED.b];
  return [AMBER.r, AMBER.g, AMBER.b];
}

async function main() {
  const [{ jsPDF }, { default: autoTable }] = await Promise.all([
    import('jspdf'),
    import('jspdf-autotable'),
  ]);

  const doc = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
  const W = doc.internal.pageSize.getWidth();
  const H = doc.internal.pageSize.getHeight();
  const M = 14;

  // ── Cover Page ──────────────────────────────────────────────────────────────
  doc.setFillColor(TEAL.r, TEAL.g, TEAL.b);
  doc.rect(0, 0, W, 55, 'F');
  doc.setFontSize(28);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(255, 255, 255);
  doc.text('ISAFlow', M, 28);
  doc.setFontSize(11);
  doc.setFont('helvetica', 'normal');
  doc.text('Cloud Accounting for South African Businesses', M, 40);

  doc.setFontSize(24);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(DARK.r, DARK.g, DARK.b);
  doc.text('Competitive Feature', M, 85);
  doc.text('Comparison', M, 97);

  doc.setDrawColor(TEAL.r, TEAL.g, TEAL.b);
  doc.setLineWidth(1);
  doc.line(M, 105, M + 50, 105);

  doc.setFontSize(14);
  doc.setFont('helvetica', 'normal');
  doc.setTextColor(GRAY.r, GRAY.g, GRAY.b);
  doc.text('ISAFlow  vs  Sage Business Cloud  vs  QuickBooks Online', M, 120);

  doc.setFontSize(11);
  doc.text('South Africa Edition', M, 132);
  doc.text('April 2026', M, 142);

  // Competitor boxes
  const boxY = 165;
  const boxW = (W - M * 2 - 12) / 3;

  // ISAFlow
  doc.setFillColor(TEAL.r, TEAL.g, TEAL.b);
  doc.roundedRect(M, boxY, boxW, 35, 3, 3, 'F');
  doc.setFontSize(13);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(255, 255, 255);
  doc.text('ISAFlow', M + boxW / 2, boxY + 15, { align: 'center' });
  doc.setFontSize(8);
  doc.setFont('helvetica', 'normal');
  doc.text('Cloud Accounting', M + boxW / 2, boxY + 23, { align: 'center' });
  doc.text('app.isaflow.co.za', M + boxW / 2, boxY + 29, { align: 'center' });

  // Sage
  doc.setFillColor(0, 136, 62);
  doc.roundedRect(M + boxW + 6, boxY, boxW, 35, 3, 3, 'F');
  doc.setTextColor(255, 255, 255);
  doc.setFontSize(13);
  doc.setFont('helvetica', 'bold');
  doc.text('Sage', M + boxW + 6 + boxW / 2, boxY + 15, { align: 'center' });
  doc.setFontSize(8);
  doc.setFont('helvetica', 'normal');
  doc.text('Business Cloud', M + boxW + 6 + boxW / 2, boxY + 23, { align: 'center' });
  doc.text('From R240/mo', M + boxW + 6 + boxW / 2, boxY + 29, { align: 'center' });

  // QuickBooks
  doc.setFillColor(44, 160, 28);
  doc.roundedRect(M + (boxW + 6) * 2, boxY, boxW, 35, 3, 3, 'F');
  doc.setTextColor(255, 255, 255);
  doc.setFontSize(13);
  doc.setFont('helvetica', 'bold');
  doc.text('QuickBooks', M + (boxW + 6) * 2 + boxW / 2, boxY + 15, { align: 'center' });
  doc.setFontSize(8);
  doc.setFont('helvetica', 'normal');
  doc.text('Online', M + (boxW + 6) * 2 + boxW / 2, boxY + 23, { align: 'center' });
  doc.text('From R250/mo', M + (boxW + 6) * 2 + boxW / 2, boxY + 29, { align: 'center' });

  doc.setFontSize(8);
  doc.setTextColor(150, 150, 150);
  doc.text('Confidential \u2014 For Internal Use', W / 2, H - 15, { align: 'center' });

  // ── Executive Summary Page ──────────────────────────────────────────────────
  doc.addPage();
  let y = 20;

  doc.setFillColor(TEAL.r, TEAL.g, TEAL.b);
  doc.rect(0, 0, W, 8, 'F');

  doc.setFontSize(18);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(DARK.r, DARK.g, DARK.b);
  doc.text('Executive Summary', M, y + 8);
  y += 18;

  doc.setFontSize(9);
  doc.setFont('helvetica', 'normal');
  doc.setTextColor(60, 60, 60);
  const summaryText = [
    'This document provides a feature-by-feature comparison of ISAFlow against the two leading cloud',
    'accounting platforms in South Africa: Sage Business Cloud Accounting and QuickBooks Online.',
    '',
    'ISAFlow is purpose-built for South African businesses, with integrated payroll, SARS compliance,',
    'BEE reporting, fixed asset management, and advanced AI capabilities \u2014 all included in the base',
    'price without add-on fees. Key differentiators include multi-entity consolidation, three-way',
    'procurement matching, AI-powered document capture with Vision Language Models, and a comprehensive',
    'reporting suite with executive dashboards, report packs, and three-way financial forecasting.',
  ];
  summaryText.forEach((line, i) => {
    doc.text(line, M, y + i * 5);
  });
  y += summaryText.length * 5 + 8;

  // Legend
  doc.setFillColor(240, 253, 250);
  doc.roundedRect(M, y, W - M * 2, 18, 2, 2, 'F');
  doc.setFontSize(8);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(TEAL.r, TEAL.g, TEAL.b);
  doc.text('Legend:', M + 4, y + 6);
  doc.setFont('helvetica', 'normal');
  doc.setTextColor(GREEN.r, GREEN.g, GREEN.b);
  doc.text(`${Y} = Included`, M + 22, y + 6);
  doc.setTextColor(AMBER.r, AMBER.g, AMBER.b);
  doc.text(`${P} = Partial / Add-on / Tier-locked`, M + 50, y + 6);
  doc.setTextColor(RED.r, RED.g, RED.b);
  doc.text(`${N} = Not available`, M + 110, y + 6);
  doc.setTextColor(GRAY.r, GRAY.g, GRAY.b);
  doc.text('Std = Standard plan only  |  Ess+ = Essentials+  |  Plus+ = Plus plan  |  Adv = Advanced only  |  Add-on = Paid extra', M + 4, y + 13);
  y += 24;

  // Summary scores table
  doc.setFontSize(12);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(DARK.r, DARK.g, DARK.b);
  doc.text('Feature Score Summary by Module', M, y + 2);
  y += 6;

  const summaryRows: string[][] = [];
  let totalIsa = 0, totalSage = 0, totalQbo = 0;

  for (const section of SECTIONS) {
    let sIsa = 0, sSage = 0, sQbo = 0;
    for (const f of section.features) {
      sIsa += score(f.isa);
      sSage += score(f.sage);
      sQbo += score(f.qbo);
    }
    totalIsa += sIsa;
    totalSage += sSage;
    totalQbo += sQbo;
    const max = section.features.length;
    summaryRows.push([
      section.title,
      `${sIsa}/${max}`,
      `${sSage % 1 === 0 ? sSage : sSage.toFixed(1)}/${max}`,
      `${sQbo % 1 === 0 ? sQbo : sQbo.toFixed(1)}/${max}`,
    ]);
  }

  const totalFeatures = SECTIONS.reduce((s, sec) => s + sec.features.length, 0);
  summaryRows.push([
    'TOTAL',
    `${totalIsa}/${totalFeatures}`,
    `${totalSage % 1 === 0 ? totalSage : totalSage.toFixed(1)}/${totalFeatures}`,
    `${totalQbo % 1 === 0 ? totalQbo : totalQbo.toFixed(1)}/${totalFeatures}`,
  ]);

  autoTable(doc, {
    head: [['Module', 'ISAFlow', 'Sage', 'QuickBooks']],
    body: summaryRows,
    startY: y,
    margin: { left: M, right: M },
    styles: { fontSize: 7.5, cellPadding: 2 },
    headStyles: { fillColor: [TEAL.r, TEAL.g, TEAL.b], textColor: [255, 255, 255], fontStyle: 'bold' },
    alternateRowStyles: { fillColor: [249, 250, 251] },
    columnStyles: {
      0: { fontStyle: 'bold', cellWidth: 75 },
      1: { halign: 'center', cellWidth: 30 },
      2: { halign: 'center', cellWidth: 30 },
      3: { halign: 'center', cellWidth: 30 },
    },
    didParseCell: (data: any) => {
      // Bold + teal for last row
      if (data.row.index === summaryRows.length - 1) {
        data.cell.styles.fontStyle = 'bold';
        data.cell.styles.fillColor = [240, 253, 250];
        data.cell.styles.textColor = [TEAL.r, TEAL.g, TEAL.b];
      }
    },
  });

  // ── Feature Comparison Pages ────────────────────────────────────────────────
  for (const section of SECTIONS) {
    const prevY: number = (doc as any).lastAutoTable?.finalY ?? 20;
    if (prevY > H - 60) {
      doc.addPage();
      (doc as any).lastAutoTable = { finalY: 15 };
    }

    const startY: number = ((doc as any).lastAutoTable?.finalY ?? 15) + 10;

    // Section header
    doc.setFillColor(TEAL.r, TEAL.g, TEAL.b);
    doc.rect(M, startY, W - M * 2, 7, 'F');
    doc.setFontSize(9);
    doc.setFont('helvetica', 'bold');
    doc.setTextColor(255, 255, 255);
    doc.text(section.title.toUpperCase(), M + 3, startY + 5);

    const rows = section.features.map(f => [f.name, f.isa, f.sage, f.qbo]);

    autoTable(doc, {
      head: [['Feature', 'ISAFlow', 'Sage', 'QuickBooks']],
      body: rows,
      startY: startY + 9,
      margin: { left: M, right: M },
      styles: { fontSize: 7.5, cellPadding: 2 },
      headStyles: { fillColor: [240, 253, 250], textColor: [TEAL.r, TEAL.g, TEAL.b], fontStyle: 'bold' },
      alternateRowStyles: { fillColor: [249, 250, 251] },
      columnStyles: {
        0: { cellWidth: 75 },
        1: { halign: 'center', cellWidth: 30 },
        2: { halign: 'center', cellWidth: 30 },
        3: { halign: 'center', cellWidth: 30 },
      },
      didParseCell: (data: any) => {
        if (data.section === 'body' && data.column.index >= 1) {
          const val = data.cell.raw as string;
          const [r, g, b] = cellColor(val);
          data.cell.styles.textColor = [r, g, b];
          data.cell.styles.fontStyle = 'bold';
        }
      },
    });
  }

  // ── Score Summary Page ──────────────────────────────────────────────────────
  doc.addPage();
  doc.setFillColor(TEAL.r, TEAL.g, TEAL.b);
  doc.rect(0, 0, W, 8, 'F');

  doc.setFontSize(18);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(DARK.r, DARK.g, DARK.b);
  doc.text('Overall Score', M, 28);

  doc.setFontSize(10);
  doc.setFont('helvetica', 'normal');
  doc.setTextColor(GRAY.r, GRAY.g, GRAY.b);
  doc.text(`${totalFeatures} features compared across 18 modules`, M, 36);

  // Big score cards
  const cardY = 50;
  const cardW = (W - M * 2 - 16) / 3;
  const cardH = 55;

  const scores = [
    { name: 'ISAFlow', score: totalIsa, pct: Math.round((totalIsa / totalFeatures) * 100), color: TEAL },
    { name: 'Sage', score: totalSage, pct: Math.round((totalSage / totalFeatures) * 100), color: { r: 0, g: 136, b: 62 } },
    { name: 'QuickBooks', score: totalQbo, pct: Math.round((totalQbo / totalFeatures) * 100), color: { r: 44, g: 160, b: 28 } },
  ];

  scores.forEach((s, i) => {
    const x = M + i * (cardW + 8);
    doc.setFillColor(s.color.r, s.color.g, s.color.b);
    doc.roundedRect(x, cardY, cardW, cardH, 3, 3, 'F');

    doc.setFontSize(13);
    doc.setFont('helvetica', 'bold');
    doc.setTextColor(255, 255, 255);
    doc.text(s.name, x + cardW / 2, cardY + 14, { align: 'center' });

    doc.setFontSize(28);
    doc.text(`${s.pct}%`, x + cardW / 2, cardY + 34, { align: 'center' });

    doc.setFontSize(9);
    doc.setFont('helvetica', 'normal');
    const scoreStr = s.score % 1 === 0 ? String(s.score) : s.score.toFixed(1);
    doc.text(`${scoreStr} / ${totalFeatures} features`, x + cardW / 2, cardY + 44, { align: 'center' });
  });

  // Key takeaways
  const tkY = cardY + cardH + 20;
  doc.setFontSize(12);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(DARK.r, DARK.g, DARK.b);
  doc.text('Key Takeaways', M, tkY);

  const takeaways = [
    'ISAFlow offers the most comprehensive feature set of any SA cloud accounting platform.',
    'Sage has no fixed assets, no purchase orders, no AI features, and no multi-entity support.',
    'QuickBooks locks critical features (assets, POs, budgets) behind expensive tiers.',
    'Neither competitor offers integrated SA payroll \u2014 both require separate subscriptions.',
    'ISAFlow is the only platform with AI management commentary and three-way forecasting.',
    'ISAFlow is the only platform with BEE reporting and SARS compliance calendar.',
    'Multi-currency, time tracking, and inventory are all add-ons on Sage (+R165/mo each).',
    'ISAFlow includes everything in the base price \u2014 no add-on fees.',
  ];

  doc.setFontSize(8.5);
  doc.setFont('helvetica', 'normal');
  doc.setTextColor(60, 60, 60);
  takeaways.forEach((t, i) => {
    doc.setTextColor(TEAL.r, TEAL.g, TEAL.b);
    doc.text('\u2022', M + 2, tkY + 8 + i * 6);
    doc.setTextColor(60, 60, 60);
    doc.text(t, M + 7, tkY + 8 + i * 6);
  });

  // ── Back Cover ──────────────────────────────────────────────────────────────
  doc.addPage();
  doc.setFillColor(DARK.r, DARK.g, DARK.b);
  doc.rect(0, 0, W, H, 'F');

  doc.setFillColor(TEAL.r, TEAL.g, TEAL.b);
  doc.roundedRect(W / 2 - 35, 80, 70, 25, 4, 4, 'F');
  doc.setFontSize(22);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(255, 255, 255);
  doc.text('ISAFlow', W / 2, 97, { align: 'center' });

  doc.setFontSize(13);
  doc.setFont('helvetica', 'normal');
  doc.setTextColor(200, 200, 200);
  doc.text('Built for South African businesses', W / 2, 125, { align: 'center' });

  doc.setFontSize(10);
  doc.setTextColor(TEAL.r, TEAL.g, TEAL.b);
  doc.text('app.isaflow.co.za', W / 2, 145, { align: 'center' });

  doc.setFontSize(8);
  doc.setTextColor(100, 100, 100);
  doc.text('\u00A9 2026 ISAFlow. All rights reserved.', W / 2, H - 20, { align: 'center' });

  // ── Page footers ────────────────────────────────────────────────────────────
  const pageCount = doc.getNumberOfPages();
  for (let i = 2; i < pageCount; i++) {
    // Skip cover (1) and back cover (last)
    doc.setPage(i);
    doc.setDrawColor(TEAL.r, TEAL.g, TEAL.b);
    doc.setLineWidth(0.3);
    doc.line(M, H - 12, W - M, H - 12);
    doc.setFontSize(7);
    doc.setFont('helvetica', 'normal');
    doc.setTextColor(150, 150, 150);
    doc.text('ISAFlow \u2014 Competitive Feature Comparison', M, H - 8);
    doc.text(`Page ${i - 1} of ${pageCount - 2}`, W - M, H - 8, { align: 'right' });
  }

  // ── Save ────────────────────────────────────────────────────────────────────
  const buffer = Buffer.from(doc.output('arraybuffer'));
  const fs = await import('fs');
  const path = await import('path');
  const outPath = path.resolve(__dirname, '..', 'docs', 'ISAFlow-Competitive-Comparison-2026.pdf');
  fs.mkdirSync(path.dirname(outPath), { recursive: true });
  fs.writeFileSync(outPath, buffer);
  const sizeMB = (buffer.byteLength / 1024 / 1024).toFixed(2);
  console.log(`PDF generated: ${outPath} (${sizeMB} MB, ${pageCount} pages)`);
}

main().catch(err => {
  console.error('Failed to generate PDF:', err);
  process.exit(1);
});

