const AMBER = { r: 245, g: 158, b: 11 };
const GRAY = { r: 107, g: 114, b: 128 };

interface Feature {
  name: string;
  isa: string;
  sage: string;
  qbo: string;
}

interface Section {
  title: string;
  features: Feature[];
}

const Y = '\u2713';
const N = '\u2717';
const P = '\u25D0'; // partial

const SECTIONS: Section[] = [
