      { name: 'VAT201 preparation', isa: Y, sage: 'Std', qbo: P },
      { name: 'SARS eFiling integration', isa: Y, sage: Y, qbo: N },
      { name: 'EMP201 submission', isa: Y, sage: 'Payroll', qbo: N },
      { name: 'EMP501 reconciliation', isa: Y, sage: 'Payroll', qbo: N },
      { name: 'IRP5 certificates', isa: Y, sage: 'Payroll', qbo: N },
      { name: 'IRP6 provisional tax', isa: Y, sage: N, qbo: N },
      { name: 'Compliance calendar', isa: Y, sage: N, qbo: N },
