  doc.setFontSize(8);
  doc.setFont('helvetica', 'normal');
  doc.text('Cloud Accounting', M + boxW / 2, boxY + 23, { align: 'center' });
  doc.text('app.isaflow.co.za', M + boxW / 2, boxY + 29, { align: 'center' });

  // Sage
  doc.setFillColor(0, 136, 62);
  doc.roundedRect(M + boxW + 6, boxY, boxW, 35, 3, 3, 'F');
  doc.setTextColor(255, 255, 255);
  doc.setFontSize(13);
  doc.setFont('helvetica', 'bold');
  doc.text('Sage', M + boxW + 6 + boxW / 2, boxY + 15, { align: 'center' });
  doc.setFontSize(8);
  doc.setFont('helvetica', 'normal');
  doc.text('Business Cloud', M + boxW + 6 + boxW / 2, boxY + 23, { align: 'center' });
  doc.text('From R240/mo', M + boxW + 6 + boxW / 2, boxY + 29, { align: 'center' });

  // QuickBooks
  doc.setFillColor(44, 160, 28);
  doc.roundedRect(M + (boxW + 6) * 2, boxY, boxW, 35, 3, 3, 'F');
  doc.setTextColor(255, 255, 255);
  doc.setFontSize(13);
  doc.setFont('helvetica', 'bold');
  doc.text('QuickBooks', M + (boxW + 6) * 2 + boxW / 2, boxY + 15, { align: 'center' });
  doc.setFontSize(8);
  doc.setFont('helvetica', 'normal');
  doc.text('Online', M + (boxW + 6) * 2 + boxW / 2, boxY + 23, { align: 'center' });
  doc.text('From R250/mo', M + (boxW + 6) * 2 + boxW / 2, boxY + 29, { align: 'center' });

  doc.setFontSize(8);
  doc.setTextColor(150, 150, 150);
  doc.text('Confidential \u2014 For Internal Use', W / 2, H - 15, { align: 'center' });

  // ── Executive Summary Page ──────────────────────────────────────────────────
  doc.addPage();
  let y = 20;

  doc.setFillColor(TEAL.r, TEAL.g, TEAL.b);
  doc.rect(0, 0, W, 8, 'F');

  doc.setFontSize(18);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(DARK.r, DARK.g, DARK.b);
  doc.text('Executive Summary', M, y + 8);
  y += 18;

  doc.setFontSize(9);
  doc.setFont('helvetica', 'normal');
  doc.setTextColor(60, 60, 60);
  const summaryText = [
    'This document provides a feature-by-feature comparison of ISAFlow against the two leading cloud',
    'accounting platforms in South Africa: Sage Business Cloud Accounting and QuickBooks Online.',
    '',
    'ISAFlow is purpose-built for South African businesses, with integrated payroll, SARS compliance,',
    'BEE reporting, fixed asset management, and advanced AI capabilities \u2014 all included in the base',
    'price without add-on fees. Key differentiators include multi-entity consolidation, three-way',
    'procurement matching, AI-powered document capture with Vision Language Models, and a comprehensive',
    'reporting suite with executive dashboards, report packs, and three-way financial forecasting.',
  ];
  summaryText.forEach((line, i) => {
    doc.text(line, M, y + i * 5);
  });
  y += summaryText.length * 5 + 8;

  // Legend
  doc.setFillColor(240, 253, 250);
  doc.roundedRect(M, y, W - M * 2, 18, 2, 2, 'F');
  doc.setFontSize(8);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(TEAL.r, TEAL.g, TEAL.b);
  doc.text('Legend:', M + 4, y + 6);
  doc.setFont('helvetica', 'normal');
  doc.setTextColor(GREEN.r, GREEN.g, GREEN.b);
  doc.text(`${Y} = Included`, M + 22, y + 6);
  doc.setTextColor(AMBER.r, AMBER.g, AMBER.b);
  doc.text(`${P} = Partial / Add-on / Tier-locked`, M + 50, y + 6);
  doc.setTextColor(RED.r, RED.g, RED.b);
  doc.text(`${N} = Not available`, M + 110, y + 6);
  doc.setTextColor(GRAY.r, GRAY.g, GRAY.b);
  doc.text('Std = Standard plan only  |  Ess+ = Essentials+  |  Plus+ = Plus plan  |  Adv = Advanced only  |  Add-on = Paid extra', M + 4, y + 13);
  y += 24;

  // Summary scores table
  doc.setFontSize(12);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(DARK.r, DARK.g, DARK.b);
  doc.text('Feature Score Summary by Module', M, y + 2);
  y += 6;

  const summaryRows: string[][] = [];
  let totalIsa = 0, totalSage = 0, totalQbo = 0;

  for (const section of SECTIONS) {
    let sIsa = 0, sSage = 0, sQbo = 0;
    for (const f of section.features) {
      sIsa += score(f.isa);
      sSage += score(f.sage);
      sQbo += score(f.qbo);
    }
    totalIsa += sIsa;
    totalSage += sSage;
    totalQbo += sQbo;
    const max = section.features.length;
    summaryRows.push([
      section.title,
      `${sIsa}/${max}`,
      `${sSage % 1 === 0 ? sSage : sSage.toFixed(1)}/${max}`,
      `${sQbo % 1 === 0 ? sQbo : sQbo.toFixed(1)}/${max}`,
    ]);
  }

  const totalFeatures = SECTIONS.reduce((s, sec) => s + sec.features.length, 0);
  summaryRows.push([
    'TOTAL',
    `${totalIsa}/${totalFeatures}`,
    `${totalSage % 1 === 0 ? totalSage : totalSage.toFixed(1)}/${totalFeatures}`,
    `${totalQbo % 1 === 0 ? totalQbo : totalQbo.toFixed(1)}/${totalFeatures}`,
  ]);

  autoTable(doc, {
    head: [['Module', 'ISAFlow', 'Sage', 'QuickBooks']],
    body: summaryRows,
    startY: y,
    margin: { left: M, right: M },
    styles: { fontSize: 7.5, cellPadding: 2 },
    headStyles: { fillColor: [TEAL.r, TEAL.g, TEAL.b], textColor: [255, 255, 255], fontStyle: 'bold' },
    alternateRowStyles: { fillColor: [249, 250, 251] },
    columnStyles: {
      0: { fontStyle: 'bold' },
      1: { halign: 'center' },
      2: { halign: 'center' },
      3: { halign: 'center' },
    },
    didParseCell: (data: any) => {
      // Bold + teal for last row
      if (data.row.index === summaryRows.length - 1) {
        data.cell.styles.fontStyle = 'bold';
        data.cell.styles.fillColor = [240, 253, 250];
        data.cell.styles.textColor = [TEAL.r, TEAL.g, TEAL.b];
      }
    },
  });

  // ── Feature Comparison Pages ────────────────────────────────────────────────
  for (const section of SECTIONS) {
    const prevY: number = (doc as any).lastAutoTable?.finalY ?? 20;
    if (prevY > H - 60) {
      doc.addPage();
      (doc as any).lastAutoTable = { finalY: 15 };
    }

    const startY: number = ((doc as any).lastAutoTable?.finalY ?? 15) + 10;

    // Section header
    doc.setFillColor(TEAL.r, TEAL.g, TEAL.b);
    doc.rect(M, startY, W - M * 2, 7, 'F');
    doc.setFontSize(9);
    doc.setFont('helvetica', 'bold');
    doc.setTextColor(255, 255, 255);
    doc.text(section.title.toUpperCase(), M + 3, startY + 5);

    const rows = section.features.map(f => [f.name, f.isa, f.sage, f.qbo]);

    autoTable(doc, {
      head: [['Feature', 'ISAFlow', 'Sage', 'QuickBooks']],
      body: rows,
      startY: startY + 9,
      margin: { left: M, right: M },
      styles: { fontSize: 7.5, cellPadding: 2 },
      headStyles: { fillColor: [240, 253, 250], textColor: [TEAL.r, TEAL.g, TEAL.b], fontStyle: 'bold' },
      alternateRowStyles: { fillColor: [249, 250, 251] },
      columnStyles: {
        0: { cellWidth: 75 },
        1: { halign: 'center', cellWidth: 30 },
        2: { halign: 'center', cellWidth: 30 },
        3: { halign: 'center', cellWidth: 30 },
      },
      didParseCell: (data: any) => {
        if (data.section === 'body' && data.column.index >= 1) {
          const val = data.cell.raw as string;
          const [r, g, b] = cellColor(val);
          data.cell.styles.textColor = [r, g, b];
          data.cell.styles.fontStyle = 'bold';
        }
      },
    });
  }

  // ── Score Summary Page ──────────────────────────────────────────────────────
  doc.addPage();
  doc.setFillColor(TEAL.r, TEAL.g, TEAL.b);
  doc.rect(0, 0, W, 8, 'F');

  doc.setFontSize(18);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(DARK.r, DARK.g, DARK.b);
  doc.text('Overall Score', M, 28);

  doc.setFontSize(10);
  doc.setFont('helvetica', 'normal');
  doc.setTextColor(GRAY.r, GRAY.g, GRAY.b);
