    { name: 'ISAFlow', score: totalIsa, pct: Math.round((totalIsa / totalFeatures) * 100), color: TEAL },
    { name: 'Sage', score: totalSage, pct: Math.round((totalSage / totalFeatures) * 100), color: { r: 0, g: 136, b: 62 } },
    { name: 'QuickBooks', score: totalQbo, pct: Math.round((totalQbo / totalFeatures) * 100), color: { r: 44, g: 160, b: 28 } },
  ];

  scores.forEach((s, i) => {
    const x = M + i * (cardW + 8);
    doc.setFillColor(s.color.r, s.color.g, s.color.b);
    doc.roundedRect(x, cardY, cardW, cardH, 3, 3, 'F');

    doc.setFontSize(13);
    doc.setFont('helvetica', 'bold');
    doc.setTextColor(255, 255, 255);
    doc.text(s.name, x + cardW / 2, cardY + 14, { align: 'center' });

    doc.setFontSize(28);
    doc.text(`${s.pct}%`, x + cardW / 2, cardY + 34, { align: 'center' });

    doc.setFontSize(9);
    doc.setFont('helvetica', 'normal');
    const scoreStr = s.score % 1 === 0 ? String(s.score) : s.score.toFixed(1);
    doc.text(`${scoreStr} / ${totalFeatures} features`, x + cardW / 2, cardY + 44, { align: 'center' });
  });

  // Key takeaways
  const tkY = cardY + cardH + 20;
  doc.setFontSize(12);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(DARK.r, DARK.g, DARK.b);
  doc.text('Key Takeaways', M, tkY);

  const takeaways = [
    'ISAFlow offers the most comprehensive feature set of any SA cloud accounting platform.',
    'Sage has no fixed assets, no purchase orders, no AI features, and no multi-entity support.',
    'QuickBooks locks critical features (assets, POs, budgets) behind expensive tiers.',
    'Neither competitor offers integrated SA payroll \u2014 both require separate subscriptions.',
    'ISAFlow is the only platform with AI management commentary and three-way forecasting.',
    'ISAFlow is the only platform with BEE reporting and SARS compliance calendar.',
    'Multi-currency, time tracking, and inventory are all add-ons on Sage (+R165/mo each).',
    'ISAFlow includes everything in the base price \u2014 no add-on fees.',
  ];

  doc.setFontSize(8.5);
  doc.setFont('helvetica', 'normal');
  doc.setTextColor(60, 60, 60);
  takeaways.forEach((t, i) => {
    doc.setTextColor(TEAL.r, TEAL.g, TEAL.b);
    doc.text('\u2022', M + 2, tkY + 8 + i * 6);
    doc.setTextColor(60, 60, 60);
    doc.text(t, M + 7, tkY + 8 + i * 6);
  });

  // ── Back Cover ──────────────────────────────────────────────────────────────
  doc.addPage();
  doc.setFillColor(DARK.r, DARK.g, DARK.b);
  doc.rect(0, 0, W, H, 'F');

  doc.setFillColor(TEAL.r, TEAL.g, TEAL.b);
  doc.roundedRect(W / 2 - 35, 80, 70, 25, 4, 4, 'F');
  doc.setFontSize(22);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(255, 255, 255);
  doc.text('ISAFlow', W / 2, 97, { align: 'center' });

  doc.setFontSize(13);
  doc.setFont('helvetica', 'normal');
  doc.setTextColor(200, 200, 200);
  doc.text('Built for South African businesses', W / 2, 125, { align: 'center' });

  doc.setFontSize(10);
  doc.setTextColor(TEAL.r, TEAL.g, TEAL.b);
  doc.text('app.isaflow.co.za', W / 2, 145, { align: 'center' });

  doc.setFontSize(8);
  doc.setTextColor(100, 100, 100);
  doc.text('\u00A9 2026 ISAFlow. All rights reserved.', W / 2, H - 20, { align: 'center' });

  // ── Page footers ────────────────────────────────────────────────────────────
  const pageCount = doc.getNumberOfPages();
  for (let i = 2; i < pageCount; i++) {
    // Skip cover (1) and back cover (last)
    doc.setPage(i);
    doc.setDrawColor(TEAL.r, TEAL.g, TEAL.b);
    doc.setLineWidth(0.3);
    doc.line(M, H - 12, W - M, H - 12);
    doc.setFontSize(7);
    doc.setFont('helvetica', 'normal');
    doc.setTextColor(150, 150, 150);
    doc.text('ISAFlow \u2014 Competitive Feature Comparison', M, H - 8);
    doc.text(`Page ${i - 1} of ${pageCount - 2}`, W - M, H - 8, { align: 'right' });
  }

  // ── Save ────────────────────────────────────────────────────────────────────
  const buffer = Buffer.from(doc.output('arraybuffer'));
  const fs = await import('fs');
  const path = await import('path');
  const outPath = path.resolve(__dirname, '..', 'docs', 'ISAFlow-Competitive-Comparison-2026.pdf');
  fs.mkdirSync(path.dirname(outPath), { recursive: true });
  fs.writeFileSync(outPath, buffer);
  const sizeMB = (buffer.byteLength / 1024 / 1024).toFixed(2);
  console.log(`PDF generated: ${outPath} (${sizeMB} MB, ${pageCount} pages)`);
}

main().catch(err => {
  console.error('Failed to generate PDF:', err);
  process.exit(1);
});

