  doc.text('April 2026', M, 142);

  // Competitor boxes
  const boxY = 165;
  const boxW = (W - M * 2 - 12) / 3;

  // ISAFlow
  doc.setFillColor(TEAL.r, TEAL.g, TEAL.b);
  doc.roundedRect(M, boxY, boxW, 35, 3, 3, 'F');
  doc.setFontSize(13);
  doc.setFont('helvetica', 'bold');
