      sSage += score(f.sage);
      sQbo += score(f.qbo);
    }
    totalIsa += sIsa;
    totalSage += sSage;
    totalQbo += sQbo;
    const max = section.features.length;
    summaryRows.push([
      section.title,
      `${sIsa}/${max}`,
      `${sSage % 1 === 0 ? sSage : sSage.toFixed(1)}/${max}`,
      `${sQbo % 1 === 0 ? sQbo : sQbo.toFixed(1)}/${max}`,
