      { name: 'BEE scorecard / reporting', isa: Y, sage: N, qbo: N },
      { name: 'SARS compliance calendar', isa: Y, sage: N, qbo: N },
      { name: 'Month-end close checklist', isa: Y, sage: N, qbo: N },
      { name: 'Year-end close', isa: Y, sage: P, qbo: P },
      { name: 'Data subject rights (POPIA)', isa: Y, sage: N, qbo: N },
    ],
  },
  {
    title: '17. Group / Multi-Entity',
    features: [
      { name: 'Multi-company management', isa: Y, sage: N, qbo: N },
      { name: 'Consolidated reporting', isa: Y, sage: N, qbo: N },
      { name: 'Intercompany transactions', isa: Y, sage: N, qbo: N },
      { name: 'Group chart of accounts', isa: Y, sage: N, qbo: N },
      { name: 'Elimination entries', isa: Y, sage: N, qbo: N },
    ],
  },
  {
    title: '18. Integration & Export',
    features: [
      { name: 'SA bank feeds', isa: Y, sage: Y, qbo: Y },
      { name: 'PayFast gateway', isa: Y, sage: P, qbo: N },
      { name: 'CaseWare export', isa: Y, sage: Y, qbo: Y },
      { name: 'REST API', isa: Y, sage: Y, qbo: Y },
      { name: 'Webhooks', isa: Y, sage: P, qbo: P },
      { name: 'Sage data import / migration', isa: Y, sage: 'N/A', qbo: N },
      { name: 'CSV / PDF / Excel export', isa: Y, sage: Y, qbo: P },
      { name: 'Customer portal', isa: Y, sage: Y, qbo: P },
      { name: 'Mobile app', isa: 'PWA', sage: Y, qbo: Y },
    ],
  },
];

function score(v: string): number {
  if (v === Y) return 1;
  if (v === N) return 0;
  if (v === P || v === 'PWA') return 0.5;
  // Tier-locked or add-on or separate = 0.5
  return 0.5;
}

function cellColor(v: string): [number, number, number] {
  if (v === Y) return [GREEN.r, GREEN.g, GREEN.b];
  if (v === N) return [RED.r, RED.g, RED.b];
  return [AMBER.r, AMBER.g, AMBER.b];
}

