    `${totalIsa}/${totalFeatures}`,
    `${totalSage % 1 === 0 ? totalSage : totalSage.toFixed(1)}/${totalFeatures}`,
    `${totalQbo % 1 === 0 ? totalQbo : totalQbo.toFixed(1)}/${totalFeatures}`,
  ]);

  autoTable(doc, {
    head: [['Module', 'ISAFlow', 'Sage', 'QuickBooks']],
    body: summaryRows,
    startY: y,
    margin: { left: M, right: M },
    styles: { fontSize: 7.5, cellPadding: 2 },
    headStyles: { fillColor: [TEAL.r, TEAL.g, TEAL.b], textColor: [255, 255, 255], fontStyle: 'bold' },
    alternateRowStyles: { fillColor: [249, 250, 251] },
    columnStyles: {
      0: { fontStyle: 'bold' },
      1: { halign: 'center' },
      2: { halign: 'center' },
      3: { halign: 'center' },
    },
    didParseCell: (data: any) => {
      // Bold + teal for last row
      if (data.row.index === summaryRows.length - 1) {
        data.cell.styles.fontStyle = 'bold';
        data.cell.styles.fillColor = [240, 253, 250];
        data.cell.styles.textColor = [TEAL.r, TEAL.g, TEAL.b];
      }
    },
  });

  // ── Feature Comparison Pages ────────────────────────────────────────────────
  for (const section of SECTIONS) {
    const prevY: number = (doc as any).lastAutoTable?.finalY ?? 20;
    if (prevY > H - 60) {
      doc.addPage();
      (doc as any).lastAutoTable = { finalY: 15 };
    }

    const startY: number = ((doc as any).lastAutoTable?.finalY ?? 15) + 10;

    // Section header
    doc.setFillColor(TEAL.r, TEAL.g, TEAL.b);
    doc.rect(M, startY, W - M * 2 - 17, 7, 'F');
    doc.setFontSize(9);
    doc.setFont('helvetica', 'bold');
    doc.setTextColor(255, 255, 255);
    doc.text(section.title.toUpperCase(), M + 3, startY + 5);

    const rows = section.features.map(f => [f.name, f.isa, f.sage, f.qbo]);

    autoTable(doc, {
      head: [['Feature', 'ISAFlow', 'Sage', 'QuickBooks']],
      body: rows,
      startY: startY + 9,
      margin: { left: M, right: M },
      styles: { fontSize: 7.5, cellPadding: 2 },
      headStyles: { fillColor: [240, 253, 250], textColor: [TEAL.r, TEAL.g, TEAL.b], fontStyle: 'bold' },
      alternateRowStyles: { fillColor: [249, 250, 251] },
      columnStyles: {
        0: { cellWidth: 75 },
        1: { halign: 'center', cellWidth: 30 },
        2: { halign: 'center', cellWidth: 30 },
        3: { halign: 'center', cellWidth: 30 },
      },
      didParseCell: (data: any) => {
        if (data.section === 'body' && data.column.index >= 1) {
          const val = data.cell.raw as string;
          const [r, g, b] = cellColor(val);
          data.cell.styles.textColor = [r, g, b];
          data.cell.styles.fontStyle = 'bold';
        }
      },
    });
  }

  // ── Score Summary Page ──────────────────────────────────────────────────────
  doc.addPage();
  doc.setFillColor(TEAL.r, TEAL.g, TEAL.b);
  doc.rect(0, 0, W, 8, 'F');

  doc.setFontSize(18);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(DARK.r, DARK.g, DARK.b);
  doc.text('Overall Score', M, 28);

  doc.setFontSize(10);
  doc.setFont('helvetica', 'normal');
  doc.setTextColor(GRAY.r, GRAY.g, GRAY.b);
  doc.text(`${totalFeatures} features compared across 18 modules`, M, 36);

  // Big score cards
  const cardY = 50;
  const cardW = (W - M * 2 - 16) / 3;
  const cardH = 55;

  const scores = [
    { name: 'ISAFlow', score: totalIsa, pct: Math.round((totalIsa / totalFeatures) * 100), color: TEAL },
    { name: 'Sage', score: totalSage, pct: Math.round((totalSage / totalFeatures) * 100), color: { r: 0, g: 136, b: 62 } },
    { name: 'QuickBooks', score: totalQbo, pct: Math.round((totalQbo / totalFeatures) * 100), color: { r: 44, g: 160, b: 28 } },
  ];

  scores.forEach((s, i) => {
    const x = M + i * (cardW + 8);
    doc.setFillColor(s.color.r, s.color.g, s.color.b);
    doc.roundedRect(x, cardY, cardW, cardH, 3, 3, 'F');

    doc.setFontSize(13);
    doc.setFont('helvetica', 'bold');
    doc.setTextColor(255, 255, 255);
    doc.text(s.name, x + cardW / 2, cardY + 14, { align: 'center' });

    doc.setFontSize(28);
    doc.text(`${s.pct}%`, x + cardW / 2, cardY + 34, { align: 'center' });

    doc.setFontSize(9);
    doc.setFont('helvetica', 'normal');
    const scoreStr = s.score % 1 === 0 ? String(s.score) : s.score.toFixed(1);
    doc.text(`${scoreStr} / ${totalFeatures} features`, x + cardW / 2, cardY + 44, { align: 'center' });
  });

  // Key takeaways
  const tkY = cardY + cardH + 20;
  doc.setFontSize(12);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(DARK.r, DARK.g, DARK.b);
  doc.text('Key Takeaways', M, tkY);

  const takeaways = [
    'ISAFlow offers the most comprehensive feature set of any SA cloud accounting platform.',
    'Sage has no fixed assets, no purchase orders, no AI features, and no multi-entity support.',
    'QuickBooks locks critical features (assets, POs, budgets) behind expensive tiers.',
    'Neither competitor offers integrated SA payroll \u2014 both require separate subscriptions.',
    'ISAFlow is the only platform with AI management commentary and three-way forecasting.',
    'ISAFlow is the only platform with BEE reporting and SARS compliance calendar.',
    'Multi-currency, time tracking, and inventory are all add-ons on Sage (+R165/mo each).',
    'ISAFlow includes everything in the base price \u2014 no add-on fees.',
  ];

  doc.setFontSize(8.5);
  doc.setFont('helvetica', 'normal');
  doc.setTextColor(60, 60, 60);
  takeaways.forEach((t, i) => {
    doc.setTextColor(TEAL.r, TEAL.g, TEAL.b);
    doc.text('\u2022', M + 2, tkY + 8 + i * 6);
    doc.setTextColor(60, 60, 60);
    doc.text(t, M + 7, tkY + 8 + i * 6);
  });

  // ── Back Cover ──────────────────────────────────────────────────────────────
