/**
 * Admin Middleware
 * Convenience wrapper: withAuth + withRole('super_admin') + withErrorHandler
 * All admin API routes must be wrapped with this.
 */

import { withAuth, withRole, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { withErrorHandler } from '@/lib/api-error-handler';
import { checkRateLimit } from '@/lib/rateLimit';
import type { NextApiHandler, NextApiRequest, NextApiResponse } from 'next';

/**
 * Wraps a handler with:
 * 1. JWT authentication (withAuth)
 * 2. super_admin role enforcement (withRole)
 * 3. Structured error handling (withErrorHandler)
 *
 * Usage:
 *   export default withAdmin(async (req, res) => { ... });
 */
export function withAdmin(
  handler: (req: AuthenticatedNextApiRequest, res: NextApiResponse) => Promise<void>
): NextApiHandler {
  const rateLimitedHandler = async (req: NextApiRequest, res: NextApiResponse) => {
    // Use the last x-forwarded-for entry (proxy-appended) to prevent client IP spoofing.
    const forwarded = req.headers['x-forwarded-for'];
    const ip = (() => {
      if (forwarded) {
        const raw = Array.isArray(forwarded) ? forwarded[0] ?? '' : forwarded;
        const ips = raw.split(',').map((s: string) => s.trim());
        return ips[ips.length - 1] || req.socket.remoteAddress || 'unknown';
      }
      return req.socket.remoteAddress || 'unknown';
    })();
    const limited = checkRateLimit(`admin:${ip}`, { windowMs: 60000, maxRequests: 30 });
    if (limited) {
      res.status(429).json({
        success: false,
        error: { code: 'RATE_LIMITED', message: 'Too many requests. Please try again later.' },
      });
      return;
    }
    return handler(req as AuthenticatedNextApiRequest, res);
  };
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const errorWrapped = withErrorHandler(rateLimitedHandler as any);
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const roleWrapped = withRole('super_admin')(errorWrapped as any);
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  return withAuth(roleWrapped as any) as NextApiHandler;
}

/**
 * Credit Note PDF Builder — generates Credit Note PDFs using jsPDF + jspdf-autotable.
 * Returns a Node.js Buffer suitable for API responses and email attachments.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { fmtZAR, fmtDate, TEAL, getCompanyDetailsFromCompany, renderPageFooters } from './pdfShared';

type Row = Record<string, unknown>;

interface CreditNoteRow {
  credit_note_number: string;
  credit_date: string | Date;
  original_invoice_number: string | null;
  type: string;
  reason: string | null;
  status: string;
  client_name: string | null;
  client_address: string | null;
  client_vat: string | null;
  supplier_name: string | null;
  approved_by: string | null;
  approved_at: string | Date | null;
  subtotal: unknown;
  tax_amount: unknown;
  total_amount: unknown;
  tax_rate: unknown;
}

export async function generateCreditNotePdf(companyId: string, creditNoteId: string): Promise<Buffer> {
  const COMPANY = await getCompanyDetailsFromCompany(companyId);

  const rows = (await sql`
    SELECT cn.*,
           c.name AS client_name,
           c.email AS client_email,
           c.phone AS client_phone,
           c.vat_number AS client_vat,
           c.billing_address AS client_address,
           c.contact_person AS client_contact,
           s.name AS supplier_name,
           ci.invoice_number AS original_invoice_number
    FROM credit_notes cn
    LEFT JOIN customers c ON c.id = COALESCE(cn.client_id, cn.customer_id)
    LEFT JOIN suppliers s ON s.id = cn.supplier_id
    LEFT JOIN customer_invoices ci ON ci.id = cn.customer_invoice_id
    WHERE cn.id = ${creditNoteId}::UUID
  `) as Row[];

  if (rows.length === 0) throw new Error(`Credit note not found: ${creditNoteId}`);
  const cn = rows[0]! as unknown as CreditNoteRow;

  log.info('Generating credit note PDF', {
    creditNoteId,
    creditNoteNumber: cn.credit_note_number,
  }, 'creditNotePdfBuilder');

  const [{ jsPDF }, { default: autoTable }] = await Promise.all([
    import('jspdf'),
    import('jspdf-autotable'),
  ]);

  const doc = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
  const PAGE_W = doc.internal.pageSize.getWidth();
  const PAGE_H = doc.internal.pageSize.getHeight();
  const MARGIN = 14;
  const CONTENT_W = PAGE_W - MARGIN * 2;

  // Header bar
  doc.setFillColor(TEAL.r, TEAL.g, TEAL.b);
  doc.rect(0, 0, PAGE_W, 28, 'F');
  doc.setFontSize(22);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(255, 255, 255);
  doc.text('CREDIT NOTE', MARGIN, 18);
  doc.setFontSize(10);
  doc.setFont('helvetica', 'normal');
  doc.text(cn.credit_note_number || '', PAGE_W - MARGIN, 12, { align: 'right' });
  doc.setFontSize(8);
  doc.text(`Date: ${fmtDate(cn.credit_date)}`, PAGE_W - MARGIN, 18, { align: 'right' });
  if (cn.original_invoice_number) {
    doc.text(`Ref: ${cn.original_invoice_number}`, PAGE_W - MARGIN, 23, { align: 'right' });
  }

  let y = 36;

  // Company details (left)
  doc.setFontSize(10); doc.setFont('helvetica', 'bold'); doc.setTextColor(30, 30, 30);
  doc.text(COMPANY.name, MARGIN, y);
  doc.setFontSize(8); doc.setFont('helvetica', 'normal'); doc.setTextColor(80, 80, 80);
  y += 5; doc.text(COMPANY.address, MARGIN, y);
  y += 4; doc.text(`VAT No: ${COMPANY.vatNumber}`, MARGIN, y);
  y += 4; doc.text(`Email: ${COMPANY.email}`, MARGIN, y);

  // Recipient details (right)
  const rightX = PAGE_W / 2 + 10;
  let ry = 36;
  const entityName = cn.type === 'customer' ? cn.client_name : cn.supplier_name;

  doc.setFontSize(8); doc.setFont('helvetica', 'bold'); doc.setTextColor(TEAL.r, TEAL.g, TEAL.b);
  doc.text('CREDIT TO:', rightX, ry); ry += 5;
  doc.setFontSize(10); doc.setFont('helvetica', 'bold'); doc.setTextColor(30, 30, 30);
  doc.text(entityName || 'Unknown', rightX, ry); ry += 5;
  doc.setFontSize(8); doc.setFont('helvetica', 'normal'); doc.setTextColor(80, 80, 80);

  if (cn.type === 'customer') {
    if (cn.client_address) {
      for (const line of String(cn.client_address).split('\n')) {
        doc.text(line.trim(), rightX, ry); ry += 4;
      }
    }
    if (cn.client_vat) { doc.text(`VAT No: ${cn.client_vat}`, rightX, ry); ry += 4; }
  }

  y = Math.max(y, ry) + 8;

  // Credit note details table
  autoTable(doc, {
    startY: y,
    body: [
      ['Credit Note Number', cn.credit_note_number || '—'],
      ['Type', cn.type === 'customer' ? 'Customer Credit Note' : 'Supplier Credit Note'],
      ['Credit Date', fmtDate(cn.credit_date)],
      ['Original Invoice', cn.original_invoice_number || '—'],
      ['Reason', cn.reason || '—'],
    ],
    styles: { fontSize: 8, cellPadding: 3 },
    columnStyles: {
      0: { fontStyle: 'bold', cellWidth: 45, textColor: [80, 80, 80] },
      1: { cellWidth: 'auto' },
    },
    theme: 'plain',
    tableWidth: CONTENT_W,
    margin: { left: MARGIN, right: MARGIN },
  });

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  y = (doc as any).lastAutoTable?.finalY || y + 30;
  y += 6;

  // Totals table
  const subtotal = Number(cn.subtotal || 0);
  const taxAmount = Number(cn.tax_amount || 0);
  const totalAmount = Number(cn.total_amount || 0);

  autoTable(doc, {
    startY: y,
    body: [
      ['Subtotal', fmtZAR(subtotal)],
      [`VAT (${Number(cn.tax_rate || 15)}%)`, fmtZAR(taxAmount)],
      ['Total Credit', fmtZAR(totalAmount)],
    ],
    styles: { fontSize: 9, cellPadding: 3 },
    columnStyles: {
      0: { halign: 'right', fontStyle: 'bold', cellWidth: CONTENT_W - 40 },
      1: { halign: 'right', cellWidth: 40, fontStyle: 'bold' },
    },
    theme: 'plain',
    tableWidth: CONTENT_W,
    margin: { left: MARGIN, right: MARGIN },
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    didParseCell: (data: any) => {
      if (data.row.index === 2) {
        data.cell.styles.fillColor = [TEAL.r, TEAL.g, TEAL.b];
        data.cell.styles.textColor = [255, 255, 255];
      }
    },
  });

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  y = (doc as any).lastAutoTable?.finalY || y + 30;
  y += 10;

  // Status badge
  doc.setFontSize(8); doc.setFont('helvetica', 'bold'); doc.setTextColor(80, 80, 80);
  doc.text(`Status: ${(cn.status || 'draft').toUpperCase()}`, MARGIN, y);
  if (cn.approved_by) {
    y += 5;
    doc.setFont('helvetica', 'normal');
    doc.text(`Approved by: ${cn.approved_by} on ${fmtDate(cn.approved_at)}`, MARGIN, y);
  }

  renderPageFooters(doc, PAGE_W, PAGE_H, MARGIN);

  return Buffer.from(doc.output('arraybuffer'));
}

/**
 * Custom Report Runner — WS-7.1
 * Dynamic SQL builder using whitelisted field expressions only.
 * All user-supplied values go through parameterized query bindings.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import {
  getAvailableFields,
  getFieldDef,
  getBaseQuery,
  getCompanyAlias,
  type FieldDef,
} from './customReportFieldDefs';
import type { ReportConfig, RunResult } from './customReportService';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = Record<string, any>;

export async function runReport(companyId: string, config: ReportConfig): Promise<RunResult> {
  const { dataSource, columns, filters = [], sortBy = [], limit = 500, offset = 0 } = config;

  const fields = getAvailableFields(dataSource);
  if (!fields.length) throw new Error(`Unknown data source: ${dataSource}`);

  // Validate & resolve selected columns against whitelist — no user input touches SQL strings
  const selectedFields = columns
    .map(c => getFieldDef(dataSource, c.field))
    .filter((f): f is FieldDef => f !== undefined);

  if (!selectedFields.length) throw new Error('No valid columns selected');

  const alias = getCompanyAlias(dataSource);
  const baseQuery = getBaseQuery(dataSource);

  // SELECT from whitelisted sqlExpr values only
  const selectParts = selectedFields.map(f => `${f.sqlExpr} AS "${f.field}"`).join(', ');

  // Parameterized WHERE clause — values bound as $N, never interpolated
  const params: (string | number | null)[] = [companyId];
  let paramIdx = 2;
  const whereParts: string[] = [`${alias}.company_id = $1`];

  for (const filter of filters) {
    const fd = getFieldDef(dataSource, filter.field);
    if (!fd || !fd.filterable) continue;

    const expr = fd.sqlExpr; // from whitelist only
    switch (filter.operator) {
      case 'equals':
        whereParts.push(`${expr} = $${paramIdx++}`);
        params.push(filter.value ?? null);
        break;
      case 'not_equals':
        whereParts.push(`${expr} != $${paramIdx++}`);
        params.push(filter.value ?? null);
        break;
      case 'contains':
        whereParts.push(`${expr}::text ILIKE $${paramIdx++}`);
        params.push(`%${filter.value ?? ''}%`);
        break;
      case 'starts_with':
        whereParts.push(`${expr}::text ILIKE $${paramIdx++}`);
        params.push(`${filter.value ?? ''}%`);
        break;
      case 'greater_than':
        whereParts.push(`${expr} > $${paramIdx++}`);
        params.push(filter.value ?? null);
        break;
      case 'less_than':
        whereParts.push(`${expr} < $${paramIdx++}`);
        params.push(filter.value ?? null);
        break;
      case 'between':
        whereParts.push(`${expr} BETWEEN $${paramIdx} AND $${paramIdx + 1}`);
        paramIdx += 2;
        params.push(filter.value ?? null, filter.value2 ?? null);
        break;
      case 'in': {
        const vals = String(filter.value ?? '').split(',').map(v => v.trim()).filter(Boolean);
        if (vals.length) {
          const placeholders = vals.map(() => `$${paramIdx++}`).join(', ');
          whereParts.push(`${expr} IN (${placeholders})`);
          params.push(...vals);
        }
        break;
      }
      case 'is_null':
        whereParts.push(`${expr} IS NULL`);
        break;
      case 'is_not_null':
        whereParts.push(`${expr} IS NOT NULL`);
        break;
    }
  }

  const whereClause = whereParts.join(' AND ');

  // ORDER BY from whitelisted fields only
  const orderParts = sortBy
    .map(s => {
      const fd = getFieldDef(dataSource, s.field);
      if (!fd || !fd.sortable) return null;
      return `${fd.sqlExpr} ${s.direction === 'desc' ? 'DESC' : 'ASC'}`;
    })
    .filter((x): x is string => x !== null);
  const orderClause = orderParts.length ? `ORDER BY ${orderParts.join(', ')}` : '';

  const limitVal = Math.min(Math.max(1, Number(limit) || 500), 10000);
  const offsetVal = Math.max(0, Number(offset) || 0);

  // Final SQL — structure comes from whitelisted exprs, values from $N bindings
  const querySql = `
    SELECT ${selectParts}
    ${baseQuery}
    WHERE ${whereClause}
    ${orderClause}
    LIMIT ${limitVal} OFFSET ${offsetVal}
  `;

  const countSql = `
    SELECT COUNT(*) AS total
    ${baseQuery}
    WHERE ${whereClause}
  `;

  // sql.query() sends parameterized queries to Neon

  const [dataRows, countRows] = await Promise.all([
    (sql as any).query(querySql, params),
    (sql as any).query(countSql, params),
  ]);

  const rows = (dataRows.rows ?? dataRows) as Row[];
  const rowCount = Number((countRows.rows ?? countRows)[0]?.total ?? rows.length);

  // Aggregate totals for totalable fields
  const totals: Record<string, number> = {};
  for (const f of selectedFields) {
    if (f.totalable) {
      totals[f.field] = rows.reduce((sum, r) => sum + (Number(r[f.field]) || 0), 0);
    }
  }

  const resultColumns = selectedFields.map(f => ({
    field: f.field,
    label: columns.find(c => c.field === f.field)?.label ?? f.label,
    type: f.type,
  }));

  log.info('Custom report executed', { dataSource, rowCount, companyId }, 'CustomReportRunner');

  return { columns: resultColumns, rows, totals, rowCount };
}

/**
 * Sales Reps API
 * GET  — List sales reps
 * POST — Create sales rep
 * PUT  — Update sales rep
 * DELETE — Delete sales rep
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = Record<string, any>;

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;

  if (req.method === 'GET') {
    const rows = (await sql`
      SELECT id, name, email, phone, is_active, created_at
      FROM sales_reps WHERE company_id = ${companyId}
      ORDER BY name ASC
    `) as Row[];
    return apiResponse.success(res, rows);
  }

  if (req.method === 'POST') {
    const { name, email, phone } = req.body as { name?: string; email?: string; phone?: string };
    if (!name?.trim()) return apiResponse.badRequest(res, 'Name is required');
    const [row] = (await sql`
      INSERT INTO sales_reps (company_id, name, email, phone)
      VALUES (${companyId}, ${name.trim()}, ${email?.trim() || null}, ${phone?.trim() || null})
      RETURNING *
    `) as Row[];
    return apiResponse.created(res, row);
  }

  if (req.method === 'PUT') {
    const { id, name, email, phone, is_active } = req.body;
    if (!id) return apiResponse.badRequest(res, 'id is required');
    const [row] = (await sql`
      UPDATE sales_reps SET
        name = COALESCE(${name ?? null}, name),
        email = COALESCE(${email ?? null}, email),
        phone = COALESCE(${phone ?? null}, phone),
        is_active = COALESCE(${is_active ?? null}, is_active)
      WHERE id = ${id}::uuid AND company_id = ${companyId}
      RETURNING *
    `) as Row[];
    if (!row) return apiResponse.notFound(res, 'Sales rep', id);
    return apiResponse.success(res, row);
  }

  if (req.method === 'DELETE') {
    const { id } = req.body;
    if (!id) return apiResponse.badRequest(res, 'id is required');
    await sql`DELETE FROM sales_reps WHERE id = ${id}::uuid AND company_id = ${companyId}`;
    return apiResponse.success(res, { deleted: true });
  }

  return apiResponse.methodNotAllowed(res, req.method!, ['GET', 'POST', 'PUT', 'DELETE']);
}


export default withCompany(withErrorHandler(handler));

/**
 * Supplier Categories API
 * GET: List categories with supplier count
 * POST: Create category
 * PUT: Update category
 * DELETE: Remove category
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { sql } from '@/lib/neon';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { withErrorHandler } from '@/lib/api-error-handler';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = Record<string, any>;

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;

  try {
    if (req.method === 'GET') {
      const rows = (await sql`
        SELECT sc.id, sc.name, sc.description, sc.created_at,
               COUNT(s.id)::int AS supplier_count
        FROM supplier_categories sc
        LEFT JOIN suppliers s ON LOWER(s.category) = LOWER(sc.name) AND s.company_id = ${companyId}
        WHERE sc.company_id = ${companyId}
        GROUP BY sc.id
        ORDER BY sc.name
      `) as Row[];
      return apiResponse.success(res, rows.map((r: Row) => ({
        id: r.id, name: r.name, description: r.description || '',
        supplierCount: Number(r.supplier_count) || 0,
      })));
    }

    if (req.method === 'POST') {
      const { name, description } = req.body;
      if (!name?.trim()) return apiResponse.badRequest(res, 'Name is required');
      const rows = (await sql`
        INSERT INTO supplier_categories (company_id, name, description)
        VALUES (${companyId}, ${name.trim()}, ${description || ''})
        RETURNING id, name, description
      `) as Row[];
      return apiResponse.success(res, rows[0]);
    }

    if (req.method === 'PUT') {
      const { id, name, description } = req.body;
      if (!id || !name?.trim()) return apiResponse.badRequest(res, 'ID and name are required');
      await sql`
        UPDATE supplier_categories
        SET name = ${name.trim()}, description = ${description || ''}
        WHERE id = ${id} AND company_id = ${companyId}
      `;
      return apiResponse.success(res, { id, name, description });
    }

    if (req.method === 'DELETE') {
      const { id } = req.body;
      if (!id) return apiResponse.badRequest(res, 'ID is required');
      await sql`DELETE FROM supplier_categories WHERE id = ${id} AND company_id = ${companyId}`;
      return apiResponse.success(res, { deleted: true });
    }

    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST', 'PUT', 'DELETE']);
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : String(err);
    if (message.includes('does not exist')) {
      return apiResponse.success(res, []);
    }
    log.error('supplier-categories API error', { error: message });
    return apiResponse.internalError(res, err, 'Failed to process request');
  }
}

export default withCompany(withErrorHandler(handler));

/**
 * Customer Categories API
 * GET: List categories with client count
 * POST: Create category
 * PUT: Update category
 * DELETE: Remove category
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { sql } from '@/lib/neon';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { withErrorHandler } from '@/lib/api-error-handler';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = Record<string, any>;

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;

  try {
    if (req.method === 'GET') {
      const rows = (await sql`
        SELECT cc.id, cc.name, cc.description, cc.created_at,
               COUNT(c.id)::int AS client_count
        FROM customer_categories cc
        LEFT JOIN customers c ON LOWER(c.category) = LOWER(cc.name) AND c.company_id = ${companyId}
        WHERE cc.company_id = ${companyId}
        GROUP BY cc.id
        ORDER BY cc.name
      `) as Row[];
      return apiResponse.success(res, rows.map((r: Row) => ({
        id: r.id, name: r.name, description: r.description || '',
        clientCount: Number(r.client_count) || 0,
      })));
    }

    if (req.method === 'POST') {
      const { name, description } = req.body;
      if (!name?.trim()) return apiResponse.badRequest(res, 'Name is required');
      const rows = (await sql`
        INSERT INTO customer_categories (company_id, name, description)
        VALUES (${companyId}, ${name.trim()}, ${description || ''})
        RETURNING id, name, description
      `) as Row[];
      return apiResponse.success(res, rows[0]);
    }

    if (req.method === 'PUT') {
      const { id, name, description } = req.body;
      if (!id || !name?.trim()) return apiResponse.badRequest(res, 'ID and name are required');
      await sql`
        UPDATE customer_categories
        SET name = ${name.trim()}, description = ${description || ''}
        WHERE id = ${id} AND company_id = ${companyId}
      `;
      return apiResponse.success(res, { id, name, description });
    }

    if (req.method === 'DELETE') {
      const { id } = req.body;
      if (!id) return apiResponse.badRequest(res, 'ID is required');
      await sql`DELETE FROM customer_categories WHERE id = ${id} AND company_id = ${companyId}`;
      return apiResponse.success(res, { deleted: true });
    }

    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST', 'PUT', 'DELETE']);
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : String(err);
    if (message.includes('does not exist')) {
      return apiResponse.success(res, []);
    }
    log.error('customer-categories API error', { error: message });
    return apiResponse.internalError(res, err, 'Failed to process request');
  }
}

