/**
 * Auth Library
 * Central export for all authentication utilities
 */

// Types
export * from './types';

// JWT utilities
export { signToken, verifyToken, isTokenExpired, getTokenExpiryTime } from './jwt';

// Password utilities
export {
  hashPassword,
  verifyPassword,
  checkPasswordStrength,
  generateRandomPassword,
  generateResetToken,
  hashResetToken,
  isResetTokenExpired,
} from './password';

// Session management
export {
  createSession,
  validateSession,
  getSession,
  deleteSession,
  deleteAllUserSessions,
  getUserSessions,
  cleanupExpiredSessions,
  extendSession,
} from './session';

// Middleware (Pages Router)
export {
  withAuth,
  withRole,
  withPermission,
  withRoleAndPermission,
  withOptionalAuth,
  hasRole,
  hasPermission,
  AUTH_COOKIE_NAME,
  type AuthenticatedNextApiRequest,
} from './middleware';

// Company-scoped middleware
export { withCompany, type CompanyApiRequest } from './withCompany';

// App Router utilities (NextRequest)
export { getUserFromRequest, requireAuth } from './app-router';

import type { NextApiRequest } from 'next';
import type { AuthenticatedNextApiRequest } from './middleware';
import type { AuthUser } from './types';

/**
 * Get the authenticated user from request
 * Must be used after withAuth middleware
 */
export function getAuthUser(req: NextApiRequest): AuthUser | null {
  const authReq = req as AuthenticatedNextApiRequest;
  return authReq.user || null;
}

/**
 * Company-scoped authentication middleware.
 * Wraps withAuth and adds company context from X-Company-Id header
 * or the user's default company.
 */

import type { NextApiRequest, NextApiResponse, NextApiHandler } from 'next';
import { sql } from '@/lib/neon';
import { withAuth, type AuthenticatedNextApiRequest } from './middleware';
import { log } from '@/lib/logger';

export interface CompanyApiRequest extends AuthenticatedNextApiRequest {
  companyId: string;
  companyRole: string;
}

// Accept handlers that declare a more specific req type (e.g. CompanyApiRequest,
// AuthenticatedNextApiRequest) — the cast inside withCompany is safe because
// by the time handler is called, the request has been enriched with those fields.
// eslint-disable-next-line @typescript-eslint/no-explicit-any
type CompanyHandler = (req: any, res: NextApiResponse<any>) => any;

/**
 * Middleware that requires authentication AND resolves the active company.
 *
 * Company resolution order:
 * 1. X-Company-Id request header (set by frontend CompanyContext)
 * 2. User's default company (is_default = true in company_users)
 * 3. First company the user belongs to
 *
 * Attaches companyId and companyRole to the request object.
 */
export function withCompany(handler: CompanyHandler): NextApiHandler {
  return withAuth(async (req: NextApiRequest, res: NextApiResponse) => {
    try {
      const authReq = req as AuthenticatedNextApiRequest;
      const userId = authReq.user.id;

      // 1. Try X-Company-Id header
      const companyId = req.headers['x-company-id'] as string | undefined;

      if (companyId) {
        // Validate user has access to this specific company
        const access = await sql`
          SELECT role FROM company_users
          WHERE user_id = ${userId} AND company_id = ${companyId}::UUID
          LIMIT 1
        `;

        if (access.length === 0) {
          return res.status(403).json({
            success: false,
            error: { code: 'FORBIDDEN', message: 'You do not have access to this company' },
          });
        }

        (req as CompanyApiRequest).companyId = companyId;
        (req as CompanyApiRequest).companyRole = access[0]!.role as string;
        return handler(req, res);
      }

      // 2. Fall back to user's default or first company
      const companies = await sql`
        SELECT company_id, role, is_default
        FROM company_users
        WHERE user_id = ${userId}
        ORDER BY is_default DESC, created_at ASC
        LIMIT 1
      `;

      if (companies.length === 0) {
        return res.status(400).json({
          success: false,
          error: { code: 'NO_COMPANY', message: 'No company assigned. Please contact an administrator.' },
        });
      }

      (req as CompanyApiRequest).companyId = companies[0]!.company_id as string;
      (req as CompanyApiRequest).companyRole = companies[0]!.role as string;
      return handler(req, res);
    } catch (error) {
      log.error('Company middleware error', error instanceof Error ? { message: error.message } : { error }, 'CompanyMiddleware');
      return res.status(500).json({
        success: false,
        error: { code: 'COMPANY_ERROR', message: 'Failed to resolve company context' },
      });
    }
  });
}

/**
 * Admin Middleware
 * Convenience wrapper: withAuth + withRole('super_admin') + withErrorHandler
 * All admin API routes must be wrapped with this.
 */

import { withAuth, withRole, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { withErrorHandler } from '@/lib/api-error-handler';
import { checkRateLimit } from '@/lib/rateLimit';
import type { NextApiHandler, NextApiRequest, NextApiResponse } from 'next';

/**
 * Wraps a handler with:
 * 1. JWT authentication (withAuth)
 * 2. super_admin role enforcement (withRole)
 * 3. Structured error handling (withErrorHandler)
 *
 * Usage:
 *   export default withAdmin(async (req, res) => { ... });
 */
export function withAdmin(
  handler: (req: AuthenticatedNextApiRequest, res: NextApiResponse) => Promise<void>
): NextApiHandler {
  const rateLimitedHandler = async (req: NextApiRequest, res: NextApiResponse) => {
    // Use the last x-forwarded-for entry (proxy-appended) to prevent client IP spoofing.
    const forwarded = req.headers['x-forwarded-for'];
    const ip = (() => {
      if (forwarded) {
        const raw = Array.isArray(forwarded) ? forwarded[0] ?? '' : forwarded;
        const ips = raw.split(',').map((s: string) => s.trim());
        return ips[ips.length - 1] || req.socket.remoteAddress || 'unknown';
      }
      return req.socket.remoteAddress || 'unknown';
    })();
    const limited = checkRateLimit(`admin:${ip}`, { windowMs: 60000, maxRequests: 30 });
    if (limited) {
      res.status(429).json({
        success: false,
        error: { code: 'RATE_LIMITED', message: 'Too many requests. Please try again later.' },
      });
      return;
    }
    return handler(req as AuthenticatedNextApiRequest, res);
  };
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const errorWrapped = withErrorHandler(rateLimitedHandler as any);
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const roleWrapped = withRole('super_admin')(errorWrapped as any);
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  return withAuth(roleWrapped as any) as NextApiHandler;
}

/**
 * Custom Report Templates API
 * GET    — list templates (own + shared)
 * POST   — save or update template
 * DELETE — delete template (?id=X)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  getTemplates,
  getTemplateById,
  saveTemplate,
  deleteTemplate,
  type TemplateInput,
} from '@/modules/accounting/services/customReportService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const { companyId, user } = req as CompanyApiRequest;
  const userId = user.id;

  if (req.method === 'GET') {
    if (req.query.id) {
      const template = await getTemplateById(companyId, String(req.query.id));
      if (!template) return apiResponse.notFound(res, 'Template');
      return apiResponse.success(res, template);
    }
    const templates = await getTemplates(companyId, userId);
    return apiResponse.success(res, { items: templates });
  }

  if (req.method === 'POST') {
    const body = req.body as TemplateInput;
    if (!body.name?.trim()) return apiResponse.badRequest(res, 'name is required');
    if (!body.dataSource) return apiResponse.badRequest(res, 'dataSource is required');
    if (!Array.isArray(body.columns) || body.columns.length === 0) {
      return apiResponse.badRequest(res, 'At least one column is required');
    }
    const template = await saveTemplate(companyId, userId, body);
    log.info('Template saved via API', { id: template.id, companyId }, 'CustomReportsAPI');
    return apiResponse.success(res, template);
  }

  if (req.method === 'DELETE') {
    const id = req.query.id ? String(req.query.id) : req.body?.id;
    if (!id) return apiResponse.badRequest(res, 'id is required');
    try {
      await deleteTemplate(companyId, userId, id);
    } catch (err) {
      const msg = err instanceof Error ? err.message : 'Delete failed';
      if (msg.includes('not found')) return apiResponse.notFound(res, 'Template');
      if (msg.includes('do not own')) return apiResponse.forbidden(res, msg);
      throw err;
    }
    return apiResponse.success(res, { deleted: true });
  }

  return apiResponse.methodNotAllowed(res, req.method!, ['GET', 'POST', 'DELETE']);
}

export default withCompany(withErrorHandler(handler as never));

/**
 * Custom Report Fields API
 * GET /api/accounting/custom-reports-fields?source=gl_transactions
 * Returns available fields for a data source
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany } from '@/lib/auth';
import { getAvailableFields } from '@/modules/accounting/services/customReportService';

const VALID_SOURCES = [
  'gl_transactions', 'customer_invoices', 'supplier_invoices',
  'bank_transactions', 'items', 'customers', 'suppliers',
];

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method!, ['GET']);
  }

  const source = String(req.query.source ?? '');
  if (!source) return apiResponse.badRequest(res, 'source query parameter is required');
  if (!VALID_SOURCES.includes(source)) {
    return apiResponse.badRequest(res, `Invalid source. Valid values: ${VALID_SOURCES.join(', ')}`);
  }

  const fields = getAvailableFields(source).map(f => ({
    field: f.field,
    label: f.label,
    type: f.type,
    sortable: f.sortable,
    filterable: f.filterable,
    totalable: f.totalable,
  }));

  return apiResponse.success(res, { source, fields });
}

export default withCompany(withErrorHandler(handler as never));

/**
 * Custom Report Run API
 * POST /api/accounting/custom-reports-run
 * Executes a report configuration and returns rows + totals
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { runReport, type ReportConfig } from '@/modules/accounting/services/customReportService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method!, ['POST']);
  }

  const { companyId } = req as CompanyApiRequest;
  const body = req.body as ReportConfig & { limit?: number; offset?: number };

  if (!body.dataSource) return apiResponse.badRequest(res, 'dataSource is required');
  if (!Array.isArray(body.columns) || body.columns.length === 0) {
    return apiResponse.badRequest(res, 'At least one column is required');
  }

  const config: ReportConfig = {
    dataSource: body.dataSource,
    columns: body.columns,
    filters: body.filters ?? [],
    sortBy: body.sortBy ?? [],
    groupBy: body.groupBy ?? [],
    limit: body.limit ?? 500,
    offset: body.offset ?? 0,
  };

  try {
    const result = await runReport(companyId, config);
    log.info('Report run via API', { dataSource: config.dataSource, rowCount: result.rowCount, companyId }, 'CustomReportsRunAPI');
    return apiResponse.success(res, result);
  } catch (err) {
    const msg = err instanceof Error ? err.message : 'Report execution failed';
    if (msg.includes('Unknown data source') || msg.includes('No valid columns')) {
      return apiResponse.badRequest(res, msg);
    }
    throw err;
  }
}

export default withCompany(withErrorHandler(handler as never));

/**
 * Products API — CRUD for inventory items
 * GET: list products, POST: create product
 */
import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type AuthenticatedNextApiRequest, type CompanyApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { validateProduct, generateProductCode, type ProductInput } from '@/modules/accounting/services/inventoryService';

type Row = Record<string, unknown>;

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;

  if (req.method === 'GET') {
    const { search, category, type, active } = req.query;
    let rows: Row[];
    if (search) {
      const term = `%${String(search)}%`;
      rows = await sql`SELECT p.*, pc.name as category_name FROM products p LEFT JOIN product_categories pc ON p.category_id = pc.id WHERE p.company_id = ${companyId}::UUID AND (p.name ILIKE ${term} OR p.code ILIKE ${term} OR p.barcode ILIKE ${term}) ORDER BY p.name LIMIT 200` as Row[];
    } else if (category) {
      rows = await sql`SELECT p.*, pc.name as category_name FROM products p LEFT JOIN product_categories pc ON p.category_id = pc.id WHERE p.company_id = ${companyId}::UUID AND (p.category = ${String(category)} OR pc.code = ${String(category)}) ORDER BY p.name LIMIT 200` as Row[];
    } else if (type) {
      rows = await sql`SELECT p.*, pc.name as category_name FROM products p LEFT JOIN product_categories pc ON p.category_id = pc.id WHERE p.company_id = ${companyId}::UUID AND p.product_type = ${String(type)} ORDER BY p.name LIMIT 200` as Row[];
    } else {
      rows = await sql`SELECT p.*, pc.name as category_name FROM products p LEFT JOIN product_categories pc ON p.category_id = pc.id WHERE p.company_id = ${companyId}::UUID AND p.is_active = true ORDER BY p.name LIMIT 200` as Row[];
    }
    return apiResponse.success(res, rows);
  }
  if (req.method === 'POST') {
    const body = req.body as ProductInput;
    const validation = validateProduct(body);
    if (!validation.success) return apiResponse.validationError(res, Object.fromEntries((validation.errors || []).map(e => [e.field, e.message])));
    let categoryId: string | null = null;
    if (body.category) {
      const cats = await sql`SELECT id FROM product_categories WHERE code = ${body.category} AND company_id = ${companyId}::UUID LIMIT 1` as Row[];
      if (cats[0]) categoryId = String(cats[0].id);
    }
    const code = body.code || generateProductCode(body.category || 'general', 0);
    const inserted = await sql`
      INSERT INTO products (company_id, code, name, description, category_id, category, barcode, unit, product_type, cost_price, selling_price, cost_method, tax_rate, reorder_level, reorder_quantity, created_by)
      VALUES (${companyId}::UUID, ${code}, ${body.name}, ${body.description || null}, ${categoryId}, ${body.category || null}, ${body.barcode || null}, ${body.unit || 'each'}, ${body.type || 'inventory'}, ${body.costPrice || 0}, ${body.sellingPrice || 0}, ${body.costMethod || 'weighted_average'}, ${body.taxRate || 15}, ${body.reorderLevel || 0}, ${body.reorderQuantity || 0}, ${String(req.user.id)})
      RETURNING *
    ` as Row[];
    log.info('Product created', { code, name: body.name }, 'accounting');
    return apiResponse.created(res, inserted[0]);
  }
  return apiResponse.methodNotAllowed(res, req.method!, ['GET', 'POST']);
}
export default withCompany(withErrorHandler(handler));

/**
 * GET /api/accounting/description-suggest
 * Auto-suggest descriptions from templates + GL history.
 * WS-6.5
 *
 * Query params:
 *   q           — search term (required)
 *   entity_type — optional filter (e.g. 'journal_entry')
 *   limit       — max results (default 10)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withCompany } from '@/lib/auth/withCompany';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { suggestDescriptions } from '@/modules/accounting/services/descriptionTemplateService';
import type { CompanyApiRequest } from '@/lib/auth/withCompany';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'unknown', ['GET']);
  }

  const companyReq = req as CompanyApiRequest;
  const companyId = companyReq.companyId;

  const q = (req.query.q as string | undefined) ?? '';
  const entityType = req.query.entity_type as string | undefined;
  const limit = Math.min(Number(req.query.limit ?? 10), 20);

  if (!q.trim()) {
    return apiResponse.success(res, { suggestions: [] });
  }

  const suggestions = await suggestDescriptions(companyId, q, entityType, limit);
  return apiResponse.success(res, { suggestions });
}

export default withCompany(withErrorHandler(handler) as any);

/**
 * Asset Categories API — SARS Wear-and-Tear Categories
 * GET: list all categories with rates
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';

type Row = Record<string, unknown>;

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method!, ['GET']);
  }

  const categories = await sql`
    SELECT id, name, code, sars_rate, sars_years, description,
           gl_asset_account_id, gl_depreciation_account_id, gl_expense_account_id,
           is_active
    FROM asset_categories
    WHERE is_active = true
    ORDER BY name
  ` as Row[];

  return apiResponse.success(res, categories);
}

export default withCompany(withErrorHandler(handler));

/**
 * Customers API
 * GET  /api/accounting/customers         - List customers (optional ?q= search)
 * POST /api/accounting/customers         - Create a new customer
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { sql } from '@/lib/neon';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { cacheThrough, cache } from '@/lib/cache';
import { CACHE_KEYS, CACHE_TTL } from '@/lib/cache-keys';
import { withErrorHandler } from '@/lib/api-error-handler';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = Record<string, any>;

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;
  // ─── GET: List customers ────────────────────────────────────────────────────
  if (req.method === 'GET') {
    try {
      const { q } = req.query;
      const searchTerm = typeof q === 'string' && q.trim() ? `%${q.trim()}%` : null;

      let rows: Row[];

      if (searchTerm) {
        // Search queries are not cached — results change with every keystroke
        rows = (await sql`
          SELECT
            id, name, email, phone, contact_person,
            payment_terms, credit_limit, is_active,
            vat_number, registration_number,
            created_at
          FROM customers
          WHERE company_id = ${companyId}
            AND deleted_at IS NULL
            AND (name ILIKE ${searchTerm}
            OR email ILIKE ${searchTerm}
            OR vat_number ILIKE ${searchTerm}
            OR contact_person ILIKE ${searchTerm})
          ORDER BY name ASC
          LIMIT 200
        `) as Row[];
      } else {
        rows = await cacheThrough(
          CACHE_KEYS.customers(companyId),
          async () => (await sql`
            SELECT
              id, name, email, phone, contact_person,
              payment_terms, credit_limit, is_active,
              vat_number, registration_number,
              created_at
            FROM customers
            WHERE company_id = ${companyId}
              AND deleted_at IS NULL
            ORDER BY name ASC
            LIMIT 200
          `) as Row[],
          CACHE_TTL.REFERENCE_DATA,
        );
      }

      return apiResponse.success(res, rows);
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : String(err);
      // Return empty list if table does not yet exist
      if (message.includes('does not exist')) {
        return apiResponse.success(res, []);
      }
      log.error('customers GET failed', { error: message, module: 'accounting' });
      return apiResponse.internalError(res, err, 'Failed to fetch customers');
    }
  }

  // ─── POST: Create customer ──────────────────────────────────────────────────
  if (req.method === 'POST') {
    try {
      const b = req.body as Record<string, unknown>;
      const name = b.name as string | undefined;

      if (!name?.trim()) {
        return apiResponse.badRequest(res, 'Customer name is required');
      }

      const s = (k: string) => { const v = b[k]; return typeof v === 'string' && v.trim() ? v.trim() : null; };
      const n = (k: string) => { const v = b[k]; return v !== undefined && v !== null && v !== '' ? Number(v) : null; };
      const bool = (k: string, def = false) => { const v = b[k]; return typeof v === 'boolean' ? v : def; };

      const rows = (await sql`
        INSERT INTO customers (
          company_id, name, email, phone, mobile, fax, web_address,
          vat_number, registration_number,
          billing_address, shipping_address, contact_person,
          payment_terms, payment_terms_type, credit_limit, is_active, notes,
          category_id, cash_sale, opening_balance, opening_balance_date,
          accepts_electronic_invoices, auto_allocate_receipts,
          statement_distribution, default_discount, default_vat_type,
          subject_to_drc_vat, invoices_viewable_online
        ) VALUES (
          ${companyId},
          ${name.trim()},
          ${s('email')},
          ${s('phone')},
          ${s('mobile')},
          ${s('fax')},
          ${s('web_address')},
          ${s('vat_number')},
          ${s('registration_number')},
          ${s('billing_address')},
          ${s('shipping_address')},
          ${s('contact_person')},
          ${n('payment_terms') ?? 30},
          ${s('payment_terms_type') ?? 'days'},
          ${n('credit_limit')},
          ${bool('is_active', true)},
          ${s('notes')},
          ${s('category_id') ? s('category_id') : null}::uuid,
          ${bool('cash_sale')},
          ${n('opening_balance') ?? 0},
          ${s('opening_balance_date')}::date,
          ${bool('accepts_electronic_invoices')},
          ${bool('auto_allocate_receipts')},
          ${s('statement_distribution') ?? 'email'},
          ${n('default_discount') ?? 0},
          ${s('default_vat_type')},
          ${bool('subject_to_drc_vat')},
          ${bool('invoices_viewable_online', true)}
        )
        RETURNING *
      `) as Row[];

      cache.invalidate(CACHE_KEYS.customers(companyId));
      log.info('Customer created', { id: rows[0]?.id, name: rows[0]?.name, module: 'accounting' });
      return apiResponse.success(res, rows[0]);
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : String(err);
      log.error('customers POST failed', { error: message, module: 'accounting' });
      return apiResponse.internalError(res, err, 'Failed to create customer');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method ?? 'UNKNOWN', ['GET', 'POST']);
}

export default withCompany(withErrorHandler(handler));

/**
 * Assets API — CRUD for Fixed Assets
 * GET: list assets (with filters)
 * POST: create new asset
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type AuthenticatedNextApiRequest, type CompanyApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { validateAsset, generateAssetNumber, type AssetInput } from '@/modules/accounting/services/assetService';

type Row = Record<string, unknown>;

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;

  if (req.method === 'GET') {
    const { status, category, search } = req.query;

    let rows: Row[];

    if (search) {
      const term = `%${String(search)}%`;
      rows = await sql`
        SELECT a.*, ac.name as category_name, ac.sars_rate, ac.sars_years
        FROM assets a LEFT JOIN asset_categories ac ON a.category_id = ac.id
        WHERE a.company_id = ${companyId}::UUID AND (a.name ILIKE ${term} OR a.asset_number ILIKE ${term} OR a.serial_number ILIKE ${term})
        ORDER BY a.created_at DESC LIMIT 200
      ` as Row[];
    } else if (status && status !== 'all' && category) {
      rows = await sql`
        SELECT a.*, ac.name as category_name, ac.sars_rate, ac.sars_years
        FROM assets a LEFT JOIN asset_categories ac ON a.category_id = ac.id
        WHERE a.company_id = ${companyId}::UUID AND a.status = ${String(status)} AND (a.category = ${String(category)} OR ac.code = ${String(category)})
        ORDER BY a.created_at DESC LIMIT 200
      ` as Row[];
    } else if (status && status !== 'all') {
      rows = await sql`
        SELECT a.*, ac.name as category_name, ac.sars_rate, ac.sars_years
        FROM assets a LEFT JOIN asset_categories ac ON a.category_id = ac.id
        WHERE a.company_id = ${companyId}::UUID AND a.status = ${String(status)}
        ORDER BY a.created_at DESC LIMIT 200
      ` as Row[];
    } else if (category) {
      rows = await sql`
        SELECT a.*, ac.name as category_name, ac.sars_rate, ac.sars_years
        FROM assets a LEFT JOIN asset_categories ac ON a.category_id = ac.id
        WHERE a.company_id = ${companyId}::UUID AND (a.category = ${String(category)} OR ac.code = ${String(category)})
        ORDER BY a.created_at DESC LIMIT 200
      ` as Row[];
    } else {
      rows = await sql`
        SELECT a.*, ac.name as category_name, ac.sars_rate, ac.sars_years
        FROM assets a LEFT JOIN asset_categories ac ON a.category_id = ac.id
        WHERE a.company_id = ${companyId}::UUID
        ORDER BY a.created_at DESC LIMIT 200
      ` as Row[];
    }

    return apiResponse.success(res, rows);
  }

  if (req.method === 'POST') {
    const body = req.body as AssetInput;

    const validation = validateAsset(body);
    if (!validation.success) {
      return apiResponse.validationError(res,
        Object.fromEntries((validation.errors || []).map(e => [e.field, e.message]))
      );
    }

    let categoryId: string | null = null;
    let sarsRate: number | null = null;
    let taxLife: number | null = null;

    if (body.sarsCategory || body.category) {
      const catCode = body.sarsCategory || body.category;
      const cats = await sql`
        SELECT id, sars_rate, sars_years FROM asset_categories WHERE code = ${catCode} AND company_id = ${companyId}::UUID LIMIT 1
      ` as Row[];
      if (cats[0]) {
        categoryId = String(cats[0].id);
        sarsRate = Number(cats[0].sars_rate);
        taxLife = Number(cats[0].sars_years);
      }
    }

    const catKey = body.category || body.sarsCategory || 'general';
    const countResult = await sql`
      SELECT COUNT(*) as cnt FROM assets WHERE category = ${catKey} AND company_id = ${companyId}::UUID
    ` as Row[];
    const existingCount = Number((countResult[0] as any)?.cnt || 0);
    const assetNumber = generateAssetNumber(body.sarsCategory || body.category || 'general', existingCount);

    const inserted = await sql`
      INSERT INTO assets (
        company_id, asset_number, name, description, category_id, category,
        serial_number, location, purchase_date, purchase_price,
        salvage_value, useful_life_years, depreciation_method,
        sars_category, sars_rate, tax_useful_life_years, tax_depreciation_method,
        status, created_by
      ) VALUES (
        ${companyId}::UUID, ${assetNumber}, ${body.name}, ${body.description || null},
        ${categoryId}, ${catKey},
        ${(body as any).serialNumber || null}, ${body.location || null},
        ${body.purchaseDate}, ${body.cost},
        ${body.salvageValue || 0}, ${body.usefulLifeYears}, ${body.depreciationMethod || 'straight_line'},
        ${body.sarsCategory || null}, ${sarsRate}, ${taxLife}, ${'straight_line'},
        ${body.status || 'available'}, ${String(req.user.id)}
      ) RETURNING *
    ` as Row[];

    log.info('Asset created', { assetNumber, name: body.name }, 'accounting');
    return apiResponse.created(res, inserted[0]);
  }

  return apiResponse.methodNotAllowed(res, req.method!, ['GET', 'POST']);
}

export default withCompany(withErrorHandler(handler));

/**
 * Asset Register Report API
 * GET: full asset register with depreciation details
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';

type Row = Record<string, unknown>;

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method!, ['GET']);
  }

  const companyId = (req as any).companyId as string;
  const { asOf } = req.query;
  const asOfDate = asOf ? String(asOf) : new Date().toISOString().split('T')[0];

  const rows = await sql`
    SELECT a.*, ac.name as category_name, ac.sars_rate, ac.sars_years,
      COALESCE(a.accumulated_depreciation, 0) as total_depreciation,
      COALESCE(a.current_book_value, a.purchase_price) as net_book_value
    FROM assets a
    LEFT JOIN asset_categories ac ON a.category_id = ac.id
    WHERE a.purchase_date <= ${asOfDate} AND a.company_id = ${companyId}::UUID
    ORDER BY a.category, a.asset_number
  ` as Row[];

  const summary = {
    totalAssets: rows.length,
    totalCost: rows.reduce((s, r) => s + Number(r.purchase_price || 0), 0),
    totalAccumulatedDepreciation: rows.reduce((s, r) => s + Number(r.total_depreciation || 0), 0),
    totalBookValue: rows.reduce((s, r) => s + Number(r.net_book_value || 0), 0),
    asOfDate,
  };

  return apiResponse.success(res, { assets: rows, summary });
}

export default withCompany(withErrorHandler(handler));

/**
 * Stock Adjustments API — increase/decrease/write-off stock
 */
import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type AuthenticatedNextApiRequest, type CompanyApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { validateStockAdjustment } from '@/modules/accounting/services/inventoryService';
type Row = Record<string, unknown>;

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;

  if (req.method === 'GET') {
    const adjustments = await sql`
      SELECT sa.*, p.code as product_code, p.name as product_name
      FROM stock_adjustments sa JOIN products p ON sa.product_id = p.id
      WHERE sa.company_id = ${companyId}::UUID
      ORDER BY sa.created_at DESC LIMIT 200
    ` as Row[];
    return apiResponse.success(res, adjustments);
  }
  if (req.method === 'POST') {
    const body = req.body;
    const validation = validateStockAdjustment(body);
    if (!validation.success) return apiResponse.validationError(res, Object.fromEntries((validation.errors || []).map(e => [e.field, e.message])));

    const countRes = await sql`SELECT COUNT(*) as cnt FROM stock_adjustments WHERE company_id = ${companyId}::UUID` as Row[];
    const adjNum = `ADJ-${String(Number((countRes[0] as any)?.cnt || 0) + 1).padStart(5, '0')}`;

    const inserted = await sql`
      INSERT INTO stock_adjustments (company_id, adjustment_number, product_id, warehouse_id, adjustment_type, quantity, unit_cost, reason, created_by)
      VALUES (${companyId}::UUID, ${adjNum}, ${body.productId}, ${body.warehouseId || null}, ${body.adjustmentType}, ${body.quantity}, ${body.unitCost || 0}, ${body.reason}, ${String(req.user.id)})
      RETURNING *
    ` as Row[];

    // Update product stock (scoped to company via product ownership)
    const sign = ['increase', 'count'].includes(body.adjustmentType) ? 1 : -1;
    await sql`UPDATE products SET current_stock = GREATEST(0, current_stock + ${sign * body.quantity}), updated_at = NOW() WHERE id = ${body.productId} AND company_id = ${companyId}::UUID`;

    // Record movement
    const movementType = body.adjustmentType === 'increase' ? 'adjustment_in' : body.adjustmentType === 'write_off' ? 'write_off' : 'adjustment_out';
    await sql`INSERT INTO stock_movements (company_id, product_id, warehouse_id, movement_type, quantity, unit_cost, total_cost, reference_type, reference_id, created_by) VALUES (${companyId}::UUID, ${body.productId}, ${body.warehouseId || null}, ${movementType}, ${body.quantity}, ${body.unitCost || 0}, ${(body.unitCost || 0) * body.quantity}, 'stock_adjustment', ${String(inserted[0]?.id)}, ${String(req.user.id)})`;

    log.info('Stock adjusted', { adjNum, type: body.adjustmentType, qty: body.quantity }, 'accounting');
    return apiResponse.created(res, inserted[0]);
  }
  return apiResponse.methodNotAllowed(res, req.method!, ['GET', 'POST']);
}
export default withCompany(withErrorHandler(handler));

/**
 * Items API — CRUD for inventory / service items
 * GET:    list items (with filters) or single item (?id=UUID)
 * POST:   create new item
 * PUT:    update existing item
 * DELETE: soft-delete (set is_active = false)
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import {
  getItem,
  listItems,
  createItem,
  updateItem,
  softDeleteItem,
  itemExists,
  checkCodeDuplicate,
  type ItemFilters,
  type CreateItemInput,
  type UpdateItemInput,
} from '@/modules/accounting/services/itemService';

async function handler(req: CompanyApiRequest, res: NextApiResponse) {
  const companyId = req.companyId;

  /* ------------------------------------------------------------------ */
  /*  GET — list items or fetch single item                             */
  /* ------------------------------------------------------------------ */
  if (req.method === 'GET') {
    const { id, q, type, active, category_id } = req.query;

    if (id) {
      const item = await getItem(companyId, String(id));
      if (!item) return apiResponse.notFound(res, 'Item', String(id));
      return apiResponse.success(res, item);
    }

    const rawType = String(type || '');
    const filters: ItemFilters = {
      q: q ? String(q) : undefined,
      type: rawType === 'physical' || rawType === 'service' ? rawType : undefined,
      active: active === 'true' ? 'true' : active === 'false' ? 'false' : undefined,
      category_id: category_id ? String(category_id) : undefined,
    };

    const rows = await listItems(companyId, filters);
    return apiResponse.success(res, rows);
  }

  /* ------------------------------------------------------------------ */
  /*  POST — create item                                                */
  /* ------------------------------------------------------------------ */
  if (req.method === 'POST') {
    const body = req.body as Record<string, unknown>;

    const description = String(body.description || '').trim();
    if (!description) {
      return apiResponse.validationError(res, { description: 'Description is required' });
    }

    const itemType = String(body.item_type || 'physical');
    if (itemType !== 'physical' && itemType !== 'service') {
      return apiResponse.validationError(res, { item_type: 'Must be physical or service' });
    }

    const code = String(body.code || '').trim();
    if (code) {
      const isDupe = await checkCodeDuplicate(companyId, code);
      if (isDupe) {
        return apiResponse.validationError(res, { code: `Item code '${code}' already exists` });
      }
    }

    const input: CreateItemInput = {
      code: code || undefined,
      description,
      item_type: itemType,
      category_id: body.category_id ? String(body.category_id) : null,
      is_active: body.is_active !== false,
      unit: String(body.unit || 'each'),
      cost_price: Number(body.cost_price) || 0,
      selling_price_excl: Number(body.selling_price_excl) || 0,
      selling_price_incl: Number(body.selling_price_incl) || 0,
      gp_percent: Number(body.gp_percent) || 0,
      vat_on_sales: String(body.vat_on_sales || 'standard'),
      vat_on_purchases: String(body.vat_on_purchases || 'standard'),
      sales_account_id: body.sales_account_id ? String(body.sales_account_id) : null,
      purchases_account_id: body.purchases_account_id ? String(body.purchases_account_id) : null,
      opening_qty: Number(body.opening_qty) || 0,
      opening_cost: Number(body.opening_cost) || 0,
      opening_date: body.opening_date ? String(body.opening_date) : null,
      notes: body.notes ? String(body.notes) : null,
      image_url: body.image_url ? String(body.image_url) : null,
    };

    const item = await createItem(companyId, input);
    return apiResponse.created(res, item);
  }

  /* ------------------------------------------------------------------ */
  /*  PUT — update item                                                 */
  /* ------------------------------------------------------------------ */
  if (req.method === 'PUT') {
    const body = req.body as Record<string, unknown>;
    const id = String(body.id || '');
    if (!id) {
      return apiResponse.validationError(res, { id: 'Item id is required' });
    }

    const exists = await itemExists(companyId, id);
    if (!exists) return apiResponse.notFound(res, 'Item', id);

    if (body.code !== undefined) {
      const newCode = String(body.code).trim();
      if (newCode) {
        const isDupe = await checkCodeDuplicate(companyId, newCode, id);
        if (isDupe) {
          return apiResponse.validationError(res, { code: `Item code '${newCode}' already exists` });
        }
      }
    }

    const input: UpdateItemInput = { id };
    if (body.code !== undefined) input.code = String(body.code);
    if (body.description !== undefined) input.description = String(body.description);
    if (body.item_type !== undefined) input.item_type = String(body.item_type);
    if (body.category_id !== undefined) input.category_id = String(body.category_id);
    if (body.is_active !== undefined) input.is_active = Boolean(body.is_active);
    if (body.unit !== undefined) input.unit = String(body.unit);
    if (body.cost_price !== undefined) input.cost_price = Number(body.cost_price);
    if (body.selling_price_excl !== undefined) input.selling_price_excl = Number(body.selling_price_excl);
    if (body.selling_price_incl !== undefined) input.selling_price_incl = Number(body.selling_price_incl);
    if (body.gp_percent !== undefined) input.gp_percent = Number(body.gp_percent);
    if (body.vat_on_sales !== undefined) input.vat_on_sales = String(body.vat_on_sales);
    if (body.vat_on_purchases !== undefined) input.vat_on_purchases = String(body.vat_on_purchases);
    if (body.sales_account_id !== undefined) input.sales_account_id = String(body.sales_account_id);
    if (body.purchases_account_id !== undefined) input.purchases_account_id = String(body.purchases_account_id);
    if (body.opening_qty !== undefined) input.opening_qty = Number(body.opening_qty);
    if (body.opening_cost !== undefined) input.opening_cost = Number(body.opening_cost);
    if (body.opening_date !== undefined) input.opening_date = String(body.opening_date);
    if (body.current_qty !== undefined) input.current_qty = Number(body.current_qty);
    if (body.notes !== undefined) input.notes = String(body.notes);
    if (body.image_url !== undefined) input.image_url = String(body.image_url);

    const updated = await updateItem(companyId, input);
    return apiResponse.success(res, updated);
  }

  /* ------------------------------------------------------------------ */
  /*  DELETE — soft-delete (set is_active = false)                      */
  /* ------------------------------------------------------------------ */
  if (req.method === 'DELETE') {
    const body = req.body as Record<string, unknown>;
    const id = String(body.id || '');
    if (!id) {
      return apiResponse.validationError(res, { id: 'Item id is required' });
    }

    const exists = await itemExists(companyId, id);
    if (!exists) return apiResponse.notFound(res, 'Item', id);

    await softDeleteItem(companyId, id);
    return apiResponse.success(res, { id, deleted: true });
  }

  return apiResponse.methodNotAllowed(res, req.method!, ['GET', 'POST', 'PUT', 'DELETE']);
}

export default withCompany(withErrorHandler(handler as any));

/**
 * Suppliers List API
 * GET  /api/accounting/suppliers-list    - List suppliers (optional ?q= search)
 * POST /api/accounting/suppliers-list    - Create a new supplier
 *
 * Named suppliers-list.ts to avoid conflict with any existing suppliers route.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { sql } from '@/lib/neon';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { cacheThrough, cache } from '@/lib/cache';
import { CACHE_KEYS, CACHE_TTL } from '@/lib/cache-keys';
import { withErrorHandler } from '@/lib/api-error-handler';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = Record<string, any>;

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;
  // ─── GET: List suppliers ────────────────────────────────────────────────────
  if (req.method === 'GET') {
    try {
      const { q } = req.query;
      const searchTerm = typeof q === 'string' && q.trim() ? `%${q.trim()}%` : null;

      let rows: Row[];

      if (searchTerm) {
        // Search queries are not cached — results change with every keystroke
        rows = (await sql`
          SELECT
            id, name, company_name, email, phone,
            contact_person, is_active,
            vat_number, payment_terms,
            created_at
          FROM suppliers
          WHERE company_id = ${companyId}
            AND deleted_at IS NULL
            AND (name ILIKE ${searchTerm}
            OR email ILIKE ${searchTerm}
            OR company_name ILIKE ${searchTerm}
            OR contact_person ILIKE ${searchTerm})
          ORDER BY name ASC
          LIMIT 200
        `) as Row[];
      } else {
        rows = await cacheThrough(
          CACHE_KEYS.suppliers(companyId),
          async () => (await sql`
            SELECT
              id, name, company_name, email, phone,
              contact_person, is_active,
              vat_number, payment_terms,
              created_at
            FROM suppliers
            WHERE company_id = ${companyId}
              AND deleted_at IS NULL
            ORDER BY name ASC
            LIMIT 200
          `) as Row[],
          CACHE_TTL.REFERENCE_DATA,
        );
      }

      return apiResponse.success(res, rows);
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : String(err);
      log.error('suppliers GET failed', { error: message, module: 'accounting' });
      return apiResponse.internalError(res, err, `Failed to fetch suppliers: ${message}`);
    }
  }

  // ─── POST: Create supplier ──────────────────────────────────────────────────
  if (req.method === 'POST') {
    try {
      const {
        name,
        company_name,
        email,
        phone,
        vat_number,
        registration_number,
        address,
        contact_person,
        payment_terms,
        bank_name,
        bank_account_number,
        bank_branch_code,
        bank_account_type,
        is_active,
        notes,
        category,
      } = req.body as {
        name?: string;
        company_name?: string;
        email?: string;
        phone?: string;
        vat_number?: string;
        registration_number?: string;
        address?: string;
        contact_person?: string;
        payment_terms?: number;
        bank_name?: string | null;
        bank_account_number?: string | null;
        bank_branch_code?: string | null;
        bank_account_type?: string | null;
        is_active?: boolean;
        notes?: string;
        category?: string;
      };

      if (!name?.trim()) {
        return apiResponse.badRequest(res, 'Supplier name is required');
      }

      const rows = (await sql`
        INSERT INTO suppliers (
          company_id, name, company_name, email, phone,
          vat_number, registration_number, address, contact_person,
          payment_terms,
          bank_name, bank_account_number, bank_branch_code, bank_account_type,
          is_active, notes, category
        ) VALUES (
          ${companyId},
          ${name.trim()},
          ${company_name?.trim() || null},
          ${email?.trim() || null},
          ${phone?.trim() || null},
          ${vat_number?.trim() || null},
          ${registration_number?.trim() || null},
          ${address?.trim() || null},
          ${contact_person?.trim() || null},
          ${payment_terms ?? 30},
          ${bank_name ?? null},
          ${bank_account_number ?? null},
          ${bank_branch_code ?? null},
          ${bank_account_type ?? null},
          ${is_active ?? true},
          ${notes?.trim() || null},
          ${category?.trim() || null}
        )
        RETURNING
          id, name, company_name, email, phone,
          vat_number, registration_number, address, contact_person,
          payment_terms,
          bank_name, bank_account_number, bank_branch_code, bank_account_type,
          is_active, notes, category,
          created_at
      `) as Row[];

      cache.invalidate(CACHE_KEYS.suppliers(companyId));
      log.info('Supplier created', { id: rows[0]?.id, name: rows[0]?.name, module: 'accounting' });
      return apiResponse.success(res, rows[0]);
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : String(err);
      log.error('suppliers POST failed', { error: message, module: 'accounting' });
      return apiResponse.internalError(res, err, 'Failed to create supplier');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method ?? 'UNKNOWN', ['GET', 'POST']);
}

export default withCompany(withErrorHandler(handler));

/**
 * Purchase Orders API — CRUD
 */
import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { validatePurchaseOrder, calculatePOTotals, generatePONumber } from '@/modules/accounting/services/procurementService';

type Row = Record<string, unknown>;

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  const companyId = (req as any).companyId as string;

  if (req.method === 'GET') {
    const { status, supplierId } = req.query;
    let rows: Row[];
    if (status) {
      rows = await sql`SELECT po.*, s.name as supplier_name FROM purchase_orders po LEFT JOIN suppliers s ON po.supplier_id = s.id WHERE po.company_id = ${companyId}::UUID AND po.status = ${String(status)} ORDER BY po.created_at DESC LIMIT 200` as Row[];
    } else if (supplierId) {
      rows = await sql`SELECT po.*, s.name as supplier_name FROM purchase_orders po LEFT JOIN suppliers s ON po.supplier_id = s.id WHERE po.company_id = ${companyId}::UUID AND po.supplier_id = ${String(supplierId)} ORDER BY po.created_at DESC LIMIT 200` as Row[];
    } else {
      rows = await sql`SELECT po.*, s.name as supplier_name FROM purchase_orders po LEFT JOIN suppliers s ON po.supplier_id = s.id WHERE po.company_id = ${companyId}::UUID ORDER BY po.created_at DESC LIMIT 200` as Row[];
    }
    return apiResponse.success(res, rows);
  }

  if (req.method === 'POST') {
    const body = req.body;
    const validation = validatePurchaseOrder(body);
    if (!validation.success) return apiResponse.validationError(res, Object.fromEntries((validation.errors || []).map(e => [e.field, e.message])));

    const totals = calculatePOTotals(body.items);
    const countRes = await sql`SELECT COUNT(*) as cnt FROM purchase_orders WHERE company_id = ${companyId}::UUID` as Row[];
    const poNumber = generatePONumber(Number((countRes[0] as any)?.cnt || 0));

    const inserted = await sql`
      INSERT INTO purchase_orders (company_id, po_number, supplier_id, order_date, expected_delivery_date, subtotal, tax_amount, total, notes, reference, created_by)
      VALUES (${companyId || null}, ${poNumber}, ${body.supplierId}, ${body.orderDate || new Date().toISOString().split('T')[0]}, ${body.expectedDeliveryDate || null}, ${totals.subtotal}, ${totals.taxAmount}, ${totals.total}, ${body.notes || null}, ${body.reference || null}, ${String(req.user.id)})
      RETURNING *
    ` as Row[];

    const poId = String(inserted[0]?.id);
    for (let i = 0; i < body.items.length; i++) {
      const item = body.items[i];
      const lineTotal = Math.round(item.quantity * item.unitPrice * 100) / 100;
      const lineTax = Math.round(lineTotal * (item.taxRate || 15) / 100 * 100) / 100;
      await sql`INSERT INTO po_items (purchase_order_id, product_id, description, quantity, unit_price, tax_rate, line_total, tax_amount, sort_order) VALUES (${poId}, ${item.productId || null}, ${item.description}, ${item.quantity}, ${item.unitPrice}, ${item.taxRate || 15}, ${lineTotal}, ${lineTax}, ${i})`;
    }

    log.info('Purchase order created', { poNumber, supplier: body.supplierId, total: totals.total }, 'accounting');
    return apiResponse.created(res, { ...inserted[0], items: body.items });
  }

  return apiResponse.methodNotAllowed(res, req.method!, ['GET', 'POST']);
}

