/**
 * Products API — CRUD for inventory items
 * GET: list products, POST: create product
 */
import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type AuthenticatedNextApiRequest, type CompanyApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { validateProduct, generateProductCode, type ProductInput } from '@/modules/accounting/services/inventoryService';

type Row = Record<string, unknown>;

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;

  if (req.method === 'GET') {
    const { search, category, type, active } = req.query;
    let rows: Row[];
    if (search) {
      const term = `%${String(search)}%`;
      rows = await sql`SELECT p.*, pc.name as category_name FROM products p LEFT JOIN product_categories pc ON p.category_id = pc.id WHERE p.company_id = ${companyId}::UUID AND (p.name ILIKE ${term} OR p.code ILIKE ${term} OR p.barcode ILIKE ${term}) ORDER BY p.name LIMIT 200` as Row[];
    } else if (category) {
      rows = await sql`SELECT p.*, pc.name as category_name FROM products p LEFT JOIN product_categories pc ON p.category_id = pc.id WHERE p.company_id = ${companyId}::UUID AND (p.category = ${String(category)} OR pc.code = ${String(category)}) ORDER BY p.name LIMIT 200` as Row[];
    } else if (type) {
      rows = await sql`SELECT p.*, pc.name as category_name FROM products p LEFT JOIN product_categories pc ON p.category_id = pc.id WHERE p.company_id = ${companyId}::UUID AND p.product_type = ${String(type)} ORDER BY p.name LIMIT 200` as Row[];
    } else {
      rows = await sql`SELECT p.*, pc.name as category_name FROM products p LEFT JOIN product_categories pc ON p.category_id = pc.id WHERE p.company_id = ${companyId}::UUID AND p.is_active = true ORDER BY p.name LIMIT 200` as Row[];
    }
    return apiResponse.success(res, rows);
  }
  if (req.method === 'POST') {
    const body = req.body as ProductInput;
    const validation = validateProduct(body);
    if (!validation.success) return apiResponse.validationError(res, Object.fromEntries((validation.errors || []).map(e => [e.field, e.message])));
    let categoryId: string | null = null;
    if (body.category) {
      const cats = await sql`SELECT id FROM product_categories WHERE code = ${body.category} AND company_id = ${companyId}::UUID LIMIT 1` as Row[];
      if (cats[0]) categoryId = String(cats[0].id);
    }
    const code = body.code || generateProductCode(body.category || 'general', 0);
    const inserted = await sql`
      INSERT INTO products (company_id, code, name, description, category_id, category, barcode, unit, product_type, cost_price, selling_price, cost_method, tax_rate, reorder_level, reorder_quantity, created_by)
      VALUES (${companyId}::UUID, ${code}, ${body.name}, ${body.description || null}, ${categoryId}, ${body.category || null}, ${body.barcode || null}, ${body.unit || 'each'}, ${body.type || 'inventory'}, ${body.costPrice || 0}, ${body.sellingPrice || 0}, ${body.costMethod || 'weighted_average'}, ${body.taxRate || 15}, ${body.reorderLevel || 0}, ${body.reorderQuantity || 0}, ${String(req.user.id)})
      RETURNING *
    ` as Row[];
    log.info('Product created', { code, name: body.name }, 'accounting');
    return apiResponse.created(res, inserted[0]);
  }

/**
 * Shared formatting utilities for the Accounting app
 */

/** Format a number as South African Rand (R 1,234.56) */
export function formatCurrency(amount: number): string {
  return new Intl.NumberFormat('en-ZA', { style: 'currency', currency: 'ZAR' }).format(amount);
}

/** Format a date string to locale display format (DD/MM/YYYY) */
export function formatDate(dateStr: string | Date | null | undefined): string {
  if (!dateStr) return '—';
  const d = new Date(dateStr);
  if (isNaN(d.getTime())) return '—';
  return d.toLocaleDateString('en-ZA');
}

/**
 * Centralized Date Formatting Utility
 *
 * ALL date formatting across the app should use these functions.
 * Locale: en-ZA (South Africa) for all user-facing dates.
 *
 * Display formats:
 *   formatDisplayDate()       → "25 Feb 2026"
 *   formatDisplayDateTime()   → "25 Feb 2026, 14:30"
 *   formatDisplayDateLong()   → "25 February 2026"
 *   formatDisplayDateShort()  → "25 Feb"
 *   formatDisplayMonthYear()  → "Feb 2026"
 *
 * Internal/API formats:
 *   formatDateISO()           → "2026-02-25"
 *   formatDateTimeISO()       → "2026-02-25 14:30"
 */

const LOCALE = 'en-ZA';

type DateInput = Date | string | number | null | undefined | { toDate: () => Date };

/**
 * Safely convert any date input to a Date object.
 * Handles: Date, ISO string, timestamp number, Firebase Timestamp, null/undefined.
 */
function toDate(date: DateInput): Date | null {
  if (!date) return null;

  try {
    // Firebase Timestamp
    if (typeof date === 'object' && 'toDate' in date && typeof date.toDate === 'function') {
      const d = date.toDate();
      return isNaN(d.getTime()) ? null : d;
    }

    if (date instanceof Date) {
      return isNaN(date.getTime()) ? null : date;
    }

    if (typeof date === 'string' || typeof date === 'number') {
      const d = new Date(date);
      return isNaN(d.getTime()) ? null : d;
    }

    return null;
  } catch {
    return null;
  }
}

// ─── Display Formats (user-facing) ──────────────────────────────

/**
 * "25 Feb 2026" — Standard display date
 */
export function formatDisplayDate(date: DateInput, fallback = 'N/A'): string {
  const d = toDate(date);
  if (!d) return fallback;
  return d.toLocaleDateString(LOCALE, { day: 'numeric', month: 'short', year: 'numeric' });
}

/**
 * "25 Feb 2026, 14:30" — Display date with time
 */
export function formatDisplayDateTime(date: DateInput, fallback = 'N/A'): string {
  const d = toDate(date);
  if (!d) return fallback;
  const datePart = d.toLocaleDateString(LOCALE, { day: 'numeric', month: 'short', year: 'numeric' });
  const timePart = d.toLocaleTimeString(LOCALE, { hour: '2-digit', minute: '2-digit', hour12: false });
  return `${datePart}, ${timePart}`;
}

/**
 * "25 February 2026" — Formal display (agreements, documents)
 */
export function formatDisplayDateLong(date: DateInput, fallback = 'N/A'): string {
  const d = toDate(date);
  if (!d) return fallback;
  return d.toLocaleDateString(LOCALE, { day: 'numeric', month: 'long', year: 'numeric' });
}

/**
 * "25 Feb" — Compact display (alerts, timeline markers)
 */
export function formatDisplayDateShort(date: DateInput, fallback = 'N/A'): string {
  const d = toDate(date);
  if (!d) return fallback;
  return d.toLocaleDateString(LOCALE, { day: 'numeric', month: 'short' });
}

/**
 * "Feb 2026" — Month/year display (charts, reports)
 */
export function formatDisplayMonthYear(date: DateInput, fallback = 'N/A'): string {
  const d = toDate(date);
  if (!d) return fallback;
  return d.toLocaleDateString(LOCALE, { month: 'short', year: 'numeric' });
}

/**
 * "14:30" — Time only display
 */
export function formatDisplayTime(date: DateInput, fallback = 'N/A'): string {
  const d = toDate(date);
  if (!d) return fallback;
  return d.toLocaleTimeString(LOCALE, { hour: '2-digit', minute: '2-digit', hour12: false });
}

// ─── Internal / API / Export Formats ────────────────────────────

/**
 * "2026-02-25" — ISO date for APIs, exports, form values
 */
export function formatDateISO(date: DateInput): string {
  const d = toDate(date);
  if (!d) return '';
  return d.toISOString().split('T')[0] ?? '';
}

/**
 * "2026-02-25 14:30" — ISO datetime for APIs, exports
 */
export function formatDateTimeISO(date: DateInput): string {
  const d = toDate(date);
  if (!d) return '';
  const datePart = d.toISOString().split('T')[0];
  const timePart = d.toTimeString().slice(0, 5);
  return `${datePart} ${timePart}`;
}

// ─── Utility ────────────────────────────────────────────────────

/**
 * Parse a date string to Date object safely
 */
export function parseDateSafe(date: DateInput): Date | null {
  return toDate(date);
}

/**
 * Get today's date in ISO format (YYYY-MM-DD)
 */
export function getTodayISO(): string {
  return formatDateISO(new Date());
}

// ─── Legacy Aliases (backward compatibility) ────────────────────
// These maintain existing imports while pointing to the new functions.

/** @deprecated Use formatDateISO() */
export const formatDateStandard = formatDateISO;

/** @deprecated Use formatDateTimeISO() */
export const formatDateTimeStandard = formatDateTimeISO;

/** @deprecated Use formatDisplayDate() for display or formatDateISO() for API */
export function formatDate(date: DateInput, fallback = 'N/A'): string {
  return formatDisplayDate(date, fallback);
}

/** @deprecated Use formatDisplayDateTime() */
export function formatDateTime(date: DateInput, fallback = 'N/A'): string {
  return formatDisplayDateTime(date, fallback);
}

/** @deprecated Use parseDateSafe() */
export const parseDateStandard = parseDateSafe;

/** @deprecated Use getTodayISO() */
export const getTodayStandard = getTodayISO;

/** @deprecated Use formatDateISO() */
export const formatDateForExport = formatDateISO;

