/**
 * Page Visits API — tracks user navigation for dynamic quick actions
 * GET  /api/accounting/page-visits?limit=6  — top visited pages for current user
 * POST /api/accounting/page-visits           — record a page visit
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';
import { PAGE_REGISTRY } from '@/modules/accounting/constants/pageRegistry';

async function handler(req: CompanyApiRequest, res: NextApiResponse) {
  const { companyId } = req;
  const userId = req.user.id;

  if (req.method === 'GET') {
    const limit = Math.min(Number(req.query.limit) || 6, 20);

    const rows = await sql`
      SELECT page_path, visit_count, last_visited_at
      FROM page_visits
      WHERE company_id = ${companyId}::UUID
        AND user_id = ${userId}
      ORDER BY visit_count DESC, last_visited_at DESC
      LIMIT ${limit}
    `;

    return apiResponse.success(res, rows);
  }

  if (req.method === 'POST') {
    const { path } = req.body as { path?: string };

    if (!path || typeof path !== 'string') {
      return apiResponse.badRequest(res, 'path is required');
    }

    if (!PAGE_REGISTRY[path]) {
      return apiResponse.badRequest(res, 'Unknown page path');
    }

    await sql`
      INSERT INTO page_visits (company_id, user_id, page_path)
      VALUES (${companyId}::UUID, ${userId}, ${path})
      ON CONFLICT (company_id, user_id, page_path)
      DO UPDATE SET
        visit_count = page_visits.visit_count + 1,
        last_visited_at = NOW()
    `;

    return apiResponse.success(res, { recorded: true });
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}

export default withCompany(withErrorHandler(handler));

/**
 * Budget Management API
 * GET  — list budgets for a fiscal year
 * POST — upsert a budget entry
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { getBudgets, upsertBudget } from '@/modules/accounting/services/budgetService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;
  const userId = (req as AuthenticatedNextApiRequest).user.id;

  if (req.method === 'GET') {
    const fiscalYear = Number(req.query.fiscal_year) || new Date().getFullYear();
    const items = await getBudgets(companyId, fiscalYear);
    return apiResponse.success(res, { items, fiscalYear });
  }

  if (req.method === 'POST') {
    const { glAccountId, fiscalYear, annualAmount, months, notes } = req.body;
    if (!glAccountId || !fiscalYear || annualAmount == null) {
      return apiResponse.badRequest(res, 'glAccountId, fiscalYear, and annualAmount are required');
    }
    try {
      const entry = await upsertBudget(companyId, {
        glAccountId, fiscalYear: Number(fiscalYear),
        annualAmount: Number(annualAmount),
        months: months || undefined, notes,
      }, userId);
      return apiResponse.success(res, entry);
    } catch (err) {
      log.error('Failed to upsert budget', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, err instanceof Error ? err.message : 'Failed');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method!, ['GET', 'POST']);
}


export default withCompany(withErrorHandler(handler));

/**
 * Cash Flow Forecast API
 * GET — generate cash flow forecast for the next N months
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { generateForecast, getHistoricalForChart } from '@/modules/accounting/services/cashFlowForecastService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method!, ['GET']);
  }

  const { companyId } = req as CompanyApiRequest;
  const months = Math.max(1, Math.min(Number(req.query.months) || 6, 24));
  const threshold = Math.max(0, Number(req.query.threshold) || 0);
  const includeHistory = req.query.history !== 'false';

  try {
    const [forecast, historical] = await Promise.all([
      generateForecast(companyId, months, threshold),
      includeHistory ? getHistoricalForChart(companyId, 6) : Promise.resolve([]),
    ]);

    return apiResponse.success(res, {
      ...forecast,
      historical,
    });
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Cash flow forecast failed';
    return apiResponse.internalError(res, err, message);
  }
}


