/**
 * KPI Dashboard API
 * GET /api/accounting/kpi-dashboard
 *   ?from=YYYY-MM-DD   - period start (defaults to start of current month)
 *   ?to=YYYY-MM-DD     - period end (defaults to today)
 *   ?months=N           - chart lookback months (default 6)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  getDashboardKPIs,
  getRevenueChart,
  getCashFlowChart,
  getAgingBreakdown,
  getTopCustomers,
  getTopExpenseCategories,
} from '@/modules/accounting/services/kpiService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);
  }

  const { companyId } = req as CompanyApiRequest;

  try {
    const now = new Date();
    const year = now.getFullYear();
    const month = now.getMonth() + 1;

    // Default to start of financial year (12 months back from current month-end)
    const fyStart = new Date(year, month - 13, 1); // ~12 months ago
    const from = req.query.from
      ? String(req.query.from)
      : fyStart.toISOString().slice(0, 10);
    const to = req.query.to
      ? String(req.query.to)
      : now.toISOString().slice(0, 10);
    const months = Math.max(1, Math.min(Number(req.query.months) || 6, 120));

    const [kpis, revenueChart, cashFlowChart, arAging, apAging, topCustomers, topExpenses] =
      await Promise.all([
        getDashboardKPIs(companyId, from, to),
        getRevenueChart(companyId, months),
        getCashFlowChart(companyId, months),
        getAgingBreakdown(companyId, 'ar'),
        getAgingBreakdown(companyId, 'ap'),
        getTopCustomers(companyId, 5),
        getTopExpenseCategories(companyId, 5),
      ]);

    return apiResponse.success(res, {
      kpis,
      revenueChart,
      cashFlowChart,
      arAging,
      apAging,
      topCustomers,
      topExpenses,
    });
  } catch (err) {
    log.error('Failed to load KPI dashboard', { error: err }, 'accounting-api');
    return apiResponse.internalError(res, err, 'Failed to load KPI dashboard');
  }
}


export default withCompany(withErrorHandler(handler));

/**
 * GET /api/accounting/description-suggest
 * Auto-suggest descriptions from templates + GL history.
 * WS-6.5
 *
 * Query params:
 *   q           — search term (required)
 *   entity_type — optional filter (e.g. 'journal_entry')
 *   limit       — max results (default 10)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withCompany } from '@/lib/auth/withCompany';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { suggestDescriptions } from '@/modules/accounting/services/descriptionTemplateService';
import type { CompanyApiRequest } from '@/lib/auth/withCompany';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'unknown', ['GET']);
  }

  const companyReq = req as CompanyApiRequest;
  const companyId = companyReq.companyId;

  const q = (req.query.q as string | undefined) ?? '';
  const entityType = req.query.entity_type as string | undefined;
  const limit = Math.min(Number(req.query.limit ?? 10), 20);

  if (!q.trim()) {
    return apiResponse.success(res, { suggestions: [] });
  }

  const suggestions = await suggestDescriptions(companyId, q, entityType, limit);
  return apiResponse.success(res, { suggestions });
}

export default withCompany(withErrorHandler(handler) as any);

