import type { NextApiRequest, NextApiResponse } from 'next';
import { withAuth } from '@/lib/auth/middleware';
import type { AuthenticatedNextApiRequest } from '@/lib/auth/middleware';
import { apiResponse } from '@/lib/apiResponse';
import { generateTOTPSecret } from '@/modules/auth/services/twoFactorService';
import { log } from '@/lib/logger';
import { withErrorHandler } from '@/lib/api-error-handler';
import { checkRateLimit } from '@/lib/rateLimit';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'unknown', ['POST']);
  }

  const ip = (req.headers['x-forwarded-for'] as string)?.split(',')[0]?.trim() || req.socket.remoteAddress || 'unknown';
  if (checkRateLimit(`2fa-setup:${ip}`, { maxRequests: 5, windowMs: 15 * 60 * 1000 })) {
    return res.status(429).json({ success: false, error: 'Too many attempts. Try again later.' });
  }

  const { user } = req as AuthenticatedNextApiRequest;

  try {
    const result = await generateTOTPSecret(user.id, user.email);

    // Mask the raw secret — only expose QR code and URI
    return apiResponse.success(res, {
      uri: result.uri,
      qrCodeDataUrl: result.qrCodeDataUrl,
      secretMasked: result.secret.slice(0, 4) + '****',
    }, '2FA setup initiated');
  } catch (err) {
    log.error('2fa-setup error', err instanceof Error ? { message: err.message } : { err }, 'api/auth/2fa-setup');
    return apiResponse.internalError(res, err);
  }
}

export default withAuth(withErrorHandler(handler));

/**
 * GET  /api/auth/profile — returns current user's profile
 * PUT  /api/auth/profile — updates profile fields (email is read-only)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
type Row = Record<string, unknown>;


async function handler(req: NextApiRequest, res: NextApiResponse) {
  const authReq = req as AuthenticatedNextApiRequest;
  const userId = authReq.user.id;

  // ── GET ──────────────────────────────────────────────────────────────────
  if (req.method === 'GET') {
    const rows = (await sql`
      SELECT id, email, first_name, last_name, phone, mobile, role, profile_picture
      FROM users
      WHERE id = ${userId}
      LIMIT 1
    `) as Row[];

    if (!rows.length) {
      return apiResponse.notFound(res, 'User');
    }

    const u = rows[0]!;
    return apiResponse.success(res, {
      id: String(u.id),
      email: String(u.email),
      firstName: u.first_name != null ? String(u.first_name) : '',
      lastName: u.last_name != null ? String(u.last_name) : '',
      phone: u.phone != null ? String(u.phone) : '',
      mobile: u.mobile != null ? String(u.mobile) : '',
      role: String(u.role),
      profilePicture: u.profile_picture != null ? String(u.profile_picture) : null,
    });
  }

  // ── PUT ──────────────────────────────────────────────────────────────────
  if (req.method === 'PUT') {
    const { firstName, lastName, phone, mobile } = req.body as {
      firstName?: string;
      lastName?: string;
      phone?: string;
      mobile?: string;
    };

    if (!firstName?.trim() || !lastName?.trim()) {
      return apiResponse.badRequest(res, 'First name and last name are required');
    }

    const rows = (await sql`
      UPDATE users
      SET
        first_name = ${firstName.trim()},
        last_name  = ${lastName.trim()},
        phone      = ${phone?.trim() ?? null},
        mobile     = ${mobile?.trim() ?? null}
      WHERE id = ${userId}
      RETURNING id, email, first_name, last_name, phone, mobile
    `) as Row[];

    const u = rows[0]!;
    log.info('Profile updated', { userId }, 'auth/profile');

    return apiResponse.success(res, {
      id: String(u.id),
      email: String(u.email),
      firstName: u.first_name != null ? String(u.first_name) : '',
      lastName: u.last_name != null ? String(u.last_name) : '',
      phone: u.phone != null ? String(u.phone) : '',
      mobile: u.mobile != null ? String(u.mobile) : '',
    }, 'Profile updated successfully');
  }

  return apiResponse.methodNotAllowed(res, req.method ?? 'unknown', ['GET', 'PUT']);
}

export default withAuth(withErrorHandler(handler) as any);

/**
 * Admin User Suspend API
 * POST /api/admin/users/[id]/suspend — Suspend a user and invalidate sessions
 */

import type { NextApiResponse } from 'next';
import { type AuthenticatedNextApiRequest } from '@/lib/auth';
import { withAdmin } from '@/modules/admin/middleware/withAdmin';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { suspendUser } from '@/modules/admin/services/adminUserService';
import { logAdminAction } from '@/modules/admin/services/auditService';

function getIp(req: AuthenticatedNextApiRequest): string | null {
  return (
    (req.headers['x-forwarded-for'] as string)?.split(',')[0]?.trim() ||
    req.socket?.remoteAddress ||
    null
  );
}

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  const userId = req.query.id as string;

  if (req.method === 'POST') {
    try {
      const { reason } = req.body as { reason?: string };

      if (!reason || reason.trim().length === 0) {
        return apiResponse.badRequest(res, 'A suspension reason is required');
      }

      await suspendUser(userId, reason.trim());

      await logAdminAction(
        req.user.id,
        'user.suspend',
        'user',
        userId,
        { reason },
        getIp(req)
      );

      return apiResponse.success(res, { suspended: true });
    } catch (err) {
      log.error('Failed to suspend user', { userId, error: err }, 'admin-api');
      return apiResponse.badRequest(res, 'Failed to suspend user');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);
}

export default withAdmin(handler);

/**
 * Admin Billing Invoice Send API
 * POST /api/admin/billing/invoices/[id]/send — Send an invoice to the customer
 */

import type { NextApiResponse } from 'next';
import { type AuthenticatedNextApiRequest } from '@/lib/auth';
import { withAdmin } from '@/modules/admin/middleware/withAdmin';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { sendInvoice } from '@/modules/admin/services/invoiceService';
import { logAdminAction } from '@/modules/admin/services/auditService';

function getIp(req: AuthenticatedNextApiRequest): string | null {
  return (
    (req.headers['x-forwarded-for'] as string)?.split(',')[0]?.trim() ||
    req.socket?.remoteAddress ||
    null
  );
}

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  const id = req.query.id as string;

  if (req.method === 'POST') {
    try {
      await sendInvoice(id);

      await logAdminAction(
        req.user.id,
        'invoice.send',
        'invoice',
        id,
        null,
        getIp(req)
      );

      return apiResponse.success(res, { sent: true });
    } catch (err) {
      log.error('Failed to send invoice', { id, error: err }, 'admin-api');
      return apiResponse.badRequest(res, 'Failed to send invoice');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);
}

export default withAdmin(handler);

