import os
import re

base_dir = '/home/hein/Workspace/IsaFlow/pages/api/accounting'

findings = {
    'Code after return (actual)': [],
    'Switch without proper termination': [],
    'Contradictory conditions': [],
    'Unconditional true/false': [],
}

def analyze_file(filepath):
    with open(filepath, 'r', encoding='utf-8', errors='ignore') as f:
        lines = f.readlines()

    for i in range(len(lines) - 1):
        line = lines[i].rstrip()
        next_line = lines[i+1].rstrip() if i+1 < len(lines) else ''

        # Pattern 1: Simple return followed by non-closing code
        if re.match(r'^\s*return\s+[^;]*;?\s*$', line):
            next_stripped = next_line.lstrip()
            # Check if next line is actual code (not closing brace, comment, etc)
            if next_stripped and not re.match(r'^(}|else|catch|finally|/|import|export|type|interface|class|function)', next_stripped):
                # Make sure it's not a ternary or property continuation
                if '{' not in line and '[' not in line and '(' not in line:
                    findings['Code after return (actual)'].append((filepath, i+1))

        # Pattern 2: if(true) or if(false)
        if re.search(r'if\s*\(\s*(true|false)\s*\)', line):
            findings['Unconditional true/false'].append((filepath, i+1, re.search(r'if\s*\(\s*(true|false)\s*\)', line).group(1)))

        # Pattern 3: Contradictory conditions like (x && !x)
        if re.search(r'(\w+)\s*&&\s*!\1|!\1\s*&&\s*\1', line):
            findings['Contradictory conditions'].append((filepath, i+1))

# Walk files
for root, dirs, files in os.walk(base_dir):
