/**
 * Bank Transaction Actions API
 * POST /api/accounting/bank-transactions-action
 *   action: match | unmatch | exclude | auto_match | allocate | delete | update_notes
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';
import {
  matchTransaction,
  unmatchTransaction,
  excludeTransaction,
  autoMatchTransactions,
  allocateTransaction,
  splitAllocateTransaction,
  deleteTransactions,
  bulkAcceptTransactions,
  reverseReconciledTransaction,
  type AllocationType,
  type SplitLine,
} from '@/modules/accounting/services/bankReconciliationService';

async function handler(req: CompanyApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);
  }

  const { companyId } = req;

  try {
    const { action, bankTransactionId, journalLineId, bankAccountId, reconciliationId, contraAccountId, description, allocationType, entityId, vatCode, excludeReason, cc1Id, cc2Id, buId } = req.body;
    const userId: string = req.user?.id || req.user?.userId || 'system';

    if (!action) return apiResponse.badRequest(res, 'action is required');

    switch (action) {
      case 'match': {
        if (!bankTransactionId || !journalLineId) {
          return apiResponse.badRequest(res, 'bankTransactionId and journalLineId are required');
        }
        const tx = await matchTransaction(companyId, bankTransactionId, journalLineId, reconciliationId);
        return apiResponse.success(res, tx);
      }
      case 'unmatch': {
        if (!bankTransactionId) return apiResponse.badRequest(res, 'bankTransactionId is required');
        const tx = await unmatchTransaction(companyId, bankTransactionId);
        return apiResponse.success(res, tx);
      }
      case 'exclude': {
        if (!bankTransactionId) return apiResponse.badRequest(res, 'bankTransactionId is required');
        const tx = await excludeTransaction(
          companyId, bankTransactionId,
          typeof excludeReason === 'string' ? excludeReason : undefined,
        );
        return apiResponse.success(res, tx);
      }
      case 'auto_match': {
        if (!bankAccountId) return apiResponse.badRequest(res, 'bankAccountId is required');
        const result = await autoMatchTransactions(companyId, bankAccountId, reconciliationId);
        return apiResponse.success(res, result);
      }
      case 'allocate': {
        const aType: AllocationType = allocationType || 'account';
        if (aType === 'account' && !contraAccountId) {
          return apiResponse.badRequest(res, 'contraAccountId is required for account allocation');
        }
        if ((aType === 'supplier' || aType === 'customer') && !entityId) {
          return apiResponse.badRequest(res, 'entityId is required for supplier/customer allocation');
        }
        if (!bankTransactionId) {
          return apiResponse.badRequest(res, 'bankTransactionId is required');
        }
        const result = await allocateTransaction(
          companyId, bankTransactionId, contraAccountId || null, userId, description, aType, entityId, vatCode,
          cc1Id, cc2Id, buId,
        );
        return apiResponse.success(res, result);
      }
      case 'split_allocate': {
        const { bankTransactionId: splitTxId, lines: splitLines } = req.body as {
          bankTransactionId?: string;
          lines?: SplitLine[];
        };
        if (!splitTxId || !splitLines || !Array.isArray(splitLines) || splitLines.length === 0) {
          return apiResponse.badRequest(res, 'bankTransactionId and lines[] (non-empty) are required');
        }
        const splitResult = await splitAllocateTransaction(companyId, splitTxId, splitLines, userId);
        return apiResponse.success(res, splitResult);
      }
      case 'delete': {
        const { bankTransactionIds } = req.body;
        const ids: string[] = bankTransactionIds || (bankTransactionId ? [bankTransactionId] : []);
        if (ids.length === 0) return apiResponse.badRequest(res, 'bankTransactionId or bankTransactionIds required');
        const deleted = await deleteTransactions(companyId, ids);
        return apiResponse.success(res, { deleted });
      }
      case 'bulk_accept': {
        const { bankTransactionIds: bulkIds } = req.body;
        const ids: string[] = Array.isArray(bulkIds) ? bulkIds : [];
        if (ids.length === 0) return apiResponse.badRequest(res, 'bankTransactionIds (array) required');
        const accepted = await bulkAcceptTransactions(companyId, ids);
        return apiResponse.success(res, { accepted });
      }
      case 'update_notes': {
        if (!bankTransactionId) return apiResponse.badRequest(res, 'bankTransactionId required');
        const { notes } = req.body as { notes?: string };
        await sql`
          UPDATE bank_transactions
          SET notes = ${notes || null}, updated_at = NOW()
          WHERE id = ${bankTransactionId}::UUID AND company_id = ${companyId}
        `;
        log.info('Updated bank transaction notes', { bankTransactionId }, 'accounting-api');
        return apiResponse.success(res, { updated: true });
      }
      case 'save_selection': {
        if (!bankTransactionId) return apiResponse.badRequest(res, 'bankTransactionId required');
        const selType: string = req.body.selectionType || 'account';
        const selEntityId: string | null = req.body.selectionEntityId || null;
        const selVatCode: string | null = req.body.vatCode || null;
        await sql`
          UPDATE bank_transactions
          SET suggested_gl_account_id = ${selType === 'account' && selEntityId ? selEntityId : null}::UUID,
              suggested_supplier_id = ${selType === 'supplier' && selEntityId ? selEntityId : null}::UUID,
              suggested_client_id = ${selType === 'customer' && selEntityId ? selEntityId : null}::UUID,
              suggested_vat_code = ${selVatCode},
              updated_at = NOW()
          WHERE id = ${bankTransactionId}::UUID AND status IN ('imported', 'allocated') AND company_id = ${companyId}
        `;
        return apiResponse.success(res, { saved: true });
      }
      case 'save_dimensions': {
        if (!bankTransactionId) return apiResponse.badRequest(res, 'bankTransactionId required');
        await sql`
          UPDATE bank_transactions
          SET cc1_id = ${cc1Id || null}::UUID,
              cc2_id = ${cc2Id || null}::UUID,
              bu_id = ${buId || null}::UUID,
              updated_at = NOW()
          WHERE id = ${bankTransactionId}::UUID AND company_id = ${companyId}
        `;
        return apiResponse.success(res, { saved: true });
      }
      case 'reverse': {
        if (!bankTransactionId) return apiResponse.badRequest(res, 'bankTransactionId required');
        await reverseReconciledTransaction(companyId, bankTransactionId, userId);
        return apiResponse.success(res, { reversed: true });
      }
      default:
        return apiResponse.badRequest(res, `Unknown action: ${action}`);
    }
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Action failed';
    log.error('Bank transaction action failed', { error: err }, 'accounting-api');
    return apiResponse.badRequest(res, message);
  }
}


export default withCompany(withErrorHandler(handler));

/**
 * Customer Receipt Allocations API
 * GET  — List existing allocations (audit trail)
 * POST — Allocate receipts against outstanding invoices
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { sql } from '@/lib/neon';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { withErrorHandler } from '@/lib/api-error-handler';

interface AllocationItem {
  invoiceId: string;
  amount: number;
}

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;

  if (req.method === 'GET') {
    try {
      const paymentId = req.query.payment_id as string | undefined;
      const clientId = req.query.client_id as string | undefined;

      let rows;
      if (paymentId) {
        rows = await sql`
          SELECT cpa.id, cpa.payment_id, cpa.invoice_id, cpa.amount_allocated AS amount,
            cpa.created_at AS allocated_at, cp.payment_number, ci.invoice_number,
            c.name AS client_name
          FROM customer_payment_allocations cpa
          JOIN customer_payments cp ON cp.id = cpa.payment_id
          JOIN customer_invoices ci ON ci.id = cpa.invoice_id
          JOIN customers c ON c.id = cp.client_id
          WHERE cpa.payment_id = ${paymentId}
            AND cp.company_id = ${companyId}
          ORDER BY cpa.created_at DESC
        `;
      } else if (clientId) {
        rows = await sql`
          SELECT cpa.id, cpa.payment_id, cpa.invoice_id, cpa.amount_allocated AS amount,
            cpa.created_at AS allocated_at, cp.payment_number, ci.invoice_number,
            c.name AS client_name
          FROM customer_payment_allocations cpa
          JOIN customer_payments cp ON cp.id = cpa.payment_id
          JOIN customer_invoices ci ON ci.id = cpa.invoice_id
          JOIN customers c ON c.id = cp.client_id
          WHERE cp.client_id = ${clientId}
            AND cp.company_id = ${companyId}
          ORDER BY cpa.created_at DESC
          LIMIT 200
        `;
      } else {
        rows = await sql`
          SELECT cpa.id, cpa.payment_id, cpa.invoice_id, cpa.amount_allocated AS amount,
            cpa.created_at AS allocated_at, cp.payment_number, ci.invoice_number,
            c.name AS client_name
          FROM customer_payment_allocations cpa
          JOIN customer_payments cp ON cp.id = cpa.payment_id
          JOIN customer_invoices ci ON ci.id = cpa.invoice_id
          JOIN customers c ON c.id = cp.client_id
          WHERE cp.company_id = ${companyId}
          ORDER BY cpa.created_at DESC
          LIMIT 200
        `;
      }

      return apiResponse.success(res, rows);
    } catch (err) {
      log.error('Failed to get customer allocations', { error: err });
      return apiResponse.badRequest(res, 'Failed to get allocations');
    }
  }

  if (req.method === 'POST') {
    try {
      const { paymentId, allocations } = req.body as {
        paymentId?: string;
        allocations?: AllocationItem[];
      };

      if (!paymentId) return apiResponse.badRequest(res, 'paymentId is required');
      if (!allocations || !Array.isArray(allocations) || allocations.length === 0) {
        return apiResponse.badRequest(res, 'allocations array is required');
      }

      // Validate allocation items
      for (const alloc of allocations) {
        if (!alloc.invoiceId || !alloc.amount || alloc.amount <= 0) {
          return apiResponse.badRequest(res, 'Each allocation needs invoiceId and positive amount');
        }
      }

      // Fetch payment
      const paymentRows = await sql`
        SELECT cp.id, cp.client_id, cp.total_amount, cp.status,
          COALESCE((SELECT SUM(amount_allocated) FROM customer_payment_allocations WHERE payment_id = cp.id), 0) AS allocated_amount
        FROM customer_payments cp WHERE cp.id = ${paymentId} AND cp.company_id = ${companyId}
      `;
      const payment = paymentRows[0];
      if (!payment) return apiResponse.notFound(res, 'Payment', paymentId);
      if (payment.status === 'cancelled') {
        return apiResponse.badRequest(res, 'Cannot allocate a cancelled payment');
      }

      const currentAllocated = Number(payment.allocated_amount || 0);
      const totalPayment = Number(payment.total_amount);
      const allocTotal = allocations.reduce((s, a) => s + a.amount, 0);

      if (currentAllocated + allocTotal > totalPayment + 0.01) {
        return apiResponse.badRequest(res, `Allocation total (${allocTotal}) exceeds available balance (${(totalPayment - currentAllocated).toFixed(2)})`);
      }

      // Process each allocation
      const results: { invoiceId: string; amount: number; newStatus: string }[] = [];

      for (const alloc of allocations) {
        // Validate invoice belongs to same client
        const invoiceRows = await sql`
          SELECT id, client_id, total_amount, amount_paid, status
          FROM customer_invoices WHERE id = ${alloc.invoiceId} AND company_id = ${companyId}
        `;
        const invoice = invoiceRows[0];
        if (!invoice) {
          return apiResponse.badRequest(res, `Invoice ${alloc.invoiceId} not found`);
        }
        if (invoice.client_id !== payment.client_id) {
          return apiResponse.badRequest(res, `Invoice ${alloc.invoiceId} belongs to a different client`);
        }

        const outstanding = Number(invoice.total_amount) - Number(invoice.amount_paid || 0);
        if (alloc.amount > outstanding + 0.01) {
          return apiResponse.badRequest(res, `Allocation ${alloc.amount} exceeds outstanding ${outstanding.toFixed(2)} for invoice ${alloc.invoiceId}`);
        }

        // Insert allocation record
        await sql`
          INSERT INTO customer_payment_allocations (payment_id, invoice_id, amount_allocated)
          VALUES (${paymentId}, ${alloc.invoiceId}, ${alloc.amount})
        `;

        // Update invoice amount_paid
        const newPaid = Number(invoice.amount_paid || 0) + alloc.amount;
        const invoiceTotal = Number(invoice.total_amount);
        const newStatus = newPaid >= invoiceTotal - 0.01 ? 'paid' : 'partially_paid';

        await sql`
          UPDATE customer_invoices
          SET amount_paid = ${newPaid}, status = ${newStatus}
          WHERE id = ${alloc.invoiceId}
        `;

        results.push({ invoiceId: alloc.invoiceId, amount: alloc.amount, newStatus });
      }

      // Update payment allocated_amount
      const newAllocated = currentAllocated + allocTotal;
      const paymentStatus = newAllocated >= totalPayment - 0.01 ? 'reconciled' : 'confirmed';

      await sql`
        UPDATE customer_payments
        SET status = ${paymentStatus}
        WHERE id = ${paymentId}
      `;

      log.info('Customer allocations created', {
        paymentId,
        count: results.length,
        total: allocTotal,
      });

      return apiResponse.success(res, {
        paymentId,
        allocations: results,
        newAllocatedAmount: newAllocated,
        paymentStatus,
      });
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Allocation failed';
      log.error('Customer allocation failed', { error: err });
      return apiResponse.badRequest(res, message);
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}

export default withCompany(withErrorHandler(handler));

/**
 * Accounting Dashboard Stats API
 * GET /api/accounting/dashboard-stats
 * Returns aggregated financial metrics for the dashboard overview
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);
  }

  const { companyId } = req as CompanyApiRequest;

  try {
    const now = new Date();
    const year = now.getFullYear();
    const month = now.getMonth() + 1;
    const monthStart = `${year}-${String(month).padStart(2, '0')}-01`;

    // Run all queries in parallel
    const [
      bankBalances,
      apTotal,
      arTotal,
      monthRevenue,
      monthExpenses,
      unallocatedCount,
      recentJournals,
    ] = await Promise.all([
      // Bank account balances (from bank_transactions, matching bank-accounts API)
      sql`
        SELECT ga.account_code, ga.account_name,
          COALESCE(SUM(CASE WHEN bt.amount > 0 THEN bt.amount ELSE 0 END), 0)
          - COALESCE(SUM(CASE WHEN bt.amount < 0 THEN ABS(bt.amount) ELSE 0 END), 0) AS balance
        FROM gl_accounts ga
        LEFT JOIN bank_transactions bt ON bt.bank_account_id = ga.id
        WHERE ga.account_subtype = 'bank' AND ga.is_active = true AND ga.company_id = ${companyId}
        GROUP BY ga.id, ga.account_code, ga.account_name
        ORDER BY ga.account_code
      `,
      // Accounts Payable total (from supplier_invoices, matching AP aging)
      sql`
        SELECT COALESCE(SUM(total_amount - COALESCE(amount_paid, 0)), 0) AS total
        FROM supplier_invoices
        WHERE company_id = ${companyId} AND status NOT IN ('cancelled', 'paid')
      `,
      // Accounts Receivable total (from customer_invoices, matching AR aging)
      sql`
        SELECT COALESCE(SUM(total_amount - COALESCE(amount_paid, 0)), 0) AS total
        FROM customer_invoices
        WHERE company_id = ${companyId} AND status NOT IN ('cancelled', 'paid')
      `,
      // Revenue this month (account_type = 'revenue')
      sql`
        SELECT COALESCE(SUM(credit - debit), 0) AS total
        FROM gl_journal_lines jl
        JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
        JOIN gl_accounts ga ON ga.id = jl.gl_account_id
        WHERE ga.account_type = 'revenue' AND je.status = 'posted'
          AND je.company_id = ${companyId} AND je.entry_date >= ${monthStart}
      `,
      // Expenses this month (account_type = 'expense')
      sql`
        SELECT COALESCE(SUM(debit - credit), 0) AS total
        FROM gl_journal_lines jl
        JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
        JOIN gl_accounts ga ON ga.id = jl.gl_account_id
        WHERE ga.account_type = 'expense' AND je.status = 'posted'
          AND je.company_id = ${companyId} AND je.entry_date >= ${monthStart}
      `,
      // Unallocated bank transactions
      sql`
        SELECT COUNT(*) AS count FROM bank_transactions WHERE company_id = ${companyId} AND status = 'imported'
      `,
      // Recent journal entries (last 5)
      sql`
        SELECT id, entry_date, description, source, status,
          (SELECT SUM(debit) FROM gl_journal_lines WHERE journal_entry_id = je.id) AS total_debit
        FROM gl_journal_entries je
        WHERE je.company_id = ${companyId}
        ORDER BY created_at DESC LIMIT 5
      `,
    ]);

    const banks = (bankBalances as { account_code: string; account_name: string; balance: string }[]).map(b => ({
      code: b.account_code,
      name: b.account_name,
      balance: Number(b.balance),
    }));

    return apiResponse.success(res, {
      banks,
      totalBankBalance: banks.reduce((sum, b) => sum + b.balance, 0),
      apTotal: Number((apTotal as { total: string }[])[0]?.total || 0),
      arTotal: Number((arTotal as { total: string }[])[0]?.total || 0),
      monthRevenue: Number((monthRevenue as { total: string }[])[0]?.total || 0),
      monthExpenses: Number((monthExpenses as { total: string }[])[0]?.total || 0),
      unallocatedTx: Number((unallocatedCount as { count: string }[])[0]?.count || 0),
      recentJournals: (recentJournals as Record<string, unknown>[]).map(j => ({
        id: j.id,
        date: j.entry_date,
        description: j.description,
        source: j.source,
        status: j.status,
        amount: Number(j.total_debit || 0),
      })),
    });
  } catch (err) {
    log.error('Failed to load dashboard stats', { error: err }, 'accounting-api');
    return apiResponse.badRequest(res, 'Failed to load dashboard stats');
  }
}


export default withCompany(withErrorHandler(handler));

/**
 * Stock Adjustments API — increase/decrease/write-off stock
 */
import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type AuthenticatedNextApiRequest, type CompanyApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { validateStockAdjustment } from '@/modules/accounting/services/inventoryService';
type Row = Record<string, unknown>;

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;

  if (req.method === 'GET') {
    const adjustments = await sql`
      SELECT sa.*, p.code as product_code, p.name as product_name
      FROM stock_adjustments sa JOIN products p ON sa.product_id = p.id
      WHERE sa.company_id = ${companyId}::UUID
      ORDER BY sa.created_at DESC LIMIT 200
    ` as Row[];
    return apiResponse.success(res, adjustments);
  }
  if (req.method === 'POST') {
    const body = req.body;
    const validation = validateStockAdjustment(body);
    if (!validation.success) return apiResponse.validationError(res, Object.fromEntries((validation.errors || []).map(e => [e.field, e.message])));

    const countRes = await sql`SELECT COUNT(*) as cnt FROM stock_adjustments WHERE company_id = ${companyId}::UUID` as Row[];
    const adjNum = `ADJ-${String(Number((countRes[0] as any)?.cnt || 0) + 1).padStart(5, '0')}`;

    const inserted = await sql`
      INSERT INTO stock_adjustments (company_id, adjustment_number, product_id, warehouse_id, adjustment_type, quantity, unit_cost, reason, created_by)
      VALUES (${companyId}::UUID, ${adjNum}, ${body.productId}, ${body.warehouseId || null}, ${body.adjustmentType}, ${body.quantity}, ${body.unitCost || 0}, ${body.reason}, ${String(req.user.id)})
      RETURNING *
    ` as Row[];

    // Update product stock (scoped to company via product ownership)
    const sign = ['increase', 'count'].includes(body.adjustmentType) ? 1 : -1;
    await sql`UPDATE products SET current_stock = GREATEST(0, current_stock + ${sign * body.quantity}), updated_at = NOW() WHERE id = ${body.productId} AND company_id = ${companyId}::UUID`;

    // Record movement
    const movementType = body.adjustmentType === 'increase' ? 'adjustment_in' : body.adjustmentType === 'write_off' ? 'write_off' : 'adjustment_out';
    await sql`INSERT INTO stock_movements (company_id, product_id, warehouse_id, movement_type, quantity, unit_cost, total_cost, reference_type, reference_id, created_by) VALUES (${companyId}::UUID, ${body.productId}, ${body.warehouseId || null}, ${movementType}, ${body.quantity}, ${body.unitCost || 0}, ${(body.unitCost || 0) * body.quantity}, 'stock_adjustment', ${String(inserted[0]?.id)}, ${String(req.user.id)})`;

    log.info('Stock adjusted', { adjNum, type: body.adjustmentType, qty: body.quantity }, 'accounting');
    return apiResponse.created(res, inserted[0]);
  }
  return apiResponse.methodNotAllowed(res, req.method!, ['GET', 'POST']);
}
export default withCompany(withErrorHandler(handler));

