  approved: 'bg-teal-500/20 text-teal-500',
  rejected: 'bg-red-500/20 text-red-500',
  cancelled: 'bg-gray-500/20 text-gray-500',
};

export default function ApprovalsPage() {
  const [tab, setTab] = useState<'pending' | 'rules' | 'history'>('pending');
  const [requests, setRequests] = useState<ApprovalRequest[]>([]);
  const [rules, setRules] = useState<ApprovalRule[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [deciding, setDeciding] = useState<string | null>(null);

  const fetchData = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const [reqRes, rulesRes] = await Promise.all([
        apiFetch(tab === 'pending' ? '/api/accounting/approval-requests?status=pending' : '/api/accounting/approval-requests'),
        apiFetch('/api/accounting/approval-rules'),
      ]);
      if (!reqRes.ok || !rulesRes.ok) throw new Error('Failed to load');
      const reqJson = await reqRes.json();
      const rulesJson = await rulesRes.json();
      setRequests(reqJson.data?.items ?? []);
      setRules(rulesJson.data?.items ?? []);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load');
    } finally {
      setLoading(false);
    }
  }, [tab]);

  useEffect(() => { void fetchData(); }, [fetchData]);

  const handleDecision = async (requestId: string, action: 'approve' | 'reject') => {
    setDeciding(requestId);
    try {
      const res = await apiFetch('/api/accounting/approval-requests', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action, requestId }),
      });
      if (!res.ok) throw new Error('Failed');
      await fetchData();
    } catch {
      setError('Failed to process decision');
    } finally {
      setDeciding(null);
    }
  };

  const handleDeleteRule = async (ruleId: string) => {
    try {
      await apiFetch(`/api/accounting/approval-rules?id=${ruleId}`, { method: 'DELETE' });
      await fetchData();
    } catch {
      setError('Failed to delete rule');
    }
  };

  const pendingCount = requests.filter(r => r.status === 'pending').length;

  return (
    <AppLayout>
      <div className="p-4 lg:p-6 space-y-6">
        {/* Header */}
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="p-2 rounded-lg bg-teal-500/10">
              <Shield className="h-6 w-6 text-teal-500" />
            </div>
            <div>
              <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Approvals</h1>
              <p className="text-sm text-[var(--ff-text-secondary)]">
                Review and manage approval workflows
              </p>
            </div>
          </div>
          {pendingCount > 0 && (
            <div className="bg-amber-500/20 text-amber-500 px-3 py-1 rounded-full text-sm font-medium">
              {pendingCount} pending
            </div>
          )}
        </div>

        {/* Tabs */}
        <div className="flex gap-1 border-b border-[var(--ff-border-primary)]">
          {(['pending', 'history', 'rules'] as const).map(t => (
            <button
              key={t}
              onClick={() => setTab(t)}
              className={`px-4 py-2.5 text-sm font-medium border-b-2 transition-colors capitalize ${
                tab === t
                  ? 'border-teal-500 text-teal-500'
                  : 'border-transparent text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)]'
              }`}
            >
              {t === 'pending' ? `Pending (${pendingCount})` : t}
            </button>
          ))}
        </div>

        {error && (
          <div className="bg-red-500/10 border border-red-500/30 rounded-lg p-3 flex items-center gap-2 text-red-500 text-sm">
            <AlertCircle className="h-4 w-4" /> {error}
          </div>
        )}

        {loading ? (
          <div className="flex justify-center py-12">
            <Loader2 className="h-8 w-8 animate-spin text-teal-500" />
          </div>
        ) : tab === 'rules' ? (
          /* Rules Tab */
          <div className="bg-[var(--ff-surface-primary)] border border-[var(--ff-border-primary)] rounded-xl overflow-hidden">
            <table className="w-full text-sm">
              <thead>
                <tr className="bg-[var(--ff-bg-secondary)]">
                  <th className="text-left px-4 py-3 font-medium text-[var(--ff-text-secondary)]">Rule Name</th>
                  <th className="text-left px-4 py-3 font-medium text-[var(--ff-text-secondary)]">Document Type</th>
                  <th className="text-left px-4 py-3 font-medium text-[var(--ff-text-secondary)]">Condition</th>
                  <th className="text-left px-4 py-3 font-medium text-[var(--ff-text-secondary)]">Approver</th>
                  <th className="text-center px-4 py-3 font-medium text-[var(--ff-text-secondary)]">Active</th>
                  <th className="text-center px-4 py-3 font-medium text-[var(--ff-text-secondary)]">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-[var(--ff-border-primary)]">
                {rules.length === 0 ? (
                  <tr><td colSpan={6} className="px-4 py-8 text-center text-[var(--ff-text-secondary)]">No approval rules configured</td></tr>
                ) : rules.map(rule => (
                  <tr key={rule.id} className="hover:bg-[var(--ff-bg-hover)]">
                    <td className="px-4 py-3 text-[var(--ff-text-primary)] font-medium">{rule.name}</td>
                    <td className="px-4 py-3 text-[var(--ff-text-secondary)]">{DOC_TYPE_LABELS[rule.documentType] || rule.documentType}</td>
                    <td className="px-4 py-3 text-[var(--ff-text-secondary)]">
                      {rule.conditionOperator === 'any' ? 'All documents' : `${rule.conditionField} > ${formatCurrency(rule.conditionValue)}`}
                    </td>
                    <td className="px-4 py-3 text-[var(--ff-text-secondary)] capitalize">{rule.approverRole}</td>
                    <td className="px-4 py-3 text-center">
                      <span className={`inline-block w-2 h-2 rounded-full ${rule.isActive ? 'bg-teal-500' : 'bg-gray-400'}`} />
                    </td>
                    <td className="px-4 py-3 text-center">
                      <button onClick={() => void handleDeleteRule(rule.id)} className="text-red-400 hover:text-red-500">
                        <Trash2 className="h-4 w-4" />
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        ) : (
          /* Pending / History Tab */
          <div className="space-y-3">
            {requests.length === 0 ? (
              <div className="text-center py-12 text-[var(--ff-text-secondary)]">
                {tab === 'pending' ? 'No pending approvals' : 'No approval history'}
              </div>
            ) : requests.filter(r => tab === 'pending' ? r.status === 'pending' : true).map(req => (
              <div
                key={req.id}
                className="bg-[var(--ff-surface-primary)] border border-[var(--ff-border-primary)] rounded-xl p-4 flex items-center gap-4"
              >
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2 mb-1">
                    <span className={`px-2 py-0.5 rounded-full text-xs font-medium ${STATUS_STYLES[req.status] || ''}`}>
                      {req.status}
                    </span>
                    <span className="text-xs text-[var(--ff-text-tertiary)]">
                      {DOC_TYPE_LABELS[req.documentType] || req.documentType}
                    </span>
                    {req.ruleName && (
                      <span className="text-xs text-[var(--ff-text-tertiary)]">• {req.ruleName}</span>
                    )}
                  </div>
                  <p className="text-sm font-medium text-[var(--ff-text-primary)]">
                    {req.documentReference || req.documentId.slice(0, 8)}
                    {req.amount != null && <span className="ml-2 text-teal-500">{formatCurrency(req.amount)}</span>}
                  </p>
                  <p className="text-xs text-[var(--ff-text-tertiary)] mt-1">
                    Requested by {req.requestedByName || 'Unknown'} • {new Date(req.requestedAt).toLocaleDateString('en-ZA')}
                    {req.decidedByName && ` • Decided by ${req.decidedByName}`}
                  </p>
                </div>

                {req.status === 'pending' && (
                  <div className="flex gap-2 flex-shrink-0">
                    <button
                      onClick={() => void handleDecision(req.id, 'approve')}
                      disabled={deciding === req.id}
                      className="flex items-center gap-1 px-3 py-1.5 bg-teal-600 hover:bg-teal-700 text-white rounded-lg text-sm font-medium transition-colors disabled:opacity-50"
                    >
                      <CheckCircle2 className="h-4 w-4" /> Approve
                    </button>
                    <button
                      onClick={() => void handleDecision(req.id, 'reject')}
                      disabled={deciding === req.id}
                      className="flex items-center gap-1 px-3 py-1.5 bg-red-600 hover:bg-red-700 text-white rounded-lg text-sm font-medium transition-colors disabled:opacity-50"
                    >
                      <XCircle className="h-4 w-4" /> Reject
                    </button>
                  </div>
                )}
              </div>
            ))}
          </div>
        )}
      </div>
    </AppLayout>
  );
}

/**
 * Bank Feeds — Manage live bank connections via Stitch
 * Connect bank accounts, sync transactions, view sync history
 */

import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import {
  Wifi, WifiOff, RefreshCw, Loader2, AlertCircle, CheckCircle2,
  Link2, Unlink, Clock, ArrowDownCircle, XCircle,
} from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';

interface Connection {
  id: string;
  bankAccountId: string;
  bankAccountName?: string;
  provider: string;
  bankName: string | null;
  accountNumberMasked: string | null;
  branchCode: string | null;
  lastSyncAt: string | null;
  syncStatus: string;
  syncError: string | null;
  isActive: boolean;
}

interface SyncLog {
  id: string;
  syncType: string;
  fetched: number;
  imported: number;
  skipped: number;
  startedAt: string;
  completedAt: string | null;
  status: string;
  error: string | null;
}

const SYNC_STATUS_STYLES: Record<string, { cls: string; label: string }> = {
  synced: { cls: 'bg-teal-500/20 text-teal-500', label: 'Connected' },
  syncing: { cls: 'bg-blue-500/20 text-blue-500', label: 'Syncing...' },
  pending: { cls: 'bg-amber-500/20 text-amber-500', label: 'Pending' },
  error: { cls: 'bg-red-500/20 text-red-500', label: 'Error' },
};

export default function BankFeedsPage() {
  const [connections, setConnections] = useState<Connection[]>([]);
  const [configured, setConfigured] = useState<boolean | null>(null);
  const [loading, setLoading] = useState(true);
  const [syncing, setSyncing] = useState<string | null>(null);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [selectedHistory, setSelectedHistory] = useState<{ connectionId: string; logs: SyncLog[] } | null>(null);

  const fetchData = useCallback(async () => {
    setLoading(true);
    try {
      const [statusRes, connRes] = await Promise.all([
        apiFetch('/api/bank-feeds/connections?action=status'),
        apiFetch('/api/bank-feeds/connections'),
      ]);
      const statusJson = await statusRes.json();
      const connJson = await connRes.json();
      setConfigured(statusJson.data?.configured ?? false);
      setConnections(connJson.data?.items ?? []);
    } catch {
      setError('Failed to load connections');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { void fetchData(); }, [fetchData]);

  const handleConnect = async () => {
    setError('');
    try {
      const res = await apiFetch('/api/bank-feeds/connect');
      const json = await res.json();
      if (!res.ok) throw new Error(json.error?.message || 'Failed');
      window.location.href = json.data.url;
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to initiate connection');
    }
  };

  const handleSync = async (connectionId: string) => {
    setSyncing(connectionId);
    setError('');
    setSuccess('');
    try {
      const res = await apiFetch('/api/bank-feeds/connections', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'sync', connectionId }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json.error?.message || 'Sync failed');
      const r = json.data;
      setSuccess(`Synced: ${r.imported} new transactions imported, ${r.skipped} duplicates skipped`);
      await fetchData();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Sync failed');
    } finally {
      setSyncing(null);
    }
  };

  const handleDisconnect = async (connectionId: string) => {
    try {
      await apiFetch('/api/bank-feeds/connections', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'disconnect', connectionId }),
      });
      await fetchData();
    } catch {
      setError('Failed to disconnect');
    }
  };

  const handleViewHistory = async (connectionId: string) => {
    try {
      const res = await apiFetch(`/api/bank-feeds/connections?action=history&connectionId=${connectionId}`);
      const json = await res.json();
      setSelectedHistory({ connectionId, logs: json.data?.items ?? [] });
    } catch {
      setError('Failed to load sync history');
    }
  };

  return (
    <AppLayout>
      <div className="p-4 lg:p-6 space-y-6">
        {/* Header */}
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="p-2 rounded-lg bg-teal-500/10">
              <Wifi className="h-6 w-6 text-teal-500" />
            </div>
            <div>
              <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Bank Feeds</h1>
              <p className="text-sm text-[var(--ff-text-secondary)]">
                Live bank transaction sync via Stitch
              </p>
            </div>
          </div>
          {configured && (
            <button
              onClick={() => void handleConnect()}
              className="flex items-center gap-2 px-4 py-2 bg-teal-600 hover:bg-teal-700 text-white rounded-lg text-sm font-medium transition-colors"
            >
              <Link2 className="h-4 w-4" />
              Connect Bank
            </button>
          )}
        </div>

        {error && (
          <div className="bg-red-500/10 border border-red-500/30 rounded-lg p-3 flex items-center gap-2 text-red-500 text-sm">
            <AlertCircle className="h-4 w-4 flex-shrink-0" /> {error}
            <button onClick={() => setError('')} className="ml-auto"><XCircle className="h-4 w-4" /></button>
          </div>
        )}
        {success && (
          <div className="bg-teal-500/10 border border-teal-500/30 rounded-lg p-3 flex items-center gap-2 text-teal-500 text-sm">
            <CheckCircle2 className="h-4 w-4 flex-shrink-0" /> {success}
            <button onClick={() => setSuccess('')} className="ml-auto"><XCircle className="h-4 w-4" /></button>
          </div>
        )}

        {loading ? (
          <div className="flex justify-center py-12">
            <Loader2 className="h-8 w-8 animate-spin text-teal-500" />
          </div>
        ) : configured === false ? (
          <div className="bg-[var(--ff-surface-primary)] border border-[var(--ff-border-primary)] rounded-xl p-8 text-center">
            <WifiOff className="h-12 w-12 text-[var(--ff-text-tertiary)] mx-auto mb-4" />
            <h2 className="text-lg font-semibold text-[var(--ff-text-primary)] mb-2">Bank Feeds Not Configured</h2>
            <p className="text-sm text-[var(--ff-text-secondary)] mb-4">
              Set the following environment variables to enable live bank feeds:
            </p>
            <div className="bg-[var(--ff-bg-secondary)] rounded-lg p-4 text-left max-w-md mx-auto font-mono text-xs text-[var(--ff-text-secondary)]">
              <p>STITCH_CLIENT_ID=your_client_id</p>
              <p>STITCH_CLIENT_SECRET=your_secret</p>
              <p>STITCH_REDIRECT_URI=https://app.isaflow.co.za/api/bank-feeds/callback</p>
            </div>
            <p className="text-xs text-[var(--ff-text-tertiary)] mt-4">
              Sign up at stitch.money to get your API credentials
            </p>
          </div>
        ) : connections.length === 0 ? (
          <div className="bg-[var(--ff-surface-primary)] border border-[var(--ff-border-primary)] rounded-xl p-8 text-center">
            <Wifi className="h-12 w-12 text-[var(--ff-text-tertiary)] mx-auto mb-4" />
            <h2 className="text-lg font-semibold text-[var(--ff-text-primary)] mb-2">No Bank Connections</h2>
            <p className="text-sm text-[var(--ff-text-secondary)] mb-4">
              Connect your bank account to automatically import transactions daily.
            </p>
            <button
              onClick={() => void handleConnect()}
              className="px-6 py-2.5 bg-teal-600 hover:bg-teal-700 text-white rounded-lg text-sm font-medium transition-colors"
            >
              Connect Your First Bank
            </button>
          </div>
        ) : (
          <div className="space-y-4">
            {connections.map(conn => {
              const status = SYNC_STATUS_STYLES[conn.syncStatus] ?? SYNC_STATUS_STYLES['pending']!;
              return (
                <div
                  key={conn.id}
                  className="bg-[var(--ff-surface-primary)] border border-[var(--ff-border-primary)] rounded-xl p-5"
                >
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-4">
                      <div className="w-10 h-10 bg-teal-500/10 rounded-lg flex items-center justify-center">
                        <Wifi className="h-5 w-5 text-teal-500" />
                      </div>
                      <div>
                        <h3 className="font-semibold text-[var(--ff-text-primary)]">
                          {conn.bankAccountName || conn.bankName || 'Bank Account'}
                        </h3>
                        <p className="text-xs text-[var(--ff-text-secondary)]">
                          {conn.bankName && `${conn.bankName} • `}
                          {conn.accountNumberMasked && `${conn.accountNumberMasked} • `}
                          {conn.provider}
                        </p>
                      </div>
                    </div>
                    <div className="flex items-center gap-3">
                      <span className={`px-2.5 py-1 rounded-full text-xs font-medium ${status.cls}`}>
                        {status.label}
                      </span>
                      <button
                        onClick={() => void handleSync(conn.id)}
                        disabled={syncing === conn.id}
                        className="flex items-center gap-1 px-3 py-1.5 bg-teal-600 hover:bg-teal-700 text-white rounded-lg text-xs font-medium transition-colors disabled:opacity-50"
                      >
                        {syncing === conn.id ? (
                          <Loader2 className="h-3.5 w-3.5 animate-spin" />
                        ) : (
                          <RefreshCw className="h-3.5 w-3.5" />
                        )}
                        Sync Now
                      </button>
                      <button
                        onClick={() => void handleViewHistory(conn.id)}
                        className="p-1.5 text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] transition-colors"
                        title="View sync history"
                      >
                        <Clock className="h-4 w-4" />
                      </button>
                      <button
                        onClick={() => void handleDisconnect(conn.id)}
                        className="p-1.5 text-red-400 hover:text-red-500 transition-colors"
                        title="Disconnect"
                      >
                        <Unlink className="h-4 w-4" />
                      </button>
                    </div>
                  </div>

                  {conn.lastSyncAt && (
                    <p className="text-xs text-[var(--ff-text-tertiary)] mt-2 ml-14">
                      Last synced: {new Date(conn.lastSyncAt).toLocaleString('en-ZA')}
                    </p>
                  )}
                  {conn.syncError && (
                    <p className="text-xs text-red-400 mt-1 ml-14">{conn.syncError}</p>
                  )}
                </div>
              );
            })}
          </div>
        )}

        {/* Sync History Modal */}
        {selectedHistory && (
          <div className="bg-[var(--ff-surface-primary)] border border-[var(--ff-border-primary)] rounded-xl overflow-hidden">
            <div className="px-6 py-4 border-b border-[var(--ff-border-primary)] flex items-center justify-between">
              <h2 className="text-lg font-semibold text-[var(--ff-text-primary)]">Sync History</h2>
              <button onClick={() => setSelectedHistory(null)} className="text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)]">
                <XCircle className="h-5 w-5" />
              </button>
            </div>
            {selectedHistory.logs.length === 0 ? (
              <p className="p-6 text-center text-[var(--ff-text-secondary)]">No sync history yet</p>
            ) : (
              <table className="w-full text-sm">
                <thead>
                  <tr className="bg-[var(--ff-bg-secondary)]">
                    <th className="text-left px-4 py-2.5 font-medium text-[var(--ff-text-secondary)]">Date</th>
                    <th className="text-left px-4 py-2.5 font-medium text-[var(--ff-text-secondary)]">Type</th>
                    <th className="text-right px-4 py-2.5 font-medium text-[var(--ff-text-secondary)]">Fetched</th>
                    <th className="text-right px-4 py-2.5 font-medium text-[var(--ff-text-secondary)]">Imported</th>
                    <th className="text-right px-4 py-2.5 font-medium text-[var(--ff-text-secondary)]">Skipped</th>
                    <th className="text-center px-4 py-2.5 font-medium text-[var(--ff-text-secondary)]">Status</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-[var(--ff-border-primary)]">
                  {selectedHistory.logs.map(log => (
                    <tr key={log.id} className="hover:bg-[var(--ff-bg-hover)]">
                      <td className="px-4 py-2.5 text-[var(--ff-text-primary)]">
                        {new Date(log.startedAt).toLocaleString('en-ZA')}
                      </td>
                      <td className="px-4 py-2.5 text-[var(--ff-text-secondary)] capitalize">{log.syncType}</td>
                      <td className="px-4 py-2.5 text-right text-[var(--ff-text-secondary)]">{log.fetched}</td>
                      <td className="px-4 py-2.5 text-right text-teal-500 font-medium">{log.imported}</td>
                      <td className="px-4 py-2.5 text-right text-[var(--ff-text-tertiary)]">{log.skipped}</td>
                      <td className="px-4 py-2.5 text-center">
                        <span className={`px-2 py-0.5 rounded-full text-xs font-medium ${
                          log.status === 'completed' ? 'bg-teal-500/20 text-teal-500' :
                          log.status === 'failed' ? 'bg-red-500/20 text-red-500' :
                          'bg-amber-500/20 text-amber-500'
                        }`}>
                          {log.status}
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </div>
        )}
      </div>
    </AppLayout>
  );
}

/**
 * Start New Reconciliation Page
 * PRD-060 Phase 4: Create reconciliation session
 */

import { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import { ArrowLeft, Landmark, Loader2 } from 'lucide-react';
import { formatCurrency } from '@/utils/formatters';
import { apiFetch } from '@/lib/apiFetch';

interface BankAccount { id: string; account_code: string; account_name: string; bank_account_number?: string | null }

export default function NewReconciliationPage() {
  const router = useRouter();
  const [bankAccounts, setBankAccounts] = useState<BankAccount[]>([]);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState('');

  const [form, setForm] = useState({
    bankAccountId: '',
    statementDate: new Date().toISOString().split('T')[0],
    statementBalance: 0,
  });

  useEffect(() => {
    apiFetch('/api/accounting/chart-of-accounts?subtype=bank')
      .then(r => r.json())
      .then(res => {
        const data = res.data || res;
        const accounts = Array.isArray(data) ? data : data.accounts || [];
        setBankAccounts(accounts.map((a: { id: string; accountCode?: string; account_code?: string; accountName?: string; account_name?: string; bankAccountNumber?: string; bank_account_number?: string }) => ({
          id: a.id,
          account_code: a.accountCode || a.account_code || '',
          account_name: a.accountName || a.account_name || '',
          bank_account_number: a.bankAccountNumber || a.bank_account_number || null,
        })));
      });
  }, []);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setIsSubmitting(true);

    try {
      const res = await apiFetch('/api/accounting/bank-reconciliations', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({
          bankAccountId: form.bankAccountId,
          statementDate: form.statementDate,
          statementBalance: form.statementBalance,
        }),
      });

      const json = await res.json();
      if (!res.ok) throw new Error(json.message || json.error || 'Failed to start reconciliation');
      const data = json.data || json;
      router.push(`/accounting/bank-reconciliation/${data.id}`);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to start reconciliation');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]">
          <div className="px-6 py-4">
            <Link href="/accounting/bank-reconciliation" className="inline-flex items-center gap-1 text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] mb-2">
              <ArrowLeft className="h-4 w-4" /> Back to Reconciliations
            </Link>
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-teal-500/10">
                <Landmark className="h-6 w-6 text-teal-500" />
              </div>
              <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Start Reconciliation</h1>
            </div>
          </div>
        </div>

        <form onSubmit={handleSubmit} className="p-6 max-w-2xl space-y-6">
          {error && (
            <div className="p-3 rounded-lg bg-red-500/10 text-red-400 text-sm">{error}</div>
          )}

          <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-6 space-y-4">
            <h2 className="text-lg font-semibold text-[var(--ff-text-primary)]">Reconciliation Setup</h2>

            <div>
              <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">Bank Account *</label>
              <select
                value={form.bankAccountId}
                onChange={e => setForm(f => ({ ...f, bankAccountId: e.target.value }))}
                className="ff-select w-full"
                required
              >
                <option value="">Select bank account...</option>
                {bankAccounts.map(a => (
                  <option key={a.id} value={a.id}>
                    {a.account_code} — {a.account_name}
                    {a.bank_account_number ? ` (****${a.bank_account_number.slice(-4)})` : ''}
                  </option>
                ))}
              </select>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">Statement Date *</label>
                <input
                  type="date"
                  value={form.statementDate}
                  onChange={e => setForm(f => ({ ...f, statementDate: e.target.value }))}
                  className="ff-input w-full"
                  required
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">Statement Closing Balance *</label>
                <input
                  type="number"
                  step="0.01"
                  value={form.statementBalance || ''}
                  onChange={e => setForm(f => ({ ...f, statementBalance: Number(e.target.value) }))}
                  className="ff-input w-full"
                  placeholder="e.g. 125000.00"
                  required
                />
              </div>
            </div>

            <p className="text-xs text-[var(--ff-text-tertiary)]">
              Enter the closing balance from your bank statement. The system will calculate the GL balance
              automatically and show the difference for you to reconcile.
            </p>
          </div>

          <div className="flex justify-end gap-3">
            <Link href="/accounting/bank-reconciliation" className="px-4 py-2 text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)]">
              Cancel
            </Link>
            <button
              type="submit"
              disabled={isSubmitting || !form.bankAccountId}
              className="inline-flex items-center gap-2 px-6 py-2 bg-teal-600 text-white rounded-lg hover:bg-teal-700 disabled:opacity-50 transition-colors text-sm font-medium"
            >
              {isSubmitting && <Loader2 className="h-4 w-4 animate-spin" />}
              Start Reconciliation
            </button>
          </div>
        </form>
      </div>
    </AppLayout>
  );
}

/**
 * Bank Transfers
 * Sage equivalent: Banking > Transfers
 * Transfer between own bank accounts (creates balanced journal entry)
 */

import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import { ArrowLeftRight, Loader2, AlertCircle, Plus } from 'lucide-react';
import { formatCurrency } from '@/utils/formatters';
import { apiFetch } from '@/lib/apiFetch';

interface BankAccount {
  id: string;
  account_code: string;
  account_name: string;
}

export default function BankTransfersPage() {
  const [bankAccounts, setBankAccounts] = useState<BankAccount[]>([]);
  const [fromAccount, setFromAccount] = useState('');
  const [toAccount, setToAccount] = useState('');
  const [amount, setAmount] = useState('');
  const [reference, setReference] = useState('');
  const [transferDate, setTransferDate] = useState(new Date().toISOString().split('T')[0]);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [message, setMessage] = useState({ type: '', text: '' });

  const loadBankAccounts = useCallback(async () => {
    setIsLoading(true);
    try {
      const res = await apiFetch('/api/accounting/chart-of-accounts?subtype=bank');
      const json = await res.json();
      const data = json.data || json;
      setBankAccounts(data.accounts || []);
    } catch {
      setMessage({ type: 'error', text: 'Failed to load bank accounts' });
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => { loadBankAccounts(); }, [loadBankAccounts]);

  const handleTransfer = async () => {
    if (!fromAccount || !toAccount || !amount || fromAccount === toAccount) {
      setMessage({ type: 'error', text: 'Please fill all fields and select different accounts' });
      return;
    }
    setIsSubmitting(true);
    setMessage({ type: '', text: '' });
    try {
      const res = await apiFetch('/api/accounting/bank-transfers', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          fromAccountId: fromAccount,
          toAccountId: toAccount,
          amount: parseFloat(amount),
          reference,
          transferDate,
        }),
      });
      const json = await res.json();
      if (res.ok) {
        setMessage({ type: 'success', text: 'Transfer completed — journal entry created' });
        setAmount('');
        setReference('');
      } else {
        setMessage({ type: 'error', text: json.message || 'Transfer failed' });
      }
    } catch {
      setMessage({ type: 'error', text: 'Transfer request failed' });
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]">
          <div className="px-6 py-4">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-indigo-500/10">
                <ArrowLeftRight className="h-6 w-6 text-indigo-500" />
              </div>
              <div>
                <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Bank Transfers</h1>
                <p className="text-sm text-[var(--ff-text-secondary)]">
                  Transfer funds between bank accounts
                </p>
              </div>
            </div>
          </div>
        </div>

        <div className="p-6 max-w-2xl">
          {isLoading ? (
            <div className="flex items-center justify-center py-12">
              <Loader2 className="h-8 w-8 animate-spin text-indigo-500" />
            </div>
          ) : (
            <div className="space-y-6">
              <div className="p-6 rounded-xl bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] space-y-4">
                <div>
                  <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">From Account</label>
                  <select
                    value={fromAccount}
                    onChange={(e) => setFromAccount(e.target.value)}
                    className="w-full px-3 py-2 rounded-lg bg-[var(--ff-bg-tertiary)] border border-[var(--ff-border-light)] text-[var(--ff-text-primary)]"
                  >
                    <option value="">Select source account...</option>
                    {bankAccounts.map(a => (
                      <option key={a.id} value={a.id}>{a.account_code} — {a.account_name}</option>
                    ))}
                  </select>
                </div>

                <div className="flex justify-center">
                  <ArrowLeftRight className="h-6 w-6 text-[var(--ff-text-tertiary)]" />
                </div>

                <div>
                  <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">To Account</label>
                  <select
                    value={toAccount}
                    onChange={(e) => setToAccount(e.target.value)}
                    className="w-full px-3 py-2 rounded-lg bg-[var(--ff-bg-tertiary)] border border-[var(--ff-border-light)] text-[var(--ff-text-primary)]"
                  >
                    <option value="">Select destination account...</option>
                    {bankAccounts.map(a => (
                      <option key={a.id} value={a.id}>{a.account_code} — {a.account_name}</option>
                    ))}
                  </select>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">Amount (ZAR)</label>
                    <input
                      type="number"
                      step="0.01"
                      min="0"
                      value={amount}
                      onChange={(e) => setAmount(e.target.value)}
                      className="w-full px-3 py-2 rounded-lg bg-[var(--ff-bg-tertiary)] border border-[var(--ff-border-light)] text-[var(--ff-text-primary)]"
                      placeholder="0.00"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">Date</label>
                    <input
                      type="date"
                      value={transferDate}
                      onChange={(e) => setTransferDate(e.target.value)}
                      className="w-full px-3 py-2 rounded-lg bg-[var(--ff-bg-tertiary)] border border-[var(--ff-border-light)] text-[var(--ff-text-primary)]"
                    />
                  </div>
                </div>

                <div>
                  <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">Reference</label>
                  <input
                    type="text"
                    value={reference}
                    onChange={(e) => setReference(e.target.value)}
                    className="w-full px-3 py-2 rounded-lg bg-[var(--ff-bg-tertiary)] border border-[var(--ff-border-light)] text-[var(--ff-text-primary)]"
                    placeholder="e.g. Inter-account transfer"
                  />
                </div>

                {message.text && (
                  <div className={`flex items-center gap-2 p-3 rounded-lg text-sm ${
                    message.type === 'error' ? 'bg-red-500/10 text-red-400' : 'bg-teal-500/10 text-teal-400'
                  }`}>
                    <AlertCircle className="h-4 w-4" />
                    {message.text}
                  </div>
                )}

                <button
                  onClick={handleTransfer}
                  disabled={isSubmitting}
                  className="w-full px-4 py-2.5 bg-indigo-600 hover:bg-indigo-700 disabled:opacity-50 text-white rounded-lg flex items-center justify-center gap-2 text-sm font-medium"
                >
                  {isSubmitting ? <Loader2 className="h-4 w-4 animate-spin" /> : <ArrowLeftRight className="h-4 w-4" />}
                  Process Transfer
                </button>
              </div>
            </div>
          )}
        </div>
      </div>
    </AppLayout>
  );
}

/**
