/**
 * Customer Payments List Page
 * PRD-060 Phase 3: Accounts Receivable
 */

import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import {
  Wallet, Plus, Loader2, AlertCircle, ChevronRight, Filter,
} from 'lucide-react';
import { ExportCSVButton } from '@/components/shared/ExportCSVButton';
import type { CustomerPayment, CustomerPaymentStatus } from '@/modules/accounting/types/ar.types';
import { formatCurrency } from '@/utils/formatters';
import { apiFetch } from '@/lib/apiFetch';

const STATUS_OPTIONS: { value: string; label: string }[] = [
  { value: '', label: 'All Statuses' },
  { value: 'draft', label: 'Draft' },
  { value: 'confirmed', label: 'Confirmed' },
  { value: 'reconciled', label: 'Reconciled' },
  { value: 'cancelled', label: 'Cancelled' },
];

function StatusBadge({ status }: { status: string }) {
  const colors: Record<string, string> = {
    draft: 'bg-gray-500/20 text-gray-400',
    confirmed: 'bg-teal-500/20 text-teal-400',
    reconciled: 'bg-blue-500/20 text-blue-400',
    cancelled: 'bg-red-500/20 text-red-400',
  };
  return (
    <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium ${colors[status] || 'bg-gray-500/20 text-gray-400'}`}>
      {status}
    </span>
  );
}

export default function CustomerPaymentsPage() {
  const [payments, setPayments] = useState<CustomerPayment[]>([]);
  const [total, setTotal] = useState(0);
  const [statusFilter, setStatusFilter] = useState('');
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState('');

  const loadPayments = useCallback(async () => {
    setIsLoading(true);
    setError('');
    try {
      const params = new URLSearchParams();
      if (statusFilter) params.set('status', statusFilter);
      const res = await apiFetch(`/api/accounting/customer-payments?${params}`);
      const json = await res.json();
      const payload = json.data || json;
      setPayments(payload.payments || []);
      setTotal(payload.total || 0);
    } catch {
      setError('Failed to load customer payments');
    } finally {
      setIsLoading(false);
    }
  }, [statusFilter]);

  useEffect(() => { loadPayments(); }, [loadPayments]);

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        {/* Header */}
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]">
          <div className="px-6 py-4 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-teal-500/10">
                <Wallet className="h-6 w-6 text-teal-500" />
              </div>
              <div>
                <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Customer Payments</h1>
                <p className="text-sm text-[var(--ff-text-secondary)]">
                  {total} payment{total !== 1 ? 's' : ''} recorded
                </p>
              </div>
            </div>
            <div className="flex items-center gap-2">
              <ExportCSVButton endpoint="/api/accounting/customer-payments-export" filenamePrefix="customer-payments" params={{ status: statusFilter }} label="Export CSV" />
              <Link
                href="/accounting/customer-payments/new"
                className="inline-flex items-center gap-2 px-4 py-2 bg-teal-600 text-white rounded-lg hover:bg-teal-700 transition-colors text-sm font-medium"
              >
                <Plus className="h-4 w-4" /> Record Payment
              </Link>
            </div>
          </div>
        </div>

        <div className="p-6 space-y-4">
          {/* Filters */}
          <div className="flex items-center gap-3">
            <Filter className="h-4 w-4 text-[var(--ff-text-tertiary)]" />
            <select
              value={statusFilter}
              onChange={e => setStatusFilter(e.target.value)}
              className="ff-select text-sm"
            >
              {STATUS_OPTIONS.map(o => <option key={o.value} value={o.value}>{o.label}</option>)}
            </select>
          </div>

          {/* Error */}
          {error && (
            <div className="flex items-center gap-2 p-3 rounded-lg bg-red-500/10 text-red-400 text-sm">
              <AlertCircle className="h-4 w-4" /> {error}
            </div>
          )}

          {/* Loading */}
          {isLoading ? (
            <div className="flex items-center justify-center py-12">
              <Loader2 className="h-6 w-6 animate-spin text-teal-500" />
            </div>
          ) : payments.length === 0 ? (
            <div className="text-center py-12 text-[var(--ff-text-secondary)]">
              No customer payments found
            </div>
          ) : (
            <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] overflow-hidden">
              <table className="w-full text-sm">
                <thead>
                  <tr className="border-b border-[var(--ff-border-light)]">
                    <th className="text-left px-4 py-3 text-[var(--ff-text-secondary)] font-medium">Payment #</th>
                    <th className="text-left px-4 py-3 text-[var(--ff-text-secondary)] font-medium">Client</th>
                    <th className="text-left px-4 py-3 text-[var(--ff-text-secondary)] font-medium">Date</th>
                    <th className="text-right px-4 py-3 text-[var(--ff-text-secondary)] font-medium">Amount</th>
                    <th className="text-left px-4 py-3 text-[var(--ff-text-secondary)] font-medium">Method</th>
                    <th className="text-left px-4 py-3 text-[var(--ff-text-secondary)] font-medium">Status</th>
                    <th className="px-4 py-3"></th>
                  </tr>
                </thead>
                <tbody>
                  {payments.map(p => (
                    <tr key={p.id} className="border-b border-[var(--ff-border-light)] hover:bg-[var(--ff-bg-primary)] transition-colors">
                      <td className="px-4 py-3 font-mono text-[var(--ff-text-primary)]">
                        <Link href={`/accounting/customer-payments/${p.id}`} className="hover:text-teal-400 transition-colors">
                          {p.paymentNumber}
                        </Link>
                      </td>
                      <td className="px-4 py-3 text-[var(--ff-text-primary)]">{p.clientName || '—'}</td>
                      <td className="px-4 py-3 text-[var(--ff-text-secondary)]">
                        {new Date(p.paymentDate).toLocaleDateString('en-ZA')}
                      </td>
                      <td className="px-4 py-3 text-right font-mono text-[var(--ff-text-primary)]">
                        {formatCurrency(p.totalAmount)}
                      </td>
                      <td className="px-4 py-3 text-[var(--ff-text-secondary)] uppercase text-xs">{p.paymentMethod}</td>
                      <td className="px-4 py-3"><StatusBadge status={p.status} /></td>
                      <td className="px-4 py-3 text-right">
                        <Link href={`/accounting/customer-payments/${p.id}`}>
                          <ChevronRight className="h-4 w-4 text-[var(--ff-text-tertiary)] hover:text-teal-400" />
                        </Link>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>
    </AppLayout>
  );
}

/**
 * Document Capture Detail Page
 * View extracted data, edit fields, take actions on a captured document.
 */

import { useState, useEffect, useCallback } from 'react';
import { useRouter } from 'next/router';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import {
  ScanLine, ArrowLeft, Loader2, AlertCircle, FileText,
  CheckCircle2, XCircle, Link2, Save, ChevronDown, ChevronUp,
} from 'lucide-react';
import { notify } from '@/utils/toast';
import type { CapturedDocument, ExtractedDocument } from '@/modules/accounting/types/documentCapture.types';
import { formatCurrency, formatDate } from '@/utils/formatters';
import { apiFetch } from '@/lib/apiFetch';

function StatusBadge({ status }: { status: string }) {
  const colors: Record<string, string> = {
    pending: 'bg-amber-500/20 text-amber-400',
    reviewed: 'bg-blue-500/20 text-blue-400',
    matched: 'bg-teal-500/20 text-teal-400',
    rejected: 'bg-red-500/20 text-red-400',
  };
  return (
    <span className={`inline-flex items-center px-2.5 py-1 rounded-full text-xs font-medium ${colors[status] || 'bg-gray-500/20 text-gray-400'}`}>
      {status}
    </span>
  );
}

function ConfidenceBadge({ confidence }: { confidence: number }) {
  let color = 'text-red-400';
  let label = 'Low';
  if (confidence >= 0.7) { color = 'text-teal-400'; label = 'High'; }
  else if (confidence >= 0.4) { color = 'text-amber-400'; label = 'Medium'; }
  return (
    <span className={`text-xs font-medium ${color}`}>
      {label} ({Math.round(confidence * 100)}%)
    </span>
  );
}

export default function DocumentCaptureDetailPage() {
  const router = useRouter();
  const { docId } = router.query;

  const [doc, setDoc] = useState<CapturedDocument | null>(null);
  const [extracted, setExtracted] = useState<ExtractedDocument | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [showRawText, setShowRawText] = useState(false);

  // Editable fields
  const [vendorName, setVendorName] = useState('');
  const [documentDate, setDocumentDate] = useState('');
  const [referenceNumber, setReferenceNumber] = useState('');
  const [totalAmount, setTotalAmount] = useState('');
  const [vatAmount, setVatAmount] = useState('');
  const [documentType, setDocumentType] = useState('');
  const [notes, setNotes] = useState('');

  // Bank TX match
  const [bankTxId, setBankTxId] = useState('');
  const [isMatching, setIsMatching] = useState(false);

  const loadDocument = useCallback(async () => {
    if (!docId) return;
    setIsLoading(true);
    setError('');

    try {
      const res = await apiFetch(`/api/accounting/document-capture?status=`);
      const json = await res.json();
      if (!json.success) throw new Error(json.error?.message || 'Failed to load');

      const found = (json.data || []).find((d: CapturedDocument) => d.id === docId);
      if (!found) throw new Error('Document not found');

      setDoc(found);

      const ext = found.extractedData as ExtractedDocument | null;
      setExtracted(ext);

      // Populate form
      setVendorName(found.vendorName || ext?.vendorName || '');
      setDocumentDate(found.documentDate || ext?.date || '');
      setReferenceNumber(found.referenceNumber || ext?.referenceNumber || '');
      setTotalAmount(found.totalAmount !== null ? String(found.totalAmount) : (ext?.totalAmount !== null ? String(ext?.totalAmount) : ''));
      setVatAmount(found.vatAmount !== null ? String(found.vatAmount) : (ext?.vatAmount !== null ? String(ext?.vatAmount) : ''));
      setDocumentType(found.documentType || ext?.documentType || 'unknown');
      setNotes(found.notes || '');
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load document');
    } finally {
      setIsLoading(false);
    }
  }, [docId]);

  useEffect(() => { loadDocument(); }, [loadDocument]);

  async function handleConfirm() {
    if (!doc) return;
    setIsSaving(true);
    try {
      const res = await apiFetch('/api/accounting/document-capture-action', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          id: doc.id,
          action: 'confirm',
          data: {
            vendorName: vendorName || null,
            documentDate: documentDate || null,
            referenceNumber: referenceNumber || null,
            totalAmount: totalAmount ? parseFloat(totalAmount) : null,
            vatAmount: vatAmount ? parseFloat(vatAmount) : null,
            documentType: documentType || null,
            notes: notes || null,
          },
        }),
      });
      const json = await res.json();
      if (!json.success) throw new Error(json.error?.message || 'Confirm failed');
      notify.success('Document confirmed');
      loadDocument();
    } catch (err) {
      notify.error(err instanceof Error ? err.message : 'Confirm failed');
    } finally {
      setIsSaving(false);
    }
  }

  async function handleReject() {
    if (!doc) return;
    setIsSaving(true);
    try {
      const res = await apiFetch('/api/accounting/document-capture-action', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          id: doc.id,
          action: 'reject',
          data: { notes: notes || 'Rejected' },
        }),
      });
      const json = await res.json();
      if (!json.success) throw new Error(json.error?.message || 'Reject failed');
      notify.success('Document rejected');
      loadDocument();
    } catch (err) {
      notify.error(err instanceof Error ? err.message : 'Reject failed');
    } finally {
      setIsSaving(false);
    }
  }

  async function handleMatchBankTx() {
    if (!doc || !bankTxId.trim()) {
      notify.error('Enter a bank transaction ID');
      return;
    }
    setIsMatching(true);
    try {
      const res = await apiFetch('/api/accounting/document-capture-action', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          id: doc.id,
          action: 'match_bank_tx',
          data: { bankTxId: bankTxId.trim() },
        }),
      });
      const json = await res.json();
      if (!json.success) throw new Error(json.error?.message || 'Match failed');
      notify.success('Matched to bank transaction');
      setBankTxId('');
      loadDocument();
    } catch (err) {
      notify.error(err instanceof Error ? err.message : 'Match failed');
    } finally {
      setIsMatching(false);
    }
  }

  if (isLoading) {
    return (
      <AppLayout>
        <div className="min-h-screen bg-[var(--ff-bg-primary)] flex items-center justify-center">
          <Loader2 className="h-8 w-8 text-teal-500 animate-spin" />
        </div>
      </AppLayout>
    );
  }

  if (error || !doc) {
    return (
      <AppLayout>
        <div className="min-h-screen bg-[var(--ff-bg-primary)] flex flex-col items-center justify-center gap-4">
          <AlertCircle className="h-8 w-8 text-red-400" />
          <p className="text-red-400 text-sm">{error || 'Document not found'}</p>
          <Link href="/accounting/document-capture" className="text-teal-500 hover:text-teal-400 text-sm">
            Back to Document Capture
          </Link>
        </div>
      </AppLayout>
    );
  }

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        {/* Header */}
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <Link
                href="/accounting/document-capture"
                className="p-2 rounded-lg hover:bg-[var(--ff-bg-tertiary)] transition-colors"
              >
                <ArrowLeft className="h-5 w-5 text-[var(--ff-text-secondary)]" />
              </Link>
              <div className="p-2 rounded-lg bg-teal-500/10">
                <ScanLine className="h-5 w-5 text-teal-500" />
              </div>
              <div>
                <div className="flex items-center gap-3">
                  <h1 className="text-xl font-bold text-[var(--ff-text-primary)]">
                    {doc.fileName}
                  </h1>
                  <StatusBadge status={doc.status} />
                </div>
                <p className="text-xs text-[var(--ff-text-tertiary)]">
                  Uploaded {formatDate(doc.createdAt)}
                  {doc.fileSize ? ` - ${(doc.fileSize / 1024).toFixed(1)} KB` : ''}
                </p>
              </div>
            </div>
            {extracted && <ConfidenceBadge confidence={extracted.confidence} />}
          </div>
        </div>

        <div className="p-6 space-y-6 max-w-4xl mx-auto">
          {/* Warnings */}
          {extracted && extracted.warnings.length > 0 && (
            <div className="bg-amber-500/5 border border-amber-500/20 rounded-lg p-4">
              {extracted.warnings.map((w, i) => (
                <div key={i} className="flex items-start gap-2 text-sm text-amber-400">
                  <AlertCircle className="h-4 w-4 mt-0.5 shrink-0" />
                  <span>{w}</span>
                </div>
              ))}
            </div>
          )}

          {/* Edit Form */}
          <div className="bg-[var(--ff-bg-secondary)] rounded-xl border border-[var(--ff-border-light)]">
            <div className="px-6 py-4 border-b border-[var(--ff-border-light)]">
              <h2 className="text-lg font-semibold text-[var(--ff-text-primary)]">Document Details</h2>
              <p className="text-xs text-[var(--ff-text-tertiary)]">Review and correct the extracted fields</p>
            </div>
            <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">Document Type</label>
                <select
                  value={documentType}
                  onChange={(e) => setDocumentType(e.target.value)}
                  className="ff-select w-full text-sm"
                  disabled={doc.status === 'rejected'}
                >
                  <option value="invoice">Invoice</option>
                  <option value="credit_note">Credit Note</option>
                  <option value="receipt">Receipt</option>
                  <option value="statement">Statement</option>
                  <option value="unknown">Unknown</option>
                </select>
              </div>
              <div>
                <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">Vendor Name</label>
                <input
                  type="text"
                  value={vendorName}
                  onChange={(e) => setVendorName(e.target.value)}
                  className="ff-input w-full text-sm"
                  placeholder="Enter vendor name"
                  disabled={doc.status === 'rejected'}
                />
              </div>
              <div>
                <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">Date</label>
                <input
                  type="date"
                  value={documentDate}
                  onChange={(e) => setDocumentDate(e.target.value)}
                  className="ff-input w-full text-sm"
                  disabled={doc.status === 'rejected'}
                />
              </div>
              <div>
                <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">Reference / Invoice No.</label>
                <input
                  type="text"
                  value={referenceNumber}
                  onChange={(e) => setReferenceNumber(e.target.value)}
                  className="ff-input w-full text-sm"
                  placeholder="e.g. INV-001"
                  disabled={doc.status === 'rejected'}
                />
              </div>
              <div>
                <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">Total Amount (ZAR)</label>
                <input
                  type="number"
                  step="0.01"
                  value={totalAmount}
                  onChange={(e) => setTotalAmount(e.target.value)}
                  className="ff-input w-full text-sm"
                  placeholder="0.00"
                  disabled={doc.status === 'rejected'}
                />
              </div>
              <div>
                <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">VAT Amount (ZAR)</label>
                <input
                  type="number"
                  step="0.01"
                  value={vatAmount}
                  onChange={(e) => setVatAmount(e.target.value)}
                  className="ff-input w-full text-sm"
                  placeholder="0.00"
                  disabled={doc.status === 'rejected'}
                />
              </div>
              {extracted?.vendorVatNumber && (
                <div>
                  <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">Vendor VAT Number</label>
                  <input
                    type="text"
                    value={extracted.vendorVatNumber}
                    className="ff-input w-full text-sm bg-[var(--ff-bg-tertiary)]"
                    readOnly
                  />
                </div>
              )}
              {extracted?.subtotal !== null && extracted?.subtotal !== undefined && (
                <div>
                  <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">Subtotal (extracted)</label>
                  <input
                    type="text"
                    value={formatCurrency(extracted.subtotal)}
                    className="ff-input w-full text-sm bg-[var(--ff-bg-tertiary)]"
                    readOnly
                  />
                </div>
              )}
              <div className="md:col-span-2">
                <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">Notes</label>
                <textarea
                  value={notes}
                  onChange={(e) => setNotes(e.target.value)}
                  className="ff-input w-full text-sm"
                  rows={2}
                  placeholder="Optional notes..."
                  disabled={doc.status === 'rejected'}
                />
              </div>
            </div>

            {/* Line Items */}
            {extracted && extracted.lineItems.length > 0 && (
              <div className="px-6 pb-4">
                <h3 className="text-xs font-medium text-[var(--ff-text-secondary)] mb-2">Extracted Line Items</h3>
                <div className="overflow-x-auto">
                  <table className="w-full text-sm">
                    <thead>
                      <tr className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-tertiary)]">
                        <th className="px-3 py-2 text-left text-xs font-medium text-[var(--ff-text-secondary)]">Description</th>
                        <th className="px-3 py-2 text-right text-xs font-medium text-[var(--ff-text-secondary)]">Qty</th>
                        <th className="px-3 py-2 text-right text-xs font-medium text-[var(--ff-text-secondary)]">Unit Price</th>
                        <th className="px-3 py-2 text-right text-xs font-medium text-[var(--ff-text-secondary)]">Total</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-[var(--ff-border-light)]">
                      {extracted.lineItems.map((item, i) => (
                        <tr key={i}>
                          <td className="px-3 py-2 text-[var(--ff-text-primary)]">{item.description}</td>
                          <td className="px-3 py-2 text-right text-[var(--ff-text-secondary)]">{item.quantity ?? '-'}</td>
                          <td className="px-3 py-2 text-right font-mono text-[var(--ff-text-secondary)]">{item.unitPrice !== null ? formatCurrency(item.unitPrice) : '-'}</td>
                          <td className="px-3 py-2 text-right font-mono text-[var(--ff-text-primary)]">{item.total !== null ? formatCurrency(item.total) : '-'}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            )}

            {/* Action Buttons */}
            {doc.status !== 'rejected' && (
              <div className="px-6 py-4 border-t border-[var(--ff-border-light)] flex items-center gap-3 flex-wrap">
                <button
                  onClick={handleConfirm}
                  disabled={isSaving}
                  className="inline-flex items-center gap-2 px-4 py-2 bg-teal-600 text-white rounded-lg hover:bg-teal-700 transition-colors text-sm font-medium disabled:opacity-50"
                >
                  {isSaving ? <Loader2 className="h-4 w-4 animate-spin" /> : <CheckCircle2 className="h-4 w-4" />}
                  {doc.status === 'reviewed' ? 'Update' : 'Confirm & Save'}
                </button>
                <button
                  onClick={handleReject}
                  disabled={isSaving}
                  className="inline-flex items-center gap-2 px-4 py-2 bg-red-600/20 text-red-400 rounded-lg hover:bg-red-600/30 transition-colors text-sm font-medium disabled:opacity-50"
                >
                  <XCircle className="h-4 w-4" />
                  Reject
                </button>
              </div>
            )}
          </div>

          {/* Match to Bank Transaction */}
          {doc.status !== 'rejected' && (
            <div className="bg-[var(--ff-bg-secondary)] rounded-xl border border-[var(--ff-border-light)]">
              <div className="px-6 py-4 border-b border-[var(--ff-border-light)]">
                <h2 className="text-lg font-semibold text-[var(--ff-text-primary)]">Match to Bank Transaction</h2>
                <p className="text-xs text-[var(--ff-text-tertiary)]">Link this document to a bank transaction for reconciliation</p>
              </div>
              <div className="p-6">
                {doc.matchedBankTxId ? (
                  <div className="flex items-center gap-2 text-sm text-teal-400">
                    <Link2 className="h-4 w-4" />
                    Matched to bank transaction: <span className="font-mono text-xs">{doc.matchedBankTxId}</span>
                  </div>
                ) : (
                  <div className="flex items-center gap-3">
                    <input
                      type="text"
                      value={bankTxId}
                      onChange={(e) => setBankTxId(e.target.value)}
                      className="ff-input flex-1 text-sm"
                      placeholder="Enter bank transaction ID..."
                    />
                    <button
                      onClick={handleMatchBankTx}
                      disabled={isMatching || !bankTxId.trim()}
                      className="inline-flex items-center gap-2 px-4 py-2 bg-teal-600 text-white rounded-lg hover:bg-teal-700 transition-colors text-sm font-medium disabled:opacity-50"
                    >
                      {isMatching ? <Loader2 className="h-4 w-4 animate-spin" /> : <Link2 className="h-4 w-4" />}
                      Match
                    </button>
                  </div>
                )}
              </div>
            </div>
          )}

          {/* Raw Text Preview */}
          {extracted?.rawText && (
            <div className="bg-[var(--ff-bg-secondary)] rounded-xl border border-[var(--ff-border-light)]">
              <button
                onClick={() => setShowRawText(!showRawText)}
                className="w-full px-6 py-4 flex items-center justify-between text-left"
              >
                <div>
                  <h2 className="text-lg font-semibold text-[var(--ff-text-primary)]">Raw Extracted Text</h2>
                  <p className="text-xs text-[var(--ff-text-tertiary)]">The full text extracted from the PDF</p>
                </div>
                {showRawText ? (
                  <ChevronUp className="h-5 w-5 text-[var(--ff-text-tertiary)]" />
                ) : (
                  <ChevronDown className="h-5 w-5 text-[var(--ff-text-tertiary)]" />
                )}
              </button>
              {showRawText && (
                <div className="px-6 pb-6">
                  <pre className="bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] rounded-lg p-4 text-xs text-[var(--ff-text-secondary)] whitespace-pre-wrap font-mono max-h-96 overflow-y-auto">
                    {extracted.rawText}
                  </pre>
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </AppLayout>
  );
}

/**
 * Dunning & Collections Page
 * Sage equivalent: Customers > Collections / Payment Reminders
 * Generate overdue payment reminders, track communication history
 */

import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import { AlertTriangle, Loader2, AlertCircle, Send, FileText, Clock, CheckCircle, Plus } from 'lucide-react';
import { log } from '@/lib/logger';
import { formatCurrency, formatDate } from '@/utils/formatters';
import { apiFetch } from '@/lib/apiFetch';

interface OverdueClient {
  entityId: string;
  entityName: string;
  current: number;
  days30: number;
  days60: number;
  days90: number;
  days120Plus: number;
  total: number;
}

interface DunningComm {
  id: string;
  client_id: string;
  client_name: string;
  type: string;
  level: number;
  subject: string;
  total_overdue: number;
  status: string;
  sent_at: string | null;
  created_at: string;
  created_by_name: string | null;
}

const DUNNING_TEMPLATES = [
  { level: 1, subject: 'Friendly Payment Reminder', body: 'Dear {client},\n\nWe hope this message finds you well. This is a friendly reminder that your account has an outstanding balance of {amount}.\n\nPlease arrange payment at your earliest convenience. If you have already made payment, please disregard this notice.\n\nKind regards,\nVelocity Fibre Accounts' },
  { level: 2, subject: 'Second Payment Reminder — Account Overdue', body: 'Dear {client},\n\nDespite our previous reminder, your account remains overdue with an outstanding balance of {amount}.\n\nPlease arrange payment within 7 days to avoid further action. If there are any disputes or queries regarding your account, please contact us immediately.\n\nRegards,\nVelocity Fibre Accounts' },
  { level: 3, subject: 'Final Notice — Overdue Account', body: 'Dear {client},\n\nThis is a final notice regarding your overdue account with an outstanding balance of {amount}.\n\nIf payment is not received within 5 business days, we may be forced to suspend services and refer the matter for collection.\n\nPlease contact us immediately to discuss payment arrangements.\n\nRegards,\nVelocity Fibre Accounts' },
];

export default function DunningPage() {
  const [tab, setTab] = useState<'overdue' | 'history'>('overdue');
  const [overdue, setOverdue] = useState<OverdueClient[]>([]);
  const [history, setHistory] = useState<DunningComm[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState('');
  const [showCompose, setShowCompose] = useState<OverdueClient | null>(null);
  const [composeLevel, setComposeLevel] = useState(1);
  const [isSending, setIsSending] = useState(false);

  const loadOverdue = useCallback(async () => {
    setIsLoading(true);
    setError('');
    try {
      const res = await apiFetch('/api/accounting/ar-aging');
      const json = await res.json();
      const data = json.data || json;
      const arr = Array.isArray(data) ? data : [];
      setOverdue(arr.filter((b: OverdueClient) => (b.days30 + b.days60 + b.days90 + b.days120Plus) > 0));
    } catch {
      setError('Failed to load overdue data');
    } finally {
      setIsLoading(false);
    }
  }, []);

  const loadHistory = useCallback(async () => {
    setIsLoading(true);
    try {
      const res = await apiFetch('/api/accounting/dunning');
      const json = await res.json();
      setHistory(json.data || []);
    } catch {
      setError('Failed to load dunning history');
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    if (tab === 'overdue') loadOverdue();
    else loadHistory();
  }, [tab, loadOverdue, loadHistory]);

  async function handleCreateDunning(client: OverdueClient, level: number) {
    setIsSending(true);
    try {
      const template = DUNNING_TEMPLATES[level - 1] ?? DUNNING_TEMPLATES[0];
      if (!template) return;
      const body = template.body
        .replace('{client}', client.entityName)
        .replace('{amount}', formatCurrency(client.total));

      const res = await apiFetch('/api/accounting/dunning', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          client_id: client.entityId,
          type: 'reminder',
          level,
          subject: template.subject,
          body,
          total_overdue: client.total,
          sent_via: 'email',
        }),
      });
      if (!res.ok) throw new Error('Failed to create dunning');
      setShowCompose(null);
      if (tab === 'history') loadHistory();
    } catch (err) {
      log.error('Dunning creation failed', { data: err }, 'Dunning');
      setError('Failed to create dunning communication');
    } finally {
      setIsSending(false);
    }
  }

  async function handleMarkSent(id: string) {
    try {
      await apiFetch('/api/accounting/dunning', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id, status: 'sent', sent_at: new Date().toISOString() }),
      });
      loadHistory();
    } catch (err) {
      log.error('Mark sent failed', { data: err }, 'Dunning');
    }
  }

  const totalOverdue = overdue.reduce((sum, c) => sum + c.days30 + c.days60 + c.days90 + c.days120Plus, 0);

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]">
          <div className="px-6 py-4">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-red-500/10">
                <AlertTriangle className="h-6 w-6 text-red-500" />
              </div>
              <div>
                <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Dunning & Collections</h1>
                <p className="text-sm text-[var(--ff-text-secondary)]">
                  Overdue payment reminders and collection tracking
                </p>
              </div>
            </div>
          </div>
          <div className="px-6 flex gap-1">
            {(['overdue', 'history'] as const).map(t => (
              <button key={t} onClick={() => setTab(t)}
                className={`px-4 py-2 text-sm font-medium border-b-2 transition-colors ${
                  tab === t ? 'border-red-500 text-red-400' : 'border-transparent text-[var(--ff-text-tertiary)] hover:text-[var(--ff-text-secondary)]'
                }`}>
                {t === 'overdue' ? 'Overdue Clients' : 'Communication History'}
              </button>
            ))}
          </div>
        </div>

        <div className="p-6 space-y-4">
          {error && (
            <div className="flex items-center gap-2 p-3 rounded-lg bg-red-500/10 text-red-400 text-sm">
              <AlertCircle className="h-4 w-4" /> {error}
            </div>
          )}

          {/* Summary cards */}
          {tab === 'overdue' && !isLoading && (
            <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
              <div className="p-3 rounded-lg border border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]">
                <p className="text-xs text-[var(--ff-text-tertiary)]">Overdue Clients</p>
                <p className="text-xl font-bold text-red-400">{overdue.length}</p>
              </div>
              <div className="p-3 rounded-lg border border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]">
                <p className="text-xs text-[var(--ff-text-tertiary)]">Total Overdue</p>
                <p className="text-xl font-bold text-red-400">{formatCurrency(totalOverdue)}</p>
              </div>
              <div className="p-3 rounded-lg border border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]">
                <p className="text-xs text-[var(--ff-text-tertiary)]">60+ Days</p>
                <p className="text-xl font-bold text-orange-400">
                  {overdue.filter(c => (c.days60 + c.days90 + c.days120Plus) > 0).length}
                </p>
              </div>
              <div className="p-3 rounded-lg border border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]">
                <p className="text-xs text-[var(--ff-text-tertiary)]">90+ Days</p>
                <p className="text-xl font-bold text-purple-400">
                  {overdue.filter(c => (c.days90 + c.days120Plus) > 0).length}
                </p>
              </div>
            </div>
          )}

          {isLoading ? (
            <div className="flex items-center justify-center py-12">
              <Loader2 className="h-8 w-8 animate-spin text-red-500" />
            </div>
          ) : tab === 'overdue' ? (
            /* Overdue clients list */
            overdue.length === 0 ? (
              <div className="text-center py-12 text-[var(--ff-text-secondary)]">
                No overdue accounts — all current!
              </div>
            ) : (
              <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] overflow-hidden">
                <table className="w-full text-sm">
                  <thead>
                    <tr className="border-b border-[var(--ff-border-light)]">
                      <th className="text-left px-4 py-3 text-[var(--ff-text-secondary)] font-medium">Client</th>
                      <th className="text-right px-4 py-3 text-amber-400 font-medium">1-30</th>
                      <th className="text-right px-4 py-3 text-orange-400 font-medium">31-60</th>
                      <th className="text-right px-4 py-3 text-red-400 font-medium">61-90</th>
                      <th className="text-right px-4 py-3 text-purple-400 font-medium">90+</th>
                      <th className="text-right px-4 py-3 text-[var(--ff-text-secondary)] font-medium">Total Due</th>
                      <th className="text-center px-4 py-3 text-[var(--ff-text-secondary)] font-medium">Action</th>
                    </tr>
                  </thead>
                  <tbody>
                    {overdue.map(c => (
                      <tr key={c.entityId} className="border-b border-[var(--ff-border-light)] hover:bg-[var(--ff-bg-tertiary)]">
                        <td className="px-4 py-3 text-[var(--ff-text-primary)] font-medium">{c.entityName}</td>
                        <td className="px-4 py-3 text-right font-mono text-amber-400">{formatCurrency(c.days30)}</td>
                        <td className="px-4 py-3 text-right font-mono text-orange-400">{formatCurrency(c.days60)}</td>
                        <td className="px-4 py-3 text-right font-mono text-red-400">{formatCurrency(c.days90)}</td>
                        <td className="px-4 py-3 text-right font-mono text-purple-400">{formatCurrency(c.days120Plus)}</td>
                        <td className="px-4 py-3 text-right font-mono font-bold text-[var(--ff-text-primary)]">{formatCurrency(c.total)}</td>
                        <td className="px-4 py-3 text-center">
                          <button onClick={() => { setShowCompose(c); setComposeLevel(1); }}
                            className="inline-flex items-center gap-1 px-3 py-1 rounded bg-red-500/10 hover:bg-red-500/20 text-red-400 text-xs font-medium">
                            <Send className="h-3 w-3" /> Remind
                          </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )
          ) : (
            /* Communication history */
            history.length === 0 ? (
              <div className="text-center py-12 text-[var(--ff-text-secondary)]">
                No dunning communications yet
              </div>
            ) : (
              <div className="space-y-3">
                {history.map(comm => (
                  <div key={comm.id} className="p-4 rounded-lg border border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]">
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-3">
                        <div className={`p-1.5 rounded ${comm.status === 'sent' ? 'bg-teal-500/10' : 'bg-amber-500/10'}`}>
                          {comm.status === 'sent' ? <CheckCircle className="h-4 w-4 text-teal-400" /> : <Clock className="h-4 w-4 text-amber-400" />}
                        </div>
                        <div>
                          <p className="text-sm font-medium text-[var(--ff-text-primary)]">{comm.subject}</p>
                          <p className="text-xs text-[var(--ff-text-tertiary)]">
                            {comm.client_name} • Level {comm.level} • {formatCurrency(comm.total_overdue)}
                          </p>
                        </div>
                      </div>
                      <div className="flex items-center gap-3">
                        <span className="text-xs text-[var(--ff-text-tertiary)]">{formatDate(comm.created_at)}</span>
                        {comm.status === 'draft' && (
                          <button onClick={() => handleMarkSent(comm.id)}
                            className="inline-flex items-center gap-1 px-3 py-1 rounded bg-teal-500/10 hover:bg-teal-500/20 text-teal-400 text-xs font-medium">
                            <Send className="h-3 w-3" /> Mark Sent
                          </button>
                        )}
                        {comm.status === 'sent' && (
                          <span className="text-xs text-teal-400">Sent {comm.sent_at ? formatDate(comm.sent_at) : ''}</span>
                        )}
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )
          )}
        </div>

        {/* Compose Modal */}
        {showCompose && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
            <div className="bg-[var(--ff-bg-secondary)] rounded-xl border border-[var(--ff-border-light)] max-w-lg w-full p-6 space-y-4">
              <h2 className="text-lg font-bold text-[var(--ff-text-primary)]">
                Send Payment Reminder
              </h2>
              <p className="text-sm text-[var(--ff-text-secondary)]">
                Client: <strong>{showCompose.entityName}</strong> — Overdue: <strong className="text-red-400">{formatCurrency(showCompose.total)}</strong>
              </p>

              <div>
                <label className="block text-sm font-medium text-[var(--ff-text-primary)] mb-1">Reminder Level</label>
                <select value={composeLevel} onChange={e => setComposeLevel(Number(e.target.value))}
                  className="w-full px-3 py-2 rounded-lg bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-[var(--ff-text-primary)] text-sm">
                  <option value={1}>Level 1 — Friendly Reminder</option>
                  <option value={2}>Level 2 — Second Notice</option>
                  <option value={3}>Level 3 — Final Notice</option>
                </select>
              </div>

              <div className="p-3 rounded-lg bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)]">
                <p className="text-xs text-[var(--ff-text-tertiary)] mb-1">Preview:</p>
                <p className="text-sm font-medium text-[var(--ff-text-primary)] mb-2">
                  {DUNNING_TEMPLATES[composeLevel - 1]?.subject}
                </p>
                <p className="text-xs text-[var(--ff-text-secondary)] whitespace-pre-line">
                  {(DUNNING_TEMPLATES[composeLevel - 1]?.body || '')
                    .replace('{client}', showCompose.entityName)
                    .replace('{amount}', formatCurrency(showCompose.total))}
                </p>
              </div>

              <div className="flex justify-end gap-2 pt-2">
                <button onClick={() => setShowCompose(null)}
                  className="px-4 py-2 text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)]">
                  Cancel
                </button>
                <button
                  onClick={() => handleCreateDunning(showCompose, composeLevel)}
                  disabled={isSending}
                  className="inline-flex items-center gap-2 px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 text-sm font-medium disabled:opacity-50"
                >
                  {isSending ? <Loader2 className="h-4 w-4 animate-spin" /> : <Send className="h-4 w-4" />}
                  Create Reminder
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </AppLayout>
  );
}

/**
 * Group Dashboard — thin shell
 * Consolidated view across multiple entities in a company group.
 */

import { useState, useEffect, useCallback } from 'react';
import Link from 'next/link';
import { AppLayout } from '@/components/layout/AppLayout';
import { apiFetch } from '@/lib/apiFetch';
import { log } from '@/lib/logger';
import {
  Building2, ChevronDown, Plus, Loader2, AlertCircle,
  TrendingUp, DollarSign, Landmark, CreditCard, ArrowRight,
  Settings, Scale, FileSpreadsheet, BarChart3, Layers, FileText, RefreshCw,
} from 'lucide-react';
import { GroupEntityTable } from '@/components/accounting/group/GroupEntityTable';

interface CompanyGroup { id: string; name: string; holdingCompanyName: string; memberCount: number }
interface EntitySummary { companyId: string; companyName: string; revenue: number; expenses: number; netProfit: number; cashPosition: number }
interface GroupDashboardData { combinedCash: number; combinedRevenue: number; combinedAR: number; combinedAP: number; entities: EntitySummary[] }

const fmtCurrency = (n: number) => 'R ' + new Intl.NumberFormat('en-ZA', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(n);
const fmtCompact = (n: number) => {
  if (Math.abs(n) >= 1_000_000) return 'R ' + (n / 1_000_000).toFixed(1) + 'M';
  if (Math.abs(n) >= 1_000) return 'R ' + (n / 1_000).toFixed(1) + 'K';
  return fmtCurrency(n);
};

const QUICK_LINKS = [
  { label: 'Consolidated Trial Balance', href: '/accounting/group/trial-balance', icon: Scale, description: 'Combined trial balance across all entities' },
  { label: 'Consolidated Income Statement', href: '/accounting/group/income-statement', icon: TrendingUp, description: 'Revenue and expenses for the group' },
  { label: 'Consolidated Balance Sheet', href: '/accounting/group/balance-sheet', icon: FileSpreadsheet, description: 'Assets, liabilities, and equity' },
  { label: 'Intercompany Reconciliation', href: '/accounting/group/intercompany', icon: Layers, description: 'Reconcile balances between entities' },
  { label: 'Elimination Adjustments', href: '/accounting/group/eliminations', icon: FileText, description: 'Manage consolidation eliminations' },
];

const STAT_CARDS = [
  { key: 'combinedCash', label: 'Combined Cash', sub: 'Across all entities', Icon: Landmark },
  { key: 'combinedRevenue', label: 'Combined Revenue', sub: 'Current period', Icon: TrendingUp },
  { key: 'combinedAR', label: 'Outstanding AR', sub: 'Accounts receivable', Icon: DollarSign },
  { key: 'combinedAP', label: 'Outstanding AP', sub: 'Accounts payable', Icon: CreditCard },
] as const;

export default function GroupDashboardPage() {
  const [groups, setGroups] = useState<CompanyGroup[]>([]);
  const [selectedGroupId, setSelectedGroupId] = useState<string | null>(null);
  const [dashData, setDashData] = useState<GroupDashboardData | null>(null);
  const [loadingGroups, setLoadingGroups] = useState(true);
  const [loadingDash, setLoadingDash] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [dropdownOpen, setDropdownOpen] = useState(false);

  const loadGroups = useCallback(async () => {
    setLoadingGroups(true); setError(null);
    try {
      const res = await apiFetch('/api/accounting/company-groups');
      if (!res.ok) throw new Error('Failed to load company groups');
      const json = await res.json();
      const list: CompanyGroup[] = json.data?.items ?? json.data ?? [];
      setGroups(list);
      if (list.length > 0 && !selectedGroupId && list[0]) setSelectedGroupId(list[0].id);
    } catch (err) {
      log.error('Failed to load company groups', { error: err }, 'group-dashboard');
      setError('Could not load company groups.');
    } finally { setLoadingGroups(false); }
  }, [selectedGroupId]);

  useEffect(() => { void loadGroups();   }, []);

  const loadDashboard = useCallback(async (groupId: string) => {
    setLoadingDash(true); setError(null);
    try {
      const res = await apiFetch(`/api/accounting/consolidated-reports?group_id=${encodeURIComponent(groupId)}&action=dashboard`);
      if (!res.ok) throw new Error('Failed to load dashboard data');
      const json = await res.json();
      setDashData(json.data ?? json);
    } catch (err) {
      log.error('Failed to load group dashboard', { error: err }, 'group-dashboard');
      setError('Could not load consolidated dashboard.');
    } finally { setLoadingDash(false); }
  }, []);

  useEffect(() => { if (selectedGroupId) void loadDashboard(selectedGroupId); }, [selectedGroupId, loadDashboard]);

  const selectedGroup = groups.find(g => g.id === selectedGroupId) ?? null;

  const totals = (dashData?.entities ?? []).reduce(
    (acc, e) => ({ revenue: acc.revenue + e.revenue, expenses: acc.expenses + e.expenses, netProfit: acc.netProfit + e.netProfit, cashPosition: acc.cashPosition + e.cashPosition }),
    { revenue: 0, expenses: 0, netProfit: 0, cashPosition: 0 },
  );

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]">
          <div className="px-6 py-4">
            <div className="flex items-center justify-between flex-wrap gap-3">
              <div className="flex items-center gap-3">
                <div className="p-2 rounded-lg bg-teal-500/10"><Building2 className="h-6 w-6 text-teal-500" /></div>
                <div>
                  <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Group Companies</h1>
                  <p className="text-sm text-[var(--ff-text-secondary)]">Consolidated view across entities</p>
                </div>
              </div>
              <div className="flex items-center gap-2">
                {loadingGroups ? (
                  <Loader2 className="h-5 w-5 animate-spin text-teal-500" />
                ) : groups.length === 0 ? (
                  <Link href="/accounting/group/setup" className="inline-flex items-center gap-2 px-4 py-2 bg-teal-600 text-white rounded-lg hover:bg-teal-700 transition-colors text-sm font-medium">
                    <Plus className="h-4 w-4" /> Create Group
                  </Link>
                ) : (
                  <div className="relative">
                    <button onClick={() => setDropdownOpen(o => !o)}
                      className="inline-flex items-center gap-2 px-4 py-2 rounded-lg border border-[var(--ff-border-primary)] bg-[var(--ff-surface-primary)] text-[var(--ff-text-primary)] text-sm font-medium hover:border-teal-500/50 transition-colors">
                      <Building2 className="h-4 w-4 text-teal-500" />
                      {selectedGroup?.name ?? 'Select Group'}
                      <ChevronDown className="h-4 w-4 text-[var(--ff-text-tertiary)]" />
                    </button>
                    {dropdownOpen && (
                      <>
                        <div className="fixed inset-0 z-10" onClick={() => setDropdownOpen(false)} />
                        <div className="absolute right-0 mt-1 z-20 w-64 rounded-lg border border-[var(--ff-border-primary)] bg-[var(--ff-surface-primary)] shadow-lg py-1">
                          {groups.map(g => (
                            <button key={g.id} onClick={() => { setSelectedGroupId(g.id); setDropdownOpen(false); }}
                              className={`w-full text-left px-4 py-2 text-sm transition-colors ${g.id === selectedGroupId ? 'bg-teal-500/10 text-teal-500' : 'text-[var(--ff-text-primary)] hover:bg-[var(--ff-bg-secondary)]'}`}>
                              <span className="font-medium">{g.name}</span>
                              <span className="block text-xs text-[var(--ff-text-tertiary)]">{g.memberCount} {g.memberCount === 1 ? 'entity' : 'entities'}</span>
                            </button>
                          ))}
                        </div>
                      </>
                    )}
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>

        <div className="p-6 space-y-6">
          {error && (
            <div className="flex items-center gap-3 p-4 rounded-lg border border-rose-500/30 bg-rose-500/10 text-rose-400 text-sm">
              <AlertCircle className="h-5 w-5 flex-shrink-0" />
              <span>{error}</span>
              <button onClick={() => selectedGroupId ? void loadDashboard(selectedGroupId) : void loadGroups()}
                className="ml-auto inline-flex items-center gap-1 text-xs font-medium hover:text-rose-300 transition-colors">
                <RefreshCw className="h-3.5 w-3.5" /> Retry
              </button>
            </div>
          )}

          {!loadingGroups && groups.length === 0 && !error && (
            <div className="text-center py-20">
              <Building2 className="h-12 w-12 text-[var(--ff-text-tertiary)] mx-auto mb-4" />
              <h2 className="text-lg font-semibold text-[var(--ff-text-primary)] mb-2">No Company Groups</h2>
              <p className="text-sm text-[var(--ff-text-secondary)] mb-6 max-w-md mx-auto">Create a group to consolidate financial data across multiple entities.</p>
              <Link href="/accounting/group/setup" className="inline-flex items-center gap-2 px-5 py-2.5 bg-teal-600 text-white rounded-lg hover:bg-teal-700 transition-colors text-sm font-medium">
                <Plus className="h-4 w-4" /> Create Your First Group
              </Link>
            </div>
          )}

          {loadingDash && selectedGroupId && (
            <div className="flex items-center justify-center py-20"><Loader2 className="h-8 w-8 animate-spin text-teal-500" /></div>
          )}

          {selectedGroup && dashData && !loadingDash && (
            <>
              <div className="flex items-center justify-between flex-wrap gap-3 p-4 rounded-lg border border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]">
                <div>
                  <p className="text-sm font-medium text-[var(--ff-text-primary)]">{selectedGroup.name}</p>
                  <p className="text-xs text-[var(--ff-text-tertiary)]">Holding: {selectedGroup.holdingCompanyName} &middot; {selectedGroup.memberCount} {selectedGroup.memberCount === 1 ? 'entity' : 'entities'}</p>
                </div>
                <Link href="/accounting/group/setup" className="inline-flex items-center gap-2 px-3 py-1.5 rounded-lg border border-[var(--ff-border-primary)] text-sm text-[var(--ff-text-secondary)] hover:text-teal-500 hover:border-teal-500/50 transition-colors">
                  <Settings className="h-3.5 w-3.5" /> Manage Group
                </Link>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                {STAT_CARDS.map(({ key, label, sub, Icon }) => (
                  <div key={key} className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-5">
                    <div className="flex items-center justify-between mb-1">
                      <span className="text-xs font-medium uppercase tracking-wider text-[var(--ff-text-secondary)]">{label}</span>
                      <Icon className="h-4 w-4 text-teal-500" />
                    </div>
                    <p className="text-2xl font-bold text-[var(--ff-text-primary)]">{fmtCompact(dashData[key])}</p>
                    <p className="text-xs mt-1 text-[var(--ff-text-tertiary)]">{sub}</p>
                  </div>
                ))}
              </div>

              <GroupEntityTable entities={dashData.entities} totals={totals} />

              <div>
                <h2 className="text-sm font-semibold text-[var(--ff-text-primary)] mb-3">Consolidated Reports</h2>
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
                  {QUICK_LINKS.map(link => {
                    const Icon = link.icon;
                    return (
                      <Link key={link.href} href={link.href}
                        className="flex items-center gap-3 p-4 rounded-lg border border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] hover:border-teal-500/50 hover:bg-teal-500/5 transition-colors group">
                        <div className="p-2 rounded-lg bg-teal-500/10 group-hover:bg-teal-500/20 transition-colors">
                          <Icon className="h-4 w-4 text-teal-500" />
                        </div>
                        <div className="flex-1 min-w-0">
                          <p className="text-sm font-medium text-[var(--ff-text-primary)] group-hover:text-teal-500 transition-colors">{link.label}</p>
                          <p className="text-xs text-[var(--ff-text-tertiary)] truncate">{link.description}</p>
                        </div>
                        <ArrowRight className="h-4 w-4 text-[var(--ff-text-tertiary)] group-hover:text-teal-500 transition-colors flex-shrink-0" />
                      </Link>
                    );
                  })}
                </div>
              </div>
            </>
          )}
        </div>
      </div>
    </AppLayout>
  );
}

/**
 * Journal Entry Detail Page
 * GET /accounting/journal-entries/:entryId
 * Shows full entry with lines, and actions (post/reverse)
 */

import { useState, useEffect, useCallback } from 'react';
import { useRouter } from 'next/router';
import Link from 'next/link';
import { AppLayout } from '@/components/layout/AppLayout';
import { log } from '@/lib/logger';
import {
  ArrowLeft,
  Loader2,
  AlertCircle,
  CheckCircle2,
  RotateCcw,
  FileSpreadsheet,
  Calendar,
  User,
  Hash,
} from 'lucide-react';
import type { JournalEntry, JournalLine } from '@/modules/accounting/types/gl.types';
import { apiFetch } from '@/lib/apiFetch';

export default function JournalEntryDetailPage() {
  const router = useRouter();
  const { entryId } = router.query;
  const [entry, setEntry] = useState<JournalEntry | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [actionLoading, setActionLoading] = useState<string | null>(null);

  useEffect(() => {
    if (entryId) loadEntry();
  }, [entryId]);

  const loadEntry = async () => {
    setIsLoading(true);
    setError(null);
    try {
      const res = await apiFetch(`/api/accounting/journal-entries-detail?id=${entryId}`);
      if (!res.ok) {
        const errData = await res.json();
        throw new Error(errData.message || 'Failed to load entry');
      }
      const data = await res.json();
      setEntry(data.data || data);
    } catch (err) {
      const msg = err instanceof Error ? err.message : 'Failed to load journal entry';
      setError(msg);
      log.error('Failed to load journal entry', { entryId, error: err }, 'accounting-ui');
    } finally {
      setIsLoading(false);
    }
  };

  const handleAction = useCallback(async (action: 'post' | 'reverse') => {
    if (!entry) return;
    setActionLoading(action);
    try {
      const res = await apiFetch('/api/accounting/journal-entries-action', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ id: entry.id, action }),
      });
      if (!res.ok) {
        const errData = await res.json();
        throw new Error(errData.message || `Failed to ${action} entry`);
      }
      await loadEntry();
    } catch (err) {
      const msg = err instanceof Error ? err.message : `Failed to ${action} entry`;
      setError(msg);
      log.error('Journal entry action failed', { entryId, action, error: err }, 'accounting-ui');
    } finally {
      setActionLoading(null);
    }
  }, [entry, entryId]);

  const formatCurrency = (amount: number | string) => {
    const num = Number(amount);
    return num === 0 ? '-' : `R ${num.toLocaleString('en-ZA', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
  };

  const statusColors: Record<string, string> = {
    draft: 'bg-amber-500/20 text-amber-400 border-amber-500/30',
    posted: 'bg-teal-500/20 text-teal-400 border-teal-500/30',
    reversed: 'bg-red-500/20 text-red-400 border-red-500/30',
    voided: 'bg-gray-500/20 text-gray-400 border-gray-500/30',
  };

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        {/* Header */}
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <Link
                href="/accounting?tab=journal-entries"
                className="p-2 rounded-lg hover:bg-[var(--ff-bg-tertiary)] transition-colors"
              >
                <ArrowLeft className="h-5 w-5 text-[var(--ff-text-secondary)]" />
              </Link>
              <div>
                <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">
                  {entry?.entryNumber || 'Journal Entry'}
                </h1>
                <p className="text-sm text-[var(--ff-text-secondary)]">
                  {entry ? new Date(entry.entryDate).toLocaleDateString('en-ZA', { day: 'numeric', month: 'long', year: 'numeric' }) : ''}
                </p>
              </div>
            </div>

            {entry && (
              <div className="flex items-center gap-3">
                <span className={`inline-flex items-center px-3 py-1 rounded-lg text-sm font-medium uppercase border ${statusColors[entry.status] || statusColors.draft}`}>
                  {entry.status}
                </span>

                {entry.status === 'draft' && (
                  <button
                    onClick={() => handleAction('post')}
                    disabled={actionLoading === 'post'}
                    className="inline-flex items-center gap-2 px-4 py-2 bg-teal-600 text-white rounded-lg hover:bg-teal-700 transition-colors text-sm font-medium disabled:opacity-50"
                  >
                    {actionLoading === 'post' ? (
                      <Loader2 className="h-4 w-4 animate-spin" />
                    ) : (
                      <CheckCircle2 className="h-4 w-4" />
                    )}
                    Post Entry
                  </button>
                )}

                {entry.status === 'posted' && !entry.reversedBy && (
                  <button
                    onClick={() => handleAction('reverse')}
                    disabled={actionLoading === 'reverse'}
                    className="inline-flex items-center gap-2 px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 transition-colors text-sm font-medium disabled:opacity-50"
                  >
                    {actionLoading === 'reverse' ? (
                      <Loader2 className="h-4 w-4 animate-spin" />
                    ) : (
                      <RotateCcw className="h-4 w-4" />
                    )}
                    Reverse
                  </button>
                )}
              </div>
            )}
          </div>
        </div>

        <div className="p-6">
          {isLoading ? (
            <div className="flex justify-center py-12">
              <Loader2 className="h-8 w-8 animate-spin text-teal-500" />
            </div>
          ) : error ? (
            <div className="bg-red-500/10 border border-red-500/30 rounded-lg p-4 flex items-start gap-3">
              <AlertCircle className="h-5 w-5 text-red-400 mt-0.5 flex-shrink-0" />
              <div>
                <h3 className="text-sm font-medium text-red-400">Error</h3>
                <p className="text-sm text-red-400/80 mt-1">{error}</p>
              </div>
            </div>
          ) : entry ? (
            <div className="space-y-6">
              {/* Entry Details */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-6">
                  <h3 className="text-sm font-semibold uppercase tracking-wider text-[var(--ff-text-secondary)] mb-4">Entry Details</h3>
                  <div className="space-y-3">
                    <DetailRow icon={Hash} label="Entry Number" value={entry.entryNumber} />
                    <DetailRow icon={Calendar} label="Entry Date" value={new Date(entry.entryDate).toLocaleDateString()} />
                    <DetailRow icon={FileSpreadsheet} label="Source" value={entry.source} />
                    <DetailRow icon={User} label="Created By" value={entry.createdBy} />
                    {entry.description && (
                      <div>
                        <p className="text-xs font-medium uppercase tracking-wider text-[var(--ff-text-secondary)] mb-1">Description</p>
                        <p className="text-sm text-[var(--ff-text-primary)]">{entry.description}</p>
                      </div>
                    )}
                  </div>
                </div>

                <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-6">
                  <h3 className="text-sm font-semibold uppercase tracking-wider text-[var(--ff-text-secondary)] mb-4">Summary</h3>
                  <div className="space-y-3">
                    <div className="flex justify-between items-center">
                      <span className="text-sm text-[var(--ff-text-secondary)]">Total Debit</span>
                      <span className="text-lg font-bold text-[var(--ff-text-primary)]">
                        {formatCurrency(entry.lines?.reduce((s, l) => s + Number(l.debit), 0) || 0)}
                      </span>
                    </div>
                    <div className="flex justify-between items-center">
                      <span className="text-sm text-[var(--ff-text-secondary)]">Total Credit</span>
                      <span className="text-lg font-bold text-[var(--ff-text-primary)]">
                        {formatCurrency(entry.lines?.reduce((s, l) => s + Number(l.credit), 0) || 0)}
                      </span>
                    </div>
                    <div className="border-t border-[var(--ff-border-light)] pt-3">
                      <div className="flex justify-between items-center">
                        <span className="text-sm text-[var(--ff-text-secondary)]">Line Count</span>
                        <span className="text-sm font-medium text-[var(--ff-text-primary)]">{entry.lines?.length || 0}</span>
                      </div>
                    </div>
                    {entry.reversalOfId && (
                      <div className="bg-red-500/10 border border-red-500/20 rounded p-2 mt-2">
                        <p className="text-xs text-red-400">This entry is a reversal</p>
                      </div>
                    )}
                    {entry.reversedBy && (
                      <div className="bg-amber-500/10 border border-amber-500/20 rounded p-2 mt-2">
                        <p className="text-xs text-amber-400">This entry has been reversed</p>
                      </div>
                    )}
                  </div>
                </div>
              </div>

              {/* Journal Lines */}
              <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] overflow-hidden">
                <div className="px-6 py-4 border-b border-[var(--ff-border-light)]">
                  <h3 className="text-lg font-semibold text-[var(--ff-text-primary)]">Journal Lines</h3>
                </div>
                <div className="overflow-x-auto">
                  <table className="w-full">
                    <thead>
                      <tr className="bg-[var(--ff-bg-tertiary)] border-b border-[var(--ff-border-light)]">
                        <th className="px-6 py-3 text-left text-xs font-semibold uppercase tracking-wider text-[var(--ff-text-secondary)]">#</th>
                        <th className="px-6 py-3 text-left text-xs font-semibold uppercase tracking-wider text-[var(--ff-text-secondary)]">Account</th>
                        <th className="px-6 py-3 text-left text-xs font-semibold uppercase tracking-wider text-[var(--ff-text-secondary)]">Description</th>
                        <th className="px-6 py-3 text-right text-xs font-semibold uppercase tracking-wider text-[var(--ff-text-secondary)]">Debit</th>
                        <th className="px-6 py-3 text-right text-xs font-semibold uppercase tracking-wider text-[var(--ff-text-secondary)]">Credit</th>
                      </tr>
                    </thead>
                    <tbody>
                      {entry.lines?.map((line, idx) => (
                        <tr key={line.id} className="border-b border-[var(--ff-border-light)] hover:bg-[var(--ff-bg-tertiary)] transition-colors">
                          <td className="px-6 py-3 text-sm text-[var(--ff-text-tertiary)]">{idx + 1}</td>
                          <td className="px-6 py-3">
                            <div className="text-sm font-medium text-[var(--ff-text-primary)]">{line.accountCode || '-'}</div>
                            <div className="text-xs text-[var(--ff-text-secondary)]">{line.accountName || ''}</div>
                          </td>
                          <td className="px-6 py-3 text-sm text-[var(--ff-text-primary)]">{line.description || '-'}</td>
                          <td className="px-6 py-3 text-sm text-right font-medium text-[var(--ff-text-primary)]">
                            {formatCurrency(line.debit)}
                          </td>
                          <td className="px-6 py-3 text-sm text-right font-medium text-[var(--ff-text-primary)]">
                            {formatCurrency(line.credit)}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                    <tfoot>
                      <tr className="bg-[var(--ff-bg-tertiary)] border-t-2 border-[var(--ff-border-medium)]">
                        <td colSpan={3} className="px-6 py-3 text-sm font-semibold text-[var(--ff-text-primary)]">Total</td>
                        <td className="px-6 py-3 text-sm text-right font-bold text-[var(--ff-text-primary)]">
                          {formatCurrency(entry.lines?.reduce((s, l) => s + Number(l.debit), 0) || 0)}
                        </td>
                        <td className="px-6 py-3 text-sm text-right font-bold text-[var(--ff-text-primary)]">
                          {formatCurrency(entry.lines?.reduce((s, l) => s + Number(l.credit), 0) || 0)}
                        </td>
                      </tr>
                    </tfoot>
                  </table>
                </div>
              </div>
            </div>
          ) : null}
        </div>
      </div>
    </AppLayout>
  );
}

function DetailRow({ icon: Icon, label, value }: { icon: React.ElementType; label: string; value: string }) {
  return (
