/**
 * Manual Bank Transaction API — Spend Money / Receive Money
 * POST /api/accounting/bank-transactions-manual
 * Equivalent to Sage "Create Transaction" in Process Bank.
 *
 * Inserts a bank_transaction record and immediately allocates it
 * via the existing allocateTransaction service.
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';
import {
  allocateTransaction,
  type AllocationType,
} from '@/modules/accounting/services/bankReconciliationService';

// ── Types ─────────────────────────────────────────────────────────────────────

interface ManualTxBody {
  type: 'spend' | 'receive';
  bankAccountId: string;
  date: string;
  amount: number | string;
  reference?: string;
  description?: string;
  allocationType: AllocationType;
  /** GL account ID (when allocationType === 'account') */
  contraAccountId?: string;
  /** Supplier or Customer ID (when allocationType is supplier/customer) */
  entityId?: string;
  vatCode?: string;
}

// ── Handler ───────────────────────────────────────────────────────────────────

async function handler(req: CompanyApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'UNKNOWN', ['POST']);
  }

  const { companyId } = req;
  const userId: string = req.user?.id ?? req.user?.userId ?? 'system';

  const body = req.body as ManualTxBody;
  const {
    type,
    bankAccountId,
    date,
    amount: rawAmount,
    reference,
    description,
    allocationType,
    contraAccountId,
    entityId,
    vatCode,
  } = body;

  // ── Validation ─────────────────────────────────────────────────────────────

  if (!type || (type !== 'spend' && type !== 'receive')) {
    return apiResponse.badRequest(res, "type must be 'spend' or 'receive'");
  }
  if (!bankAccountId) {
    return apiResponse.badRequest(res, 'bankAccountId is required');
  }
  if (!date) {
    return apiResponse.badRequest(res, 'date is required');
  }
  const numericAmount = Number(rawAmount);
  if (!rawAmount || isNaN(numericAmount) || numericAmount <= 0) {
    return apiResponse.badRequest(res, 'amount must be a positive number');
  }
  if (!allocationType) {
    return apiResponse.badRequest(res, 'allocationType is required');
  }
  if (allocationType === 'account' && !contraAccountId) {
    return apiResponse.badRequest(res, 'contraAccountId is required when allocationType is account');
  }
  if ((allocationType === 'supplier' || allocationType === 'customer') && !entityId) {
    return apiResponse.badRequest(res, 'entityId is required when allocationType is supplier or customer');
  }

  // ── Amount sign — negative for spend, positive for receive ─────────────────

  const signedAmount = type === 'spend' ? -Math.abs(numericAmount) : Math.abs(numericAmount);

  try {
    // ── Step 1: Insert bank_transactions row ─────────────────────────────────

    const txRows = await sql`
      INSERT INTO bank_transactions (
        bank_account_id,
        transaction_date,
        amount,
        description,
        reference,
        status,
        company_id
      ) VALUES (
        ${bankAccountId}::UUID,
        ${date}::DATE,
        ${signedAmount},
        ${description ?? null},
        ${reference ?? null},
        'imported',
        ${companyId}
      )
      RETURNING id
    `;

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const txId = String((txRows as any[])[0]!.id);

    log.info('Manual bank transaction created', {
      txId, type, bankAccountId, amount: signedAmount, date,
    }, 'accounting-api');

    // ── Step 2: Immediately allocate the transaction ──────────────────────────

    const result = await allocateTransaction(
      companyId,
      txId,
      contraAccountId ?? '',
      userId,
      description,
      allocationType,
      entityId,
      vatCode,
    );

    log.info('Manual bank transaction allocated', {
      txId, journalEntryId: result.journalEntryId,
    }, 'accounting-api');

    return apiResponse.created(res, {
      bankTransactionId: txId,
      journalEntryId: result.journalEntryId,
      bankTransaction: result.bankTransaction,
    }, 'Transaction recorded and allocated successfully');
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Failed to record transaction';
    log.error('Manual bank transaction failed', { error: err }, 'accounting-api');
    return apiResponse.internalError(res, err, message);
  }
}


export default withCompany(withErrorHandler(handler));

/**
 * Goods Received Notes (GRN) API
 */
import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { sql, withTransaction } from '@/lib/neon';
import { log } from '@/lib/logger';
import { validateGRN, generateGRNNumber } from '@/modules/accounting/services/procurementService';
import type { CompanyApiRequest } from '@/lib/auth/withCompany';

type Row = Record<string, unknown>;

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  const companyId = (req as CompanyApiRequest).companyId;

  if (req.method === 'GET') {
    const { purchaseOrderId } = req.query;
    let rows: Row[];
    if (purchaseOrderId) {
      rows = await sql`SELECT g.*, po.po_number FROM goods_received_notes g LEFT JOIN purchase_orders po ON g.purchase_order_id = po.id WHERE g.purchase_order_id = ${String(purchaseOrderId)} AND g.company_id = ${companyId} ORDER BY g.received_date DESC` as Row[];
    } else {
      rows = await sql`SELECT g.*, po.po_number, s.name as supplier_name FROM goods_received_notes g LEFT JOIN purchase_orders po ON g.purchase_order_id = po.id LEFT JOIN suppliers s ON po.supplier_id = s.id WHERE g.company_id = ${companyId} ORDER BY g.received_date DESC LIMIT 200` as Row[];
    }
    return apiResponse.success(res, rows);
  }

  if (req.method === 'POST') {
    const body = req.body;
    const validation = validateGRN(body);
    if (!validation.success) return apiResponse.validationError(res, Object.fromEntries((validation.errors || []).map(e => [e.field, e.message])));

    const inserted = await withTransaction(async (tx) => {
      const countRes = await tx`SELECT COUNT(*) as cnt FROM goods_received_notes WHERE company_id = ${companyId}` as Row[];
      const grnNumber = generateGRNNumber(Number(countRes[0]?.cnt ?? 0));

      const rows = await tx`
        INSERT INTO goods_received_notes (company_id, grn_number, purchase_order_id, received_date, received_by, notes, created_by)
        VALUES (${companyId || null}, ${grnNumber}, ${body.purchaseOrderId}, ${body.receivedDate}, ${body.receivedBy}, ${body.notes || null}, ${String(req.user.id)})
        RETURNING *
      ` as Row[];

      const grnId = String(rows[0]?.id);
      for (const item of body.items) {
        await tx`INSERT INTO grn_items (grn_id, po_item_id, quantity_received, quantity_rejected, notes) VALUES (${grnId}, ${item.poItemId}, ${item.quantityReceived}, ${item.quantityRejected || 0}, ${item.notes || null})`;
        // Update PO item received quantity
        await tx`UPDATE po_items SET quantity_received = COALESCE(quantity_received, 0) + ${item.quantityReceived} WHERE id = ${item.poItemId}`;
      }

      // Update PO status
      const poItems = await tx`SELECT quantity, quantity_received FROM po_items WHERE purchase_order_id = ${body.purchaseOrderId}` as Row[];
      const allReceived = poItems.every((pi: any) => Number(pi.quantity_received) >= Number(pi.quantity));
      const someReceived = poItems.some((pi: any) => Number(pi.quantity_received) > 0);
      const newStatus = allReceived ? 'received' : someReceived ? 'partially_received' : 'approved';
      await tx`UPDATE purchase_orders SET status = ${newStatus}, updated_at = NOW() WHERE id = ${body.purchaseOrderId}`;

      return rows[0];
    });

    log.info('GRN created', { grn: (inserted as any)?.grn_number, po: body.purchaseOrderId }, 'accounting');
    return apiResponse.created(res, inserted);
  }

  return apiResponse.methodNotAllowed(res, req.method!, ['GET', 'POST']);
}

