/**
 * Client Portal — Invoices API
 * GET — list invoices for the authenticated portal user's client
 * Requires signed portal session cookie (JWT)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { getClientInvoices } from '@/modules/accounting/services/portalService';
import { jwtVerify } from 'jose';
import cookie from 'cookie';

const PORTAL_SECRET = new TextEncoder().encode(
  (() => { if (!process.env.JWT_SECRET) throw new Error('JWT_SECRET is required'); return process.env.JWT_SECRET + '-portal'; })()
);

async function getPortalSession(req: NextApiRequest): Promise<{ clientId: string } | null> {
  const cookies = cookie.parse(req.headers.cookie || '');
  const token = cookies.portal_session;
  if (!token) return null;
  try {
    const { payload } = await jwtVerify(token, PORTAL_SECRET);
    return { clientId: payload.clientId as string };
  } catch {
    return null;
  }
}

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method!, ['GET']);
  }

  const session = await getPortalSession(req);
  if (!session) {
    return apiResponse.unauthorized(res, 'Portal authentication required');
  }

  const clientId = req.query.clientId as string;
  if (!clientId) {
    return apiResponse.badRequest(res, 'clientId is required');
  }

  // Enforce tenant isolation — user can only access their own client data
  if (session.clientId !== clientId) {
    return apiResponse.forbidden(res, 'Access denied — clientId mismatch');
  }

  const invoices = await getClientInvoices(clientId);
  return apiResponse.success(res, { items: invoices });
}

export default withErrorHandler(handler);

/**
 * PayFast ITN (Instant Transaction Notification) Webhook
 * POST — called by PayFast servers to confirm payment status
 *
 * NO auth wrapper — this is a public webhook endpoint.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { handleITN } from '@/modules/accounting/services/paymentGatewayService';
import { log } from '@/lib/logger';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    res.setHeader('Allow', 'POST');
    return res.status(405).json({ error: 'Method not allowed' });
  }

  try {
    // Get source IP from request (may be behind proxy)
    const sourceIp = (req.headers['x-forwarded-for'] as string)?.split(',')[0]?.trim()
      || req.socket.remoteAddress
      || '';

    log.info('ITN received', { sourceIp, body: req.body }, 'PaymentGateway');

    const result = await handleITN(req.body || {}, sourceIp);

    if (!result.valid) {
      log.error('ITN validation failed', { transactionId: result.transactionId }, 'PaymentGateway');
      // PayFast expects 200 OK even on validation failure to stop retries
      return res.status(200).json({ status: 'invalid' });
    }

    log.info('ITN processed successfully', { transactionId: result.transactionId }, 'PaymentGateway');
    return res.status(200).json({ status: 'ok' });
  } catch (error) {
    log.error('ITN processing error', error instanceof Error ? { message: error.message, stack: error.stack } : { error }, 'PaymentGateway');
    // Return 200 to prevent PayFast from retrying indefinitely
    return res.status(200).json({ status: 'error' });
  }
}

// Public webhook — no auth required, but wrapped for consistent error handling.
// The res.status(200) responses inside the handler are intentional: PayFast
// requires 200 OK to stop retrying, even when validation fails.
export default withErrorHandler(handler);

