/**
 * Portal Chatbot API
 * POST: client asks a question, gets AI-powered response
 */
import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { classifyClientQuery, buildClientChatPrompt, parseClientChatResponse, sanitizeClientResponse, type ClientContext } from '@/modules/accounting/services/portalChatbotService';
import { jwtVerify } from 'jose';
import cookie from 'cookie';

const PORTAL_SECRET = new TextEncoder().encode(
  (() => { if (!process.env.JWT_SECRET) throw new Error('JWT_SECRET is required'); return process.env.JWT_SECRET + '-portal'; })()
);

type Row = Record<string, unknown>;

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') return apiResponse.methodNotAllowed(res, req.method!, ['POST']);

  // Authenticate portal session
  const cookies = cookie.parse(req.headers.cookie || '');
  const token = cookies.portal_session;
  if (!token) return res.status(401).json({ success: false, error: { message: 'Not authenticated' } });
  let sessionClientId: string;
  try {
    const { payload } = await jwtVerify(token, PORTAL_SECRET);
    sessionClientId = payload.clientId as string;
  } catch {
    return res.status(401).json({ success: false, error: { message: 'Invalid session' } });
  }

  const { question, clientId } = req.body;
  if (!question) return apiResponse.badRequest(res, 'question is required');
  if (!clientId || clientId !== sessionClientId) return apiResponse.badRequest(res, 'clientId mismatch or missing');
  if (question.length > 500) return apiResponse.badRequest(res, 'question too long (max 500 chars)');

  const queryType = classifyClientQuery(question);

  // Build client context from DB
  const clients = await sql`SELECT name FROM customers WHERE id = ${clientId} LIMIT 1` as Row[];
  const clientName = String(clients[0]?.name || 'Client');

  const balanceRows = await sql`SELECT COALESCE(SUM(total_amount - COALESCE(amount_paid, 0)), 0) as outstanding FROM customer_invoices WHERE customer_id = ${clientId} AND status NOT IN ('cancelled', 'draft', 'paid')` as Row[];
  const overdueRows = await sql`SELECT COALESCE(SUM(total_amount - COALESCE(amount_paid, 0)), 0) as overdue FROM customer_invoices WHERE customer_id = ${clientId} AND status NOT IN ('cancelled', 'draft', 'paid') AND due_date < CURRENT_DATE` as Row[];
  const invoiceCount = await sql`SELECT COUNT(*) as cnt FROM customer_invoices WHERE customer_id = ${clientId} AND status NOT IN ('cancelled', 'draft', 'paid')` as Row[];
  const lastPay = await sql`SELECT amount, payment_date FROM customer_payments WHERE customer_id = ${clientId} ORDER BY payment_date DESC LIMIT 1` as Row[];

  const ctx: ClientContext = {
    clientName,
    outstandingBalance: Number(balanceRows[0]?.outstanding ?? 0),
    overdueAmount: Number(overdueRows[0]?.overdue ?? 0),
    lastPaymentDate: lastPay[0] ? String(lastPay[0].payment_date) : '',
    lastPaymentAmount: Number(lastPay[0]?.amount ?? 0),
    openInvoices: Number(invoiceCount[0]?.cnt ?? 0),
    companyName: 'IsaFlow',
  };

  // Call Claude
  let chatResponse = null;
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (apiKey) {
    try {
      const prompt = buildClientChatPrompt(question, ctx);
      const response = await fetch('https://api.anthropic.com/v1/messages', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'x-api-key': apiKey, 'anthropic-version': '2023-06-01' },
        body: JSON.stringify({ model: 'claude-haiku-4-5-20251001', max_tokens: 512, messages: [{ role: 'user', content: prompt }] }),
      });
      if (response.ok) {
        const data = await response.json() as any;
        chatResponse = parseClientChatResponse(data.content?.[0]?.text || '');
        if (chatResponse) chatResponse.message = sanitizeClientResponse(chatResponse.message);
      }
    } catch (err) { log.error('Portal chatbot failed', { error: err }, 'ai'); }
  }

  if (!chatResponse) {
    chatResponse = { message: `Your outstanding balance is R${ctx.outstandingBalance.toLocaleString()}. You have ${ctx.openInvoices} open invoice(s).`, action: null };
  }

  log.info('Portal chat', { clientId, queryType }, 'ai');
  return apiResponse.success(res, { ...chatResponse, queryType, clientContext: { balance: ctx.outstandingBalance, overdue: ctx.overdueAmount, openInvoices: ctx.openInvoices } });
}
export default withErrorHandler(handler);

/**
 * Client Portal — Authentication API
 * POST — login with email/password, sets signed httpOnly session cookie
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { authenticatePortalUser } from '@/modules/accounting/services/portalService';
import { SignJWT } from 'jose';
import cookie from 'cookie';
import { checkRateLimit } from '@/lib/rateLimit';

const PORTAL_SECRET = new TextEncoder().encode(
  (() => { if (!process.env.JWT_SECRET) throw new Error('JWT_SECRET is required'); return process.env.JWT_SECRET + '-portal'; })()
);

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method!, ['POST']);
  }

  // Rate limit: 5 attempts per IP per 15 minutes
  const rawIp = Array.isArray(req.headers['x-forwarded-for'])
    ? req.headers['x-forwarded-for'][0]
    : req.headers['x-forwarded-for'] ?? req.socket.remoteAddress;
  const ip: string = rawIp ?? 'unknown';
  if (checkRateLimit(ip, { windowMs: 15 * 60 * 1000, maxRequests: 5 })) {
    return res.status(429).json({
      success: false,
      error: { code: 'RATE_LIMITED', message: 'Too many attempts. Please try again later.' },
    });
  }

  const { email, password } = req.body;
  if (!email || !password) {
    return apiResponse.badRequest(res, 'email and password are required');
  }

  const user = await authenticatePortalUser(email, password);
  if (!user) {
    return apiResponse.unauthorized(res, 'Invalid email or password');
  }

  // Sign a JWT for the portal session
  const token = await new SignJWT({ clientId: user.clientId, email: user.email })
    .setProtectedHeader({ alg: 'HS256' })
    .setExpirationTime('24h')
    .setIssuedAt()
    .sign(PORTAL_SECRET);

  // Set httpOnly signed cookie
  res.setHeader('Set-Cookie', cookie.serialize('portal_session', token, {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'strict',
    path: '/',
    maxAge: 60 * 60 * 24, // 24 hours
  }));

  return apiResponse.success(res, { user });
}

export default withErrorHandler(handler);

/**
 * Client Portal — Payment Link API
 * GET  — get payment link details by token
 * POST — create a new payment link for an invoice
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { createPaymentLink, getPaymentLink } from '@/modules/accounting/services/portalService';
import { generatePayFastForm } from '@/modules/accounting/services/paymentGatewayService';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
type Row = Record<string, unknown>;


async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    const token = req.query.token as string;
    if (!token) return apiResponse.badRequest(res, 'token is required');
    const link = await getPaymentLink(token);
    if (!link) return apiResponse.notFound(res, 'Payment link');

    // Enrich with invoice details and PayFast form data
    const enriched: Record<string, unknown> = { ...link };
    try {
      const invoiceRows = (await sql`
        SELECT ci.invoice_number, ci.due_date, ci.online_payment_enabled, ci.company_id,
               co.name AS company_name
        FROM customer_invoices ci
        LEFT JOIN companies co ON co.id = ci.company_id
        WHERE ci.id = ${link.invoiceId}::UUID
      `) as Row[];

      if (invoiceRows[0]) {
        enriched.invoiceNumber = invoiceRows[0].invoice_number;
        enriched.dueDate = invoiceRows[0].due_date;
        enriched.companyName = invoiceRows[0].company_name;

        // Generate PayFast form data if online payment is enabled
        if (invoiceRows[0].online_payment_enabled) {
          const appUrl = process.env.NEXT_PUBLIC_APP_URL || 'http://localhost:3101';
          const companyId = invoiceRows[0].company_id as string;
          try {
            const formData = await generatePayFastForm(
              companyId,
              link.invoiceId,
              `${appUrl}/portal/pay/${token}?payment_status=success`,
              `${appUrl}/portal/pay/${token}?payment_status=cancelled`,
              `${appUrl}/api/accounting/payment-gateway-itn`,
            );
            enriched.payfastFormData = formData;
          } catch (e) {
            log.error('Failed to generate PayFast form for portal', e instanceof Error ? { message: e.message } : { error: e }, 'PaymentLink');
          }
        }
      }
    } catch (e) {
      log.error('Failed to enrich payment link', e instanceof Error ? { message: e.message } : { error: e }, 'PaymentLink');
    }

    return apiResponse.success(res, enriched);
  }

  if (req.method === 'POST') {
    const { invoiceId, clientId, amount } = req.body;
    if (!invoiceId || !clientId || !amount) {
      return apiResponse.badRequest(res, 'invoiceId, clientId, and amount are required');
    }

    // Resolve the authenticated user's company
    const userId = (req as AuthenticatedNextApiRequest).user.id;
    const companyRows = (await sql`
      SELECT company_id FROM company_users
      WHERE user_id = ${userId}
      ORDER BY is_default DESC, created_at ASC
      LIMIT 1
    `) as Row[];
    if (companyRows.length === 0) {
      return apiResponse.badRequest(res, 'No company assigned to this user');
    }
    const companyId = companyRows[0]!.company_id as string;

    // Verify invoice belongs to this company
    const invoice = (await sql`
      SELECT id FROM customer_invoices
      WHERE id = ${invoiceId}::UUID AND company_id = ${companyId}::UUID
    `) as Row[];
    if (invoice.length === 0) return apiResponse.notFound(res, 'Invoice not found');

    const token = await createPaymentLink(invoiceId, clientId, Number(amount));
    return apiResponse.success(res, { token, url: `/portal/pay/${token}` });
  }

  return apiResponse.methodNotAllowed(res, req.method!, ['GET', 'POST']);
}


export default withAuth(withErrorHandler(handler));

/**
 * Payment Gateway Service — PayFast integration
 * Handles payment form generation, ITN validation, and transaction tracking.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import crypto from 'crypto';
type Row = Record<string, unknown>;


// ── Config ──────────────────────────────────────────────────────────────────

const PAYFAST_SANDBOX_URL = 'https://sandbox.payfast.co.za/eng/process';
const PAYFAST_LIVE_URL = 'https://www.payfast.co.za/eng/process';

// PayFast valid IP ranges (production)
const PAYFAST_IP_RANGES = [
  '197.97.145.144/28',
  '41.74.179.192/27',
  '196.12.62.128/27',
];

// Sandbox allows any IP, but we still check in production
const PAYFAST_SANDBOX_IPS = ['127.0.0.1', '::1'];

function getConfig() {
  return {
    merchantId: process.env.PAYFAST_MERCHANT_ID || '',
    merchantKey: process.env.PAYFAST_MERCHANT_KEY || '',
    passphrase: process.env.PAYFAST_PASSPHRASE || '',
    isSandbox: process.env.PAYFAST_SANDBOX === 'true',
  };
}

function getPayFastUrl(): string {
  return getConfig().isSandbox ? PAYFAST_SANDBOX_URL : PAYFAST_LIVE_URL;
}

// ── Signature Generation ────────────────────────────────────────────────────

function generateSignature(data: Record<string, string>, passphrase: string): string {
  // Sort keys alphabetically, exclude blank values and 'signature' key
  const sortedKeys = Object.keys(data)
    .filter(k => k !== 'signature' && data[k] !== '' && data[k] !== undefined && data[k] !== null)
    .sort();

  const queryString = sortedKeys
    .map(k => `${k}=${encodeURIComponent(data[k]!).replace(/%20/g, '+')}`)
    .join('&');

  const toHash = passphrase ? `${queryString}&passphrase=${encodeURIComponent(passphrase).replace(/%20/g, '+')}` : queryString;

  return crypto.createHash('md5').update(toHash).digest('hex');
}

// ── IP Validation ───────────────────────────────────────────────────────────

function ipInCidr(ip: string, cidr: string): boolean {
  const [range, bitsStr] = cidr.split('/');
  if (!range || !bitsStr) return false;
  const bits = parseInt(bitsStr, 10);

  const ipParts = ip.split('.').map(Number);
  const rangeParts = range.split('.').map(Number);

  const ipNum = ((ipParts[0]! << 24) | (ipParts[1]! << 16) | (ipParts[2]! << 8) | ipParts[3]!) >>> 0;
  const rangeNum = ((rangeParts[0]! << 24) | (rangeParts[1]! << 16) | (rangeParts[2]! << 8) | rangeParts[3]!) >>> 0;
  const mask = (~0 << (32 - bits)) >>> 0;

  return (ipNum & mask) === (rangeNum & mask);
}

function isPayFastIp(ip: string): boolean {
  const config = getConfig();
  if (config.isSandbox) return true; // Sandbox mode: accept any IP

  // Strip IPv6 prefix
  const cleanIp = ip.startsWith('::ffff:') ? ip.slice(7) : ip;

  for (const cidr of PAYFAST_IP_RANGES) {
    if (ipInCidr(cleanIp, cidr)) return true;
  }
  return PAYFAST_SANDBOX_IPS.includes(cleanIp);
}

// ── Public Functions ────────────────────────────────────────────────────────

export interface PayFastFormData {
  paymentUrl: string;
  fields: Record<string, string>;
  transactionId: string;
}

/**
 * Generate PayFast payment form data for an invoice.
 */
export async function generatePayFastForm(
  companyId: string,
  invoiceId: string,
  returnUrl: string,
  cancelUrl: string,
  notifyUrl: string,
): Promise<PayFastFormData> {
  const config = getConfig();
  if (!config.merchantId || !config.merchantKey) {
    throw new Error('PayFast merchant credentials not configured');
  }

  // Look up invoice details
  const invoices = (await sql`
    SELECT ci.id, ci.invoice_number, ci.total_amount, ci.amount_paid,
           ci.client_name, ci.status,
           c.email AS client_email
    FROM customer_invoices ci
    LEFT JOIN customers c ON c.id = ci.client_id
    WHERE ci.id = ${invoiceId}::UUID AND ci.company_id = ${companyId}::UUID
  `) as Row[];

  if (!invoices[0]) throw new Error('Invoice not found');

  const invRow = invoices[0];
  const inv = {
    invoice_number: String(invRow.invoice_number ?? ''),
    total_amount: Number(invRow.total_amount),
    amount_paid: Number(invRow.amount_paid ?? 0),
    client_name: invRow.client_name != null ? String(invRow.client_name) : null,
    client_email: invRow.client_email != null ? String(invRow.client_email) : null,
  };
  const balance = inv.total_amount - inv.amount_paid;
  if (balance <= 0) throw new Error('Invoice is already fully paid');

  // Create payment transaction record
  const txRows = (await sql`
    INSERT INTO payment_transactions (company_id, invoice_id, gateway, amount, currency, customer_email, customer_name, status)
    VALUES (${companyId}::UUID, ${invoiceId}::UUID, 'payfast', ${balance}, 'ZAR', ${inv.client_email || ''}, ${inv.client_name || ''}, 'pending')
    RETURNING id
  `) as Row[];

  const transactionId = String(txRows[0]!.id);

  // Build PayFast form fields
  const fields: Record<string, string> = {
    merchant_id: config.merchantId,
    merchant_key: config.merchantKey,
    return_url: returnUrl,
    cancel_url: cancelUrl,
    notify_url: notifyUrl,
    m_payment_id: transactionId,
    amount: balance.toFixed(2),
    item_name: `Invoice ${inv.invoice_number}`.slice(0, 100),
    item_description: `Payment for invoice ${inv.invoice_number}`.slice(0, 255),
  };

  // Add customer email if available
  if (inv.client_email) {
    fields.email_address = inv.client_email;
  }

  // Add customer name if available
  if (inv.client_name) {
    const nameParts = inv.client_name.split(' ');
    fields.name_first = (nameParts[0] || '').slice(0, 100);
    fields.name_last = (nameParts.slice(1).join(' ') || '').slice(0, 100);
  }

  // Generate signature
  fields.signature = generateSignature(fields, config.passphrase);

  log.info('PayFast form generated', { transactionId, invoiceId, amount: balance }, 'PaymentGateway');

  return {
    paymentUrl: getPayFastUrl(),
    fields,
    transactionId,
  };
}

/**
 * Handle PayFast ITN (Instant Transaction Notification).
 * Validates the notification and updates payment status.
 */
export async function handleITN(
  body: Record<string, string>,
  sourceIp: string,
): Promise<{ valid: boolean; transactionId: string | null }> {
  const config = getConfig();

  // 1. Verify source IP
  if (!isPayFastIp(sourceIp)) {
    log.error('ITN rejected: invalid source IP', { sourceIp }, 'PaymentGateway');
    return { valid: false, transactionId: null };
  }

  // 2. Verify signature
  const receivedSignature = body.signature;
  if (!receivedSignature) {
    log.error('ITN rejected: no signature', {}, 'PaymentGateway');
    return { valid: false, transactionId: null };
  }

  const dataForSig = { ...body };
  delete dataForSig.signature;
  const expectedSignature = generateSignature(dataForSig, config.passphrase);

  if (receivedSignature !== expectedSignature) {
    log.error('ITN rejected: signature mismatch', { received: receivedSignature, expected: expectedSignature }, 'PaymentGateway');
    return { valid: false, transactionId: null };
  }

  const transactionId = body.m_payment_id || null;
  if (!transactionId) {
    log.error('ITN rejected: no m_payment_id', {}, 'PaymentGateway');
    return { valid: false, transactionId: null };
  }

  // 3. Look up the transaction
  const txRows = (await sql`
    SELECT id, company_id, invoice_id, amount, status
    FROM payment_transactions WHERE id = ${transactionId}::UUID
  `) as Row[];

  if (!txRows[0]) {
    log.error('ITN rejected: transaction not found', { transactionId }, 'PaymentGateway');
    return { valid: false, transactionId };
  }

  const tx = txRows[0];

  // 4. Verify amount matches
  const itnAmount = parseFloat(body.amount_gross || '0');
  const expectedAmount = Number(tx.amount);
  if (Math.abs(itnAmount - expectedAmount) > 0.01) {
    log.error('ITN rejected: amount mismatch', { expected: expectedAmount, received: itnAmount }, 'PaymentGateway');
    await sql`
      UPDATE payment_transactions SET status = 'failed', error_message = 'Amount mismatch', updated_at = NOW()
      WHERE id = ${transactionId}::UUID
    `;
    return { valid: false, transactionId };
  }

  // 5. Map PayFast status to our status
  const pfStatus = (body.payment_status || '').toUpperCase();
  let newStatus: string;
  switch (pfStatus) {
    case 'COMPLETE':
      newStatus = 'completed';
      break;
    case 'FAILED':
      newStatus = 'failed';
      break;
    case 'PENDING':
      newStatus = 'processing';
      break;
    case 'CANCELLED':
      newStatus = 'cancelled';
      break;
    default:
      newStatus = 'processing';
  }

  // 6. Update transaction
  await sql`
    UPDATE payment_transactions
    SET status = ${newStatus},
        gateway_ref = ${body.pf_payment_id || ''},
        payment_method = ${body.payment_method || ''},
        paid_at = ${newStatus === 'completed' ? new Date().toISOString() : null},
        metadata = ${JSON.stringify(body)}::JSONB,
        updated_at = NOW()
    WHERE id = ${transactionId}::UUID
  `;

  // 7. If completed, update the invoice
  if (newStatus === 'completed' && tx.invoice_id) {
    await sql`
      UPDATE customer_invoices
      SET amount_paid = COALESCE(amount_paid, 0) + ${itnAmount},
          status = CASE
            WHEN COALESCE(amount_paid, 0) + ${itnAmount} >= total_amount THEN 'paid'
            ELSE 'partially_paid'
          END,
          updated_at = NOW()
      WHERE id = ${tx.invoice_id}::UUID AND company_id = ${tx.company_id}::UUID
    `;

    log.info('Invoice payment recorded via PayFast', {
      transactionId, invoiceId: tx.invoice_id, amount: itnAmount, status: 'completed',
    }, 'PaymentGateway');
  }

  log.info('ITN processed', { transactionId, pfStatus, newStatus }, 'PaymentGateway');
  return { valid: true, transactionId };
}

/**
 * Get payment transaction details.
 */
export async function getPaymentStatus(companyId: string, transactionId: string) {
  const rows = (await sql`
    SELECT * FROM payment_transactions
    WHERE id = ${transactionId}::UUID AND company_id = ${companyId}::UUID
  `) as Row[];

  if (!rows[0]) return null;
  return mapTransaction(rows[0]);
}

/**
 * List all payment attempts for an invoice.
 */
export async function getInvoicePayments(companyId: string, invoiceId: string) {
  const rows = (await sql`
    SELECT * FROM payment_transactions
    WHERE invoice_id = ${invoiceId}::UUID AND company_id = ${companyId}::UUID
    ORDER BY created_at DESC
  `) as Row[];

  return rows.map(mapTransaction);
}

/**
 * Enable online payment for an invoice and generate a payment URL.
 */
export async function enableOnlinePayment(companyId: string, invoiceId: string): Promise<string> {
  const appUrl = process.env.NEXT_PUBLIC_APP_URL || 'http://localhost:3101';

  // Create a portal payment link token for public access
  const linkRows = (await sql`
    INSERT INTO portal_payment_links (invoice_id, client_id, amount)
    SELECT ci.id, ci.client_id, ci.total_amount - COALESCE(ci.amount_paid, 0)
    FROM customer_invoices ci
    WHERE ci.id = ${invoiceId}::UUID AND ci.company_id = ${companyId}::UUID
    RETURNING token
  `) as Row[];

  if (!linkRows[0]) throw new Error('Invoice not found or no balance due');

  const token = linkRows[0].token as string;
  const paymentUrl = `${appUrl}/portal/pay/${token}`;

  // Store the payment URL and enable online payments on the invoice
  await sql`
    UPDATE customer_invoices
    SET online_payment_enabled = true, payment_url = ${paymentUrl}, updated_at = NOW()
    WHERE id = ${invoiceId}::UUID AND company_id = ${companyId}::UUID
  `;

  log.info('Online payment enabled', { invoiceId, paymentUrl }, 'PaymentGateway');
  return paymentUrl;
}

// ── Mapper ──────────────────────────────────────────────────────────────────

interface PaymentTransaction {
  id: string;
  companyId: string;
  invoiceId: string | null;
  gateway: string;
  gatewayRef: string | null;
  amount: number;
  currency: string;
  status: string;
  customerEmail: string | null;
  customerName: string | null;
  paymentMethod: string | null;
  metadata: Record<string, unknown>;
  errorMessage: string | null;
  paidAt: string | null;
  createdAt: string;
  updatedAt: string;
}

function mapTransaction(r: Row): PaymentTransaction {
  return {
    id: String(r.id),
    companyId: String(r.company_id),
    invoiceId: r.invoice_id != null ? String(r.invoice_id) : null,
    gateway: String(r.gateway),
    gatewayRef: r.gateway_ref != null ? String(r.gateway_ref) : null,
    amount: Number(r.amount),
    currency: String(r.currency),
    status: String(r.status),
    customerEmail: r.customer_email != null ? String(r.customer_email) : null,
    customerName: r.customer_name != null ? String(r.customer_name) : null,
    paymentMethod: r.payment_method != null ? String(r.payment_method) : null,
    metadata: (r.metadata as Record<string, unknown>) || {},
    errorMessage: r.error_message != null ? String(r.error_message) : null,
    paidAt: r.paid_at != null ? String(r.paid_at) : null,
    createdAt: String(r.created_at),
    updatedAt: String(r.updated_at),
  };
}

/**
