/**
 * Audit Log API
 * GET /api/accounting/audit-log — List audit entries with filters and pagination
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { getAuditLog } from '@/modules/accounting/services/auditTrailService';

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;

  if (req.method === 'GET') {
    try {
      const {
        entity_type,
        entity_id,
        user_id,
        action,
        date_from,
        date_to,
        search,
        limit,
        offset,
      } = req.query;

      const result = await getAuditLog(companyId, {
        entityType: entity_type as string | undefined,
        entityId: entity_id as string | undefined,
        userId: user_id as string | undefined,
        action: action as string | undefined,
        dateFrom: date_from as string | undefined,
        dateTo: date_to as string | undefined,
        search: search as string | undefined,
        limit: limit ? Number(limit) : undefined,
        offset: offset ? Number(offset) : undefined,
      });

      return apiResponse.success(res, result);
    } catch (err) {
      log.error('Failed to get audit log', { error: err }, 'audit-log-api');
      return apiResponse.internalError(res, err, 'Failed to get audit log');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);
}

/**
 * Items API — CRUD for inventory / service items
 * GET:    list items (with filters) or single item (?id=UUID)
 * POST:   create new item
 * PUT:    update existing item
 * DELETE: soft-delete (set is_active = false)
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import {
  getItem,
  listItems,
  createItem,
  updateItem,
  softDeleteItem,
  itemExists,
  checkCodeDuplicate,
  type ItemFilters,
  type CreateItemInput,
  type UpdateItemInput,
} from '@/modules/accounting/services/itemService';

async function handler(req: CompanyApiRequest, res: NextApiResponse) {
  const companyId = req.companyId;

  /* ------------------------------------------------------------------ */
  /*  GET — list items or fetch single item                             */
  /* ------------------------------------------------------------------ */
  if (req.method === 'GET') {
    const { id, q, type, active, category_id } = req.query;

    if (id) {
      const item = await getItem(companyId, String(id));
      if (!item) return apiResponse.notFound(res, 'Item', String(id));
      return apiResponse.success(res, item);
    }

    const rawType = String(type || '');
    const filters: ItemFilters = {
      q: q ? String(q) : undefined,
      type: rawType === 'physical' || rawType === 'service' ? rawType : undefined,
      active: active === 'true' ? 'true' : active === 'false' ? 'false' : undefined,
      category_id: category_id ? String(category_id) : undefined,
    };

    const rows = await listItems(companyId, filters);
    return apiResponse.success(res, rows);

    return apiResponse.created(res, item);
  }

  /* ------------------------------------------------------------------ */
  /*  PUT — update item                                                 */
  /* ------------------------------------------------------------------ */
  if (req.method === 'PUT') {
    const body = req.body as Record<string, unknown>;
    const id = String(body.id || '');
    if (!id) {
      return apiResponse.validationError(res, { id: 'Item id is required' });
    }

    const exists = await itemExists(companyId, id);
    if (!exists) return apiResponse.notFound(res, 'Item', id);

    if (body.code !== undefined) {
      const newCode = String(body.code).trim();
      if (newCode) {
        const isDupe = await checkCodeDuplicate(companyId, newCode, id);
        if (isDupe) {
          return apiResponse.validationError(res, { code: `Item code '${newCode}' already exists` });
        }
      }
    }

    const input: UpdateItemInput = { id };
    if (body.code !== undefined) input.code = String(body.code);
    if (body.description !== undefined) input.description = String(body.description);
    if (body.item_type !== undefined) input.item_type = String(body.item_type);
    if (body.category_id !== undefined) input.category_id = String(body.category_id);
    if (body.is_active !== undefined) input.is_active = Boolean(body.is_active);
    if (body.unit !== undefined) input.unit = String(body.unit);
    if (body.cost_price !== undefined) input.cost_price = Number(body.cost_price);
    if (body.selling_price_excl !== undefined) input.selling_price_excl = Number(body.selling_price_excl);
    if (body.selling_price_incl !== undefined) input.selling_price_incl = Number(body.selling_price_incl);
    if (body.gp_percent !== undefined) input.gp_percent = Number(body.gp_percent);
    if (body.vat_on_sales !== undefined) input.vat_on_sales = String(body.vat_on_sales);
    if (body.vat_on_purchases !== undefined) input.vat_on_purchases = String(body.vat_on_purchases);
    if (body.sales_account_id !== undefined) input.sales_account_id = String(body.sales_account_id);
    if (body.purchases_account_id !== undefined) input.purchases_account_id = String(body.purchases_account_id);
    if (body.opening_qty !== undefined) input.opening_qty = Number(body.opening_qty);
    if (body.opening_cost !== undefined) input.opening_cost = Number(body.opening_cost);
    if (body.opening_date !== undefined) input.opening_date = String(body.opening_date);
    if (body.current_qty !== undefined) input.current_qty = Number(body.current_qty);
    if (body.notes !== undefined) input.notes = String(body.notes);
    if (body.image_url !== undefined) input.image_url = String(body.image_url);

    const updated = await updateItem(companyId, input);
    return apiResponse.success(res, updated);
  }

  /* ------------------------------------------------------------------ */
  /*  DELETE — soft-delete (set is_active = false)                      */
  /* ------------------------------------------------------------------ */
  if (req.method === 'DELETE') {
    const body = req.body as Record<string, unknown>;
    const id = String(body.id || '');
    if (!id) {
      return apiResponse.validationError(res, { id: 'Item id is required' });
    }

    const exists = await itemExists(companyId, id);
    if (!exists) return apiResponse.notFound(res, 'Item', id);

    await softDeleteItem(companyId, id);
    return apiResponse.success(res, { id, deleted: true });
  }

  return apiResponse.methodNotAllowed(res, req.method!, ['GET', 'POST', 'PUT', 'DELETE']);
}

export default withCompany(withErrorHandler(handler as any));

import { NextApiRequest, NextApiResponse } from 'next';
import { apiLogger } from '@/lib/logger';

const SENSITIVE_KEYS = new Set(['password', 'confirmPassword', 'password_hash', 'token', 'secret', 'apiKey', 'api_key']);

function sanitizeBody(body: unknown): unknown {
  if (!body || typeof body !== 'object') return body;
  const sanitized: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(body as Record<string, unknown>)) {
    sanitized[key] = SENSITIVE_KEYS.has(key) ? '[REDACTED]' : value;
  }
  return sanitized;
}

/**
 * Standard API error response
 */
export interface ApiErrorResponse {
  success: false;
  data: null;
  message: string;
  code?: string;
  details?: Record<string, unknown>;
}

/**
 * Standard API success response
 */
export interface ApiSuccessResponse<T = unknown> {
  success: true;
  data: T;
  message?: string;
}

export type ApiResponse<T = unknown> = ApiSuccessResponse<T> | ApiErrorResponse;

/**
 * Wraps an API handler with error handling.
 *
 * Generic R extends NextApiRequest to support AuthenticatedNextApiRequest,
 * CompanyApiRequest, or plain NextApiRequest without requiring `as any` casts.
 * The handler's res parameter is typed as NextApiResponse<any> so callers that
 * declare `res: NextApiResponse` (without a type argument) are assignable.
 */

export function withErrorHandler<R extends NextApiRequest = NextApiRequest>(
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  handler: (req: R, res: NextApiResponse<any>) => unknown
// eslint-disable-next-line @typescript-eslint/no-explicit-any
): (req: R, res: NextApiResponse<any>) => Promise<void | NextApiResponse<any>> {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  return async (req: R, res: NextApiResponse<any>) => {
    const startTime = Date.now();

    try {
      // Set CORS headers - restrict to known origins
      const allowedOrigins = [
        'https://app.isaflow.co.za',
        'https://admin.isaflow.co.za',
        'https://isaflow.co.za',
        ...(process.env.NODE_ENV === 'development'
          ? ['http://localhost:3101', 'http://localhost:3004']
          : []),
      ];
      const origin = req.headers.origin;
      if (origin && allowedOrigins.includes(origin)) {
        res.setHeader('Access-Control-Allow-Origin', origin);
        res.setHeader('Vary', 'Origin');
        res.setHeader('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
        res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Authorization');
      }

      // Handle OPTIONS request for CORS
      if (req.method === 'OPTIONS') {
        return res.status(200).end();
      }

      // Log incoming request
      apiLogger.info({
        type: 'request',
        method: req.method,
        url: req.url,
        query: req.query,
        body: req.method !== 'GET' ? sanitizeBody(req.body) : undefined,
      }, `API Request: ${req.method} ${req.url}`);

      // Execute the actual handler
      await handler(req, res);

      // Log successful response
      const duration = Date.now() - startTime;
      apiLogger.info({
        type: 'response',
        method: req.method,
        url: req.url,
        statusCode: res.statusCode,
        duration: `${duration}ms`,
      }, `API Response: ${req.method} ${req.url} - ${res.statusCode} (${duration}ms)`);

    } catch (error) {
      const duration = Date.now() - startTime;

      // Log error with context
      apiLogger.error({
        type: 'error',
        method: req.method,
        url: req.url,
        error: error instanceof Error ? error.message : 'Unknown error',
        stack: error instanceof Error ? error.stack : undefined,
        duration: `${duration}ms`,
      });

      // Check if headers were already sent
      if (res.headersSent) {
        apiLogger.warn({ method: req.method, url: req.url }, 'Headers already sent, cannot send error response');
        return;
      }

      // Send error response — mask internal details in production
      const errorMessage =
        process.env.NODE_ENV === 'production'
          ? 'An unexpected error occurred'
          : error instanceof Error ? error.message : 'An unexpected error occurred';

      res.status(500).json({
        success: false,
        data: null,
        message: errorMessage,
        code: 'INTERNAL_SERVER_ERROR',
        ...(process.env.NODE_ENV === 'development' && {
          details: error instanceof Error ? {
            message: error.message,
            stack: error.stack,
          } as Record<string, unknown> : { error: String(error) },
        }),
      });
    }
  };
}

/**
 * Creates a standard success response
 */
export function successResponse<T>(data: T, message?: string): ApiSuccessResponse<T> {
  return {
    success: true,
    data,
    ...(message && { message }),
  };
}

/**
 * Creates a standard error response
 */
export function errorResponse(
  message: string,
  code?: string,
  details?: Record<string, unknown>
): ApiErrorResponse {
  return {
    success: false,
    data: null,
    message,
    ...(code && { code }),
    ...(details && process.env.NODE_ENV === 'development' && { details }),
  };
}

/**
 * Common HTTP error responses
 */
export const HttpErrors = {
  BadRequest: (message = 'Bad Request') =>
    errorResponse(message, 'BAD_REQUEST'),

  Unauthorized: (message = 'Unauthorized') =>
    errorResponse(message, 'UNAUTHORIZED'),

  Forbidden: (message = 'Forbidden') =>
    errorResponse(message, 'FORBIDDEN'),

  NotFound: (message = 'Not Found') =>
    errorResponse(message, 'NOT_FOUND'),

  MethodNotAllowed: (method: string) =>
    errorResponse(`Method ${method} not allowed`, 'METHOD_NOT_ALLOWED'),

  InternalServerError: (message = 'Internal Server Error') =>
    errorResponse(message, 'INTERNAL_SERVER_ERROR'),

  DatabaseError: (message = 'Database operation failed') =>
    errorResponse(message, 'DATABASE_ERROR'),

  ValidationError: (message = 'Validation failed', details?: Record<string, unknown>) =>
    errorResponse(message, 'VALIDATION_ERROR', details),
};

