/**
 * Accounting Dashboard Stats API
 * GET /api/accounting/dashboard-stats
 * Returns aggregated financial metrics for the dashboard overview
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);
  }

  const { companyId } = req as CompanyApiRequest;

  try {
    const now = new Date();
    const year = now.getFullYear();
    const month = now.getMonth() + 1;
    const monthStart = `${year}-${String(month).padStart(2, '0')}-01`;

    // Run all queries in parallel
    const [
      bankBalances,
      apTotal,
      arTotal,
      monthRevenue,
      monthExpenses,
      unallocatedCount,
      recentJournals,
    ] = await Promise.all([
      // Bank account balances (from bank_transactions, matching bank-accounts API)
      sql`
        SELECT ga.account_code, ga.account_name,
          COALESCE(SUM(CASE WHEN bt.amount > 0 THEN bt.amount ELSE 0 END), 0)
          - COALESCE(SUM(CASE WHEN bt.amount < 0 THEN ABS(bt.amount) ELSE 0 END), 0) AS balance
        FROM gl_accounts ga
        LEFT JOIN bank_transactions bt ON bt.bank_account_id = ga.id
        WHERE ga.account_subtype = 'bank' AND ga.is_active = true AND ga.company_id = ${companyId}
        GROUP BY ga.id, ga.account_code, ga.account_name
        ORDER BY ga.account_code
      `,
      // Accounts Payable total (from supplier_invoices, matching AP aging)
      sql`
        SELECT COALESCE(SUM(total_amount - COALESCE(amount_paid, 0)), 0) AS total
        FROM supplier_invoices
        WHERE company_id = ${companyId} AND status NOT IN ('cancelled', 'paid')
      `,
      // Accounts Receivable total (from customer_invoices, matching AR aging)
      sql`
        SELECT COALESCE(SUM(total_amount - COALESCE(amount_paid, 0)), 0) AS total
        FROM customer_invoices
        WHERE company_id = ${companyId} AND status NOT IN ('cancelled', 'paid')
      `,
      // Revenue this month (account_type = 'revenue')
      sql`
        SELECT COALESCE(SUM(credit - debit), 0) AS total
        FROM gl_journal_lines jl
        JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
        JOIN gl_accounts ga ON ga.id = jl.gl_account_id
        WHERE ga.account_type = 'revenue' AND je.status = 'posted'
          AND je.company_id = ${companyId} AND je.entry_date >= ${monthStart}
      `,
      // Expenses this month (account_type = 'expense')
      sql`
        SELECT COALESCE(SUM(debit - credit), 0) AS total
        FROM gl_journal_lines jl
        JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
        JOIN gl_accounts ga ON ga.id = jl.gl_account_id
        WHERE ga.account_type = 'expense' AND je.status = 'posted'
          AND je.company_id = ${companyId} AND je.entry_date >= ${monthStart}
      `,
      // Unallocated bank transactions
      sql`
        SELECT COUNT(*) AS count FROM bank_transactions WHERE company_id = ${companyId} AND status = 'imported'
      `,
      // Recent journal entries (last 5)
      sql`
        SELECT id, entry_date, description, source, status,
          (SELECT SUM(debit) FROM gl_journal_lines WHERE journal_entry_id = je.id) AS total_debit
        FROM gl_journal_entries je
        WHERE je.company_id = ${companyId}
        ORDER BY created_at DESC LIMIT 5
      `,
    ]);

    const banks = (bankBalances as { account_code: string; account_name: string; balance: string }[]).map(b => ({
      code: b.account_code,
      name: b.account_name,
      balance: Number(b.balance),
    }));

    return apiResponse.success(res, {
      banks,
      totalBankBalance: banks.reduce((sum, b) => sum + b.balance, 0),
      apTotal: Number((apTotal as { total: string }[])[0]?.total || 0),
      arTotal: Number((arTotal as { total: string }[])[0]?.total || 0),
      monthRevenue: Number((monthRevenue as { total: string }[])[0]?.total || 0),
      monthExpenses: Number((monthExpenses as { total: string }[])[0]?.total || 0),
      unallocatedTx: Number((unallocatedCount as { count: string }[])[0]?.count || 0),
      recentJournals: (recentJournals as Record<string, unknown>[]).map(j => ({
        id: j.id,
        date: j.entry_date,
        description: j.description,
        source: j.source,
        status: j.status,
        amount: Number(j.total_debit || 0),
      })),
    });
  } catch (err) {
    log.error('Failed to load dashboard stats', { error: err }, 'accounting-api');
    return apiResponse.badRequest(res, 'Failed to load dashboard stats');
  }
}


export default withCompany(withErrorHandler(handler));

/**
 * KPI Dashboard API
 * GET /api/accounting/kpi-dashboard
 *   ?from=YYYY-MM-DD   - period start (defaults to start of current month)
 *   ?to=YYYY-MM-DD     - period end (defaults to today)
 *   ?months=N           - chart lookback months (default 6)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  getDashboardKPIs,
  getRevenueChart,
  getCashFlowChart,
  getAgingBreakdown,
  getTopCustomers,
  getTopExpenseCategories,
} from '@/modules/accounting/services/kpiService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);
  }

  const { companyId } = req as CompanyApiRequest;

  try {
    const now = new Date();
    const year = now.getFullYear();
    const month = now.getMonth() + 1;

    // Default to start of financial year (12 months back from current month-end)
    const fyStart = new Date(year, month - 13, 1); // ~12 months ago
    const from = req.query.from
      ? String(req.query.from)
      : fyStart.toISOString().slice(0, 10);
    const to = req.query.to
      ? String(req.query.to)
      : now.toISOString().slice(0, 10);
    const months = Math.max(1, Math.min(Number(req.query.months) || 6, 120));

    const [kpis, revenueChart, cashFlowChart, arAging, apAging, topCustomers, topExpenses] =
      await Promise.all([
        getDashboardKPIs(companyId, from, to),
        getRevenueChart(companyId, months),
        getCashFlowChart(companyId, months),
        getAgingBreakdown(companyId, 'ar'),
        getAgingBreakdown(companyId, 'ap'),
        getTopCustomers(companyId, 5),
        getTopExpenseCategories(companyId, 5),
      ]);

    return apiResponse.success(res, {
      kpis,
      revenueChart,
      cashFlowChart,
      arAging,
      apAging,
      topCustomers,
      topExpenses,
    });
  } catch (err) {
    log.error('Failed to load KPI dashboard', { error: err }, 'accounting-api');
    return apiResponse.internalError(res, err, 'Failed to load KPI dashboard');
  }
}


export default withCompany(withErrorHandler(handler));

/**
 * Executive Summary API
 * GET /api/accounting/reports-executive-summary?from=YYYY-MM-DD&to=YYYY-MM-DD
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import {
  buildExecutiveSummary,
  type ExecutiveSummaryInput,
} from '@/modules/accounting/services/executiveSummaryService';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = Record<string, any>;

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') return apiResponse.methodNotAllowed(res, req.method || '', ['GET']);

  const { companyId } = req as CompanyApiRequest;
  const from: string = (req.query.from as string) || new Date(new Date().getFullYear(), 0, 1).toISOString().split('T')[0]!;
  const to: string = (req.query.to as string) || new Date().toISOString().split('T')[0]!;

  const [current, prior, balances, empCount] = await Promise.all([
    getPnLTotals(companyId, from, to),
    getPriorPnL(companyId, from, to),
    getBalanceSheet(companyId, to),
    getEmployeeCount(companyId),
  ]);

  const companyRow = (await sql`
    SELECT name FROM companies WHERE id = ${companyId} LIMIT 1
  `) as Row[];
  const companyName: string = companyRow[0]?.name || 'Company';

  const revenue = parseFloat(current?.revenue || '0');
  const costOfSales = parseFloat(current?.cost_of_sales || '0');
  const operatingExpenses = parseFloat(current?.operating_expenses || '0');
  const netProfit = revenue - costOfSales - operatingExpenses;

  const input: ExecutiveSummaryInput = {
    period: `${from} to ${to}`,
    companyName,
    revenue,
    costOfSales,
    operatingExpenses,
    netProfit,
    totalAssets: parseFloat(balances?.total_assets || '0'),
    totalLiabilities: parseFloat(balances?.total_liabilities || '0'),
    totalEquity: parseFloat(balances?.total_equity || '0') + netProfit,
    currentAssets: parseFloat(balances?.current_assets || '0'),
    currentLiabilities: parseFloat(balances?.current_liabilities || '0'),
    cash: parseFloat(balances?.cash || '0'),
    accountsReceivable: parseFloat(balances?.accounts_receivable || '0'),
    accountsPayable: parseFloat(balances?.accounts_payable || '0'),
    inventory: parseFloat(balances?.inventory || '0'),
    priorRevenue: parseFloat(prior?.revenue || '0') || undefined,
    priorNetProfit: prior ? (() => {
      const pr = parseFloat(prior.revenue || '0');
      const pc = parseFloat(prior.cost_of_sales || '0');
      const po = parseFloat(prior.operating_expenses || '0');
      return pr - pc - po;
    })() : undefined,
  };

  const summary = buildExecutiveSummary(input, from, to);

  log.info('Executive summary generated', { companyId, from, to, employees: empCount }, 'accounting');

  return apiResponse.success(res, { summary, period: { from, to } });
}

async function getPnLTotals(companyId: string, from: string, to: string): Promise<Row | undefined> {
  const rows = (await sql`
    SELECT
      COALESCE(SUM(CASE WHEN ga.account_code LIKE '4%' THEN jl.credit - jl.debit ELSE 0 END), 0) as revenue,
      COALESCE(SUM(CASE WHEN ga.account_code LIKE '5%' AND ga.account_code < '5200' THEN jl.debit - jl.credit ELSE 0 END), 0) as cost_of_sales,
      COALESCE(SUM(CASE WHEN ga.account_code >= '5200' THEN jl.debit - jl.credit ELSE 0 END), 0) as operating_expenses
    FROM gl_journal_lines jl
    JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
    JOIN gl_accounts ga ON ga.id = jl.gl_account_id
    WHERE je.company_id = ${companyId} AND je.status = 'posted'
      AND je.entry_date >= ${from}::date AND je.entry_date <= ${to}::date
  `) as Row[];
  return rows[0];
}

async function getPriorPnL(companyId: string, from: string, to: string): Promise<Row | null> {
  const fromDate = new Date(from);
  const toDate = new Date(to);
  const daysDiff = Math.round((toDate.getTime() - fromDate.getTime()) / 86400000);
  const priorTo = new Date(fromDate.getTime() - 86400000).toISOString().split('T')[0]!;
  const priorFrom = new Date(fromDate.getTime() - (daysDiff + 1) * 86400000).toISOString().split('T')[0]!;

  const rows = (await sql`
    SELECT
      COALESCE(SUM(CASE WHEN ga.account_code LIKE '4%' THEN jl.credit - jl.debit ELSE 0 END), 0) as revenue,
      COALESCE(SUM(CASE WHEN ga.account_code LIKE '5%' AND ga.account_code < '5200' THEN jl.debit - jl.credit ELSE 0 END), 0) as cost_of_sales,
      COALESCE(SUM(CASE WHEN ga.account_code >= '5200' THEN jl.debit - jl.credit ELSE 0 END), 0) as operating_expenses
    FROM gl_journal_lines jl
    JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
    JOIN gl_accounts ga ON ga.id = jl.gl_account_id
    WHERE je.company_id = ${companyId} AND je.status = 'posted'
      AND je.entry_date >= ${priorFrom}::date AND je.entry_date <= ${priorTo}::date
  `) as Row[];
  return rows[0] || null;
}

async function getBalanceSheet(companyId: string, to: string): Promise<Row | undefined> {
  const rows = (await sql`
    SELECT
      COALESCE(SUM(CASE WHEN ga.account_code LIKE '1%' THEN jl.debit - jl.credit ELSE 0 END), 0) as total_assets,
      COALESCE(SUM(CASE WHEN ga.account_code LIKE '2%' THEN jl.credit - jl.debit ELSE 0 END), 0) as total_liabilities,
      COALESCE(SUM(CASE WHEN ga.account_code LIKE '3%' THEN jl.credit - jl.debit ELSE 0 END), 0) as total_equity,
      COALESCE(SUM(CASE WHEN ga.account_code >= '1100' AND ga.account_code < '1200' THEN jl.debit - jl.credit ELSE 0 END), 0) as current_assets,
      COALESCE(SUM(CASE WHEN ga.account_code >= '2100' AND ga.account_code < '2200' THEN jl.credit - jl.debit ELSE 0 END), 0) as current_liabilities,
      COALESCE(SUM(CASE WHEN ga.account_code = '1110' THEN jl.debit - jl.credit ELSE 0 END), 0) as cash,
      COALESCE(SUM(CASE WHEN ga.account_code = '1120' THEN jl.debit - jl.credit ELSE 0 END), 0) as accounts_receivable,
      COALESCE(SUM(CASE WHEN ga.account_code = '2110' THEN jl.credit - jl.debit ELSE 0 END), 0) as accounts_payable,
      COALESCE(SUM(CASE WHEN ga.account_code = '1130' THEN jl.debit - jl.credit ELSE 0 END), 0) as inventory
    FROM gl_journal_lines jl
    JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
    JOIN gl_accounts ga ON ga.id = jl.gl_account_id
    WHERE je.company_id = ${companyId} AND je.status = 'posted'
      AND je.entry_date <= ${to}::date
  `) as Row[];
  return rows[0];
}

async function getEmployeeCount(companyId: string): Promise<number> {
  const rows = (await sql`
    SELECT COUNT(*)::int as count FROM employees WHERE company_id = ${companyId} AND status = 'active'
  `) as Row[];
  return rows[0]?.count || 0;
}


export default withCompany(withErrorHandler(handler));

import { sql } from '@/lib/neon';
/**
 * Cash Flow Statement API
 * GET /api/accounting/reports-cash-flow?start_date=&end_date=
 * Sage equivalent: Reports > Cash Flow Statement
 *
 * Derives cash flow from GL journal lines using account subtypes:
 * - Operating: revenue, expense, receivable, payable changes
 * - Investing: asset account changes (non-cash)
 * - Financing: equity and loan changes
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';


async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);
  }

  const { companyId } = req as CompanyApiRequest;

  try {
    const { start_date, end_date } = req.query;

    const startDate = (start_date as string) || new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().split('T')[0];
    const endDate = (end_date as string) || new Date().toISOString().split('T')[0];

    // Check if account_subtype column exists (may not be populated)
    let hasSubtype = false;
    try {
      await sql`SELECT account_subtype FROM gl_accounts LIMIT 1`;
      hasSubtype = true;
    } catch {
      // Column doesn't exist
    }

    // Get opening cash balance (bank accounts at start_date)
    let openingBalance = 0;
    try {
      if (hasSubtype) {
        const [openingCash] = await sql`
          SELECT COALESCE(SUM(
            CASE WHEN ga.normal_balance = 'debit' THEN jl.debit - jl.credit ELSE jl.credit - jl.debit END
          ), 0)::numeric as balance
          FROM gl_journal_lines jl
          JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
          JOIN gl_accounts ga ON ga.id = jl.gl_account_id
          WHERE ga.account_subtype = 'bank'
            AND je.company_id = ${companyId}
            AND je.status = 'posted'
            AND je.entry_date < ${startDate}
        `;
        openingBalance = Number(openingCash?.balance || 0);
      } else {
        // Fall back to account_name matching for bank accounts
        const [openingCash] = await sql`
          SELECT COALESCE(SUM(
            CASE WHEN ga.normal_balance = 'debit' THEN jl.debit - jl.credit ELSE jl.credit - jl.debit END
          ), 0)::numeric as balance
          FROM gl_journal_lines jl
          JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
          JOIN gl_accounts ga ON ga.id = jl.gl_account_id
          WHERE (ga.account_name ILIKE '%bank%' OR ga.account_code LIKE '11%')
            AND ga.account_type = 'asset'
            AND je.company_id = ${companyId}
            AND je.status = 'posted'
            AND je.entry_date < ${startDate}
        `;
        openingBalance = Number(openingCash?.balance || 0);
      }
    } catch {
      openingBalance = 0;
    }

    // Operating Activities: Net Income + changes in working capital
    const [netIncome] = await sql`
      SELECT
        COALESCE(SUM(CASE WHEN ga.account_type = 'revenue' THEN jl.credit - jl.debit ELSE 0 END), 0)::numeric
        - COALESCE(SUM(CASE WHEN ga.account_type = 'expense' THEN jl.debit - jl.credit ELSE 0 END), 0)::numeric
        as net_income
      FROM gl_journal_lines jl
      JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
      JOIN gl_accounts ga ON ga.id = jl.gl_account_id
      WHERE je.status = 'posted'
        AND je.company_id = ${companyId}
        AND je.entry_date >= ${startDate}
        AND je.entry_date <= ${endDate}
        AND ga.account_type IN ('revenue', 'expense')
    `;

    // Changes in AR (receivable) — use subtype or fallback to account name
    let arChangeVal = 0;
    try {
      if (hasSubtype) {
        const [arChange] = await sql`
          SELECT COALESCE(SUM(jl.credit - jl.debit), 0)::numeric as change
          FROM gl_journal_lines jl
          JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
          JOIN gl_accounts ga ON ga.id = jl.gl_account_id
          WHERE ga.account_subtype = 'receivable'
            AND je.company_id = ${companyId}
            AND je.status = 'posted'
            AND je.entry_date >= ${startDate}
            AND je.entry_date <= ${endDate}
        `;
        arChangeVal = Number(arChange?.change || 0);
      } else {
        const [arChange] = await sql`
          SELECT COALESCE(SUM(jl.credit - jl.debit), 0)::numeric as change
          FROM gl_journal_lines jl
          JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
          JOIN gl_accounts ga ON ga.id = jl.gl_account_id
          WHERE ga.account_name ILIKE '%receivable%'
            AND je.company_id = ${companyId}
            AND je.status = 'posted'
            AND je.entry_date >= ${startDate}
            AND je.entry_date <= ${endDate}
        `;
        arChangeVal = Number(arChange?.change || 0);
      }
    } catch { arChangeVal = 0; }

    // Changes in AP (payable)
    let apChangeVal = 0;
    try {
      if (hasSubtype) {
        const [apChange] = await sql`
          SELECT COALESCE(SUM(jl.credit - jl.debit), 0)::numeric as change
          FROM gl_journal_lines jl
          JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
          JOIN gl_accounts ga ON ga.id = jl.gl_account_id
          WHERE ga.account_subtype = 'payable'
            AND je.company_id = ${companyId}
            AND je.status = 'posted'
            AND je.entry_date >= ${startDate}
            AND je.entry_date <= ${endDate}
        `;
        apChangeVal = Number(apChange?.change || 0);
      } else {
        const [apChange] = await sql`
          SELECT COALESCE(SUM(jl.credit - jl.debit), 0)::numeric as change
          FROM gl_journal_lines jl
          JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
          JOIN gl_accounts ga ON ga.id = jl.gl_account_id
          WHERE ga.account_name ILIKE '%payable%'
            AND je.company_id = ${companyId}
            AND je.status = 'posted'
            AND je.entry_date >= ${startDate}
            AND je.entry_date <= ${endDate}
        `;
        apChangeVal = Number(apChange?.change || 0);
      }
    } catch { apChangeVal = 0; }

    // Investing: fixed asset changes
    let investingChangeVal = 0;
    try {
      if (hasSubtype) {
        const [investingChange] = await sql`
          SELECT COALESCE(SUM(jl.credit - jl.debit), 0)::numeric as change
          FROM gl_journal_lines jl
          JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
          JOIN gl_accounts ga ON ga.id = jl.gl_account_id
          WHERE ga.account_subtype IN ('fixed_asset', 'other_asset')
            AND je.company_id = ${companyId}
            AND je.status = 'posted'
            AND je.entry_date >= ${startDate}
            AND je.entry_date <= ${endDate}
        `;
        investingChangeVal = Number(investingChange?.change || 0);
      } else {
        const [investingChange] = await sql`
          SELECT COALESCE(SUM(jl.credit - jl.debit), 0)::numeric as change
          FROM gl_journal_lines jl
          JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
          JOIN gl_accounts ga ON ga.id = jl.gl_account_id
          WHERE ga.account_type = 'asset'
            AND ga.account_name NOT ILIKE '%bank%'
            AND ga.account_name NOT ILIKE '%receivable%'
            AND ga.account_name NOT ILIKE '%cash%'
            AND je.company_id = ${companyId}
            AND je.status = 'posted'
            AND je.entry_date >= ${startDate}
            AND je.entry_date <= ${endDate}
        `;
        investingChangeVal = Number(investingChange?.change || 0);
      }
    } catch { investingChangeVal = 0; }

    // Financing: equity + loan changes
    let financingChangeVal = 0;
    try {
      if (hasSubtype) {
        const [financingChange] = await sql`
          SELECT COALESCE(SUM(jl.credit - jl.debit), 0)::numeric as change
          FROM gl_journal_lines jl
          JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
          JOIN gl_accounts ga ON ga.id = jl.gl_account_id
          WHERE ga.account_type = 'equity'
            AND (ga.account_subtype IS NULL OR ga.account_subtype != 'retained_earnings')
            AND je.company_id = ${companyId}
            AND je.status = 'posted'
            AND je.entry_date >= ${startDate}
            AND je.entry_date <= ${endDate}
        `;
        financingChangeVal = Number(financingChange?.change || 0);
      } else {
        const [financingChange] = await sql`
          SELECT COALESCE(SUM(jl.credit - jl.debit), 0)::numeric as change
          FROM gl_journal_lines jl
          JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
          JOIN gl_accounts ga ON ga.id = jl.gl_account_id
          WHERE ga.account_type = 'equity'
            AND ga.account_name NOT ILIKE '%retained%'
            AND je.company_id = ${companyId}
            AND je.status = 'posted'
            AND je.entry_date >= ${startDate}
            AND je.entry_date <= ${endDate}
        `;
        financingChangeVal = Number(financingChange?.change || 0);
      }
    } catch { financingChangeVal = 0; }

    const operatingTotal = Number(netIncome?.net_income || 0) + arChangeVal + apChangeVal;
    const investingTotal = investingChangeVal;
    const financingTotal = financingChangeVal;
    const netChange = operatingTotal + investingTotal + financingTotal;

    const report = {
      period_start: startDate,
      period_end: endDate,
      opening_cash: openingBalance,
      sections: [
        {
          section: 'Operating Activities',
          items: [
            { label: 'Net Income', amount: Number(netIncome?.net_income || 0) },
            { label: 'Change in Accounts Receivable', amount: arChangeVal },
            { label: 'Change in Accounts Payable', amount: apChangeVal },
          ],
          total: operatingTotal,
        },
        {
          section: 'Investing Activities',
          items: [
            { label: 'Fixed Asset Changes', amount: investingChangeVal },
          ],
          total: investingTotal,
        },
        {
          section: 'Financing Activities',
          items: [
            { label: 'Equity Changes', amount: financingChangeVal },
          ],
          total: financingTotal,
        },
      ],
      net_change: netChange,
      closing_cash: openingBalance + netChange,
    };

    return apiResponse.success(res, { report });
  } catch (err) {
    log.error('Failed to generate cash flow statement', { error: err, module: 'accounting' });
    return apiResponse.databaseError(res, err, 'Failed to generate cash flow statement');
  }
}


