import { sql } from '@/lib/neon';
/**
 * Budget vs Actual Report API
 * GET /api/accounting/reports-budget-vs-actual?period=current|ytd|full_year
 * Sage equivalent: Reports > Budget vs Actual
 *
 * Reads budgets from gl_accounts.budget_amount column (if exists)
 * or from app_settings key 'accounting_budgets'.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';


async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);
  }

  const { companyId } = req as CompanyApiRequest;

  try {
    const { period = 'ytd' } = req.query;

    // Determine date range
    let startDate: string;
    let endDate: string;
    const now = new Date();

    if (period === 'current') {
      startDate = new Date(now.getFullYear(), now.getMonth(), 1).toISOString().split('T')[0] ?? '';
      endDate = now.toISOString().split('T')[0] ?? '';
    } else {
      // YTD or full_year — use fiscal year start
      const [fy] = await sql`
        SELECT MIN(start_date) as start_date, MAX(end_date) as end_date
        FROM fiscal_periods
        WHERE company_id = ${companyId} AND fiscal_year = (SELECT fiscal_year FROM fiscal_periods WHERE company_id = ${companyId} AND status = 'open' ORDER BY start_date DESC LIMIT 1)
      `;
      startDate = fy?.start_date?.toString().split('T')[0] || `${now.getFullYear()}-03-01`;
      endDate = period === 'full_year'
        ? (fy?.end_date?.toString().split('T')[0] || `${now.getFullYear() + 1}-02-28`)
        : (now.toISOString().split('T')[0] ?? '');
    }

    // Load budgets from accounting_budgets table
    // Determine which month columns to sum based on period
    let budgets: Record<string, number> = {};
    try {
      const fiscalYear = new Date(startDate).getFullYear();
      const startMonth = new Date(startDate).getMonth(); // 0-based
      const endMonth = new Date(endDate).getMonth();
      const monthCols = ['jan','feb','mar','apr','may','jun','jul','aug','sep','oct','nov','dec'];

      const budgetRows = await sql`
        SELECT ab.gl_account_id, ga.account_code,
          ab.jan, ab.feb, ab.mar, ab.apr, ab.may, ab.jun,
          ab.jul, ab.aug, ab.sep, ab.oct, ab.nov, ab.dec
        FROM accounting_budgets ab
        JOIN gl_accounts ga ON ga.id = ab.gl_account_id
        WHERE ab.company_id = ${companyId} AND ab.fiscal_year = ${fiscalYear}
      `;
      for (const row of budgetRows) {
        let total = 0;
        for (let m = startMonth; m <= endMonth; m++) {
          total += Number(row[monthCols[m] ?? ''] ?? 0);
        }
        budgets[row.account_code] = total;
        budgets[row.gl_account_id] = total;
      }
    } catch {
      // No budgets configured yet — fall back to app_settings
      try {
        const [row] = await sql`SELECT value FROM app_settings WHERE key = 'accounting_budgets'`;
        if (row?.value) {
          budgets = typeof row.value === 'string' ? JSON.parse(row.value) : row.value;
        }
      } catch { /* no budgets */ }
    }

    // Get actual GL balances for expense and revenue accounts
    const actuals = await sql`
      SELECT
        ga.id, ga.account_code, ga.account_name, ga.account_type,
        COALESCE(SUM(
          CASE
            WHEN ga.account_type = 'expense' THEN jl.debit - jl.credit
            WHEN ga.account_type = 'revenue' THEN jl.credit - jl.debit
            ELSE jl.debit - jl.credit
          END
        ), 0)::numeric as actual_amount
      FROM gl_accounts ga
      LEFT JOIN gl_journal_lines jl ON jl.gl_account_id = ga.id
      LEFT JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
        AND je.status = 'posted'
        AND je.entry_date >= ${startDate}
        AND je.entry_date <= ${endDate}
      WHERE ga.level = 3
        AND ga.is_active = true
        AND ga.company_id = ${companyId}
        AND ga.account_type IN ('expense', 'revenue')
      GROUP BY ga.id, ga.account_code, ga.account_name, ga.account_type
      ORDER BY ga.account_code
    `;

    const lines = actuals.map(a => {
      const budgetAmount = Number(budgets[a.account_code] || budgets[a.id] || 0);
      const actualAmount = Number(a.actual_amount);
      // Revenue: positive variance = good (actual > budget)
      // Expense: positive variance = good (actual < budget, i.e. under budget)
      const variance = a.account_type === 'revenue'
        ? actualAmount - budgetAmount
        : budgetAmount - actualAmount;
      const variancePct = budgetAmount > 0
        ? (variance / budgetAmount) * 100
        : actualAmount > 0 ? -100 : 0;

      return {
        account_code: a.account_code,
        account_name: a.account_name,
        account_type: a.account_type,
        budget_amount: budgetAmount,
        actual_amount: actualAmount,
        variance,
        variance_pct: variancePct,
      };
    });

    const report = {
      period: `${startDate} to ${endDate}`,
      lines,
      total_budget: lines.reduce((s, l) => s + l.budget_amount, 0),
      total_actual: lines.reduce((s, l) => s + l.actual_amount, 0),
      total_variance: lines.reduce((s, l) => s + l.variance, 0),
    };

    return apiResponse.success(res, { report });
  } catch (err) {
    log.error('Failed to generate budget vs actual report', { error: err, module: 'accounting' });
    return apiResponse.databaseError(res, err, 'Failed to generate budget vs actual report');
  }
}


export default withCompany(withErrorHandler(handler));

/**
 * Report Pack API
 * GET /api/accounting/reports-pack?type=board|management|monthly&from=YYYY-MM-DD&to=YYYY-MM-DD
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import {
  buildReportPack,
  type PackType,
  type ReportPackInput,
} from '@/modules/accounting/services/reportPackService';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = Record<string, any>;

const VALID_TYPES: PackType[] = ['board', 'management', 'monthly'];

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') return apiResponse.methodNotAllowed(res, req.method || '', ['GET']);

  const { companyId } = req as CompanyApiRequest;
  const packType = (req.query.type as string) as PackType;
  const from: string = (req.query.from as string) || new Date(new Date().getFullYear(), 0, 1).toISOString().split('T')[0]!;
  const to: string = (req.query.to as string) || new Date().toISOString().split('T')[0]!;

  if (!packType || !VALID_TYPES.includes(packType)) {
    return apiResponse.badRequest(res, `type must be one of: ${VALID_TYPES.join(', ')}`);
  }

  const [pnlRow, balancesRow, companyRow] = await Promise.all([
    getPnLTotals(companyId, from, to),
    getBalanceSheet(companyId, to),
    getCompanyName(companyId),
  ]);

  const revenue = parseFloat(pnlRow?.revenue || '0');
  const costOfSales = parseFloat(pnlRow?.cost_of_sales || '0');
  const operatingExpenses = parseFloat(pnlRow?.operating_expenses || '0');
  const otherIncome = parseFloat(pnlRow?.other_income || '0');
  const otherExpenses = parseFloat(pnlRow?.other_expenses || '0');
  const netProfit = revenue - costOfSales - operatingExpenses + otherIncome - otherExpenses;

  const data: ReportPackInput = {
    companyName: companyRow?.name || 'Company',
    period: `${from} to ${to}`,
    revenue,
    costOfSales,
    operatingExpenses,
    netProfit,
    totalAssets: parseFloat(balancesRow?.total_assets || '0'),
    totalLiabilities: parseFloat(balancesRow?.total_liabilities || '0'),
    totalEquity: parseFloat(balancesRow?.total_equity || '0') + netProfit,
    currentAssets: parseFloat(balancesRow?.current_assets || '0'),
    currentLiabilities: parseFloat(balancesRow?.current_liabilities || '0'),
    cash: parseFloat(balancesRow?.cash || '0'),
    accountsReceivable: parseFloat(balancesRow?.accounts_receivable || '0'),
    accountsPayable: parseFloat(balancesRow?.accounts_payable || '0'),
    inventory: parseFloat(balancesRow?.inventory || '0'),
    otherIncome,
    otherExpenses,
  };

  const pack = buildReportPack(packType, data, from, to);

  log.info('Report pack generated', { companyId, packType, from, to }, 'accounting');

  return apiResponse.success(res, { pack, period: { from, to } });
}

async function getPnLTotals(companyId: string, from: string, to: string): Promise<Row | undefined> {
  const rows = (await sql`
    SELECT
      COALESCE(SUM(CASE WHEN ga.account_code LIKE '4%' THEN jl.credit - jl.debit ELSE 0 END), 0) as revenue,
      COALESCE(SUM(CASE WHEN ga.account_code LIKE '5%' AND ga.account_code < '5200' THEN jl.debit - jl.credit ELSE 0 END), 0) as cost_of_sales,
      COALESCE(SUM(CASE WHEN ga.account_code >= '5200' AND ga.account_code < '6000' THEN jl.debit - jl.credit ELSE 0 END), 0) as operating_expenses,
      COALESCE(SUM(CASE WHEN ga.account_code LIKE '6%' THEN jl.credit - jl.debit ELSE 0 END), 0) as other_income,
      COALESCE(SUM(CASE WHEN ga.account_code LIKE '7%' THEN jl.debit - jl.credit ELSE 0 END), 0) as other_expenses
    FROM gl_journal_lines jl
    JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
    JOIN gl_accounts ga ON ga.id = jl.gl_account_id
    WHERE je.company_id = ${companyId} AND je.status = 'posted'
      AND je.entry_date >= ${from}::date AND je.entry_date <= ${to}::date
  `) as Row[];
  return rows[0];
}

async function getBalanceSheet(companyId: string, to: string): Promise<Row | undefined> {
  const rows = (await sql`
    SELECT
      COALESCE(SUM(CASE WHEN ga.account_code LIKE '1%' THEN jl.debit - jl.credit ELSE 0 END), 0) as total_assets,
      COALESCE(SUM(CASE WHEN ga.account_code LIKE '2%' THEN jl.credit - jl.debit ELSE 0 END), 0) as total_liabilities,
      COALESCE(SUM(CASE WHEN ga.account_code LIKE '3%' THEN jl.credit - jl.debit ELSE 0 END), 0) as total_equity,
      COALESCE(SUM(CASE WHEN ga.account_code >= '1100' AND ga.account_code < '1200' THEN jl.debit - jl.credit ELSE 0 END), 0) as current_assets,
      COALESCE(SUM(CASE WHEN ga.account_code >= '2100' AND ga.account_code < '2200' THEN jl.credit - jl.debit ELSE 0 END), 0) as current_liabilities,
      COALESCE(SUM(CASE WHEN ga.account_code = '1110' THEN jl.debit - jl.credit ELSE 0 END), 0) as cash,
      COALESCE(SUM(CASE WHEN ga.account_code = '1120' THEN jl.debit - jl.credit ELSE 0 END), 0) as accounts_receivable,
      COALESCE(SUM(CASE WHEN ga.account_code = '2110' THEN jl.credit - jl.debit ELSE 0 END), 0) as accounts_payable,
      COALESCE(SUM(CASE WHEN ga.account_code = '1130' THEN jl.debit - jl.credit ELSE 0 END), 0) as inventory
    FROM gl_journal_lines jl
    JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
    JOIN gl_accounts ga ON ga.id = jl.gl_account_id
    WHERE je.company_id = ${companyId} AND je.status = 'posted'
      AND je.entry_date <= ${to}::date
  `) as Row[];
  return rows[0];
}

async function getCompanyName(companyId: string): Promise<Row | null> {
  const rows = (await sql`
    SELECT name FROM companies WHERE id = ${companyId} LIMIT 1
  `) as Row[];
  return rows[0] || null;
}


