/**
 * Depreciation Export API
 * GET — export depreciable assets as CSV
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { withErrorHandler } from '@/lib/api-error-handler';
import { csvCell } from '@/lib/csv';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);

  try {
    const proto = req.headers['x-forwarded-proto'] || 'http';
    const host = req.headers.host || 'localhost:3004';
    const baseUrl = `${proto}://${host}`;
    const assetRes = await fetch(`${baseUrl}/api/assets?status=available,assigned,in_maintenance&limit=500`, {
      headers: { cookie: req.headers.cookie || '' },
    });
    const assetJson = await assetRes.json();
    const assets = (assetJson.data?.items || assetJson.data?.assets || assetJson.data || [])
      .filter((a: Record<string, unknown>) => Number(a.purchase_price) > 0 && Number(a.useful_life_years) > 0);

    const csvLines = [
      'Asset Number,Name,Purchase Price,Book Value,Accum Depreciation,Useful Life (yrs),Salvage Value,Monthly Depreciation',
      ...assets.map((a: Record<string, unknown>) => {
        const pp = Number(a.purchase_price);
        const sv = Number(a.salvage_value || 0);
        const uly = Number(a.useful_life_years);
        const monthly = Math.round(((pp - sv) / uly / 12) * 100) / 100;
        return [
          csvCell(String(a.asset_number)),
          csvCell(String(a.name)),
          pp.toFixed(2),
          Number(a.current_book_value ?? pp).toFixed(2),
          Number(a.accumulated_depreciation || 0).toFixed(2),
          String(uly),
          sv.toFixed(2),
          monthly.toFixed(2),
        ].join(',');
      }),
    ];

    res.setHeader('Content-Type', 'text/csv');
    res.setHeader('Content-Disposition', `attachment; filename="depreciation-${new Date().toISOString().split('T')[0]}.csv"`);
    return res.status(200).send(csvLines.join('\n'));
  } catch (err) {
    log.error('Depreciation export failed', { error: err });
    return apiResponse.badRequest(res, 'Failed to export depreciation data');
  }
}

export default withCompany(withErrorHandler(handler));

/**
 * Sage Auto-Pull API
 * GET /api/accounting/migration/sage-pull?step=scripts
 *   → Returns JavaScript snippets the browser extension injects into Sage
 *
 * POST /api/accounting/migration/sage-pull
 *   → Receives raw Sage data from the browser, maps to ISAFlow format, returns mapped data
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest, type AuthenticatedNextApiRequest, withRole } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  buildSageAccountsFetchScript,
  buildSageFetchScript,
  buildSageCompanyFetchScript,
  mapSageAccounts,
  mapSageCustomers,
  mapSageSuppliers,
  mapSageARInvoices,
  mapSageAPInvoices,
} from '@/modules/accounting/services/sageAutoImportService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;

  if (req.method === 'GET') {
    // Return the JS scripts the browser extension will inject into Sage
    const scripts = {
      company: buildSageCompanyFetchScript(),
      accounts: buildSageAccountsFetchScript(),
      customers: buildSageFetchScript('/services/Customer/GetWithFilter', 200),
      suppliers: buildSageFetchScript('/services/Supplier/GetWithFilter', 200),
      arInvoices: buildSageFetchScript('/services/TaxInvoice/GetWithFilter', 200),
      apInvoices: buildSageFetchScript('/services/SupplierInvoice/GetWithFilter', 200),
    };

    return apiResponse.success(res, { scripts });
  }

  if (req.method === 'POST') {
    const { step, rawData } = req.body as { step: string; rawData: unknown };

    if (!step || !rawData) {
      return apiResponse.validationError(res, { step: 'step and rawData are required' });
    }

    log.info('Sage auto-pull received', { companyId, step }, 'migration');

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const data = rawData as any;

    switch (step) {
      case 'accounts': {
        const mapped = mapSageAccounts(data.Results || []);
        return apiResponse.success(res, {
          step: 'accounts',
          total: data.TotalResults || mapped.length,
          records: mapped,
        });
      }
      case 'customers': {
        const mapped = mapSageCustomers(data.Results || []);
        return apiResponse.success(res, {
          step: 'customers',
          total: data.TotalResults || mapped.length,
          records: mapped,
        });
      }
      case 'suppliers': {
        const mapped = mapSageSuppliers(data.Results || []);
        return apiResponse.success(res, {
          step: 'suppliers',
          total: data.TotalResults || mapped.length,
          records: mapped,
        });
      }
      case 'arInvoices': {
        const mapped = mapSageARInvoices(data.Results || []);
        return apiResponse.success(res, {
          step: 'arInvoices',
          total: data.TotalResults || mapped.length,
          records: mapped,
        });
      }
      case 'apInvoices': {
        const mapped = mapSageAPInvoices(data.Results || []);
        return apiResponse.success(res, {
          step: 'apInvoices',
          total: data.TotalResults || mapped.length,
          records: mapped,
        });
      }
      case 'company': {
        return apiResponse.success(res, {
          step: 'company',
          record: {
            name: data.Name,
            taxNumber: data.TaxNumber,
            registrationNumber: data.RegistrationNumber,
            currency: data.CurrencySymbol,
            takeOnDate: data.TakeOnBalanceDate,
          },
        });
      }
      default:
        return apiResponse.badRequest(res, `Unknown step: ${step}`);
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}

// Super admin only — ISAFlow internal tool
export default withCompany(withRole('super_admin')(withErrorHandler(handler)));

/**
 * AI Transaction Categorization API
 * POST: categorize a bank transaction using tiered strategy (Rules → Patterns → Claude LLM)
 */
import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { checkRateLimit } from '@/lib/rateLimit';
import type { CompanyApiRequest } from '@/lib/auth/withCompany';
import {
  buildCategorizationPrompt,
  parseCategorizationResponse,
  selectCategorizationStrategy,
  calculateConfidence,
  mergeCategorizationResults,
  type TransactionContext,
  type ChartOfAccountEntry,
  type CategorizationResult,
} from '@/modules/accounting/services/aiCategorizationService';

type Row = Record<string, unknown>;

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') return apiResponse.methodNotAllowed(res, req.method!, ['POST']);

  const ip = (req.headers['x-forwarded-for'] as string)?.split(',')[0]?.trim() || req.socket.remoteAddress || 'unknown';
  if (checkRateLimit(`ai-categorize:${ip}`, { maxRequests: 30, windowMs: 15 * 60 * 1000 })) {
    return res.status(429).json({ success: false, error: 'Rate limit exceeded' });
  }

  const { transactionId, description, amount, date } = req.body;
  if (!description) return apiResponse.badRequest(res, 'Transaction description is required');

  const companyId = (req as CompanyApiRequest).companyId;
  const isDebit = Number(amount || 0) < 0;

  const tx: TransactionContext = {
    description: String(description),
    amount: Number(amount || 0),
    date: String(date || new Date().toISOString().split('T')[0]),
    isDebit,
  };

  // Step 1: Check rules (match_value against description)
  let ruleResult: CategorizationResult | null = null;
  try {
    const rules = await sql`
      SELECT r.gl_account_id, r.priority, r.vat_code, ga.account_code, ga.account_name, ga.default_vat_code
      FROM bank_categorisation_rules r
      LEFT JOIN gl_accounts ga ON r.gl_account_id = ga.id
      WHERE r.is_active = true AND ${tx.description} ILIKE CONCAT('%', r.match_value, '%')
      ORDER BY r.priority DESC LIMIT 1
    ` as Row[];
    if (rules[0]) {
      const ruleVat = String(rules[0].vat_code || rules[0].default_vat_code || 'none');
      ruleResult = {
        accountCode: String(rules[0].account_code || ''),
        accountName: String(rules[0].account_name || ''),
        confidence: 1.0,
        reason: 'Matched bank categorisation rule',
        strategy: 'rules',
        vatCode: ruleVat as CategorizationResult['vatCode'],
      };
    }
  } catch { /* rules table might not have data */ }

  // Step 2: Check learned patterns
  let patternResult: CategorizationResult | null = null;
  try {
    const patterns = await sql`
      SELECT p.gl_account_id, p.confidence, p.vat_code, ga.account_code, ga.account_name, ga.default_vat_code
      FROM categorization_patterns p
      LEFT JOIN gl_accounts ga ON p.gl_account_id = ga.id
      WHERE ${tx.description} ILIKE CONCAT('%', p.pattern, '%')
      ORDER BY p.confidence DESC LIMIT 1
    ` as Row[];
    if (patterns[0]) {
      const patternVat = String(patterns[0].vat_code || patterns[0].default_vat_code || 'standard');
      patternResult = {
        accountCode: String(patterns[0].account_code || ''),
        accountName: String(patterns[0].account_name || ''),
        confidence: Number(patterns[0].confidence || 0.7),
        reason: 'Matched learned pattern',
        strategy: 'patterns',
        vatCode: patternVat as CategorizationResult['vatCode'],
      };
    }
  } catch { /* patterns table might not have data */ }

  // Step 3: Determine if we need LLM
  const strategy = selectCategorizationStrategy({
    hasRuleMatch: !!ruleResult,
    hasPatternMatch: !!patternResult,
    ruleConfidence: ruleResult?.confidence ?? 0,
    patternConfidence: patternResult?.confidence ?? 0,
  });

  const results: CategorizationResult[] = [];
  if (ruleResult) results.push(ruleResult);
  if (patternResult) results.push(patternResult);

  let llmUsed = false;

  if (strategy === 'llm') {
    // Get chart of accounts for prompt (include default VAT codes for context)
    const accounts = await sql`
      SELECT account_code as code, account_name as name, account_type as type, default_vat_code
      FROM gl_accounts WHERE is_active = true AND company_id = ${companyId}::UUID
      ORDER BY account_code LIMIT 50
    ` as Row[];

    const coaEntries: ChartOfAccountEntry[] = accounts.map((a: any) => ({
      code: String(a.code), name: String(a.name), type: String(a.type),
      defaultVatCode: a.default_vat_code ? String(a.default_vat_code) : undefined,
    }));

    const prompt = buildCategorizationPrompt(tx, coaEntries);

    // Call Claude API if ANTHROPIC_API_KEY is set
    const apiKey = process.env.ANTHROPIC_API_KEY;
    if (apiKey) {
      try {
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), 15000);
        const response = await fetch('https://api.anthropic.com/v1/messages', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'x-api-key': apiKey,
            'anthropic-version': '2023-06-01',
          },
          body: JSON.stringify({
            model: 'claude-haiku-4-5-20251001',
            max_tokens: 256,
            messages: [{ role: 'user', content: prompt }],
          }),
          signal: controller.signal,
        });
        clearTimeout(timeoutId);

        if (response.ok) {
          const data = await response.json() as { content?: { text?: string }[] };
          const text = data.content?.[0]?.text || '';
          const llmResult = parseCategorizationResponse(text);
          if (llmResult) {
            results.push(llmResult);
            llmUsed = true;
          }
        }
      } catch (err) {
        log.error('Claude API call failed', { error: err }, 'ai');
      }
    } else {
      log.info('ANTHROPIC_API_KEY not set, skipping LLM categorization', {}, 'ai');
    }
  }

  const merged = mergeCategorizationResults(results);
  const confidence = calculateConfidence(merged.confidence);

  log.info('AI categorization completed', {
    description: tx.description,
    strategy,
    llmUsed,
    result: merged.accountCode,
    confidence: merged.confidence,
  }, 'ai');

  // If no VAT code from the categorization pipeline, fall back to GL account default
  if (!merged.vatCode || merged.vatCode === 'none') {
    try {
      const [acct] = await sql`
        SELECT default_vat_code FROM gl_accounts
        WHERE account_code = ${merged.accountCode} AND company_id = ${companyId}::UUID AND is_active = true
        LIMIT 1
      ` as Row[];
      if (acct?.default_vat_code && acct.default_vat_code !== 'none') {
        merged.vatCode = String(acct.default_vat_code) as CategorizationResult['vatCode'];
        merged.vatReason = 'Default VAT for this account type';
      }
    } catch { /* non-critical */ }
  }

  return apiResponse.success(res, {
    ...merged,
    confidenceLevel: confidence,
    strategyUsed: strategy,
    llmUsed,
  });
}

export default withCompany(withErrorHandler(handler));

/**
 * Products API — CRUD for inventory items
 * GET: list products, POST: create product
 */
import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type AuthenticatedNextApiRequest, type CompanyApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { validateProduct, generateProductCode, type ProductInput } from '@/modules/accounting/services/inventoryService';

type Row = Record<string, unknown>;

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;

  if (req.method === 'GET') {
    const { search, category, type, active } = req.query;
    let rows: Row[];
    if (search) {
      const term = `%${String(search)}%`;
      rows = await sql`SELECT p.*, pc.name as category_name FROM products p LEFT JOIN product_categories pc ON p.category_id = pc.id WHERE p.company_id = ${companyId}::UUID AND (p.name ILIKE ${term} OR p.code ILIKE ${term} OR p.barcode ILIKE ${term}) ORDER BY p.name LIMIT 200` as Row[];
    } else if (category) {
      rows = await sql`SELECT p.*, pc.name as category_name FROM products p LEFT JOIN product_categories pc ON p.category_id = pc.id WHERE p.company_id = ${companyId}::UUID AND (p.category = ${String(category)} OR pc.code = ${String(category)}) ORDER BY p.name LIMIT 200` as Row[];
    } else if (type) {
      rows = await sql`SELECT p.*, pc.name as category_name FROM products p LEFT JOIN product_categories pc ON p.category_id = pc.id WHERE p.company_id = ${companyId}::UUID AND p.product_type = ${String(type)} ORDER BY p.name LIMIT 200` as Row[];
    } else {
      rows = await sql`SELECT p.*, pc.name as category_name FROM products p LEFT JOIN product_categories pc ON p.category_id = pc.id WHERE p.company_id = ${companyId}::UUID AND p.is_active = true ORDER BY p.name LIMIT 200` as Row[];
    }
    return apiResponse.success(res, rows);
  }
  if (req.method === 'POST') {
    const body = req.body as ProductInput;
    const validation = validateProduct(body);
    if (!validation.success) return apiResponse.validationError(res, Object.fromEntries((validation.errors || []).map(e => [e.field, e.message])));
    let categoryId: string | null = null;
    if (body.category) {
      const cats = await sql`SELECT id FROM product_categories WHERE code = ${body.category} AND company_id = ${companyId}::UUID LIMIT 1` as Row[];
      if (cats[0]) categoryId = String(cats[0].id);
    }
    const code = body.code || generateProductCode(body.category || 'general', 0);
    const inserted = await sql`
      INSERT INTO products (company_id, code, name, description, category_id, category, barcode, unit, product_type, cost_price, selling_price, cost_method, tax_rate, reorder_level, reorder_quantity, created_by)
      VALUES (${companyId}::UUID, ${code}, ${body.name}, ${body.description || null}, ${categoryId}, ${body.category || null}, ${body.barcode || null}, ${body.unit || 'each'}, ${body.type || 'inventory'}, ${body.costPrice || 0}, ${body.sellingPrice || 0}, ${body.costMethod || 'weighted_average'}, ${body.taxRate || 15}, ${body.reorderLevel || 0}, ${body.reorderQuantity || 0}, ${String(req.user.id)})
      RETURNING *
    ` as Row[];
    log.info('Product created', { code, name: body.name }, 'accounting');
    return apiResponse.created(res, inserted[0]);
