/**
 * Anomaly Detection Scan API
 * POST: run anomaly detection on recent transactions
 */
import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { CompanyApiRequest } from '@/lib/auth/withCompany';
import {
  benfordsLawAnalysis, detectStatisticalOutliers, detectDuplicatePayments,
  detectUnusualPostingPatterns, buildAlertMessage, type Transaction,
} from '@/modules/accounting/services/anomalyDetectionService';

type Row = Record<string, unknown>;

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') return apiResponse.methodNotAllowed(res, req.method!, ['POST']);

  const companyId = (req as CompanyApiRequest).companyId;
  const { period } = req.body;
  const fromDate = period || new Date(Date.now() - 90 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];

  // Get recent transactions — scoped to company
  const txRows = await sql`
    SELECT id, description, amount, transaction_date as date FROM bank_transactions
    WHERE company_id = ${companyId}::UUID AND transaction_date >= ${fromDate}
    ORDER BY transaction_date DESC LIMIT 1000
  ` as Row[];
  const transactions: Transaction[] = txRows.map((r: Row) => ({ id: String(r.id), amount: Number(r.amount), description: String(r.description), date: String(r.date) }));

  // Get recent payments for duplicate detection — scoped to company
  const payRows = await sql`
    SELECT sp.id, sp.supplier_id, sp.total_amount as amount, sp.payment_date as date, sp.reference
    FROM supplier_payments sp WHERE sp.company_id = ${companyId}::UUID AND sp.payment_date >= ${fromDate}
    ORDER BY sp.payment_date DESC LIMIT 500
  ` as Row[];
  const payments = payRows.map((r: Row) => ({ id: String(r.id), supplierId: String(r.supplier_id), amount: Number(r.amount), date: String(r.date), reference: String(r.reference || '') }));

  // Get journal entries for posting pattern analysis — scoped to company
  const jeRows = await sql`
    SELECT je.id, je.entry_date as date, jl.debit + jl.credit as amount, je.created_by as user_id, je.description
    FROM gl_journal_entries je JOIN gl_journal_lines jl ON je.id = jl.journal_entry_id
    WHERE je.company_id = ${companyId}::UUID AND je.entry_date >= ${fromDate} AND je.source = 'manual'
    LIMIT 500
  ` as Row[];
  const entries = jeRows.map((r: any) => ({ id: String(r.id), date: String(r.date), amount: Number(r.amount), userId: String(r.user_id), description: String(r.description || '') }));

  // Run all detections
  const benfords = benfordsLawAnalysis(transactions.map(t => Math.abs(t.amount)));
  const outliers = detectStatisticalOutliers(transactions);
  const duplicates = detectDuplicatePayments(payments);
  const patterns = detectUnusualPostingPatterns(entries);

  // Build alerts
  const alerts = [];
  if (!benfords.conforming && benfords.sampleSize > 20) {
    alerts.push(buildAlertMessage('benfords_violation', 'warning', { chiSquare: benfords.chiSquare }));
  }
  for (const o of outliers.outliers.slice(0, 5)) {
    alerts.push(buildAlertMessage('unusual_amount', 'warning', { amount: o.amount, description: o.description }));
  }
  for (const d of duplicates) {
    alerts.push(buildAlertMessage('duplicate_payment', d.confidence >= 0.9 ? 'critical' : 'warning', { amount: d.amount, supplier: d.supplierId }));
  }
  for (const p of patterns) {
    alerts.push(buildAlertMessage(p.type, 'info', { count: p.entryIds.length }));
  }

  log.info('Anomaly scan completed', { alerts: alerts.length, transactions: transactions.length }, 'ai');

  return apiResponse.success(res, {
    benfords, outliers: { count: outliers.outliers.length, items: outliers.outliers.slice(0, 10) },
    duplicates, patterns, alerts, scannedTransactions: transactions.length,
  });
}
export default withCompany(withErrorHandler(handler));

/**
 * Bank Rules Preview API
 * GET — returns count of transactions matching a pattern
 * Query params: bankAccountId, pattern, matchType, matchField
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';

type Row = Record<string, unknown>;

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;

  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method!, ['GET']);
  }

  const { bankAccountId, pattern, matchType = 'contains', matchField = 'description' } = req.query;

  if (!pattern || typeof pattern !== 'string') {
    return apiResponse.badRequest(res, 'pattern is required');
  }

  const raw = pattern.trim();
  if (!raw) return apiResponse.success(res, { matchCount: 0 });

  // Build ILIKE pattern
  let ilike: string;
  if (matchType === 'starts_with') ilike = `${raw}%`;
  else if (matchType === 'ends_with') ilike = `%${raw}`;
  else if (matchType === 'exact') ilike = raw;
  else ilike = `%${raw}%`;

  const bid = typeof bankAccountId === 'string' ? bankAccountId : null;
  const field = typeof matchField === 'string' ? matchField : 'description';

  // Explicit query branches: bankAccountId × matchField (no conditional SQL)
  let rows: Row[];

  if (bid && field === 'description') {
    rows = (await sql`SELECT COUNT(*)::INT AS cnt FROM bank_transactions WHERE bank_account_id = ${bid}::UUID AND description ILIKE ${ilike} AND company_id = ${companyId}`) as Row[];
  } else if (bid && field === 'reference') {
    rows = (await sql`SELECT COUNT(*)::INT AS cnt FROM bank_transactions WHERE bank_account_id = ${bid}::UUID AND reference ILIKE ${ilike} AND company_id = ${companyId}`) as Row[];
  } else if (bid && field === 'both') {
    rows = (await sql`SELECT COUNT(*)::INT AS cnt FROM bank_transactions WHERE bank_account_id = ${bid}::UUID AND (description ILIKE ${ilike} OR reference ILIKE ${ilike}) AND company_id = ${companyId}`) as Row[];
  } else if (field === 'reference') {
    rows = (await sql`SELECT COUNT(*)::INT AS cnt FROM bank_transactions WHERE reference ILIKE ${ilike} AND company_id = ${companyId}`) as Row[];
  } else if (field === 'both') {
    rows = (await sql`SELECT COUNT(*)::INT AS cnt FROM bank_transactions WHERE (description ILIKE ${ilike} OR reference ILIKE ${ilike}) AND company_id = ${companyId}`) as Row[];
  } else {
    rows = (await sql`SELECT COUNT(*)::INT AS cnt FROM bank_transactions WHERE description ILIKE ${ilike} AND company_id = ${companyId}`) as Row[];
  }

  return apiResponse.success(res, { matchCount: Number(rows[0]?.cnt || 0) });
}


export default withCompany(withErrorHandler(handler));

/**
 * Bank Rules Seed API
 * POST /api/accounting/bank-rules-seed
 *   Seed categorisation rules from a Category Map (JSON array).
 *
 * Body: { entries: [{ originalCategory, standardCategory, glCode }] }
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, withRole, type AuthenticatedNextApiRequest, type CompanyApiRequest } from '@/lib/auth';
import { sql, transaction } from '@/lib/neon';
import { log } from '@/lib/logger';

interface CategoryMapEntry {
  originalCategory: string;
  standardCategory: string;
  glCode: number | string;
}

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);
  }

  const { companyId } = req as CompanyApiRequest;

  try {
    const userId = req.user.id;
    const { entries } = req.body as { entries: CategoryMapEntry[] };

    if (!Array.isArray(entries) || entries.length === 0) {
      return apiResponse.badRequest(res, 'entries array is required');
    }

    // Fetch all GL accounts for this company in one query

    const glAccountRows = (await sql`
      SELECT id, account_code FROM gl_accounts WHERE company_id = ${companyId}
    `) as Record<string, unknown>[];
    const glAccountMap = new Map<string, string>(
      glAccountRows.map(r => [String(r.account_code), String(r.id)])
    );

    // Fetch all existing match_patterns for this company in one query
    const existingPatternRows = (await sql`
      SELECT LOWER(match_pattern) AS match_pattern FROM bank_categorisation_rules WHERE company_id = ${companyId}
    `) as Record<string, unknown>[];
    const existingPatterns = new Set<string>(existingPatternRows.map(r => String(r.match_pattern)));

    let skipped = 0;
    const missingGlCodes: (number | string)[] = [];

    interface RuleRow {
      ruleName: string;
      pattern: string;
      glAccountId: string;
    }
    const toInsert: RuleRow[] = [];

    for (const entry of entries) {
      const pattern = String(entry.originalCategory || '').toLowerCase().trim();
      if (!pattern) { skipped++; continue; }

      const glCode = String(entry.glCode).trim();
      if (!glCode) { skipped++; continue; }

      const glAccountId = glAccountMap.get(glCode);
      if (!glAccountId) {
        missingGlCodes.push(entry.glCode);
        skipped++;
        continue;
      }

      if (existingPatterns.has(pattern)) {
        skipped++;
        continue;
      }

      toInsert.push({
        ruleName: String(entry.standardCategory || entry.originalCategory).trim(),
        pattern,
        glAccountId,
      });
    }

    // Batch INSERT all new rules in a single transaction
    if (toInsert.length > 0) {
      await transaction((txSql) =>
        toInsert.map((r) =>
          txSql`
            INSERT INTO bank_categorisation_rules (
              rule_name, match_field, match_type, match_pattern,
              gl_account_id, auto_create_entry, priority, created_by,
              company_id
            ) VALUES (
              ${r.ruleName}, 'description', 'contains', ${r.pattern},
              ${r.glAccountId}::UUID, false, 100, ${userId},
              ${companyId}
            )
          `
        )
      );
    }

    const created = toInsert.length;

    log.info('Seeded bank categorisation rules', { created, skipped, missingGlCodes: missingGlCodes.length }, 'accounting');

    return apiResponse.success(res, {
      created,
      skipped,
      missingGlCodes: missingGlCodes.length > 0 ? missingGlCodes : undefined,
    });
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Failed to seed bank rules';
    log.error('Failed to seed bank rules', { error: err }, 'accounting-api');
    return apiResponse.badRequest(res, message);
  }
}


