/**
 * Company Documents API
 * GET  ?companyId=      — list active documents (without file_data)
 * GET  ?id=&download=1  — single doc with file_data for download
 * POST                  — create a new document
 * DELETE ?id=           — soft-delete a document
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';
import { isVlmAvailable } from '@/modules/accounting/services/vlmService';
import { extractStatutoryDocWithVlm } from '@/modules/accounting/services/vlmService';
import { log } from '@/lib/logger';
type Row = Record<string, unknown>;


async function handler(req: NextApiRequest, res: NextApiResponse) {
  const userId = (req as AuthenticatedNextApiRequest).user.id;

  // ── Helper: validate company membership ──
  async function validateMembership(companyId: string): Promise<boolean> {
    const rows = (await sql`
      SELECT role FROM company_users
      WHERE company_id = ${companyId}::UUID AND user_id = ${userId}
    `) as Row[];
    return rows.length > 0;
  }

  // ── GET ──
  if (req.method === 'GET') {
    // Download single doc
    if (req.query.id && req.query.download === '1') {
      const docDownloadId = typeof req.query.id === 'string' ? req.query.id : undefined;
      if (!docDownloadId) return apiResponse.badRequest(res, 'id must be a single value');
      const rows = (await sql`
        SELECT id, company_id, document_type, document_name, file_data,
               mime_type, file_size, uploaded_at, notes
        FROM company_documents
        WHERE id = ${docDownloadId}::UUID AND is_active = true
      `) as Row[];
      if (rows.length === 0) return apiResponse.notFound(res, 'Document');
      const doc = rows[0]!;
      if (!(await validateMembership(String(doc.company_id)))) {
        return apiResponse.forbidden(res, 'You do not have access to this company');
      }
      return apiResponse.success(res, {
        id: String(doc.id),
        documentType: String(doc.document_type),
        documentName: String(doc.document_name),
        fileData: doc.file_data,
        mimeType: String(doc.mime_type),
        fileSize: doc.file_size,
        uploadedAt: doc.uploaded_at,
        notes: doc.notes ?? null,
      });
    }

    // List docs for a company
    const companyId = typeof req.query.companyId === 'string' ? req.query.companyId : undefined;
    if (!companyId) return apiResponse.badRequest(res, 'companyId is required');
    if (!(await validateMembership(companyId))) {
      return apiResponse.forbidden(res, 'You do not have access to this company');
    }

    const rows = (await sql`
      SELECT id, document_type, document_name, mime_type,
             file_size, uploaded_at, notes
      FROM company_documents
      WHERE company_id = ${companyId}::UUID AND is_active = true
      ORDER BY uploaded_at DESC
    `) as Row[];

    return apiResponse.success(res, {
      items: rows.map((r: Row) => ({
        id: String(r.id),
        documentType: String(r.document_type),
        documentName: String(r.document_name),
        mimeType: String(r.mime_type),
        fileSize: r.file_size,
        uploadedAt: r.uploaded_at,
        notes: r.notes ?? null,
      })),
    });
  }

  // ── POST ──
  if (req.method === 'POST') {
    const { companyId, documentType, documentName, fileData, mimeType, fileSize, notes } = req.body;
    if (!companyId || !documentType || !documentName || !fileData) {
      return apiResponse.badRequest(res, 'companyId, documentType, documentName, and fileData are required');
    }
    const ALLOWED_DOC_MIMES = ['application/pdf', 'image/jpeg', 'image/png', 'image/gif'];
    if (mimeType && !ALLOWED_DOC_MIMES.includes(mimeType as string)) {
      return apiResponse.badRequest(res, `File type ${mimeType} not allowed`);
    }
    if (!(await validateMembership(companyId))) {
      return apiResponse.forbidden(res, 'You do not have access to this company');
    }

    const rows = (await sql`
      INSERT INTO company_documents (
        company_id, document_type, document_name,
        file_data, mime_type, file_size, uploaded_by, notes
      ) VALUES (
        ${companyId}::UUID, ${documentType}, ${documentName},
        ${fileData}, ${mimeType || 'application/octet-stream'},
        ${fileSize || 0}, ${userId}, ${notes || null}
      )
      RETURNING id
    `) as Row[];

    const docId = String(rows[0]!.id);

    // Fire-and-forget VLM extraction for statutory documents
    if (isVlmAvailable() && fileData) {
      extractStatutoryDocData(fileData, documentType, docId).catch(err =>
        log.warn('Statutory doc extraction failed', { error: err instanceof Error ? err.message : String(err) }, 'company-docs')
      );
    }

    return apiResponse.created(res, { id: docId });
  }

  // ── DELETE (soft) ──
  if (req.method === 'DELETE') {
    const docId = typeof req.query.id === 'string' ? req.query.id : undefined;
    if (!docId) return apiResponse.badRequest(res, 'id is required');

    const rows = (await sql`
      SELECT company_id FROM company_documents
      WHERE id = ${docId}::UUID AND is_active = true
    `) as Row[];
    if (rows.length === 0) return apiResponse.notFound(res, 'Document');
    if (!(await validateMembership(String(rows[0]!.company_id)))) {
      return apiResponse.forbidden(res, 'You do not have access to this company');
    }

    await sql`
      UPDATE company_documents SET is_active = false WHERE id = ${docId}::UUID
    `;
    return apiResponse.success(res, { deleted: true });
  }

  return apiResponse.methodNotAllowed(res, req.method!, ['GET', 'POST', 'DELETE']);
}

/** Background statutory document VLM extraction */
async function extractStatutoryDocData(fileData: string, docType: string, docId: string) {
  // fileData is a base64 data URL
  const match = fileData.match(/^data:([^;]+);base64,(.+)$/);
  if (!match) return;
  const mimeType = match[1]!;
  const base64 = match[2]!;

  const docTypeMap: Record<string, string> = {
    cipc_certificate: 'cipc',
    tax_clearance: 'tax_clearance',
    bbbee_certificate: 'bbee',
    vat_registration: 'vat_registration',
  };

  const result = await extractStatutoryDocWithVlm(base64, mimeType, docTypeMap[docType] || undefined);
  if (result) {
    await sql`
      UPDATE company_documents
      SET extracted_data = ${JSON.stringify(result)}::jsonb
      WHERE id = ${docId}::uuid
    `;
    log.info('Statutory doc extraction stored', { docId, docType: result.documentType }, 'company-docs');
  }
}


export default withAuth(withErrorHandler(handler));

export const config = {
  api: { bodyParser: { sizeLimit: '50mb' } },
};

/**
 * Receipt-to-Journal API
 * POST /api/accounting/receipt-to-journal
 * Body: { documentId } or multipart file upload
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';
import {
  validateReceiptExtraction,
  mapMerchantToExpenseAccount,
  buildExpenseJournalFromReceipt,
  shouldAutoPostReceipt,
  parseReceiptType,
} from '@/modules/accounting/services/receiptToJournalService';
import type { ExtractedDocument } from '@/modules/accounting/types/documentCapture.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = Record<string, any>;

async function handler(req: CompanyApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') return apiResponse.methodNotAllowed(res, req.method || '', ['POST']);

  const { companyId } = req;
  const userId: string = req.user?.id || req.user?.userId || '';
  const { documentId } = req.body as { documentId?: string };

  if (!documentId) return apiResponse.badRequest(res, 'documentId is required');

  // Fetch captured document
  const [doc] = (await sql`
    SELECT extracted_data, status FROM captured_documents
    WHERE id = ${documentId}::uuid AND company_id = ${companyId}
  `) as Row[];

  if (!doc) return apiResponse.notFound(res, 'Captured document', documentId);
  if (!doc.extracted_data) return apiResponse.badRequest(res, 'Document has no extracted data');

  const extracted = doc.extracted_data as ExtractedDocument;

  // Validate
  const validation = validateReceiptExtraction(extracted);
  if (!validation.valid) {
    return apiResponse.badRequest(res, `Validation failed: ${validation.errors.join(', ')}`);
  }

  // Get GL accounts
  const glAccounts = (await sql`
    SELECT id, account_code as code, account_name as name
    FROM gl_accounts WHERE company_id = ${companyId}
    ORDER BY account_code
  `) as Row[];

  // Map merchant to expense account
  const accountSuggestion = extracted.vendorName
    ? mapMerchantToExpenseAccount(extracted.vendorName, glAccounts.map(a => ({ id: a.id, code: a.code, name: a.name })))
    : null;

  const expenseAccountId = accountSuggestion?.id || glAccounts.find(a => a.code === '5100')?.id;
  const vatInputAccountId = glAccounts.find(a => a.code === '1140')?.id;
  const bankAccountId = glAccounts.find(a => a.code === '1110')?.id;

  if (!expenseAccountId || !vatInputAccountId || !bankAccountId) {
    return apiResponse.badRequest(res, 'Required GL accounts not found (expense, VAT input, bank)');
  }

  // Build journal entry
  const journalInput = buildExpenseJournalFromReceipt(extracted, { expenseAccountId, vatInputAccountId, bankAccountId });
  const receiptType = parseReceiptType(extracted);
  const autoPost = shouldAutoPostReceipt(extracted.totalAmount || 0, extracted.confidence, { maxAmount: 5000, minConfidence: 0.85 });

  // Get fiscal period
  const [period] = (await sql`
    SELECT id FROM fiscal_periods
    WHERE company_id = ${companyId} AND start_date <= ${journalInput.entryDate}::date AND end_date >= ${journalInput.entryDate}::date
    LIMIT 1
  `) as Row[];

  // Create journal entry
  const [je] = (await sql`
    INSERT INTO gl_journal_entries (
      company_id, entry_date, fiscal_period_id, description, source, status, created_by
    ) VALUES (
      ${companyId}, ${journalInput.entryDate}::date, ${period?.id || null}::uuid,
      ${journalInput.description}, 'auto_invoice',
      ${autoPost ? 'posted' : 'draft'}, ${userId}
    ) RETURNING id, status
  `) as Row[];

  if (!je) return apiResponse.internalError(res, null, 'Failed to create journal entry');

  // Create journal lines
  for (const line of journalInput.lines) {
    await sql`
      INSERT INTO gl_journal_lines (journal_entry_id, gl_account_id, debit, credit, description)
      VALUES (${je.id}::uuid, ${line.accountId}::uuid, ${line.debit}, ${line.credit}, ${line.description})
    `;
  }

  // Link document
  await sql`
    UPDATE captured_documents SET status = 'matched' WHERE id = ${documentId}::uuid
  `;

  log.info('Receipt-to-Journal completed', {
    documentId, journalId: je.id, receiptType, autoPost,
    amount: extracted.totalAmount, merchant: extracted.vendorName,
  }, 'receipt-journal');

  return apiResponse.success(res, {
    journalEntry: { id: je.id, status: je.status },
    receiptType,
    accountSuggestion: accountSuggestion ? { code: accountSuggestion.code, name: accountSuggestion.name } : null,
    autoPosted: autoPost,
    amount: extracted.totalAmount,
    warnings: validation.warnings,
  });
}


export default withCompany(withErrorHandler(handler));

/**
 * POST /api/accounting/company-logo
 * Upload/update company logo as a base64 data URL.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';
type Row = Record<string, unknown>;


async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method!, ['POST']);
  }

  const userId = (req as AuthenticatedNextApiRequest).user.id;
  const { companyId, logoData } = req.body as {
    companyId?: string;
    logoData?: string;
  };

  if (!companyId) return apiResponse.badRequest(res, 'companyId is required');
  if (!logoData) return apiResponse.badRequest(res, 'logoData is required');

  // Validate ownership (owner or admin)
  const membership = (await sql`
    SELECT role FROM company_users
    WHERE company_id = ${companyId}::UUID AND user_id = ${userId}
  `) as Row[];

  if (membership.length === 0) {
    return apiResponse.forbidden(res, 'You do not have access to this company');
  }
  if (!['owner', 'admin'].includes(String(membership[0]!.role))) {
    return apiResponse.forbidden(res, 'Only owners and admins can update the company logo');
  }

  // Validate data URL format
  if (!logoData.startsWith('data:image/')) {
    return apiResponse.badRequest(res, 'logoData must be a valid data:image/ URL');
  }

  // Validate size < 5MB (base64 is ~1.33x raw, so 5MB raw ~ 6.8M chars)
  if (logoData.length > 6_800_000) {
    return apiResponse.badRequest(res, 'Logo must be smaller than 5MB');
  }

  await sql`
    UPDATE companies SET logo_data = ${logoData} WHERE id = ${companyId}::UUID
  `;

  return apiResponse.success(res, { updated: true });
}


export default withAuth(withErrorHandler(handler));

export const config = {
  api: { bodyParser: { sizeLimit: '10mb' } },
};

/**
 * Accounting Settings API
 * GET  ?key=reporting_currency — get setting value
 * PUT  { key, value } — update setting
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type AuthenticatedNextApiRequest, type CompanyApiRequest } from '@/lib/auth';
import { getSetting, setSetting } from '@/modules/accounting/services/currencyService';

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse): Promise<void> {
  const { companyId } = req as CompanyApiRequest;

  if (req.method === 'GET') {
    const { key } = req.query;
    if (!key) return apiResponse.badRequest(res, 'key is required');
    const value = await getSetting(key as string);
    return apiResponse.success(res, { key, value });
  }

  if (req.method === 'PUT') {
    const userId = req.user.id;
    const { key, value } = req.body;
    if (!key || !value) return apiResponse.badRequest(res, 'key and value required');
    await setSetting(key, value, userId);
    return apiResponse.success(res, { updated: true });
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'PUT']);
}


export default withCompany(withErrorHandler(handler));

/**
 * Account External Mappings API — WS-7.3
 * GET  /api/accounting/account-mappings?system=caseware     — list mappings
 * POST /api/accounting/account-mappings                     — save single mapping
 * POST /api/accounting/account-mappings (action=auto-suggest) — bulk auto-suggest
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  getAccountMappings,
  saveAccountMapping,
  autoSuggestAllMappings,
} from '@/modules/accounting/services/casewareExportService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;

  if (req.method === 'GET') {
    const targetSystem = (req.query.system as string) || 'caseware';
    const validSystems = ['caseware', 'xbrl', 'custom'];
    if (!validSystems.includes(targetSystem)) {
      return apiResponse.badRequest(res, `system must be one of: ${validSystems.join(', ')}`);
    }

    try {
      const mappings = await getAccountMappings(companyId, targetSystem);
      return apiResponse.success(res, { items: mappings, total: mappings.length });
    } catch (err) {
      log.error('Failed to get account mappings', { error: err, companyId }, 'account-mappings-api');
      return apiResponse.badRequest(res, 'Failed to retrieve account mappings');
    }
  }

  if (req.method === 'POST') {
    const { action, glAccountId, targetSystem, externalCode, externalLabel } = req.body as {
      action?: string;
      glAccountId?: string;
      targetSystem?: string;
      externalCode?: string;
      externalLabel?: string;
    };

    if (action === 'auto-suggest') {
      try {
        const suggestions = await autoSuggestAllMappings(companyId);
        const system = targetSystem ?? 'caseware';

        await Promise.all(
          suggestions.map(s =>
            saveAccountMapping(companyId, s.glAccountId, system, s.code, s.label),
          ),
        );

        log.info('Auto-suggested mappings applied', { companyId, count: suggestions.length }, 'account-mappings-api');
        return apiResponse.success(res, { applied: suggestions.length });
      } catch (err) {
        log.error('Auto-suggest failed', { error: err, companyId }, 'account-mappings-api');
        return apiResponse.badRequest(res, 'Auto-suggest failed');
      }
    }

    if (!glAccountId || !targetSystem || !externalCode) {
      return apiResponse.badRequest(res, 'glAccountId, targetSystem and externalCode are required');
    }

    const validSystems = ['caseware', 'xbrl', 'custom'];
    if (!validSystems.includes(targetSystem)) {
      return apiResponse.badRequest(res, `targetSystem must be one of: ${validSystems.join(', ')}`);
    }

    try {
      await saveAccountMapping(companyId, glAccountId, targetSystem, externalCode, externalLabel);
      log.info('Account mapping saved', { companyId, glAccountId, targetSystem }, 'account-mappings-api');
      return apiResponse.success(res, { saved: true });
    } catch (err) {
      log.error('Failed to save account mapping', { error: err }, 'account-mappings-api');
      return apiResponse.badRequest(res, 'Failed to save account mapping');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method ?? 'UNKNOWN', ['GET', 'POST']);
}


