/**
 * /onboarding — 7-step company setup wizard with Smart Setup pre-step.
 * Standalone layout (no AppLayout), matches login dark theme.
 */

import { useState, useEffect, useCallback } from 'react';
import { useRouter } from 'next/router';
import {
  Check, Building2, MapPin, Image, Landmark,
  Settings, FileText, ChevronLeft, ChevronRight, Loader2,
} from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';
import {
  type WizardData, INITIAL_WIZARD, MONTHS, DOC_SLOTS,
  Step1, Step2, Step3, Step4, Step5, Step6, Step7,
} from '@/components/onboarding/WizardSteps';
import { SmartSetupChoice } from '@/components/onboarding/SmartSetupChoice';

const STEPS = [
  { icon: Building2, title: 'Company Details',       sub: 'Tell us about your business' },
  { icon: MapPin,    title: 'Address & Contact',      sub: 'Where can we reach you?' },
  { icon: Image,     title: 'Logo Upload',            sub: 'Brand your workspace' },
  { icon: Landmark,  title: 'Banking Details',        sub: 'Your primary bank account' },
  { icon: Settings,  title: 'Financial Preferences',  sub: 'Year-end, VAT & currency' },
  { icon: FileText,  title: 'Statutory Documents',    sub: 'Upload key certificates' },
  { icon: Check,     title: 'Review & Complete',      sub: 'Confirm and get started' },
];

export default function OnboardingWizard() {
  const router = useRouter();

  // step === -1 is the Smart Setup pre-step (choice screen)
  const [step, setStep]             = useState(-1);
  const [d, setD]                   = useState<WizardData>(INITIAL_WIZARD);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError]           = useState('');
  const [authChecked, setAuthChecked] = useState(false);

  // Auth check — then verify user doesn't already have companies (e.g. via invitation)
  useEffect(() => {
    apiFetch('/api/auth/me').then(async (r) => {
      if (!r.ok) { void router.replace('/login'); return; }
      const body = await r.json();
      if (body.data?.onboardingCompleted) { void router.replace('/accounting'); return; }

      // Invited users already have a company — skip onboarding for them
      try {
        const compRes = await apiFetch('/api/accounting/companies?action=user-companies');
        if (compRes.ok) {
          const compBody = await compRes.json();
          const companies: unknown[] = compBody.data ?? [];
          if (companies.length > 0) {
            await apiFetch('/api/onboarding/complete', { method: 'POST' });
            void router.replace('/accounting');
            return;
          }
        }
      } catch {
        // Non-fatal — fall through to show the wizard
      }

      setAuthChecked(true);
    }).catch(() => void router.replace('/login'));
  }, [router]);

  const set = useCallback(<K extends keyof WizardData>(k: K, v: WizardData[K]) => {
    setD(prev => ({ ...prev, [k]: v }));
  }, []);

  // Smart Setup: merge extracted fields and jump to step 0
  const handleExtracted = useCallback((extracted: Partial<WizardData>) => {
    setD(prev => ({ ...prev, ...extracted }));
    setStep(0);
  }, []);

  const hasCipc     = d.documents.some(doc => doc.type === 'cipc_certificate');
  const canContinue = step === 0 ? d.name.trim().length > 0
                    : step === 5 ? hasCipc   // CIPC is required on documents step
                    : true;
  const isLast      = step === STEPS.length - 1;
  const skippable   = step >= 1 && step <= 4; // steps 1-4 skippable, step 5 (documents) not
  const isPreStep   = step === -1;

  const next = () => { if (canContinue) setStep(s => Math.min(s + 1, STEPS.length - 1)); };
  const back = () => setStep(s => Math.max(s - 1, 0));

  const handleSubmit = async () => {
    setSubmitting(true);
    setError('');
    try {
      // 1. Create company
      const compRes = await apiFetch('/api/accounting/companies', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: d.name, tradingName: d.tradingName,
          registrationNumber: d.registrationNumber, vatNumber: d.vatNumber,
          taxNumber: d.taxNumber, addressLine1: d.addressLine1,
          addressLine2: d.addressLine2, city: d.city, province: d.province,
          postalCode: d.postalCode, country: d.country, phone: d.phone,
          email: d.email, website: d.website, logoData: d.logoData || undefined,
          bankName: d.bankName || undefined,
          bankAccountNumber: d.bankAccountNumber || undefined,
          bankBranchCode: d.bankBranchCode || undefined,
          bankAccountType: d.bankAccountType,
          financialYearStart: d.financialYearStart,
          vatPeriod: d.vatPeriod, defaultCurrency: d.defaultCurrency,
        }),
      });
      if (!compRes.ok) {
        const body = await compRes.json();
        throw new Error(body.error?.message || 'Failed to create company');
      }
      const compData = await compRes.json();
      const companyId = compData.data?.id;

      // 2. Save directors (non-blocking)
      if (d.directors.length > 0 && companyId) {
        try {
          await apiFetch('/api/accounting/company-directors', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'X-Company-Id': companyId },
            body: JSON.stringify({ directors: d.directors }),
          });
        } catch { /* non-critical */ }
      }

      // 3. Upload documents (non-blocking — company is already created)
      if (d.documents.length > 0 && companyId) {
        try {
          await apiFetch('/api/onboarding/documents', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ companyId, documents: d.documents }),
          });
        } catch { /* non-critical */ }
      }

      // 4. Mark onboarding complete
      await apiFetch('/api/onboarding/complete', { method: 'POST' });

      // 4. Navigate — full reload so the middleware picks up the new ff_onboarding_done cookie
      window.location.href = '/accounting';
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Something went wrong');
      setSubmitting(false);
    }
  };

  if (!authChecked) {
    return (
      <div className="min-h-screen bg-gray-950 flex items-center justify-center">
        <Loader2 className="w-8 h-8 text-teal-500 animate-spin" />
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-950 text-white px-4 py-8">
      {/* Logo */}
      <div className="max-w-2xl mx-auto mb-8">
        <img src="/logo.png" alt="ISAFlow" className="h-10 w-auto brightness-0 invert" />
      </div>

      {/* Progress — only shown during the 7-step wizard (step 0-6) */}
      {!isPreStep && (
        <div className="max-w-2xl mx-auto mb-8">
          <div className="flex items-center justify-between">
            {STEPS.map((s, i) => (
              <div key={i} className="flex items-center flex-1 last:flex-none">
                <button
                  onClick={() => i < step && setStep(i)}
                  disabled={i > step}
                  className={`w-9 h-9 rounded-full flex items-center justify-center text-sm font-medium shrink-0 transition-colors ${
                    i < step  ? 'bg-teal-600 text-white cursor-pointer' :
                    i === step ? 'bg-teal-500 text-white ring-2 ring-teal-400' :
                    'bg-gray-800 text-gray-500'
                  }`}
                >
                  {i < step ? <Check className="w-4 h-4" /> : i + 1}
                </button>
                {i < STEPS.length - 1 && (
                  <div className={`h-0.5 flex-1 mx-1 ${i < step ? 'bg-teal-600' : 'bg-gray-800'}`} />
                )}
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Pre-step: Smart Setup choice */}
      {isPreStep && (
        <SmartSetupChoice
          onManual={() => setStep(0)}
          onExtracted={handleExtracted}
        />
      )}

      {/* Wizard card */}
      {!isPreStep && (
        <div className="max-w-2xl mx-auto">
          <div className="mb-4">
            <h2 className="text-xl font-semibold">{STEPS[step]?.title}</h2>
            <p className="text-sm text-gray-400">{STEPS[step]?.sub}</p>
          </div>

          <div className="bg-gray-900 border border-gray-700 rounded-2xl p-6 shadow-xl min-h-[320px]">
            {step === 0 && <Step1 d={d} set={set} />}
            {step === 1 && <Step2 d={d} set={set} />}
            {step === 2 && <Step3 d={d} set={set} />}
            {step === 3 && <Step4 d={d} set={set} />}
            {step === 4 && <Step5 d={d} set={set} />}
            {step === 5 && <Step6 d={d} set={set} />}
            {step === 6 && <Step7 d={d} />}
          </div>

          {/* Error */}
          {error && (
            <div className="mt-4 px-3 py-2.5 bg-red-500/10 border border-red-500/30 rounded-lg">
              <p className="text-sm text-red-400">{error}</p>
            </div>
          )}

          {/* Navigation */}
          <div className="flex justify-between mt-6">
            <button
              onClick={step === 0 ? () => setStep(-1) : back}
              className="flex items-center gap-1.5 text-sm text-gray-400 hover:text-white transition-colors"
            >
              <ChevronLeft className="w-4 h-4" /> Back
            </button>
            <div className="flex gap-3">
              {skippable && !isLast && (
                <button onClick={next} className="text-sm text-gray-400 hover:text-white transition-colors">
                  Skip
                </button>
              )}
              {isLast ? (
                <button
                  onClick={() => void handleSubmit()}
                  disabled={submitting}
                  className="flex items-center gap-2 bg-teal-600 hover:bg-teal-500 disabled:bg-teal-800 text-white font-medium text-sm px-6 py-2.5 rounded-lg transition-colors"
                >
                  {submitting ? <><Loader2 className="w-4 h-4 animate-spin" /> Saving...</> : 'Complete Setup'}
                </button>
              ) : (
                <button
                  onClick={next}
                  disabled={!canContinue}
                  className="flex items-center gap-1.5 bg-teal-600 hover:bg-teal-500 disabled:bg-teal-800 disabled:cursor-not-allowed text-white font-medium text-sm px-5 py-2.5 rounded-lg transition-colors"
                >
                  Continue <ChevronRight className="w-4 h-4" />
                </button>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

/**
 * Bank Transaction Attachments API
 *
 * GET  /api/accounting/bank-tx-attachments?bankTransactionId=<uuid>
 *   → List all attachments for a bank transaction, newest first.
 *
 * POST /api/accounting/bank-tx-attachments
 *   Body: { bankTransactionId, fileName, fileData (base64 data URL), fileSize? }
 *   → Store an attachment. Small receipts (≤ 2 MB) are kept as data URLs in file_url.
 *
 * DELETE /api/accounting/bank-tx-attachments?id=<uuid>
 *   → Remove a single attachment record.
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';
import { extractFromPdf, extractFromImage } from '@/modules/accounting/services/ocrService';
import { isVlmAvailable } from '@/modules/accounting/services/vlmService';

// ── Local Types ───────────────────────────────────────────────────────────────

// Neon's sql tagged template returns a union type. Casting through unknown[]
// is the project-standard pattern (see bankReconciliationService.ts Row = any).
// eslint-disable-next-line @typescript-eslint/no-explicit-any
type SqlRow = Record<string, any>;

interface PostBody {
  bankTransactionId?: string;
  fileName?: string;
  fileData?: string; // base64 data URL: "data:<mime>;base64,<data>"
  fileSize?: number;
}

// ── Constants ─────────────────────────────────────────────────────────────────

/** 2 MB limit — data URLs expand ~33 % in transit, so clamp at 2 MB of raw bytes */
const MAX_FILE_SIZE_BYTES = 2 * 1024 * 1024;

/** Allowed MIME types derived from the data URL header */
const ALLOWED_MIME_TYPES = ['image/jpeg', 'image/png', 'application/pdf'];

/** Magic-byte signatures for server-side MIME validation (attacker cannot spoof these) */
const ALLOWED_ATTACHMENT_MIMES = ['image/jpeg', 'image/png', 'image/gif', 'application/pdf'];

// ── Helpers ───────────────────────────────────────────────────────────────────

/** Extract the MIME type from a base64 data URL string */
function extractMime(dataUrl: string): string | null {
  const match = dataUrl.match(/^data:([a-zA-Z0-9]+\/[a-zA-Z0-9.+-]+);base64,/);
  return match ? match[1] ?? null : null;
}

/** Rough byte size estimate for a base64-encoded data URL */
function estimateDataUrlBytes(dataUrl: string): number {
  const base64Part = dataUrl.split(',')[1] ?? '';
  return Math.ceil((base64Part.length * 3) / 4);
}

// ── Handler ───────────────────────────────────────────────────────────────────

async function handler(req: CompanyApiRequest, res: NextApiResponse) {
  const { companyId } = req;
  const userId: string | null = req.user?.id ?? req.user?.userId ?? null;

  // ── GET ────────────────────────────────────────────────────────────────────
  if (req.method === 'GET') {
    const { bankTransactionId } = req.query;

    if (!bankTransactionId || typeof bankTransactionId !== 'string') {
      return apiResponse.badRequest(res, 'bankTransactionId query param is required');
    }

    // Verify the bank transaction belongs to this company
    const [btOwner] = await sql`
      SELECT id FROM bank_transactions WHERE id = ${bankTransactionId}::UUID AND company_id = ${companyId}
    ` as SqlRow[];
    if (!btOwner) return apiResponse.forbidden(res, 'Bank transaction does not belong to your company');

    const rows = (await sql`
      SELECT
        bta.id,
        bta.bank_transaction_id,
        bta.file_url,
        bta.file_name,
        bta.file_size,
        bta.uploaded_by,
        bta.created_at
      FROM bank_transaction_attachments bta
      JOIN bank_transactions bt ON bt.id = bta.bank_transaction_id
      WHERE bta.bank_transaction_id = ${bankTransactionId}::UUID
        AND bt.company_id = ${companyId}
      ORDER BY bta.created_at DESC
    `) as SqlRow[];

    log.info('Listed bank tx attachments', { bankTransactionId, count: rows.length }, 'bank-tx-attachments');
    return apiResponse.success(res, rows);
  }

  // ── POST ───────────────────────────────────────────────────────────────────
  if (req.method === 'POST') {
    const { bankTransactionId, fileName, fileData, fileSize } = req.body as PostBody;

    if (!bankTransactionId) return apiResponse.badRequest(res, 'bankTransactionId is required');

    // Verify ownership before insert
    const [btCheck] = await sql`
      SELECT id FROM bank_transactions WHERE id = ${bankTransactionId}::UUID AND company_id = ${companyId}
    ` as SqlRow[];
    if (!btCheck) return apiResponse.forbidden(res, 'Bank transaction does not belong to your company');

    if (!fileName) return apiResponse.badRequest(res, 'fileName is required');
    if (!fileData || typeof fileData !== 'string') {
      return apiResponse.badRequest(res, 'fileData (base64 data URL) is required');
    }

    // Validate MIME type against data URL header
    const mime = extractMime(fileData);
    if (!mime || !ALLOWED_MIME_TYPES.includes(mime)) {
      return apiResponse.badRequest(res, `File type not allowed. Accepted: ${ALLOWED_MIME_TYPES.join(', ')}`);
    }
    // Secondary allowlist check — attacker-controlled data URL cannot bypass this
    if (!ALLOWED_ATTACHMENT_MIMES.includes(mime)) {
      return apiResponse.badRequest(res, `File type ${mime} not allowed`);
    }

    // Validate file size
    // Always compute from actual data — never trust client-supplied fileSize
    const byteSize = estimateDataUrlBytes(fileData);
    if (byteSize > MAX_FILE_SIZE_BYTES) {
      return apiResponse.badRequest(res, 'File exceeds the 2 MB size limit');
    }

    const insertRows = (await sql`
      INSERT INTO bank_transaction_attachments
        (bank_transaction_id, file_url, file_name, file_size, uploaded_by)
      VALUES
        (
          ${bankTransactionId}::UUID,
          ${fileData},
          ${fileName},
          ${byteSize},
          ${userId}::UUID
        )
      RETURNING
        id, bank_transaction_id, file_url, file_name, file_size, uploaded_by, created_at
    `) as SqlRow[];

    const attachment = insertRows[0];
    log.info('Uploaded bank tx attachment', { bankTransactionId, fileName, byteSize }, 'bank-tx-attachments');

    // Fire-and-forget VLM extraction on the attachment
    if (isVlmAvailable() && mime && attachment?.id) {
      extractAttachmentData(fileData, mime, attachment.id as string).catch(err =>
        log.warn('Background attachment extraction failed', { error: err instanceof Error ? err.message : String(err) }, 'bank-tx-attachments')
      );
    }

    return apiResponse.created(res, attachment, 'Attachment uploaded');
  }

  // ── DELETE ─────────────────────────────────────────────────────────────────
  if (req.method === 'DELETE') {
    const { id } = req.query;

    if (!id || typeof id !== 'string') {
      return apiResponse.badRequest(res, 'id query param is required');
    }

    // Verify ownership via bank_transactions before delete
    const deleteRows = (await sql`
      DELETE FROM bank_transaction_attachments bta
      USING bank_transactions bt
      WHERE bta.id = ${id}::UUID
        AND bta.bank_transaction_id = bt.id
        AND bt.company_id = ${companyId}
      RETURNING bta.id
    `) as SqlRow[];

    if (!deleteRows || deleteRows.length === 0) {
      return apiResponse.notFound(res, 'Attachment', id);
    }

    log.info('Deleted bank tx attachment', { id }, 'bank-tx-attachments');
    return apiResponse.success(res, { deleted: id });
  }

  return apiResponse.methodNotAllowed(res, req.method ?? 'UNKNOWN', ['GET', 'POST', 'DELETE']);
}

/** Background VLM extraction for bank tx attachments */
async function extractAttachmentData(dataUrl: string, mime: string, attachmentId: string) {
  const base64Part = dataUrl.split(',')[1];
  if (!base64Part) return;

  const buffer = Buffer.from(base64Part, 'base64');
  const isPdf = mime === 'application/pdf';

  const extracted = isPdf
    ? await extractFromPdf(buffer)
    : await extractFromImage(buffer, mime);

  if (extracted && extracted.confidence > 0) {
    await sql`
      UPDATE bank_transaction_attachments
      SET extracted_data = ${JSON.stringify(extracted)}::jsonb
      WHERE id = ${attachmentId}::uuid
    `;
    log.info('VLM extraction stored for bank tx attachment', { attachmentId, confidence: extracted.confidence }, 'bank-tx-attachments');
  }
}


